// This is an operator-controlled diagnostic only. It deliberately logs before
// destination filtering so a failed cross-window drag can distinguish "AppKit
// never dispatched to this view" from a type/hit/identity rejection without
// changing any drag, FIFO or owner behavior.
static BOOL CjguiDataTransferTraceEnabled(void) {
    static int enabled = -1;
    if (enabled < 0) {
        const char *value = getenv("CJGUI_DATA_TRANSFER_TRACE");
        enabled = value && strcmp(value, "1") == 0 ? 1 : 0;
    }
    return enabled != 0;
}

// The caretaker clock is required by the normal renderer. Keep it separate
// from the TESTING-only interval probes below, whose production call sites
// deliberately compile to zero to avoid reads in hot drawing paths.
static uint64_t CjguiCaretBlinkClockMicros(void) {
    static mach_timebase_info_data_t timebase;
    static dispatch_once_t once;
    dispatch_once(&once, ^{ mach_timebase_info(&timebase); });
    uint64_t ticks = mach_continuous_time();
    // Convert before dividing to microseconds. Dividing ticks by 1000 first
    // quantized the clock in timebase.numer/denom-sized steps (41 us here),
    // hiding the actual bracket width of cross-clock test observations.
    return (uint64_t)(((__uint128_t)ticks * timebase.numer) /
                      ((__uint128_t)MAX((uint32_t)1, timebase.denom) * 1000u));
}

// Opt-in owner pacing observations share Python/macOS's mach_absolute_time
// origin. They measure only the actual idle wait, never main-queue dispatch
// or event delivery. Keep those costs in the caller's full turn interval.
static uint64_t CjguiOwnerTraceNanoseconds(void) {
    mach_timebase_info_data_t timebase;
    mach_timebase_info(&timebase);
    return (uint64_t)(((__uint128_t)mach_absolute_time() * timebase.numer) /
                      MAX((uint32_t)1, timebase.denom));
}
static BOOL CjguiOwnerPhaseTraceEnabled(void) {
