static BOOL CjguiOwnerTraceIsRetentionCritical(uint32_t kind, uint32_t phase) {
    if (phase >= 320 && phase <= 356) return YES;
    if (kind == CJGUI_OWNER_TRACE_OBSERVATION_SCALAR && phase >= CJGUI_OWNER_PHASE_SELECTION_INSTALLED &&
        phase <= CJGUI_OWNER_PHASE_SELECTION_DRAW_OWNER_TURN) return YES;
    switch (phase) {
        case CJGUI_OWNER_PHASE_ACCEPTED_FOCUS_SELECTION:
        case CJGUI_OWNER_PHASE_NATIVE_INPUT_PUBLICATION:
        case CJGUI_OWNER_PHASE_NATIVE_RESTORE_SELECTION:
        case CJGUI_OWNER_PHASE_NATIVE_READ_SELECTION:
        case CJGUI_OWNER_PHASE_NATIVE_RECOVER_TEXT_PROXY:
        case CJGUI_OWNER_PHASE_NATIVE_FORM_EVENT_TEXT:
        case CJGUI_OWNER_PHASE_PROJECTION_INPUT_ADMISSION:
            return YES;
        default:
            return NO;
    }
}

static BOOL CjguiOwnerTraceIsFixedPreparationSummary(uint32_t kind, uint32_t phase) {
    return kind == CJGUI_OWNER_TRACE_OBSERVATION_SCALAR && phase >=
        CJGUI_OWNER_PHASE_PREPARATION_DECLARATIONS_COPIED && phase <=
        CJGUI_OWNER_PHASE_PREPARATION_GEOMETRY_WRITTEN;
}

static BOOL CjguiOwnerTraceIsFixedWaitSummary(uint32_t kind, uint32_t phase) {
    return kind == CJGUI_OWNER_TRACE_OBSERVATION_SCALAR && phase >=
        CJGUI_OWNER_PHASE_OWNER_WAIT_ABSOLUTE_DEADLINE && phase <=
        CJGUI_OWNER_PHASE_OWNER_WAIT_NOTIFY_READY_REVISION;
}

static BOOL CjguiOwnerTraceCopyToRetention(CjguiOwnerTraceRecord *source, uint64_t sourceSequence,
    CjguiOwnerTraceRecord *records, uint32_t capacity, _Atomic(uint64_t) *next,
    BOOL fixedPrefix, _Atomic(uint64_t) *dropped, _Atomic(uint64_t) *overwritten) {
    bool expected = false;
    if (!atomic_compare_exchange_strong_explicit(&source->writing, &expected, true,
            memory_order_acquire, memory_order_relaxed)) {
        atomic_fetch_add_explicit(dropped, 1, memory_order_relaxed);
        return NO;
    }
    if (atomic_load_explicit(&source->publishedSequence, memory_order_acquire) != sourceSequence) {
        atomic_store_explicit(&source->writing, false, memory_order_release);
        atomic_fetch_add_explicit(dropped, 1, memory_order_relaxed);
        return NO;
    }
    uint64_t ordinal = atomic_fetch_add_explicit(next, 1, memory_order_relaxed);
    if (fixedPrefix && ordinal >= capacity) {
        atomic_store_explicit(&source->writing, false, memory_order_release);
        atomic_fetch_add_explicit(dropped, 1, memory_order_relaxed);
        return NO;
    }
    if (!fixedPrefix && ordinal >= capacity && overwritten)
        atomic_fetch_add_explicit(overwritten, 1, memory_order_relaxed);
    CjguiOwnerTraceRecord *destination = &records[ordinal % capacity];
    expected = false;
    if (!atomic_compare_exchange_strong_explicit(&destination->writing, &expected, true,
            memory_order_acquire, memory_order_relaxed)) {
        atomic_store_explicit(&source->writing, false, memory_order_release);
        atomic_fetch_add_explicit(dropped, 1, memory_order_relaxed);
        return NO;
    }
    destination->sequence = source->sequence;
    destination->monoNs = source->monoNs;
    destination->cpuNs = source->cpuNs;
    destination->session = source->session;
    destination->turn = source->turn;
    destination->request = source->request;
    destination->dispatch = source->dispatch;
    destination->generation = source->generation;
    destination->span = source->span;
    destination->threadId = source->threadId;
    destination->managedThreadId = source->managedThreadId;
    destination->ownerConsumeTurn = source->ownerConsumeTurn;
    destination->ownerConsumeGeneration = source->ownerConsumeGeneration;
    destination->ownerConsumeThreadId = source->ownerConsumeThreadId;
    destination->kind = source->kind;
    destination->phase = source->phase;
    destination->cpuValid = source->cpuValid;
    atomic_store_explicit(&destination->publishedSequence, ordinal + 1, memory_order_release);
    atomic_store_explicit(&destination->writing, false, memory_order_release);
    atomic_store_explicit(&source->writing, false, memory_order_release);
    return YES;
}

static void CjguiOwnerTraceCaptureActivityTurn(uint64_t session, uint64_t turn, uint64_t endSequence) {
    if (!atomic_load_explicit(&gCjguiOwnerTraceActiveHasCriticalObservation, memory_order_acquire) ||
        session != atomic_load_explicit(&gCjguiOwnerTraceActiveSession, memory_order_relaxed) ||
        turn != atomic_load_explicit(&gCjguiOwnerTraceActiveTurn, memory_order_relaxed)) return;
    uint64_t startedNs = CjguiOwnerTraceNanoseconds();
    uint64_t firstSequence = atomic_load_explicit(&gCjguiOwnerTraceActiveStartSequence, memory_order_relaxed);
    uint64_t earliest = endSequence > CJGUI_OWNER_TRACE_CAPACITY ?
        endSequence - CJGUI_OWNER_TRACE_CAPACITY + 1 : 1;
    if (firstSequence < earliest) {
        atomic_fetch_add_explicit(&gCjguiOwnerTraceActivitySourceMissing, earliest - firstSequence,
            memory_order_relaxed);
        firstSequence = earliest;
    }
    for (uint64_t sourceSequence = firstSequence; sourceSequence <= endSequence; sourceSequence++) {
        CjguiOwnerTraceRecord *source = &gCjguiOwnerTraceRecords[
            (sourceSequence - 1) % CJGUI_OWNER_TRACE_CAPACITY];
        bool expected = false;
        if (!atomic_compare_exchange_strong_explicit(&source->writing, &expected, true,
                memory_order_acquire, memory_order_relaxed)) {
            atomic_fetch_add_explicit(&gCjguiOwnerTraceActivitySourceMissing, 1, memory_order_relaxed);
            continue;
        }
        // This is a retained interval, not a session projection. One real
        // owner turn may pump sibling native windows, and its measured idle
        // endpoints belong to those sessions. Keep the original records and
        // actor identities; consumers attribute physical overlap and credit
        // idle only on the actual owner OS thread. Filtering by the outer
        // session loses those endpoints after the source ring wraps.
        BOOL belongs = atomic_load_explicit(&source->publishedSequence, memory_order_acquire) == sourceSequence;
        atomic_store_explicit(&source->writing, false, memory_order_release);
        if (!belongs) continue;
        uint64_t ordinal = atomic_load_explicit(&gCjguiOwnerTraceActivityNext, memory_order_relaxed);
        if (CjguiOwnerTraceCopyToRetention(source, sourceSequence, gCjguiOwnerTraceActivityRecords,
                CJGUI_OWNER_TRACE_ACTIVITY_CAPACITY, &gCjguiOwnerTraceActivityNext, NO,
                &gCjguiOwnerTraceActivityDropped, &gCjguiOwnerTraceActivityOverwritten)) {
            uint64_t retainedFirst = sourceSequence;
            if (ordinal >= CJGUI_OWNER_TRACE_ACTIVITY_CAPACITY)
                retainedFirst = gCjguiOwnerTraceActivityRecords[(ordinal + 1) %
                    CJGUI_OWNER_TRACE_ACTIVITY_CAPACITY].sequence;
            uint64_t unset = 0;
            if (ordinal < CJGUI_OWNER_TRACE_ACTIVITY_CAPACITY)
                atomic_compare_exchange_strong_explicit(&gCjguiOwnerTraceActivityFirstSequence, &unset,
                    retainedFirst, memory_order_relaxed, memory_order_relaxed);
            else
                atomic_store_explicit(&gCjguiOwnerTraceActivityFirstSequence, retainedFirst, memory_order_relaxed);
            atomic_store_explicit(&gCjguiOwnerTraceActivityLastSequence, sourceSequence, memory_order_relaxed);
        }
    }
    atomic_fetch_add_explicit(&gCjguiOwnerTraceActivityCaptureCount, 1, memory_order_relaxed);
    uint64_t finishedNs = CjguiOwnerTraceNanoseconds();
    if (finishedNs >= startedNs)
        atomic_fetch_add_explicit(&gCjguiOwnerTraceActivityCopyNs, finishedNs - startedNs,
            memory_order_relaxed);
    atomic_store_explicit(&gCjguiOwnerTraceActiveHasCriticalObservation, false, memory_order_release);
}

static void CjguiOwnerTraceExitExport(void) {
    (void)cjgui_internal_renderer_finalize_owner_trace();
}

static void CjguiOwnerTraceEnsureExitExport(void) {
    if (atomic_load_explicit(&gCjguiOwnerTraceExitHandlerRegistrationAttempted,
            memory_order_relaxed)) return;
    if (!CjguiOwnerPhaseTraceEnabled()) return;
    atomic_store_explicit(&gCjguiOwnerTraceEnabledObserved, true, memory_order_release);
    bool expected = false;
    if (atomic_compare_exchange_strong_explicit(&gCjguiOwnerTraceExitHandlerRegistrationAttempted,
            &expected, true, memory_order_acq_rel, memory_order_relaxed)) {
        if (atexit(CjguiOwnerTraceExitExport) == 0)
            atomic_store_explicit(&gCjguiOwnerTraceExitHandlerRegistered, true, memory_order_release);
    }
}

static BOOL CjguiOwnerTraceCopyToSlow(uint64_t sequence) {
    CjguiOwnerTraceRecord *source = &gCjguiOwnerTraceRecords[(sequence - 1) % CJGUI_OWNER_TRACE_CAPACITY];
    bool sourceExpected = false;
    if (!atomic_compare_exchange_strong_explicit(&source->writing, &sourceExpected, true,
            memory_order_acquire, memory_order_relaxed)) return NO;
    if (atomic_load_explicit(&source->publishedSequence, memory_order_acquire) != sequence) {
        atomic_store_explicit(&source->writing, false, memory_order_release);
        return NO;
    }
    CjguiOwnerTraceRecord *destination = &gCjguiOwnerTraceSlowRecords[
        (sequence - 1) % CJGUI_OWNER_TRACE_SLOW_CAPACITY];
    bool destinationExpected = false;
    if (!atomic_compare_exchange_strong_explicit(&destination->writing, &destinationExpected, true,
            memory_order_acquire, memory_order_relaxed)) {
        atomic_store_explicit(&source->writing, false, memory_order_release);
        return NO;
    }
    destination->sequence = source->sequence;
    destination->monoNs = source->monoNs;
    destination->cpuNs = source->cpuNs;
    destination->session = source->session;
    destination->turn = source->turn;
    destination->request = source->request;
    destination->dispatch = source->dispatch;
    destination->generation = source->generation;
    destination->span = source->span;
    destination->threadId = source->threadId;
    destination->managedThreadId = source->managedThreadId;
    destination->ownerConsumeTurn = source->ownerConsumeTurn;
    destination->ownerConsumeGeneration = source->ownerConsumeGeneration;
    destination->ownerConsumeThreadId = source->ownerConsumeThreadId;
    destination->kind = source->kind;
    destination->phase = source->phase;
    destination->cpuValid = source->cpuValid;
    atomic_store_explicit(&destination->publishedSequence, sequence, memory_order_release);
    atomic_store_explicit(&destination->writing, false, memory_order_release);
    atomic_store_explicit(&source->writing, false, memory_order_release);
    return YES;
}

static void CjguiOwnerTraceCaptureSlowWindow(uint64_t sequence, uint64_t turn) {
    uint64_t first = sequence > 2048 ? sequence - 2048 : 1;
    atomic_store_explicit(&gCjguiOwnerTraceSlowFirstSequence, first, memory_order_relaxed);
    atomic_store_explicit(&gCjguiOwnerTraceSlowLastSequence, sequence, memory_order_relaxed);
    atomic_store_explicit(&gCjguiOwnerTraceSlowDropped, 0, memory_order_relaxed);
    atomic_store_explicit(&gCjguiOwnerTraceSlowTurn, turn, memory_order_release);
    atomic_store_explicit(&gCjguiOwnerTraceSlowPostRemaining, 4096, memory_order_release);
    for (uint64_t item = first; item <= sequence; item++) {
        if (!CjguiOwnerTraceCopyToSlow(item)) {
            atomic_fetch_add_explicit(&gCjguiOwnerTraceSlowDropped, 1, memory_order_relaxed);
        }
    }
}

static BOOL CjguiOwnerTraceSlowSampleHasSequence(uint64_t sequence) {
    CjguiOwnerTraceStackSample *slot = &gCjguiOwnerTraceSlowStackSamples[
        (sequence - 1) % CJGUI_OWNER_TRACE_SAMPLE_CAPACITY];
    return atomic_load_explicit(&slot->publishedSequence, memory_order_acquire) == sequence;
}

static BOOL CjguiOwnerTraceRefreshTurnEndTimestamp(uint64_t sequence, uint64_t captureStartedNs) {
    CjguiOwnerTraceRecord *source = &gCjguiOwnerTraceRecords[(sequence - 1) % CJGUI_OWNER_TRACE_CAPACITY];
    bool expected = false;
    if (!atomic_compare_exchange_strong_explicit(&source->writing, &expected, true,
            memory_order_acquire, memory_order_relaxed)) return NO;
    if (atomic_load_explicit(&source->publishedSequence, memory_order_acquire) != sequence) {
        atomic_store_explicit(&source->writing, false, memory_order_release);
        return NO;
    }
    BOOL cpuValid = NO;
    uint64_t threadId = 0;
    uint64_t cpuNs = CjguiOwnerTraceThreadCpu(&threadId, &cpuValid);
    uint64_t monoNs = CjguiOwnerTraceNanoseconds();
    source->monoNs = monoNs;
    source->cpuNs = cpuNs;
    source->threadId = threadId;
    source->cpuValid = cpuValid;
    atomic_store_explicit(&source->writing, false, memory_order_release);

    CjguiOwnerTraceRecord *slow = &gCjguiOwnerTraceSlowRecords[
        (sequence - 1) % CJGUI_OWNER_TRACE_SLOW_CAPACITY];
    expected = false;
    if (!atomic_compare_exchange_strong_explicit(&slow->writing, &expected, true,
            memory_order_acquire, memory_order_relaxed)) return NO;
    if (atomic_load_explicit(&slow->publishedSequence, memory_order_acquire) == sequence) {
        slow->monoNs = monoNs;
        slow->cpuNs = cpuNs;
        slow->threadId = threadId;
        slow->cpuValid = cpuValid;
    }
    atomic_store_explicit(&slow->writing, false, memory_order_release);
    if (captureStartedNs != 0 && monoNs >= captureStartedNs) {
        atomic_store_explicit(&gCjguiOwnerTraceSlowCaptureStartedNs, captureStartedNs, memory_order_relaxed);
        atomic_store_explicit(&gCjguiOwnerTraceSlowCaptureFinishedNs, monoNs, memory_order_relaxed);
        atomic_store_explicit(&gCjguiOwnerTraceSlowCaptureCostNs, monoNs - captureStartedNs, memory_order_relaxed);
    }
    return YES;
}

