static uint64_t CjguiOwnerTraceThreadCpu(uint64_t *outThreadId, BOOL *outValid) {
    uint64_t threadId = 0;
    bool idValid = pthread_threadid_np(NULL, &threadId) == 0 && threadId != 0;
    if (outThreadId) *outThreadId = idValid ? threadId : UINT64_MAX;
    if (outValid) *outValid = NO;
    thread_basic_info_data_t info = {0};
    mach_msg_type_number_t count = THREAD_BASIC_INFO_COUNT;
    thread_t thread = mach_thread_self();
    kern_return_t result = thread_info(thread, THREAD_BASIC_INFO, (thread_info_t)&info, &count);
    mach_port_deallocate(mach_task_self(), thread);
    if (!idValid || result != KERN_SUCCESS) return 0;
    if (outValid) *outValid = YES;
    return ((uint64_t)info.user_time.seconds + (uint64_t)info.system_time.seconds) * 1000000000ULL +
        ((uint64_t)info.user_time.microseconds + (uint64_t)info.system_time.microseconds) * 1000ULL;
}

static BOOL CjguiOwnerTraceThreadSamplesEnabled(void) {
    static _Atomic(int) enabled = -1;
    int state = atomic_load_explicit(&enabled, memory_order_acquire);
    if (state < 0) {
        const char *value = getenv("CJGUI_OWNER_THREAD_SAMPLES");
        int resolved = CjguiOwnerPhaseTraceEnabled() && value && strcmp(value, "1") == 0 ? 1 : 0;
        int expected = -1;
        atomic_compare_exchange_strong_explicit(&enabled, &expected, resolved,
            memory_order_release, memory_order_relaxed);
        state = atomic_load_explicit(&enabled, memory_order_acquire);
    }
    return state != 0;
}

static uint64_t CjguiOwnerTraceThreadInfoCpu(const thread_basic_info_data_t *info) {
    return ((uint64_t)info->user_time.seconds + (uint64_t)info->system_time.seconds) * 1000000000ULL +
        ((uint64_t)info->user_time.microseconds + (uint64_t)info->system_time.microseconds) * 1000ULL;
}

static void CjguiOwnerTraceCaptureThread(CjguiOwnerTraceStackSample *sample, thread_t target,
    uint8_t role, uint64_t expectedThreadId) {
    sample->role = role;
    sample->pid = (uint64_t)getpid();
    sample->startedNs = CjguiOwnerTraceNanoseconds();
    sample->threadId = UINT64_MAX;
    sample->expectedThreadId = expectedThreadId ? expectedThreadId : UINT64_MAX;
    sample->runState = -1;
    sample->infoStatus = KERN_FAILURE;
    sample->suspendStatus = KERN_FAILURE;
    sample->stateStatus = KERN_FAILURE;
    sample->resumeStatus = KERN_FAILURE;
    sample->frameStatus = KERN_FAILURE;
    sample->frameModel = 0;

    sample->infoStartedNs = CjguiOwnerTraceNanoseconds();
    thread_identifier_info_data_t identifier = {0};
    mach_msg_type_number_t identifierCount = THREAD_IDENTIFIER_INFO_COUNT;
    kern_return_t identifierResult = thread_info(target, THREAD_IDENTIFIER_INFO,
        (thread_info_t)&identifier, &identifierCount);
    sample->observedThreadId = identifierResult == KERN_SUCCESS ? identifier.thread_id : UINT64_MAX;
    if (identifierResult == KERN_SUCCESS) sample->threadId = identifier.thread_id;
    if (expectedThreadId != 0 && sample->threadId != expectedThreadId)
        sample->threadId = UINT64_MAX;

    thread_basic_info_data_t basic = {0};
    mach_msg_type_number_t basicCount = THREAD_BASIC_INFO_COUNT;
    sample->infoStatus = thread_info(target, THREAD_BASIC_INFO,
        (thread_info_t)&basic, &basicCount);
    if (sample->infoStatus == KERN_SUCCESS) {
        sample->runState = basic.run_state;
        sample->cpuNs = CjguiOwnerTraceThreadInfoCpu(&basic);
        sample->cpuValid = sample->threadId != UINT64_MAX;
    }
    sample->infoFinishedNs = CjguiOwnerTraceNanoseconds();
    sample->infoIntervalValid = sample->infoStartedNs != 0 &&
        sample->infoFinishedNs >= sample->infoStartedNs;

#if defined(__arm64__)
    arm_thread_state64_t armState = {0};
    mach_msg_type_number_t armStateCount = ARM_THREAD_STATE64_COUNT;
#elif defined(__x86_64__)
    x86_thread_state64_t x86State = {0};
    mach_msg_type_number_t x86StateCount = x86_THREAD_STATE64_COUNT;
#endif
    sample->suspendStatus = thread_suspend(target);
    if (sample->suspendStatus == KERN_SUCCESS) {
        // Keep the suspended interval limited to one register-state API call.
        // No memory reads, unwinding, allocation, formatting, or locks happen
        // before the matching resume.
        uint64_t suspendReturnedTicks = mach_absolute_time();
        uint64_t stateStartedTicks = UINT64_MAX;
        uint64_t stateFinishedTicks = UINT64_MAX;
#if defined(__arm64__)
        stateStartedTicks = mach_absolute_time();
        sample->stateStatus = thread_get_state(target, ARM_THREAD_STATE64,
            (thread_state_t)&armState, &armStateCount);
        stateFinishedTicks = mach_absolute_time();
#elif defined(__x86_64__)
        stateStartedTicks = mach_absolute_time();
        sample->stateStatus = thread_get_state(target, x86_THREAD_STATE64,
            (thread_state_t)&x86State, &x86StateCount);
        stateFinishedTicks = mach_absolute_time();
#else
        sample->stateStatus = KERN_NOT_SUPPORTED;
#endif
        sample->resumeStatus = thread_resume(target);
        if (sample->resumeStatus != KERN_SUCCESS) sample->resumeStatus = thread_resume(target);
        uint64_t resumedAtTicks = mach_absolute_time();
        if (sample->resumeStatus == KERN_SUCCESS) {
            mach_timebase_info_data_t timebase = {0};
            if (mach_timebase_info(&timebase) == KERN_SUCCESS && timebase.denom != 0 &&
                resumedAtTicks >= suspendReturnedTicks) {
                sample->suspendNs = (uint64_t)(((__uint128_t)(resumedAtTicks - suspendReturnedTicks) *
                    timebase.numer) / timebase.denom);
                sample->registerPauseStartedNs = (uint64_t)(((__uint128_t)suspendReturnedTicks *
                    timebase.numer) / timebase.denom);
                sample->registerPauseFinishedNs = (uint64_t)(((__uint128_t)resumedAtTicks *
                    timebase.numer) / timebase.denom);
                sample->pauseValid = 1;
                sample->registerPauseIntervalValid = 1;
                atomic_fetch_add_explicit(&gCjguiOwnerTraceSamplePauseNs, sample->suspendNs,
                    memory_order_relaxed);
                if (stateStartedTicks != UINT64_MAX && stateFinishedTicks != UINT64_MAX &&
                    stateFinishedTicks >= stateStartedTicks) {
                    sample->registerStateStartedNs = (uint64_t)(((__uint128_t)stateStartedTicks *
                        timebase.numer) / timebase.denom);
                    sample->registerStateFinishedNs = (uint64_t)(((__uint128_t)stateFinishedTicks *
                        timebase.numer) / timebase.denom);
                    sample->registerStateIntervalValid = 1;
                }
            }
        }
        if (!sample->pauseValid)
            atomic_fetch_add_explicit(&gCjguiOwnerTraceSamplePauseUnknown, 1, memory_order_relaxed);
#if defined(__arm64__)
        if (sample->stateStatus == KERN_SUCCESS) {
            arm_thread_state64_ptrauth_strip(armState);
            sample->pc = arm_thread_state64_get_pc(armState);
            sample->fp = arm_thread_state64_get_fp(armState);
            sample->sp = arm_thread_state64_get_sp(armState);
            sample->frames[0] = sample->pc;
            sample->frameCount = sample->pc != 0 ? 1 : 0;
            uint64_t linkRegister = arm_thread_state64_get_lr(armState);
            if (sample->frameCount == 1 && linkRegister != 0)
                sample->frames[sample->frameCount++] = linkRegister;
            sample->frameModel = 1; // PC and LR from the same ARM64 register snapshot.
        }
#elif defined(__x86_64__)
        if (sample->stateStatus == KERN_SUCCESS) {
            sample->pc = x86State.__rip;
            sample->fp = x86State.__rbp;
            sample->sp = x86State.__rsp;
            sample->frames[0] = sample->pc;
            sample->frameCount = sample->pc != 0 ? 1 : 0;
            sample->frameModel = 2; // x86_64 has no link register in this state flavor.
        }
#endif
        if (sample->stateStatus == KERN_SUCCESS && sample->frameCount > 0)
            sample->frameStatus = KERN_SUCCESS;
    } else {
        atomic_fetch_add_explicit(&gCjguiOwnerTraceSamplePauseUnknown, 1, memory_order_relaxed);
    }
    sample->finishedNs = CjguiOwnerTraceNanoseconds();
}

static void CjguiOwnerTracePublishStackSample(CjguiOwnerTraceStackSample *sample) {
    uint64_t sequence = atomic_fetch_add_explicit(&gCjguiOwnerTraceSampleSequence, 1,
        memory_order_relaxed) + 1;
    CjguiOwnerTraceStackSample *slot = &gCjguiOwnerTraceStackSamples[
        (sequence - 1) % CJGUI_OWNER_TRACE_SAMPLE_CAPACITY];
    bool expected = false;
    if (!atomic_compare_exchange_strong_explicit(&slot->writing, &expected, true,
            memory_order_acquire, memory_order_relaxed)) {
        atomic_fetch_add_explicit(&gCjguiOwnerTraceSampleDropped, 1, memory_order_relaxed);
        return;
    }
    if (sequence > CJGUI_OWNER_TRACE_SAMPLE_CAPACITY)
        atomic_fetch_add_explicit(&gCjguiOwnerTraceSampleOverwritten, 1, memory_order_relaxed);
    sample->sequence = sequence;
    memcpy(&slot->sequence, &sample->sequence,
        sizeof(*sample) - offsetof(CjguiOwnerTraceStackSample, sequence));
    atomic_store_explicit(&slot->publishedSequence, sequence, memory_order_release);
    atomic_store_explicit(&slot->writing, false, memory_order_release);
}

static void CjguiOwnerTraceCaptureSlowStackSamples(uint64_t turn) {
    uint64_t last = atomic_load_explicit(&gCjguiOwnerTraceSampleSequence, memory_order_acquire);
    uint64_t first = last > CJGUI_OWNER_TRACE_SAMPLE_CAPACITY ?
        last - CJGUI_OWNER_TRACE_SAMPLE_CAPACITY + 1 : (last ? 1 : 0);
    uint64_t retainedFirst = 0, retainedLast = 0, retainedCount = 0, dropped = 0;
    atomic_store_explicit(&gCjguiOwnerTraceSlowSampleFirst, 0, memory_order_relaxed);
    atomic_store_explicit(&gCjguiOwnerTraceSlowSampleLast, 0, memory_order_relaxed);
    atomic_store_explicit(&gCjguiOwnerTraceSlowSampleCount, 0, memory_order_relaxed);
    atomic_store_explicit(&gCjguiOwnerTraceSlowSampleDropped, 0, memory_order_relaxed);
    for (uint64_t sequence = first; sequence > 0 && sequence <= last; sequence++) {
        CjguiOwnerTraceStackSample *source = &gCjguiOwnerTraceStackSamples[
            (sequence - 1) % CJGUI_OWNER_TRACE_SAMPLE_CAPACITY];
        bool expected = false;
        if (!atomic_compare_exchange_strong_explicit(&source->writing, &expected, true,
                memory_order_acquire, memory_order_relaxed)) {
            dropped++;
            continue;
        }
        if (atomic_load_explicit(&source->publishedSequence, memory_order_acquire) == sequence &&
            source->turn == turn) {
            CjguiOwnerTraceStackSample *destination = &gCjguiOwnerTraceSlowStackSamples[
                (sequence - 1) % CJGUI_OWNER_TRACE_SAMPLE_CAPACITY];
            bool destinationExpected = false;
            if (atomic_compare_exchange_strong_explicit(&destination->writing, &destinationExpected, true,
                    memory_order_acquire, memory_order_relaxed)) {
                memcpy(&destination->sequence, &source->sequence,
                    sizeof(*source) - offsetof(CjguiOwnerTraceStackSample, sequence));
                atomic_store_explicit(&destination->publishedSequence, sequence, memory_order_release);
                atomic_store_explicit(&destination->writing, false, memory_order_release);
                if (retainedFirst == 0) retainedFirst = sequence;
                retainedLast = sequence;
                retainedCount++;
            } else {
                dropped++;
            }
        }
        atomic_store_explicit(&source->writing, false, memory_order_release);
    }
    atomic_store_explicit(&gCjguiOwnerTraceSlowSampleFirst, retainedFirst, memory_order_relaxed);
    atomic_store_explicit(&gCjguiOwnerTraceSlowSampleLast, retainedLast, memory_order_relaxed);
    atomic_store_explicit(&gCjguiOwnerTraceSlowSampleCount, retainedCount, memory_order_relaxed);
    atomic_store_explicit(&gCjguiOwnerTraceSlowSampleDropped, dropped, memory_order_relaxed);
}

static int CjguiOwnerTraceWatchPriority(const CjguiOwnerTraceWatch *watch) {
    if (watch->kind == 3) return 4; // dispatch wait
    if (watch->phase == CJGUI_OWNER_PHASE_OBSERVER_WRITE ||
        watch->phase == CJGUI_OWNER_PHASE_OBSERVER_FLUSH) return 3;
    if (watch->kind == 2) return 2; // explicit phase
    return 1; // complete owner turn
}

// The slot remains RELEASING until its unique send-right reference is actually
// returned. A sampler copy never owns another reference, and cannot free or
// overwrite a subsequent lease even when the port name happens to be equal.
static void CjguiOwnerTraceReleaseWatchSlot(int index, uint64_t lease) {
    pthread_mutex_lock(&gCjguiOwnerTraceWatchLock);
    CjguiOwnerTraceWatch *watch = &gCjguiOwnerTraceWatches[index];
    if (watch->leaseEpoch != lease || watch->state != CjguiTraceWatchReleasing || watch->releaseClaimed) {
        pthread_mutex_unlock(&gCjguiOwnerTraceWatchLock);
        return;
    }
    watch->releaseClaimed = YES;
    CjguiOwnerTraceWatch retiring = *watch;
    pthread_mutex_unlock(&gCjguiOwnerTraceWatchLock);
    if (retiring.ownerThread != MACH_PORT_NULL)
        mach_port_deallocate(mach_task_self(), retiring.ownerThread);
    pthread_mutex_lock(&gCjguiOwnerTraceWatchLock);
    watch = &gCjguiOwnerTraceWatches[index];
    if (watch->leaseEpoch == lease && watch->state == CjguiTraceWatchReleasing)
        memset(watch, 0, sizeof(*watch));
    pthread_mutex_unlock(&gCjguiOwnerTraceWatchLock);
    if (retiring.retiredNs) {
        cjgui_internal_renderer_owner_trace_boundary(retiring.session, retiring.turn,
            CJGUI_OWNER_PHASE_TRACE_WATCH_TAIL, retiring.kind, 0, lease, UINT64_MAX);
    }
}

static BOOL CjguiOwnerTraceSampleTargetReleased(const CjguiOwnerTraceStackSample *sample,
    thread_t target) {
    if (sample->suspendStatus != KERN_SUCCESS || sample->resumeStatus == KERN_SUCCESS) return YES;
    mach_port_type_t type = 0;
    return mach_port_type(mach_task_self(), target, &type) == KERN_SUCCESS &&
        (type & MACH_PORT_TYPE_DEAD_NAME) != 0;
}

static void CjguiOwnerTraceCompleteWatchSample(int index, const CjguiOwnerTraceWatch *captured,
    BOOL resolved) {
    BOOL release = NO;
    pthread_mutex_lock(&gCjguiOwnerTraceWatchLock);
    CjguiOwnerTraceWatch *watch = &gCjguiOwnerTraceWatches[index];
    if (watch->leaseEpoch == captured->leaseEpoch && watch->kind == captured->kind &&
        watch->key == captured->key && watch->sampling) {
        watch->sampling = NO;
        if (!resolved) {
            // Never silently return a right after an unmatched suspend. Keep
            // the bounded slot quarantined and forbid additional sampling.
            watch->active = NO;
            watch->state = CjguiTraceWatchQuarantined;
            gCjguiOwnerTraceSamplerStop = YES;
            gCjguiOwnerTraceSamplerState = CjguiTraceSamplerStopping;
            atomic_fetch_add(&gCjguiOwnerTraceResumeUnresolved, 1);
        } else if (watch->state == CjguiTraceWatchRetired) {
            watch->state = CjguiTraceWatchReleasing;
            release = YES;
        } else if (watch->state == CjguiTraceWatchSampling) {
            watch->state = CjguiTraceWatchLive;
        }
    }
    if (atomic_load(&gCjguiOwnerTraceSamplerSelectedLease) == captured->leaseEpoch) {
        atomic_store(&gCjguiOwnerTraceSamplerInFlight, 0);
        atomic_store(&gCjguiOwnerTraceSamplerSelectedLease, 0);
    }
    pthread_cond_broadcast(&gCjguiOwnerTraceWatchCondition);
    pthread_mutex_unlock(&gCjguiOwnerTraceWatchLock);
    if (release) CjguiOwnerTraceReleaseWatchSlot(index, captured->leaseEpoch);
#ifdef CJGUI_INTERNAL_RENDERER_TESTING
    if (gCjguiOwnerTraceCompleteHook) gCjguiOwnerTraceCompleteHook(index, captured->leaseEpoch);
#endif
}

static void *CjguiOwnerTraceSamplerMain(void *unused) {
    (void)unused;
    for (;;) {
        pthread_mutex_lock(&gCjguiOwnerTraceWatchLock);
        int selected = -1, bestPriority = 0;
        while (!gCjguiOwnerTraceSamplerStop) {
            selected = -1;
            bestPriority = 0;
            for (int index = 0; index < CJGUI_OWNER_TRACE_WATCH_CAPACITY; index++) {
                CjguiOwnerTraceWatch *watch = &gCjguiOwnerTraceWatches[index];
                if (watch->state != CjguiTraceWatchLive) continue;
                int priority = CjguiOwnerTraceWatchPriority(watch);
                if (priority > bestPriority) { selected = index; bestPriority = priority; }
            }
            if (selected >= 0) break;
            pthread_cond_wait(&gCjguiOwnerTraceWatchCondition, &gCjguiOwnerTraceWatchLock);
        }
        if (gCjguiOwnerTraceSamplerStop) {
            pthread_mutex_unlock(&gCjguiOwnerTraceWatchLock);
            return NULL;
        }
        CjguiOwnerTraceWatch *watch = &gCjguiOwnerTraceWatches[selected];
        watch->sampling = YES;
        watch->state = CjguiTraceWatchSampling;
        CjguiOwnerTraceWatch captured = *watch;
        atomic_store(&gCjguiOwnerTraceSamplerSelectedLease, captured.leaseEpoch);
        atomic_store(&gCjguiOwnerTraceSamplerInFlight, 1);
        thread_t appKitThread = captured.kind == 3 ? gCjguiOwnerTraceMainThread : MACH_PORT_NULL;
        pthread_mutex_unlock(&gCjguiOwnerTraceWatchLock);
#ifdef CJGUI_INTERNAL_RENDERER_TESTING
        if (gCjguiOwnerTraceBorrowHook) gCjguiOwnerTraceBorrowHook(selected, captured.leaseEpoch);
#endif

        CjguiOwnerTraceStackSample sample = {0};
        sample.session = captured.session;
        sample.turn = captured.turn;
        sample.request = captured.request;
        sample.dispatch = captured.dispatch;
        sample.generation = captured.generation;
        sample.span = captured.key;
        sample.phase = captured.phase;
        CjguiOwnerTraceCaptureThread(&sample, captured.ownerThread, 1,
            captured.ownerThreadId);
        CjguiOwnerTraceStackSample mainSample = {0};
        if (appKitThread != MACH_PORT_NULL && appKitThread != captured.ownerThread) {
            mainSample.session = captured.session;
            mainSample.turn = captured.turn;
            mainSample.request = captured.request;
            mainSample.dispatch = captured.dispatch;
            mainSample.generation = captured.generation;
            mainSample.span = captured.key;
            mainSample.phase = captured.phase;
            CjguiOwnerTraceCaptureThread(&mainSample, appKitThread, 2, 0);
        }
        BOOL resolved = CjguiOwnerTraceSampleTargetReleased(&sample, captured.ownerThread) &&
            (!mainSample.role || CjguiOwnerTraceSampleTargetReleased(&mainSample, appKitThread));
        pthread_mutex_lock(&gCjguiOwnerTraceWatchLock);
        watch = &gCjguiOwnerTraceWatches[selected];
        uint64_t retiredNs = watch->leaseEpoch == captured.leaseEpoch ? watch->retiredNs : UINT64_MAX;
        pthread_mutex_unlock(&gCjguiOwnerTraceWatchLock);
        sample.watchLease = captured.leaseEpoch;
        sample.retiredNs = retiredNs;
        CjguiOwnerTracePublishStackSample(&sample);
        if (mainSample.role) {
            mainSample.watchLease = captured.leaseEpoch;
            mainSample.retiredNs = retiredNs;
            CjguiOwnerTracePublishStackSample(&mainSample);
        }
        CjguiOwnerTraceCompleteWatchSample(selected, &captured, resolved);

        struct timespec deadline = {0};
        clock_gettime(CLOCK_REALTIME, &deadline);
        deadline.tv_nsec += 4000000L;
        if (deadline.tv_nsec >= 1000000000L) { deadline.tv_sec += 1; deadline.tv_nsec -= 1000000000L; }
        pthread_mutex_lock(&gCjguiOwnerTraceWatchLock);
        if (!gCjguiOwnerTraceSamplerStop)
            pthread_cond_timedwait(&gCjguiOwnerTraceWatchCondition,
                &gCjguiOwnerTraceWatchLock, &deadline);
        pthread_mutex_unlock(&gCjguiOwnerTraceWatchLock);
    }
}

static void CjguiOwnerTraceRememberMainThread(void) {
    if (!CjguiOwnerTraceThreadSamplesEnabled() || gCjguiOwnerTraceMainThread != MACH_PORT_NULL) return;
    thread_t thread = mach_thread_self();
    if (thread == MACH_PORT_NULL) return;
    pthread_mutex_lock(&gCjguiOwnerTraceWatchLock);
    if (gCjguiOwnerTraceMainThread == MACH_PORT_NULL) gCjguiOwnerTraceMainThread = thread;
    else mach_port_deallocate(mach_task_self(), thread);
    pthread_mutex_unlock(&gCjguiOwnerTraceWatchLock);
}

static uint64_t CjguiOwnerTraceAppendManaged(uint32_t kind, uint64_t session, uint64_t turn,
    uint64_t request, uint64_t dispatch, uint64_t generation, uint32_t phase, uint64_t span,
    uint64_t managedThreadId);

static void CjguiOwnerTraceBeginWatch(uint8_t kind, uint64_t key, uint64_t session,
    uint64_t turn, uint64_t request, uint64_t dispatch, uint64_t generation, uint32_t phase,
    uint64_t managedThreadId) {
    if (!CjguiOwnerTraceThreadSamplesEnabled()) return;
    uint64_t registrationSpan = CjguiOwnerTraceAppendManaged(CJGUI_OWNER_TRACE_PHASE_BEGIN,
        session, turn, request, dispatch, generation, CJGUI_OWNER_PHASE_TRACE_WATCH_REGISTER,
        0, managedThreadId);
    thread_t ownerThread = mach_thread_self();
    if (ownerThread == MACH_PORT_NULL) {
        atomic_fetch_add(&gCjguiOwnerTraceWatchDropped, 1);
        CjguiOwnerTraceAppendManaged(CJGUI_OWNER_TRACE_PHASE_END, session, turn, request,
            dispatch, generation, CJGUI_OWNER_PHASE_TRACE_WATCH_REGISTER, registrationSpan,
            managedThreadId);
        return;
    }
    uint64_t ownerThreadId = 0;
    if (pthread_threadid_np(NULL, &ownerThreadId) != 0) ownerThreadId = UINT64_MAX;
    pthread_mutex_lock(&gCjguiOwnerTraceWatchLock);
    if (gCjguiOwnerTraceSamplerState == CjguiTraceSamplerUnstarted) {
        if (pthread_create(&gCjguiOwnerTraceSamplerThread, NULL, CjguiOwnerTraceSamplerMain, NULL) == 0)
            gCjguiOwnerTraceSamplerStarted = YES;
        if (gCjguiOwnerTraceSamplerStarted) gCjguiOwnerTraceSamplerState = CjguiTraceSamplerRunning;
    }
    int freeIndex = -1;
    for (int index = 0; index < CJGUI_OWNER_TRACE_WATCH_CAPACITY; index++) {
        if (gCjguiOwnerTraceWatches[index].state == CjguiTraceWatchFree) { freeIndex = index; break; }
    }
    if (freeIndex >= 0 && gCjguiOwnerTraceSamplerState == CjguiTraceSamplerRunning &&
        gCjguiOwnerTraceWatchNextLease != UINT64_MAX) {
        gCjguiOwnerTraceWatches[freeIndex] = (CjguiOwnerTraceWatch){
            .active = YES, .state = CjguiTraceWatchLive,
            .leaseEpoch = gCjguiOwnerTraceWatchNextLease++,
            .kind = kind, .key = key, .session = session, .turn = turn,
            .request = request, .dispatch = dispatch, .generation = generation,
            .phase = phase, .ownerThread = ownerThread, .ownerThreadId = ownerThreadId
        };
        pthread_cond_signal(&gCjguiOwnerTraceWatchCondition);
        ownerThread = MACH_PORT_NULL;
    } else {
        atomic_fetch_add_explicit(&gCjguiOwnerTraceWatchDropped, 1, memory_order_relaxed);
    }
    pthread_mutex_unlock(&gCjguiOwnerTraceWatchLock);
    if (ownerThread != MACH_PORT_NULL) mach_port_deallocate(mach_task_self(), ownerThread);
    CjguiOwnerTraceAppendManaged(CJGUI_OWNER_TRACE_PHASE_END, session, turn, request,
        dispatch, generation, CJGUI_OWNER_PHASE_TRACE_WATCH_REGISTER, registrationSpan,
        managedThreadId);
}

static void CjguiOwnerTraceEndWatch(uint8_t kind, uint64_t key, uint64_t managedThreadId,
    uint64_t session, uint64_t turn, uint64_t request, uint64_t dispatch, uint64_t generation) {
    cjgui_internal_renderer_owner_trace_boundary(session, turn,
        CJGUI_OWNER_PHASE_TRACE_WATCH_ENTRY, kind, 0, key, managedThreadId);
    if (!CjguiOwnerTraceThreadSamplesEnabled()) return;
    int releaseIndex = -1;
    uint64_t releaseLease = 0;
    // Complete caller-side retirement includes mutex acquisition and any
    // immediate port release. A sampling slot is retired without waiting;
    // its actual tail remains attributed to the same immutable lease/turn.
    uint64_t cleanupSpan = CjguiOwnerTraceAppendManaged(CJGUI_OWNER_TRACE_PHASE_BEGIN,
        session, turn, request, dispatch, generation,
        CJGUI_OWNER_PHASE_TRACE_WATCH_CLEANUP, 0, managedThreadId);
    pthread_mutex_lock(&gCjguiOwnerTraceWatchLock);
    for (int index = 0; index < CJGUI_OWNER_TRACE_WATCH_CAPACITY; index++) {
        CjguiOwnerTraceWatch *watch = &gCjguiOwnerTraceWatches[index];
        if ((watch->state != CjguiTraceWatchLive && watch->state != CjguiTraceWatchSampling) ||
            watch->kind != kind || watch->key != key) continue;
        watch->retiredNs = CjguiOwnerTraceNanoseconds();
        watch->active = NO;
        releaseLease = watch->leaseEpoch;
        if (watch->state == CjguiTraceWatchSampling) {
            watch->state = CjguiTraceWatchRetired;
        } else {
            watch->state = CjguiTraceWatchReleasing;
            releaseIndex = index;
        }
        break;
    }
    pthread_mutex_unlock(&gCjguiOwnerTraceWatchLock);
    if (releaseLease)
        cjgui_internal_renderer_owner_trace_boundary(session, turn,
            CJGUI_OWNER_PHASE_TRACE_WATCH_RETIRE, kind, 0, releaseLease, managedThreadId);
    if (releaseIndex >= 0) CjguiOwnerTraceReleaseWatchSlot(releaseIndex, releaseLease);
    CjguiOwnerTraceAppendManaged(CJGUI_OWNER_TRACE_PHASE_END,
        session, turn, request, dispatch, generation,
        CJGUI_OWNER_PHASE_TRACE_WATCH_CLEANUP, cleanupSpan, managedThreadId);
}

static void CjguiOwnerTraceStopSampler(void) {
    pthread_mutex_lock(&gCjguiOwnerTraceWatchLock);
    while (gCjguiOwnerTraceSamplerJoinOwner)
        pthread_cond_wait(&gCjguiOwnerTraceWatchCondition, &gCjguiOwnerTraceWatchLock);
    if (gCjguiOwnerTraceSamplerState == CjguiTraceSamplerStopped) {
        pthread_mutex_unlock(&gCjguiOwnerTraceWatchLock);
        return;
    }
    BOOL join = gCjguiOwnerTraceSamplerStarted;
    if (join && pthread_equal(pthread_self(), gCjguiOwnerTraceSamplerThread)) {
        pthread_mutex_unlock(&gCjguiOwnerTraceWatchLock);
        atomic_fetch_add(&gCjguiOwnerTraceResumeUnresolved, 1);
        return;
    }
    gCjguiOwnerTraceSamplerJoinOwner = YES;
    gCjguiOwnerTraceSamplerState = CjguiTraceSamplerStopping;
    gCjguiOwnerTraceSamplerStop = YES;
    atomic_store(&gCjguiOwnerTraceSamplerStoppedObserved, 1);
    pthread_cond_broadcast(&gCjguiOwnerTraceWatchCondition);
    pthread_mutex_unlock(&gCjguiOwnerTraceWatchLock);
    if (join) pthread_join(gCjguiOwnerTraceSamplerThread, NULL);
    pthread_mutex_lock(&gCjguiOwnerTraceWatchLock);
    int releasing[CJGUI_OWNER_TRACE_WATCH_CAPACITY];
    uint64_t leases[CJGUI_OWNER_TRACE_WATCH_CAPACITY];
    int releasingCount = 0, quarantinedCount = 0;
    for (int index = 0; index < CJGUI_OWNER_TRACE_WATCH_CAPACITY; index++) {
        CjguiOwnerTraceWatch *watch = &gCjguiOwnerTraceWatches[index];
        if (watch->state == CjguiTraceWatchQuarantined) { quarantinedCount++; continue; }
        if (watch->state != CjguiTraceWatchFree) {
            watch->state = CjguiTraceWatchReleasing;
            releasing[releasingCount] = index;
            leases[releasingCount++] = watch->leaseEpoch;
        }
    }
    thread_t mainThread = gCjguiOwnerTraceMainThread;
    if (!quarantinedCount) gCjguiOwnerTraceMainThread = MACH_PORT_NULL;
    gCjguiOwnerTraceSamplerStarted = NO;
    pthread_mutex_unlock(&gCjguiOwnerTraceWatchLock);
    for (int i = 0; i < releasingCount; i++) CjguiOwnerTraceReleaseWatchSlot(releasing[i], leases[i]);
    if (!quarantinedCount && mainThread != MACH_PORT_NULL) mach_port_deallocate(mach_task_self(), mainThread);
    pthread_mutex_lock(&gCjguiOwnerTraceWatchLock);
    gCjguiOwnerTraceSamplerState = CjguiTraceSamplerStopped;
    gCjguiOwnerTraceSamplerJoinOwner = NO;
    pthread_cond_broadcast(&gCjguiOwnerTraceWatchCondition);
    pthread_mutex_unlock(&gCjguiOwnerTraceWatchLock);
}

static const char *CjguiOwnerTraceId(uint64_t value, char buffer[32]) {
    if (value == UINT64_MAX) return "unknown";
    snprintf(buffer, 32, "%llu", (unsigned long long)value);
    return buffer;
}

static void CjguiOwnerTraceHexText(const char *source, char *destination, size_t capacity,
                                   BOOL *outTruncated) {
    static const char digits[] = "0123456789abcdef";
    size_t output = 0;
    size_t input = 0;
    if (outTruncated) *outTruncated = NO;
    if (!source || capacity < 3) {
        if (capacity > 0) destination[0] = '\0';
        return;
    }
    size_t maxBytes = (capacity - 1) / 2;
    while (source[input] != '\0' && input < maxBytes) {
        unsigned char byte = (unsigned char)source[input++];
        destination[output++] = digits[byte >> 4];
        destination[output++] = digits[byte & 0x0f];
    }
    destination[output] = '\0';
    if (outTruncated) *outTruncated = source[input] != '\0';
}

static uint64_t CjguiOwnerTraceAppendAtWithOwnerIdentity(uint32_t kind, uint64_t session, uint64_t turn,
    uint64_t request, uint64_t dispatch, uint64_t generation, uint32_t phase, uint64_t span,
    uint64_t timestampOverride, uint64_t threadIdOverride, uint64_t ownerConsumeTurn,
    uint64_t ownerConsumeGeneration, BOOL ownerConsume, uint64_t managedThreadId) {
    uint64_t sequence = atomic_fetch_add_explicit(&gCjguiOwnerTraceNextSequence, 1,
        memory_order_relaxed) + 1;
    if (span == 0 && (kind == CJGUI_OWNER_TRACE_TURN_BEGIN || kind == CJGUI_OWNER_TRACE_PHASE_BEGIN ||
        kind == CJGUI_OWNER_TRACE_OBSERVER_READ_BEGIN || kind == CJGUI_OWNER_TRACE_OBSERVER_FORMAT_BEGIN ||
        kind == CJGUI_OWNER_TRACE_OBSERVER_WRITE_BEGIN || kind == CJGUI_OWNER_TRACE_OBSERVER_FLUSH_BEGIN ||
        kind == CJGUI_OWNER_TRACE_IDLE_BEGIN)) span = sequence;
    CjguiOwnerTraceRecord *slot = &gCjguiOwnerTraceRecords[(sequence - 1) % CJGUI_OWNER_TRACE_CAPACITY];
    bool expected = false;
    if (!atomic_compare_exchange_strong_explicit(&slot->writing, &expected, true,
            memory_order_acquire, memory_order_relaxed)) {
        atomic_fetch_add_explicit(&gCjguiOwnerTraceDropped, 1, memory_order_relaxed);
        return sequence;
    }
    uint64_t now = timestampOverride ? timestampOverride : CjguiOwnerTraceNanoseconds();
    // Take the event's boundary before atexit registration. On the first
    // enabled event, registration cost therefore remains inside the recorded
    // process wall and (for a begin record) inside the owner turn.
    CjguiOwnerTraceEnsureExitExport();
    BOOL cpuValid = NO;
    uint64_t threadId = 0;
    uint64_t cpuNs = timestampOverride ? 0 : CjguiOwnerTraceThreadCpu(&threadId, &cpuValid);
    if (timestampOverride) threadId = threadIdOverride ? threadIdOverride : UINT64_MAX;
    slot->sequence = sequence;
    slot->monoNs = now;
    slot->cpuNs = cpuNs;
    slot->session = session;
    slot->turn = turn;
    slot->request = request;
    slot->dispatch = dispatch;
    slot->generation = generation;
    slot->span = span;
    slot->threadId = threadId;
    slot->managedThreadId = managedThreadId != UINT64_MAX ? managedThreadId : UINT64_MAX;
    slot->ownerConsumeTurn = ownerConsume && ownerConsumeTurn != 0 && ownerConsumeTurn != UINT64_MAX
        ? ownerConsumeTurn : 0;
    slot->ownerConsumeGeneration = ownerConsume && ownerConsumeGeneration != 0 &&
        ownerConsumeGeneration != UINT64_MAX ? ownerConsumeGeneration : 0;
    slot->ownerConsumeThreadId = ownerConsume && threadId != 0 && threadId != UINT64_MAX
        ? threadId : 0;
    slot->kind = kind;
    slot->phase = phase;
    slot->cpuValid = cpuValid;
    atomic_store_explicit(&slot->publishedSequence, sequence, memory_order_release);
    atomic_store_explicit(&slot->writing, false, memory_order_release);
    uint64_t empty = 0;
    atomic_compare_exchange_strong_explicit(&gCjguiOwnerTraceFirstNs, &empty, now,
        memory_order_relaxed, memory_order_relaxed);
    BOOL outerBegin = kind == CJGUI_OWNER_TRACE_BOUNDARY &&
        phase == CJGUI_OWNER_PHASE_OWNER_OUTER_BEGIN;
    BOOL outerEnd = kind == CJGUI_OWNER_TRACE_BOUNDARY &&
        phase == CJGUI_OWNER_PHASE_OWNER_OUTER_END;
    BOOL traceTurnBegin = kind == CJGUI_OWNER_TRACE_TURN_BEGIN;
    if (outerBegin || (traceTurnBegin &&
        (session != atomic_load_explicit(&gCjguiOwnerTraceActiveSession, memory_order_relaxed) ||
         turn != atomic_load_explicit(&gCjguiOwnerTraceActiveTurn, memory_order_relaxed)))) {
        atomic_store_explicit(&gCjguiOwnerTraceActiveSession, session, memory_order_relaxed);
        atomic_store_explicit(&gCjguiOwnerTraceActiveTurn, turn, memory_order_relaxed);
        atomic_store_explicit(&gCjguiOwnerTraceActiveStartSequence, sequence, memory_order_relaxed);
        atomic_store_explicit(&gCjguiOwnerTraceActiveHasCriticalObservation, false, memory_order_release);
    }
    // Compact budget endpoints must survive the detailed source ring, but
    // they are not user activity and must not trigger a full-turn copy.
    BOOL activityCritical = CjguiOwnerTraceIsRetentionCritical(kind, phase);
    BOOL fixedPreparationSummary = CjguiOwnerTraceIsFixedPreparationSummary(kind, phase);
    BOOL fixedWaitSummary = CjguiOwnerTraceIsFixedWaitSummary(kind, phase);
    BOOL budgetBoundary = outerBegin || outerEnd || kind == CJGUI_OWNER_TRACE_IDLE_BEGIN ||
        kind == CJGUI_OWNER_TRACE_IDLE_END;
    if (activityCritical || fixedPreparationSummary || fixedWaitSummary || budgetBoundary) {
        if (activityCritical && session == atomic_load_explicit(&gCjguiOwnerTraceActiveSession, memory_order_relaxed) &&
            turn == atomic_load_explicit(&gCjguiOwnerTraceActiveTurn, memory_order_relaxed))
            atomic_store_explicit(&gCjguiOwnerTraceActiveHasCriticalObservation, true, memory_order_release);
        uint64_t ordinal = atomic_load_explicit(&gCjguiOwnerTraceCriticalNext, memory_order_relaxed);
        if (CjguiOwnerTraceCopyToRetention(slot, sequence, gCjguiOwnerTraceCriticalRecords,
                CJGUI_OWNER_TRACE_CRITICAL_CAPACITY, &gCjguiOwnerTraceCriticalNext, NO,
                &gCjguiOwnerTraceCriticalDropped, &gCjguiOwnerTraceCriticalOverwritten)) {
            uint64_t unset = 0;
            uint64_t retainedFirst = sequence;
            if (ordinal >= CJGUI_OWNER_TRACE_CRITICAL_CAPACITY) {
                CjguiOwnerTraceRecord *oldest = &gCjguiOwnerTraceCriticalRecords[
                    (ordinal + 1) % CJGUI_OWNER_TRACE_CRITICAL_CAPACITY];
                retainedFirst = oldest->sequence;
            }
            if (ordinal < CJGUI_OWNER_TRACE_CRITICAL_CAPACITY)
                atomic_compare_exchange_strong_explicit(&gCjguiOwnerTraceCriticalFirstSequence, &unset,
                    retainedFirst, memory_order_relaxed, memory_order_relaxed);
            else
                atomic_store_explicit(&gCjguiOwnerTraceCriticalFirstSequence, retainedFirst, memory_order_relaxed);
            atomic_store_explicit(&gCjguiOwnerTraceCriticalLastSequence, sequence, memory_order_relaxed);
        }
    }
    if (outerBegin && atomic_load_explicit(&gCjguiOwnerTraceStartupState, memory_order_acquire) == 0) {
        uint8_t unseen = 0;
        if (atomic_compare_exchange_strong_explicit(&gCjguiOwnerTraceStartupState, &unseen, 3,
                memory_order_acq_rel, memory_order_relaxed)) {
            atomic_store_explicit(&gCjguiOwnerTraceStartupSession, session, memory_order_relaxed);
            atomic_store_explicit(&gCjguiOwnerTraceStartupTurn, turn, memory_order_relaxed);
            atomic_store_explicit(&gCjguiOwnerTraceStartupState, 1, memory_order_release);
        }
    }
    // The bootstrap owner call begins before a renderer token exists. Its
    // children acquire that real token during this same call. Retain the
    // bounded interval's published facts with their original identities,
    // rather than filtering out those children by the pre-create token.
    // Concurrent facts keep their own identity too; only the original outer
    // end may finish this interval. Capacity loss remains explicitly counted.
    if (atomic_load_explicit(&gCjguiOwnerTraceStartupState, memory_order_acquire) == 1) {
        (void)CjguiOwnerTraceCopyToRetention(slot, sequence, gCjguiOwnerTraceStartupRecords,
            CJGUI_OWNER_TRACE_STARTUP_CAPACITY, &gCjguiOwnerTraceStartupCount, YES,
            &gCjguiOwnerTraceStartupDropped, NULL);
        uint64_t startupCount = atomic_load_explicit(&gCjguiOwnerTraceStartupCount, memory_order_relaxed);
        if (startupCount <= CJGUI_OWNER_TRACE_STARTUP_CAPACITY) {
            uint64_t unset = 0;
            atomic_compare_exchange_strong_explicit(&gCjguiOwnerTraceStartupFirstSequence, &unset,
                sequence, memory_order_relaxed, memory_order_relaxed);
            atomic_store_explicit(&gCjguiOwnerTraceStartupLastSequence, sequence, memory_order_relaxed);
        }
        if (outerEnd &&
            session == atomic_load_explicit(&gCjguiOwnerTraceStartupSession, memory_order_relaxed) &&
            turn == atomic_load_explicit(&gCjguiOwnerTraceStartupTurn, memory_order_relaxed))
            atomic_store_explicit(&gCjguiOwnerTraceStartupState, 2, memory_order_release);
    }
    if (outerBegin || (kind == CJGUI_OWNER_TRACE_TURN_BEGIN &&
        atomic_load_explicit(&gCjguiOwnerTraceTurnStartIdentity, memory_order_acquire) != turn)) {
        atomic_store_explicit(&gCjguiOwnerTraceTurnStartNs, now, memory_order_release);
        atomic_store_explicit(&gCjguiOwnerTraceTurnStartIdentity, turn, memory_order_release);
        atomic_store_explicit(&gCjguiOwnerTraceTurnStartSession, session, memory_order_release);
        atomic_store_explicit(&gCjguiOwnerTraceTurnStartGeneration, generation, memory_order_release);
        atomic_store_explicit(&gCjguiOwnerTraceTurnStartThread, threadId, memory_order_release);
        atomic_store_explicit(&gCjguiOwnerTraceTurnHasOuterBegin, outerBegin, memory_order_release);
        atomic_store_explicit(&gCjguiOwnerTraceCurrentTurnIdleNs, 0, memory_order_release);
    }
    BOOL capturedNow = NO;
    BOOL completeOuter = kind == CJGUI_OWNER_TRACE_BOUNDARY && phase == CJGUI_OWNER_PHASE_OWNER_OUTER_END;
    BOOL legacyEnd = kind == CJGUI_OWNER_TRACE_TURN_END &&
        !atomic_load_explicit(&gCjguiOwnerTraceTurnHasOuterBegin, memory_order_acquire);
    if (completeOuter || legacyEnd) {
        uint64_t turnStarted = atomic_load_explicit(&gCjguiOwnerTraceTurnStartNs, memory_order_acquire);
        uint64_t turnIdentity = atomic_load_explicit(&gCjguiOwnerTraceTurnStartIdentity, memory_order_acquire);
        uint64_t turnIdle = atomic_load_explicit(&gCjguiOwnerTraceCurrentTurnIdleNs, memory_order_acquire);
        uint64_t completedAt = CjguiOwnerTraceNanoseconds();
        BOOL sameLiveIdentity = session > 0 && session <= 4 && generation != 0 && generation != UINT64_MAX &&
            session == atomic_load_explicit(&gCjguiOwnerTraceTurnStartSession, memory_order_acquire) &&
            generation == atomic_load_explicit(&gCjguiOwnerTraceTurnStartGeneration, memory_order_acquire) &&
            threadId != UINT64_MAX && threadId != 0 &&
            threadId == atomic_load_explicit(&gCjguiOwnerTraceTurnStartThread, memory_order_acquire);
        if (sameLiveIdentity && turn != 0 && turn != UINT64_MAX && turn == turnIdentity &&
            turnStarted != 0 && completedAt >= turnStarted &&
            completedAt - turnStarted >= turnIdle &&
            completedAt - turnStarted - turnIdle >= 16000000ULL &&
            completedAt - turnStarted - turnIdle >
                atomic_load_explicit(&gCjguiOwnerTraceSlowWorkNs, memory_order_acquire) &&
            atomic_load_explicit(&gCjguiOwnerTraceSlowTurn, memory_order_acquire) != turn) {
            // Retain the largest complete same-session/OS-thread sample.
            // A partial/closing session-0 turn cannot erase natural evidence.
            atomic_store_explicit(&gCjguiOwnerTraceSlowWorkNs,
                completedAt - turnStarted - turnIdle, memory_order_release);
            CjguiOwnerTraceCaptureSlowWindow(sequence, turn);
            CjguiOwnerTraceCaptureSlowStackSamples(turn);
            CjguiOwnerTraceRefreshTurnEndTimestamp(sequence, completedAt);
            capturedNow = YES;
        }
    }
    if (!capturedNow && atomic_load_explicit(&gCjguiOwnerTraceSlowPostRemaining,
            memory_order_acquire) > 0) {
        if (CjguiOwnerTraceCopyToSlow(sequence)) {
            uint64_t firstSlow = atomic_load_explicit(&gCjguiOwnerTraceSlowFirstSequence, memory_order_relaxed);
            uint64_t lastSlow = atomic_load_explicit(&gCjguiOwnerTraceSlowLastSequence, memory_order_relaxed);
            if (firstSlow == 0 || sequence < firstSlow)
                atomic_store_explicit(&gCjguiOwnerTraceSlowFirstSequence, sequence, memory_order_relaxed);
            if (sequence > lastSlow)
                atomic_store_explicit(&gCjguiOwnerTraceSlowLastSequence, sequence, memory_order_relaxed);
            atomic_fetch_sub_explicit(&gCjguiOwnerTraceSlowPostRemaining, 1, memory_order_relaxed);
        } else {
            atomic_fetch_add_explicit(&gCjguiOwnerTraceSlowDropped, 1, memory_order_relaxed);
        }
    }
    if (outerEnd || legacyEnd) CjguiOwnerTraceCaptureActivityTurn(session, turn, sequence);
    return sequence;
}

static uint64_t CjguiOwnerTraceAppendAt(uint32_t kind, uint64_t session, uint64_t turn,
    uint64_t request, uint64_t dispatch, uint64_t generation, uint32_t phase, uint64_t span,
    uint64_t timestampOverride, uint64_t threadIdOverride) {
    return CjguiOwnerTraceAppendAtWithOwnerIdentity(kind, session, turn, request, dispatch,
        generation, phase, span, timestampOverride, threadIdOverride, 0, 0, NO, UINT64_MAX);
}

static uint64_t CjguiOwnerTraceAppend(uint32_t kind, uint64_t session, uint64_t turn,
    uint64_t request, uint64_t dispatch, uint64_t generation, uint32_t phase, uint64_t span) {
    return CjguiOwnerTraceAppendAt(kind, session, turn, request, dispatch, generation, phase, span, 0, 0);
}

static uint64_t CjguiOwnerTraceAppendManaged(uint32_t kind, uint64_t session, uint64_t turn,
    uint64_t request, uint64_t dispatch, uint64_t generation, uint32_t phase, uint64_t span,
    uint64_t managedThreadId) {
    return CjguiOwnerTraceAppendAtWithOwnerIdentity(kind, session, turn, request, dispatch,
        generation, phase, span, 0, 0, 0, 0, NO, managedThreadId);
}

void cjgui_internal_renderer_owner_trace_boundary(uint64_t session, uint64_t turn,
    uint32_t stage, uint32_t relatedKind, uint32_t relatedPhase, uint64_t value,
    uint64_t managedId) {
    uint64_t now = CjguiOwnerTraceNanoseconds();
    if (!CjguiOwnerPhaseTraceEnabled()) return;
    uint64_t threadId = UINT64_MAX;
    if (pthread_threadid_np(NULL, &threadId) != 0 || !threadId) threadId = UINT64_MAX;
    if (!turn) turn = atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn, memory_order_acquire);
    uint64_t generation = UINT64_MAX, liveGeneration = 0;
    if (cjgui_internal_renderer_coordinate_lifetime(session, &liveGeneration) != 0 && liveGeneration != 0)
        generation = liveGeneration;
    (void)CjguiOwnerTraceAppendAtWithOwnerIdentity(CJGUI_OWNER_TRACE_BOUNDARY,
        session, turn, relatedKind, relatedPhase, generation, stage, value,
        now, threadId, 0, 0, NO, managedId);
    if (stage == CJGUI_OWNER_PHASE_OWNER_OUTER_END) {
        uint64_t leaseBefore = atomic_load(&gCjguiOwnerTraceSamplerSelectedLease);
        uint64_t inFlight = atomic_load(&gCjguiOwnerTraceSamplerInFlight);
        uint64_t stopped = atomic_load(&gCjguiOwnerTraceSamplerStoppedObserved);
        uint64_t leaseAfter = atomic_load(&gCjguiOwnerTraceSamplerSelectedLease);
        uint64_t snapshot = leaseBefore == leaseAfter ? ((inFlight & 1) | ((stopped & 1) << 1)) : UINT64_MAX;
        (void)CjguiOwnerTraceAppendAtWithOwnerIdentity(CJGUI_OWNER_TRACE_OBSERVATION_SCALAR,
            session, turn, leaseAfter, atomic_load(&gCjguiOwnerTraceSampleSequence),
            atomic_load(&gCjguiOwnerTraceSampleDropped), CJGUI_OWNER_PHASE_TRACE_SAMPLER_SNAPSHOT,
            snapshot, CjguiOwnerTraceNanoseconds(), threadId, 0, 0, NO, UINT64_MAX);
    }
}

uint64_t cjgui_internal_renderer_owner_trace_record(uint32_t kind, uint64_t session,
    uint64_t turn, uint64_t request, uint64_t dispatch, uint64_t generation,
    uint32_t phase, uint64_t span) {
    return cjgui_internal_renderer_owner_trace_managed_record(kind, session, turn, request,
        dispatch, generation, phase, span, UINT64_MAX, 1);
}

uint64_t cjgui_internal_renderer_owner_trace_managed_record(uint32_t kind, uint64_t session,
    uint64_t turn, uint64_t request, uint64_t dispatch, uint64_t generation,
    uint32_t phase, uint64_t span, uint64_t managedId, uint8_t withWatch) {
    if (kind == CJGUI_OWNER_TRACE_TURN_END || phase == CJGUI_OWNER_PHASE_HOST_OWNER_PUMP ||
        phase == CJGUI_OWNER_PHASE_COST_OBSERVER)
        cjgui_internal_renderer_owner_trace_boundary(session, turn,
            CJGUI_OWNER_PHASE_TRACE_NATIVE_ENTRY, kind, phase, 0, managedId);
    if (!CjguiOwnerPhaseTraceEnabled()) return 0;
    BOOL turnBegin = kind == CJGUI_OWNER_TRACE_TURN_BEGIN;
    BOOL phaseBegin = kind == CJGUI_OWNER_TRACE_PHASE_BEGIN ||
        kind == CJGUI_OWNER_TRACE_OBSERVER_READ_BEGIN || kind == CJGUI_OWNER_TRACE_OBSERVER_FORMAT_BEGIN ||
        kind == CJGUI_OWNER_TRACE_OBSERVER_WRITE_BEGIN || kind == CJGUI_OWNER_TRACE_OBSERVER_FLUSH_BEGIN;
    BOOL turnEnd = kind == CJGUI_OWNER_TRACE_TURN_END;
    BOOL phaseEnd = kind == CJGUI_OWNER_TRACE_PHASE_END ||
        kind == CJGUI_OWNER_TRACE_OBSERVER_READ_END || kind == CJGUI_OWNER_TRACE_OBSERVER_FORMAT_END ||
        kind == CJGUI_OWNER_TRACE_OBSERVER_WRITE_END || kind == CJGUI_OWNER_TRACE_OBSERVER_FLUSH_END;
    if (withWatch) {
        if (turnEnd) CjguiOwnerTraceEndWatch(1, span, managedId, session, turn, request, dispatch, generation);
        if (phaseEnd) CjguiOwnerTraceEndWatch(2, span, managedId, session, turn, request, dispatch, generation);
    }
    uint64_t recorded = CjguiOwnerTraceAppendManaged(kind, session, turn, request, dispatch,
        generation, phase, span, managedId);
    if (withWatch) {
        if (turnBegin) CjguiOwnerTraceBeginWatch(1, recorded, session, turn, request, dispatch, generation, phase, managedId);
        if (phaseBegin) CjguiOwnerTraceBeginWatch(2, recorded, session, turn, request, dispatch, generation, phase, managedId);
    }
    return recorded;
}

void cjgui_internal_renderer_owner_trace_legacy_span(uint64_t session, uint64_t turn,
    uint64_t request, uint64_t generation, uint32_t phase, uint64_t started_ns) {
    if (!CjguiOwnerPhaseTraceEnabled() || started_ns == 0) return;
    uint64_t span = CjguiOwnerTraceAppendAt(CJGUI_OWNER_TRACE_PHASE_BEGIN, session, turn,
        request, 0, generation, phase, 0, started_ns, 0);
    CjguiOwnerTraceAppend(CJGUI_OWNER_TRACE_PHASE_END, session, turn, request,
        0, generation, phase, span);
}

uint64_t cjgui_internal_renderer_owner_trace_dispatch_begin(uint64_t session, uint64_t turn,
    uint64_t request, uint64_t generation, uint32_t phase, uint64_t span) {
    if (!CjguiOwnerPhaseTraceEnabled()) return 0;
    uint64_t dispatch = atomic_fetch_add_explicit(&gCjguiOwnerTraceDispatchSequence, 1,
        memory_order_relaxed) + 1;
    if (request == 0) request = dispatch;
    CjguiOwnerTraceAppend(CJGUI_OWNER_TRACE_DISPATCH_SUBMIT, session, turn, request,
        dispatch, generation, phase, span);
    CjguiOwnerTraceBeginWatch(3, dispatch, session, turn, request, dispatch, generation, phase, UINT64_MAX);
    return dispatch;
}

void cjgui_internal_renderer_owner_trace_set_turn(uint64_t turn) {
    if (!CjguiOwnerPhaseTraceEnabled()) return;
    atomic_store_explicit(&gCjguiOwnerTraceCurrentTurn,
        turn ? turn : UINT64_MAX, memory_order_release);
}

void cjgui_internal_renderer_owner_trace_dispatch_event(uint32_t kind, uint64_t session,
    uint64_t turn, uint64_t request, uint64_t dispatch, uint64_t generation,
    uint32_t phase, uint64_t span) {
    if (dispatch != 0) {
        if (kind == CJGUI_OWNER_TRACE_OWNER_RETURN) CjguiOwnerTraceEndWatch(3, dispatch, UINT64_MAX,
            session, turn, request, dispatch, generation);
        CjguiOwnerTraceAppend(kind, session, turn, request, dispatch, generation, phase, span);
    }
}

// The call sites below already have a synchronous AppKit-main contract. When
// tracing is disabled this is exactly the original dispatch_sync path. When
// enabled, the same block is bracketed with the four existing bounded records;
// turn identity is fixed at submit and generation is read from the live atomic
// session table at submit, main entry/exit and owner return.
static void CjguiOwnerTraceDispatchSync(uint64_t session, uint64_t request,
    uint32_t phase, dispatch_block_t operation) {
    if (!CjguiOwnerPhaseTraceEnabled()) {
        dispatch_sync(dispatch_get_main_queue(), operation);
        return;
    }
    uint64_t generation = UINT64_MAX;
    uint64_t liveGeneration = 0;
    if (cjgui_internal_renderer_coordinate_lifetime(session, &liveGeneration) != 0 && liveGeneration != 0) {
        generation = liveGeneration;
    }
    uint64_t turn = atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn, memory_order_acquire);
    uint64_t dispatch = cjgui_internal_renderer_owner_trace_dispatch_begin(
        session, turn, request, generation, phase, 0);
    if (!dispatch) {
        dispatch_sync(dispatch_get_main_queue(), operation);
        return;
    }
    if (!request) request = dispatch;
    uint64_t callThread = UINT64_MAX;
    if (pthread_threadid_np(NULL, &callThread) != 0 || !callThread) callThread = UINT64_MAX;
    // Watch registration precedes this point. These two fixed records bracket
    // the actual call, without a CPU query or a new sampler watch.
    CjguiOwnerTraceAppendAt(CJGUI_OWNER_TRACE_DISPATCH_SYNC_CALL, session, turn,
        request, dispatch, generation, phase, 0, CjguiOwnerTraceNanoseconds(), callThread);
    dispatch_sync(dispatch_get_main_queue(), ^{
        uint64_t blockEntryAt = CjguiOwnerTraceNanoseconds();
        uint64_t mainGeneration = 0;
        uint64_t mainLifetime = cjgui_internal_renderer_coordinate_lifetime(session, &mainGeneration);
        uint64_t lifetimeReadyAt = CjguiOwnerTraceNanoseconds();
        if (!mainLifetime || !mainGeneration) mainGeneration = UINT64_MAX;
        uint64_t mainThread = UINT64_MAX;
        if (pthread_threadid_np(NULL, &mainThread) != 0 || !mainThread) mainThread = UINT64_MAX;
        // Entry precedes the identity query. It has no validated live generation
        // yet; the dispatch id pairs it with the fresh query result below.
        CjguiOwnerTraceAppendAt(CJGUI_OWNER_TRACE_BOUNDARY, session, turn,
            request, dispatch, UINT64_MAX, 350, 0, blockEntryAt, mainThread);
        CjguiOwnerTraceAppendAt(CJGUI_OWNER_TRACE_BOUNDARY, session, turn,
            request, dispatch, mainGeneration, 351, 0, lifetimeReadyAt, mainThread);
        cjgui_internal_renderer_owner_trace_dispatch_event(CJGUI_OWNER_TRACE_MAIN_ENTER,
            session, turn, request, dispatch, mainGeneration, phase, 0);
        operation();
        uint64_t exitGeneration = 0;
        uint64_t exitLifetime = cjgui_internal_renderer_coordinate_lifetime(session, &exitGeneration);
        if (!exitLifetime || !exitGeneration) exitGeneration = UINT64_MAX;
        cjgui_internal_renderer_owner_trace_dispatch_event(CJGUI_OWNER_TRACE_MAIN_EXIT,
            session, turn, request, dispatch, exitGeneration, phase, 0);
    });
    uint64_t returnedAt = CjguiOwnerTraceNanoseconds();
    uint64_t returnedThread = UINT64_MAX;
    if (pthread_threadid_np(NULL, &returnedThread) != 0 || !returnedThread) returnedThread = UINT64_MAX;
    CjguiOwnerTraceAppendAt(CJGUI_OWNER_TRACE_DISPATCH_SYNC_RETURN, session, turn,
        request, dispatch, generation, phase, 0, returnedAt, returnedThread);
    uint64_t returnGeneration = 0;
    uint64_t returnLifetime = cjgui_internal_renderer_coordinate_lifetime(session, &returnGeneration);
    if (!returnLifetime || !returnGeneration) returnGeneration = UINT64_MAX;
    cjgui_internal_renderer_owner_trace_dispatch_event(CJGUI_OWNER_TRACE_OWNER_RETURN,
        session, turn, request, dispatch, returnGeneration, phase, 0);
}

// text_position_v1 is part of the caret's synchronous owner turn. Capture its
// actual dispatch boundaries in the existing fixed ring, but do not register a
// sampler watch: the four timestamps must distinguish main-queue delay from
// main-thread service without adding watch setup/retirement work to this path.
static void CjguiOwnerTraceTextPositionDispatchSync(uint64_t session, uint64_t request,
    dispatch_block_t operation) {
    if (!CjguiOwnerPhaseTraceEnabled()) {
        dispatch_sync(dispatch_get_main_queue(), operation);
        return;
    }
    uint64_t generation = UINT64_MAX, liveGeneration = 0;
    if (cjgui_internal_renderer_coordinate_lifetime(session, &liveGeneration) != 0 && liveGeneration != 0)
        generation = liveGeneration;
    uint64_t turn = atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn, memory_order_acquire);
    uint64_t dispatch = atomic_fetch_add_explicit(&gCjguiOwnerTraceDispatchSequence, 1,
        memory_order_relaxed) + 1;
    uint64_t callThread = UINT64_MAX;
    if (pthread_threadid_np(NULL, &callThread) != 0 || !callThread) callThread = UINT64_MAX;
    CjguiOwnerTraceAppendAt(CJGUI_OWNER_TRACE_DISPATCH_SYNC_CALL, session, turn,
        request, dispatch, generation, CJGUI_OWNER_PHASE_NATIVE_TEXT_POSITION, 0,
        CjguiOwnerTraceNanoseconds(), callThread);
    dispatch_sync(dispatch_get_main_queue(), ^{
        uint64_t mainGeneration = 0;
        uint64_t mainLifetime = cjgui_internal_renderer_coordinate_lifetime(session, &mainGeneration);
        if (!mainLifetime || !mainGeneration) mainGeneration = UINT64_MAX;
        uint64_t mainThread = UINT64_MAX;
        if (pthread_threadid_np(NULL, &mainThread) != 0 || !mainThread) mainThread = UINT64_MAX;
        CjguiOwnerTraceAppendAt(CJGUI_OWNER_TRACE_MAIN_ENTER, session, turn,
            request, dispatch, mainGeneration, CJGUI_OWNER_PHASE_NATIVE_TEXT_POSITION, 0,
            CjguiOwnerTraceNanoseconds(), mainThread);
        operation();
        uint64_t exitGeneration = 0;
        uint64_t exitLifetime = cjgui_internal_renderer_coordinate_lifetime(session, &exitGeneration);
        if (!exitLifetime || !exitGeneration) exitGeneration = UINT64_MAX;
        CjguiOwnerTraceAppendAt(CJGUI_OWNER_TRACE_MAIN_EXIT, session, turn,
            request, dispatch, exitGeneration, CJGUI_OWNER_PHASE_NATIVE_TEXT_POSITION, 0,
            CjguiOwnerTraceNanoseconds(), mainThread);
    });
    uint64_t returnThread = UINT64_MAX;
    if (pthread_threadid_np(NULL, &returnThread) != 0 || !returnThread) returnThread = UINT64_MAX;
    uint64_t returnGeneration = 0;
    uint64_t returnLifetime = cjgui_internal_renderer_coordinate_lifetime(session, &returnGeneration);
    if (!returnLifetime || !returnGeneration) returnGeneration = UINT64_MAX;
    CjguiOwnerTraceAppendAt(CJGUI_OWNER_TRACE_DISPATCH_SYNC_RETURN, session, turn,
        request, dispatch, returnGeneration, CJGUI_OWNER_PHASE_NATIVE_TEXT_POSITION, 0,
        CjguiOwnerTraceNanoseconds(), returnThread);
}

uint64_t cjgui_internal_renderer_owner_trace_ns(void) {
    if (!CjguiOwnerPhaseTraceEnabled()) return 0;
    return CjguiOwnerTraceNanoseconds();
}
uint64_t cjgui_internal_renderer_owner_clock_ns(void) { return CjguiOwnerTraceNanoseconds(); }
uint64_t cjgui_internal_renderer_owner_thread_cpu_ns(void) {
    BOOL valid = NO;
    return CjguiOwnerTraceThreadCpu(NULL, &valid);
}

static void CjguiOwnerTraceWriteRecord(CjguiOwnerTraceRecord *slot) {
    uint64_t recordSequence = slot->sequence;
    uint64_t monoNs = slot->monoNs, cpuNs = slot->cpuNs;
    uint64_t session = slot->session, turn = slot->turn, request = slot->request;
    uint64_t dispatch = slot->dispatch, generation = slot->generation, span = slot->span;
    uint64_t threadId = slot->threadId;
    uint64_t managedThreadId = slot->managedThreadId;
    uint64_t ownerConsumeTurn = slot->ownerConsumeTurn;
    uint64_t ownerConsumeGeneration = slot->ownerConsumeGeneration;
    uint64_t ownerConsumeThreadId = slot->ownerConsumeThreadId;
    uint32_t kind = slot->kind, phase = slot->phase;
    uint8_t cpuValid = slot->cpuValid;
    char sessionText[32], turnText[32], requestText[32], dispatchText[32];
    char generationText[32], spanText[32], threadText[32], managedThreadText[32], cpuText[32];
    char requestTurnText[32], requestGenerationText[32];
    char ownerTurnText[32], ownerGenerationText[32], ownerThreadText[32];
    fprintf(stderr, "CJGUI_OWNER_TRACE v=1 seq=%llu kind=%s pid=%d session=%s turn=%s request=%s dispatch=%s generation=%s span=%s phase=%s phase_id=%u mono_ns=%llu tid=%s managed_tid=%s cpu_ns=%s cpu_valid=%u request_turn=%s request_generation=%s owner_consume_turn=%s owner_consume_generation=%s owner_consume_tid=%s\n",
        (unsigned long long)recordSequence, CjguiOwnerTraceKindName(kind), getpid(),
        CjguiOwnerTraceId(session, sessionText), CjguiOwnerTraceId(turn, turnText),
        CjguiOwnerTraceId(request, requestText), CjguiOwnerTraceId(dispatch, dispatchText),
        CjguiOwnerTraceId(generation, generationText), CjguiOwnerTraceId(span, spanText),
        CjguiOwnerTracePhaseName(phase), phase,
        (unsigned long long)monoNs, CjguiOwnerTraceId(threadId, threadText),
        CjguiOwnerTraceId(managedThreadId, managedThreadText),
        cpuValid ? CjguiOwnerTraceId(cpuNs, cpuText) : "unknown", cpuValid,
        CjguiOwnerTraceId(turn, requestTurnText),
        CjguiOwnerTraceId(generation, requestGenerationText),
        CjguiOwnerTraceId(ownerConsumeTurn, ownerTurnText),
        CjguiOwnerTraceId(ownerConsumeGeneration, ownerGenerationText),
        CjguiOwnerTraceId(ownerConsumeThreadId, ownerThreadText));
}

static void CjguiOwnerTraceWriteStackSample(CjguiOwnerTraceStackSample *sample) {
    char sessionText[32], turnText[32], requestText[32], dispatchText[32];
    char generationText[32], spanText[32], threadText[32], expectedThreadText[32], cpuText[32], pauseText[32];
    char frameText[CJGUI_OWNER_TRACE_SAMPLE_MAX_FRAMES][32];
    char imageBaseText[CJGUI_OWNER_TRACE_SAMPLE_MAX_FRAMES][32];
    char symbolAddressText[CJGUI_OWNER_TRACE_SAMPLE_MAX_FRAMES][32];
    char infoStartedText[32], infoFinishedText[32];
    char registerPauseStartedText[32], registerPauseFinishedText[32];
    char registerStateStartedText[32], registerStateFinishedText[32];
    char imagePathHex[CJGUI_OWNER_TRACE_SAMPLE_MAX_FRAMES][257];
    char symbolHex[CJGUI_OWNER_TRACE_SAMPLE_MAX_FRAMES][257];
    int32_t symbolStatus[CJGUI_OWNER_TRACE_SAMPLE_MAX_FRAMES] = {-1, -1};
    BOOL imagePathTruncated[CJGUI_OWNER_TRACE_SAMPLE_MAX_FRAMES] = {NO, NO};
    BOOL symbolTruncated[CJGUI_OWNER_TRACE_SAMPLE_MAX_FRAMES] = {NO, NO};
    CjguiOwnerTraceId(sample->infoStartedNs, infoStartedText);
    CjguiOwnerTraceId(sample->infoFinishedNs, infoFinishedText);
    CjguiOwnerTraceId(sample->registerPauseStartedNs, registerPauseStartedText);
    CjguiOwnerTraceId(sample->registerPauseFinishedNs, registerPauseFinishedText);
    CjguiOwnerTraceId(sample->registerStateStartedNs, registerStateStartedText);
    CjguiOwnerTraceId(sample->registerStateFinishedNs, registerStateFinishedText);
    for (uint32_t index = 0; index < CJGUI_OWNER_TRACE_SAMPLE_MAX_FRAMES; index++) {
        uint64_t imageBase = UINT64_MAX, symbolAddress = UINT64_MAX;
        if (index < sample->frameCount)
            snprintf(frameText[index], sizeof(frameText[index]), "0x%llx", (unsigned long long)sample->frames[index]);
        else snprintf(frameText[index], sizeof(frameText[index]), "unknown");
        snprintf(imageBaseText[index], sizeof(imageBaseText[index]), "unknown");
        snprintf(imagePathHex[index], sizeof(imagePathHex[index]), "unknown");
        snprintf(symbolAddressText[index], sizeof(symbolAddressText[index]), "unknown");
        snprintf(symbolHex[index], sizeof(symbolHex[index]), "unknown");
        if (index < sample->frameCount) {
            Dl_info symbol = {0};
            if (dladdr((const void *)(uintptr_t)sample->frames[index], &symbol) != 0) {
                symbolStatus[index] = 0;
                if (symbol.dli_fbase) imageBase = (uint64_t)(uintptr_t)symbol.dli_fbase;
                if (symbol.dli_saddr) symbolAddress = (uint64_t)(uintptr_t)symbol.dli_saddr;
                if (symbol.dli_fname)
                    CjguiOwnerTraceHexText(symbol.dli_fname, imagePathHex[index],
                        sizeof(imagePathHex[index]), &imagePathTruncated[index]);
                if (symbol.dli_sname)
                    CjguiOwnerTraceHexText(symbol.dli_sname, symbolHex[index],
                        sizeof(symbolHex[index]), &symbolTruncated[index]);
            }
        }
        CjguiOwnerTraceId(imageBase, imageBaseText[index]);
        CjguiOwnerTraceId(symbolAddress, symbolAddressText[index]);
    }
    const char *frameModel = sample->frameModel == 1 ? "register_pc_lr" :
        sample->frameModel == 2 ? "register_pc_only" : "unknown";
    uint32_t frameLimit = sample->frameModel == 1 ? 2 : sample->frameModel == 2 ? 1 : 0;
    fprintf(stderr, "CJGUI_OWNER_TRACE v=1 kind=stack_sample sample_seq=%llu pid=%llu session=%s turn=%s request=%s dispatch=%s generation=%s span=%s phase_id=%u role=%s tid=%s expected_tid=%s started_ns=%llu finished_ns=%llu sample_wall_ns=%llu info_started_ns=%s info_finished_ns=%s info_interval_valid=%u register_pause_started_ns=%s register_pause_finished_ns=%s register_pause_interval_valid=%u register_state_started_ns=%s register_state_finished_ns=%s register_state_interval_valid=%u target_pause_ns=%s target_pause_valid=%u run_state=%d cpu_ns=%s cpu_valid=%u pc=0x%llx fp=0x%llx sp=0x%llx info_status=%d suspend_status=%d state_status=%d resume_status=%d frame_status=%d frame_model=%s frame_limit=%u frame_complete=0 frame_count=%u frame0=%s frame0_image_base=%s frame0_image_path_hex=%s frame0_image_path_truncated=%u frame0_symbol_hex=%s frame0_symbol_truncated=%u frame0_symbol_address=%s frame0_symbol_status=%d frame1=%s frame1_image_base=%s frame1_image_path_hex=%s frame1_image_path_truncated=%u frame1_symbol_hex=%s frame1_symbol_truncated=%u frame1_symbol_address=%s frame1_symbol_status=%d observed_tid=%llu watch_lease=%llu retired_ns=%llu sample_scope=%s\n",
        (unsigned long long)sample->sequence,
        (unsigned long long)sample->pid,
        CjguiOwnerTraceId(sample->session, sessionText), CjguiOwnerTraceId(sample->turn, turnText),
        CjguiOwnerTraceId(sample->request, requestText), CjguiOwnerTraceId(sample->dispatch, dispatchText),
        CjguiOwnerTraceId(sample->generation, generationText), CjguiOwnerTraceId(sample->span, spanText),
        sample->phase, sample->role == 1 ? "owner" : "appkit",
        CjguiOwnerTraceId(sample->threadId, threadText),
        CjguiOwnerTraceId(sample->expectedThreadId, expectedThreadText),
        (unsigned long long)sample->startedNs, (unsigned long long)sample->finishedNs,
        (unsigned long long)(sample->finishedNs >= sample->startedNs ? sample->finishedNs - sample->startedNs : 0),
        sample->infoIntervalValid ? infoStartedText : "unknown",
        sample->infoIntervalValid ? infoFinishedText : "unknown", sample->infoIntervalValid,
        sample->registerPauseIntervalValid ? registerPauseStartedText : "unknown",
        sample->registerPauseIntervalValid ? registerPauseFinishedText : "unknown",
        sample->registerPauseIntervalValid,
        sample->registerStateIntervalValid ? registerStateStartedText : "unknown",
        sample->registerStateIntervalValid ? registerStateFinishedText : "unknown",
        sample->registerStateIntervalValid,
        sample->pauseValid ? CjguiOwnerTraceId(sample->suspendNs, pauseText) : "unknown",
        sample->pauseValid, sample->runState,
        sample->cpuValid ? CjguiOwnerTraceId(sample->cpuNs, cpuText) : "unknown", sample->cpuValid,
        (unsigned long long)sample->pc, (unsigned long long)sample->fp, (unsigned long long)sample->sp,
        sample->infoStatus, sample->suspendStatus, sample->stateStatus, sample->resumeStatus,
        sample->frameStatus, frameModel, frameLimit, sample->frameCount,
        frameText[0], imageBaseText[0], imagePathHex[0], imagePathTruncated[0],
        symbolHex[0], symbolTruncated[0], symbolAddressText[0], symbolStatus[0],
        frameText[1], imageBaseText[1], imagePathHex[1], imagePathTruncated[1],
        symbolHex[1], symbolTruncated[1], symbolAddressText[1], symbolStatus[1],
        (unsigned long long)sample->observedThreadId, (unsigned long long)sample->watchLease,
        (unsigned long long)sample->retiredNs,
        sample->retiredNs == UINT64_MAX || !sample->registerStateIntervalValid ? "unknown" :
        !sample->retiredNs || sample->registerStateFinishedNs <= sample->retiredNs ? "live" :
        sample->registerStateStartedNs >= sample->retiredNs ? "late" : "straddling");
}

static BOOL CjguiOwnerTracePeekRetainedSequence(CjguiOwnerTraceRecord *records, uint64_t ordinal,
    uint32_t capacity, uint64_t *outSequence) {
    CjguiOwnerTraceRecord *slot = &records[ordinal % capacity];
    bool expected = false;
    if (!atomic_compare_exchange_strong_explicit(&slot->writing, &expected, true,
            memory_order_acquire, memory_order_relaxed)) return NO;
    BOOL valid = atomic_load_explicit(&slot->publishedSequence, memory_order_acquire) == ordinal + 1;
    if (valid) *outSequence = slot->sequence;
    atomic_store_explicit(&slot->writing, false, memory_order_release);
    return valid;
}

static void CjguiOwnerTraceWriteRetainedRecord(CjguiOwnerTraceRecord *records, uint64_t ordinal,
    uint32_t capacity, uint64_t sequence, uint64_t firstMainSequence, uint64_t slowFirst, uint64_t slowLast) {
    CjguiOwnerTraceRecord *slot = &records[ordinal % capacity];
    bool expected = false;
    if (!atomic_compare_exchange_strong_explicit(&slot->writing, &expected, true,
            memory_order_acquire, memory_order_relaxed)) return;
    if (atomic_load_explicit(&slot->publishedSequence, memory_order_acquire) == ordinal + 1 &&
        slot->sequence < firstMainSequence &&
        !(slowFirst > 0 && slot->sequence >= slowFirst && slot->sequence <= slowLast) &&
        slot->sequence == sequence) {
        CjguiOwnerTraceWriteRecord(slot);
    }
    atomic_store_explicit(&slot->writing, false, memory_order_release);
}

static void CjguiOwnerTraceExportRetainedRecords(uint64_t firstMainSequence,
    uint64_t slowFirst, uint64_t slowLast, uint64_t startupCount, uint64_t activityFirstOrdinal,
    uint64_t activityNext, uint64_t criticalFirstOrdinal, uint64_t criticalNext) {
    uint64_t cursors[3] = {0, activityFirstOrdinal, criticalFirstOrdinal};
    uint64_t limits[3] = {startupCount, activityNext, criticalNext};
    uint32_t capacities[3] = {CJGUI_OWNER_TRACE_STARTUP_CAPACITY,
        CJGUI_OWNER_TRACE_ACTIVITY_CAPACITY, CJGUI_OWNER_TRACE_CRITICAL_CAPACITY};
    CjguiOwnerTraceRecord *rings[3] = {gCjguiOwnerTraceStartupRecords,
        gCjguiOwnerTraceActivityRecords, gCjguiOwnerTraceCriticalRecords};
    while (YES) {
        uint64_t nextSequence[3] = {UINT64_MAX, UINT64_MAX, UINT64_MAX};
        for (uint32_t ring = 0; ring < 3; ring++) {
            while (cursors[ring] < limits[ring] &&
                !CjguiOwnerTracePeekRetainedSequence(rings[ring], cursors[ring], capacities[ring],
                    &nextSequence[ring])) cursors[ring]++;
        }
        uint64_t smallest = MIN(nextSequence[0], MIN(nextSequence[1], nextSequence[2]));
        if (smallest == UINT64_MAX) break;
        BOOL wroteSequence = NO;
        for (uint32_t ring = 0; ring < 3; ring++) {
            if (nextSequence[ring] != smallest) continue;
            if (!wroteSequence) {
                CjguiOwnerTraceWriteRetainedRecord(rings[ring], cursors[ring], capacities[ring],
                    smallest, firstMainSequence, slowFirst, slowLast);
                wroteSequence = YES;
            }
            cursors[ring]++;
        }
    }
}

void cjgui_internal_renderer_owner_trace_export(void) {
    CjguiOwnerTraceEnsureExitExport();
    if (!atomic_load_explicit(&gCjguiOwnerTraceEnabledObserved, memory_order_acquire)) return;
    bool expected = false;
    if (!atomic_compare_exchange_strong_explicit(&gCjguiOwnerTraceExportStarted, &expected, true,
            memory_order_acq_rel, memory_order_relaxed)) return;
    pthread_mutex_lock(&gCjguiOwnerTraceExportLock);
    gCjguiOwnerTraceExportThread = pthread_self();
    atomic_store(&gCjguiOwnerTraceExportState, 1);
    pthread_mutex_unlock(&gCjguiOwnerTraceExportLock);
    uint64_t exportStarted = CjguiOwnerTraceNanoseconds();
    CjguiOwnerTraceAppend(CJGUI_OWNER_TRACE_EXPORT, UINT64_MAX, UINT64_MAX, 0,
        0, 0, CJGUI_OWNER_PHASE_UNKNOWN, 0);
    uint64_t last = atomic_load_explicit(&gCjguiOwnerTraceNextSequence, memory_order_acquire);
    uint64_t first = last > CJGUI_OWNER_TRACE_CAPACITY ? last - CJGUI_OWNER_TRACE_CAPACITY + 1 : 1;
    uint64_t slowFirst = atomic_load_explicit(&gCjguiOwnerTraceSlowFirstSequence, memory_order_acquire);
    uint64_t slowLast = atomic_load_explicit(&gCjguiOwnerTraceSlowLastSequence, memory_order_acquire);
    uint64_t slowBeforeRingEnd = first > 0 ? first - 1 : 0;
    uint64_t startupCount = atomic_load_explicit(&gCjguiOwnerTraceStartupCount, memory_order_acquire);
    if (startupCount > CJGUI_OWNER_TRACE_STARTUP_CAPACITY) startupCount = CJGUI_OWNER_TRACE_STARTUP_CAPACITY;
    uint64_t activityNext = atomic_load_explicit(&gCjguiOwnerTraceActivityNext, memory_order_acquire);
    uint64_t activityFirstOrdinal = activityNext > CJGUI_OWNER_TRACE_ACTIVITY_CAPACITY ?
        activityNext - CJGUI_OWNER_TRACE_ACTIVITY_CAPACITY : 0;
    uint64_t criticalNext = atomic_load_explicit(&gCjguiOwnerTraceCriticalNext, memory_order_acquire);
    uint64_t criticalFirstOrdinal = criticalNext > CJGUI_OWNER_TRACE_CRITICAL_CAPACITY ?
        criticalNext - CJGUI_OWNER_TRACE_CRITICAL_CAPACITY : 0;
    CjguiOwnerTraceExportRetainedRecords(first, slowFirst, slowLast, startupCount,
        activityFirstOrdinal, activityNext, criticalFirstOrdinal, criticalNext);
    if (slowLast > 0 && slowFirst > 0) {
        uint64_t slowEnd = slowLast < slowBeforeRingEnd ? slowLast : slowBeforeRingEnd;
        for (uint64_t sequence = slowFirst; sequence <= slowEnd; sequence++) {
            CjguiOwnerTraceRecord *slot = &gCjguiOwnerTraceSlowRecords[
                (sequence - 1) % CJGUI_OWNER_TRACE_SLOW_CAPACITY];
            bool expected = false;
            if (!atomic_compare_exchange_strong_explicit(&slot->writing, &expected, true,
                    memory_order_acquire, memory_order_relaxed)) continue;
            if (atomic_load_explicit(&slot->publishedSequence, memory_order_acquire) == sequence)
                CjguiOwnerTraceWriteRecord(slot);
            atomic_store_explicit(&slot->writing, false, memory_order_release);
        }
    }
    for (uint64_t sequence = first; sequence <= last; sequence++) {
        CjguiOwnerTraceRecord *slot = &gCjguiOwnerTraceRecords[(sequence - 1) % CJGUI_OWNER_TRACE_CAPACITY];
        bool expected = false;
        if (!atomic_compare_exchange_strong_explicit(&slot->writing, &expected, true,
                memory_order_acquire, memory_order_relaxed)) continue;
        if (atomic_load_explicit(&slot->publishedSequence, memory_order_acquire) == sequence) {
            CjguiOwnerTraceWriteRecord(slot);
        }
        atomic_store_explicit(&slot->writing, false, memory_order_release);
    }
    uint64_t sampleLast = atomic_load_explicit(&gCjguiOwnerTraceSampleSequence, memory_order_acquire);
    uint64_t sampleFirst = sampleLast > CJGUI_OWNER_TRACE_SAMPLE_CAPACITY ?
        sampleLast - CJGUI_OWNER_TRACE_SAMPLE_CAPACITY + 1 : (sampleLast ? 1 : 0);
    uint64_t slowSampleFirst = atomic_load_explicit(&gCjguiOwnerTraceSlowSampleFirst, memory_order_acquire);
    uint64_t slowSampleLast = atomic_load_explicit(&gCjguiOwnerTraceSlowSampleLast, memory_order_acquire);
    if (slowSampleFirst > 0 && slowSampleLast >= slowSampleFirst) {
        for (uint64_t sequence = slowSampleFirst; sequence <= slowSampleLast; sequence++) {
            CjguiOwnerTraceStackSample *slot = &gCjguiOwnerTraceSlowStackSamples[
                (sequence - 1) % CJGUI_OWNER_TRACE_SAMPLE_CAPACITY];
            bool expected = false;
            if (!atomic_compare_exchange_strong_explicit(&slot->writing, &expected, true,
                    memory_order_acquire, memory_order_relaxed)) continue;
            if (atomic_load_explicit(&slot->publishedSequence, memory_order_acquire) == sequence)
                CjguiOwnerTraceWriteStackSample(slot);
            atomic_store_explicit(&slot->writing, false, memory_order_release);
        }
    }
    for (uint64_t sequence = sampleFirst; sequence > 0 && sequence <= sampleLast; sequence++) {
        CjguiOwnerTraceStackSample *slot = &gCjguiOwnerTraceStackSamples[
            (sequence - 1) % CJGUI_OWNER_TRACE_SAMPLE_CAPACITY];
        bool expected = false;
        if (!atomic_compare_exchange_strong_explicit(&slot->writing, &expected, true,
                memory_order_acquire, memory_order_relaxed)) continue;
        if (atomic_load_explicit(&slot->publishedSequence, memory_order_acquire) == sequence &&
            !CjguiOwnerTraceSlowSampleHasSequence(sequence))
            CjguiOwnerTraceWriteStackSample(slot);
        atomic_store_explicit(&slot->writing, false, memory_order_release);
    }
    fflush(stderr);
    uint64_t afterRows = CjguiOwnerTraceNanoseconds();
    uint64_t exportNs = afterRows >= exportStarted ? afterRows - exportStarted : 0;
    uint64_t firstNs = atomic_load_explicit(&gCjguiOwnerTraceFirstNs, memory_order_relaxed);
    uint64_t overwritten = last > CJGUI_OWNER_TRACE_CAPACITY ? last - CJGUI_OWNER_TRACE_CAPACITY : 0;
    uint64_t dropped = atomic_load_explicit(&gCjguiOwnerTraceDropped, memory_order_relaxed);
    uint64_t slowTurn = atomic_load_explicit(&gCjguiOwnerTraceSlowTurn, memory_order_relaxed);
    uint64_t slowDropped = atomic_load_explicit(&gCjguiOwnerTraceSlowDropped, memory_order_relaxed);
    uint64_t sampleDropped = atomic_load_explicit(&gCjguiOwnerTraceSampleDropped, memory_order_relaxed);
    uint64_t sampleOverwritten = atomic_load_explicit(&gCjguiOwnerTraceSampleOverwritten, memory_order_relaxed);
    uint64_t slowSampleCount = atomic_load_explicit(&gCjguiOwnerTraceSlowSampleCount, memory_order_relaxed);
    uint64_t slowSampleDropped = atomic_load_explicit(&gCjguiOwnerTraceSlowSampleDropped, memory_order_relaxed);
    uint64_t slowCaptureStarted = atomic_load_explicit(&gCjguiOwnerTraceSlowCaptureStartedNs, memory_order_relaxed);
    uint64_t slowCaptureFinished = atomic_load_explicit(&gCjguiOwnerTraceSlowCaptureFinishedNs, memory_order_relaxed);
    uint64_t slowCaptureCost = atomic_load_explicit(&gCjguiOwnerTraceSlowCaptureCostNs, memory_order_relaxed);
    uint64_t samplePauseNs = atomic_load_explicit(&gCjguiOwnerTraceSamplePauseNs, memory_order_relaxed);
    uint64_t samplePauseUnknown = atomic_load_explicit(&gCjguiOwnerTraceSamplePauseUnknown, memory_order_relaxed);
    uint64_t watchDropped = atomic_load_explicit(&gCjguiOwnerTraceWatchDropped, memory_order_relaxed);
    uint64_t criticalFirst = atomic_load_explicit(&gCjguiOwnerTraceCriticalFirstSequence, memory_order_relaxed);
    uint64_t criticalLast = atomic_load_explicit(&gCjguiOwnerTraceCriticalLastSequence, memory_order_relaxed);
    uint64_t criticalOverwritten = atomic_load_explicit(&gCjguiOwnerTraceCriticalOverwritten, memory_order_relaxed);
    uint64_t criticalDropped = atomic_load_explicit(&gCjguiOwnerTraceCriticalDropped, memory_order_relaxed);
    uint64_t startupStored = atomic_load_explicit(&gCjguiOwnerTraceStartupCount, memory_order_relaxed);
    if (startupStored > CJGUI_OWNER_TRACE_STARTUP_CAPACITY) startupStored = CJGUI_OWNER_TRACE_STARTUP_CAPACITY;
    uint64_t startupFirstSummary = atomic_load_explicit(&gCjguiOwnerTraceStartupFirstSequence, memory_order_relaxed);
    uint64_t startupLastSummary = atomic_load_explicit(&gCjguiOwnerTraceStartupLastSequence, memory_order_relaxed);
    uint64_t startupDropped = atomic_load_explicit(&gCjguiOwnerTraceStartupDropped, memory_order_relaxed);
    uint8_t startupState = atomic_load_explicit(&gCjguiOwnerTraceStartupState, memory_order_relaxed);
    uint64_t activityFirst = atomic_load_explicit(&gCjguiOwnerTraceActivityFirstSequence, memory_order_relaxed);
    uint64_t activityLast = atomic_load_explicit(&gCjguiOwnerTraceActivityLastSequence, memory_order_relaxed);
    uint64_t activityOverwritten = atomic_load_explicit(&gCjguiOwnerTraceActivityOverwritten, memory_order_relaxed);
    uint64_t activityDropped = atomic_load_explicit(&gCjguiOwnerTraceActivityDropped, memory_order_relaxed);
    uint64_t activityCaptureCount = atomic_load_explicit(&gCjguiOwnerTraceActivityCaptureCount, memory_order_relaxed);
    uint64_t activityCopyNs = atomic_load_explicit(&gCjguiOwnerTraceActivityCopyNs, memory_order_relaxed);
    uint64_t activitySourceMissing = atomic_load_explicit(&gCjguiOwnerTraceActivitySourceMissing, memory_order_relaxed);
    uint64_t summaryStarted = CjguiOwnerTraceNanoseconds();
    fprintf(stderr, "CJGUI_OWNER_TRACE v=1 kind=summary capacity=%u first_seq=%llu last_seq=%llu overwritten=%llu dropped=%llu export_ns=%llu process_wall_ns=%llu slow_capacity=%u slow_turn=%s slow_first_seq=%llu slow_last_seq=%llu slow_dropped=%llu slow_capture_started_ns=%s slow_capture_finished_ns=%s slow_capture_cost_ns=%s critical_capacity=%u critical_first_seq=%llu critical_last_seq=%llu critical_overwritten=%llu critical_dropped=%llu startup_capacity=%u startup_state=%u startup_first_seq=%llu startup_last_seq=%llu startup_records=%llu startup_dropped=%llu activity_capacity=%u activity_first_seq=%llu activity_last_seq=%llu activity_overwritten=%llu activity_dropped=%llu activity_capture_count=%llu activity_copy_ns=%llu activity_source_missing=%llu stack_sample_capacity=%u stack_sample_first=%llu stack_sample_last=%llu stack_sample_overwritten=%llu stack_sample_dropped=%llu slow_sample_first=%llu slow_sample_last=%llu slow_sample_count=%llu slow_sample_dropped=%llu stack_sample_pause_ns=%llu stack_sample_pause_unknown=%llu stack_watch_dropped=%llu stack_samples_enabled=%u atexit_registered=%u\n",
        CJGUI_OWNER_TRACE_CAPACITY, (unsigned long long)first, (unsigned long long)last,
        (unsigned long long)overwritten, (unsigned long long)dropped,
        (unsigned long long)exportNs,
        afterRows >= firstNs && firstNs ? (unsigned long long)(afterRows - firstNs) : 0ULL,
        CJGUI_OWNER_TRACE_SLOW_CAPACITY,
        slowTurn == UINT64_MAX ? "unknown" : CjguiOwnerTraceId(slowTurn, (char[32]){0}),
        (unsigned long long)slowFirst, (unsigned long long)slowLast, (unsigned long long)slowDropped,
        CjguiOwnerTraceId(slowCaptureStarted, (char[32]){0}),
        CjguiOwnerTraceId(slowCaptureFinished, (char[32]){0}),
        CjguiOwnerTraceId(slowCaptureCost, (char[32]){0}),
        CJGUI_OWNER_TRACE_CRITICAL_CAPACITY, (unsigned long long)criticalFirst,
        (unsigned long long)criticalLast, (unsigned long long)criticalOverwritten,
        (unsigned long long)criticalDropped, CJGUI_OWNER_TRACE_STARTUP_CAPACITY, startupState,
        (unsigned long long)startupFirstSummary, (unsigned long long)startupLastSummary,
        (unsigned long long)startupStored, (unsigned long long)startupDropped,
        CJGUI_OWNER_TRACE_ACTIVITY_CAPACITY, (unsigned long long)activityFirst,
        (unsigned long long)activityLast, (unsigned long long)activityOverwritten,
        (unsigned long long)activityDropped, (unsigned long long)activityCaptureCount,
        (unsigned long long)activityCopyNs, (unsigned long long)activitySourceMissing,
        CJGUI_OWNER_TRACE_SAMPLE_CAPACITY, (unsigned long long)sampleFirst,
        (unsigned long long)sampleLast, (unsigned long long)sampleOverwritten,
        (unsigned long long)sampleDropped,
        (unsigned long long)slowSampleFirst, (unsigned long long)slowSampleLast,
        (unsigned long long)slowSampleCount, (unsigned long long)slowSampleDropped,
        (unsigned long long)samplePauseNs,
        (unsigned long long)samplePauseUnknown,
        (unsigned long long)watchDropped, CjguiOwnerTraceThreadSamplesEnabled(),
        atomic_load_explicit(&gCjguiOwnerTraceExitHandlerRegistered, memory_order_acquire));
    fflush(stderr);
    uint64_t afterSummary = CjguiOwnerTraceNanoseconds();
    uint64_t measuredExportNs = afterSummary >= exportStarted ? afterSummary - exportStarted : 0;
    uint64_t measuredProcessWallNs = afterSummary >= firstNs && firstNs ? afterSummary - firstNs : 0;
    uint64_t summaryWriteFlushNs = afterSummary >= summaryStarted ? afterSummary - summaryStarted : 0;
    fprintf(stderr, "CJGUI_OWNER_TRACE v=1 kind=export stage=end export_ns=%llu process_wall_ns=%llu summary_write_flush_ns=%llu final_footer_flush_included=0 export_scope=%s resume_unresolved=%llu\n",
        (unsigned long long)measuredExportNs, (unsigned long long)measuredProcessWallNs,
        (unsigned long long)summaryWriteFlushNs,
        atomic_load(&gCjguiOwnerTraceFinalExport) ? "final" : "snapshot",
        (unsigned long long)atomic_load(&gCjguiOwnerTraceResumeUnresolved));
    int flushed = fflush(stderr);
    BOOL complete = flushed == 0 && !ferror(stderr) && !atomic_load(&gCjguiOwnerTraceResumeUnresolved);
    if (!complete) {
        const char failure[] = "CJGUI_OWNER_TRACE_EXPORT_FAILED reason=write_flush_or_unresolved_resume\n";
        (void)write(STDERR_FILENO, failure, sizeof(failure) - 1);
    }
    pthread_mutex_lock(&gCjguiOwnerTraceExportLock);
    atomic_store(&gCjguiOwnerTraceExportState, complete ? 2 : 3);
    pthread_cond_broadcast(&gCjguiOwnerTraceExportCondition);
    pthread_mutex_unlock(&gCjguiOwnerTraceExportLock);
}

uint8_t cjgui_internal_renderer_finalize_owner_trace(void) {
    CjguiOwnerTraceStopSampler();
    if (!CjguiOwnerPhaseTraceEnabled() && !atomic_load(&gCjguiOwnerTraceEnabledObserved)) return 2;
    if (!atomic_load(&gCjguiOwnerTraceExportStarted)) atomic_store(&gCjguiOwnerTraceFinalExport, true);
    cjgui_internal_renderer_owner_trace_export();
    pthread_mutex_lock(&gCjguiOwnerTraceExportLock);
    while (atomic_load(&gCjguiOwnerTraceExportState) <= 1) {
        if (atomic_load(&gCjguiOwnerTraceExportState) == 1 &&
            pthread_equal(pthread_self(), gCjguiOwnerTraceExportThread)) {
            pthread_mutex_unlock(&gCjguiOwnerTraceExportLock);
            return 3; // reentrant finalizer cannot claim the exporter is done
        }
        pthread_cond_wait(&gCjguiOwnerTraceExportCondition, &gCjguiOwnerTraceExportLock);
    }
    uint8_t state = atomic_load(&gCjguiOwnerTraceExportState);
    BOOL final = atomic_load(&gCjguiOwnerTraceFinalExport);
    pthread_mutex_unlock(&gCjguiOwnerTraceExportLock);
    if (!final && state == 2) {
        // The running snapshot is complete, but it is not the cleanup
        // terminal. Publish that failure before a cleanup ticket can read
        // the terminal; otherwise it would report the old snapshot's done.
        pthread_mutex_lock(&gCjguiOwnerTraceExportLock);
        atomic_store(&gCjguiOwnerTraceExportState, 3);
        pthread_cond_broadcast(&gCjguiOwnerTraceExportCondition);
        pthread_mutex_unlock(&gCjguiOwnerTraceExportLock);
        const char failure[] = "CJGUI_OWNER_TRACE_EXPORT_FAILED reason=prior_running_snapshot_not_final\n";
        (void)write(STDERR_FILENO, failure, sizeof(failure) - 1);
        return 3;
    }
    return state == 2 ? 2 : 3;
}

static void CjguiTraceOwnerCpuSpan(uint64_t session, const char *name,
                                  uint64_t started, uint64_t cpuStarted) {
    (void)session; (void)name; (void)started; (void)cpuStarted;
}
static void CjguiTraceOwnerPhase(uint64_t session, const char *name, uint64_t started) {
    if (!started) return;
    uint64_t turn = atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn, memory_order_acquire);
    uint32_t phase = CJGUI_OWNER_PHASE_UNKNOWN;
    if (name && strstr(name, "pump.before_idle")) phase = CJGUI_OWNER_PHASE_PUMP_BEFORE_IDLE;
    else if (name && strstr(name, "pump.after_idle")) phase = CJGUI_OWNER_PHASE_PUMP_AFTER_IDLE;
    else if (name && strstr(name, "focus.prepare_inactive_text")) phase = CJGUI_OWNER_PHASE_FOCUS_INACTIVE_TEXT;
    else if (name && strstr(name, "focus.proxy_properties.container_flags")) phase = CJGUI_OWNER_PHASE_FOCUS_PROXY_FLAGS;
    else if (name && strstr(name, "focus.proxy_properties.color")) phase = CJGUI_OWNER_PHASE_FOCUS_PROXY_COLOR;
    else if (name && strstr(name, "focus.proxy_properties.body")) phase = CJGUI_OWNER_PHASE_FOCUS_PROXY_BODY;
    else if (name && strstr(name, "focus.proxy_properties.selection")) phase = CJGUI_OWNER_PHASE_FOCUS_PROXY_SELECTION;
    else if (name && strstr(name, "focus.position_input_proxy")) phase = CJGUI_OWNER_PHASE_FOCUS_PROXY_POSITION;
    else if (name && (strstr(name, "focus.input_first_responder") || strstr(name, "focus.non_text_first_responder"))) phase = CJGUI_OWNER_PHASE_FOCUS_FIRST_RESPONDER;
    else if (name && strstr(name, "focus.command_menu")) phase = CJGUI_OWNER_PHASE_FOCUS_COMMAND_MENU;
    else if (name && (strstr(name, "focus.accessibility") || strstr(name, "focus.non_text_accessibility"))) phase = CJGUI_OWNER_PHASE_FOCUS_ACCESSIBILITY;
    else if (name && strstr(name, "focus.refresh_gpu_text")) phase = CJGUI_OWNER_PHASE_FOCUS_GPU_TEXT;
    else if (name && strstr(name, "focus.caret_display_tail")) phase = CJGUI_OWNER_PHASE_FOCUS_CARET_DISPLAY;
    else if (name && strstr(name, "focus_node.")) phase = CJGUI_OWNER_PHASE_FOCUS_TOTAL;
    else if (name && strstr(name, "focus_composable_node.")) phase = CJGUI_OWNER_PHASE_NATIVE_FOCUS_NODE;
    else if (name && strstr(name, "restore_composable_selection.")) phase = CJGUI_OWNER_PHASE_NATIVE_RESTORE_SELECTION;
    else if (name && strstr(name, "projection.input_admission")) phase = CJGUI_OWNER_PHASE_PROJECTION_INPUT_ADMISSION;
    else if (name && (strstr(name, "projection.refresh_gpu_text") || strstr(name, "refresh_gpu_text_for_active_input"))) phase = CJGUI_OWNER_PHASE_ACTIVE_GPU_TEXT;
    uint64_t span = CjguiOwnerTraceAppendAt(CJGUI_OWNER_TRACE_PHASE_BEGIN, session, turn, 0,
        0, 0, phase, 0, started, 0);
    CjguiOwnerTraceAppend(CJGUI_OWNER_TRACE_PHASE_END, session, turn, 0,
        0, 0, phase, span);
}
static void CjguiTraceOwnerIdleWait(uint64_t session, uint64_t started, uint64_t ended) {
    if (!started || ended < started) return;
    if (!CjguiOwnerPhaseTraceEnabled()) return;
    atomic_fetch_add_explicit(&gCjguiOwnerTraceCurrentTurnIdleNs, ended - started, memory_order_relaxed);
    uint64_t turn = atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn, memory_order_acquire);
    uint64_t threadId = 0;
    if (pthread_threadid_np(NULL, &threadId) != 0 || threadId == 0) threadId = UINT64_MAX;
    uint64_t span = CjguiOwnerTraceAppendAt(CJGUI_OWNER_TRACE_IDLE_BEGIN, session, turn, 0,
        0, 0, CJGUI_OWNER_PHASE_IDLE_WAIT, 0, started, threadId);
    CjguiOwnerTraceAppendAt(CJGUI_OWNER_TRACE_IDLE_END, session, turn, 0,
        0, 0, CJGUI_OWNER_PHASE_IDLE_WAIT, span, ended, threadId);
}

#ifdef CJGUI_INTERNAL_TESTING
static uint64_t CjguiMonotonicMicros(void) {
    return CjguiCaretBlinkClockMicros();
}
#else
// Interval probes are TESTING-only. Keep their call sites compile-time inert
// in the exported renderer rather than adding clock reads to production draw.
#define CjguiMonotonicMicros() 0ULL
#endif

// Pure arithmetic, no clock: the production workload counters (raster/upload
// counts and bytes) accumulate through this in every build, so it must NOT
// live behind CJGUI_INTERNAL_TESTING like the interval probes do.
static uint64_t CjguiSaturatingAddU64(uint64_t value, uint64_t delta) {
    return delta > UINT64_MAX - value ? UINT64_MAX : value + delta;
}

// Normal-build diagnostics clock. Call sites guard this read with the owning
// session's explicit timing switch; it is intentionally independent of caret,
// animation and scroll scheduling clocks.
static uint64_t CjguiDiagnosticMonotonicNanoseconds(void) {
    static mach_timebase_info_data_t timebase;
    static dispatch_once_t once;
    dispatch_once(&once, ^{ mach_timebase_info(&timebase); });
    uint64_t ticks = mach_continuous_time();
    return (uint64_t)(((__uint128_t)ticks * timebase.numer) /
                      ((__uint128_t)MAX((uint32_t)1, timebase.denom)));
}


@class CJGuiInternalComposableSceneNode;

// A Metal completion may arrive while a synchronous owner turn is still
// building later scenes. The callback releases its exact captured resources
// off-thread, then publishes this one-way flag; the owner prunes its own
// dictionary before charging the next candidate. No mutable session table is
// touched from the Metal callback.
@interface CjguiTextSubmissionCompletion : NSObject
@property(atomic, assign) BOOL resourcesReleased;
@end
@implementation CjguiTextSubmissionCompletion
@end

enum { CJGUI_INTERNAL_COMPOSABLE_CLIP_CONSTRAINT_CAPACITY = 4 };
// Apple documents a 4 KiB upper bound for setVertexBytes. This renderer uses
// it only for short-lived shape data, so split consecutive shape commands at
// that byte boundary rather than retaining a Metal buffer across frames. A
// triangle batches must remain whole to preserve painter ordering. Ordinary
// rectangles contribute six vertices; bounded vector geometry may contribute
// more but still splits only at complete-triangle boundaries.
enum {
    CJGUI_INTERNAL_METAL_SET_VERTEX_BYTES_CAPACITY = 4 * 1024,
    CJGUI_INTERNAL_COMPOSABLE_VECTOR_MAX_POINTS = 12,
    CJGUI_INTERNAL_COMPOSABLE_VECTOR_ELLIPSE_SEGMENTS = 32,
};

enum {
    CJGUI_INTERNAL_VECTOR_LINE = 1,
    CJGUI_INTERNAL_VECTOR_POLYLINE = 2,
    CJGUI_INTERNAL_VECTOR_ELLIPSE = 3,
    CJGUI_INTERNAL_VECTOR_SIMPLE_POLYGON = 4,
    CJGUI_INTERNAL_VECTOR_CAP_BUTT = 1,
    CJGUI_INTERNAL_VECTOR_CAP_ROUND = 2,
    CJGUI_INTERNAL_VECTOR_CAP_SQUARE = 3,
    CJGUI_INTERNAL_VECTOR_JOIN_MITER = 1,
    CJGUI_INTERNAL_VECTOR_JOIN_BEVEL = 2,
    CJGUI_INTERNAL_VECTOR_JOIN_ROUND = 3,
};

#ifdef CJGUI_INTERNAL_TESTING
// Bounded attribution for real text bitmap/texture work. Unknown is retained
// as an honest bucket whenever a refresh cannot prove its triggering change.
typedef enum CjguiInternalTextWorkReason {
    CjguiInternalTextWorkReasonUnknown = 0,
    CjguiInternalTextWorkReasonStaticCandidate = 1,
    CjguiInternalTextWorkReasonActiveContent = 2,
    CjguiInternalTextWorkReasonSelectionCaret = 3,
    CjguiInternalTextWorkReasonVisibleTileScroll = 4,
    CjguiInternalTextWorkReasonRetry = 5,
    // A projection-driven geometry/scale change refreshed the focused input, or
    // an external owner replaced its value while focused. Without these buckets
    // such refreshes fall into Unknown and attribution cannot distinguish
    // static-candidate work from active work.
    CjguiInternalTextWorkReasonProjectionGeometry = 6,
    CjguiInternalTextWorkReasonExternalProjectionContent = 7,
    CjguiInternalTextWorkReasonCount = 8,
} CjguiInternalTextWorkReason;
typedef struct CjguiInternalTextWorkReasonCounters {
    uint64_t raster[CjguiInternalTextWorkReasonCount];
    uint64_t upload[CjguiInternalTextWorkReasonCount];
} CjguiInternalTextWorkReasonCounters;
#endif

typedef struct CJGuiInternalMetalVertex {
    vector_float2 position;
    vector_float2 scenePoint;
    vector_float2 localPoint;
    vector_float2 size;
    vector_float4 clips[CJGUI_INTERNAL_COMPOSABLE_CLIP_CONSTRAINT_CAPACITY];
    vector_float4 clipRadii;
    // Keep the count vector-aligned so the C and Metal layouts stay identical.
    vector_float4 clipCount;
    float cornerRadius;
    float borderWidth;
    // Shapes emitted for vector geometry already have exact triangle bounds;
    // the fragment still applies the shared rounded clip chain, but bypasses
    // the rectangle signed-distance/border calculation below.
    float isVectorShape;
    float vectorPadding;
    vector_float4 fill;
    vector_float4 border;
    // ---- P1 shape effects (vertex payload) ----
    // `passKind` selects the fragment path: 0 = ordinary fill/border quad,
    // 1 = outer shadow quad. A shadow vertex carries no gradient; it reuses
    // localPoint/size as the expanded shadow-shape SDF space and reads only
    // shadowBlurRadius/shadowColor. Gradient vertices carry the normalized
    // endpoints plus up to four stops (xyz = sRGB color, w of the parallel
    // alphas vector = stop alpha). Field order is mirrored verbatim in the
    // Metal struct inside `CjguiEncodeComposableNodes`.
    float passKind;
    float shadowBlurRadius;
    float gradientPresent;
    float gradientStopCount;
    vector_float2 gradientStart;
    vector_float2 gradientEnd;
    vector_float4 shadowColor;
    vector_float4 gradientStop0;
    vector_float4 gradientStop1;
    vector_float4 gradientStop2;
    vector_float4 gradientStop3;
    vector_float4 gradientStopAlphas;
} CJGuiInternalMetalVertex;

typedef struct CjguiInternalComposableVectorPoint {
    double x;
    double y;
} CjguiInternalComposableVectorPoint;

typedef struct CjguiInternalComposableVectorGeometry {
    uint32_t kind;
    uint32_t pointCount;
    uint32_t cap;
    uint32_t join;
    double viewBoxWidth;
    double viewBoxHeight;
    double strokeWidth;
    double fillRed, fillGreen, fillBlue, fillAlpha;
    double strokeRed, strokeGreen, strokeBlue, strokeAlpha;
    CjguiInternalComposableVectorPoint center;
    double radiusX;
    double radiusY;
    CjguiInternalComposableVectorPoint points[CJGUI_INTERNAL_COMPOSABLE_VECTOR_MAX_POINTS];
    // Ear clipping is performed once when the copied scene payload changes.
    // Each triplet indexes `points`; a 12-point simple polygon has at most
    // ten triangles, so this remains a fixed 30-byte bound.
    uint8_t triangleIndices[(CJGUI_INTERNAL_COMPOSABLE_VECTOR_MAX_POINTS - 2) * 3];
    uint32_t triangleIndexCount;
} CjguiInternalComposableVectorGeometry;

typedef struct CJGuiInternalMetalTextureVertex {
    vector_float2 position;
    vector_float2 texCoord;
    vector_float2 scenePoint;
    vector_float4 clips[CJGUI_INTERNAL_COMPOSABLE_CLIP_CONSTRAINT_CAPACITY];
    vector_float4 clipRadii;
    vector_float4 clipCount;
    vector_float4 nodeRect;
    float nodeCornerRadius;
    // Per-draw alpha multiplier applied to the sampled texel. Text glyph
    // textures are rasterized with an opaque colour so a dynamic opacity
    // animation changes this multiplier, not the cached texture; image quads
    // pass 1.0 and keep their texel alpha untouched.
    float paintAlpha;
} CJGuiInternalMetalTextureVertex;

@class CJGuiInternalComposableEffectTarget;

static BOOL CjguiEncodeComposableNodes(id view, id<MTLRenderCommandEncoder> encoder, CGSize drawableSize);
static uint32_t CjguiComposableClipConstraintCount(CjguiInternalRendererComposableNode value);
static void CjguiComposableClipConstraintAt(CjguiInternalRendererComposableNode value, uint32_t index,
                                             CGFloat *x, CGFloat *y, CGFloat *width, CGFloat *height, CGFloat *radius);

static uint8_t CjguiColorChannelToByte(double value) {
    if (value <= 0.0) return 0;
    if (value >= 1.0) return 255;
    return (uint8_t)(value * 255.0 + 0.5);
}

static BOOL CjguiColorByteMatches(uint8_t actual, uint8_t expected) {
    const int tolerance = 3;
    int delta = (int)actual - (int)expected;
    if (delta < 0) delta = -delta;
    return delta <= tolerance;
}

