@interface CJGuiInternalMetalView : NSView
// The session this view belongs to. Binds session-scoped presentation data
// (a node's style-run table) to the view that rasterizes it.
@property(nonatomic, assign) uint64_t sessionToken;
@property(nonatomic, assign) uint64_t coordinateSessionGeneration;
@property(nonatomic, strong) id<MTLDevice> device;
@property(nonatomic, strong) id<MTLCommandQueue> commandQueue;
@property(nonatomic, strong) CAMetalLayer *metalLayer;
@property(nonatomic, assign) BOOL invalidated;
@property(nonatomic, assign) BOOL readbackProbeCompleted;
@property(nonatomic, strong) id readbackProbeTask;
@property(nonatomic, strong) id readbackProbeImageTag;
@property(nonatomic, assign) BOOL readbackProbeColorMatched;
@property(nonatomic, assign) uint64_t frameIndex;
@property(nonatomic, assign) CGSize lastSubmittedDrawableSize;
@property(nonatomic, assign) NSSize lastSubmittedPointSize;
@property(nonatomic, assign) CGFloat lastSubmittedContentsScale;
@property(nonatomic, strong) id<MTLRenderPipelineState> composablePipeline;
@property(nonatomic, strong) id<MTLRenderPipelineState> composableImagePipeline;
@property(nonatomic, strong) id<MTLRenderPipelineState> composableVectorPipeline;
// Ordinary form/text/image scenes render directly to the drawable. A vector
// scene selects the matching reusable 4x states below for that frame only;
// a sample-count mismatch is not valid Metal pipeline reuse.
@property(nonatomic, strong) id<MTLRenderPipelineState> composableMultisamplePipeline;
@property(nonatomic, strong) id<MTLRenderPipelineState> composableMultisampleImagePipeline;
@property(nonatomic, strong) id<MTLRenderPipelineState> composableMultisampleVectorPipeline;
@property(nonatomic, strong) id<MTLTexture> composableMultisampleTexture;
@property(nonatomic, assign) BOOL composableUsesMultisampling;
@property(nonatomic, strong) NSArray<CJGuiInternalComposableSceneNode *> *composableNodes;
// Only accepted groups are cached here. Candidate targets live on their
// staged node until presentation succeeds; in-flight command buffers retain
// their exact generation independently of later accepted replacements.
@property(nonatomic, strong) NSMutableDictionary<NSNumber *, CJGuiInternalComposableEffectTarget *> *effectGroupCache;
@property(nonatomic, strong) NSMutableDictionary<NSNumber *, CJGuiInternalComposableEffectTarget *> *backdropCache;
@property(nonatomic, strong) NSHashTable<CJGuiInternalComposableEffectTarget *> *effectTargetLedger;
// Transient collector for the current command buffer. The submitted callback
// takes an immutable copy of exactly the image textures encoded into it.
@property(nonatomic, strong) NSMutableArray<id<MTLTexture>> *encodedImageTextures;
@property(nonatomic, strong) NSMutableDictionary<NSString *, id<MTLRenderPipelineState>> *effectPipelines;
@property(nonatomic, strong) id<MTLComputePipelineState> backdropHorizontalPipeline;
@property(nonatomic, strong) id<MTLComputePipelineState> backdropVerticalPipeline;
// Always-on scalar work totals for normal app diagnostics. They count actual
// successful text tile raster/upload points, independently of test tracing.
@property(nonatomic, assign) uint64_t textRasterCount;
@property(nonatomic, assign) uint64_t textRasterBytes;
@property(nonatomic, assign) uint64_t textRasterMicros;
@property(nonatomic, assign) uint64_t textUploadCount;
@property(nonatomic, assign) uint64_t textUploadBytes;
@property(nonatomic, assign) uint64_t textUploadMicros;
#ifdef CJGUI_INTERNAL_TESTING
// A probe may select a controlled backing scale only to exercise the normal
// backing-properties notification route on a single-display machine. The
// production scale always comes from the attached NSWindow/NSScreen.
@property(nonatomic, assign) CGFloat testBackingScaleOverride;
// Scalar encoder work facts for the focused renderer probe.  They expose no
// Metal object and deliberately distinguish shape-node count from contiguous
// batch submissions and texture boundaries.
// 0 = capacity-bounded consecutive rectangles (production path), 1 = one
// complete rectangle per legal setVertexBytes submission (comparison path).
@property(nonatomic, assign) uint8_t testComposableShapeSubmissionMode;
@property(nonatomic, assign) uint32_t testComposableShapeNodeCount;
@property(nonatomic, assign) uint32_t testComposableShapeBatchCount;
@property(nonatomic, assign) uint32_t testComposableTextureDrawCount;
@property(nonatomic, assign) uint64_t testComposableShapeVertexBytes;
@property(nonatomic, assign) uint64_t testComposableMaxShapeBatchVertexBytes;
@property(nonatomic, assign) uint32_t testComposableShapeVertexStride;
// Wall time inside CjguiEncodeComposableNodes for this submitted frame. It is
// CPU encoder work only: it excludes command-buffer completion and display.
@property(nonatomic, assign) uint64_t testComposableEncoderCpuMicros;
// Direct per-frame native spans. The final readback field records only an
// explicit synchronous diagnostic wait, never asynchronous Metal completion.
@property(nonatomic, assign) uint64_t testComposableNextDrawableMicros;
@property(nonatomic, assign) uint64_t testComposableCommandBufferMicros;
@property(nonatomic, assign) uint64_t testComposablePresentMicros;
@property(nonatomic, assign) uint64_t testComposableCommitMicros;
@property(nonatomic, assign) uint64_t testComposableReadbackWaitMicros;
@property(nonatomic, assign) uint8_t testComposableReadbackWaited;
// These scalar diagnostics describe attachment ownership, lazy pipeline
// construction and accepted-node local vector preparation. They are not GPU
// completion or physical presentation timings.
@property(nonatomic, assign) uint8_t testComposableRenderSampleCount;
@property(nonatomic, assign) uint64_t testComposableMultisampleAttachmentBytes;
@property(nonatomic, assign) uint64_t testComposablePipelineBuildCount;
@property(nonatomic, assign) uint64_t testComposableVectorGeometryPreparationCount;
@property(nonatomic, assign) uint64_t testComposableVectorGeometryPreparedBytes;
// Latest-frame submission facts for the compact resident vector buffers.
// Uploads occur only when topology changes; reuses are ordinary paint/layout
// draws of a previously accepted immutable buffer.
@property(nonatomic, assign) uint32_t testComposableVectorDrawCount;
@property(nonatomic, assign) uint32_t testComposableVectorBufferUploadCount;
@property(nonatomic, assign) uint32_t testComposableVectorBufferReuseCount;
@property(nonatomic, assign) uint64_t testComposableVectorBufferUploadBytes;
// Text preparation is deliberately reported apart from command encoding:
// an AppKit bitmap raster and `replaceRegion` are real work with different
// owners and neither implies a completed/presented Metal frame.
@property(nonatomic, assign) uint64_t testComposableTextRasterCount;
@property(nonatomic, assign) uint64_t testComposableTextRasterBytes;
@property(nonatomic, assign) uint64_t testComposableTextRasterMicros;
@property(nonatomic, assign) uint64_t testComposableTextUploadCount;
@property(nonatomic, assign) uint64_t testComposableTextUploadBytes;
@property(nonatomic, assign) uint64_t testComposableTextUploadMicros;
@property(nonatomic, assign) CjguiInternalTextWorkReasonCounters testComposableTextWorkReasonCounters;
@property(nonatomic, assign) uint64_t testComposableTextLastProjectionVersion;
@property(nonatomic, assign) uint64_t testComposableTextLastContentUtf8Bytes;
// One candidate-only failure at the shared-layout boundary. The ordinary
// preparation-failure hook returns earlier and cannot exercise its nil guard.
@property(nonatomic, assign) BOOL testForceSharedTextLayoutNilOnce;
// Candidate text preparation's CPU scratch is the shared BGRA bitmap. It is
// allocated and released inside every raster; these counters make that visible
// instead of inferred. Current must return to zero after each raster; peak is
// a high-water mark and is reported separately from Metal texture bytes.
@property(nonatomic, assign) uint64_t testComposableTextCpuScratchCurrentBytes;
@property(nonatomic, assign) uint64_t testComposableTextCpuScratchPeakBytes;
// Sub-interval attribution. The per-reason raster counters are outer wall time
// per prepared node; the intervals below cover distinct sub-steps and MUST NOT
// be summed with them into a total.
@property(nonatomic, assign) uint64_t testComposableTextStaticDrawWithLayoutMicros;
@property(nonatomic, assign) uint64_t testComposableTextNormalizeMicros;
@property(nonatomic, assign) uint64_t testComposableTextTextureCreateMicros;
@property(nonatomic, assign) uint64_t testEffectTargetAllocationCount;
@property(nonatomic, assign) uint64_t testEffectTargetReuseCount;
@property(nonatomic, assign) uint64_t testEffectTargetCurrentBytes;
@property(nonatomic, assign) uint64_t testEffectTargetPeakBytes;
@property(nonatomic, assign) uint64_t testEffectContentRedrawCount;
@property(nonatomic, assign) uint64_t testEffectPassCount;
@property(nonatomic, assign) uint64_t testEffectCompositeDrawCount;
@property(nonatomic, assign) uint64_t testBackdropPrefixPassCount;
@property(nonatomic, assign) uint64_t testBackdropHorizontalPassCount;
@property(nonatomic, assign) uint64_t testBackdropVerticalPassCount;
@property(nonatomic, assign) uint64_t testBackdropCacheHitCount;
@property(nonatomic, assign) uint64_t testBackdropFallbackCount;
#endif
- (instancetype)initWithFrame:(NSRect)frame
                       device:(id<MTLDevice>)device
                 commandQueue:(id<MTLCommandQueue>)commandQueue;
- (void)updateDrawableSize;
- (void)invalidateBridgeResources;
