@end

#ifdef CJGUI_INTERNAL_TESTING
// Detailed glyph dumps are useful only when diagnosing text geometry. Keep
// default probe stderr scalar-friendly so concurrent runner output cannot
// corrupt performance samples. The opt-in is process-scoped and test-only.
static BOOL CjguiTestVerboseGlyphDiagnosticsEnabled(void) {
    return [NSProcessInfo.processInfo.environment[@"CJGUI_INTERNAL_VERBOSE_GLYPH_DIAGNOSTICS"] boolValue];
}
static BOOL CjguiTestTileCostDiagnosticsEnabled(void) {
    return [NSProcessInfo.processInfo.environment[@"CJGUI_INTERNAL_TRACE_TILE_COST"] boolValue];
}

static void CjguiRecordTextWork(CJGuiInternalMetalView *metalView,
                                uint64_t projectionVersion,
                                uint64_t contentUtf8Bytes,
                                CjguiInternalTextWorkReason reason) {
    if (!metalView) return;
    if (reason >= CjguiInternalTextWorkReasonCount) reason = CjguiInternalTextWorkReasonUnknown;
    // Objective-C struct properties are returned by value. Mutate a local
    // copy, then assign it back, so attribution is retained across events.
    CjguiInternalTextWorkReasonCounters counters = metalView.testComposableTextWorkReasonCounters;
    counters.raster[reason] = CjguiSaturatingAddU64(counters.raster[reason], 1);
    counters.upload[reason] = CjguiSaturatingAddU64(counters.upload[reason], 1);
    metalView.testComposableTextWorkReasonCounters = counters;
    metalView.testComposableTextLastProjectionVersion = projectionVersion;
    metalView.testComposableTextLastContentUtf8Bytes = contentUtf8Bytes;
}

// The shared BGRA bitmap is the only CPU staging a text raster owns. Bump on
// allocation and drop on every exit so `current` honestly returns to zero;
// `peak` records the high-water mark separately from Metal texture bytes.
static void CjguiAddTextCpuScratch(CJGuiInternalMetalView *metalView, uint64_t byteCount) {
    if (!metalView || byteCount == 0) return;
    metalView.testComposableTextCpuScratchCurrentBytes = CjguiSaturatingAddU64(
        metalView.testComposableTextCpuScratchCurrentBytes, byteCount);
    if (metalView.testComposableTextCpuScratchCurrentBytes > metalView.testComposableTextCpuScratchPeakBytes) {
        metalView.testComposableTextCpuScratchPeakBytes = metalView.testComposableTextCpuScratchCurrentBytes;
    }
}

static void CjguiDropTextCpuScratch(CJGuiInternalMetalView *metalView, uint64_t byteCount) {
    if (!metalView || byteCount == 0) return;
    if (metalView.testComposableTextCpuScratchCurrentBytes >= byteCount) {
        metalView.testComposableTextCpuScratchCurrentBytes -= byteCount;
    } else {
        metalView.testComposableTextCpuScratchCurrentBytes = 0;
    }
}
#else
__attribute__((unused)) static void CjguiAddTextCpuScratch(CJGuiInternalMetalView *metalView, uint64_t byteCount) { (void)metalView; (void)byteCount; }
__attribute__((unused)) static void CjguiDropTextCpuScratch(CJGuiInternalMetalView *metalView, uint64_t byteCount) { (void)metalView; (void)byteCount; }
#endif

@implementation CJGuiInternalMetalView

- (CGFloat)currentBackingScale {
#ifdef CJGUI_INTERNAL_TESTING
    if (self.testBackingScaleOverride > 0.0) return self.testBackingScaleOverride;
#endif
    return self.window ? self.window.backingScaleFactor : NSScreen.mainScreen.backingScaleFactor;
}

- (instancetype)initWithFrame:(NSRect)frame
                       device:(id<MTLDevice>)device
                 commandQueue:(id<MTLCommandQueue>)commandQueue {
    self = [super initWithFrame:frame];
    if (!self || !device || !commandQueue) {
        return nil;
    }

    self.wantsLayer = YES;
    self.device = device;
    self.commandQueue = commandQueue;
    self.effectGroupCache = [NSMutableDictionary dictionary];
    self.backdropCache = [NSMutableDictionary dictionary];
    self.effectTargetLedger = [NSHashTable weakObjectsHashTable];
    self.effectPipelines = [NSMutableDictionary dictionary];

    self.metalLayer = [CAMetalLayer layer];
    if (!self.metalLayer) {
        return nil;
    }

    self.metalLayer.device = self.device;
    self.metalLayer.pixelFormat = MTLPixelFormatBGRA8Unorm;
    // Readback probe requires a blit-readable drawable.
    self.metalLayer.framebufferOnly = NO;
    self.metalLayer.opaque = NO;
    self.metalLayer.backgroundColor = NSColor.clearColor.CGColor;
    self.metalLayer.contentsScale = [self currentBackingScale];
    self.layer = self.metalLayer;
    [self updateDrawableSize];

    return self;
}

- (void)setFrameSize:(NSSize)newSize {
    BOOL changed=!NSEqualSizes(self.frame.size,newSize);
    [super setFrameSize:newSize];
    [self updateDrawableSize];
    if(changed) CjguiBumpCoordinateLifetimeForIdentity(self.sessionToken,self.coordinateSessionGeneration);
}
- (void)setFrameOrigin:(NSPoint)newOrigin {
    BOOL changed=!NSEqualPoints(self.frame.origin,newOrigin);
    [super setFrameOrigin:newOrigin];
    if(changed) CjguiBumpCoordinateLifetimeForIdentity(self.sessionToken,self.coordinateSessionGeneration);
}
- (void)setBoundsOrigin:(NSPoint)newOrigin {
    BOOL changed=!NSEqualPoints(self.bounds.origin,newOrigin);
    [super setBoundsOrigin:newOrigin];
    if(changed) CjguiBumpCoordinateLifetimeForIdentity(self.sessionToken,self.coordinateSessionGeneration);
}
- (void)setBoundsSize:(NSSize)newSize {
    BOOL changed=!NSEqualSizes(self.bounds.size,newSize);
    [super setBoundsSize:newSize];
    if(changed) CjguiBumpCoordinateLifetimeForIdentity(self.sessionToken,self.coordinateSessionGeneration);
}
- (void)setFrame:(NSRect)newFrame {
    BOOL changed=!NSEqualRects(self.frame,newFrame);
    [super setFrame:newFrame];
    if(changed) CjguiBumpCoordinateLifetimeForIdentity(self.sessionToken,self.coordinateSessionGeneration);
}
- (void)setBounds:(NSRect)newBounds {
    BOOL changed=!NSEqualRects(self.bounds,newBounds);
    [super setBounds:newBounds];
    if(changed) CjguiBumpCoordinateLifetimeForIdentity(self.sessionToken,self.coordinateSessionGeneration);
}
- (void)setFrameRotation:(CGFloat)rotation {
    BOOL changed=self.frameRotation!=rotation;
    [super setFrameRotation:rotation];
    if(changed) CjguiBumpCoordinateLifetimeForIdentity(self.sessionToken,self.coordinateSessionGeneration);
}
- (void)setFrameCenterRotation:(CGFloat)rotation {
    BOOL changed=self.frameCenterRotation!=rotation;
    [super setFrameCenterRotation:rotation];
    if(changed) CjguiBumpCoordinateLifetimeForIdentity(self.sessionToken,self.coordinateSessionGeneration);
}
- (void)setBoundsRotation:(CGFloat)rotation {
    BOOL changed=self.boundsRotation!=rotation;
    [super setBoundsRotation:rotation];
    if(changed) CjguiBumpCoordinateLifetimeForIdentity(self.sessionToken,self.coordinateSessionGeneration);
}
- (void)viewDidMoveToSuperview {
    [super viewDidMoveToSuperview];
    CjguiBumpCoordinateLifetimeForIdentity(self.sessionToken,self.coordinateSessionGeneration);
}

- (void)viewDidMoveToWindow {
    NSWindow *priorWindow=self.window;
    [super viewDidMoveToWindow];
    if(priorWindow!=self.window)
        CjguiBumpCoordinateLifetimeForIdentity(self.sessionToken,self.coordinateSessionGeneration);
    // The view overrides mouseMoved: to drive hover enter/leave, but AppKit only
    // delivers mouseMoved while the window opts in. Without this, hover was
    // observable ONLY on the mouseDown path (which calls updateHoverAtPoint
    // directly), so UI-only consumers saw no HOVER_ENTER/LEAVE on a plain move.
    if (self.window) {
        self.window.acceptsMouseMovedEvents = YES;
    }
    [self updateDrawableSize];
}

- (void)viewDidChangeBackingProperties {
    [super viewDidChangeBackingProperties];
    CjguiBumpCoordinateLifetimeForIdentity(self.sessionToken,self.coordinateSessionGeneration);
    [self updateDrawableSize];
}

- (void)updateDrawableSize {
    if (!self.metalLayer || self.invalidated) {
        return;
    }
    CGFloat scale = [self currentBackingScale];
    CGSize pointSize = self.bounds.size;
    self.metalLayer.frame = self.bounds;
    self.metalLayer.contentsScale = scale;
    // Request integral texels covering the full logical content. Child
    // layout and text coordinates remain subpoint-precise.
    self.metalLayer.drawableSize = CGSizeMake(ceil(pointSize.width * scale),
                                              ceil(pointSize.height * scale));
}

- (void)invalidateBridgeResources {
    if (self.invalidated) {
        return;
    }
    self.invalidated = YES;
    CjguiInvalidateCoordinateLifetimeForIdentity(self.sessionToken,self.coordinateSessionGeneration);
    self.layer = nil;
    self.metalLayer = nil;
    self.commandQueue = nil;
    self.device = nil;
    self.composableImagePipeline = nil;
    self.composablePipeline = nil;
    self.composableVectorPipeline = nil;
    self.composableMultisampleImagePipeline = nil;
    self.composableMultisamplePipeline = nil;
    self.composableMultisampleVectorPipeline = nil;
    self.composableMultisampleTexture = nil;
    self.composableUsesMultisampling = NO;
    [self.effectGroupCache removeAllObjects];
    [self.backdropCache removeAllObjects];
    self.effectPipelines = nil;
}

- (BOOL)encodeComposableNodes:(id<MTLRenderCommandEncoder>)encoder drawableSize:(CGSize)drawableSize {
    return CjguiEncodeComposableNodes(self, encoder, drawableSize);
}

@end

