              selectionStart:(uint32_t)selectionStart selectionEnd:(uint32_t)selectionEnd
                    formText:(NSString *)formText nodeId:(uint64_t)nodeId
           projectionVersion:(uint64_t)projectionVersion resourceId:(int64_t)resourceId
                     nodeKind:(uint32_t)nodeKind {
    self = [super init];
    if (!self) return nil;
    self.kind = kind;
    self.recordIndex = recordIndex;
    self.selectionStart = selectionStart;
    self.selectionEnd = selectionEnd;
    self.nodeId = nodeId;
    self.projectionVersion = projectionVersion;
    self.resourceId = resourceId;
    self.nodeKind = nodeKind;
    self.pointerX = 0;
    self.pointerY = 0;
    self.coordinateSessionGeneration = 0;
    self.coordinateEpoch = 0;
    self.formText = [formText copy] ?: @"";
    self.dataTransferFormat = @"";
    self.dataTransferSourceKind = @"";
    self.dataTransferSourceIdentity = @"";
    self.dataTransferSourceId = -1;
    self.compositionPhase = 0;
    self.replacementStart16 = -1;
    self.replacementLength16 = 0;
    self.markedStart16 = -1;
    self.markedLength16 = 0;
    self.compositionId = 0;
    self.bindingEpoch = 0;
    self.expectedOwnerVersion = -1;
    return self;
}

