}

- (instancetype)init {
    self = [super init];
    if (!self) return nil;
    self.pendingInteractions = [NSMutableArray array];
    self.installedRangeObservedAckVersion = -1;
    self.pendingFileTransfers = [NSMutableArray array];
    self.pendingTransferTerminalFacts = [NSMutableArray array];
    self.rangeTextEditDeltaDeliveryEnabled = NO;
    self.ownedTextSessionEnabled = NO;
    self.ownedTextSessionNodeId = 0;
    self.ownedTextSessionResourceId = -1;
    self.ownedTextSessionNodeKind = 0;
    self.ownedTextSessionBindingEpoch = 0;
    self.composableContextMenuGuardEnabled = NO;
    self.composableContextMenuGuardSceneVersion = 0;
    self.composableContextMenuGuardLayerScope = 0;
    self.composableContextMenuGuardRequestId = 0;
    self.composableContextMenuGuardLayerNodeId = 0;
    self.composableContextMenuGuardResourceId = -1;
    self.composableContextMenuGuardNodeKind = 0;
    self.composableContextMenuGuardBounds = NSZeroRect;
    self.nextCompositionId = 0;
    self.composableNodes = [NSMutableArray array];
    self.stagedComposableNodes = [NSMutableArray array];
    self.stagedComposableGeometryIndices = [NSMutableIndexSet indexSet];
    self.composableDataTransferItems = [NSMutableArray array];
    self.stagedComposableDataTransferItems = [NSMutableArray array];
    self.composableCommandMenuItems = [NSMutableArray array];
    self.stagedComposableCommandMenuItems = [NSMutableArray array];
    self.pumpedFormText = @"";
    self.pumpedFormTextUtf8 = [NSData dataWithBytes:"" length:1];
    self.pumpedDataTransferFormat = @"";
    self.pumpedDataTransferFormatUtf8 = [NSData dataWithBytes:"" length:1];
    self.pumpedDataTransferSourceKind = @"";
    self.pumpedDataTransferSourceKindUtf8 = [NSData dataWithBytes:"" length:1];
    self.pumpedDataTransferSourceIdentity = @"";
    self.pumpedDataTransferSourceIdentityUtf8 = [NSData dataWithBytes:"" length:1];
    self.pumpedDataTransferSourceId = -1;
    self.observedMetalGpuDurationMicros = -1;
    self.diagnosticTimingEnabled = NO;
    self.positionPrepareCount = 0;
    self.positionQueryCount = 0;
    self.positionLineBuildCount = 0;
    self.positionCacheHitCount = 0;
    self.positionPrepareNanoseconds = 0;
    self.positionQueryNanoseconds = 0;
    self.positionLineBuildNanoseconds = 0;
    self.diagnosticEncodeNanoseconds = 0;
    self.diagnosticSubmitNanoseconds = 0;
    self.diagnosticRasterNanoseconds = 0;
    self.diagnosticUploadNanoseconds = 0;
    self.diagnosticReadCount = 0;
    self.diagnosticReadNanoseconds = 0;
    return self;
}

- (BOOL)windowShouldClose:(id)sender {
    (void)sender;
    if (self.closeRequested) return YES;
    (void)CjguiEnqueueInteraction(self, CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_CLOSE,
                                  0, @"", 0, 0);
    NSLog(@"cjgui: user close deferred to collection domain");
    return NO;
}

- (void)windowWillClose:(NSNotification *)notification {
    (void)notification;
    id overlay = self.composableSceneOverlay;
    if (overlay && [overlay respondsToSelector:@selector(stopCaretBlink)]) {
        [overlay performSelector:@selector(stopCaretBlink)];
    }
    if (!self.closeRequested) {
        self.closeRequested = YES;
        NSLog(@"cjgui: close requested: window");
    }
    if (self.rendererSessionToken > 0 && self.rendererSessionToken <= kCjguiSessionCapacity) {
        CjguiClearWindowBackgroundSnapshotForSlot((NSUInteger)(self.rendererSessionToken - 1),
            self.sessionGeneration);
        CjguiClearViewportSnapshotForSlot((NSUInteger)(self.rendererSessionToken - 1),
            self.sessionGeneration);
    }
    NSLog(@"cjgui: window will close");
    CjguiRebuildComposableCommandMenuForKeyWindow();
}

- (void)windowDidBecomeKey:(NSNotification *)notification {
    (void)notification;
    self.windowBackgroundWindowActive = self.window.isKeyWindow && self.app.isActive;
    self.windowBackgroundEnvironmentRevision += 1;
    self.windowBackgroundObservationRevision += 1;
    CjguiPublishWindowBackgroundSnapshot(self);
    CjguiRebuildComposableCommandMenuForKeyWindow();
    id overlay = self.composableSceneOverlay;
    if (overlay && [overlay respondsToSelector:@selector(resetCaretBlink)]) {
        [overlay performSelector:@selector(resetCaretBlink)];
    }
}

- (void)windowDidResignKey:(NSNotification *)notification {
    (void)notification;
    self.windowBackgroundWindowActive = NO;
    self.windowBackgroundEnvironmentRevision += 1;
    self.windowBackgroundObservationRevision += 1;
    CjguiPublishWindowBackgroundSnapshot(self);
    id overlay = self.composableSceneOverlay;
    if (overlay && [overlay respondsToSelector:@selector(stopCaretBlink)]) {
        [overlay performSelector:@selector(stopCaretBlink)];
    }
    if (overlay && [overlay respondsToSelector:@selector(cancelPointerCaptureForPlatformLoss)]) {
        if ([overlay respondsToSelector:@selector(tracePointerCaptureCancellation:)])
            [overlay performSelector:@selector(tracePointerCaptureCancellation:) withObject:@"window_resign"];
        [overlay performSelector:@selector(cancelPointerCaptureForPlatformLoss)];
    }
}

- (void)windowBackgroundEnvironmentDidChange:(NSNotification *)notification {
    (void)notification;
    BOOL reduce = CjguiWindowReduceTransparency(self);
    BOOL active = self.window.isKeyWindow && self.app.isActive;
    if (reduce != self.windowBackgroundReduceTransparency || active != self.windowBackgroundWindowActive) {
        self.windowBackgroundReduceTransparency = reduce;
        self.windowBackgroundWindowActive = active;
        self.windowBackgroundEnvironmentRevision += 1;
        self.windowBackgroundObservationRevision += 1;
    }
    if (reduce && self.windowBackgroundHostAppliedSystem) {
        self.windowMaterialView.hidden = YES;
        self.windowOpaqueFallbackView.hidden = NO;
        self.windowBackgroundHostAppliedSystem = NO;
        self.windowBackgroundActualMode = 2;
        self.windowBackgroundFallbackReason = 2;
        self.windowBackgroundObservationRevision += 1;
    }
    CjguiPublishWindowBackgroundSnapshot(self);
}

- (void)windowDidResize:(NSNotification *)notification {
    (void)notification;
    CjguiBumpCoordinateLifetimeForSession(self);
    CjguiTraceWindowInputGeometry(self, "resize", NSApp.currentEvent);
    [self windowGeometryDidChange];
}

- (void)windowDidMove:(NSNotification *)notification {
    if(notification.object!=self.window) return;
    CjguiBumpCoordinateLifetimeForSession(self);
}

- (void)windowWillStartLiveResize:(NSNotification *)notification {
    (void)notification;
    CjguiTraceWindowInputGeometry(self, "live_begin", NSApp.currentEvent);
}

- (void)windowDidEndLiveResize:(NSNotification *)notification {
    (void)notification;
    CjguiTraceWindowInputGeometry(self, "live_end", NSApp.currentEvent);
}

- (void)windowDidChangeBackingProperties:(NSNotification *)notification {
    if (notification.object != self.window) return;
    CjguiBumpCoordinateLifetimeForSession(self);
    [self windowGeometryDidChange];
}

- (void)windowGeometryDidChange {
    [self.view updateDrawableSize];
    NSSize points = self.view.bounds.size;
    CGSize pixels = self.view.metalLayer.drawableSize;
    CGFloat scale = [self.view currentBackingScale];
    if (self.hasObservedGeometry && NSEqualSizes(self.observedPointSize, points) &&
        CGSizeEqualToSize(self.observedDrawableSize, pixels) && self.observedBackingScale == scale) return;
    self.hasObservedGeometry = YES;
    self.observedPointSize = points;
    self.observedDrawableSize = pixels;
    self.observedBackingScale = scale;
    self.resizeVersion += 1;
    CjguiPublishViewportSnapshot(self);
    if (self.composableSceneOverlay) {
        (void)CjguiEnqueueComposableInteraction(self, CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_RESIZED,
                                                0, @"", NSMakeRange(0, 0));
    }
}

@end

// The fixed session table is also the only application-domain membership
// index. Resource helpers use it for bounded, non-retaining inspection of
// live sessions; no process-global application-data dictionary is created.
static CJGuiInternalSession *gCjguiSessions[4];
static BOOL gCjguiSessionOccupied[4];
static _Atomic(uint64_t) gCjguiCoordinateSessionGeneration[4];
// One immutable, NUL-terminated payload from the actual native dequeue per
// session. Reading it has no AppKit work and must not queue behind drawing.
// The slot and the calling thread each retain the same NSData, without a
// second body copy. A thread borrow lasts until its next getter or teardown.
static pthread_mutex_t gCjguiFormTextSnapshotLock = PTHREAD_MUTEX_INITIALIZER;
static NSData *gCjguiFormTextSnapshots[4];
static uint64_t gCjguiFormTextSnapshotGenerations[4];
static pthread_once_t gCjguiFormTextBorrowOnce = PTHREAD_ONCE_INIT;
static pthread_key_t gCjguiFormTextBorrowKey;
static BOOL gCjguiFormTextBorrowKeyValid;

static void CjguiReleaseFormTextBorrow(void *bytes) {
    if (bytes) CFRelease((CFDataRef)bytes);
}

static void CjguiCreateFormTextBorrowKey(void) {
    gCjguiFormTextBorrowKeyValid = pthread_key_create(&gCjguiFormTextBorrowKey,
        CjguiReleaseFormTextBorrow) == 0;
}

static void CjguiPublishPumpedFormText(CJGuiInternalSession *ctx) {
    if (!ctx || !ctx.rendererSessionToken || ctx.rendererSessionToken > kCjguiSessionCapacity) return;
    NSUInteger index = (NSUInteger)(ctx.rendererSessionToken - 1);
    pthread_mutex_lock(&gCjguiFormTextSnapshotLock);
    gCjguiFormTextSnapshots[index] = ctx.pumpedFormTextUtf8;
    gCjguiFormTextSnapshotGenerations[index] = ctx.sessionGeneration;
    pthread_mutex_unlock(&gCjguiFormTextSnapshotLock);
}

static void CjguiClearFormTextSnapshot(NSUInteger index) {
    if (index >= kCjguiSessionCapacity) return;
    pthread_mutex_lock(&gCjguiFormTextSnapshotLock);
    gCjguiFormTextSnapshots[index] = nil;
    gCjguiFormTextSnapshotGenerations[index] = 0;
    pthread_mutex_unlock(&gCjguiFormTextSnapshotLock);
}
static _Atomic(uint64_t) gCjguiCoordinateEpoch[4];
static _Atomic(uint64_t) gCjguiMainPumpedPointerSessionGeneration[4];
static _Atomic(uint64_t) gCjguiMainPumpedPointerCoordinateEpoch[4];
static _Atomic(uint64_t) gCjguiOwnerConsumedPointerSessionGeneration[4];
static _Atomic(uint64_t) gCjguiOwnerConsumedPointerCoordinateEpoch[4];
// Selection transfer has one fixed atomic decision cell per native session.
// The small slot lock protects only its scalar tag/reference metadata; the
// decision itself remains one acquire/release word shared with input admission.
enum { kCjguiSelectionTransferCancelBit = 1u << 8 };
typedef struct CjguiSelectionTransferCell {
    atomic_flag metadataLock;
    uint64_t sessionGeneration;
    uint64_t transferId;
    _Atomic(uint64_t) decision;
    uint32_t references;
    BOOL installedProof; // Set only by exact main-thread B readback, before the terminal CAS.
    BOOL restoredProof; // Exact A readback, required before reopening input after installation.
    CjguiInternalSelectionTransferReceipt candidateSceneReceipt; // Immutable actual terminal; no AppKit read on ACK.
} CjguiSelectionTransferCell;
static CjguiSelectionTransferCell gCjguiSelectionTransferCells[4] = {
    {.metadataLock = ATOMIC_FLAG_INIT}, {.metadataLock = ATOMIC_FLAG_INIT},
    {.metadataLock = ATOMIC_FLAG_INIT}, {.metadataLock = ATOMIC_FLAG_INIT},
};
static _Atomic(uint64_t) gCjguiNextSelectionTransferId = 1;
typedef struct CjguiOwnerConsumedPointerGeometrySnapshot {
    uint64_t sessionGeneration;
    uint64_t ownerThreadId;
    CjguiInternalRendererPointerEventGeometry geometry;
} CjguiOwnerConsumedPointerGeometrySnapshot;
static CjguiOwnerConsumedPointerGeometrySnapshot gCjguiOwnerConsumedPointerGeometry[4];
static pthread_mutex_t gCjguiOwnerConsumedPointerGeometryLock = PTHREAD_MUTEX_INITIALIZER;
typedef struct CjguiWindowBackgroundSnapshotEntry {
    uint64_t sessionGeneration;
    BOOL valid;
    CjguiInternalRendererWindowBackgroundSnapshot value;
} CjguiWindowBackgroundSnapshotEntry;
static CjguiWindowBackgroundSnapshotEntry gCjguiWindowBackgroundSnapshots[4];
static pthread_mutex_t gCjguiWindowBackgroundSnapshotLock = PTHREAD_MUTEX_INITIALIZER;
typedef struct CjguiViewportSnapshotEntry {
    uint64_t sessionGeneration;
    BOOL valid;
    CjguiInternalRendererViewport value;
} CjguiViewportSnapshotEntry;
static CjguiViewportSnapshotEntry gCjguiViewportSnapshots[4];
static pthread_mutex_t gCjguiViewportSnapshotLock = PTHREAD_MUTEX_INITIALIZER;
// Main publishes copied scalars; readers never inspect AppKit objects or
// borrow a session pointer. Slots are reused only under a generation check.
typedef struct CjguiDiagnosticScalarSnapshotEntry {
    uint64_t sessionGeneration;
    BOOL valid;
    CjguiInternalRendererComposableDisplayProgress progress;
    CjguiInternalRendererDiagnosticWorkload workload;
    CjguiInternalRendererDiagnosticTiming timing;
} CjguiDiagnosticScalarSnapshotEntry;
static CjguiDiagnosticScalarSnapshotEntry gCjguiDiagnosticScalarSnapshots[4];
static pthread_mutex_t gCjguiDiagnosticScalarSnapshotLock = PTHREAD_MUTEX_INITIALIZER;
typedef struct CjguiWorkloadAttemptCountsEntry {
    BOOL valid;
    CjguiInternalRendererWorkloadAttemptCounts counts;
} CjguiWorkloadAttemptCountsEntry;
static CjguiWorkloadAttemptCountsEntry gCjguiWorkloadAttemptCounts[4];
static pthread_mutex_t gCjguiWorkloadAttemptCountsLock = PTHREAD_MUTEX_INITIALIZER;

static void CjguiPublishWorkloadAttemptCounts(CJGuiInternalSession *ctx) {
    if (!ctx || ctx.destroyed || !ctx.rendererSessionToken ||
        ctx.rendererSessionToken > kCjguiSessionCapacity || !ctx.sessionGeneration) return;
    NSUInteger index = (NSUInteger)(ctx.rendererSessionToken - 1);
    CjguiInternalRendererWorkloadAttemptCounts counts = {
        ctx.sessionGeneration, ctx.composableSceneNodeUpdateCount,
        ctx.composableSceneCloneCount, ctx.composableSceneNodeAllocationCount,
        ctx.composableTextLayoutPreparationCount, ctx.composableImageDecodeStartCount
    };
    pthread_mutex_lock(&gCjguiWorkloadAttemptCountsLock);
    if (atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index], memory_order_acquire) ==
        counts.sessionGeneration)
        gCjguiWorkloadAttemptCounts[index] = (CjguiWorkloadAttemptCountsEntry){YES, counts};
    pthread_mutex_unlock(&gCjguiWorkloadAttemptCountsLock);
}

static void CjguiClearWorkloadAttemptCounts(NSUInteger index, uint64_t expectedGeneration) {
    if (index >= kCjguiSessionCapacity) return;
    pthread_mutex_lock(&gCjguiWorkloadAttemptCountsLock);
    CjguiWorkloadAttemptCountsEntry *entry = &gCjguiWorkloadAttemptCounts[index];
    if (!expectedGeneration || entry->counts.sessionGeneration == expectedGeneration)
        *entry = (CjguiWorkloadAttemptCountsEntry){0};
    pthread_mutex_unlock(&gCjguiWorkloadAttemptCountsLock);
}

CjguiInternalRendererStatus cjgui_internal_renderer_workload_attempt_counts(uint64_t session,
    uint64_t expectedGeneration, CjguiInternalRendererWorkloadAttemptCounts *outCounts) {
    if (!outCounts) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    *outCounts = (CjguiInternalRendererWorkloadAttemptCounts){0};
    if (!session || session > kCjguiSessionCapacity) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    NSUInteger index = (NSUInteger)(session - 1);
    pthread_mutex_lock(&gCjguiWorkloadAttemptCountsLock);
    uint64_t live = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index], memory_order_acquire);
    CjguiWorkloadAttemptCountsEntry entry = gCjguiWorkloadAttemptCounts[index];
    pthread_mutex_unlock(&gCjguiWorkloadAttemptCountsLock);
    if (!live || (expectedGeneration && expectedGeneration != live))
        return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    if (!entry.valid || entry.counts.sessionGeneration != live)
        return CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED;
    if (atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index], memory_order_acquire) != live)
        return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    *outCounts = entry.counts;
    return CJGUI_INTERNAL_RENDERER_OK;
}
typedef struct CjguiConsumedActivationPrefix {
    uint64_t ownerThreadId;
    CjguiInternalActivationPrefix value;
} CjguiConsumedActivationPrefix;
static CjguiConsumedActivationPrefix gCjguiConsumedActivationPrefixes[4];
typedef struct CjguiPointerStreamSnapshot {
    _Atomic(uint64_t) version;
    _Atomic(uint64_t) sessionGeneration;
    _Atomic(uint64_t) bindingEpoch;
    _Atomic(uint64_t) firstSequence;
    _Atomic(uint64_t) lastSequence;
    _Atomic(uint64_t) previousSequence;
    _Atomic(uint32_t) phase;
} CjguiPointerStreamSnapshot;
static CjguiPointerStreamSnapshot gCjguiMainPumpedPointerStreams[4];
static CjguiPointerStreamSnapshot gCjguiOwnerConsumedPointerStreams[4];
// At most the bounded event FIFO plus its in-flight owner ticket can pin old
// accepted frames. This stores receipts only; the existing FIFO owns events.
enum { kCjguiPointerBeginOriginCapacity = 66 };
typedef struct CjguiPointerBeginOriginSlot {
    uint64_t generation;
    uint64_t latestGestureEpoch;
    uint64_t publishedSource;
    uint64_t publishedScene;
    CjguiInternalRendererPointerBeginOrigin entries[kCjguiPointerBeginOriginCapacity];
} CjguiPointerBeginOriginSlot;
static CjguiPointerBeginOriginSlot gCjguiPointerBeginOrigins[4];
static pthread_mutex_t gCjguiPointerBeginOriginsLock = PTHREAD_MUTEX_INITIALIZER;
static void CjguiClearPointerBeginOriginsForSlot(NSUInteger index) {
    if (index >= kCjguiSessionCapacity) return;
    pthread_mutex_lock(&gCjguiPointerBeginOriginsLock);
    memset(&gCjguiPointerBeginOrigins[index], 0, sizeof(gCjguiPointerBeginOrigins[index]));
    pthread_mutex_unlock(&gCjguiPointerBeginOriginsLock);
}

static BOOL CjguiRetainPointerBeginOrigin(uint64_t session,
    CjguiInternalRendererPointerBeginOrigin origin) {
    if (!session || session > kCjguiSessionCapacity || !origin.sessionGeneration ||
        !origin.coordinateEpoch || !origin.gestureEpoch || !origin.sceneVersion || !origin.nodeId)
        return NO;
    NSUInteger index = (NSUInteger)(session - 1);
    pthread_mutex_lock(&gCjguiPointerBeginOriginsLock);
    CjguiPointerBeginOriginSlot *slot = &gCjguiPointerBeginOrigins[index];
    uint64_t live = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index], memory_order_acquire);
    if (slot->generation != live) {
        memset(slot, 0, sizeof(*slot)); slot->generation = live;
    }
    BOOL retained = NO;
    if (live == origin.sessionGeneration && origin.gestureEpoch > slot->latestGestureEpoch) {
        origin.sourcePublication = slot->publishedSource;
        for (NSUInteger i = 0; i < kCjguiPointerBeginOriginCapacity; ++i) {
            if (slot->entries[i].gestureEpoch) continue;
            slot->entries[i] = origin;
            slot->latestGestureEpoch = origin.gestureEpoch;
            retained = YES; break;
        }
    }
    pthread_mutex_unlock(&gCjguiPointerBeginOriginsLock);
    return retained;
}
CjguiInternalRendererStatus cjgui_internal_renderer_publish_pointer_begin_source(uint64_t session,
    uint64_t generation, uint64_t publication, uint64_t sceneVersion) {
    if (!session || session > kCjguiSessionCapacity || !generation || !publication || !sceneVersion)
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    NSUInteger index = (NSUInteger)(session - 1);
    pthread_mutex_lock(&gCjguiPointerBeginOriginsLock);
    CjguiPointerBeginOriginSlot *slot = &gCjguiPointerBeginOrigins[index];
    uint64_t live = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index], memory_order_acquire);
    CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    if (live == generation) {
        if (slot->generation != live) {
            memset(slot, 0, sizeof(*slot)); slot->generation = live;
        }
        if (publication > slot->publishedSource && sceneVersion >= slot->publishedScene) {
            slot->publishedSource = publication;
            slot->publishedScene = sceneVersion;
            status = CJGUI_INTERNAL_RENDERER_OK;
        }
    }
    pthread_mutex_unlock(&gCjguiPointerBeginOriginsLock);
    return status;
}
int cjgui_internal_renderer_pointer_begin_frame_retained(uint64_t session, uint64_t publication) {
    if (!session || session > kCjguiSessionCapacity || !publication) return 0;
    NSUInteger index = (NSUInteger)(session - 1);
    pthread_mutex_lock(&gCjguiPointerBeginOriginsLock);
    CjguiPointerBeginOriginSlot *slot = &gCjguiPointerBeginOrigins[index];
    uint64_t live = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index], memory_order_acquire);
    BOOL retained = NO;
    if (live && slot->generation == live) {
        for (NSUInteger i = 0; i < kCjguiPointerBeginOriginCapacity; ++i) {
            if (slot->entries[i].gestureEpoch && slot->entries[i].sourcePublication == publication) {
                retained = YES; break;
            }
        }
    }
    pthread_mutex_unlock(&gCjguiPointerBeginOriginsLock);
    return retained;
}
CjguiInternalRendererStatus cjgui_internal_renderer_consume_pointer_begin_origin(uint64_t session,
    uint64_t gestureEpoch, CjguiInternalRendererPointerBeginOrigin *outOrigin) {
    if (!outOrigin) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    memset(outOrigin, 0, sizeof(*outOrigin));
    uint64_t generation = 0, binding = 0, first = 0, last = 0, previous = 0;
    uint32_t phase = 0;
    if (!gestureEpoch || !cjgui_internal_renderer_owner_consumed_pointer_fifo(session,
            &generation, &binding, &first, &last, &previous, &phase) ||
        binding != gestureEpoch || first != 1 || last != 1 || previous != 0 ||
        phase != CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_BEGIN)
        return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    NSUInteger index = (NSUInteger)(session - 1);
    pthread_mutex_lock(&gCjguiPointerBeginOriginsLock);
    CjguiPointerBeginOriginSlot *slot = &gCjguiPointerBeginOrigins[index];
    CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    uint64_t live = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index], memory_order_acquire);
    if (live == generation && slot->generation == live) {
        for (NSUInteger i = 0; i < kCjguiPointerBeginOriginCapacity; ++i) {
            CjguiInternalRendererPointerBeginOrigin origin = slot->entries[i];
            if (origin.gestureEpoch != gestureEpoch) continue;
            memset(&slot->entries[i], 0, sizeof(slot->entries[i]));
            if (origin.sessionGeneration == generation && slot->latestGestureEpoch == gestureEpoch) {
                *outOrigin = origin; status = CJGUI_INTERNAL_RENDERER_OK;
            }
            break;
        }
    }
    pthread_mutex_unlock(&gCjguiPointerBeginOriginsLock);
    return status;
}

typedef struct CjguiInputProvenanceSnapshot {
    _Atomic(uint64_t) version;
    _Atomic(uint64_t) sessionGeneration;
    _Atomic(uint64_t) sequence;
    _Atomic(uint64_t) previousSequence;
    _Atomic(uint32_t) eventKind;
} CjguiInputProvenanceSnapshot;
static CjguiInputProvenanceSnapshot gCjguiMainPumpedInputProvenance[4];
static CjguiInputProvenanceSnapshot gCjguiOwnerConsumedInputProvenance[4];
// A source-only, owner-issued gate closes admission before the next AppKit
// callback, without another dispatch hop. It never changes the event FIFO.
static _Atomic(uint64_t) gCjguiSourceInstallRequest[4];
static _Atomic(uint64_t) gCjguiSourceInstallEpoch[4];
static _Atomic(bool) gCjguiMainThreadDispatchEnabled;

static void CjguiLockSelectionTransferCell(CjguiSelectionTransferCell *cell) {
    while (atomic_flag_test_and_set_explicit(&cell->metadataLock, memory_order_acquire)) { }
}

static void CjguiUnlockSelectionTransferCell(CjguiSelectionTransferCell *cell) {
    atomic_flag_clear_explicit(&cell->metadataLock, memory_order_release);
}

static uint32_t CjguiSelectionTransferStateOf(uint64_t word) {
    return (uint32_t)(word & 0xffu);
}

static uint8_t CjguiSelectionTransferCancelled(uint64_t word) {
    return (word & kCjguiSelectionTransferCancelBit) != 0 ? 1u : 0u;
}

static BOOL CjguiSelectionTransferCellMatchesLocked(CjguiSelectionTransferCell *cell,
    uint64_t session, uint64_t transferId) {
    if (!cell || !session || session > kCjguiSessionCapacity || !transferId) return NO;
    uint64_t generation = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[session - 1],
        memory_order_acquire);
    return generation && cell->sessionGeneration == generation && cell->transferId == transferId;
}

static uint64_t CjguiNextSelectionTransferId(void) {
    uint64_t value = atomic_load_explicit(&gCjguiNextSelectionTransferId, memory_order_relaxed);
    for (;;) {
        if (!value || value == UINT64_MAX) return 0;
        if (atomic_compare_exchange_weak_explicit(&gCjguiNextSelectionTransferId, &value, value + 1,
            memory_order_relaxed, memory_order_relaxed)) return value;
    }
}

CjguiInternalRendererStatus cjgui_internal_renderer_selection_transfer_create(
    uint64_t session, uint64_t *outTransferId) {
    if (outTransferId) *outTransferId = 0;
    if (!outTransferId || !session || session > kCjguiSessionCapacity)
        return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    NSUInteger index = (NSUInteger)(session - 1);
    uint64_t generation = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index], memory_order_acquire);
    if (!generation) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    CjguiSelectionTransferCell *cell = &gCjguiSelectionTransferCells[index];
    CjguiLockSelectionTransferCell(cell);
    uint64_t oldWord = atomic_load_explicit(&cell->decision, memory_order_acquire);
    uint32_t oldState = CjguiSelectionTransferStateOf(oldWord);
    if (cell->sessionGeneration != generation || cell->references != 0 ||
        (oldState != CJGUI_SELECTION_TRANSFER_EMPTY && oldState != CJGUI_SELECTION_TRANSFER_COMMITTED &&
         oldState != CJGUI_SELECTION_TRANSFER_ABORTED)) {
        CjguiUnlockSelectionTransferCell(cell);
        return CJGUI_INTERNAL_RENDERER_PRESENT_PENDING;
    }
    uint64_t transferId = CjguiNextSelectionTransferId();
    if (!transferId) {
        CjguiUnlockSelectionTransferCell(cell);
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    cell->transferId = transferId;
    cell->references = 2; // owner descriptor + native capsule
    cell->installedProof = NO;
    cell->restoredProof = NO;
    atomic_store_explicit(&cell->decision, CJGUI_SELECTION_TRANSFER_PREPARING, memory_order_release);
    *outTransferId = transferId;
    CjguiUnlockSelectionTransferCell(cell);
    return CJGUI_INTERNAL_RENDERER_OK;
}

static CjguiInternalRendererStatus CjguiSelectionTransferTransition(uint64_t session,
    uint64_t transferId, uint32_t expectedState, uint32_t nextState, BOOL requireNoCancel) {
    if (!session || session > kCjguiSessionCapacity || !transferId)
        return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    CjguiSelectionTransferCell *cell = &gCjguiSelectionTransferCells[session - 1];
    CjguiLockSelectionTransferCell(cell);
    if (!CjguiSelectionTransferCellMatchesLocked(cell, session, transferId)) {
        CjguiUnlockSelectionTransferCell(cell);
        return CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED;
    }
    uint64_t word = atomic_load_explicit(&cell->decision, memory_order_acquire);
    if (CjguiSelectionTransferStateOf(word) != expectedState ||
        (requireNoCancel && CjguiSelectionTransferCancelled(word))) {
        CjguiUnlockSelectionTransferCell(cell);
        return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    }
    atomic_store_explicit(&cell->decision, (word & kCjguiSelectionTransferCancelBit) | nextState,
        memory_order_release);
    CjguiUnlockSelectionTransferCell(cell);
    return CJGUI_INTERNAL_RENDERER_OK;
}

static CjguiInternalRendererStatus CjguiSelectionTransferBeginFinalizingWithPrecheck(
    uint64_t session, uint64_t transferId);

CjguiInternalRendererStatus cjgui_internal_renderer_selection_transfer_publish_pending(
    uint64_t session, uint64_t transferId) {
    return CjguiSelectionTransferTransition(session, transferId,
        CJGUI_SELECTION_TRANSFER_PREPARING, CJGUI_SELECTION_TRANSFER_PENDING, YES);
}

CjguiInternalRendererStatus cjgui_internal_renderer_selection_transfer_begin_finalizing(
    uint64_t session, uint64_t transferId) {
#ifdef CJGUI_INTERNAL_TESTING
    // Split finalization is retained only as a state-machine test seam.
    // Production must use install_b so FINALIZING cannot span an event turn.
    return CjguiSelectionTransferBeginFinalizingWithPrecheck(session, transferId);
#else
    (void)session;
    (void)transferId;
    return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
#endif
}

CjguiInternalRendererStatus cjgui_internal_renderer_selection_transfer_request_cancel(
    uint64_t session, uint64_t transferId) {
    if (!session || session > kCjguiSessionCapacity || !transferId)
        return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    CjguiSelectionTransferCell *cell = &gCjguiSelectionTransferCells[session - 1];
    CjguiLockSelectionTransferCell(cell);
    if (!CjguiSelectionTransferCellMatchesLocked(cell, session, transferId)) {
        CjguiUnlockSelectionTransferCell(cell);
        return CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED;
    }
    uint64_t word = atomic_load_explicit(&cell->decision, memory_order_acquire);
    uint32_t state = CjguiSelectionTransferStateOf(word);
    if (state != CJGUI_SELECTION_TRANSFER_PENDING && state != CJGUI_SELECTION_TRANSFER_FINALIZING) {
        CjguiUnlockSelectionTransferCell(cell);
        return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    }
    atomic_fetch_or_explicit(&cell->decision, kCjguiSelectionTransferCancelBit, memory_order_acq_rel);
    CjguiUnlockSelectionTransferCell(cell);
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus cjgui_internal_renderer_selection_transfer_commit(
    uint64_t session, uint64_t transferId) {
    if (!session || session > kCjguiSessionCapacity || !transferId)
        return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    CjguiSelectionTransferCell *cell = &gCjguiSelectionTransferCells[session - 1];
    CjguiLockSelectionTransferCell(cell);
    uint64_t word = atomic_load_explicit(&cell->decision, memory_order_acquire);
    BOOL valid = CjguiSelectionTransferCellMatchesLocked(cell, session, transferId) &&
        cell->installedProof && CjguiSelectionTransferStateOf(word) == CJGUI_SELECTION_TRANSFER_FINALIZING &&
        !CjguiSelectionTransferCancelled(word);
    if (valid) atomic_store_explicit(&cell->decision, CJGUI_SELECTION_TRANSFER_COMMITTED, memory_order_release);
    CjguiUnlockSelectionTransferCell(cell);
    return valid ? CJGUI_INTERNAL_RENDERER_OK : CJGUI_INTERNAL_RENDERER_SCENE_STALE;
}

CjguiInternalRendererStatus cjgui_internal_renderer_selection_transfer_finish_abort(
    uint64_t session, uint64_t transferId) {
    if (!session || session > kCjguiSessionCapacity || !transferId)
        return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    CjguiSelectionTransferCell *cell = &gCjguiSelectionTransferCells[session - 1];
    CjguiLockSelectionTransferCell(cell);
    if (!CjguiSelectionTransferCellMatchesLocked(cell, session, transferId)) {
        CjguiUnlockSelectionTransferCell(cell);
        return CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED;
    }
    uint64_t word = atomic_load_explicit(&cell->decision, memory_order_acquire);
    uint32_t state = CjguiSelectionTransferStateOf(word);
    if (state != CJGUI_SELECTION_TRANSFER_PENDING &&
        !((state == CJGUI_SELECTION_TRANSFER_FINALIZING || state == CJGUI_SELECTION_TRANSFER_RECOVERY_BLOCKED)
          && cell->restoredProof)) {
        CjguiUnlockSelectionTransferCell(cell);
        return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    }
    atomic_store_explicit(&cell->decision,
        (word & kCjguiSelectionTransferCancelBit) | CJGUI_SELECTION_TRANSFER_ABORTED,
        memory_order_release);
    CjguiUnlockSelectionTransferCell(cell);
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus cjgui_internal_renderer_selection_transfer_recovery_blocked(
    uint64_t session, uint64_t transferId) {
    return CjguiSelectionTransferTransition(session, transferId,
        CJGUI_SELECTION_TRANSFER_FINALIZING, CJGUI_SELECTION_TRANSFER_RECOVERY_BLOCKED, NO);
}

CjguiInternalRendererStatus cjgui_internal_renderer_selection_transfer_state(
    uint64_t session, uint64_t transferId, uint32_t *outState, uint8_t *outCancelled,
    uint32_t *outReferences) {
    if (outState) *outState = CJGUI_SELECTION_TRANSFER_EMPTY;
    if (outCancelled) *outCancelled = 0;
    if (outReferences) *outReferences = 0;
    if (!outState || !outCancelled || !outReferences || !session ||
        session > kCjguiSessionCapacity || !transferId) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    CjguiSelectionTransferCell *cell = &gCjguiSelectionTransferCells[session - 1];
    CjguiLockSelectionTransferCell(cell);
    if (!CjguiSelectionTransferCellMatchesLocked(cell, session, transferId)) {
        CjguiUnlockSelectionTransferCell(cell);
        return CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED;
    }
    uint64_t word = atomic_load_explicit(&cell->decision, memory_order_acquire);
    *outState = CjguiSelectionTransferStateOf(word);
    *outCancelled = CjguiSelectionTransferCancelled(word);
    *outReferences = cell->references;
    CjguiUnlockSelectionTransferCell(cell);
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus cjgui_internal_renderer_selection_transfer_admit_input(
    uint64_t session, uint64_t transferId, uint32_t *outAdmission) {
    if (outAdmission) *outAdmission = CJGUI_SELECTION_INPUT_STALE;
    if (!outAdmission || !session || session > kCjguiSessionCapacity || !transferId)
        return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    CjguiSelectionTransferCell *cell = &gCjguiSelectionTransferCells[session - 1];
    CjguiLockSelectionTransferCell(cell);
    if (!CjguiSelectionTransferCellMatchesLocked(cell, session, transferId)) {
        CjguiUnlockSelectionTransferCell(cell);
        return CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED;
    }
    uint64_t word = atomic_load_explicit(&cell->decision, memory_order_acquire);
    uint32_t state = CjguiSelectionTransferStateOf(word);
    if (state == CJGUI_SELECTION_TRANSFER_PREPARING) {
        atomic_store_explicit(&cell->decision, CJGUI_SELECTION_TRANSFER_ABORTED, memory_order_release);
        *outAdmission = CJGUI_SELECTION_INPUT_ALLOW;
    } else if (state == CJGUI_SELECTION_TRANSFER_PENDING) {
        atomic_store_explicit(&cell->decision,
            (word & kCjguiSelectionTransferCancelBit) | CJGUI_SELECTION_TRANSFER_ABORTED,
            memory_order_release);
        *outAdmission = CJGUI_SELECTION_INPUT_ALLOW;
    } else if (state == CJGUI_SELECTION_TRANSFER_FINALIZING) {
        atomic_fetch_or_explicit(&cell->decision, kCjguiSelectionTransferCancelBit, memory_order_acq_rel);
        *outAdmission = CJGUI_SELECTION_INPUT_RETAINED_CANCEL;
    } else if (state == CJGUI_SELECTION_TRANSFER_RECOVERY_BLOCKED) {
        *outAdmission = CJGUI_SELECTION_INPUT_RECOVERY_BLOCKED;
    } else {
        *outAdmission = CJGUI_SELECTION_INPUT_ALLOW;
    }
    CjguiUnlockSelectionTransferCell(cell);
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus cjgui_internal_renderer_selection_transfer_retain(
    uint64_t session, uint64_t transferId) {
    if (!session || session > kCjguiSessionCapacity || !transferId)
        return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    CjguiSelectionTransferCell *cell = &gCjguiSelectionTransferCells[session - 1];
    CjguiLockSelectionTransferCell(cell);
    if (!CjguiSelectionTransferCellMatchesLocked(cell, session, transferId) || !cell->references ||
        cell->references == UINT32_MAX) {
        CjguiUnlockSelectionTransferCell(cell);
        return CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED;
    }
    cell->references += 1;
    CjguiUnlockSelectionTransferCell(cell);
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus cjgui_internal_renderer_selection_transfer_release(
    uint64_t session, uint64_t transferId) {
    if (!session || session > kCjguiSessionCapacity || !transferId)
        return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    CjguiSelectionTransferCell *cell = &gCjguiSelectionTransferCells[session - 1];
    CjguiLockSelectionTransferCell(cell);
    if (!CjguiSelectionTransferCellMatchesLocked(cell, session, transferId) || !cell->references) {
        CjguiUnlockSelectionTransferCell(cell);
        return CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED;
    }
    cell->references -= 1;
    CjguiUnlockSelectionTransferCell(cell);
    return CJGUI_INTERNAL_RENDERER_OK;
}

static void CjguiFillWindowBackgroundSnapshot(CJGuiInternalSession *session,
    CjguiInternalRendererWindowBackgroundSnapshot *outSnapshot) {
    if (!outSnapshot) return;
    *outSnapshot = (CjguiInternalRendererWindowBackgroundSnapshot){0};
    if (!session || session.destroyed) return;
    outSnapshot->acceptedSceneVersion = session.windowBackgroundAcceptedSceneVersion;
    outSnapshot->frameIndex = session.view ? session.view.frameIndex : 0;
    outSnapshot->requestRevision = session.windowBackgroundRequestRevision;
    outSnapshot->environmentRevision = session.windowBackgroundEnvironmentRevision;
    outSnapshot->observationRevision = session.windowBackgroundObservationRevision;
    outSnapshot->requestedMode = session.windowBackgroundRequestedMode;
    outSnapshot->backend = session.windowBackgroundBackend;
    outSnapshot->actualMode = session.windowBackgroundActualMode;
    outSnapshot->fallbackReason = session.windowBackgroundFallbackReason;
    outSnapshot->completion = session.windowBackgroundCompletion;
    outSnapshot->reduceTransparency = session.windowBackgroundReduceTransparency ? 1u : 0u;
    outSnapshot->windowActive = session.windowBackgroundWindowActive ? 1u : 0u;
    outSnapshot->colorScheme = session.windowBackgroundColorScheme;
}

static void CjguiPublishWindowBackgroundSnapshot(CJGuiInternalSession *session) {
    if (!CjguiIsMainThread() || !session || session.destroyed ||
        session.closeRequested ||
        !session.rendererSessionToken || session.rendererSessionToken > kCjguiSessionCapacity ||
        !session.sessionGeneration) return;
    NSUInteger index = (NSUInteger)(session.rendererSessionToken - 1);
    CjguiInternalRendererWindowBackgroundSnapshot value = {0};
    CjguiFillWindowBackgroundSnapshot(session, &value);
    pthread_mutex_lock(&gCjguiWindowBackgroundSnapshotLock);
    uint64_t liveGeneration = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index],
        memory_order_acquire);
    if (liveGeneration == session.sessionGeneration) {
        gCjguiWindowBackgroundSnapshots[index] = (CjguiWindowBackgroundSnapshotEntry){
            .sessionGeneration = session.sessionGeneration,
            .valid = YES,
            .value = value,
        };
    }
    pthread_mutex_unlock(&gCjguiWindowBackgroundSnapshotLock);
}

static void CjguiClearWindowBackgroundSnapshotForSlot(NSUInteger index,
    uint64_t expectedGeneration) {
    if (index >= kCjguiSessionCapacity) return;
    pthread_mutex_lock(&gCjguiWindowBackgroundSnapshotLock);
    CjguiWindowBackgroundSnapshotEntry *entry = &gCjguiWindowBackgroundSnapshots[index];
    if (!expectedGeneration || !entry->sessionGeneration ||
        entry->sessionGeneration == expectedGeneration) {
        *entry = (CjguiWindowBackgroundSnapshotEntry){0};
    }
    pthread_mutex_unlock(&gCjguiWindowBackgroundSnapshotLock);
}

static CjguiInternalRendererStatus CjguiReadWindowBackgroundSnapshot(uint64_t session,
    CjguiInternalRendererWindowBackgroundSnapshot *outSnapshot) {
    if (!outSnapshot) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    *outSnapshot = (CjguiInternalRendererWindowBackgroundSnapshot){0};
    if (!session || session > kCjguiSessionCapacity) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    NSUInteger index = (NSUInteger)(session - 1);
    pthread_mutex_lock(&gCjguiWindowBackgroundSnapshotLock);
    uint64_t liveGeneration = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index],
        memory_order_acquire);
    CjguiWindowBackgroundSnapshotEntry entry = gCjguiWindowBackgroundSnapshots[index];
    if (entry.sessionGeneration != liveGeneration) {
        // The generation is read under this same lock: a stale reader cannot
        // erase a replacement session's already-published snapshot.
        gCjguiWindowBackgroundSnapshots[index] = (CjguiWindowBackgroundSnapshotEntry){0};
    }
    pthread_mutex_unlock(&gCjguiWindowBackgroundSnapshotLock);
    if (!liveGeneration) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    if (!entry.valid || entry.sessionGeneration != liveGeneration)
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    uint64_t liveAfter = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index],
        memory_order_acquire);
    if (liveAfter != liveGeneration) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    *outSnapshot = entry.value;
    return CJGUI_INTERNAL_RENDERER_OK;
}

static void CjguiFillViewportSnapshot(CJGuiInternalSession *session,
    CjguiInternalRendererViewport *outViewport) {
    if (!outViewport) return;
    *outViewport = (CjguiInternalRendererViewport){0};
    if (!session || session.destroyed || !session.view) return;
    outViewport->width = (uint32_t)MAX(0.0, session.view.bounds.size.width);
    outViewport->height = (uint32_t)MAX(0.0, session.view.bounds.size.height);
    outViewport->resizeVersion = session.resizeVersion;
    outViewport->resourceCompletionVersion = session.composableImageResourceCompletionVersion;
}


static void CjguiPublishDiagnosticScalarSnapshot(CJGuiInternalSession *ctx) {
    if (!CjguiIsMainThread() || !ctx || ctx.destroyed || ctx.closeRequested ||
        !ctx.view || !ctx.composableSceneOverlay || !ctx.rendererSessionToken ||
        ctx.rendererSessionToken > kCjguiSessionCapacity || !ctx.sessionGeneration) return;
    cjgui_internal_renderer_owner_trace_boundary(ctx.rendererSessionToken, 0,
        CJGUI_OWNER_PHASE_DIAGNOSTIC_PUBLISH_BEGIN, 0, 0, 0, UINT64_MAX);
    NSUInteger index = (NSUInteger)(ctx.rendererSessionToken - 1);
    CjguiDiagnosticScalarSnapshotEntry entry = {.sessionGeneration = ctx.sessionGeneration, .valid = YES};
    CjguiFillDiagnosticDisplayProgress(ctx, &entry.progress);
    entry.workload.sceneVersion = ctx.composableSceneVersion;
    entry.workload.frameIndex = ctx.view.frameIndex;
    entry.workload.nodeWriteCount = ctx.composableSceneNodeUpdateCount;
    entry.workload.nodeCloneCount = ctx.composableSceneCloneCount;
    entry.workload.nodeAllocationCount = ctx.composableSceneNodeAllocationCount;
    entry.workload.textLayoutPreparationCount = ctx.composableTextLayoutPreparationCount;
    entry.workload.imageDecodeStartCount = ctx.composableImageDecodeStartCount;
    entry.workload.textRasterCount = ctx.view.textRasterCount;
    entry.workload.textRasterBytes = ctx.view.textRasterBytes;
    entry.workload.textUploadCount = ctx.view.textUploadCount;
    entry.workload.textUploadBytes = ctx.view.textUploadBytes;
    entry.workload.textCandidatePeakBytes = ctx.composableTextCandidatePeakBytes;

    // These two byte totals require traversing nodes/caches in the fresh
    // diagnostic getter. They are explicitly unavailable in the scalar API.
    entry.workload.reusableResourceBytes = UINT64_MAX;
    entry.workload.textTextureLiveBytes = UINT64_MAX;
    entry.timing.sceneVersion = ctx.composableSceneVersion;
    entry.timing.frameIndex = ctx.view.frameIndex;
    entry.timing.enabled = ctx.diagnosticTimingEnabled ? 1u : 0u;
    entry.timing.clockAvailable = ctx.diagnosticTimingEnabled ? 1u : 0u;
    entry.timing.positionPrepareCount = ctx.positionPrepareCount;
    entry.timing.positionQueryCount = ctx.positionQueryCount;
    entry.timing.positionLineBuildCount = ctx.positionLineBuildCount;
    entry.timing.positionCacheHitCount = ctx.positionCacheHitCount;
    entry.timing.positionPrepareNanoseconds = ctx.positionPrepareNanoseconds;
    entry.timing.positionQueryNanoseconds = ctx.positionQueryNanoseconds;
    entry.timing.positionLineBuildNanoseconds = ctx.positionLineBuildNanoseconds;
    entry.timing.encodeNanoseconds = ctx.diagnosticEncodeNanoseconds;
    entry.timing.submitNanoseconds = ctx.diagnosticSubmitNanoseconds;
    entry.timing.rasterNanoseconds = ctx.diagnosticRasterNanoseconds;
    entry.timing.uploadNanoseconds = ctx.diagnosticUploadNanoseconds;
    entry.timing.readCount = ctx.diagnosticReadCount;
    entry.timing.readNanoseconds = ctx.diagnosticReadNanoseconds;

    pthread_mutex_lock(&gCjguiDiagnosticScalarSnapshotLock);
    uint64_t live = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index], memory_order_acquire);
    if (live == entry.sessionGeneration) gCjguiDiagnosticScalarSnapshots[index] = entry;
    pthread_mutex_unlock(&gCjguiDiagnosticScalarSnapshotLock);
    cjgui_internal_renderer_owner_trace_boundary(ctx.rendererSessionToken, 0,
        CJGUI_OWNER_PHASE_DIAGNOSTIC_PUBLISH_END, 0, 0, 0, UINT64_MAX);
}

static void CjguiClearDiagnosticScalarSnapshot(NSUInteger index, uint64_t expectedGeneration) {
    if (index >= kCjguiSessionCapacity) return;
    pthread_mutex_lock(&gCjguiDiagnosticScalarSnapshotLock);
    CjguiDiagnosticScalarSnapshotEntry *entry = &gCjguiDiagnosticScalarSnapshots[index];
    if (!expectedGeneration || !entry->sessionGeneration || entry->sessionGeneration == expectedGeneration)
        *entry = (CjguiDiagnosticScalarSnapshotEntry){0};
    pthread_mutex_unlock(&gCjguiDiagnosticScalarSnapshotLock);
}

static CjguiInternalRendererStatus CjguiReadDiagnosticScalarSnapshot(uint64_t session,
    uint64_t expectedGeneration, uint64_t expectedSceneVersion,
    CjguiInternalRendererComposableDisplayProgress *outProgress,
    CjguiInternalRendererDiagnosticWorkload *outWorkload,
    CjguiInternalRendererDiagnosticTiming *outTiming) {
    if (!outProgress || !outWorkload || !outTiming) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    *outProgress = (CjguiInternalRendererComposableDisplayProgress){0};
    *outWorkload = (CjguiInternalRendererDiagnosticWorkload){0};
    *outTiming = (CjguiInternalRendererDiagnosticTiming){0};
    if (!session || session > kCjguiSessionCapacity || !expectedGeneration)
        return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    NSUInteger index = (NSUInteger)(session - 1);
    pthread_mutex_lock(&gCjguiDiagnosticScalarSnapshotLock);
    uint64_t live = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index], memory_order_acquire);
    CjguiDiagnosticScalarSnapshotEntry entry = gCjguiDiagnosticScalarSnapshots[index];
    // Only clear a genuinely old entry, never a replacement generation.
    if (entry.sessionGeneration != live) gCjguiDiagnosticScalarSnapshots[index] = (CjguiDiagnosticScalarSnapshotEntry){0};
    pthread_mutex_unlock(&gCjguiDiagnosticScalarSnapshotLock);
    if (!live || live != expectedGeneration) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    if (!entry.valid || entry.sessionGeneration != live) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    if (entry.workload.sceneVersion != expectedSceneVersion || entry.timing.sceneVersion != expectedSceneVersion)
        return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    if (entry.workload.frameIndex != entry.progress.submittedFrameIndex ||
        entry.timing.frameIndex != entry.progress.submittedFrameIndex)
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    if (atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index], memory_order_acquire) != live)
        return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    *outProgress = entry.progress; *outWorkload = entry.workload; *outTiming = entry.timing;
    return CJGUI_INTERNAL_RENDERER_OK;
}

// Pure observation of the last published state, not an ACK/freshness gate.
CjguiInternalRendererStatus cjgui_internal_renderer_diagnostic_scalar_snapshot(
    uint64_t session, uint64_t expectedGeneration, uint64_t expectedSceneVersion,
    CjguiInternalRendererComposableDisplayProgress *outProgress,
    CjguiInternalRendererDiagnosticWorkload *outWorkload,
    CjguiInternalRendererDiagnosticTiming *outTiming) {
    cjgui_internal_renderer_owner_trace_boundary(session, 0,
        CJGUI_OWNER_PHASE_DIAGNOSTIC_SCALAR_READ_BEGIN, 0, 0, 0, UINT64_MAX);
    CjguiInternalRendererStatus status = CjguiReadDiagnosticScalarSnapshot(session,
        expectedGeneration, expectedSceneVersion, outProgress, outWorkload, outTiming);
    cjgui_internal_renderer_owner_trace_boundary(session, 0,
        CJGUI_OWNER_PHASE_DIAGNOSTIC_SCALAR_READ_END, 0, 0, 0, UINT64_MAX);
    return status;
}

static void CjguiPublishViewportSnapshot(CJGuiInternalSession *session) {
    if (!CjguiIsMainThread() || !session || session.destroyed || session.closeRequested ||
        !session.view || !session.rendererSessionToken ||
        session.rendererSessionToken > kCjguiSessionCapacity || !session.sessionGeneration) return;
    NSUInteger index = (NSUInteger)(session.rendererSessionToken - 1);
    CjguiInternalRendererViewport value = {0};
    CjguiFillViewportSnapshot(session, &value);
    pthread_mutex_lock(&gCjguiViewportSnapshotLock);
    uint64_t liveGeneration = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index],
        memory_order_acquire);
    if (liveGeneration == session.sessionGeneration) {
        gCjguiViewportSnapshots[index] = (CjguiViewportSnapshotEntry){
            .sessionGeneration = session.sessionGeneration,
            .valid = YES,
            .value = value,
        };
    }
    pthread_mutex_unlock(&gCjguiViewportSnapshotLock);
    CjguiPublishDiagnosticScalarSnapshot(session);
}

static void CjguiClearViewportSnapshotForSlot(NSUInteger index, uint64_t expectedGeneration) {
    if (index >= kCjguiSessionCapacity) return;
    CjguiClearDiagnosticScalarSnapshot(index, expectedGeneration);
    pthread_mutex_lock(&gCjguiViewportSnapshotLock);
    CjguiViewportSnapshotEntry *entry = &gCjguiViewportSnapshots[index];
    if (!expectedGeneration || !entry->sessionGeneration ||
        entry->sessionGeneration == expectedGeneration) {
        *entry = (CjguiViewportSnapshotEntry){0};
    }
    pthread_mutex_unlock(&gCjguiViewportSnapshotLock);
}

static CjguiInternalRendererStatus CjguiReadViewportSnapshot(uint64_t session,
    CjguiInternalRendererViewport *outViewport) {
    if (!outViewport) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    *outViewport = (CjguiInternalRendererViewport){0};
    if (!session || session > kCjguiSessionCapacity) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    NSUInteger index = (NSUInteger)(session - 1);
    pthread_mutex_lock(&gCjguiViewportSnapshotLock);
    uint64_t liveGeneration = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index],
        memory_order_acquire);
    CjguiViewportSnapshotEntry entry = gCjguiViewportSnapshots[index];
    if (entry.sessionGeneration != liveGeneration) {
        // The slot and cache share this lock so an old reader cannot erase a
        // snapshot already published for a replacement renderer generation.
        gCjguiViewportSnapshots[index] = (CjguiViewportSnapshotEntry){0};
    }
    pthread_mutex_unlock(&gCjguiViewportSnapshotLock);
    if (!liveGeneration) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    if (!entry.valid || entry.sessionGeneration != liveGeneration)
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    if (atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index], memory_order_acquire) !=
        liveGeneration) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    *outViewport = entry.value;
    return CJGUI_INTERNAL_RENDERER_OK;
}

static void CjguiClearOwnerConsumedPointerGeometryForSlot(NSUInteger index) {
    if (index >= kCjguiSessionCapacity) return;
    pthread_mutex_lock(&gCjguiOwnerConsumedPointerGeometryLock);
    gCjguiOwnerConsumedPointerGeometry[index] =
        (CjguiOwnerConsumedPointerGeometrySnapshot){0};
    gCjguiConsumedActivationPrefixes[index] = (CjguiConsumedActivationPrefix){0};
    pthread_mutex_unlock(&gCjguiOwnerConsumedPointerGeometryLock);
}

static void CjguiClearOwnerConsumedPointerGeometry(uint64_t session) {
    if (!session || session > kCjguiSessionCapacity) return;
    CjguiClearOwnerConsumedPointerGeometryForSlot((NSUInteger)(session - 1));
}

static uint64_t CjguiCurrentNativeThreadId(void) {
    uint64_t threadId = 0;
    if (pthread_threadid_np(NULL, &threadId) != 0 || threadId == 0) return 0;
    return threadId;
}

static void CjguiPublishConsumedActivationPrefix(uint64_t session, uint64_t generation,
    CjguiInternalActivationPrefix prefix) {
    if (!session || session > kCjguiSessionCapacity || !generation) return;
    NSUInteger index = (NSUInteger)(session - 1);
    uint64_t tid = CjguiCurrentNativeThreadId();
    pthread_mutex_lock(&gCjguiOwnerConsumedPointerGeometryLock);
    if (tid && atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index], memory_order_acquire) == generation) {
        gCjguiConsumedActivationPrefixes[index] = (CjguiConsumedActivationPrefix){tid, prefix};
    }
    pthread_mutex_unlock(&gCjguiOwnerConsumedPointerGeometryLock);
}

CjguiInternalRendererStatus cjgui_internal_renderer_consumed_activation_prefix(
    uint64_t session, CjguiInternalActivationPrefix *outPrefix) {
    if (!outPrefix) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    *outPrefix = (CjguiInternalActivationPrefix){0};
    if (!session || session > kCjguiSessionCapacity) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    if (CjguiIsMainThread()) {
        CJGuiInternalSession *ctx = CjguiLookupSession(session);
        if (!ctx || ctx.destroyed) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
        *outPrefix = ctx.pumpedActivationPrefix;
        ctx.pumpedActivationPrefix = (CjguiInternalActivationPrefix){0};
        return CJGUI_INTERNAL_RENDERER_OK;
    }
    NSUInteger index = (NSUInteger)(session - 1);
    uint64_t tid = CjguiCurrentNativeThreadId();
    pthread_mutex_lock(&gCjguiOwnerConsumedPointerGeometryLock);
    uint64_t generation = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index], memory_order_acquire);
    CjguiConsumedActivationPrefix snapshot = gCjguiConsumedActivationPrefixes[index];
    BOOL exact = tid && tid == snapshot.ownerThreadId && generation &&
        (!snapshot.value.nonce || snapshot.value.sessionGeneration == generation);
    if (exact) gCjguiConsumedActivationPrefixes[index] = (CjguiConsumedActivationPrefix){0};
    pthread_mutex_unlock(&gCjguiOwnerConsumedPointerGeometryLock);
    if (!exact || atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index], memory_order_acquire) != generation)
        return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    *outPrefix = snapshot.value;
    return CJGUI_INTERNAL_RENDERER_OK;
}

static void CjguiPublishOwnerConsumedPointerGeometry(uint64_t session,
    uint64_t sessionGeneration, uint64_t ownerThreadId,
    CjguiInternalRendererPointerEventGeometry geometry) {
    if (!session || session > kCjguiSessionCapacity || !sessionGeneration || !ownerThreadId) return;
    NSUInteger index = (NSUInteger)(session - 1);
    uint64_t liveBefore = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index],
        memory_order_acquire);
    if (liveBefore != sessionGeneration) return;
    pthread_mutex_lock(&gCjguiOwnerConsumedPointerGeometryLock);
    uint64_t liveAfter = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index],
        memory_order_acquire);
    if (liveAfter == sessionGeneration) {
        gCjguiOwnerConsumedPointerGeometry[index] =
            (CjguiOwnerConsumedPointerGeometrySnapshot){
                .sessionGeneration = sessionGeneration,
                .ownerThreadId = ownerThreadId,
                .geometry = geometry,
            };
    }
    pthread_mutex_unlock(&gCjguiOwnerConsumedPointerGeometryLock);
}

static BOOL CjguiReadOwnerConsumedPointerGeometry(uint64_t session,
    CjguiInternalRendererPointerEventGeometry *outGeometry) {
    if (!outGeometry || !session || session > kCjguiSessionCapacity) return NO;
    NSUInteger index = (NSUInteger)(session - 1);
    uint64_t ownerThreadId = CjguiCurrentNativeThreadId();
    if (!ownerThreadId) return NO;
    pthread_mutex_lock(&gCjguiOwnerConsumedPointerGeometryLock);
    // Read generation while holding the same lock that protects the snapshot.
    // A getter delayed before this lock must not use an old generation value
    // to erase geometry already published for a replacement owner.
    uint64_t liveGeneration = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index],
        memory_order_acquire);
    CjguiOwnerConsumedPointerGeometrySnapshot snapshot =
        gCjguiOwnerConsumedPointerGeometry[index];
    // One bounded read belongs to the thread that consumed the ticket. A
    // different thread cannot steal it; stale generations are cleared, and
    // the matching owner clears its entry before returning the copy.
    if (snapshot.sessionGeneration != liveGeneration ||
        snapshot.ownerThreadId == ownerThreadId) {
        gCjguiOwnerConsumedPointerGeometry[index] =
            (CjguiOwnerConsumedPointerGeometrySnapshot){0};
    }
    pthread_mutex_unlock(&gCjguiOwnerConsumedPointerGeometryLock);
    uint64_t liveAfter = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index],
        memory_order_acquire);
    if (!liveGeneration || liveGeneration != liveAfter || snapshot.sessionGeneration != liveGeneration ||
        snapshot.ownerThreadId != ownerThreadId) return NO;
    *outGeometry = snapshot.geometry;
    return YES;
}

uint64_t cjgui_internal_renderer_coordinate_lifetime(uint64_t session,uint64_t *outSessionGeneration) {
    if(outSessionGeneration) *outSessionGeneration=0;
    if(!session || session>kCjguiSessionCapacity) return 0;
    NSUInteger index=(NSUInteger)(session-1);
    uint64_t generationBefore=atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index],memory_order_acquire);
    uint64_t epoch=atomic_load_explicit(&gCjguiCoordinateEpoch[index],memory_order_acquire);
    uint64_t generationAfter=atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index],memory_order_acquire);
    if(!generationBefore || generationBefore!=generationAfter || !epoch) return 0;
    if(outSessionGeneration) *outSessionGeneration=generationBefore;
    return epoch;
}

static BOOL CjguiPointerStreamPhase(uint32_t phase) {
    return phase >= CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_BEGIN &&
        phase <= CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_CANCEL;
}

static BOOL CjguiPointerStreamTupleValid(uint64_t sessionGeneration, uint64_t bindingEpoch,
    uint64_t firstSequence, uint64_t lastSequence, uint64_t previousSequence, uint32_t phase) {
    if (!sessionGeneration || !bindingEpoch || !firstSequence || !lastSequence ||
        lastSequence < firstSequence || !CjguiPointerStreamPhase(phase)) return NO;
    if (phase == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_BEGIN)
        return firstSequence == 1 && lastSequence == 1 && previousSequence == 0;
    if (previousSequence == UINT64_MAX || previousSequence + 1 != firstSequence) return NO;
    if (phase != CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_UPDATE)
        return lastSequence == firstSequence;
    return YES;
}

static void CjguiStorePointerStreamSnapshot(CjguiPointerStreamSnapshot *snapshot,
    uint64_t sessionGeneration, uint64_t bindingEpoch, uint64_t firstSequence,
    uint64_t lastSequence, uint64_t previousSequence, uint32_t phase) {
    if (!snapshot) return;
    uint64_t version = atomic_load_explicit(&snapshot->version, memory_order_acquire);
    BOOL locked = NO;
    for (NSUInteger attempt = 0; attempt < 64; ++attempt) {
        if (version & 1) {
            version = atomic_load_explicit(&snapshot->version, memory_order_acquire);
            continue;
        }
        uint64_t writing = version + 1;
        if (atomic_compare_exchange_weak_explicit(&snapshot->version, &version, writing,
                memory_order_acq_rel, memory_order_acquire)) {
            locked = YES;
            break;
        }
    }
    if (!locked) return;
    BOOL valid = CjguiPointerStreamTupleValid(sessionGeneration, bindingEpoch,
        firstSequence, lastSequence, previousSequence, phase);
    atomic_store_explicit(&snapshot->sessionGeneration, valid ? sessionGeneration : 0, memory_order_relaxed);
    atomic_store_explicit(&snapshot->bindingEpoch, valid ? bindingEpoch : 0, memory_order_relaxed);
    atomic_store_explicit(&snapshot->firstSequence, valid ? firstSequence : 0, memory_order_relaxed);
    atomic_store_explicit(&snapshot->lastSequence, valid ? lastSequence : 0, memory_order_relaxed);
    atomic_store_explicit(&snapshot->previousSequence, valid ? previousSequence : 0, memory_order_relaxed);
    atomic_store_explicit(&snapshot->phase, valid ? phase : 0, memory_order_relaxed);
    atomic_store_explicit(&snapshot->version, version + 2, memory_order_release);
}

static int CjguiReadPointerStreamSnapshot(uint64_t session, CjguiPointerStreamSnapshot *slots,
    uint64_t *outSessionGeneration, uint64_t *outBindingEpoch, uint64_t *outFirstSequence,
    uint64_t *outLastSequence, uint64_t *outPreviousSequence, uint32_t *outPhase) {
    if (outSessionGeneration) *outSessionGeneration = 0;
    if (outBindingEpoch) *outBindingEpoch = 0;
    if (outFirstSequence) *outFirstSequence = 0;
    if (outLastSequence) *outLastSequence = 0;
    if (outPreviousSequence) *outPreviousSequence = 0;
    if (outPhase) *outPhase = 0;
    if (!session || session > kCjguiSessionCapacity) return 0;
    NSUInteger index = (NSUInteger)(session - 1);
    CjguiPointerStreamSnapshot *snapshot = &slots[index];
    for (NSUInteger attempt = 0; attempt < 8; ++attempt) {
        uint64_t before = atomic_load_explicit(&snapshot->version, memory_order_acquire);
        if (before & 1) continue;
        uint64_t generation = atomic_load_explicit(&snapshot->sessionGeneration, memory_order_relaxed);
        uint64_t binding = atomic_load_explicit(&snapshot->bindingEpoch, memory_order_relaxed);
        uint64_t first = atomic_load_explicit(&snapshot->firstSequence, memory_order_relaxed);
        uint64_t last = atomic_load_explicit(&snapshot->lastSequence, memory_order_relaxed);
        uint64_t previous = atomic_load_explicit(&snapshot->previousSequence, memory_order_relaxed);
        uint32_t phase = atomic_load_explicit(&snapshot->phase, memory_order_relaxed);
        uint64_t after = atomic_load_explicit(&snapshot->version, memory_order_acquire);
        uint64_t liveGeneration = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index],
            memory_order_acquire);
        if (before != after || (after & 1) || !CjguiPointerStreamTupleValid(
                generation, binding, first, last, previous, phase) || generation != liveGeneration)
            return 0;
        if (outSessionGeneration) *outSessionGeneration = generation;
        if (outBindingEpoch) *outBindingEpoch = binding;
        if (outFirstSequence) *outFirstSequence = first;
        if (outLastSequence) *outLastSequence = last;
        if (outPreviousSequence) *outPreviousSequence = previous;
        if (outPhase) *outPhase = phase;
        return 1;
    }
    return 0;
}

static void CjguiStoreInputProvenance(CjguiInputProvenanceSnapshot *snapshot,
    uint64_t generation, uint64_t sequence, uint64_t previousSequence, uint32_t eventKind);

int cjgui_internal_renderer_main_pumped_pointer_fifo(uint64_t session,
    uint64_t *outSessionGeneration, uint64_t *outBindingEpoch,
    uint64_t *outFirstSequence, uint64_t *outLastSequence,
    uint64_t *outPreviousSequence, uint32_t *outPhase) {
    return CjguiReadPointerStreamSnapshot(session, gCjguiMainPumpedPointerStreams,
        outSessionGeneration, outBindingEpoch, outFirstSequence, outLastSequence,
        outPreviousSequence, outPhase);
}

int cjgui_internal_renderer_owner_consumed_pointer_fifo(uint64_t session,
    uint64_t *outSessionGeneration, uint64_t *outBindingEpoch,
    uint64_t *outFirstSequence, uint64_t *outLastSequence,
    uint64_t *outPreviousSequence, uint32_t *outPhase) {
    return CjguiReadPointerStreamSnapshot(session, gCjguiOwnerConsumedPointerStreams,
        outSessionGeneration, outBindingEpoch, outFirstSequence, outLastSequence,
        outPreviousSequence, outPhase);
}

void cjgui_internal_renderer_publish_owner_consumed_pointer_fifo(uint64_t session,
    uint64_t sessionGeneration, uint64_t bindingEpoch, uint64_t firstSequence,
    uint64_t lastSequence, uint64_t previousSequence, uint32_t phase) {
    if (!session || session > kCjguiSessionCapacity) return;
    NSUInteger index = (NSUInteger)(session - 1);
    uint64_t liveGeneration = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index],
        memory_order_acquire);
    if (sessionGeneration != liveGeneration || !CjguiPointerStreamTupleValid(
            sessionGeneration, bindingEpoch, firstSequence, lastSequence, previousSequence, phase)) {
        CjguiStorePointerStreamSnapshot(&gCjguiOwnerConsumedPointerStreams[index], 0, 0, 0, 0, 0, 0);
        return;
    }
    CjguiStorePointerStreamSnapshot(&gCjguiOwnerConsumedPointerStreams[index], sessionGeneration,
        bindingEpoch, firstSequence, lastSequence, previousSequence, phase);
}

static void CjguiClearMainPumpedPointerStream(CJGuiInternalSession *session) {
    if (!session || !session.rendererSessionToken || session.rendererSessionToken > kCjguiSessionCapacity) return;
    CjguiStorePointerStreamSnapshot(
        &gCjguiMainPumpedPointerStreams[session.rendererSessionToken - 1], 0, 0, 0, 0, 0, 0);
}

static void CjguiClearPointerStreamSnapshotsForSlot(NSUInteger index) {
    if (index >= kCjguiSessionCapacity) return;
    CjguiStorePointerStreamSnapshot(&gCjguiMainPumpedPointerStreams[index], 0, 0, 0, 0, 0, 0);
    CjguiStorePointerStreamSnapshot(&gCjguiOwnerConsumedPointerStreams[index], 0, 0, 0, 0, 0, 0);
    CjguiStoreInputProvenance(&gCjguiMainPumpedInputProvenance[index], 0, 0, 0, 0);
    CjguiStoreInputProvenance(&gCjguiOwnerConsumedInputProvenance[index], 0, 0, 0, 0);
}

static void CjguiPublishMainPumpedPointerStream(CJGuiInternalSession *session,
    CJGuiInternalQueuedInteraction *interaction) {
    if (!session || !interaction || !session.rendererSessionToken ||
        session.rendererSessionToken > kCjguiSessionCapacity) return;
    NSUInteger index = (NSUInteger)(session.rendererSessionToken - 1);
    uint64_t liveGeneration = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index],
        memory_order_acquire);
    BOOL valid = interaction.kind == interaction.pointerStreamPhase &&
        interaction.pointerStreamSessionGeneration == session.sessionGeneration &&
        interaction.pointerStreamBindingEpoch == interaction.bindingEpoch &&
        liveGeneration == session.sessionGeneration && CjguiPointerStreamTupleValid(
            interaction.pointerStreamSessionGeneration, interaction.pointerStreamBindingEpoch,
            interaction.pointerStreamFirstSequence, interaction.pointerStreamLastSequence,
            interaction.pointerStreamPreviousSequence, interaction.pointerStreamPhase);
    CjguiStorePointerStreamSnapshot(&gCjguiMainPumpedPointerStreams[index],
        valid ? interaction.pointerStreamSessionGeneration : 0,
        valid ? interaction.pointerStreamBindingEpoch : 0,
        valid ? interaction.pointerStreamFirstSequence : 0,
        valid ? interaction.pointerStreamLastSequence : 0,
        valid ? interaction.pointerStreamPreviousSequence : 0,
        valid ? interaction.pointerStreamPhase : 0);
}

static BOOL CjguiInputProvenanceTupleValid(uint64_t generation, uint64_t sequence,
    uint64_t previousSequence, uint32_t eventKind) {
    return generation != 0 && sequence != 0 &&
        (eventKind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_NAVIGATE ||
         eventKind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_WINDOW_COMMAND) &&
        previousSequence != UINT64_MAX && previousSequence + 1 == sequence;
}

static void CjguiStoreInputProvenance(CjguiInputProvenanceSnapshot *snapshot,
    uint64_t generation, uint64_t sequence, uint64_t previousSequence, uint32_t eventKind) {
    if (!snapshot) return;
    uint64_t version = atomic_load_explicit(&snapshot->version, memory_order_acquire);
    BOOL locked = NO;
    for (NSUInteger attempt = 0; attempt < 64; ++attempt) {
        if (version & 1) {
            version = atomic_load_explicit(&snapshot->version, memory_order_acquire);
            continue;
        }
        if (atomic_compare_exchange_weak_explicit(&snapshot->version, &version, version + 1,
                memory_order_acq_rel, memory_order_acquire)) {
            locked = YES;
            break;
        }
    }
    if (!locked) return;
    BOOL valid = CjguiInputProvenanceTupleValid(generation, sequence, previousSequence, eventKind);
    atomic_store_explicit(&snapshot->sessionGeneration, valid ? generation : 0, memory_order_relaxed);
    atomic_store_explicit(&snapshot->sequence, valid ? sequence : 0, memory_order_relaxed);
    atomic_store_explicit(&snapshot->previousSequence, valid ? previousSequence : 0, memory_order_relaxed);
    atomic_store_explicit(&snapshot->eventKind, valid ? eventKind : 0, memory_order_relaxed);
    atomic_store_explicit(&snapshot->version, version + 2, memory_order_release);
}

static int CjguiReadInputProvenance(uint64_t session, CjguiInputProvenanceSnapshot *slots,
    uint64_t *outGeneration, uint64_t *outSequence, uint64_t *outPreviousSequence,
    uint32_t *outEventKind) {
    if (outGeneration) *outGeneration = 0;
    if (outSequence) *outSequence = 0;
    if (outPreviousSequence) *outPreviousSequence = 0;
    if (outEventKind) *outEventKind = 0;
    if (!session || session > kCjguiSessionCapacity) return 0;
    NSUInteger index = (NSUInteger)(session - 1);
    CjguiInputProvenanceSnapshot *snapshot = &slots[index];
    for (NSUInteger attempt = 0; attempt < 8; ++attempt) {
        uint64_t before = atomic_load_explicit(&snapshot->version, memory_order_acquire);
        if (before & 1) continue;
        uint64_t generation = atomic_load_explicit(&snapshot->sessionGeneration, memory_order_relaxed);
        uint64_t sequence = atomic_load_explicit(&snapshot->sequence, memory_order_relaxed);
        uint64_t previous = atomic_load_explicit(&snapshot->previousSequence, memory_order_relaxed);
        uint32_t kind = atomic_load_explicit(&snapshot->eventKind, memory_order_relaxed);
        uint64_t after = atomic_load_explicit(&snapshot->version, memory_order_acquire);
        uint64_t liveGeneration = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index],
            memory_order_acquire);
        if (before != after || (after & 1) || generation != liveGeneration ||
            !CjguiInputProvenanceTupleValid(generation, sequence, previous, kind)) return 0;
        if (outGeneration) *outGeneration = generation;
        if (outSequence) *outSequence = sequence;
        if (outPreviousSequence) *outPreviousSequence = previous;
        if (outEventKind) *outEventKind = kind;
        return 1;
    }
    return 0;
}

static void CjguiClearMainPumpedInputProvenance(CJGuiInternalSession *session) {
    if (!session || !session.rendererSessionToken || session.rendererSessionToken > kCjguiSessionCapacity) return;
    NSUInteger index = (NSUInteger)(session.rendererSessionToken - 1);
    CjguiStoreInputProvenance(&gCjguiMainPumpedInputProvenance[index], 0, 0, 0, 0);
}

static void CjguiPublishMainPumpedInputProvenance(CJGuiInternalSession *session,
    CJGuiInternalQueuedInteraction *interaction) {
    if (!session || !interaction || !session.rendererSessionToken ||
        session.rendererSessionToken > kCjguiSessionCapacity) return;
    NSUInteger index = (NSUInteger)(session.rendererSessionToken - 1);
    uint64_t liveGeneration = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index],
        memory_order_acquire);
    BOOL valid = (interaction.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_NAVIGATE ||
        (interaction.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_WINDOW_COMMAND &&
         interaction.caretInputBranch.valid)) &&
        interaction.inputSessionGeneration == session.sessionGeneration &&
        liveGeneration == session.sessionGeneration && CjguiInputProvenanceTupleValid(
            interaction.inputSessionGeneration, interaction.inputSequence,
            interaction.inputPreviousSequence, interaction.kind);
    CjguiStoreInputProvenance(&gCjguiMainPumpedInputProvenance[index],
        valid ? interaction.inputSessionGeneration : 0, valid ? interaction.inputSequence : 0,
        valid ? interaction.inputPreviousSequence : 0, valid ? interaction.kind : 0);
}

int cjgui_internal_renderer_main_pumped_input_provenance(uint64_t session,
    uint64_t *outSessionGeneration, uint64_t *outSequence,
    uint64_t *outPreviousSequence, uint32_t *outEventKind) {
    return CjguiReadInputProvenance(session, gCjguiMainPumpedInputProvenance,
        outSessionGeneration, outSequence, outPreviousSequence, outEventKind);
}

int cjgui_internal_renderer_owner_consumed_input_provenance(uint64_t session,
    uint64_t *outSessionGeneration, uint64_t *outSequence,
    uint64_t *outPreviousSequence, uint32_t *outEventKind) {
    return CjguiReadInputProvenance(session, gCjguiOwnerConsumedInputProvenance,
        outSessionGeneration, outSequence, outPreviousSequence, outEventKind);
}

void cjgui_internal_renderer_publish_owner_consumed_input_provenance(uint64_t session,
    uint64_t sessionGeneration, uint64_t sequence, uint64_t previousSequence,
    uint32_t eventKind) {
    if (!session || session > kCjguiSessionCapacity) return;
    NSUInteger index = (NSUInteger)(session - 1);
    uint64_t liveGeneration = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index],
        memory_order_acquire);
    BOOL valid = liveGeneration == sessionGeneration && CjguiInputProvenanceTupleValid(
        sessionGeneration, sequence, previousSequence, eventKind);
    CjguiStoreInputProvenance(&gCjguiOwnerConsumedInputProvenance[index],
        valid ? sessionGeneration : 0, valid ? sequence : 0,
        valid ? previousSequence : 0, valid ? eventKind : 0);
}

static void CjguiStorePointerCoordinateTuple(_Atomic(uint64_t) *generationSlot,
                                             _Atomic(uint64_t) *epochSlot,
                                             uint64_t sessionGeneration,
                                             uint64_t coordinateEpoch) {
    atomic_store_explicit(epochSlot,0,memory_order_release);
    atomic_store_explicit(generationSlot,0,memory_order_release);
    if(!sessionGeneration || !coordinateEpoch) return;
    atomic_store_explicit(generationSlot,sessionGeneration,memory_order_relaxed);
    atomic_store_explicit(epochSlot,coordinateEpoch,memory_order_release);
}

static int CjguiReadPointerCoordinateTuple(uint64_t session,
                                          _Atomic(uint64_t) *generationSlots,
                                          _Atomic(uint64_t) *epochSlots,
                                          uint64_t *outSessionGeneration,
                                          uint64_t *outCoordinateEpoch) {
    if(outSessionGeneration) *outSessionGeneration=0;
    if(outCoordinateEpoch) *outCoordinateEpoch=0;
    if(!session || session>kCjguiSessionCapacity) return 0;
    NSUInteger index=(NSUInteger)(session-1);
    uint64_t epochBefore=atomic_load_explicit(&epochSlots[index],memory_order_acquire);
    uint64_t generation=atomic_load_explicit(&generationSlots[index],memory_order_acquire);
    uint64_t epochAfter=atomic_load_explicit(&epochSlots[index],memory_order_acquire);
    uint64_t liveGeneration=atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index],memory_order_acquire);
    if(!epochBefore || epochBefore!=epochAfter || !generation || generation!=liveGeneration) return 0;
    if(outSessionGeneration) *outSessionGeneration=generation;
    if(outCoordinateEpoch) *outCoordinateEpoch=epochBefore;
    return 1;
}

int cjgui_internal_renderer_main_pumped_pointer_coordinate_lifetime(
    uint64_t session,uint64_t *outSessionGeneration,uint64_t *outCoordinateEpoch) {
    return CjguiReadPointerCoordinateTuple(session,gCjguiMainPumpedPointerSessionGeneration,
        gCjguiMainPumpedPointerCoordinateEpoch,outSessionGeneration,outCoordinateEpoch);
}

int cjgui_internal_renderer_owner_consumed_pointer_coordinate_lifetime(
    uint64_t session,uint64_t *outSessionGeneration,uint64_t *outCoordinateEpoch) {
    return CjguiReadPointerCoordinateTuple(session,gCjguiOwnerConsumedPointerSessionGeneration,
        gCjguiOwnerConsumedPointerCoordinateEpoch,outSessionGeneration,outCoordinateEpoch);
}

void cjgui_internal_renderer_publish_owner_consumed_pointer_coordinate_lifetime(
    uint64_t session,uint64_t sessionGeneration,uint64_t coordinateEpoch) {
    if(!session || session>kCjguiSessionCapacity) return;
    NSUInteger index=(NSUInteger)(session-1);
    uint64_t liveGeneration=atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index],memory_order_acquire);
    if(!sessionGeneration || sessionGeneration!=liveGeneration || !coordinateEpoch) {
        CjguiStorePointerCoordinateTuple(&gCjguiOwnerConsumedPointerSessionGeneration[index],
            &gCjguiOwnerConsumedPointerCoordinateEpoch[index],0,0);
        return;
    }
    CjguiStorePointerCoordinateTuple(&gCjguiOwnerConsumedPointerSessionGeneration[index],
        &gCjguiOwnerConsumedPointerCoordinateEpoch[index],sessionGeneration,coordinateEpoch);
}

static void CjguiClearMainPumpedPointerCoordinateLifetime(CJGuiInternalSession *session) {
    if(!session || !session.rendererSessionToken || session.rendererSessionToken>kCjguiSessionCapacity) return;
    NSUInteger index=(NSUInteger)(session.rendererSessionToken-1);
    if(atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index],memory_order_acquire)!=session.sessionGeneration)
        return;
    CjguiStorePointerCoordinateTuple(&gCjguiMainPumpedPointerSessionGeneration[index],
        &gCjguiMainPumpedPointerCoordinateEpoch[index],0,0);
}

static void CjguiPublishMainPumpedPointerCoordinateLifetime(
    CJGuiInternalSession *session,CJGuiInternalQueuedInteraction *interaction) {
    if(!session || !session.rendererSessionToken || session.rendererSessionToken>kCjguiSessionCapacity) return;
    NSUInteger index=(NSUInteger)(session.rendererSessionToken-1);
    uint64_t generation=interaction.coordinateSessionGeneration;
    uint64_t epoch=interaction.coordinateEpoch;
    uint64_t liveGeneration=atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index],memory_order_acquire);
    if(!generation || generation!=session.sessionGeneration || generation!=liveGeneration || !epoch) {
        CjguiStorePointerCoordinateTuple(&gCjguiMainPumpedPointerSessionGeneration[index],
            &gCjguiMainPumpedPointerCoordinateEpoch[index],0,0);
        return;
    }
    CjguiStorePointerCoordinateTuple(&gCjguiMainPumpedPointerSessionGeneration[index],
        &gCjguiMainPumpedPointerCoordinateEpoch[index],generation,epoch);
}

static void CjguiBumpCoordinateLifetimeForIdentity(uint64_t sessionToken,uint64_t sessionGeneration) {
    if(!sessionToken || sessionToken>kCjguiSessionCapacity || !sessionGeneration) return;
    NSUInteger index=(NSUInteger)(sessionToken-1);
    if(atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index],memory_order_acquire)!=sessionGeneration)
        return;
    uint64_t current=atomic_load_explicit(&gCjguiCoordinateEpoch[index],memory_order_acquire);
    while(current) {
        uint64_t next=current==UINT64_MAX ? 0 : current+1;
        if(atomic_compare_exchange_weak_explicit(&gCjguiCoordinateEpoch[index],&current,next,
                memory_order_acq_rel,memory_order_acquire)) {
            CJGuiInternalSession *live=gCjguiSessions[index];
            if(live && live.sessionGeneration==sessionGeneration)
                live.coordinateLifetimeGeneration=next;
            return;
        }
    }
}

static void CjguiInvalidateCoordinateLifetimeForIdentity(uint64_t sessionToken,uint64_t sessionGeneration) {
    if(!sessionToken || sessionToken>kCjguiSessionCapacity || !sessionGeneration) return;
    NSUInteger index=(NSUInteger)(sessionToken-1);
    if(atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index],memory_order_acquire)!=sessionGeneration)
        return;
    atomic_store_explicit(&gCjguiCoordinateEpoch[index],0,memory_order_release);
    CJGuiInternalSession *live=gCjguiSessions[index];
    if(live && live.sessionGeneration==sessionGeneration) live.coordinateLifetimeGeneration=0;
}

static void CjguiBumpCoordinateLifetimeForSession(CJGuiInternalSession *session) {
    if(!session || session.destroyed) return;
    CjguiBumpCoordinateLifetimeForIdentity(session.rendererSessionToken,session.sessionGeneration);
}

uint8_t cjgui_internal_renderer_source_install_pending_scalar(uint64_t session) {
    if (!session || session > kCjguiSessionCapacity) return 0;
    return atomic_load_explicit(&gCjguiSourceInstallRequest[session-1], memory_order_acquire) != 0;
}
CjguiInternalRendererStatus cjgui_internal_renderer_set_source_install_gate(
    uint64_t session, uint64_t bindingEpoch, uint64_t requestId, uint8_t pending) {
    if (session == 0 || session > kCjguiSessionCapacity || requestId == 0)
        return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    NSUInteger index = (NSUInteger)(session - 1);
    if (pending) {
        atomic_store_explicit(&gCjguiSourceInstallEpoch[index], bindingEpoch, memory_order_relaxed);
        atomic_store_explicit(&gCjguiSourceInstallRequest[index], requestId, memory_order_release);
    } else {
        uint64_t expected = requestId;
        if (atomic_load_explicit(&gCjguiSourceInstallEpoch[index], memory_order_acquire) == bindingEpoch)
            (void)atomic_compare_exchange_strong_explicit(&gCjguiSourceInstallRequest[index],
                &expected, 0, memory_order_acq_rel, memory_order_acquire);
    }
    return CJGUI_INTERNAL_RENDERER_OK;
}
static BOOL CjguiSourceInstallPending(CJGuiInternalSession *session) {
    uint64_t token = session.rendererSessionToken;
    if (!session || session.destroyed || token == 0 || token > kCjguiSessionCapacity ||
        !session.ownedTextSessionEnabled ||
        session.ownedTextSessionNodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) return NO;
    NSUInteger index = (NSUInteger)(token - 1);
    return atomic_load_explicit(&gCjguiSourceInstallRequest[index], memory_order_acquire) != 0 &&
        atomic_load_explicit(&gCjguiSourceInstallEpoch[index], memory_order_acquire) == session.ownedTextSessionBindingEpoch;
}
static BOOL CjguiInstalledRangeActivationMatches(CJGuiInternalSession *ctx,
    CjguiInstalledRangeState *state, uint64_t proxyGeneration, uint64_t selectionRevision);
static BOOL CjguiInstalledRangeBasisMatchesActual(CJGuiInternalSession *ctx,
    CJGuiInternalComposableSceneOverlay *overlay);
static CjguiCaretInputSnapshot *CjguiCaptureCaretInputSnapshot(CJGuiInternalSession *ctx);
static CjguiCaretInputSnapshot *CjguiPendingOwnerCaretSource(CJGuiInternalSession *ctx);
static BOOL CjguiFrozenCaretSourceMatchesActual(CJGuiInternalSession *ctx,
    CjguiCaretInputSnapshot *snapshot);
static void CjguiTraceOwnerHandoffProducerIdentity(CJGuiInternalSession *ctx,
    CjguiOwnerSelectionHandoff *h,CjguiCaretInputSnapshot *actual);
static BOOL CjguiQueuedCaretSuccessorOfInflight(CJGuiInternalSession *ctx,
    CJGuiInternalQueuedInteraction *queued);
static void CjguiRetireOwnerHandoff(CJGuiInternalSession *ctx, CjguiOwnerSelectionHandoff *h,
    const char *reason);
static void CjguiRejectCaretInputBranch(CJGuiInternalSession *ctx,
    CjguiCaretInputBranch *branch, const char *reason);
static BOOL CjguiRetainAfterCaretText(CJGuiInternalComposableInputProxy *proxy,
    id payload, NSRange replacementRange, uint32_t kind);
static void CjguiAdvanceCaretInputFromOwnerRangeAck(CJGuiInternalSession *ctx,
    CjguiInstalledRangeIntentState *state, CjguiInternalInstalledRangeIntent value);
static BOOL CjguiInstalledRangeScopeMatchesCurrent(CJGuiInternalSession *ctx,
    CJGuiInternalComposableSceneOverlay *overlay, CjguiInstalledRangeState *state);
static void CjguiSettleInstalledRangeLocalEditForAck(CJGuiInternalSession *ctx,
    CjguiInstalledRangeIntentState *state, CjguiInternalInstalledRangeIntent intent);
static void CjguiMarkInstalledRangeSourceParked(CJGuiInternalSession *ctx, BOOL parked);
static void CjguiRetireInstalledRangeReservation(CJGuiInternalSession *ctx,
    CjguiInstalledRangeIntentState *reservation);

static BOOL CjguiInstalledRangeQueuedLegacyRangeMatches(CJGuiInternalQueuedInteraction *queued,
    CjguiInternalInstalledRangeCandidate candidate) {
    return queued && queued.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_RANGE_CHANGED &&
        queued.nodeId == candidate.nodeId && queued.resourceId == candidate.resourceId &&
        queued.projectionVersion == candidate.installedSceneVersion &&
        !queued.installedRangeIntent && !queued.installedRangeOwnedInvalid;
}

static BOOL CjguiInstalledRangeHasUnconsumedLegacyRange(
    CJGuiInternalSession *ctx, CjguiInternalInstalledRangeCandidate candidate) {
    if (!ctx) return NO;
    for (CJGuiInternalQueuedInteraction *queued in ctx.pendingInteractions)
        if (CjguiInstalledRangeQueuedLegacyRangeMatches(queued, candidate)) return YES;
    return NO;
}

#define CJGUI_INSTALLED_RANGE_BYTE_CAPACITY (4u * 1024u * 1024u)
#define CJGUI_INSTALLED_RANGE_RESERVED_FIFO_SLOTS 1u

static BOOL CjguiEventCanProduceOrdinaryTextRange(NSEvent *event) {
    if (!event) return NO;
    // Deletion and line break produce ordinary NSTextView ranges without a
    // printable `characters` value. Navigation remains on its existing
    // owner path because this bridge has not established its coordinates.
    if (event.keyCode == 51 || event.keyCode == 117 || event.keyCode == 36 || event.keyCode == 76)
        return YES;
    NSString *characters = event.characters ?: @"";
    if (characters.length == 0) return NO;
    for (NSUInteger index = 0; index < characters.length; ++index) {
        unichar value = [characters characterAtIndex:index];
        if (value < 0x20 || (value >= 0x7f && value <= 0x9f) ||
            (value >= 0xf700 && value <= 0xf8ff)) return NO;
    }
    return YES;
}

static uint64_t CjguiInstalledRangeStateBytes(CjguiInstalledRangeState *state) {
    return state.sourceUtf8.length;
}

static CjguiInternalRendererStatus CjguiInstalledRangeRunOnMain(uint64_t token,
    CjguiInternalRendererStatus (^operation)(CJGuiInternalSession *)) {
    if (!operation || token == 0 || token > kCjguiSessionCapacity)
        return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    if (CjguiIsMainThread()) {
        CJGuiInternalSession *ctx = CjguiLookupSession(token);
        if (!ctx || ctx.destroyed) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
        return operation(ctx);
    }
    if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
    __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
    CjguiOwnerTraceDispatchSync(token, 0, CJGUI_OWNER_PHASE_INSTALLED_RANGE_MAIN, ^{
        CJGuiInternalSession *ctx = CjguiLookupSession(token);
        if (!ctx || ctx.destroyed) status = CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
        else status = operation(ctx);
    });
    return status;
}

CjguiInternalRendererStatus cjgui_internal_renderer_installed_range_arm(
    uint64_t session, const CjguiInternalInstalledRangeCandidate *candidate) {
    if (!candidate || !candidate->nonce || !candidate->windowInstanceToken || !candidate->bindingEpoch ||
        !candidate->nodeId || candidate->ownerVersion < 0 || candidate->sourceEndByte < candidate->sourceStartByte ||
        (!candidate->sourceTextUtf8 && candidate->sourceTextUtf8Length) ||
        candidate->sourceTextUtf8Length > CJGUI_INSTALLED_RANGE_BYTE_CAPACITY)
        return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    NSData *sourceBytes = candidate->sourceTextUtf8Length
        ? [NSData dataWithBytes:candidate->sourceTextUtf8 length:candidate->sourceTextUtf8Length]
        : [NSData data];
    NSString *sourceText = [[NSString alloc] initWithData:sourceBytes encoding:NSUTF8StringEncoding];
    if (!sourceBytes || !sourceText) return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    CjguiInternalInstalledRangeCandidate frozen = *candidate;
    frozen.sourceTextUtf8 = NULL;
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        if (!ctx.ownedTextSessionEnabled ||
            ctx.ownedTextSessionNodeId != frozen.nodeId ||
            ctx.ownedTextSessionResourceId != frozen.resourceId ||
            ctx.ownedTextSessionBindingEpoch != frozen.bindingEpoch ||
            ctx.ownedTextSessionNodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT ||
            !ctx.rangeTextEditDeltaDeliveryEnabled ||
            (frozen.rendererSessionGeneration && frozen.rendererSessionGeneration != ctx.sessionGeneration))
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        if (ctx.installedRangeProvisional) return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        CjguiInstalledRangeState *oldCandidate = ctx.installedRangeCandidate;
        uint64_t oldCandidateBytes = CjguiInstalledRangeStateBytes(oldCandidate);
        uint64_t used = ctx.installedRangeBytesUsed >= oldCandidateBytes
            ? ctx.installedRangeBytesUsed - oldCandidateBytes : 0;
        if (used > CJGUI_INSTALLED_RANGE_BYTE_CAPACITY || ctx.installedRangeBytesReserved >
            CJGUI_INSTALLED_RANGE_BYTE_CAPACITY - used || sourceBytes.length >
            CJGUI_INSTALLED_RANGE_BYTE_CAPACITY - used - ctx.installedRangeBytesReserved)
            return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
        CjguiInstalledRangeState *state = [CjguiInstalledRangeState new];
        if (!state) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        CjguiInternalInstalledRangeCandidate actualCandidate = frozen;
        actualCandidate.rendererSessionGeneration = ctx.sessionGeneration;
        state.candidate = actualCandidate;
        state.sourceUtf8 = sourceBytes;
        ctx.installedRangeCandidate = state;
        ctx.installedRangeBytesUsed = used + sourceBytes.length;
        // A newly adopted source extent can have identical text to the old
        // mirror. Keep its old actual adapter parked under the frozen basis;
        // the new extent becomes input-eligible only after its install receipt.
        if (ctx.installedRangeBasis &&
            (ctx.installedRangeBasis.candidate.sourceStartByte != frozen.sourceStartByte ||
             ctx.installedRangeBasis.candidate.sourceEndByte != frozen.sourceEndByte ||
             ctx.installedRangeBasis.candidate.windowInstanceToken != frozen.windowInstanceToken ||
             ctx.installedRangeBasis.candidate.bindingEpoch != frozen.bindingEpoch))
            CjguiMarkInstalledRangeSourceParked(ctx, YES);
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_installed_range_receipt(
    uint64_t session, uint64_t nonce, CjguiInternalInstalledRangeReceipt *outReceipt) {
    if (!nonce || !outReceipt) return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    memset(outReceipt, 0, sizeof(*outReceipt));
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiInstalledRangeState *state = ctx.installedRangeProvisional;
        if (!state || state.candidate.nonce != nonce) state = ctx.sourceHandoffProvisional;
        if (!state || state.candidate.nonce != nonce || !state.hasReceipt || !state.proxy)
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        CjguiInternalInstalledRangeCandidate c = state.candidate;
        outReceipt->nonce = c.nonce;
        outReceipt->rendererSessionGeneration = c.rendererSessionGeneration;
        outReceipt->windowInstanceToken = c.windowInstanceToken;
        outReceipt->bindingEpoch = c.bindingEpoch;
        outReceipt->contextEpoch = c.contextEpoch;
        outReceipt->mirrorRevision = c.mirrorRevision;
        outReceipt->ownerVersion = c.ownerVersion;
        outReceipt->installedSceneVersion = c.installedSceneVersion;
        outReceipt->nodeId = c.nodeId;
        outReceipt->resourceId = c.resourceId;
        outReceipt->sourceStartByte = c.sourceStartByte;
        outReceipt->sourceEndByte = c.sourceEndByte;
        outReceipt->proxyGeneration = state.proxyGeneration;
        outReceipt->selectionRevision = state.selectionRevision;
        outReceipt->actualSelectionStart16 = state.actualSelectionStart16;
        outReceipt->actualSelectionEnd16 = state.actualSelectionEnd16;
        outReceipt->acceptedSequence = 0;
        outReceipt->acceptedVersion = c.ownerVersion;
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}


CjguiInternalRendererStatus cjgui_internal_renderer_installed_range_activate(
    uint64_t session, uint64_t nonce, uint64_t proxyGeneration, uint64_t selectionRevision) {
    if (!nonce || !proxyGeneration) return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiInstalledRangeState *state = ctx.installedRangeProvisional;
        if (!state || state.candidate.nonce != nonce || !state.hasReceipt ||
            state.proxyGeneration != proxyGeneration || state.selectionRevision != selectionRevision ||
            !CjguiInstalledRangeActivationMatches(ctx, state, proxyGeneration, selectionRevision))
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        if (CjguiInstalledRangeHasUnconsumedLegacyRange(ctx, state.candidate))
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        CjguiInstalledRangeState *old = ctx.installedRangeBasis;
        if (old && ctx.installedRangeLocalTailSequence != ctx.installedRangeObservedAckSequence)
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        uint64_t oldBytes = CjguiInstalledRangeStateBytes(old);
        ctx.installedRangeBasis = state;
        ctx.installedRangeBasis.active = YES;
        ctx.installedRangeBasis.chainClosed = NO;
        ctx.installedRangeProvisional = nil;
        ctx.installedRangeNextSequence = 0;
        ctx.installedRangeLocalTailSequence = 0;
        ctx.installedRangeObservedAckSequence = 0;
        ctx.installedRangeObservedAckVersion = state.candidate.ownerVersion;
        ctx.installedWholeChoiceNonce = 0;
        if (ctx.installedRangeBytesUsed >= oldBytes) ctx.installedRangeBytesUsed -= oldBytes;
        ctx.installedRangeRecoveryBlock = nil;
        CjguiMarkInstalledRangeSourceParked(ctx, NO);
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_installed_range_cancel(
    uint64_t session, uint64_t nonce) {
    if (!nonce) return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiInstalledRangeState *candidate = ctx.installedRangeCandidate;
        CjguiInstalledRangeState *provisional = ctx.installedRangeProvisional;
        if (candidate && candidate.candidate.nonce == nonce) {
            uint64_t bytes = CjguiInstalledRangeStateBytes(candidate);
            ctx.installedRangeBytesUsed = ctx.installedRangeBytesUsed >= bytes
                ? ctx.installedRangeBytesUsed - bytes : 0;
            ctx.installedRangeCandidate = nil;
            if (ctx.installedRangeBasis &&
                CjguiInstalledRangeBasisMatchesActual(ctx, ctx.composableSceneOverlay))
                CjguiMarkInstalledRangeSourceParked(ctx, NO);
            return CJGUI_INTERNAL_RENDERER_OK;
        }
        if (provisional && provisional.candidate.nonce == nonce) {
            uint64_t bytes = CjguiInstalledRangeStateBytes(provisional);
            ctx.installedRangeBytesUsed = ctx.installedRangeBytesUsed >= bytes
                ? ctx.installedRangeBytesUsed - bytes : 0;
            ctx.installedRangeProvisional = nil;
            if (!(ctx.installedRangeBasis &&
                CjguiInstalledRangeBasisMatchesActual(ctx, ctx.composableSceneOverlay))) {
                provisional.sourceUtf8 = nil;
                ctx.installedRangeRecoveryBlock = provisional;
                CjguiMarkInstalledRangeSourceParked(ctx, YES);
            } else {
                CjguiMarkInstalledRangeSourceParked(ctx, NO);
            }
            return CJGUI_INTERNAL_RENDERER_OK;
        }
        return CJGUI_INTERNAL_RENDERER_NODE_NOT_FOUND;
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_claim_last_pumped_range(
    uint64_t session, uint64_t nodeId, int64_t resourceId, uint64_t bindingEpoch,
    uint64_t sceneVersion, CjguiInternalInstalledRangeIntent *outIntent) {
    if (!outIntent) return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    memset(outIntent, 0, sizeof(*outIntent));
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CJGuiInternalQueuedInteraction *queued = ctx.pumpedInstalledRangeInteraction;
        ctx.pumpedInstalledRangeInteraction = nil;
        if (!queued || queued.kind != CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_RANGE_CHANGED)
            return CJGUI_INTERNAL_RENDERER_NODE_NOT_FOUND;
        outIntent->nonce = queued.installedRangeNonce;
        CjguiInstalledRangeIntentState *state = queued.installedRangeIntent;
        BOOL identityMatches = queued.nodeId == nodeId && queued.resourceId == resourceId &&
            queued.bindingEpoch == bindingEpoch && queued.projectionVersion == sceneVersion;
        if (!identityMatches && !queued.installedRangeOwnedInvalid && !state)
            return CJGUI_INTERNAL_RENDERER_NODE_NOT_FOUND;
        if (!identityMatches) {
            if (state && !state.claimed && !state.settled) {
                ctx.installedRangeBytesUsed = ctx.installedRangeBytesUsed >= state.chargedBytes
                    ? ctx.installedRangeBytesUsed - state.chargedBytes : 0;
                state.settled = YES;
            }
            queued.installedRangeIntent = nil;
            queued.installedRangeOwnedInvalid = YES;
            outIntent->rendererSessionGeneration = ctx.sessionGeneration;
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        }
        if (queued.installedRangeOwnedInvalid || !state || state.claimed || state.settled) {
            outIntent->rendererSessionGeneration = ctx.sessionGeneration;
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        }
        if (!ctx.installedRangeBasis || ctx.installedRangeBasis.chainClosed) {
            ctx.installedRangeBytesUsed = ctx.installedRangeBytesUsed >= state.chargedBytes
                ? ctx.installedRangeBytesUsed - state.chargedBytes : 0;
            state.settled = YES;
            queued.installedRangeIntent = nil;
            outIntent->rendererSessionGeneration = ctx.sessionGeneration;
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        }
        if (ctx.claimedInstalledRangeIntent && !ctx.claimedInstalledRangeIntent.settled) {
            ctx.installedRangeBasis.chainClosed = YES;
            ctx.installedRangeBytesUsed = ctx.installedRangeBytesUsed >= state.chargedBytes
                ? ctx.installedRangeBytesUsed - state.chargedBytes : 0;
            state.settled = YES;
            queued.installedRangeIntent = nil;
            queued.installedRangeOwnedInvalid = YES;
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        }
        state.claimed = YES;
        ctx.claimedInstalledRangeIntent = state;
        CjguiInternalInstalledRangeIntent value = state.value;
        value.preBodyUtf8 = state.preBody.bytes;
        value.replacementUtf8 = state.replacement.bytes;
        value.postBodyUtf8 = state.postBody.bytes;
        *outIntent = value;
        return (value.flags & 1u) ? CJGUI_INTERNAL_RENDERER_SCENE_STALE : CJGUI_INTERNAL_RENDERER_OK;
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_copy_claimed_range_bytes(
    uint64_t session, uint64_t seq, uint8_t *preBody, uint32_t preBodyCapacity,
    uint8_t *replacement, uint32_t replacementCapacity, uint8_t *postBody, uint32_t postBodyCapacity) {
    if (!seq) return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiInstalledRangeIntentState *state = ctx.claimedInstalledRangeIntent;
        if (!state || !state.claimed || state.settled || state.value.seq != seq)
            return CJGUI_INTERNAL_RENDERER_NODE_NOT_FOUND;
        if (preBodyCapacity != state.preBody.length || replacementCapacity != state.replacement.length ||
            postBodyCapacity != state.postBody.length ||
            (preBodyCapacity && !preBody) || (replacementCapacity && !replacement) ||
            (postBodyCapacity && !postBody)) return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
        if (preBodyCapacity) memcpy(preBody, state.preBody.bytes, preBodyCapacity);
        if (replacementCapacity) memcpy(replacement, state.replacement.bytes, replacementCapacity);
        if (postBodyCapacity) memcpy(postBody, state.postBody.bytes, postBodyCapacity);
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

#ifdef CJGUI_INTERNAL_TESTING
// A one-shot fault for the real installed-range ACK entry point. The test
// build leaves the claimed native state untouched on the injected return so
// the exact same claim can be retried through this function.
static BOOL gCjguiInstalledRangeAckFaultInjected = NO;
static uint64_t gCjguiInstalledRangeAckFaultSession = 0;
static uint64_t gCjguiInstalledRangeAckFaultSequence = 0;
#endif

CjguiInternalRendererStatus cjgui_internal_renderer_ack_installed_range(
    uint64_t session, const CjguiInternalInstalledRangeIntent *intent,
    uint32_t accepted, int64_t receiptVersionAfter) {
    if (!intent || !intent->nonce || !intent->seq || accepted > 1 || (accepted && receiptVersionAfter < 0))
        return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiInstalledRangeIntentState *state = ctx.claimedInstalledRangeIntent;
        CjguiInstalledRangeState *basis = ctx.installedRangeBasis;
        CjguiInternalInstalledRangeIntent v = state ? state.value : (CjguiInternalInstalledRangeIntent){0};
        if (!state || !basis || !state.claimed || state.settled ||
            v.nonce != intent->nonce || v.seq != intent->seq ||
            v.proxyGeneration != intent->proxyGeneration ||
            v.rendererSessionGeneration != intent->rendererSessionGeneration ||
            v.windowInstanceToken != intent->windowInstanceToken || v.bindingEpoch != intent->bindingEpoch ||
            v.contextEpoch != intent->contextEpoch || v.mirrorRevision != intent->mirrorRevision ||
            v.ownerVersion != intent->ownerVersion || v.installedSceneVersion != intent->installedSceneVersion ||
            v.nodeId != intent->nodeId || v.resourceId != intent->resourceId ||
            v.sourceStartByte != intent->sourceStartByte || v.sourceEndByte != intent->sourceEndByte ||
            v.selectionRevision != intent->selectionRevision || v.previousSeq != intent->previousSeq ||
            v.observedAckSeq != intent->observedAckSeq || v.observedAckVersion != intent->observedAckVersion ||
            v.wholeChoiceNonce != intent->wholeChoiceNonce ||
            v.wholeChoicePreviousSeq != intent->wholeChoicePreviousSeq ||
            v.flags != intent->flags ||
            v.rangeStart16 != intent->rangeStart16 || v.rangeLength16 != intent->rangeLength16 ||
            v.selectionStart16 != intent->selectionStart16 || v.selectionEnd16 != intent->selectionEnd16 ||
            v.preBodyUtf8Length != intent->preBodyUtf8Length ||
            v.replacementUtf8Length != intent->replacementUtf8Length ||
            v.postBodyUtf8Length != intent->postBodyUtf8Length)
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
#ifdef CJGUI_INTERNAL_TESTING
        const char *faultSeqText = getenv("CJGUI_TEST_INSTALLED_RANGE_ACK_FAIL_SEQ");
        const char *faultSessionText = getenv("CJGUI_TEST_INSTALLED_RANGE_ACK_FAIL_SESSION");
        if (!gCjguiInstalledRangeAckFaultInjected && accepted && faultSeqText && *faultSeqText) {
            char *seqEnd = NULL;
            unsigned long long faultSeq = strtoull(faultSeqText, &seqEnd, 10);
            BOOL validSeq = seqEnd != faultSeqText && *seqEnd == '\0';
            BOOL sessionMatches = YES;
            if (faultSessionText && *faultSessionText) {
                char *sessionEnd = NULL;
                unsigned long long faultSession = strtoull(faultSessionText, &sessionEnd, 10);
                sessionMatches = sessionEnd != faultSessionText && *sessionEnd == '\0' &&
                    faultSession == session;
            }
            if (validSeq && sessionMatches && faultSeq == v.seq) {
                gCjguiInstalledRangeAckFaultInjected = YES;
                gCjguiInstalledRangeAckFaultSession = session;
                gCjguiInstalledRangeAckFaultSequence = v.seq;
                fprintf(stderr,
                    "CJGUI_TEST_INSTALLED_RANGE_ACK_FAIL_ONCE session=%llu seq=%llu status=%d\n",
                    (unsigned long long)session, (unsigned long long)v.seq,
                    CJGUI_INTERNAL_RENDERER_READBACK_FAILED);
                return CJGUI_INTERNAL_RENDERER_READBACK_FAILED;
            }
        }
#endif
    if (accepted) {
            if (v.previousSeq != ctx.installedRangeObservedAckSequence ||
                v.seq <= ctx.installedRangeObservedAckSequence ||
                receiptVersionAfter <= ctx.installedRangeObservedAckVersion ||
                !CjguiInstalledRangeBasisMatchesActual(ctx, ctx.composableSceneOverlay) ||
                ![state.preBody isEqualToData:basis.sourceUtf8] ||
                state.postBody.length > UINT64_MAX - basis.candidate.sourceStartByte)
                return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
            uint64_t oldBasisBytes = CjguiInstalledRangeStateBytes(basis);
            uint64_t nextBasisBytes = state.postBody.length;
            uint64_t releasing = state.chargedBytes;
            uint64_t retained = oldBasisBytes + releasing;
            if (nextBasisBytes > CJGUI_INSTALLED_RANGE_BYTE_CAPACITY ||
                ctx.installedRangeBytesUsed < retained ||
                ctx.installedRangeBytesUsed - retained > CJGUI_INSTALLED_RANGE_BYTE_CAPACITY - nextBasisBytes)
                return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
            basis.sourceUtf8 = state.postBody;
            ctx.installedRangeBytesUsed = ctx.installedRangeBytesUsed - retained + nextBasisBytes;
            CjguiInternalInstalledRangeCandidate updatedBasis = basis.candidate;
            // Only the actual first whole replacement establishes source 0.
            // Queued suffixes keep their captured old root and ACK=0 identity.
            if (v.wholeChoiceNonce) updatedBasis.sourceStartByte = 0;
            updatedBasis.sourceEndByte = updatedBasis.sourceStartByte + state.postBody.length;
            basis.candidate = updatedBasis;
            ctx.installedRangeObservedAckSequence = v.seq;
            ctx.installedRangeObservedAckVersion = receiptVersionAfter;
            CjguiSettleInstalledRangeLocalEditForAck(ctx, state, v);
            CjguiAdvanceCaretInputFromOwnerRangeAck(ctx,state,v);
        } else {
            basis.chainClosed = YES;
            uint64_t releasing = state.chargedBytes;
            ctx.installedRangeBytesUsed = ctx.installedRangeBytesUsed >= releasing
                ? ctx.installedRangeBytesUsed - releasing : 0;
        }
        state.settled = YES;
        ctx.claimedInstalledRangeIntent = nil;
        // A legal predecessor ACK can make a held FIFO head serviceable.
        CjguiOwnerPumpTicketNoteWork(ctx);
#ifdef CJGUI_INTERNAL_TESTING
        if (gCjguiInstalledRangeAckFaultInjected &&
            session == gCjguiInstalledRangeAckFaultSession &&
            v.seq == gCjguiInstalledRangeAckFaultSequence) {
            fprintf(stderr,
                "CJGUI_TEST_INSTALLED_RANGE_ACK_RETRY_SUCCESS session=%llu seq=%llu accepted=%u version=%lld\n",
                (unsigned long long)session, (unsigned long long)v.seq, accepted,
                (long long)receiptVersionAfter);
        }
#endif
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_release_installed_range(
    uint64_t session, uint64_t windowInstanceToken, uint64_t bindingEpoch) {
    if (!windowInstanceToken || !bindingEpoch) return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiInstalledRangeState *states[] = {ctx.installedRangeCandidate, ctx.installedRangeProvisional,
            ctx.installedRangeBasis, ctx.installedRangeRecoveryBlock, ctx.sourceHandoffCandidate,
            ctx.sourceHandoffProvisional, ctx.sourceHandoffRollbackBasis};
        for (NSUInteger i=0;i<sizeof(states)/sizeof(states[0]);i++) {
            CjguiInstalledRangeState *state=states[i];
            if (state && state.candidate.windowInstanceToken==windowInstanceToken &&
                state.candidate.bindingEpoch==bindingEpoch) {
                uint64_t bytes=CjguiInstalledRangeStateBytes(state);
                ctx.installedRangeBytesUsed=ctx.installedRangeBytesUsed>=bytes?ctx.installedRangeBytesUsed-bytes:0;
            }
        }
        if (ctx.selectionPaintWindowToken == windowInstanceToken && ctx.selectionPaintBindingEpoch == bindingEpoch) {
            ctx.selectionPaintTransferId = 0;
            ctx.selectionPaintStagedScene = 0;
        }
        if (ctx.installedRangeCandidate.candidate.windowInstanceToken==windowInstanceToken &&
            ctx.installedRangeCandidate.candidate.bindingEpoch==bindingEpoch) ctx.installedRangeCandidate=nil;
        if (ctx.installedRangeProvisional.candidate.windowInstanceToken==windowInstanceToken &&
            ctx.installedRangeProvisional.candidate.bindingEpoch==bindingEpoch) ctx.installedRangeProvisional=nil;
        if (ctx.installedRangeBasis.candidate.windowInstanceToken==windowInstanceToken &&
            ctx.installedRangeBasis.candidate.bindingEpoch==bindingEpoch) ctx.installedRangeBasis=nil;
        if (ctx.installedRangeRecoveryBlock.candidate.windowInstanceToken==windowInstanceToken &&
            ctx.installedRangeRecoveryBlock.candidate.bindingEpoch==bindingEpoch) ctx.installedRangeRecoveryBlock=nil;
        if (ctx.sourceHandoffCandidate.candidate.windowInstanceToken==windowInstanceToken &&
            ctx.sourceHandoffCandidate.candidate.bindingEpoch==bindingEpoch) ctx.sourceHandoffCandidate=nil;
        if (ctx.sourceHandoffProvisional.candidate.windowInstanceToken==windowInstanceToken &&
            ctx.sourceHandoffProvisional.candidate.bindingEpoch==bindingEpoch) ctx.sourceHandoffProvisional=nil;
        if (ctx.sourceHandoffCommitted.candidate.windowInstanceToken==windowInstanceToken &&
            ctx.sourceHandoffCommitted.candidate.bindingEpoch==bindingEpoch) {
            ctx.sourceHandoffCommitted=nil; ctx.sourceHandoffInputBlocked=NO;
        }
        if (ctx.sourceHandoffRollbackBasis.candidate.windowInstanceToken==windowInstanceToken &&
            ctx.sourceHandoffRollbackBasis.candidate.bindingEpoch==bindingEpoch) ctx.sourceHandoffRollbackBasis=nil;
        for (CJGuiInternalQueuedInteraction *queued in ctx.pendingInteractions) {
            CjguiInstalledRangeIntentState *state=queued.installedRangeIntent;
            if (!state || state.value.windowInstanceToken!=windowInstanceToken || state.value.bindingEpoch!=bindingEpoch) continue;
            queued.installedRangeOwnedInvalid=YES;
            queued.installedRangeNonce=state.value.nonce;
            if (!state.claimed && !state.settled) {
                ctx.installedRangeBytesUsed=ctx.installedRangeBytesUsed>=state.chargedBytes
                    ?ctx.installedRangeBytesUsed-state.chargedBytes:0;
                state.settled=YES; queued.installedRangeIntent=nil;
            }
        }
        CJGuiInternalQueuedInteraction *pumped=ctx.pumpedInstalledRangeInteraction;
        CjguiInstalledRangeIntentState *pumpedState=pumped.installedRangeIntent;
        if (pumpedState && pumpedState.value.windowInstanceToken==windowInstanceToken &&
            pumpedState.value.bindingEpoch==bindingEpoch) {
            pumped.installedRangeOwnedInvalid=YES;
            pumped.installedRangeNonce=pumpedState.value.nonce;
            if (!pumpedState.claimed && !pumpedState.settled) {
                ctx.installedRangeBytesUsed=ctx.installedRangeBytesUsed>=pumpedState.chargedBytes
                    ?ctx.installedRangeBytesUsed-pumpedState.chargedBytes:0;
                pumpedState.settled=YES; pumped.installedRangeIntent=nil;
            }
        }
        if (ctx.claimedInstalledRangeIntent && !ctx.claimedInstalledRangeIntent.settled &&
            ctx.claimedInstalledRangeIntent.value.windowInstanceToken==windowInstanceToken &&
            ctx.claimedInstalledRangeIntent.value.bindingEpoch==bindingEpoch) {
            CjguiInstalledRangeIntentState *state=ctx.claimedInstalledRangeIntent;
            uint64_t releasing=state.chargedBytes;
            ctx.installedRangeBytesUsed=ctx.installedRangeBytesUsed>=releasing
                ?ctx.installedRangeBytesUsed-releasing:0;
            state.settled=YES; ctx.claimedInstalledRangeIntent=nil;
        }
        CjguiInstalledRangeIntentState *reservation=ctx.installedRangeReservation;
        if (reservation && reservation.value.windowInstanceToken==windowInstanceToken &&
            reservation.value.bindingEpoch==bindingEpoch)
            CjguiRetireInstalledRangeReservation(ctx,reservation);
        ctx.installedRangeObservedAckSequence=0; ctx.installedRangeObservedAckVersion=-1;
        ctx.installedRangeLocalTailSequence=0; ctx.installedRangeNextSequence=0;
        CjguiMarkInstalledRangeSourceParked(ctx,NO);
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

static void CjguiCancelSourceProxyPreparation(CJGuiInternalSession *ctx);

// AppKit owns the event queue from beginDraggingSession through the source's
// ended callback. A CJGUI window pump in the same process must not dequeue
// the mouse-up (including when it belongs to a different CJGUI window).
// All mutations and the pump below run on the process main thread.
static NSUInteger gCjguiActiveDataTransferDragSessions = 0;
static uint64_t gCjguiNextSessionGeneration = 1;
static char CJGuiSessionWindowAssociationKey;
// The launcher installs NSApplication.run for this process. Permission to
// marshal work may be gated by tests; ownership of NSEvent never changes.
static _Atomic(bool) gCjguiLauncherOwnsEventLoop;
// Standard Quit may reach AppKit several times before the Cangjie application
// worker gets its next bounded turn. Retain only one process-level intent;
// completion is acknowledged by that owner after it accepts or rejects.
static _Atomic(bool) gCjguiApplicationExitRequestPending;
static _Atomic(bool) gCjguiApplicationExitRequestWasUnkeyed;
static _Atomic(uint32_t) gCjguiApplicationExitLifecycleOwnerCount;

// Modifier state belongs to the pointer gesture that produced an intent, not
// to the session. An activation queued by a mouse press/complete carries the
// modifiers observed for that gesture; a keyboard or accessibility activation
// carries none, so it can never inherit the Command/Shift of an earlier mouse
// click. `session.pointerModifierFlags` is still refreshed by every pointer
// event, and only pointer-originated enqueues copy it onto their own intent.
static void CjguiStampPointerModifiersOnQueuedInteraction(CJGuiInternalSession *session,
                                                          uint32_t kind, uint32_t nodeIndex) {
    if (!session || session.destroyed) return;
    CJGuiInternalQueuedInteraction *last = session.pendingInteractions.lastObject;
    if (!last || last.kind != kind || last.recordIndex != nodeIndex) return;
    last.modifierFlags = session.pointerModifierFlags;
}

// The same rule for keyboard-produced intents: a navigation/select-all queued
// by a keyDown carries the modifiers observed on THAT key event (Shift extends
// a range, Command selects all), while a programmatic or accessibility enqueue
// keeps zero and can never inherit an earlier gesture's state.
// A mouse-down on a pointer-reporting, non-input node must carry WHERE it
// happened: the controller resolves the display offset from that point through
// the framework's hit test, so an ACTIVATE without coordinates is useless.
static void CjguiCapturePrecisePointer(CJGuiInternalQueuedInteraction *interaction,
                                       CJGuiInternalComposableSceneNode *node, NSPoint point);

static void CjguiStampPointerPositionOnQueuedInteraction(CJGuiInternalSession *session,
                                                         uint32_t kind, uint32_t nodeIndex,
                                                         NSPoint point) {
    if (!session || session.destroyed) return;
    CJGuiInternalQueuedInteraction *last = session.pendingInteractions.lastObject;
    if (!last || last.kind != kind || last.recordIndex != nodeIndex) return;
    if (nodeIndex >= session.composableNodes.count) return;
    CjguiCapturePrecisePointer(last, session.composableNodes[nodeIndex], point);
}

// Focus is enqueued before the paired selection/activation record, so stamp
// the most recent matching focus record rather than assuming it is still the
// FIFO tail. Used only by the overlay's physical mouse-down path.
static void CjguiStampPointerPositionOnRecentQueuedInteraction(CJGuiInternalSession *session,
                                                               uint32_t kind, uint32_t nodeIndex,
                                                               NSPoint point, NSUInteger firstPendingIndex) {
    if (!session || session.destroyed || nodeIndex >= session.composableNodes.count) return;
    for (NSInteger index = (NSInteger)session.pendingInteractions.count - 1;
         index >= (NSInteger)firstPendingIndex; index--) {
        CJGuiInternalQueuedInteraction *interaction = session.pendingInteractions[(NSUInteger)index];
        if (interaction.kind == kind && interaction.recordIndex == nodeIndex &&
            interaction.projectionVersion == session.composableSceneVersion) {
            CjguiCapturePrecisePointer(interaction, session.composableNodes[nodeIndex], point);
            return;
        }
    }
}

static BOOL CjguiInteractionIsTextHistory(CJGuiInternalQueuedInteraction *interaction) {
    return interaction.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_WINDOW_COMMAND &&
        ([interaction.formText isEqualToString:@"shortcut:command+z"] ||
         [interaction.formText isEqualToString:@"shortcut:shift+command+z"]);
}

static void CjguiStampKeyboardModifiersOnQueuedInteraction(CJGuiInternalSession *session,
                                                           uint32_t kind, uint32_t nodeIndex,
                                                           NSEventModifierFlags flags) {
    if (!session || session.destroyed) return;
    CJGuiInternalQueuedInteraction *last = session.pendingInteractions.lastObject;
    if (!last || last.kind != kind || last.recordIndex != nodeIndex) return;
    last.modifierFlags = (int64_t)flags;
    // Physical caret keys and text history commands share the same owner
    // prefix. A window command without an actual text installation retains
    // its strict captured-scene route and has no text provenance.
    BOOL history = CjguiInteractionIsTextHistory(last);
    BOOL caret = kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_NAVIGATE &&
        ([last.formText isEqualToString:@"up"] || [last.formText isEqualToString:@"down"] ||
         [last.formText isEqualToString:@"left"] || [last.formText isEqualToString:@"right"] ||
         [last.formText isEqualToString:@"deleteBackward"] || [last.formText isEqualToString:@"deleteForward"] ||
         [last.formText isEqualToString:@"select_all"]);
    if (!caret && !history) return;
    if (history && !(session.ownerSelectionHandoff.valid && !session.ownerSelectionHandoff.completed) &&
        !CjguiInstalledRangeBasisMatchesActual(session,session.composableSceneOverlay) &&
        !session.activeCaretNavigation.caretInputBranch.valid) return;
    if (session.lastVerticalInputSequence == UINT64_MAX || !session.sessionGeneration) {
        // The key has not yet escaped the FIFO. Remove this exact tail item
        // rather than deliver an unidentifiable event after sequence exhaustion.
        [session.pendingInteractions removeLastObject];
        session.pendingInputQueueFullNotice = YES;
        CjguiOwnerPumpTicketNoteWork(session);
        return;
    }
    last.inputSessionGeneration = session.sessionGeneration;
    last.inputPreviousSequence = session.lastVerticalInputSequence;
    last.inputSequence = session.lastVerticalInputSequence + 1;
    last.caretInputOriginalSceneVersion = last.projectionVersion;
    last.caretInputOriginalNodeId = last.nodeId;
    last.caretInputOriginalResourceId = last.resourceId;
    last.caretInputOriginalNodeKind = last.nodeKind;
    session.lastVerticalInputSequence = last.inputSequence;
    CjguiOwnerSelectionHandoff *ownerH=session.ownerSelectionHandoff;
    if(ownerH.valid && !ownerH.completed) {
        CjguiCaretInputSnapshot *actual=CjguiCaptureCaretInputSnapshot(session);
        BOOL original=CjguiFrozenCaretSourceMatchesActual(session,ownerH.branch.result);
        BOOL ownB=actual && ownerH.sealed && actual.candidate.nonce==ownerH.transferId &&
            actual.acceptedVersion==ownerH.afterVersion &&
            CjguiInstalledRangeBasisMatchesActual(session,session.composableSceneOverlay);
        if(!ownerH.branch.valid || !actual || actual.candidate.windowInstanceToken!=ownerH.windowToken ||
            actual.candidate.contextEpoch!=ownerH.contextEpoch || (!original && !ownB)) {
            CjguiTraceOwnerHandoffProducerIdentity(session,ownerH,actual);
            CjguiRetireOwnerHandoff(session,ownerH,"producer_binding_changed");
            [session.pendingInteractions removeObject:last];return;
        }
        last.ownerHandoff=ownerH;last.caretInputOrigin=actual;last.caretInputBranch=ownerH.branch;
        ownerH.branch.lastProducedSequence=last.inputSequence;
        fprintf(stderr,"CJGUI_OWNER_HANDOFF_INPUT id=%llu kind=caret seq=%llu previous=%llu original_A=%lld\n",
            (unsigned long long)ownerH.identity,(unsigned long long)last.inputSequence,
            (unsigned long long)last.inputPreviousSequence,(long long)actual.acceptedVersion);
    } else if (CjguiPendingOwnerCaretSource(session)) {
        // The owner already accepted the predecessor, but its target scene
        // may omit this still-installed responder while B prepares. Capture
        // this producer's actual A and keep it behind that same prefix.
        CjguiCaretInputSnapshot *a=CjguiPendingOwnerCaretSource(session);
        CjguiCaretInputBranch *branch=session.activeCaretNavigation.caretInputBranch;
        if(!branch.valid || branch!=session.caretInputBranch ||
            !CjguiFrozenCaretSourceMatchesActual(session,a)) {
            CjguiRejectCaretInputBranch(session,branch,"parked_selector_origin_changed");
            [session.pendingInteractions removeObject:last];return;
        }
        last.caretInputBranch=branch;last.caretInputOrigin=CjguiCaptureCaretInputSnapshot(session);
        branch.lastProducedSequence=last.inputSequence;
    } else if (CjguiInstalledRangeBasisMatchesActual(session,session.composableSceneOverlay)) {
        CjguiCaretInputBranch *branch=session.caretInputBranch;
        BOOL hasHeldText=NO;
        for(CJGuiInternalQueuedInteraction *item in session.pendingInteractions)
            if(item.afterCaretTextInput.branch==branch && branch) { hasHeldText=YES; break; }
        if(!branch || !branch.valid ||
            (branch.lastProducedSequence==branch.settledSequence && !hasHeldText)) {
            CjguiCaretInputSnapshot *origin=CjguiCaptureCaretInputSnapshot(session);
            if(origin) {
                branch=[CjguiCaretInputBranch new];
                branch.origin=origin;branch.result=origin;branch.valid=YES;
                branch.settledSequence=last.inputPreviousSequence;
                session.caretInputBranch=branch;
            }
        }
        if(branch && branch.valid) {
            last.caretInputBranch=branch;
            last.caretInputOrigin=CjguiCaptureCaretInputSnapshot(session);
            branch.lastProducedSequence=last.inputSequence;
        }
    }
    if (getenv("CJGUI_CARET_FINISH_TRACE")) {
        CjguiCaretInputSnapshot *origin = last.caretInputOrigin ?: last.caretInputBranch.origin;
        fprintf(stderr, "CJGUI_CARET_INPUT_ORIGIN sequence=%llu previous=%llu intent=%s "
            "generation=%llu origin_present=%d origin_version=%lld ack_version=%lld "
            "nonce=%llu context=%llu binding=%llu scene=%llu node=%llu\n",
            (unsigned long long)last.inputSequence, (unsigned long long)last.inputPreviousSequence,
            last.formText.UTF8String ?: "", (unsigned long long)last.inputSessionGeneration,
            origin != nil, (long long)(origin ? origin.acceptedVersion : -1),
            (long long)session.installedRangeObservedAckVersion,
            (unsigned long long)origin.candidate.nonce,
            (unsigned long long)origin.candidate.contextEpoch,
            (unsigned long long)origin.candidate.bindingEpoch,
            (unsigned long long)last.projectionVersion, (unsigned long long)last.nodeId);
    }
}

// Consecutive text notifications for one field are a single logical input
// stream and may be coalesced. No focus, button, checkbox or cross-field
// boundary is crossed, so an Apply always remains after the text it applies.
// Once full, the queue refuses the new interaction and schedules an explicit
// retry notice instead of overwriting an already accepted event.
static NSUInteger CjguiPendingInteractionOccupancy(CJGuiInternalSession *session) {
    return session.pendingInteractions.count + session.installedRangeSlotsReserved +
        session.rejectedAfterCaretInputs.count + session.exportedCaretRecoveryBytes.count +
        (session.ownerSelectionHandoff.valid && !session.ownerSelectionHandoff.completed ? 1 : 0);
}

static BOOL CjguiEnqueueInteraction(CJGuiInternalSession *session,
                                    uint32_t kind, uint32_t recordIndex,
                                    NSString *formText,
                                    uint32_t selectionStart,
                                    uint32_t selectionEnd) {
    if (!session || session.destroyed) return NO;
    CJGuiInternalQueuedInteraction *last = session.pendingInteractions.lastObject;
    if (kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_FORM_TEXT_CHANGED &&
        last && last.kind == kind && last.recordIndex == recordIndex) {
        last.selectionStart = selectionStart;
        last.selectionEnd = selectionEnd;
        last.formText = [formText copy] ?: @"";
        CjguiOwnerPumpTicketNoteWork(session);
        return YES;
    }
    if (CjguiPendingInteractionOccupancy(session) >= kCjguiPendingInteractionCapacity) {
        session.pendingInputQueueFullNotice = YES;
        CjguiOwnerPumpTicketNoteWork(session);
        return NO;
    }
    CJGuiInternalQueuedInteraction *interaction =
        [[CJGuiInternalQueuedInteraction alloc] initWithKind:kind
                                                  recordIndex:recordIndex
                                               selectionStart:selectionStart
                                                 selectionEnd:selectionEnd
                                                     formText:formText nodeId:0 projectionVersion:0 resourceId:-1 nodeKind:0];
    if (!interaction) {
        session.pendingInputQueueFullNotice = YES;
        CjguiOwnerPumpTicketNoteWork(session);
        return NO;
    }
    // Ordinary form input may arrive from a mouse click as well as from the
    // keyboard/AX proxy; it carries no pointer-gesture modifiers.
    interaction.modifierFlags = 0;
    [session.pendingInteractions addObject:interaction];
    CjguiOwnerPumpTicketNoteWork(session);
    return YES;
}

static BOOL CjguiEnqueueComposableInteraction(CJGuiInternalSession *session,
                                              uint32_t kind, uint32_t nodeIndex,
                                              NSString *text, NSRange selection) {
    if (!session || session.destroyed) return NO;
    uint64_t nodeId = 0;
    int64_t resourceId = -1;
    uint32_t nodeKind = 0;
    if (kind != CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_RESIZED) {
        if (nodeIndex >= session.composableNodes.count) return NO;
        nodeId = CjguiComposableNodeIdAtIndex(session, nodeIndex);
        resourceId = CjguiComposableNodeResourceIdAtIndex(session, nodeIndex);
        nodeKind = CjguiComposableNodeKindAtIndex(session, nodeIndex);
        if (nodeId == 0) return NO;
    }
    if (kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_FOCUS ||
        (nodeId == session.ownedTextSessionNodeId && resourceId == session.ownedTextSessionResourceId &&
         (kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_CHANGED ||
          kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_SELECTION_CHANGED ||
          kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_NAVIGATE ||
          kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_RANGE_CHANGED ||
          kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_COMPOSITION))) {
        // Retire only private preparation. The original event, FIFO prefix
        // and public restore request are still consumed by their owners.
        CjguiCancelSourceProxyPreparation(session);
    }
    CJGuiInternalQueuedInteraction *last = session.pendingInteractions.lastObject;
    if ((kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_CHANGED ||
         kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_SELECTION_CHANGED) &&
        last && last.kind == kind && last.recordIndex == nodeIndex &&
        last.nodeId == nodeId &&
        last.projectionVersion == session.composableSceneVersion &&
        last.resourceId == resourceId && last.nodeKind == nodeKind) {
        last.selectionStart = (uint32_t)MIN(selection.location, UINT32_MAX);
        last.selectionEnd = (uint32_t)MIN(NSMaxRange(selection), UINT32_MAX);
        last.formText = [text copy] ?: @"";
        // This is a fresh non-pointer notification. Explicit pointer handlers
        // stamp their own origin after enqueue/coalescing; an older pointer
        // must never authorize the new notification as human selection.
        last.hasPrecisePointer = NO;
        last.pointerX = 0; last.pointerY = 0;
        last.precisePointerX = 0; last.precisePointerY = 0;
        last.pointerTranslateX = 0; last.pointerTranslateY = 0;
        last.modifierFlags = 0;
        CjguiOwnerPumpTicketNoteWork(session);
        return YES;
    }
    if (CjguiPendingInteractionOccupancy(session) >= kCjguiPendingInteractionCapacity) {
        session.pendingInputQueueFullNotice = YES;
        CjguiOwnerPumpTicketNoteWork(session);
        return NO;
    }
    CJGuiInternalQueuedInteraction *interaction =
        [[CJGuiInternalQueuedInteraction alloc] initWithKind:kind recordIndex:nodeIndex
                                               selectionStart:(uint32_t)MIN(selection.location, UINT32_MAX)
                                                 selectionEnd:(uint32_t)MIN(NSMaxRange(selection), UINT32_MAX)
                                                     formText:text nodeId:nodeId projectionVersion:session.composableSceneVersion
                                                   resourceId:resourceId nodeKind:nodeKind];
    if (!interaction) {
        session.pendingInputQueueFullNotice = YES;
        CjguiOwnerPumpTicketNoteWork(session);
        return NO;
    }
    // Non-pointer enqueue: a keyboard/AX activation, focus transfer or
    // declared shortcut must not inherit an earlier mouse gesture's modifiers.
    // Pointer-originated intents are stamped by their own handler.
    interaction.modifierFlags = 0;
    interaction.physicalProducerNonce=session.physicalProducerDepth ? session.physicalProducerNonce : 0;
    [session.pendingInteractions addObject:interaction];
    CjguiOwnerPumpTicketNoteWork(session);
#ifdef CJGUI_INTERNAL_TESTING
    session.testComposableLastEnqueuedKind = kind;
    session.testComposableLastEnqueuedNodeId = nodeId;
    session.testComposableLastEnqueuedProjectionVersion = session.composableSceneVersion;
    session.testComposableMaxPendingInteractionCount = (uint32_t)MIN(
        UINT32_MAX, MAX((NSUInteger)session.testComposableMaxPendingInteractionCount, session.pendingInteractions.count));
#endif
    return YES;
}

static BOOL CjguiRefuseSourceSelectionInput(CJGuiInternalSession *session, NSString *intent) {
    if (!CjguiSourceInstallPending(session)) return NO;
    for (uint32_t index = 0; index < session.composableNodes.count; ++index) {
        if (CjguiComposableNodeIdAtIndex(session, index) == session.ownedTextSessionNodeId &&
            CjguiComposableNodeResourceIdAtIndex(session, index) == session.ownedTextSessionResourceId &&
            CjguiComposableNodeKindAtIndex(session, index) == session.ownedTextSessionNodeKind) {
            (void)CjguiEnqueueComposableInteraction(session,
                CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_NAVIGATE, index,
                [@"selection_install_pending:" stringByAppendingString:intent ?: @"text"], NSMakeRange(0, 0));
            return YES;
        }
    }
    // The new source can be absent from the old accepted scene. Refusal is
    // still an observable FIFO outcome; it cannot address or modify that scene.
    if (CjguiPendingInteractionOccupancy(session) < kCjguiPendingInteractionCapacity) {
        CJGuiInternalQueuedInteraction *notice = [[CJGuiInternalQueuedInteraction alloc]
            initWithKind:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_NAVIGATE
            recordIndex:0 selectionStart:0 selectionEnd:0
            formText:[@"selection_install_pending:" stringByAppendingString:intent ?: @"text"]
            nodeId:session.ownedTextSessionNodeId projectionVersion:session.composableSceneVersion
            resourceId:session.ownedTextSessionResourceId nodeKind:session.ownedTextSessionNodeKind];
        if (notice) {
            [session.pendingInteractions addObject:notice];
            CjguiOwnerPumpTicketNoteWork(session);
        } else {
            session.pendingInputQueueFullNotice = YES;
            CjguiOwnerPumpTicketNoteWork(session);
        }
    } else {
        session.pendingInputQueueFullNotice = YES;
        CjguiOwnerPumpTicketNoteWork(session);
    }
    return YES;
}


static void CjguiStampActualActivationPair(CJGuiInternalSession *session, NSUInteger firstIndex) {
    if (!session || session.destroyed || session.pendingInteractions.count != firstIndex + 2 ||
        session.nextActivationPairNonce == UINT64_MAX) return;
    CJGuiInternalQueuedInteraction *first = session.pendingInteractions[firstIndex];
    CJGuiInternalQueuedInteraction *second = session.pendingInteractions[firstIndex + 1];
    if (first.kind != CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_FOCUS ||
        (second.kind != CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_ACTIVATE &&
         second.kind != CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_BOOLEAN_CHANGED) ||
        first.nodeId != second.nodeId || first.resourceId != second.resourceId ||
        first.nodeKind != second.nodeKind || first.projectionVersion != second.projectionVersion) return;
    CjguiInternalActivationPrefix prefix = {
        .sessionGeneration = session.sessionGeneration, .nonce = ++session.nextActivationPairNonce,
        .sceneVersion = first.projectionVersion, .nodeId = first.nodeId, .resourceId = first.resourceId,
        .bindingEpoch = session.ownedTextSessionBindingEpoch, .nodeKind = first.nodeKind,
        .ordinal = 1, .secondKind = second.kind, .memberCount = 2, .memberKind = first.kind,
    };
    first.activationPrefix = prefix;
    prefix.ordinal = 2;
    prefix.memberKind = second.kind;
    second.activationPrefix = prefix;
}

// Preflight this callback's actual bounded tail before assigning any prefix.
static void CjguiSealPhysicalPressPrefix(CJGuiInternalSession *ctx, NSUInteger first,
    uint64_t nonce, uint64_t generation, uint64_t scene, uint64_t binding, uint64_t dequeue) {
    if (!ctx) return;
    NSUInteger count=ctx.pendingInteractions.count;
    CJGuiInternalQueuedInteraction *terminal=ctx.physicalProducerTerminal;
    if (ctx.destroyed || ctx.physicalProducerContaminated || !nonce ||
        ctx.sessionGeneration!=generation || ctx.composableSceneVersion!=scene ||
        ctx.ownedTextSessionBindingEpoch!=binding || ctx.inputDequeueSerial!=dequeue ||
        dequeue==UINT64_MAX || first>=count || count-first>kCjguiPendingInteractionCapacity ||
        !terminal || terminal!=ctx.pendingInteractions.lastObject ||
        terminal.kind!=CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_PRESS_BEGIN) return;
    for (NSUInteger i=first; i<count; ++i) {
        CJGuiInternalQueuedInteraction *member=ctx.pendingInteractions[i];
        BOOL last=i+1==count;
        BOOL allowed=last ? member.kind==CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_PRESS_BEGIN :
            (member.kind==CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_HOVER_ENTER ||
             member.kind==CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_HOVER_LEAVE ||
             member.kind==CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_FOCUS ||
             member.kind==CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_PRESS_CANCEL);
        if (!allowed || member.physicalProducerNonce!=nonce || member.activationPrefix.nonce ||
            member.projectionVersion!=scene || !member.nodeId ||
            (member.kind==CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_PRESS_CANCEL && !member.bindingEpoch)) return;
    }
    for (NSUInteger i=first; i<count; ++i) {
        CJGuiInternalQueuedInteraction *member=ctx.pendingInteractions[i];
        member.activationPrefix=(CjguiInternalActivationPrefix){
            .sessionGeneration=generation,.nonce=nonce,.sceneVersion=member.projectionVersion,
            .nodeId=member.nodeId,.resourceId=member.resourceId,.bindingEpoch=binding,
            .nodeKind=member.nodeKind,.ordinal=(uint32_t)(i-first+1),
            .secondKind=CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_PRESS_BEGIN,
            .memberCount=(uint32_t)(count-first),.memberKind=member.kind };
    }
}

static BOOL CjguiEnqueueCompositionPhase(CJGuiInternalSession *session, uint32_t phase,
                                         uint32_t nodeIndex, NSString *text, NSRange inner,
                                         int64_t replacementStart, int64_t replacementLength,
                                         int64_t markedStart, int64_t markedLength,
                                         uint64_t compositionId, uint64_t bindingEpoch) {
    if (!session || session.destroyed) return NO;
    if (CjguiPendingInteractionOccupancy(session) >= kCjguiPendingInteractionCapacity) {
        // A dropped terminal is never treated as delivered: the same notice the
        // ordinary path raises tells the owner the edit did not reach it.
        session.pendingInputQueueFullNotice = YES;
        CjguiOwnerPumpTicketNoteWork(session);
        return NO;
    }
    CJGuiInternalQueuedInteraction *interaction =
        [[CJGuiInternalQueuedInteraction alloc] initWithKind:
            CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_COMPOSITION
            recordIndex:nodeIndex
            selectionStart:(uint32_t)MIN(inner.location, UINT32_MAX)
            selectionEnd:(uint32_t)MIN(NSMaxRange(inner), UINT32_MAX)
            formText:text
            nodeId:CjguiComposableNodeIdAtIndex(session, nodeIndex)
            projectionVersion:session.composableSceneVersion
            resourceId:CjguiComposableNodeResourceIdAtIndex(session, nodeIndex)
            nodeKind:CjguiComposableNodeKindAtIndex(session, nodeIndex)];
    if (!interaction) {
        session.pendingInputQueueFullNotice = YES;
        CjguiOwnerPumpTicketNoteWork(session);
        return NO;
    }
    interaction.modifierFlags = 0;
    interaction.compositionPhase = phase;
    interaction.replacementStart16 = replacementStart;
    interaction.replacementLength16 = replacementLength;
    interaction.markedStart16 = markedStart;
    interaction.markedLength16 = markedLength;
    interaction.compositionId = compositionId;
    interaction.bindingEpoch = bindingEpoch;
    [session.pendingInteractions addObject:interaction];
    CjguiOwnerPumpTicketNoteWork(session);
#ifdef CJGUI_INTERNAL_TESTING
    session.testComposableLastEnqueuedKind = interaction.kind;
    session.testComposableLastEnqueuedNodeId = interaction.nodeId;
    session.testComposableLastEnqueuedProjectionVersion = session.composableSceneVersion;
    session.testComposableMaxPendingInteractionCount = (uint32_t)MIN(
        UINT32_MAX, MAX((NSUInteger)session.testComposableMaxPendingInteractionCount, session.pendingInteractions.count));
#endif
    return YES;
}

// Bodies live after the overlay/scene-node interfaces; these forward
// declarations keep the enqueue helpers in their existing section.
static NSInteger CjguiIndexOfComposableNodeIdentity(CJGuiInternalComposableSceneOverlay *overlay,
                                                    uint64_t nodeId, int64_t resourceId,
                                                    uint32_t nodeKind);
static BOOL CjguiEmitProxyCompositionPhase(CJGuiInternalComposableInputProxy *proxy, uint32_t phase,
                                           NSString *text, NSRange inner, NSRange replacement,
                                           NSRange marked);

// The text an NSTextInputClient argument carries. The protocol declares `id`
// because an attributed string is allowed for richer input; the composition
// record always needs its plain string.
static NSString *CjguiInputArgumentText(id string) {
    if ([string isKindOfClass:[NSAttributedString class]]) return [(NSAttributedString *)string string];
    if ([string isKindOfClass:[NSString class]]) return (NSString *)string;
    return nil;
}

// AppKit resolves a not-specified replacement range BEFORE mutating: the
// current marked range while composing, otherwise the selection. Recording the
// resolution keeps the session's frozen owner range comparable with what the
// platform actually replaces.
static NSRange CjguiResolvedPlatformReplacement(NSTextView *proxy, NSRange replacementRange) {
    if (replacementRange.location != NSNotFound) return replacementRange;
    if (proxy.hasMarkedText) return proxy.markedRange;
    return proxy.selectedRange;
}

#ifdef CJGUI_INTERNAL_TESTING
static uint64_t CjguiTestUtf8ByteCount(NSString *value) {
    NSData *bytes = [(value ?: @"") dataUsingEncoding:NSUTF8StringEncoding];
    return bytes ? (uint64_t)bytes.length : 0;
}

static BOOL CjguiTestIsDataTransferKind(uint32_t kind) {
    return kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_DATA_TRANSFER_COPY ||
        kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_DATA_TRANSFER_PASTE ||
        kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_DATA_TRANSFER_DROP;
}

static uint64_t CjguiTestTransferItemRetainedBytes(CJGuiInternalComposableDataTransferItem *item) {
    if (!item) return 0;
    return CjguiTestUtf8ByteCount(item.format) + CjguiTestUtf8ByteCount(item.payload) +
        item.binaryPayload.length +
        CjguiTestUtf8ByteCount(item.sourceKind) + CjguiTestUtf8ByteCount(item.sourceIdentity);
}

static uint64_t CjguiTestTransferSourcePayloadBytes(NSArray<CJGuiInternalComposableDataTransferItem *> *items) {
    uint64_t total = 0;
    for (CJGuiInternalComposableDataTransferItem *item in items) {
        if (item.item.role == CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_SOURCE) {
            total += CjguiTestUtf8ByteCount(item.payload) + item.binaryPayload.length;
        }
    }
    return total;
}

static uint64_t CjguiTestTransferDeclarationBytes(NSArray<CJGuiInternalComposableDataTransferItem *> *items) {
    uint64_t total = 0;
    for (CJGuiInternalComposableDataTransferItem *item in items) {
        total += CjguiTestTransferItemRetainedBytes(item);
    }
    return total;
}

static uint64_t CjguiTestTransferFifoBytes(CJGuiInternalSession *session, uint32_t *outEvents) {
    uint64_t total = 0;
    uint32_t events = 0;
    if (session) {
        for (CJGuiInternalQueuedInteraction *interaction in session.pendingInteractions) {
            if (!CjguiTestIsDataTransferKind(interaction.kind)) continue;
            events += 1;
            total += CjguiTestUtf8ByteCount(interaction.formText) + interaction.dataTransferBytes.length +
                CjguiTestUtf8ByteCount(interaction.dataTransferFormat) +
                CjguiTestUtf8ByteCount(interaction.dataTransferSourceKind) +
                CjguiTestUtf8ByteCount(interaction.dataTransferSourceIdentity);
        }
    }
    if (outEvents) *outEvents = events;
    return total;
}

static void CjguiUpdateTestDataTransferRetentionPeaks(CJGuiInternalSession *session) {
    if (!session) return;
    uint64_t source = CjguiTestTransferSourcePayloadBytes(session.composableDataTransferItems);
    uint64_t accepted = CjguiTestTransferDeclarationBytes(session.composableDataTransferItems);
    uint64_t candidate = CjguiTestTransferDeclarationBytes(session.stagedComposableDataTransferItems);
    uint32_t fifoEvents = 0;
    uint64_t fifoBytes = CjguiTestTransferFifoBytes(session, &fifoEvents);
    session.testDataTransferSourcePeakBytes = MAX(session.testDataTransferSourcePeakBytes, source);
    session.testDataTransferAcceptedPeakBytes = MAX(session.testDataTransferAcceptedPeakBytes, accepted);
    session.testDataTransferCandidatePeakBytes = MAX(session.testDataTransferCandidatePeakBytes, candidate);
    session.testDataTransferFifoPeakEvents = (uint32_t)MIN(UINT32_MAX,
        MAX((NSUInteger)session.testDataTransferFifoPeakEvents, (NSUInteger)fifoEvents));
    session.testDataTransferFifoPeakBytes = MAX(session.testDataTransferFifoPeakBytes, fifoBytes);
}
#endif

// ---- generic composable-scene data and native projection ----

static const NSUInteger CjguiComposableImageTextureCacheCapacity = 8;
static const NSUInteger CjguiComposableImageTextureCacheByteCapacity = 32u * 1024u * 1024u;
static const NSUInteger CjguiComposableImageInFlightCapacity = 4;
static const NSUInteger CjguiComposableImagePendingCapacity = 16;
static const NSUInteger CjguiComposableImageRecordCapacity = 64;
// Text is derived presentation, not document storage.  Keep a single scene
// bounded even when a malformed projection supplies enormous logical bounds.
// A Retina normal Host can expose several dozen short text rows at once.
// 24 MiB stays explicitly bounded (and below the existing image-cache
// envelope) while admitting that ordinary 256-node viewport during resize.
// A 1000x400pt editor is 6.4 MiB at 2x, so a 4 MiB per-tile limit rejected a
// normal fully visible editor.  Keep one CPU bitmap + one scene texture
// bounded at 8 MiB; the scene admission check still caps all live text at
// 24 MiB rather than letting individual controls grow without limit.
static const NSUInteger CjguiComposableTextTextureByteCapacity = 24u * 1024u * 1024u;
static const NSUInteger CjguiComposableTextTexturePerNodeByteCapacity = 8u * 1024u * 1024u;
static const NSUInteger CjguiComposableTextTextureDimensionCapacity = 4096u;

// Error-only attribution for the existing bounded preparation paths. The
// status and admission limits stay unchanged; a refusal needs its actual
// producer location before it can be classified as capacity or retirement.
static CjguiInternalRendererStatus CjguiTextPreparationBudgetRefusal(
    const char *site, unsigned line) {
    if (getenv("CJGUI_TEXT_PREPARE_TRACE")) {
        uint64_t tid = 0;
        int identityStatus = pthread_threadid_np(NULL, &tid);
        fprintf(stderr, "CJGUI_TEXT_BUDGET_REFUSED mono_ns=%llu turn=%llu "
            "thread=%llu identity_status=%d site=%s line=%u\n",
            (unsigned long long)cjgui_internal_renderer_owner_clock_ns(),
            (unsigned long long)atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn,
                memory_order_acquire),
            (unsigned long long)tid, identityStatus, site, line);
    }
    return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
}

// A group target is an immutable content generation once submitted. Its
// resolved texture holds premultiplied BGRA8Unorm pixels; a 4x attachment is
// retained only when the scene contains vectors. No pool is used in P4: reuse
// means the accepted content target was proven unchanged, never that a retired
// in-flight allocation was recycled for different pixels.
@interface CJGuiInternalComposableEffectTarget : NSObject
@property(nonatomic, strong) id<MTLTexture> resolvedTexture;
@property(nonatomic, strong) id<MTLTexture> multisampleTexture;
@property(nonatomic, copy) NSString *contentSignature;
@property(nonatomic, assign) uint32_t pixelX;
@property(nonatomic, assign) uint32_t pixelY;
@property(nonatomic, assign) uint32_t pixelWidth;
@property(nonatomic, assign) uint32_t pixelHeight;
// Exact backdrop dependency halo used when this target was allocated. A
// cache hit retains these facts rather than recomputing them at read time.
@property(nonatomic, assign) uint32_t samplePixelX;
@property(nonatomic, assign) uint32_t samplePixelY;
@property(nonatomic, assign) uint32_t samplePixelWidth;
@property(nonatomic, assign) uint32_t samplePixelHeight;
@property(nonatomic, assign) uint64_t lastRedrawnFrameIndex;
@property(nonatomic, assign) uint64_t byteCount;
@property(nonatomic, assign) BOOL needsRedraw;
@property(nonatomic, assign) BOOL invalidatedByGpuFailure;
// A completion callback can run off the main thread before its main-queue
// bookkeeping turn. The atomic one-way success bit admits safe cache hits
// without blocking a following main-thread frame on that bookkeeping turn.
@property(atomic, assign) BOOL gpuCompleted;
@end

@implementation CJGuiInternalComposableEffectTarget
@end

typedef NS_ENUM(uint32_t, CjguiComposableImageResourceState) {
    CjguiComposableImageResourceUnrequested = 0,
    CjguiComposableImageResourceLoading = 1,
    CjguiComposableImageResourceReady = 2,
    CjguiComposableImageResourceFailed = 3,
    // Admission is temporarily full. This is not a file/decode failure;
    // visible scene references are promoted fairly by the next completion.
    CjguiComposableImageResourceBusy = 4,
};

@class CjguiPreparedTextNodeLayout;   // 2026-09-26 B2:accepted 文本几何索引(前置声明)

@interface CJGuiInternalComposableSceneNode : NSObject
// The style-run string this node was last staged with. It belongs in the text
// texture key, otherwise a run-only change reuses the previous texture.
@property(nonatomic, copy) NSString *styleRunsSignature;
@property(nonatomic, assign) CjguiInternalRendererComposableNode node;
@property(nonatomic, assign) CjguiInternalRendererComposableGeometry geometry;
@property(nonatomic, copy) NSString *label;
@property(nonatomic, copy) NSString *value;
// The accepted public semantic identity of this node. It is the exact address a
// human-facing driver or assistant uses to target one instance; the rendered
// label is a projection and two instances can share a caption.
@property(nonatomic, copy) NSString *semanticId;
@property(nonatomic, copy) NSString *semanticBindingKey;
@property(nonatomic, copy) NSString *semanticRowKey;
@property(nonatomic, copy) NSString *semanticParentRowKey;
@property(nonatomic, copy) NSString *semanticLabel;
@property(nonatomic, copy) NSString *imageResourcePath;
@property(nonatomic, copy) NSData *imageEncodedData;
@property(nonatomic, copy) NSString *imageResourceId;
@property(nonatomic, assign) uint64_t imageResourceVersion;
// The declared key can advance while an old texture is intentionally retained
// as a loading fallback. Keep the actual texture provenance separate so a
// cache eviction never relabels that old texture as the new declaration.
@property(nonatomic, copy) NSString *imageTextureCacheKey;
@property(nonatomic, copy) NSString *imageTextureContentKey;
@property(nonatomic, strong) id<MTLTexture> imageTexture;
// Raster text is an implementation-local GPU resource.  It contains no
// writable document state: the composable overlay retains the sole TextKit
// input proxy and redraws this immutable projection when content/style/scale
// changes.
@property(nonatomic, copy) NSString *textTextureCacheKey;
// Immutable description of the exact attributed/layout source that produced
// the currently accepted text tiles. It is assigned only after a complete
// raster/upload succeeds and travels with COW clones and rollback snapshots.
@property(nonatomic, strong) id textTextureSourceCredential;
// Opt-in observation retains the immutable graph that actually painted the
// accepted textures. The editable source graph can legitimately remain lazy.
@property(nonatomic, strong) id textVisibilityRasterLayout;
@property(nonatomic, strong) id<MTLTexture> textTexture;
// A large visible text area is split into independently bounded texture
// allocations. Small controls continue to use textTexture directly.
@property(nonatomic, copy) NSArray<id<MTLTexture>> *textTileTextures;
@property(nonatomic, copy) NSArray<NSValue *> *textTileRects;
@property(nonatomic, assign) uint64_t textTextureByteCount;
// Logical scene rectangle represented by textTexture. It may be a clipped
// tile of the node rather than the whole node bounds.
@property(nonatomic, assign) NSRect textTextureRect;
// The rects above are scene coordinates. This accepted origin lets a COW
// candidate match immutable tiles after its integer layout position changes.
@property(nonatomic, assign) NSPoint textTileLayoutOrigin;
// Only the intrinsic typographic extent is memoized. Clip/translation never
// enters this key and remains an accepted-scene calculation on every frame.
@property(nonatomic, copy) NSString *textMeasuredSource;
@property(nonatomic, assign) CGFloat textMeasuredWidth;
@property(nonatomic, assign) double textMeasuredFontSize;
@property(nonatomic, assign) uint32_t textMeasuredFontWeight;
@property(nonatomic, assign) uint32_t textMeasuredFontFamily;
@property(nonatomic, assign) uint32_t textMeasuredNodeKind;
@property(nonatomic, assign) NSSize textMeasuredExtent;
@property(nonatomic, assign) BOOL textMeasureValid;
#ifdef CJGUI_INTERNAL_TESTING
@property(nonatomic, assign) uint64_t testTextExtentMeasurementCount;
#endif
// Selection, marked-range and caret pixels are presentation-only geometry.
// They stay in the scene node's existing clip chain and sandwich the immutable
// body texture in painter order, so a caret move never allocates/reuploads the
// body tile or adds a second text/layout owner.
@property(nonatomic, copy) NSArray<NSValue *> *textSelectionRects;
// Nonzero only when these rectangles were precomputed for one accepted
// source-selection transfer. It prevents stale transfer geometry from being
// mistaken for later owner or local-input geometry after a scene change.
@property(nonatomic, assign) uint64_t textSelectionTransferId;
// Selection-background style runs on ordinary TEXT nodes are accepted paint
// decorations. Each item contains an NSValue rect and its explicit NSColor.
@property(nonatomic, copy) NSArray<NSDictionary *> *textDeclaredSelectionDecorations;
@property(nonatomic, copy) NSArray<NSValue *> *textMarkedRects;
@property(nonatomic, assign) NSRect textCaretRect;
// Distinguishes the caret the OWNER declared (accepted-layout geometry, drawn in the
// node's own text colour) from the one the hidden proxy derived for itself (accent
// colour). Both live in `textCaretRect`; only their presentation differs.
@property(nonatomic, assign) BOOL textCaretIsDeclared;
// Blink only gates paint. Keep the accepted rect for hit/IME geometry.
@property(nonatomic, assign) BOOL textCaretHidden;
@property(nonatomic, assign) NSRect textScrollbarRect;
@property(nonatomic, assign) uint32_t index;
@property(nonatomic, strong) CJGuiInternalComposableEffectTarget *effectTarget;
@property(nonatomic, strong) CJGuiInternalComposableEffectTarget *backdropTarget;
// Parsed once from the existing copied `value` string. The retained struct is
// pure scalar geometry, not a Cangjie pointer, Metal buffer or AppKit object.
@property(nonatomic, assign) BOOL hasVectorGeometry;
@property(nonatomic, assign) CjguiInternalComposableVectorGeometry vectorGeometry;
// Accepted-node cache: local fill/stroke triangles only. It intentionally
// excludes paint, layout, clip and backing scale so a color/local projection
// update can reuse preparation while the normal encoder reapplies its current
// transform and clip chain.
@property(nonatomic, copy) NSData *vectorPreparedTriangles;
@property(nonatomic, assign) BOOL hasVectorPreparedGeometry;
@property(nonatomic, assign) CjguiInternalComposableVectorGeometry vectorPreparedGeometry;

// 2026-09-26(B2):把**候选准备期的排版产物**持留在节点上,使其在 accept 后仍可被**只读查询**
// (契约 implementation order 1–2:随 accept 发布不可变几何索引;查询不得新建临时布局)。
// 与既有 vectorPreparedTriangles(:1427)同法,纯附加、不改既有函数体。
@property(nonatomic, strong) CjguiPreparedTextNodeLayout *preparedTextLayout;
// The buffer is native-only and COW-shared with an unchanged accepted node.
// `present_clear` retains its submitted node array through command-buffer
// completion, so a later geometry replacement cannot release an in-flight
// buffer generation.
@property(nonatomic, strong) id<MTLBuffer> vectorPreparedVertexBuffer;
@property(nonatomic, assign) NSUInteger vectorPreparedVertexCount;
@property(nonatomic, assign) NSUInteger vectorPreparedVertexBytes;
@end

@implementation CJGuiInternalComposableSceneNode
@end

static void CjguiTraceSelectionTransferScalar(CJGuiInternalSession *ctx,
    uint64_t transferId, uint64_t ownerTurn, uint64_t sceneVersion,
    uint32_t phase, uint64_t value) {
    if (!ctx || !CjguiOwnerPhaseTraceEnabled()) return;
    (void)CjguiOwnerTraceAppend(CJGUI_OWNER_TRACE_OBSERVATION_SCALAR,
        ctx.rendererSessionToken, ownerTurn, transferId, value,
        ctx.sessionGeneration, phase, sceneVersion);
}

static void CjguiTraceSelectionTransferInstalled(CJGuiInternalSession *ctx,
    CjguiSelectionTransferCapsule *capsule, CjguiInstalledRangeState *basis,
    uint64_t proxyGeneration, uint64_t selectionRevision) {
    if (!ctx || !capsule || !basis || !CjguiOwnerPhaseTraceEnabled()) return;
    uint64_t ownerTurn = atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn, memory_order_acquire);
    uint64_t transferId = capsule.transferId;
    uint64_t sceneVersion = capsule.bSceneVersion;
    ctx.selectionTraceTransferId = transferId;
    ctx.selectionTraceSessionGeneration = ctx.sessionGeneration;
    ctx.selectionTraceOwnerTurn = ownerTurn;
    ctx.selectionTraceSceneVersion = sceneVersion;
    ctx.selectionTraceBindingEpoch = capsule.bBindingEpoch;
    ctx.selectionTraceNodeId = capsule.bNodeId;
    ctx.selectionTraceResourceId = capsule.bResourceId;
    ctx.selectionTraceProjectionVersion = capsule.bProjectionVersion;
    ctx.selectionTraceProxyGeneration = proxyGeneration;
    ctx.selectionTraceSelectionRevision = selectionRevision;
    ctx.selectionTraceStart16 = basis.actualSelectionStart16;
    ctx.selectionTraceEnd16 = basis.actualSelectionEnd16;
    ctx.selectionTraceDrawEncoded = NO;

    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_INSTALLED, 1);
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_BINDING_EPOCH, capsule.bBindingEpoch);
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_NODE_ID, capsule.bNodeId);
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_RESOURCE_ID, (uint64_t)capsule.bResourceId);
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_PROJECTION_VERSION, capsule.bProjectionVersion);
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_PROXY_GENERATION, proxyGeneration);
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_REVISION, selectionRevision);
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_START16, basis.actualSelectionStart16);
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_END16, basis.actualSelectionEnd16);
}

static uint64_t CjguiSelectionTraceMilliPoints(CGFloat value) {
    if (!isfinite(value) || value > (CGFloat)LLONG_MAX / 1000.0 ||
        value < (CGFloat)LLONG_MIN / 1000.0) return UINT64_MAX;
    return (uint64_t)(int64_t)llround(value * 1000.0);
}


static void CjguiCapturePrecisePointer(CJGuiInternalQueuedInteraction *interaction,
                                       CJGuiInternalComposableSceneNode *node, NSPoint point) {
    if (!interaction || !node || !isfinite(point.x) || !isfinite(point.y)) return;
    interaction.pointerX = (int64_t)llround(point.x);
    interaction.pointerY = (int64_t)llround(point.y);
    interaction.precisePointerX = (double)point.x;
    interaction.precisePointerY = (double)point.y;
    interaction.pointerTranslateX = node.geometry.translateX;
    interaction.pointerTranslateY = node.geometry.translateY;
    interaction.hasPrecisePointer = YES;
}

static NSRect CjguiComposableVisualNodeRect(CJGuiInternalComposableSceneNode *node) {
    CjguiInternalRendererComposableNode value = node.node;
    CjguiInternalRendererComposableGeometry geometry = node.geometry;
    return NSMakeRect((CGFloat)value.x + (CGFloat)geometry.translateX,
                      (CGFloat)value.y + (CGFloat)geometry.translateY,
                      MAX(0.0, (CGFloat)value.width), MAX(0.0, (CGFloat)value.height));
}

static void CjguiComposableVisualClipConstraintAt(CJGuiInternalComposableSceneNode *node,
    uint32_t index, CGFloat *x, CGFloat *y, CGFloat *width, CGFloat *height, CGFloat *radius) {
    CjguiComposableClipConstraintAt(node.node, index, x, y, width, height, radius);
    CjguiInternalRendererComposableGeometry g = node.geometry;
    if (index >= g.clipCount) return;
    switch (index) {
        case 0: *x += (CGFloat)g.clip0X; *y += (CGFloat)g.clip0Y; break;
        case 1: *x += (CGFloat)g.clip1X; *y += (CGFloat)g.clip1Y; break;
        case 2: *x += (CGFloat)g.clip2X; *y += (CGFloat)g.clip2Y; break;
        default: *x += (CGFloat)g.clip3X; *y += (CGFloat)g.clip3Y; break;
    }
}

static NSRect CjguiComposableVisualClipBounds(CJGuiInternalComposableSceneNode *node) {
    if (!node) return NSZeroRect;
    uint32_t count = CjguiComposableClipConstraintCount(node.node);
    NSRect result = NSZeroRect;
    for (uint32_t index = 0; index < count; index++) {
        CGFloat x = 0, y = 0, width = 0, height = 0, radius = 0;
        CjguiComposableVisualClipConstraintAt(node, index, &x, &y, &width, &height, &radius);
        NSRect clip = NSMakeRect(x, y, MAX(0.0, width), MAX(0.0, height));
        result = index == 0 ? clip : NSIntersectionRect(result, clip);
        if (NSIsEmptyRect(result)) break;
    }
    return result;
}

static const double CjguiComposableVectorEpsilon = 1.0e-9;
static const double CjguiComposableVectorMiterLimit = 4.0;

static BOOL CjguiComposableVectorFiniteUnit(double value) {
    return isfinite(value) && value >= 0.0 && value <= 1.0;
}

static BOOL CjguiComposableVectorParseDouble(NSString *token, double *outValue) {
    if (!token || !outValue) return NO;
    const char *bytes = token.UTF8String;
    if (!bytes || bytes[0] == '\0') return NO;
    char *end = NULL;
    double value = strtod(bytes, &end);
    if (!end || end == bytes || *end != '\0' || !isfinite(value)) return NO;
    *outValue = value;
    return YES;
}

static BOOL CjguiComposableVectorParseUInt(NSString *token, uint32_t *outValue) {
    double value = 0.0;
    if (!outValue || !CjguiComposableVectorParseDouble(token, &value) || value < 0.0 ||
        value > (double)UINT32_MAX || floor(value) != value) return NO;
    *outValue = (uint32_t)value;
    return YES;
}

static double CjguiComposableVectorCross(CjguiInternalComposableVectorPoint a,
                                         CjguiInternalComposableVectorPoint b,
                                         CjguiInternalComposableVectorPoint c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

static BOOL CjguiComposableVectorSamePoint(CjguiInternalComposableVectorPoint a,
                                           CjguiInternalComposableVectorPoint b) {
    return a.x == b.x && a.y == b.y;
}

static BOOL CjguiComposableVectorPointInViewBox(CjguiInternalComposableVectorPoint point,
                                                CjguiInternalComposableVectorGeometry geometry) {
    return isfinite(point.x) && isfinite(point.y) && point.x >= 0.0 && point.y >= 0.0 &&
        point.x <= geometry.viewBoxWidth && point.y <= geometry.viewBoxHeight;
}

static BOOL CjguiComposableVectorBetween(double value, double first, double second) {
    return value >= MIN(first, second) && value <= MAX(first, second);
}

static BOOL CjguiComposableVectorSegmentsIntersect(CjguiInternalComposableVectorPoint a,
                                                   CjguiInternalComposableVectorPoint b,
                                                   CjguiInternalComposableVectorPoint c,
                                                   CjguiInternalComposableVectorPoint d) {
    double abC = CjguiComposableVectorCross(a, b, c);
    double abD = CjguiComposableVectorCross(a, b, d);
    double cdA = CjguiComposableVectorCross(c, d, a);
    double cdB = CjguiComposableVectorCross(c, d, b);
    if (fabs(abC) <= CjguiComposableVectorEpsilon && CjguiComposableVectorBetween(c.x, a.x, b.x) &&
        CjguiComposableVectorBetween(c.y, a.y, b.y)) return YES;
    if (fabs(abD) <= CjguiComposableVectorEpsilon && CjguiComposableVectorBetween(d.x, a.x, b.x) &&
        CjguiComposableVectorBetween(d.y, a.y, b.y)) return YES;
    if (fabs(cdA) <= CjguiComposableVectorEpsilon && CjguiComposableVectorBetween(a.x, c.x, d.x) &&
        CjguiComposableVectorBetween(a.y, c.y, d.y)) return YES;
    if (fabs(cdB) <= CjguiComposableVectorEpsilon && CjguiComposableVectorBetween(b.x, c.x, d.x) &&
        CjguiComposableVectorBetween(b.y, c.y, d.y)) return YES;
    return ((abC > 0.0 && abD < 0.0) || (abC < 0.0 && abD > 0.0)) &&
        ((cdA > 0.0 && cdB < 0.0) || (cdA < 0.0 && cdB > 0.0));
}

static BOOL CjguiComposableVectorPointInTriangle(CjguiInternalComposableVectorPoint point,
                                                 CjguiInternalComposableVectorPoint a,
                                                 CjguiInternalComposableVectorPoint b,
                                                 CjguiInternalComposableVectorPoint c,
                                                 double winding) {
    double first = CjguiComposableVectorCross(a, b, point) * winding;
    double second = CjguiComposableVectorCross(b, c, point) * winding;
    double third = CjguiComposableVectorCross(c, a, point) * winding;
    return first >= -CjguiComposableVectorEpsilon && second >= -CjguiComposableVectorEpsilon &&
        third >= -CjguiComposableVectorEpsilon;
}

static BOOL CjguiComposableVectorTriangulate(CjguiInternalComposableVectorGeometry *geometry) {
    if (!geometry || geometry->kind != CJGUI_INTERNAL_VECTOR_SIMPLE_POLYGON ||
        geometry->pointCount < 3 || geometry->pointCount > CJGUI_INTERNAL_COMPOSABLE_VECTOR_MAX_POINTS) return NO;
    double signedArea = 0.0;
    for (uint32_t index = 0; index < geometry->pointCount; index++) {
        uint32_t next = index + 1 == geometry->pointCount ? 0 : index + 1;
        signedArea += geometry->points[index].x * geometry->points[next].y -
            geometry->points[next].x * geometry->points[index].y;
    }
    if (fabs(signedArea) <= CjguiComposableVectorEpsilon) return NO;
    double winding = signedArea > 0.0 ? 1.0 : -1.0;
    uint8_t remaining[CJGUI_INTERNAL_COMPOSABLE_VECTOR_MAX_POINTS] = {0};
    uint32_t remainingCount = geometry->pointCount;
    for (uint32_t index = 0; index < remainingCount; index++) remaining[index] = (uint8_t)index;
    geometry->triangleIndexCount = 0;
    while (remainingCount > 3) {
        BOOL foundEar = NO;
        for (uint32_t position = 0; position < remainingCount; position++) {
            uint32_t before = position == 0 ? remainingCount - 1 : position - 1;
            uint32_t after = position + 1 == remainingCount ? 0 : position + 1;
            uint8_t first = remaining[before];
            uint8_t middle = remaining[position];
            uint8_t last = remaining[after];
            CjguiInternalComposableVectorPoint a = geometry->points[first];
            CjguiInternalComposableVectorPoint b = geometry->points[middle];
            CjguiInternalComposableVectorPoint c = geometry->points[last];
            if (CjguiComposableVectorCross(a, b, c) * winding <= CjguiComposableVectorEpsilon) continue;
            BOOL containsOther = NO;
            for (uint32_t candidate = 0; candidate < remainingCount; candidate++) {
                uint8_t candidateIndex = remaining[candidate];
                if (candidateIndex == first || candidateIndex == middle || candidateIndex == last) continue;
                if (CjguiComposableVectorPointInTriangle(geometry->points[candidateIndex], a, b, c, winding)) {
                    containsOther = YES;
                    break;
                }
            }
            if (containsOther) continue;
            if (geometry->triangleIndexCount + 3 > sizeof(geometry->triangleIndices)) return NO;
            geometry->triangleIndices[geometry->triangleIndexCount++] = first;
            geometry->triangleIndices[geometry->triangleIndexCount++] = middle;
            geometry->triangleIndices[geometry->triangleIndexCount++] = last;
            for (uint32_t shift = position; shift + 1 < remainingCount; shift++) remaining[shift] = remaining[shift + 1];
            remainingCount -= 1;
            foundEar = YES;
            break;
        }
        if (!foundEar) return NO;
    }
    if (geometry->triangleIndexCount + 3 > sizeof(geometry->triangleIndices)) return NO;
    geometry->triangleIndices[geometry->triangleIndexCount++] = remaining[0];
    geometry->triangleIndices[geometry->triangleIndexCount++] = remaining[1];
    geometry->triangleIndices[geometry->triangleIndexCount++] = remaining[2];
    return YES;
}

static BOOL CjguiParseComposableVectorGeometry(NSString *payload,
                                               CjguiInternalComposableVectorGeometry *outGeometry) {
    if (!payload || !outGeometry) return NO;
    NSArray<NSString *> *parts = [payload componentsSeparatedByString:@";"];
    if (parts.count < 20 || ![parts[0] isEqualToString:@"cg1"]) return NO;
    CjguiInternalComposableVectorGeometry geometry = {0};
    if (!CjguiComposableVectorParseUInt(parts[1], &geometry.kind) ||
        !CjguiComposableVectorParseDouble(parts[2], &geometry.viewBoxWidth) ||
        !CjguiComposableVectorParseDouble(parts[3], &geometry.viewBoxHeight) ||
        !CjguiComposableVectorParseDouble(parts[4], &geometry.strokeWidth) ||
        !CjguiComposableVectorParseUInt(parts[5], &geometry.cap) ||
        !CjguiComposableVectorParseUInt(parts[6], &geometry.join) ||
        !CjguiComposableVectorParseDouble(parts[7], &geometry.fillRed) ||
        !CjguiComposableVectorParseDouble(parts[8], &geometry.fillGreen) ||
        !CjguiComposableVectorParseDouble(parts[9], &geometry.fillBlue) ||
        !CjguiComposableVectorParseDouble(parts[10], &geometry.fillAlpha) ||
        !CjguiComposableVectorParseDouble(parts[11], &geometry.strokeRed) ||
        !CjguiComposableVectorParseDouble(parts[12], &geometry.strokeGreen) ||
        !CjguiComposableVectorParseDouble(parts[13], &geometry.strokeBlue) ||
        !CjguiComposableVectorParseDouble(parts[14], &geometry.strokeAlpha) ||
        !CjguiComposableVectorParseDouble(parts[15], &geometry.center.x) ||
        !CjguiComposableVectorParseDouble(parts[16], &geometry.center.y) ||
        !CjguiComposableVectorParseDouble(parts[17], &geometry.radiusX) ||
        !CjguiComposableVectorParseDouble(parts[18], &geometry.radiusY) ||
        !CjguiComposableVectorParseUInt(parts[19], &geometry.pointCount)) return NO;
    if (geometry.kind < CJGUI_INTERNAL_VECTOR_LINE || geometry.kind > CJGUI_INTERNAL_VECTOR_SIMPLE_POLYGON ||
        geometry.viewBoxWidth <= 0.0 || geometry.viewBoxHeight <= 0.0 || geometry.strokeWidth < 0.0 ||
        geometry.cap < CJGUI_INTERNAL_VECTOR_CAP_BUTT || geometry.cap > CJGUI_INTERNAL_VECTOR_CAP_SQUARE ||
        geometry.join < CJGUI_INTERNAL_VECTOR_JOIN_MITER || geometry.join > CJGUI_INTERNAL_VECTOR_JOIN_ROUND ||
        !CjguiComposableVectorFiniteUnit(geometry.fillRed) || !CjguiComposableVectorFiniteUnit(geometry.fillGreen) ||
        !CjguiComposableVectorFiniteUnit(geometry.fillBlue) || !CjguiComposableVectorFiniteUnit(geometry.fillAlpha) ||
        !CjguiComposableVectorFiniteUnit(geometry.strokeRed) || !CjguiComposableVectorFiniteUnit(geometry.strokeGreen) ||
        !CjguiComposableVectorFiniteUnit(geometry.strokeBlue) || !CjguiComposableVectorFiniteUnit(geometry.strokeAlpha)) return NO;
    if (geometry.pointCount > CJGUI_INTERNAL_COMPOSABLE_VECTOR_MAX_POINTS ||
        parts.count != 20 + geometry.pointCount * 2) return NO;
    for (uint32_t index = 0; index < geometry.pointCount; index++) {
        if (!CjguiComposableVectorParseDouble(parts[20 + index * 2], &geometry.points[index].x) ||
            !CjguiComposableVectorParseDouble(parts[21 + index * 2], &geometry.points[index].y) ||
            !CjguiComposableVectorPointInViewBox(geometry.points[index], geometry)) return NO;
        if (index > 0 && CjguiComposableVectorSamePoint(geometry.points[index - 1], geometry.points[index])) return NO;
    }
    BOOL fillVisible = geometry.fillAlpha > 0.0;
    BOOL strokeVisible = geometry.strokeAlpha > 0.0;
    if ((strokeVisible && geometry.strokeWidth <= 0.0) || (!fillVisible && !strokeVisible)) return NO;
    if (geometry.kind == CJGUI_INTERNAL_VECTOR_ELLIPSE) {
        if (geometry.pointCount != 1 || !CjguiComposableVectorPointInViewBox(geometry.center, geometry) ||
            geometry.radiusX <= 0.0 || geometry.radiusY <= 0.0 || geometry.center.x - geometry.radiusX < 0.0 ||
            geometry.center.y - geometry.radiusY < 0.0 || geometry.center.x + geometry.radiusX > geometry.viewBoxWidth ||
            geometry.center.y + geometry.radiusY > geometry.viewBoxHeight) return NO;
    } else {
        uint32_t minimum = geometry.kind == CJGUI_INTERNAL_VECTOR_SIMPLE_POLYGON ? 3u : 2u;
        if (geometry.pointCount < minimum || (geometry.kind == CJGUI_INTERNAL_VECTOR_LINE && geometry.pointCount != 2)) return NO;
        if ((geometry.kind == CJGUI_INTERNAL_VECTOR_LINE || geometry.kind == CJGUI_INTERNAL_VECTOR_POLYLINE) &&
            !strokeVisible) return NO;
        if (geometry.kind == CJGUI_INTERNAL_VECTOR_SIMPLE_POLYGON) {
            if (CjguiComposableVectorSamePoint(geometry.points[0], geometry.points[geometry.pointCount - 1])) return NO;
            for (uint32_t index = 0; index < geometry.pointCount; index++) {
                uint32_t next = index + 1 == geometry.pointCount ? 0 : index + 1;
                for (uint32_t other = index + 1; other < geometry.pointCount; other++) {
                    if (other == index + 1 || (index == 0 && other == geometry.pointCount - 1)) continue;
                    uint32_t nextOther = other + 1 == geometry.pointCount ? 0 : other + 1;
                    if (CjguiComposableVectorSegmentsIntersect(geometry.points[index], geometry.points[next],
                                                               geometry.points[other], geometry.points[nextOther])) return NO;
                }
            }
            if (!CjguiComposableVectorTriangulate(&geometry)) return NO;
        }
    }
    *outGeometry = geometry;
    return YES;
}

// Join the existing admitted FIFO identity to the product's consumed event.
// This diagnostic neither allocates an input identity nor changes admission.
static void CjguiTraceAdmittedPointer(CJGuiInternalSession *session,
                                      CJGuiInternalQueuedInteraction *interaction) {
    if (!session || !interaction || interaction.pointerStreamSessionGeneration == 0) return;
    if (CjguiOwnerPhaseTraceEnabled()) {
        uint64_t turn = atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn, memory_order_acquire);
        CjguiOwnerTraceAppend(CJGUI_OWNER_TRACE_OBSERVATION_SCALAR, session.rendererSessionToken, turn,
            interaction.pointerStreamFirstSequence, interaction.pointerStreamLastSequence,
            interaction.pointerStreamSessionGeneration, 327, interaction.pointerStreamBindingEpoch);
        CjguiOwnerTraceAppend(CJGUI_OWNER_TRACE_OBSERVATION_SCALAR, session.rendererSessionToken, turn,
            interaction.pointerStreamFirstSequence, interaction.pointerStreamPreviousSequence,
            interaction.pointerStreamSessionGeneration, 328, interaction.pointerStreamPhase);
        CjguiOwnerTraceAppend(CJGUI_OWNER_TRACE_OBSERVATION_SCALAR, session.rendererSessionToken, turn,
            interaction.pointerStreamFirstSequence, interaction.nodeId,
            interaction.pointerStreamSessionGeneration, 329, interaction.projectionVersion);
        CjguiOwnerTraceAppend(CJGUI_OWNER_TRACE_OBSERVATION_SCALAR, session.rendererSessionToken, turn,
            interaction.pointerStreamFirstSequence, interaction.kind,
            interaction.pointerStreamSessionGeneration, 330, interaction.pointerStreamLastSequence);
    }
    if (getenv("CJGUI_TRACE_POINTER_GEOMETRY") == NULL) return;
    static uint32_t count = 0;
    if (count >= 1024) return;
    count += 1;
    fprintf(stderr, "CJGUI_POINTER_ADMITTED mono_ns=%llu input_key=%llu:%llu:%llu:%llu:%llu "
        "phase=%u node=%llu scene=%llu previous=%llu sample=%u\n",
        (unsigned long long)CjguiOwnerTraceNanoseconds(),
        (unsigned long long)session.rendererSessionToken,
        (unsigned long long)interaction.pointerStreamSessionGeneration,
        (unsigned long long)interaction.pointerStreamBindingEpoch,
        (unsigned long long)interaction.pointerStreamFirstSequence,
        (unsigned long long)interaction.pointerStreamLastSequence,
        interaction.pointerStreamPhase, (unsigned long long)interaction.nodeId,
        (unsigned long long)interaction.projectionVersion,
        (unsigned long long)interaction.pointerStreamPreviousSequence, count);
}

static BOOL CjguiEnqueueComposableCapturedPointerInteraction(CJGuiInternalSession *session,
                                                             uint32_t kind,
                                                             CJGuiInternalComposableSceneNode *node,
                                                             NSPoint point,
                                                             uint64_t gestureEpoch) {
    if (!session || session.destroyed || !node || !isfinite(point.x) || !isfinite(point.y)) return NO;
    BOOL pointerStreamKind = kind >= CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_BEGIN &&
        kind <= CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_CANCEL;
    BOOL pointerStreamKnown = pointerStreamKind && gestureEpoch != 0;
    uint64_t streamSequence = 0;
    uint64_t streamPreviousSequence = 0;
    if (pointerStreamKind && !pointerStreamKnown) {
        // An unidentifiable legacy pointer event breaks any active coverage
        // claim. Keep delivering the event through the established FIFO, but
        // require a fresh BEGIN before sequence metadata can become known.
        session.activePointerStreamBindingEpoch = 0;
        session.nextPointerStreamSequence = 0;
    }
    if (pointerStreamKnown) {
        if (kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_BEGIN) {
            // The overlay supplies its existing, monotonically allocated
            // gesture binding epoch. Never create a second identity here.
            if (gestureEpoch <= session.lastPointerStreamBindingEpoch) return NO;
            streamSequence = 1;
        } else {
            // An update/terminal can only advance the stream opened by the
            // exact BEGIN epoch. Late callbacks from a prior capture are not
            // admitted into a later stream's sequence.
            if (session.activePointerStreamBindingEpoch != gestureEpoch ||
                session.nextPointerStreamSequence == 0 ||
                session.nextPointerStreamSequence == UINT64_MAX) return NO;
            streamSequence = session.nextPointerStreamSequence;
            streamPreviousSequence = streamSequence - 1;
        }
    }
    uint64_t coordinateSessionGeneration=0;
    uint64_t coordinateEpoch=cjgui_internal_renderer_coordinate_lifetime(
        session.rendererSessionToken,&coordinateSessionGeneration);
    if(!coordinateEpoch) coordinateSessionGeneration=0;
    uint32_t nodeIndex = node.index;
    uint64_t nodeId = node.node.nodeId;
    int64_t resourceId = node.node.resourceId;
    uint32_t nodeKind = node.node.nodeKind;
    // Sparse COW nodes retain the projection version of their first accepted
    // payload. The input FIFO belongs to the currently committed scene,
    // including when it reuses that payload; never stamp the stale node POD.
    uint64_t acceptedVersion = session.composableSceneVersion;
    // A cancelled press names its retained original node even after removal.
    // It terminates routing only and cannot authorize a replacement target.
    BOOL retainedPressTerminal = gestureEpoch != 0 &&
        (kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_PRESS_CANCEL ||
         kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_PRESS_END);
    if (nodeId == 0 || (!retainedPressTerminal && nodeIndex >= session.composableNodes.count)) return NO;
    CJGuiInternalQueuedInteraction *last = session.pendingInteractions.lastObject;
    // Only adjacent updates for exactly one captured identity can merge. A
    // terminal end/cancel is deliberately never coalesced behind a move.
    if (kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_UPDATE && last &&
        pointerStreamKnown &&
        last.kind == kind && last.nodeId == nodeId && last.resourceId == resourceId &&
        last.nodeKind == nodeKind && last.projectionVersion == acceptedVersion &&
        last.bindingEpoch == gestureEpoch &&
        last.pointerStreamSessionGeneration == session.sessionGeneration &&
        last.pointerStreamBindingEpoch == gestureEpoch &&
        last.pointerStreamPhase == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_UPDATE &&
        last.coordinateSessionGeneration == coordinateSessionGeneration &&
        last.coordinateEpoch == coordinateEpoch) {
        CjguiCapturePrecisePointer(last, node, point);
        last.modifierFlags = session.pointerModifierFlags;
        last.pointerStreamLastSequence = streamSequence;
        session.nextPointerStreamSequence = streamSequence + 1;
        CjguiTraceAdmittedPointer(session, last);
        CjguiOwnerPumpTicketNoteWork(session);
        return YES;
    }
    if (CjguiPendingInteractionOccupancy(session) >= kCjguiPendingInteractionCapacity) {
        session.pendingInputQueueFullNotice = YES;
        CjguiOwnerPumpTicketNoteWork(session);
        if (pointerStreamKnown &&
            (kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_END ||
             kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_CANCEL)) {
            session.activePointerStreamBindingEpoch = 0;
            session.nextPointerStreamSequence = 0;
        }
        return NO;
    }
    CJGuiInternalQueuedInteraction *interaction =
        [[CJGuiInternalQueuedInteraction alloc] initWithKind:kind recordIndex:nodeIndex
                                               selectionStart:0 selectionEnd:0 formText:@""
                                               nodeId:nodeId projectionVersion:acceptedVersion
                                                   resourceId:resourceId nodeKind:nodeKind];
    if (!interaction) {
        session.pendingInputQueueFullNotice = YES;
        CjguiOwnerPumpTicketNoteWork(session);
        if (pointerStreamKnown &&
            (kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_END ||
             kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_CANCEL)) {
            session.activePointerStreamBindingEpoch = 0;
            session.nextPointerStreamSequence = 0;
        }
        return NO;
    }
    CjguiCapturePrecisePointer(interaction, node, point);
    interaction.modifierFlags = session.pointerModifierFlags;
    interaction.bindingEpoch = gestureEpoch;
    interaction.coordinateSessionGeneration=coordinateSessionGeneration;
    interaction.coordinateEpoch=coordinateEpoch;
    if (pointerStreamKnown) {
        interaction.pointerStreamSessionGeneration = session.sessionGeneration;
        interaction.pointerStreamBindingEpoch = gestureEpoch;
        interaction.pointerStreamFirstSequence = streamSequence;
        interaction.pointerStreamLastSequence = streamSequence;
        interaction.pointerStreamPreviousSequence = streamPreviousSequence;
        interaction.pointerStreamPhase = kind;
    }
    if (pointerStreamKnown && kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_BEGIN) {
        CjguiInternalRendererPointerBeginOrigin origin = {
            .sessionGeneration = session.sessionGeneration,
            .coordinateEpoch = coordinateEpoch, .gestureEpoch = gestureEpoch,
            .sceneVersion = acceptedVersion, .nodeId = nodeId, .resourceId = resourceId,
            .nodeKind = nodeKind, .acceptedBindingEpoch = node.node.acceptedBindingEpoch,
        };
        if (!CjguiRetainPointerBeginOrigin(session.rendererSessionToken, origin)) return NO;
    }
    interaction.physicalProducerNonce=session.physicalProducerDepth ? session.physicalProducerNonce : 0;
    [session.pendingInteractions addObject:interaction];
    CjguiOwnerPumpTicketNoteWork(session);
    CjguiTraceAdmittedPointer(session, interaction);
    if (pointerStreamKnown) {
        if (kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_BEGIN) {
            session.lastPointerStreamBindingEpoch = gestureEpoch;
            session.activePointerStreamBindingEpoch = gestureEpoch;
            session.nextPointerStreamSequence = 2;
        } else if (kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_END ||
                   kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_CANCEL) {
            session.activePointerStreamBindingEpoch = 0;
            session.nextPointerStreamSequence = 0;
        } else {
            session.nextPointerStreamSequence = streamSequence + 1;
        }
    }
#ifdef CJGUI_INTERNAL_TESTING
    session.testComposableLastEnqueuedKind = kind;
    session.testComposableLastEnqueuedNodeId = nodeId;
    session.testComposableLastEnqueuedProjectionVersion = acceptedVersion;
    session.testComposableMaxPendingInteractionCount = (uint32_t)MIN(
        UINT32_MAX, MAX((NSUInteger)session.testComposableMaxPendingInteractionCount, session.pendingInteractions.count));
#endif
    return YES;
}

static BOOL CjguiEnqueueComposablePointerInteraction(CJGuiInternalSession *session,
                                                     uint32_t kind,
                                                     CJGuiInternalComposableSceneNode *node,
                                                     NSPoint point) {
    return CjguiEnqueueComposableCapturedPointerInteraction(session, kind, node, point, 0);
}

static void CjguiClearComposableTextDecorations(CJGuiInternalComposableSceneNode *node) {
    if (!node) return;
    node.textSelectionRects = @[];
    node.textSelectionTransferId = 0;
    node.textDeclaredSelectionDecorations = @[];
    node.textMarkedRects = @[];
    node.textCaretRect = NSZeroRect;
    node.textCaretIsDeclared = NO;
    node.textScrollbarRect = NSZeroRect;
}

@interface CJGuiInternalComposableImageResource : NSObject
@property(nonatomic, copy) NSString *cacheKey;
@property(nonatomic, copy) NSString *resolvedPath;
@property(nonatomic, copy) NSData *encodedData;
@property(nonatomic, assign) NSUInteger transferPreparationCount;
@property(nonatomic, strong) NSMutableArray *transferHolds;
@property(nonatomic, assign) uint32_t state;
@property(nonatomic, assign) uint64_t lastAccess;
@property(nonatomic, strong) id<MTLTexture> texture;
// Every subscriber is only a slot token plus that session's non-reusable
// generation.  The application domain never retains an NSWindow/session, so
// a closed window cannot be revived by a late loader callback.
@property(nonatomic, strong) NSMutableArray *subscribers;
// Explicit preparation may start real work before a candidate scene is
// accepted. Requesters are therefore distinct from committed subscribers:
// they may lead a bounded load, but never receive a completion invalidation.
@property(nonatomic, strong) NSMutableArray *requesters;
@property(nonatomic, assign) uint64_t loadGeneration;
@property(nonatomic, assign) uint64_t loadSessionToken;
@property(nonatomic, assign) uint64_t loadSessionGeneration;
// Aggregate accounting for the exact per-session holds below. Kept as scalar
// diagnostics for the bounded native resource probe.
@property(nonatomic, assign) uint32_t candidateLeaseCount;
#ifdef CJGUI_INTERNAL_TESTING
@property(nonatomic, assign) uint64_t launchMicros;
#endif
@end

@implementation CJGuiInternalComposableImageResource
- (instancetype)init {
    self = [super init];
    if (!self) return nil;
    self.subscribers = [NSMutableArray array];
    self.requesters = [NSMutableArray array];
    self.transferHolds = [NSMutableArray array];
    return self;
}
@end

@interface CJGuiInternalComposableImageTransferHold : NSObject
@property(nonatomic, assign) uint64_t sessionToken;
@property(nonatomic, assign) uint64_t sessionGeneration;
@property(nonatomic, assign) NSUInteger preparationCount;
@property(nonatomic, assign) BOOL candidateLease;
@property(nonatomic, assign) uint64_t candidateVersion;
@end

@implementation CJGuiInternalComposableImageTransferHold
@end

@interface CJGuiInternalComposableImageSubscription : NSObject
@property(nonatomic, assign) uint64_t sessionToken;
@property(nonatomic, assign) uint64_t sessionGeneration;
// A direct public prepare request is independent of a staged scene candidate.
// It is retained across a later scene commit and released with its session.
@property(nonatomic, assign) BOOL explicitPreload;
@end

@implementation CJGuiInternalComposableImageSubscription
@end

// This is deliberately a finite native application resource domain, not a
// process-wide cache keyed by application data. Domains are associated with
// NSApplication and partitioned by the exact MTLDevice. At most the existing
// fixed session capacity can be live, while per-domain cache/record/queue
// limits remain the established 8 / 32MiB / 4 / 16 / 64 limits.
@interface CJGuiInternalComposableImageResourceDomain : NSObject
@property(nonatomic, strong) id<MTLDevice> device;
@property(nonatomic, strong) NSMutableDictionary<NSString *, id<MTLTexture>> *textureCache;
// Allocation ledger, deliberately weak: cache, scene and GPU submissions are
// the strong owners. Repeated references to one texture cost one allocation.
@property(nonatomic, strong) NSHashTable<id<MTLTexture>> *textureLedger;
@property(nonatomic, strong) NSMutableDictionary<NSString *, CJGuiInternalComposableImageResource *> *resources;
@property(nonatomic, strong) NSMutableDictionary<NSString *, MTKTextureLoader *> *loaders;
@property(nonatomic, strong) NSMutableArray<NSString *> *pendingKeys;
@property(nonatomic, assign) uint64_t accessClock;
@property(nonatomic, assign) NSUInteger sessionCount;
@property(nonatomic, assign) BOOL destroyed;
// Domain-wide decode starts (sync transfer admission + async loader launch).
// Read by the bounded workload diagnostic; it counts real decodes, never
// cache hits, reuse or a scene refresh that reuses an existing texture.
@property(nonatomic, assign) uint64_t imageDecodeStartCount;
#ifdef CJGUI_INTERNAL_TESTING
@property(nonatomic, assign) uint64_t testPathResolveMicros;
@property(nonatomic, assign) uint64_t testCacheHitCount;
@property(nonatomic, assign) uint64_t testActualLoadCount;
@property(nonatomic, assign) uint64_t testActualDecodeCount;
@property(nonatomic, assign) uint64_t testAsyncTotalMicros;
@property(nonatomic, assign) uint32_t testPeakInFlight;
@property(nonatomic, assign) uint32_t testPeakPending;
#endif
- (instancetype)initWithDevice:(id<MTLDevice>)device;
@end

@implementation CJGuiInternalComposableImageResourceDomain
- (instancetype)initWithDevice:(id<MTLDevice>)device {
    self = [super init];
    if (!self || !device) return nil;
    self.device = device;
    self.textureCache = [NSMutableDictionary dictionary];
    self.textureLedger = [NSHashTable hashTableWithOptions:
        NSHashTableWeakMemory | NSHashTableObjectPointerPersonality];
    self.resources = [NSMutableDictionary dictionary];
    self.loaders = [NSMutableDictionary dictionary];
    self.pendingKeys = [NSMutableArray array];
    return self;
}
@end

static NSString *CjguiComposableImageResolvedPath(NSString *resourcePath) {
    if (resourcePath.length == 0) return nil;
    if ([resourcePath hasPrefix:@"cjgui-transfer:"]) return resourcePath;
    NSString *resolved = resourcePath;
    if (![resolved isAbsolutePath]) {
        NSString *fromWorkingDirectory = [NSFileManager.defaultManager.currentDirectoryPath stringByAppendingPathComponent:resolved];
        if ([NSFileManager.defaultManager fileExistsAtPath:fromWorkingDirectory]) {
            resolved = fromWorkingDirectory;
        } else if (NSBundle.mainBundle.resourcePath.length > 0) {
            resolved = [NSBundle.mainBundle.resourcePath stringByAppendingPathComponent:resolved];
        } else {
            resolved = fromWorkingDirectory;
        }
    }
    return resolved.stringByStandardizingPath;
}

static NSString *CjguiComposableImageCacheKey(NSString *resourcePath, NSString *resourceId,
                                              uint64_t resourceVersion, NSString **outResolved) {
    if (outResolved) *outResolved = nil;
    NSString *resolved = CjguiComposableImageResolvedPath(resourcePath);
    if (!resolved) return nil;
    NSString *logicalId = resourceId.length > 0 ? resourceId : resolved;
    NSString *cacheKey = [NSString stringWithFormat:@"%@\n%llu\n%@", logicalId, resourceVersion, resolved];
    if (outResolved) *outResolved = resolved;
    return cacheKey;
}

// A committed/staged node owns its texture independently of the reusable
// cache. This is the only internal path that may reuse that strong reference;
// callers still receive only scalar resource states across the ABI.
static id<MTLTexture> CjguiComposableImageBoundTexture(CJGuiInternalSession *session, NSString *cacheKey) {
    if (!session || cacheKey.length == 0) return nil;
    for (CJGuiInternalComposableSceneNode *node in session.stagedComposableNodes) {
        if ([node.imageTextureContentKey isEqualToString:cacheKey] && node.imageTexture) return node.imageTexture;
    }
    for (CJGuiInternalComposableSceneNode *node in session.composableNodes) {
        if ([node.imageTextureContentKey isEqualToString:cacheKey] && node.imageTexture) return node.imageTexture;
    }
    return nil;
}

// Reusable-cache eviction removes only the cache's own strong reference. A
// texture retained by a committed/staged node is still a safe application
// domain source for another window on the same device; scanning the fixed
// session table avoids turning that eviction into a duplicate decode.
static id<MTLTexture> CjguiComposableImageDomainBoundTexture(
    CJGuiInternalComposableImageResourceDomain *domain, NSString *cacheKey) {
    if (!domain || cacheKey.length == 0) return nil;
    for (NSUInteger index = 0; index < kCjguiSessionCapacity; index++) {
        CJGuiInternalSession *session = gCjguiSessions[index];
        if (!session || session.destroyed || session.composableImageDomain != domain) continue;
        id<MTLTexture> texture = CjguiComposableImageBoundTexture(session, cacheKey);
        if (texture) return texture;
    }
    return nil;
}

static CJGuiInternalComposableImageResourceDomain *CjguiComposableImageDomainForSession(
    CJGuiInternalSession *session) {
    if (!session || session.destroyed) return nil;
    CJGuiInternalComposableImageResourceDomain *domain = session.composableImageDomain;
    if (!domain || domain.destroyed || domain.device != session.device) return nil;
    return domain;
}

static uint64_t CjguiComposableImageNextAccess(CJGuiInternalComposableImageResourceDomain *domain) {
    if (!domain) return 0;
    if (domain.accessClock < UINT64_MAX) domain.accessClock += 1;
    return domain.accessClock;
}

static void CjguiSubscribeComposableImageResource(CJGuiInternalSession *session,
                                                   CJGuiInternalComposableImageResource *resource) {
    if (!session || session.destroyed || !resource || session.rendererSessionToken == 0) return;
    for (CJGuiInternalComposableImageSubscription *subscriber in resource.subscribers) {
        if (subscriber.sessionToken == session.rendererSessionToken &&
            subscriber.sessionGeneration == session.sessionGeneration) return;
    }
    CJGuiInternalComposableImageSubscription *subscriber = [[CJGuiInternalComposableImageSubscription alloc] init];
    subscriber.sessionToken = session.rendererSessionToken;
    subscriber.sessionGeneration = session.sessionGeneration;
    [resource.subscribers addObject:subscriber];
}

static void CjguiRequestComposableImageResource(CJGuiInternalSession *session,
                                                 CJGuiInternalComposableImageResource *resource,
                                                 BOOL explicitPreload) {
    if (!session || session.destroyed || !resource || session.rendererSessionToken == 0) return;
    for (CJGuiInternalComposableImageSubscription *requester in resource.requesters) {
        if (requester.sessionToken == session.rendererSessionToken &&
            requester.sessionGeneration == session.sessionGeneration) {
            // A later scene request must not downgrade an explicit preload.
            requester.explicitPreload = requester.explicitPreload || explicitPreload;
            return;
        }
    }
    CJGuiInternalComposableImageSubscription *requester = [[CJGuiInternalComposableImageSubscription alloc] init];
    requester.sessionToken = session.rendererSessionToken;
    requester.sessionGeneration = session.sessionGeneration;
    requester.explicitPreload = explicitPreload;
    [resource.requesters addObject:requester];
}

static NSUInteger CjguiComposableImageTextureBytes(id<MTLTexture> texture) {
    if (!texture) return 0;
    NSUInteger width = texture.width;
    NSUInteger height = texture.height;
    if (width == 0 || height == 0 || width > NSUIntegerMax / height) return NSUIntegerMax;
    NSUInteger pixels = width * height;
    return pixels > NSUIntegerMax / 4 ? NSUIntegerMax : pixels * 4;
}

static BOOL CjguiComposableImageKeyIsReferenced(CJGuiInternalSession *session, NSString *cacheKey) {
    if (!session || cacheKey.length == 0) return NO;
    for (CJGuiInternalComposableSceneNode *node in session.composableNodes) {
        if ([node.imageTextureCacheKey isEqualToString:cacheKey]) return YES;
    }
    return NO;
}

// Does ANY live session on this domain already hold the decoded texture on a
// committed or staged node? Such a node is its own strong owner, so a
// candidate lease has nothing left to protect.
static CJGuiInternalComposableImageTransferHold *CjguiComposableTransferHold(
    CJGuiInternalComposableImageResource *resource, CJGuiInternalSession *session, BOOL create) {
    if (!resource || !session || session.rendererSessionToken == 0) return nil;
    for (CJGuiInternalComposableImageTransferHold *hold in resource.transferHolds) {
        if (hold.sessionToken == session.rendererSessionToken &&
            hold.sessionGeneration == session.sessionGeneration) return hold;
    }
    if (!create || resource.transferHolds.count >= kCjguiSessionCapacity) return nil;
    CJGuiInternalComposableImageTransferHold *hold = [[CJGuiInternalComposableImageTransferHold alloc] init];
    if (!hold) return nil;
    hold.sessionToken = session.rendererSessionToken;
    hold.sessionGeneration = session.sessionGeneration;
    [resource.transferHolds addObject:hold];
    return hold;
}

static void CjguiUpdateComposableTransferHoldCounts(CJGuiInternalComposableImageResource *resource) {
    if (!resource) return;
    NSUInteger preparations = 0;
    uint32_t leases = 0;
    for (CJGuiInternalComposableImageTransferHold *hold in [resource.transferHolds copy]) {
        if (hold.preparationCount == 0 && !hold.candidateLease) {
            [resource.transferHolds removeObject:hold];
            continue;
        }
        preparations = hold.preparationCount > NSUIntegerMax - preparations
            ? NSUIntegerMax : preparations + hold.preparationCount;
        if (hold.candidateLease && leases < UINT32_MAX) leases += 1;
    }
    resource.transferPreparationCount = preparations;
    resource.candidateLeaseCount = leases;
}

#ifdef CJGUI_INTERNAL_TESTING
// The pressure counterexample must be able to show BOTH branches of the
// handoff in one binary: with the lease suppressed the ninth image is evicted
// and re-decoded; with it the same scene reuses the prepared texture.
static BOOL gCjguiPngCandidateLeaseEnabled = YES;
void cjgui_internal_renderer_test_set_png_candidate_lease_enabled(uint8_t enabled) {
    gCjguiPngCandidateLeaseEnabled = enabled != 0;
}
#endif

// Hand the last preparation reference to a candidate lease. The accepted
// transfer's node does not exist yet, so dropping the reference here would let
// the next prune evict the only decoded copy and turn the scene that follows
// into a second, unadmitted decode.
static void CjguiGrantComposableImageCandidateLease(CJGuiInternalSession *session,
                                                    CJGuiInternalComposableImageResource *resource) {
    CJGuiInternalComposableImageTransferHold *hold = CjguiComposableTransferHold(resource, session, NO);
    if (!hold) return;
    hold.candidateLease = YES;
    hold.candidateVersion = 0; // the next configured candidate owns this offer
    CjguiUpdateComposableTransferHoldCounts(resource);
}

// Only the exact candidate's own staged node may take its lease. A second
// window's node, cancellation or close never settles this session's hold.
static void CjguiTakeComposableImageCandidateLease(
    CJGuiInternalComposableImageResourceDomain *domain, CJGuiInternalSession *session,
    NSString *key, id<MTLTexture> texture) {
    if (!domain || !session || !texture || key.length == 0) return;
    CJGuiInternalComposableImageResource *resource = domain.resources[key];
    CJGuiInternalComposableImageTransferHold *hold = CjguiComposableTransferHold(resource, session, NO);
    if (!hold || !hold.candidateLease || !resource.texture || resource.texture != texture) return;
    if (hold.candidateVersion != 0 && hold.candidateVersion != session.stagedComposableSceneVersion) return;
    hold.candidateLease = NO;
    CjguiUpdateComposableTransferHoldCounts(resource);
}

static void CjguiAdvanceComposableImageCandidateLeases(
    CJGuiInternalComposableImageResourceDomain *domain, CJGuiInternalSession *session,
    uint64_t candidateVersion) {
    if (!domain || !session) return;
    for (CJGuiInternalComposableImageResource *resource in domain.resources.allValues) {
        CJGuiInternalComposableImageTransferHold *hold = CjguiComposableTransferHold(resource, session, NO);
        if (!hold || !hold.candidateLease) continue;
        if (hold.candidateVersion != 0) hold.candidateLease = NO;
        else hold.candidateVersion = candidateVersion;
        CjguiUpdateComposableTransferHoldCounts(resource);
    }
}

static void CjguiSettleComposableImageCandidateLeases(
    CJGuiInternalComposableImageResourceDomain *domain, CJGuiInternalSession *session,
    BOOL closing) {
    if (!domain || !session) return;
    for (CJGuiInternalComposableImageResource *resource in domain.resources.allValues) {
        CJGuiInternalComposableImageTransferHold *hold = CjguiComposableTransferHold(resource, session, NO);
        if (!hold) continue;
        hold.candidateLease = NO;
        if (closing) hold.preparationCount = 0;
        CjguiUpdateComposableTransferHoldCounts(resource);
    }
}

static NSMutableSet<NSString *> *CjguiComposableImageProtectedKeys(
    CJGuiInternalComposableImageResourceDomain *domain, BOOL preserveSceneReferences) {
    NSMutableSet<NSString *> *keys = [NSMutableSet set];
    if (!domain) return keys;
    if (preserveSceneReferences) {
        for (NSUInteger index = 0; index < kCjguiSessionCapacity; index++) {
            CJGuiInternalSession *session = gCjguiSessions[index];
            if (!session || session.destroyed || session.composableImageDomain != domain) continue;
            for (CJGuiInternalComposableSceneNode *node in session.composableNodes) {
                if (node.imageTextureCacheKey.length > 0) [keys addObject:node.imageTextureCacheKey];
            }
            for (CJGuiInternalComposableSceneNode *node in session.stagedComposableNodes) {
                if (node.imageTextureCacheKey.length > 0) [keys addObject:node.imageTextureCacheKey];
            }
        }
    }
    [keys addObjectsFromArray:domain.loaders.allKeys];
    [keys addObjectsFromArray:domain.pendingKeys];
    for (CJGuiInternalComposableImageResource *resource in domain.resources.allValues) {
        if (resource.transferPreparationCount > 0 || resource.candidateLeaseCount > 0) {
            [keys addObject:resource.cacheKey];
        }
    }
    return keys;
}

static void CjguiPruneComposableImageTextureCache(CJGuiInternalComposableImageResourceDomain *domain,
                                                   BOOL preserveSceneReferences) {
    if (!domain || domain.destroyed) return;
    NSMutableSet<NSString *> *protectedKeys = CjguiComposableImageProtectedKeys(domain, preserveSceneReferences);
    NSUInteger totalBytes = 0;
    for (id<MTLTexture> texture in domain.textureCache.allValues) {
        NSUInteger bytes = CjguiComposableImageTextureBytes(texture);
        totalBytes = bytes > NSUIntegerMax - totalBytes ? NSUIntegerMax : totalBytes + bytes;
    }
    while (domain.textureCache.count > CjguiComposableImageTextureCacheCapacity ||
           totalBytes > CjguiComposableImageTextureCacheByteCapacity) {
        NSString *victim = nil;
        uint64_t oldest = UINT64_MAX;
        for (NSString *key in domain.textureCache) {
            if ([protectedKeys containsObject:key]) continue;
            CJGuiInternalComposableImageResource *resource = domain.resources[key];
            uint64_t access = resource ? resource.lastAccess : 0;
            if (!victim || access < oldest) { victim = key; oldest = access; }
        }
        if (!victim) break;
        id<MTLTexture> texture = domain.textureCache[victim];
        NSUInteger bytes = CjguiComposableImageTextureBytes(texture);
        [domain.textureCache removeObjectForKey:victim];
        CJGuiInternalComposableImageResource *resource = domain.resources[victim];
        if (resource) { resource.texture = nil; resource.state = CjguiComposableImageResourceUnrequested; }
        totalBytes = bytes > totalBytes ? 0 : totalBytes - bytes;
    }
    while (domain.resources.count > CjguiComposableImageRecordCapacity) {
        NSString *victim = nil;
        uint64_t oldest = UINT64_MAX;
        for (NSString *key in domain.resources) {
            if ([protectedKeys containsObject:key] || domain.textureCache[key]) continue;
            CJGuiInternalComposableImageResource *resource = domain.resources[key];
            if (!victim || resource.lastAccess < oldest) { victim = key; oldest = resource.lastAccess; }
        }
        if (!victim) break;
        [domain.resources removeObjectForKey:victim];
    }
}

static void CjguiStartNextComposableImageLoads(CJGuiInternalComposableImageResourceDomain *domain);

static void CjguiEnqueueComposableImageResource(CJGuiInternalComposableImageResourceDomain *domain,
                                                 CJGuiInternalComposableImageResource *resource) {
    if (!domain || !resource) return;
    if (domain.pendingKeys.count >= CjguiComposableImagePendingCapacity) {
        resource.state = CjguiComposableImageResourceBusy;
        return;
    }
    if (![domain.pendingKeys containsObject:resource.cacheKey]) [domain.pendingKeys addObject:resource.cacheKey];
    resource.state = CjguiComposableImageResourceLoading;
#ifdef CJGUI_INTERNAL_TESTING
    domain.testPeakPending = (uint32_t)MIN(UINT32_MAX, MAX((NSUInteger)domain.testPeakPending, domain.pendingKeys.count));
#endif
}

static BOOL CjguiComposableImageHasExplicitPreloadForSession(
    CJGuiInternalSession *session, CJGuiInternalComposableImageResource *resource) {
    if (!session || !resource) return NO;
    for (CJGuiInternalComposableImageSubscription *requester in resource.requesters) {
        if (requester.sessionToken == session.rendererSessionToken &&
            requester.sessionGeneration == session.sessionGeneration && requester.explicitPreload) {
            return YES;
        }
    }
    return NO;
}

// Promote busy demand from a current/staged scene or an explicit public
// preload in this exact domain.  Scan fixed sessions rather than retaining a
// window from the resource domain; stable slot order bounds progression across
// windows.  Candidate-scoped requesters are reconciled separately at commit
// or rollback, while explicit preloads remain eligible until session close.
static void CjguiPromoteReferencedBusyImageResources(CJGuiInternalComposableImageResourceDomain *domain) {
    if (!domain || domain.pendingKeys.count >= CjguiComposableImagePendingCapacity) return;
    NSMutableSet<NSString *> *seen = [NSMutableSet set];
    for (NSUInteger index = 0; index < kCjguiSessionCapacity; index++) {
        CJGuiInternalSession *session = gCjguiSessions[index];
        if (!session || session.destroyed || session.composableImageDomain != domain) continue;
        NSArray<NSArray<CJGuiInternalComposableSceneNode *> *> *nodeSets = @[
            session.stagedComposableNodes ?: @[], session.composableNodes ?: @[]
        ];
        for (NSArray<CJGuiInternalComposableSceneNode *> *nodes in nodeSets) {
            for (CJGuiInternalComposableSceneNode *node in nodes) {
                NSString *cacheKey = node.imageTextureCacheKey;
                if (cacheKey.length == 0 || [seen containsObject:cacheKey]) continue;
                [seen addObject:cacheKey];
                CJGuiInternalComposableImageResource *resource = domain.resources[cacheKey];
                if (!resource || resource.state != CjguiComposableImageResourceBusy) continue;
                resource.lastAccess = CjguiComposableImageNextAccess(domain);
                CjguiEnqueueComposableImageResource(domain, resource);
                if (domain.pendingKeys.count >= CjguiComposableImagePendingCapacity) return;
            }
        }
        // A public prepare may intentionally run before there is a scene node.
        // Once a queued item starts, such overflow requests must not remain
        // permanently busy merely because no current/staged node references
        // them yet. Sort the bounded record keys for deterministic selection.
        NSArray<NSString *> *resourceKeys = [domain.resources.allKeys sortedArrayUsingSelector:@selector(compare:)];
        for (NSString *cacheKey in resourceKeys) {
            if ([seen containsObject:cacheKey]) continue;
            CJGuiInternalComposableImageResource *resource = domain.resources[cacheKey];
            if (!resource || resource.state != CjguiComposableImageResourceBusy ||
                !CjguiComposableImageHasExplicitPreloadForSession(session, resource)) continue;
            [seen addObject:cacheKey];
            resource.lastAccess = CjguiComposableImageNextAccess(domain);
            CjguiEnqueueComposableImageResource(domain, resource);
            if (domain.pendingKeys.count >= CjguiComposableImagePendingCapacity) return;
        }
    }
}

static void CjguiRemoveComposableImageSubscriptions(CJGuiInternalSession *session) {
    CJGuiInternalComposableImageResourceDomain *domain = CjguiComposableImageDomainForSession(session);
    if (!domain || session.rendererSessionToken == 0) return;
    for (CJGuiInternalComposableImageResource *resource in domain.resources.allValues) {
        [resource.subscribers removeObjectsAtIndexes:[resource.subscribers indexesOfObjectsPassingTest:
            ^BOOL(CJGuiInternalComposableImageSubscription *subscriber, NSUInteger index, BOOL *stop) {
                (void)index; (void)stop;
                return subscriber.sessionToken == session.rendererSessionToken &&
                    subscriber.sessionGeneration == session.sessionGeneration;
            }]];
        [resource.requesters removeObjectsAtIndexes:[resource.requesters indexesOfObjectsPassingTest:
            ^BOOL(CJGuiInternalComposableImageSubscription *requester, NSUInteger index, BOOL *stop) {
                (void)index; (void)stop;
                return requester.sessionToken == session.rendererSessionToken &&
                    requester.sessionGeneration == session.sessionGeneration;
            }]];
    }
}

// Rebuild one session's scene-owned demand from its accepted native scene.
// Candidate-scoped requesters are cleared with subscribers, but an explicit
// public preload remains live until its owning session closes.  Do not call
// this from configure/set, where staged candidate nodes have not yet crossed
// the native acceptance boundary.
static void CjguiRestoreAcceptedComposableImageDemand(CJGuiInternalSession *session) {
    CJGuiInternalComposableImageResourceDomain *domain = CjguiComposableImageDomainForSession(session);
    if (!domain || session.rendererSessionToken == 0) return;
    for (CJGuiInternalComposableImageResource *resource in domain.resources.allValues) {
        [resource.subscribers removeObjectsAtIndexes:[resource.subscribers indexesOfObjectsPassingTest:
            ^BOOL(CJGuiInternalComposableImageSubscription *subscriber, NSUInteger index, BOOL *stop) {
                (void)index; (void)stop;
                return subscriber.sessionToken == session.rendererSessionToken &&
                    subscriber.sessionGeneration == session.sessionGeneration;
            }]];
        [resource.requesters removeObjectsAtIndexes:[resource.requesters indexesOfObjectsPassingTest:
            ^BOOL(CJGuiInternalComposableImageSubscription *requester, NSUInteger index, BOOL *stop) {
                (void)index; (void)stop;
                return requester.sessionToken == session.rendererSessionToken &&
                    requester.sessionGeneration == session.sessionGeneration &&
                    !requester.explicitPreload;
            }]];
    }
    for (CJGuiInternalComposableSceneNode *node in session.composableNodes) {
        if (node.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_IMAGE || node.imageTextureCacheKey.length == 0) continue;
        CJGuiInternalComposableImageResource *resource = domain.resources[node.imageTextureCacheKey];
        if (resource) {
            CjguiSubscribeComposableImageResource(session, resource);
            CjguiRequestComposableImageResource(session, resource, NO);
        }
    }
    CjguiStartNextComposableImageLoads(domain);
}

// Called after a native scene replacement commits, and after native present
// rollback has restored the prior accepted scene.  Both paths have the same
// durable owner: `composableNodes`, never the staged candidate.
static void CjguiReconcileCommittedComposableImageSubscribers(CJGuiInternalSession *session) {
    CjguiRestoreAcceptedComposableImageDemand(session);
}

static void CjguiNotifyComposableImageSubscribers(CJGuiInternalComposableImageResourceDomain *domain,
                                                  CJGuiInternalComposableImageResource *resource) {
    if (!domain || !resource) return;
    for (NSInteger index = (NSInteger)resource.subscribers.count - 1; index >= 0; index--) {
        CJGuiInternalComposableImageSubscription *subscriber = resource.subscribers[(NSUInteger)index];
        CJGuiInternalSession *session = CjguiLookupSession(subscriber.sessionToken);
        if (!session || session.destroyed || session.composableImageDomain != domain ||
            session.sessionGeneration != subscriber.sessionGeneration) {
            [resource.subscribers removeObjectAtIndex:(NSUInteger)index];
            continue;
        }
        if (CjguiComposableImageKeyIsReferenced(session, resource.cacheKey) &&
            session.composableImageResourceCompletionVersion < UINT64_MAX) {
            session.composableImageResourceCompletionVersion += 1;
            CjguiPublishViewportSnapshot(session);
        }
    }
}

static CJGuiInternalSession *CjguiComposableImageLiveLaunchSession(
    CJGuiInternalComposableImageResourceDomain *domain, CJGuiInternalComposableImageResource *resource) {
    if (!domain || !resource) return nil;
    for (NSInteger index = (NSInteger)resource.requesters.count - 1; index >= 0; index--) {
        CJGuiInternalComposableImageSubscription *requester = resource.requesters[(NSUInteger)index];
        CJGuiInternalSession *session = CjguiLookupSession(requester.sessionToken);
        if (!session || session.destroyed || session.composableImageDomain != domain ||
            session.sessionGeneration != requester.sessionGeneration) {
            [resource.requesters removeObjectAtIndex:(NSUInteger)index];
            continue;
        }
#ifdef CJGUI_INTERNAL_TESTING
        if (session.testComposableImageLaunchGateHeld) continue;
#endif
        return session;
    }
    return nil;
}

// A held test gate pauses an otherwise live requester; it is not equivalent to
// the requester having gone away.  Keep this check separate from launch
// selection so an unstarted orphan can be removed without cancelling a live,
// deliberately paused request.
static BOOL CjguiComposableImageHasLiveRequester(
    CJGuiInternalComposableImageResourceDomain *domain, CJGuiInternalComposableImageResource *resource) {
    if (!domain || !resource) return NO;
    BOOL hasLiveRequester = NO;
    for (NSInteger index = (NSInteger)resource.requesters.count - 1; index >= 0; index--) {
        CJGuiInternalComposableImageSubscription *requester = resource.requesters[(NSUInteger)index];
        CJGuiInternalSession *session = CjguiLookupSession(requester.sessionToken);
        if (!session || session.destroyed || session.composableImageDomain != domain ||
            session.sessionGeneration != requester.sessionGeneration) {
            [resource.requesters removeObjectAtIndex:(NSUInteger)index];
            continue;
        }
        hasLiveRequester = YES;
    }
    return hasLiveRequester;
}

static void CjguiCompleteComposableImageLoad(CJGuiInternalComposableImageResourceDomain *domain,
                                             CJGuiInternalComposableImageResource *resource,
                                             uint64_t loadGeneration, id<MTLTexture> texture, NSError *error) {
    if (!domain || domain.destroyed || !resource || resource.loadGeneration != loadGeneration ||
        domain.resources[resource.cacheKey] != resource) return;
    [domain.loaders removeObjectForKey:resource.cacheKey];
    if (!CjguiComposableImageHasLiveRequester(domain, resource) &&
        !CjguiComposableImageDomainBoundTexture(domain, resource.cacheKey)) {
        // The owning candidate was cancelled after the loader started. Its
        // callback settles the attempt, but cannot publish an orphan texture
        // or advance any accepted window's completion epoch.
        resource.texture = nil;
        resource.encodedData = nil;
        [domain.textureCache removeObjectForKey:resource.cacheKey];
        [domain.resources removeObjectForKey:resource.cacheKey];
        CjguiStartNextComposableImageLoads(domain);
        return;
    }
    if (resource.state != CjguiComposableImageResourceLoading) {
        CjguiStartNextComposableImageLoads(domain);
        return;
    }
    CJGuiInternalSession *launchSession = CjguiLookupSession(resource.loadSessionToken);
    if (!launchSession || launchSession.destroyed || launchSession.composableImageDomain != domain ||
        launchSession.sessionGeneration != resource.loadSessionGeneration) launchSession = nil;
#ifdef CJGUI_INTERNAL_TESTING
    if (resource.launchMicros > 0 && CjguiMonotonicMicros() >= resource.launchMicros) {
        uint64_t elapsed = CjguiMonotonicMicros() - resource.launchMicros;
        if (launchSession) launchSession.testComposableImageAsyncTotalMicros += elapsed;
        domain.testAsyncTotalMicros += UINT64_MAX - domain.testAsyncTotalMicros < elapsed ? 0 : elapsed;
    }
#endif
    resource.lastAccess = CjguiComposableImageNextAccess(domain);
    if (texture) {
        [domain.textureLedger addObject:texture];
        resource.texture = texture;
        resource.state = CjguiComposableImageResourceReady;
        domain.textureCache[resource.cacheKey] = texture;
        if (launchSession && launchSession.composableImageDecodeCount < UINT32_MAX) {
            launchSession.composableImageDecodeCount += 1;
        }
#ifdef CJGUI_INTERNAL_TESTING
        if (domain.testActualDecodeCount < UINT64_MAX) domain.testActualDecodeCount += 1;
#endif
        NSLog(@"cjgui: composable image preparation ready path=%@", resource.resolvedPath);
    } else {
        resource.texture = nil;
        resource.state = CjguiComposableImageResourceFailed;
        NSLog(@"cjgui: composable image texture load failed path=%@ error=%@", resource.resolvedPath, error);
    }
    CjguiNotifyComposableImageSubscribers(domain, resource);
    CjguiPruneComposableImageTextureCache(domain, YES);
    CjguiStartNextComposableImageLoads(domain);
}

static void CjguiStartNextComposableImageLoads(CJGuiInternalComposableImageResourceDomain *domain) {
    if (!domain || domain.destroyed || !domain.device) return;
    CjguiPromoteReferencedBusyImageResources(domain);
    while (domain.loaders.count < CjguiComposableImageInFlightCapacity && domain.pendingKeys.count > 0) {
        CJGuiInternalComposableImageResource *resource = nil;
        CJGuiInternalSession *launchSession = nil;
        NSUInteger pendingCount = domain.pendingKeys.count;
        while (pendingCount-- > 0) {
            NSString *cacheKey = domain.pendingKeys.firstObject;
            [domain.pendingKeys removeObjectAtIndex:0];
            CJGuiInternalComposableImageResource *candidate = domain.resources[cacheKey];
            if (!candidate || candidate.state != CjguiComposableImageResourceLoading || domain.loaders[cacheKey]) continue;
            CJGuiInternalSession *candidateSession = CjguiComposableImageLiveLaunchSession(domain, candidate);
            if (!candidateSession) {
                if (!CjguiComposableImageHasLiveRequester(domain, candidate)) {
                    // No native loader has been started for this record.  Its
                    // owner closed before launch, so release the queue slot and
                    // record rather than treating a full queue as live demand.
                    candidate.state = CjguiComposableImageResourceUnrequested;
                    candidate.loadSessionToken = 0;
                    candidate.loadSessionGeneration = 0;
                    [domain.resources removeObjectForKey:cacheKey];
                    continue;
                }
                [domain.pendingKeys addObject:cacheKey];
                continue;
            }
            resource = candidate;
            launchSession = candidateSession;
            break;
        }
        if (!resource || !launchSession) break;
        MTKTextureLoader *loader = [[MTKTextureLoader alloc] initWithDevice:domain.device];
        if (!loader) {
            resource.state = CjguiComposableImageResourceFailed;
            CjguiNotifyComposableImageSubscribers(domain, resource);
            continue;
        }
        if (resource.loadGeneration < UINT64_MAX) resource.loadGeneration += 1;
        if (resource.loadGeneration == 0) resource.loadGeneration = 1;
        const uint64_t loadGeneration = resource.loadGeneration;
        resource.loadSessionToken = launchSession.rendererSessionToken;
        resource.loadSessionGeneration = launchSession.sessionGeneration;
        domain.loaders[resource.cacheKey] = loader;
        if (domain.imageDecodeStartCount < UINT64_MAX) domain.imageDecodeStartCount += 1;
        if (launchSession.composableImageDecodeStartCount < UINT64_MAX) {
            launchSession.composableImageDecodeStartCount += 1;
        }
#ifdef CJGUI_INTERNAL_TESTING
        resource.launchMicros = CjguiMonotonicMicros();
        if (launchSession.testComposableImageAsyncLaunchCount < UINT64_MAX) {
            launchSession.testComposableImageAsyncLaunchCount += 1;
        }
        domain.testActualLoadCount += domain.testActualLoadCount < UINT64_MAX ? 1 : 0;
        domain.testPeakInFlight = (uint32_t)MIN(UINT32_MAX, MAX((NSUInteger)domain.testPeakInFlight, domain.loaders.count));
        launchSession.testComposableImagePeakInFlight = (uint32_t)MIN(
            UINT32_MAX, MAX((NSUInteger)launchSession.testComposableImagePeakInFlight, domain.loaders.count));
#endif
        NSLog(@"cjgui: composable image preparation started path=%@", resource.resolvedPath);
        void (^completed)(id<MTLTexture>, NSError *) = ^(id<MTLTexture> texture, NSError *error) {
            CFRunLoopPerformBlock(CFRunLoopGetMain(), kCFRunLoopDefaultMode, ^{
                CjguiCompleteComposableImageLoad(domain, resource, loadGeneration, texture, error);
            });
            CFRunLoopWakeUp(CFRunLoopGetMain());
        };
        NSDictionary *options = @{ MTKTextureLoaderOptionSRGB: @NO,
                                   MTKTextureLoaderOptionGenerateMipmaps: @NO };
        if (resource.encodedData) {
            // The resource and callback both retain the immutable encoded
            // bytes until this started load completes, including after close.
            [loader newTextureWithData:resource.encodedData options:options completionHandler:completed];
        } else {
            NSURL *url = [NSURL fileURLWithPath:resource.resolvedPath];
            [loader newTextureWithContentsOfURL:url options:options completionHandler:completed];
        }
    }
    CjguiPromoteReferencedBusyImageResources(domain);
}

static uint32_t CjguiPrepareComposableImageResourceOnMain(CJGuiInternalSession *session, uint64_t sessionToken,
                                                          NSString *resourcePath, NSString *resourceId,
                                                          uint64_t resourceVersion, NSData *encodedData,
                                                          BOOL retriesFailed,
                                                          BOOL explicitPreload,
                                                          NSString **outCacheKey) {
    if (outCacheKey) *outCacheKey = nil;
    CJGuiInternalComposableImageResourceDomain *domain = CjguiComposableImageDomainForSession(session);
    if (!domain || session.rendererSessionToken != sessionToken) return CjguiComposableImageResourceFailed;
    NSString *resolved = nil;
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t resolveStarted = CjguiMonotonicMicros();
#endif
    NSString *cacheKey = CjguiComposableImageCacheKey(resourcePath, resourceId, resourceVersion, &resolved);
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t resolveElapsed = CjguiMonotonicMicros() - resolveStarted;
    session.testComposableImagePathResolveMicros += resolveElapsed;
    domain.testPathResolveMicros += UINT64_MAX - domain.testPathResolveMicros < resolveElapsed ? 0 : resolveElapsed;
#endif
    if (!cacheKey) return CjguiComposableImageResourceFailed;
    if (outCacheKey) *outCacheKey = cacheKey;
    CJGuiInternalComposableImageResource *resource = domain.resources[cacheKey];
    id<MTLTexture> cached = domain.textureCache[cacheKey] ?: resource.texture;
    if (!resource) {
        resource = [[CJGuiInternalComposableImageResource alloc] init];
        resource.cacheKey = cacheKey;
        resource.resolvedPath = resolved;
        resource.encodedData = [encodedData copy];
        domain.resources[cacheKey] = resource;
    } else if (encodedData && resource.encodedData && ![resource.encodedData isEqualToData:encodedData]) {
        return CjguiComposableImageResourceFailed;
    } else if (encodedData && !resource.encodedData) {
        resource.encodedData = [encodedData copy];
    }
    if ([resourcePath hasPrefix:@"cjgui-transfer:"] && !resource.encodedData) {
        return CjguiComposableImageResourceFailed;
    }
    CjguiRequestComposableImageResource(session, resource, explicitPreload);
    if (cached) {
        domain.textureCache[cacheKey] = cached;
        resource.texture = cached;
        resource.state = CjguiComposableImageResourceReady;
        resource.lastAccess = CjguiComposableImageNextAccess(domain);
#ifdef CJGUI_INTERNAL_TESTING
        if (session.testComposableImageCacheHitCount < UINT64_MAX) session.testComposableImageCacheHitCount += 1;
        if (domain.testCacheHitCount < UINT64_MAX) domain.testCacheHitCount += 1;
#endif
        return resource.state;
    }
    id<MTLTexture> boundTexture = CjguiComposableImageDomainBoundTexture(domain, cacheKey);
    if (boundTexture) {
        resource.texture = nil;
        resource.state = CjguiComposableImageResourceReady;
        resource.lastAccess = CjguiComposableImageNextAccess(domain);
        return resource.state;
    }
    // A transfer-origin image is only decoded by the synchronous bounded
    // admission path. The generic asynchronous loader has no PNG budget gate.
    if ([resourcePath hasPrefix:@"cjgui-transfer:"]) {
        resource.state = CjguiComposableImageResourceFailed;
        return resource.state;
    }
    resource.lastAccess = CjguiComposableImageNextAccess(domain);
    if (resource.state == CjguiComposableImageResourceUnrequested ||
        resource.state == CjguiComposableImageResourceBusy ||
        (retriesFailed && resource.state == CjguiComposableImageResourceFailed)) {
        CjguiEnqueueComposableImageResource(domain, resource);
    }
    CjguiStartNextComposableImageLoads(domain);
    CjguiPruneComposableImageTextureCache(domain, NO);
    return resource.state;
}

static id<MTLTexture> CjguiComposableImageTexture(CJGuiInternalSession *session, uint64_t sessionToken,
                                                  NSString *resourcePath, NSString *resourceId,
                                                  uint64_t resourceVersion, NSData *encodedData,
                                                  NSString **outCacheKey,
                                                  uint32_t *outState) {
    NSString *cacheKey = nil;
    uint32_t state = CjguiPrepareComposableImageResourceOnMain(session, sessionToken, resourcePath, resourceId,
                                                               resourceVersion, encodedData, NO, NO, &cacheKey);
    if (outState) *outState = state;
    if (outCacheKey) *outCacheKey = cacheKey;
    if (!cacheKey || state != CjguiComposableImageResourceReady) return nil;
    CJGuiInternalComposableImageResourceDomain *domain = CjguiComposableImageDomainForSession(session);
    return domain.textureCache[cacheKey] ?: domain.resources[cacheKey].texture ?:
        CjguiComposableImageDomainBoundTexture(domain, cacheKey);
}

static uint32_t CjguiPngBigEndian32(const uint8_t *bytes) {
    return ((uint32_t)bytes[0] << 24) | ((uint32_t)bytes[1] << 16) |
           ((uint32_t)bytes[2] << 8) | (uint32_t)bytes[3];
}

static uint32_t CjguiPngCrc32(const uint8_t *bytes, NSUInteger length) {
    uint32_t crc = UINT32_MAX;
    for (NSUInteger index = 0; index < length; index++) {
        crc ^= bytes[index];
        for (uint32_t bit = 0; bit < 8; bit++) {
            crc = (crc >> 1) ^ ((crc & 1u) ? 0xEDB88320u : 0u);
        }
    }
    return ~crc;
}

// This first PNG exchange supports static noninterlaced 8-bit RGB/RGBA images. A complete
// chunk/CRC walk runs before ImageKit's actual decode so a header-only or
// truncated source never reaches the owner. Dimensions use divide-before-
// multiply checks; the sync Metal decode below validates compressed pixels.
static CjguiInternalRendererStatus CjguiValidateComposableTransferPng(
    const uint8_t *bytes, NSUInteger length, uint32_t *outWidth, uint32_t *outHeight) {
    static const uint8_t signature[8] = {137, 80, 78, 71, 13, 10, 26, 10};
    if (!bytes || length < 8 + 25 + 12 || length > 512u * 1024u ||
        memcmp(bytes, signature, sizeof(signature)) != 0) return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
    NSUInteger offset = 8;
    BOOL sawIHDR = NO, sawIDAT = NO, sawIEND = NO, sawPLTE = NO, idatEnded = NO;
    BOOL unsupportedVariant = NO;
    uint32_t width = 0, height = 0;
    uint8_t colorType = 0;
    while (offset < length) {
        if (length - offset < 12) return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
        uint32_t chunkLength = CjguiPngBigEndian32(bytes + offset);
        if ((NSUInteger)chunkLength > length - offset - 12) return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
        const uint8_t *type = bytes + offset + 4;
        const uint8_t *payload = bytes + offset + 8;
        if (CjguiPngCrc32(type, (NSUInteger)chunkLength + 4) !=
            CjguiPngBigEndian32(payload + chunkLength)) return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
        if (!sawIHDR) {
            if (memcmp(type, "IHDR", 4) != 0 || chunkLength != 13) return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
            width = CjguiPngBigEndian32(payload);
            height = CjguiPngBigEndian32(payload + 4);
            if (width == 0 || height == 0 || width > 2048 || height > 2048 ||
                height > 1048576u / width) return CJGUI_INTERNAL_RENDERER_PNG_DIMENSION_EXCEEDED;
            uint8_t depth = payload[8], color = payload[9];
            colorType = color;
            BOOL legalDepthColor = (color == 0 && (depth == 1 || depth == 2 || depth == 4 ||
                depth == 8 || depth == 16)) || (color == 2 && (depth == 8 || depth == 16)) ||
                (color == 3 && (depth == 1 || depth == 2 || depth == 4 || depth == 8)) ||
                (color == 4 && (depth == 8 || depth == 16)) ||
                (color == 6 && (depth == 8 || depth == 16));
            if (!legalDepthColor || payload[10] != 0 || payload[11] != 0 || payload[12] > 1) {
                return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
            }
            unsupportedVariant = depth != 8 || (color != 2 && color != 6) || payload[12] != 0;
            sawIHDR = YES;
        } else if (memcmp(type, "IHDR", 4) == 0) {
            return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
        } else if (memcmp(type, "acTL", 4) == 0) {
            unsupportedVariant = YES;
            if (sawIDAT || chunkLength != 8) return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
        } else if (memcmp(type, "PLTE", 4) == 0) {
            if (sawPLTE || sawIDAT || chunkLength == 0 || chunkLength > 768 || chunkLength % 3 != 0 ||
                colorType == 0 || colorType == 4) return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
            sawPLTE = YES;
        } else if (memcmp(type, "IDAT", 4) == 0) {
            if (idatEnded || (colorType == 3 && !sawPLTE)) return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
            sawIDAT = sawIDAT || chunkLength > 0;
        } else if (memcmp(type, "IEND", 4) == 0) {
            if (chunkLength != 0 || !sawIDAT || offset + 12 != length) {
                return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
            }
            sawIEND = YES;
        } else if ((type[0] & 0x20u) == 0) {
            // Unknown critical chunks change pixel interpretation; the first
            // transfer subset cannot safely hand them to a permissive decoder.
            return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
        }
        if (sawIDAT && memcmp(type, "IDAT", 4) != 0 && memcmp(type, "IEND", 4) != 0) idatEnded = YES;
        offset += (NSUInteger)chunkLength + 12;
        if (sawIEND) break;
    }
    if (!sawIHDR || !sawIDAT || !sawIEND || offset != length) return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
    if (unsupportedVariant) return CJGUI_INTERNAL_RENDERER_PNG_UNSUPPORTED;
    if (outWidth) *outWidth = width;
    if (outHeight) *outHeight = height;
    return CJGUI_INTERNAL_RENDERER_OK;
}

// Count actual live allocations, not the number of strong references. The
// weak table does not itself extend a texture's lifetime. In particular, a
// texture in the cache, two scene nodes and an in-flight command is charged
// once; an evicted but still submitted generation remains charged.
static NSUInteger CjguiComposableImageConservativeLiveBytes(
    CJGuiInternalComposableImageResourceDomain *domain) {
    NSUInteger total = 0;
    for (id<MTLTexture> texture in domain.textureLedger) {
        NSUInteger bytes = CjguiComposableImageTextureBytes(texture);
        if (bytes > NSUIntegerMax - total) return NSUIntegerMax;
        total += bytes;
    }
    return total;
}

// Make room before allocating a PNG texture or record. Cache ownership is
// reclaimable; scene, preparation and GPU owners are not. Recount the weak
// allocation ledger after every actual eviction so a submitted old generation
// cannot be credited as free merely because its cache key was removed.
static BOOL CjguiReclaimComposablePngHeadroom(
    CJGuiInternalComposableImageResourceDomain *domain, NSString *incomingKey,
    NSUInteger incomingEncodedBytes, NSUInteger incomingTextureBytes) {
    if (!domain || incomingEncodedBytes > 8u * 1024u * 1024u ||
        incomingTextureBytes > CjguiComposableImageTextureCacheByteCapacity) return NO;
    NSMutableSet<NSString *> *protected = CjguiComposableImageProtectedKeys(domain, YES);
    if (incomingKey) [protected addObject:incomingKey];
    for (NSUInteger attempt = 0; attempt <= CjguiComposableImageRecordCapacity +
         CjguiComposableImageTextureCacheCapacity; attempt++) {
        NSUInteger encoded = 0;
        for (CJGuiInternalComposableImageResource *resource in domain.resources.allValues) {
            if ([resource.cacheKey isEqualToString:incomingKey]) continue;
            if (resource.encodedData.length > NSUIntegerMax - encoded) return NO;
            encoded += resource.encodedData.length;
        }
        NSUInteger live = CjguiComposableImageConservativeLiveBytes(domain);
        BOOL slotFits = domain.resources[incomingKey] != nil ||
            domain.resources.count < CjguiComposableImageRecordCapacity;
        if (slotFits && encoded <= 8u * 1024u * 1024u - incomingEncodedBytes &&
            live <= CjguiComposableImageTextureCacheByteCapacity - incomingTextureBytes) return YES;
        NSString *victim = nil;
        uint64_t oldest = UINT64_MAX;
        for (NSString *key in domain.resources) {
            if ([protected containsObject:key]) continue;
            CJGuiInternalComposableImageResource *candidate = domain.resources[key];
            if (!victim || candidate.lastAccess < oldest) {
                victim = key;
                oldest = candidate.lastAccess;
            }
        }
        if (!victim) {
            for (NSString *key in domain.textureCache) {
                if (![protected containsObject:key]) { victim = key; break; }
            }
        }
        if (!victim) return NO;
        CJGuiInternalComposableImageResource *retired = domain.resources[victim];
        retired.texture = nil;
        retired.encodedData = nil;
        [domain.textureCache removeObjectForKey:victim];
        [domain.resources removeObjectForKey:victim];
    }
    return NO;
}

static CjguiInternalRendererStatus CjguiPrepareComposablePngTransferOnMain(
    uint64_t sessionToken, const char *resourceIdentity, const uint8_t *bytes, uint32_t length,
    uint32_t *outWidth, uint32_t *outHeight, uint64_t *outDecodeMicros) {
    if (!outWidth || !outHeight || !outDecodeMicros) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    *outWidth = 0; *outHeight = 0; *outDecodeMicros = 0;
    CJGuiInternalSession *session = CjguiLookupSession(sessionToken);
    if (!session || session.destroyed) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    NSString *identity = resourceIdentity ? [NSString stringWithUTF8String:resourceIdentity] : nil;
    if (!identity || ![identity hasPrefix:@"cjgui-transfer:"] || identity.length > 96) {
        return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    }
    uint32_t width = 0, height = 0;
    CjguiInternalRendererStatus valid = CjguiValidateComposableTransferPng(bytes, length, &width, &height);
    if (valid != CJGUI_INTERNAL_RENDERER_OK) return valid;
    CJGuiInternalComposableImageResourceDomain *domain = CjguiComposableImageDomainForSession(session);
    if (!domain) return CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED;
    NSString *resolved = nil;
    NSString *key = CjguiComposableImageCacheKey(identity, identity, 0, &resolved);
    if (!key) return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
    CJGuiInternalComposableImageResource *existing = domain.resources[key];
    if (existing && existing.encodedData &&
        (existing.encodedData.length != length ||
         memcmp(existing.encodedData.bytes, bytes, length) != 0)) {
        return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
    }
    id<MTLTexture> texture = domain.textureCache[key] ?: existing.texture ?:
        CjguiComposableImageDomainBoundTexture(domain, key);
    BOOL cacheHit = texture && texture.width == width && texture.height == height;
    CjguiPruneComposableImageTextureCache(domain, YES);
    // Prune may have retired an evictable cache-hit record while this call
    // still holds its texture locally. Do not increment a detached record:
    // finish must find the exact newly admitted resource in this domain.
    if (existing && domain.resources[key] != existing) existing = nil;
    if (CjguiDataTransferTraceEnabled()) {
        NSLog(@"cjgui: PNG admission identity=%@ records=%lu textures=%lu encoded=%lu pixels=%ux%u",
              identity, (unsigned long)domain.resources.count,
              (unsigned long)domain.textureCache.count, (unsigned long)length, width, height);
    }
    NSUInteger budgetedTextureBytes = cacheHit ? 0 : (NSUInteger)width * (NSUInteger)height * 4u;
    if (!CjguiReclaimComposablePngHeadroom(domain, key, length, budgetedTextureBytes)) {
        return CJGUI_INTERNAL_RENDERER_PNG_RESOURCE_BUDGET_EXCEEDED;
    }
    if (existing) {
        CJGuiInternalComposableImageTransferHold *hold = CjguiComposableTransferHold(existing, session, NO);
        if ((hold && hold.preparationCount >= 128) ||
            (!hold && existing.transferHolds.count >= kCjguiSessionCapacity)) {
            return CJGUI_INTERNAL_RENDERER_PNG_RESOURCE_BUDGET_EXCEEDED;
        }
    }
    // The queue owns the first bounded copy. Do not create the retained image
    // record's second copy until both its encoded and decoded budgets fit.
    NSData *data = [NSData dataWithBytes:bytes length:length];
    if (!data) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    if (cacheHit) {
        if (!existing) {
            existing = [[CJGuiInternalComposableImageResource alloc] init];
            if (!existing) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
            existing.cacheKey = key;
            existing.resolvedPath = resolved;
            domain.resources[key] = existing;
        }
        existing.encodedData = data;
        existing.texture = texture;
        existing.state = CjguiComposableImageResourceReady;
        existing.lastAccess = CjguiComposableImageNextAccess(domain);
        CJGuiInternalComposableImageTransferHold *hold = CjguiComposableTransferHold(existing, session, YES);
        if (!hold) return CJGUI_INTERNAL_RENDERER_PNG_RESOURCE_BUDGET_EXCEEDED;
        hold.preparationCount += 1;
        CjguiUpdateComposableTransferHoldCounts(existing);
        domain.textureCache[key] = texture;
        [domain.textureLedger addObject:texture];
        *outWidth = width; *outHeight = height;
        return CJGUI_INTERNAL_RENDERER_OK;
    }
    MTKTextureLoader *loader = [[MTKTextureLoader alloc] initWithDevice:domain.device];
    if (!loader) return CJGUI_INTERNAL_RENDERER_PNG_DECODE_FAILED;
    if (domain.imageDecodeStartCount < UINT64_MAX) domain.imageDecodeStartCount += 1;
    if (session.composableImageDecodeStartCount < UINT64_MAX) session.composableImageDecodeStartCount += 1;
    NSError *error = nil;
    uint64_t started = (uint64_t)(CACurrentMediaTime() * 1000000.0);
    texture = [loader newTextureWithData:data options:@{ MTKTextureLoaderOptionSRGB: @NO,
        MTKTextureLoaderOptionGenerateMipmaps: @NO } error:&error];
    uint64_t ended = (uint64_t)(CACurrentMediaTime() * 1000000.0);
    *outDecodeMicros = ended >= started ? ended - started : 0;
    if (!texture || texture.width != width || texture.height != height ||
        (texture.pixelFormat != MTLPixelFormatRGBA8Unorm && texture.pixelFormat != MTLPixelFormatBGRA8Unorm)) {
        NSLog(@"cjgui: PNG transfer decode rejected error=%@", error);
        return CJGUI_INTERNAL_RENDERER_PNG_DECODE_FAILED;
    }
    [domain.textureLedger addObject:texture];
    CJGuiInternalComposableImageResource *resource = existing;
    if (!resource) {
        resource = [[CJGuiInternalComposableImageResource alloc] init];
        if (!resource) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        resource.cacheKey = key;
        resource.resolvedPath = resolved;
        domain.resources[key] = resource;
    }
    resource.encodedData = data;
    resource.texture = texture;
    resource.state = CjguiComposableImageResourceReady;
    resource.lastAccess = CjguiComposableImageNextAccess(domain);
    CJGuiInternalComposableImageTransferHold *hold = CjguiComposableTransferHold(resource, session, YES);
    if (!hold) return CJGUI_INTERNAL_RENDERER_PNG_RESOURCE_BUDGET_EXCEEDED;
    hold.preparationCount += 1;
    CjguiUpdateComposableTransferHoldCounts(resource);
    domain.textureCache[key] = texture;
    *outWidth = width; *outHeight = height;
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus cjgui_internal_renderer_prepare_composable_png_transfer(
    uint64_t session, const char *resourceIdentity, const uint8_t *bytes, uint32_t length,
    uint32_t *outWidth, uint32_t *outHeight, uint64_t *outDecodeMicros) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = CjguiPrepareComposablePngTransferOnMain(session, resourceIdentity, bytes, length,
                outWidth, outHeight, outDecodeMicros);
        });
        return status;
    }
    return CjguiPrepareComposablePngTransferOnMain(session, resourceIdentity, bytes, length,
        outWidth, outHeight, outDecodeMicros);
}

CjguiInternalRendererStatus cjgui_internal_renderer_finish_composable_png_transfer(
    uint64_t sessionToken, const char *resourceIdentity, uint8_t accepted) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = cjgui_internal_renderer_finish_composable_png_transfer(sessionToken, resourceIdentity, accepted);
        });
        return status;
    }
    CJGuiInternalSession *session = CjguiLookupSession(sessionToken);
    if (!session) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    CJGuiInternalComposableImageResourceDomain *domain = CjguiComposableImageDomainForSession(session);
    NSString *identity = resourceIdentity ? [NSString stringWithUTF8String:resourceIdentity] : nil;
    NSString *key = CjguiComposableImageCacheKey(identity, identity, 0, NULL);
    CJGuiInternalComposableImageResource *resource = domain.resources[key];
    CJGuiInternalComposableImageTransferHold *hold = CjguiComposableTransferHold(resource, session, NO);
    if (!hold || hold.preparationCount == 0) return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    hold.preparationCount -= 1;
    if (accepted) {
        // The accepted candidate's node is staged by the application's NEXT
        // scene, which does not exist yet. Keep the decoded texture alive
        // through that handoff instead of returning it to a cache that can
        // evict it immediately (the 9th image under a full 8-entry cache).
#ifdef CJGUI_INTERNAL_TESTING
        if (gCjguiPngCandidateLeaseEnabled)
#endif
        CjguiGrantComposableImageCandidateLease(session, resource);
    }
    CjguiUpdateComposableTransferHoldCounts(resource);
    if (!accepted && resource.transferPreparationCount == 0 && resource.candidateLeaseCount == 0 &&
        !CjguiComposableImageDomainBoundTexture(domain, key)) {
        [domain.textureCache removeObjectForKey:key];
        [domain.resources removeObjectForKey:key];
    }
    CjguiPruneComposableImageTextureCache(domain, YES);
    return CJGUI_INTERNAL_RENDERER_OK;
}

// A source-verified image frame is useful after a dynamic resource or
// fit/fill change, but forcing a synchronous readback for unrelated text
// edits would make ordinary refreshes unnecessarily expensive.
static BOOL CjguiComposableImageContentChanged(NSArray<CJGuiInternalComposableSceneNode *> *before,
                                               NSArray<CJGuiInternalComposableSceneNode *> *after) {
    NSMutableDictionary<NSNumber *, CJGuiInternalComposableSceneNode *> *oldByNodeId = [NSMutableDictionary dictionary];
    for (CJGuiInternalComposableSceneNode *node in before) {
        if (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_IMAGE) oldByNodeId[@(node.node.nodeId)] = node;
    }
    NSUInteger oldImageCount = oldByNodeId.count;
    NSUInteger newImageCount = 0;
    for (CJGuiInternalComposableSceneNode *node in after) {
        if (node.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_IMAGE) continue;
        newImageCount += 1;
        CJGuiInternalComposableSceneNode *previous = oldByNodeId[@(node.node.nodeId)];
        if (!previous || ![previous.imageTextureCacheKey isEqualToString:node.imageTextureCacheKey] ||
            previous.node.imageContentMode != node.node.imageContentMode ||
            previous.node.x != node.node.x || previous.node.y != node.node.y ||
            previous.node.width != node.node.width || previous.node.height != node.node.height ||
            previous.node.clipX != node.node.clipX || previous.node.clipY != node.node.clipY ||
            previous.node.clipWidth != node.node.clipWidth || previous.node.clipHeight != node.node.clipHeight) return YES;
    }
    return oldImageCount != newImageCount;
}

// A generic first-frame readback is intentionally much narrower than the
// renderer: it may only compare a pixel when the final Metal value is fully
// determined by an opaque, unclipped rectangle.  In particular, never clamp
// a centre outside a scroll clip, and never infer an alpha/image result from
// a lower layer.  Exact transparent and image pixels use the testing asset
// path below instead of making this diagnostic guess.
typedef struct {
    // This is the logical centre of the exact drawable texel that the blit
    // will read. It is deliberately not the mathematical centre of a node:
    // at an odd width or non-integral scale those can select different pixels.
    CGFloat logicalX;
    CGFloat logicalY;
    NSUInteger sampleX;
    NSUInteger sampleY;
} CjguiComposableReadbackProbePoint;

static BOOL CjguiComposablePointInInterval(CGFloat point, int64_t start, int64_t length) {
    return length > 0 && point >= (CGFloat)start && point < (CGFloat)start + (CGFloat)length;
}

static BOOL CjguiComposablePointInRoundedComponents(CGFloat pointX, CGFloat pointY,
                                                     CGFloat x, CGFloat y, CGFloat width, CGFloat height,
                                                     CGFloat cornerRadius) {
    if (width <= 0.0 || height <= 0.0 || pointX < x || pointY < y || pointX >= x + width || pointY >= y + height) return NO;
    CGFloat radius = MIN(MAX(0.0, cornerRadius), MIN(width, height) / 2.0);
    if (radius <= 0.0 || (pointX >= x + radius && pointX < x + width - radius) ||
        (pointY >= y + radius && pointY < y + height - radius)) return YES;
    CGFloat centreX = pointX < x + radius ? x + radius : x + width - radius;
    CGFloat centreY = pointY < y + radius ? y + radius : y + height - radius;
    CGFloat dx = pointX - centreX, dy = pointY - centreY;
    return dx * dx + dy * dy <= radius * radius;
}

static BOOL CjguiComposablePointInClipChain(CGFloat pointX, CGFloat pointY,
                                             CJGuiInternalComposableSceneNode *node) {
    uint32_t count = CjguiComposableClipConstraintCount(node.node);
    for (uint32_t i = 0; i < count; i++) {
        CGFloat x = 0, y = 0, width = 0, height = 0, radius = 0;
        CjguiComposableVisualClipConstraintAt(node, i, &x, &y, &width, &height, &radius);
        if (!CjguiComposablePointInRoundedComponents(pointX, pointY, x, y, width, height, radius)) return NO;
    }
    return YES;
}

static BOOL CjguiComposableNodeContainsVisiblePoint(CJGuiInternalComposableSceneNode *node,
                                                     CGFloat pointX, CGFloat pointY, NSSize viewSize) {
    if (!node || viewSize.width <= 0.0 || viewSize.height <= 0.0) return NO;
    NSRect visual = CjguiComposableVisualNodeRect(node);
    return NSPointInRect(NSMakePoint(pointX, pointY), visual) &&
        CjguiComposablePointInClipChain(pointX, pointY, node) &&
        pointX >= 0 && pointY >= 0 &&
        pointX < viewSize.width && pointY < viewSize.height;
}

static BOOL CjguiComposableRectContainsPoint(NSRect rect, CGFloat pointX, CGFloat pointY) {
    return !NSIsEmptyRect(rect) && pointX >= NSMinX(rect) && pointX < NSMaxX(rect) &&
        pointY >= NSMinY(rect) && pointY < NSMaxY(rect);
}

// The text body and its active decorations are ordinary Metal commands in a
// node's resolved clip chain. They do not identify a predictable colour from
// the public scene scalar, so they must make the generic opaque probe decline
// that texel. This is intentionally a bounds-only rejection: the exact glyph
// alpha belongs to the immutable native texture and is verified through the
// explicit testing readback path rather than guessed here.
static BOOL CjguiComposableTextPresentationMayAffectVisiblePoint(CJGuiInternalSession *ctx,
                                                                 CJGuiInternalComposableSceneNode *node,
                                                                 CGFloat pointX, CGFloat pointY,
                                                                 NSSize viewSize) {
    if (!CjguiComposableNodeContainsVisiblePoint(node, pointX, pointY, viewSize)) return NO;
    if ((node.textTexture || node.textTileTextures.count > 0) &&
        CjguiComposableRectContainsPoint(NSOffsetRect(node.textTextureRect,
            node.geometry.translateX, node.geometry.translateY), pointX, pointY)) return YES;
    for (NSValue *valueRect in CjguiEffectiveTransferTextSelectionRects(ctx, node)) {
        if (CjguiComposableRectContainsPoint(valueRect.rectValue, pointX, pointY)) return YES;
    }
    for (NSDictionary *decoration in CjguiEffectiveDeclaredSelectionDecorations(ctx, node)) {
        NSValue *valueRect = decoration[@"rect"];
        if ([valueRect isKindOfClass:NSValue.class] &&
            CjguiComposableRectContainsPoint(valueRect.rectValue, pointX, pointY)) return YES;
    }
    for (NSValue *valueRect in node.textMarkedRects) {
        if (CjguiComposableRectContainsPoint(valueRect.rectValue, pointX, pointY)) return YES;
    }
    return CjguiComposableRectContainsPoint(CjguiEffectiveTransferTextCaretRect(ctx, node), pointX, pointY);
}

static BOOL CjguiComposableBorderMayAffectVisiblePoint(CJGuiInternalComposableSceneNode *node,
                                                        CGFloat pointX, CGFloat pointY) {
    CjguiInternalRendererComposableNode value = node.node;
    if (value.borderWidth == 0 || value.borderAlpha <= 0.0) return NO;
    int64_t border = MIN((int64_t)value.borderWidth, MIN(value.width / 2, value.height / 2));
    NSRect rect = CjguiComposableVisualNodeRect(node);
    return pointX < NSMinX(rect) + border || pointX >= NSMaxX(rect) - border ||
        pointY < NSMinY(rect) + border || pointY >= NSMaxY(rect) - border;
}

static BOOL CjguiComposableNodeMayAffectVisiblePoint(CJGuiInternalSession *ctx,
                                                      CJGuiInternalComposableSceneNode *node,
                                                      CGFloat pointX, CGFloat pointY, NSSize viewSize) {
    if (!CjguiComposableNodeContainsVisiblePoint(node, pointX, pointY, viewSize)) return NO;
    CjguiInternalRendererComposableNode value = node.node;
    if (value.fillAlpha > 0.0 ||
        (value.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_IMAGE && node.imageTexture)) return YES;
    if (CjguiComposableTextPresentationMayAffectVisiblePoint(ctx, node, pointX, pointY, viewSize)) return YES;
    return CjguiComposableBorderMayAffectVisiblePoint(node, pointX, pointY);
}

static BOOL CjguiComposableSceneHasPotentialMetalDraw(CJGuiInternalSession *ctx,
    NSArray<CJGuiInternalComposableSceneNode *> *nodes) {
    for (CJGuiInternalComposableSceneNode *node in nodes) {
        CjguiInternalRendererComposableNode value = node.node;
        if (value.width <= 0 || value.height <= 0 ||
            NSIsEmptyRect(NSIntersectionRect(CjguiComposableVisualNodeRect(node),
                                              CjguiComposableVisualClipBounds(node)))) continue;
        if (value.fillAlpha > 0.0 || (value.borderWidth > 0 && value.borderAlpha > 0.0) ||
            (value.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_IMAGE && node.imageTexture) ||
            ((node.textTexture || node.textTileTextures.count > 0) && !NSIsEmptyRect(node.textTextureRect)) ||
            CjguiEffectiveTransferTextSelectionRects(ctx, node).count > 0 ||
            CjguiEffectiveDeclaredSelectionDecorations(ctx, node).count > 0 ||
            node.textMarkedRects.count > 0 ||
            !NSIsEmptyRect(CjguiEffectiveTransferTextCaretRect(ctx, node))) return YES;
    }
    return NO;
}

static BOOL CjguiComposableReadbackProbePointForNode(CJGuiInternalComposableSceneNode *node,
                                                      NSSize viewSize, CGSize drawableSize,
                                                      CjguiComposableReadbackProbePoint *outPoint) {
    if (!outPoint || viewSize.width <= 0.0 || viewSize.height <= 0.0 ||
        drawableSize.width < 1.0 || drawableSize.height < 1.0) return NO;
    CGFloat scaleX = drawableSize.width / viewSize.width;
    CGFloat scaleY = drawableSize.height / viewSize.height;
    if (!isfinite(scaleX) || !isfinite(scaleY) || scaleX <= 0.0 || scaleY <= 0.0) return NO;
    NSRect visual = CjguiComposableVisualNodeRect(node);
    CGFloat centreX = NSMidX(visual);
    CGFloat centreY = NSMidY(visual);
    NSInteger pixelX = (NSInteger)floor(centreX * scaleX);
    NSInteger pixelY = (NSInteger)floor(centreY * scaleY);
    if (pixelX < 0 || pixelY < 0 || pixelX >= (NSInteger)drawableSize.width || pixelY >= (NSInteger)drawableSize.height) return NO;
    outPoint->sampleX = (NSUInteger)pixelX;
    outPoint->sampleY = (NSUInteger)pixelY;
    outPoint->logicalX = ((CGFloat)pixelX + 0.5) / scaleX;
    outPoint->logicalY = ((CGFloat)pixelY + 0.5) / scaleY;
    return isfinite(outPoint->logicalX) && isfinite(outPoint->logicalY);
}

static CJGuiInternalComposableSceneNode *CjguiComposableSafeOpaqueProbeNode(CJGuiInternalSession *ctx,
    NSArray<CJGuiInternalComposableSceneNode *> *nodes, NSSize viewSize, CGSize drawableSize,
    CjguiComposableReadbackProbePoint *outPoint) {
    // Walk from the top of z order. A later transparent/image/border draw can
    // still change a lower opaque centre, so reject that lower candidate
    // rather than reporting a false colour mismatch.
    for (NSInteger candidateIndex = (NSInteger)nodes.count - 1; candidateIndex >= 0; candidateIndex--) {
        CJGuiInternalComposableSceneNode *candidate = nodes[(NSUInteger)candidateIndex];
        CjguiInternalRendererComposableNode value = candidate.node;
        // An image node first paints its declared fill and then samples an
        // arbitrary (possibly transparent) texture. Its centre is therefore
        // never a generic colour oracle even when the fill itself is opaque.
        if (value.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_IMAGE ||
            value.fillAlpha < 1.0 || value.width <= 0 || value.height <= 0) continue;
        CjguiComposableReadbackProbePoint point = {0};
        if (!CjguiComposableReadbackProbePointForNode(candidate, viewSize, drawableSize, &point) ||
            !CjguiComposableNodeContainsVisiblePoint(candidate, point.logicalX, point.logicalY, viewSize) ||
            CjguiComposableTextPresentationMayAffectVisiblePoint(ctx, candidate, point.logicalX, point.logicalY, viewSize) ||
            CjguiComposableBorderMayAffectVisiblePoint(candidate, point.logicalX, point.logicalY)) continue;
        BOOL covered = NO;
        for (NSUInteger upperIndex = (NSUInteger)candidateIndex + 1; upperIndex < nodes.count; upperIndex++) {
            if (CjguiComposableNodeMayAffectVisiblePoint(ctx, nodes[upperIndex], point.logicalX, point.logicalY, viewSize)) {
                covered = YES;
                break;
            }
        }
        if (!covered) {
            *outPoint = point;
            return candidate;
        }
    }
    return nil;
}

// A staged replacement must never mutate the live input/overlay snapshot.
// COW callers retain an immutable current node until a Cangjie setter changes
// that index, at which point this copies native-owned scalar/string/texture
// references into one staged node. The texture remains a normal strong
// Objective-C reference and no native handle crosses the ABI.
#ifdef CJGUI_INTERNAL_TESTING
// Bounded distinct-label record of clones: "index:nodeId:kind" plus a count.
// A per-refresh rewrite of untouched nodes shows up as one label whose count
// grows with the sample count, which is the discriminating fact a plain total
// (570 clones) cannot show.
static void CjguiRecordComposableSceneCloneLabel(CJGuiInternalSession *session,
                                                 CJGuiInternalComposableSceneNode *source, uint32_t index) {
    if (!session || !source) return;
    if (!session.testCloneLabels) {
        session.testCloneLabels = [NSMutableArray array];
        session.testCloneLabelCounts = [NSMutableArray array];
    }
    NSString *label = [NSString stringWithFormat:@"%u:%llu:%u", index,
        (unsigned long long)source.node.nodeId, source.node.nodeKind];
    NSUInteger position = [session.testCloneLabels indexOfObject:label];
    if (position == NSNotFound) {
        if (session.testCloneLabels.count >= 64) return;
        [session.testCloneLabels addObject:label];
        [session.testCloneLabelCounts addObject:@1];
        return;
    }
    NSNumber *count = session.testCloneLabelCounts[position];
    session.testCloneLabelCounts[position] = @(count.unsignedLongLongValue + 1);
}
#endif

static CJGuiInternalComposableSceneNode *CjguiCloneComposableSceneNode(
    CJGuiInternalSession *session, CJGuiInternalComposableSceneNode *source, uint32_t index, uint64_t projectionVersion) {
    if (!source) return nil;
    CJGuiInternalComposableSceneNode *copy = [[CJGuiInternalComposableSceneNode alloc] init];
    if (!copy) return nil;
    CjguiInternalRendererComposableNode copiedValue = source.node;
    copiedValue.projectionVersion = projectionVersion;
    copy.node = copiedValue;
    copy.geometry = source.geometry;
    copy.index = index;
    copy.label = [source.label copy] ?: @"";
    copy.value = [source.value copy] ?: @"";
    copy.semanticId = [source.semanticId copy] ?: @"";
    copy.semanticBindingKey = [source.semanticBindingKey copy] ?: @"";
    copy.semanticRowKey = [source.semanticRowKey copy] ?: @"";
    copy.semanticParentRowKey = [source.semanticParentRowKey copy] ?: @"";
    copy.semanticLabel = [source.semanticLabel copy] ?: @"";
    copy.imageResourcePath = [source.imageResourcePath copy] ?: @"";
    copy.imageEncodedData = [source.imageEncodedData copy];
    copy.imageResourceId = [source.imageResourceId copy] ?: @"";
    copy.imageResourceVersion = source.imageResourceVersion;
    copy.imageTextureCacheKey = [source.imageTextureCacheKey copy] ?: @"";
    copy.imageTextureContentKey = [source.imageTextureContentKey copy] ?: @"";
    copy.imageTexture = source.imageTexture;
    copy.styleRunsSignature = [source.styleRunsSignature copy];
    copy.textTextureCacheKey = [source.textTextureCacheKey copy] ?: @"";
    copy.textTextureSourceCredential = source.textTextureSourceCredential;
    copy.textVisibilityRasterLayout = source.textVisibilityRasterLayout;
    copy.textTexture = source.textTexture;
    copy.textTileTextures = source.textTileTextures;
    copy.textTileRects = source.textTileRects;
    copy.textTextureByteCount = source.textTextureByteCount;
    copy.textTextureRect = source.textTextureRect;
    copy.textTileLayoutOrigin = source.textTileLayoutOrigin;
    copy.textMeasuredSource = source.textMeasuredSource;
    copy.textMeasuredWidth = source.textMeasuredWidth;
    copy.textMeasuredFontSize = source.textMeasuredFontSize;
    copy.textMeasuredFontWeight = source.textMeasuredFontWeight;
    copy.textMeasuredFontFamily = source.textMeasuredFontFamily;
    copy.textMeasuredNodeKind = source.textMeasuredNodeKind;
    copy.textMeasuredExtent = source.textMeasuredExtent;
    copy.textMeasureValid = source.textMeasureValid;
#ifdef CJGUI_INTERNAL_TESTING
    copy.testTextExtentMeasurementCount = source.testTextExtentMeasurementCount;
#endif
    // Geometry-only COW can run after text preparation. The accepted layout
    // belongs to this immutable node generation too; dropping it makes a
    // pure translation turn a previously available caret/IME query into
    // GEOMETRY_EMPTY even though the raster texture was reused.
    copy.preparedTextLayout = source.preparedTextLayout;
    copy.hasVectorGeometry = source.hasVectorGeometry;
    copy.vectorGeometry = source.vectorGeometry;
    copy.vectorPreparedTriangles = source.vectorPreparedTriangles;
    copy.hasVectorPreparedGeometry = source.hasVectorPreparedGeometry;
    copy.vectorPreparedGeometry = source.vectorPreparedGeometry;
    copy.vectorPreparedVertexBuffer = source.vectorPreparedVertexBuffer;
    copy.vectorPreparedVertexCount = source.vectorPreparedVertexCount;
    copy.vectorPreparedVertexBytes = source.vectorPreparedVertexBytes;
    copy.textSelectionRects = [source.textSelectionRects copy] ?: @[];
    copy.textSelectionTransferId = source.textSelectionTransferId;
    copy.textDeclaredSelectionDecorations = [source.textDeclaredSelectionDecorations copy] ?: @[];
    copy.textMarkedRects = [source.textMarkedRects copy] ?: @[];
    copy.textCaretRect = source.textCaretRect;
    copy.textCaretIsDeclared = source.textCaretIsDeclared;
    copy.textCaretHidden = source.textCaretHidden;
    copy.textScrollbarRect = source.textScrollbarRect;
    copy.effectTarget = source.effectTarget;
    copy.backdropTarget = source.backdropTarget;
    if (session) {
        if (session.composableSceneCloneCount < UINT64_MAX) session.composableSceneCloneCount += 1;
        if (session.composableSceneNodeAllocationCount < UINT64_MAX) session.composableSceneNodeAllocationCount += 1;
    }
#ifdef CJGUI_INTERNAL_TESTING
    if (session) {
        CjguiRecordComposableSceneCloneLabel(session, source, index);
    }
#endif
    return copy;
}

static uint64_t CjguiComposableNodeIdAtIndex(CJGuiInternalSession *session, uint32_t nodeIndex) {
    if (!session || nodeIndex >= session.composableNodes.count) return 0;
    return session.composableNodes[nodeIndex].node.nodeId;
}

static int64_t CjguiComposableNodeResourceIdAtIndex(CJGuiInternalSession *session, uint32_t nodeIndex) {
    if (!session || nodeIndex >= session.composableNodes.count) return -1;
    return session.composableNodes[nodeIndex].node.resourceId;
}

static uint32_t CjguiComposableNodeKindAtIndex(CJGuiInternalSession *session, uint32_t nodeIndex) {
    if (!session || nodeIndex >= session.composableNodes.count) return 0;
    return session.composableNodes[nodeIndex].node.nodeKind;
}

static CJGuiInternalComposableDataTransferItem *CjguiComposableDataTransferItemForNode(
    CJGuiInternalSession *session, uint64_t nodeId, int64_t resourceId,
    uint32_t nodeKind, uint32_t role) {
    if (!session || session.destroyed || session.composableDataTransferVersion != session.composableSceneVersion) {
        return nil;
    }
    for (CJGuiInternalComposableDataTransferItem *candidate in session.composableDataTransferItems) {
        CjguiInternalRendererComposableDataTransferItem item = candidate.item;
        if (item.nodeId == nodeId && item.resourceId == resourceId && item.nodeKind == nodeKind &&
            item.projectionVersion == session.composableSceneVersion && item.role == role) {
            return candidate;
        }
    }
    return nil;
}

static NSPasteboardType CjguiPasteboardTypeForDataTransferFormat(NSString *format) {
    if ([format isEqualToString:@"text/plain"]) return NSPasteboardTypeString;
    if ([format isEqualToString:@"image/png"]) return NSPasteboardTypePNG;
    NSData *bytes = [format dataUsingEncoding:NSUTF8StringEncoding];
    if (!bytes || bytes.length == 0) return nil;
    // NSPasteboardType is a UTI, not an RFC 2046 MIME string.  Preserve the
    // complete declared identifier in a private, valid UTI rather than
    // casting `application/vnd…` directly (which AppKit rejects). Hex is
    // intentionally injective over the already bounded ASCII format value,
    // so two declared structured formats can never alias one pasteboard type.
    NSMutableString *type = [NSMutableString stringWithString:@"org.cangjie.cjgui.transfer.f"];
    const uint8_t *raw = bytes.bytes;
    for (NSUInteger index = 0; index < bytes.length; index++) {
        [type appendFormat:@"%02x", (unsigned int)raw[index]];
    }
    return (NSPasteboardType)type;
}


// This private type carries only copied source provenance alongside the
// declared public payload type. It is never decoded as a command, used as an
// authorization token, or retained past the FIFO event; the receiving owner
// still validates the immutable offer and its own CAS boundary.
static NSPasteboardType const kCjguiDataTransferSourceMetadataType = @"org.cangjie.cjgui.transfer-source";

static NSData *CjguiDataTransferSourceMetadata(CJGuiInternalComposableDataTransferItem *item) {
    if (!item || item.sourceKind.length == 0 || item.sourceIdentity.length == 0 || item.item.sourceId < 0) return nil;
    NSDictionary *metadata = @{ @"kind": item.sourceKind, @"identity": item.sourceIdentity,
                                @"id": @(item.item.sourceId), @"format": item.format ?: @"" };
    NSError *error = nil;
    return [NSPropertyListSerialization dataWithPropertyList:metadata format:NSPropertyListBinaryFormat_v1_0
                                                      options:0 error:&error];
}

static void CjguiReadDataTransferSourceMetadata(NSPasteboard *pasteboard, NSString *format,
                                                NSString **outKind, NSString **outIdentity, int64_t *outId) {
    if (outKind) *outKind = @"external_pasteboard";
    if (outIdentity) *outIdentity = @"macos";
    if (outId) *outId = 0;
    NSData *data = [pasteboard dataForType:kCjguiDataTransferSourceMetadataType];
    if (!data || data.length > 1024) return;
    NSError *error = nil;
    id value = [NSPropertyListSerialization propertyListWithData:data options:NSPropertyListImmutable format:nil error:&error];
    if (![value isKindOfClass:[NSDictionary class]]) return;
    NSDictionary *metadata = (NSDictionary *)value;
    NSString *kind = metadata[@"kind"];
    NSString *identity = metadata[@"identity"];
    NSNumber *identifier = metadata[@"id"];
    NSString *metadataFormat = metadata[@"format"];
    if (![kind isKindOfClass:[NSString class]] || ![identity isKindOfClass:[NSString class]] ||
        ![identifier isKindOfClass:[NSNumber class]] || ![metadataFormat isEqualToString:format] ||
        kind.length == 0 || kind.length > 128 || identity.length == 0 || identity.length > 256 ||
        identifier.longLongValue < 0) return;
    if (outKind) *outKind = [kind copy];
    if (outIdentity) *outIdentity = [identity copy];
    if (outId) *outId = identifier.longLongValue;
}

static BOOL CjguiTransferQueueCanRetain(NSUInteger incoming) {
    const NSUInteger budget = 2u * 1024u * 1024u;
    if (incoming > budget) return NO;
    NSUInteger retained = 0;
    for (NSUInteger index = 0; index < kCjguiSessionCapacity; index++) {
        CJGuiInternalSession *live = gCjguiSessions[index];
        if (!live || live.destroyed) continue;
        NSUInteger pumpedBytes = live.pumpedDataTransferBytes.length;
        if (pumpedBytes > budget - retained) return NO;
        retained += pumpedBytes;
        if (live.pendingFileTransferReservedBytes > budget - retained) return NO;
        retained += live.pendingFileTransferReservedBytes;
        for (CJGuiInternalQueuedInteraction *queued in live.pendingInteractions) {
            NSUInteger queuedBytes = queued.dataTransferBytes.length;
            if (queuedBytes > budget - retained) return NO;
            retained += queuedBytes;
        }
        if (retained > budget - incoming) return NO;
    }
    return YES;
}

static BOOL CjguiEnqueueComposableDataTransferInteraction(
    CJGuiInternalSession *session, uint32_t kind,
    CJGuiInternalComposableDataTransferItem *item, NSString *payload, NSData *binaryData,
    NSString *sourceKind, NSString *sourceIdentity, int64_t sourceId) {
    if (!session || !item || !payload) return NO;
    if (binaryData && !CjguiTransferQueueCanRetain(binaryData.length)) return NO;
    if (session.nextDataTransferEventId == UINT64_MAX) return NO;
    CJGuiInternalTransferDeliveryIdentity *deliveryIdentity =
        [[CJGuiInternalTransferDeliveryIdentity alloc] init];
    if (!deliveryIdentity) return NO;
    for (CJGuiInternalComposableSceneNode *node in session.composableNodes) {
        if (node.node.nodeId != item.item.nodeId || node.node.resourceId != item.item.resourceId ||
            node.node.nodeKind != item.item.nodeKind) continue;
        if (!CjguiEnqueueComposableInteraction(session, kind, node.index, payload, NSMakeRange(0, 0))) return NO;
        CJGuiInternalQueuedInteraction *queued = session.pendingInteractions.lastObject;
        if (!queued || queued.kind != kind || queued.nodeId != item.item.nodeId ||
            queued.projectionVersion != session.composableSceneVersion) return NO;
        queued.dataTransferFormat = [item.format copy] ?: @"";
        queued.dataTransferBytes = [binaryData copy];
        queued.bindingEpoch = item.item.bindingEpoch;
        queued.dataTransferEventId = ++session.nextDataTransferEventId;
        queued.transferDeliveryIdentity = deliveryIdentity;
        queued.expectedOwnerVersion = item.item.expectedOwnerVersion;
        queued.dataTransferSourceKind = [sourceKind copy] ?: @"external_pasteboard";
        queued.dataTransferSourceIdentity = [sourceIdentity copy] ?: @"macos";
        queued.dataTransferSourceId = sourceId >= 0 ? sourceId : 0;
#ifdef CJGUI_INTERNAL_TESTING
        CjguiUpdateTestDataTransferRetentionPeaks(session);
#endif
        return YES;
    }
    return NO;
}

static BOOL CjguiEnqueueFrozenFileTransferFact(CJGuiInternalSession *session,
    CjguiInternalRendererComposableDataTransferItem target, uint64_t eventId,
    uint32_t kind, uint32_t originKind, NSString *reason, NSData *bytes,
    CJGuiInternalTransferDeliveryIdentity *identity);

static CjguiInternalRendererStatus CjguiCopyComposableDataTransferItem(
    CJGuiInternalSession *session, CJGuiInternalComposableDataTransferItem *item) {
    if (!session || !item || item.item.role != CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_SOURCE) {
        return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    }
    BOOL png = [item.format isEqualToString:@"image/png"];
    NSData *payload = png ? item.binaryPayload : [item.payload dataUsingEncoding:NSUTF8StringEncoding];
    if (!payload || payload.length > item.item.maximumPayloadBytes) {
        return png && payload ? CJGUI_INTERNAL_RENDERER_PNG_PAYLOAD_TOO_LARGE :
            CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    }
#ifdef CJGUI_INTERNAL_TESTING
    session.testDataTransferSourceWriteCount += 1;
    session.testDataTransferSourceWriteBytes += (uint64_t)payload.length;
    session.testDataTransferSourceWritePeakBytes = MAX(session.testDataTransferSourceWritePeakBytes,
        (uint64_t)payload.length);
#endif
    NSPasteboardItem *pasteboardItem = [[NSPasteboardItem alloc] init];
    NSPasteboardType type = CjguiPasteboardTypeForDataTransferFormat(item.format);
    if (!pasteboardItem || !type) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    [pasteboardItem setData:payload forType:type];
    NSData *metadata = CjguiDataTransferSourceMetadata(item);
    if (metadata) [pasteboardItem setData:metadata forType:kCjguiDataTransferSourceMetadataType];
    NSPasteboard *pasteboard = NSPasteboard.generalPasteboard;
    if (![pasteboard clearContents] || ![pasteboard writeObjects:@[pasteboardItem]]) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    return CjguiEnqueueComposableDataTransferInteraction(session,
        CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_DATA_TRANSFER_COPY, item, item.payload, nil,
        item.sourceKind, item.sourceIdentity, item.item.sourceId)
        ? CJGUI_INTERNAL_RENDERER_OK : CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
}

#ifdef CJGUI_INTERNAL_TESTING
static int32_t gCjguiOpenFileReadDescriptors = 0;
static int32_t gCjguiAcquiredFileReadScopes = 0;
#endif
static void CjguiReadLocalPngFileAsync(CJGuiInternalFileTransferOperation *operation) {
    static dispatch_queue_t fileQueue;
    static dispatch_once_t once;
    dispatch_once(&once, ^{ fileQueue = dispatch_queue_create("cjgui.local-png-read", DISPATCH_QUEUE_SERIAL); });
    dispatch_async(fileQueue, ^{
        @autoreleasepool {
#ifdef CJGUI_INTERNAL_TESTING
            if (operation.testReadGate && !operation.testPauseAfterFirstRead) {
                dispatch_semaphore_signal(operation.testReadEntered);
                dispatch_semaphore_wait(operation.testReadGate, DISPATCH_TIME_FOREVER);
            }
#endif
            const uint64_t readStartedMicros = (uint64_t)(CACurrentMediaTime() * 1000000.0);
            uint64_t copyMicros = 0;
            NSURL *url = operation.url;
            NSString *failure = nil;
            NSData *result = nil;
            BOOL scoped = !operation.cancelled && [url startAccessingSecurityScopedResource];
#ifdef CJGUI_INTERNAL_TESTING
            if (scoped) __sync_add_and_fetch(&gCjguiAcquiredFileReadScopes, 1);
#endif
            const char *path = url.fileSystemRepresentation;
            struct stat pathBefore = {0}, before = {0}, after = {0}, pathState = {0};
            // A FIFO without a writer blocks O_RDONLY before fstat can reject
            // it, occupying the process-wide reader queue. Preflight avoids
            // opening known special files; O_NONBLOCK closes the replacement
            // race between lstat and open. The fd is checked again below.
            int preflight = !operation.cancelled && path ? lstat(path, &pathBefore) : -1;
            int fd = preflight == 0 && S_ISREG(pathBefore.st_mode) ?
                open(path, O_RDONLY | O_CLOEXEC | O_NOFOLLOW | O_NONBLOCK) : -1;
#ifdef CJGUI_INTERNAL_TESTING
            if (fd >= 0) __sync_add_and_fetch(&gCjguiOpenFileReadDescriptors, 1);
#endif
            struct statfs volume = {0};
            const NSUInteger limit = MIN((NSUInteger)operation.target.maximumPayloadBytes, 512u * 1024u);
            if (operation.cancelled) failure = @"file_cancelled";
            else if (preflight == 0 && !S_ISREG(pathBefore.st_mode)) failure = @"file_not_regular";
            else if (fd < 0) failure = @"file_open_failed";
            else if (fstat(fd, &before) != 0 || !S_ISREG(before.st_mode)) failure = @"file_not_regular";
            else if (before.st_dev != pathBefore.st_dev || before.st_ino != pathBefore.st_ino)
                failure = @"file_changed_during_read";
            else if (fstatfs(fd, &volume) != 0 || !(volume.f_flags & MNT_LOCAL)) failure = @"file_not_local";
            else if (before.st_size <= 0) failure = @"file_empty";
            else if ((uint64_t)before.st_size > limit) failure = @"file_payload_too_large";
            else if (operation.cancelled) failure = @"file_cancelled";
            else {
                const NSUInteger wanted = (NSUInteger)before.st_size;
                NSMutableData *buffer = [NSMutableData dataWithLength:wanted];
                if (!buffer) failure = @"file_read_allocation_failed";
                else {
                    NSUInteger offset = 0;
                    while (offset < wanted && !operation.cancelled) {
                        ssize_t count = read(fd, (uint8_t *)buffer.mutableBytes + offset,
                                             MIN((NSUInteger)16384, wanted - offset));
                        if (count < 0 && errno == EINTR) continue;
                        if (count <= 0) { failure = count == 0 ? @"file_short_read" : @"file_read_failed"; break; }
                        offset += (NSUInteger)count;
#ifdef CJGUI_INTERNAL_TESTING
                        if (operation.testPauseAfterFirstRead && operation.testReadGate) {
                            operation.testPauseAfterFirstRead = NO;
                            dispatch_semaphore_signal(operation.testReadEntered);
                            dispatch_semaphore_wait(operation.testReadGate, DISPATCH_TIME_FOREVER);
                        }
#endif
                    }
                    if (operation.cancelled) failure = @"file_cancelled";
                    if (!failure && (offset != wanted || fstat(fd, &after) != 0 ||
                        after.st_dev != before.st_dev || after.st_ino != before.st_ino ||
                        after.st_size != before.st_size ||
                        after.st_ctimespec.tv_sec != before.st_ctimespec.tv_sec ||
                        after.st_ctimespec.tv_nsec != before.st_ctimespec.tv_nsec ||
                        after.st_mtimespec.tv_sec != before.st_mtimespec.tv_sec ||
                        after.st_mtimespec.tv_nsec != before.st_mtimespec.tv_nsec ||
                        lstat(path, &pathState) != 0 || pathState.st_dev != before.st_dev ||
                        pathState.st_ino != before.st_ino || pathState.st_size != before.st_size ||
                        pathState.st_ctimespec.tv_sec != before.st_ctimespec.tv_sec ||
                        pathState.st_ctimespec.tv_nsec != before.st_ctimespec.tv_nsec))
                        failure = @"file_changed_during_read";
                    if (!failure) {
                        const uint64_t copyStartedMicros = (uint64_t)(CACurrentMediaTime() * 1000000.0);
                        result = [buffer copy];
                        copyMicros = (uint64_t)(CACurrentMediaTime() * 1000000.0) - copyStartedMicros;
                    }
                }
            }
            if (fd >= 0) {
                close(fd);
#ifdef CJGUI_INTERNAL_TESTING
                __sync_sub_and_fetch(&gCjguiOpenFileReadDescriptors, 1);
#endif
            }
            if (scoped) {
                [url stopAccessingSecurityScopedResource];
#ifdef CJGUI_INTERNAL_TESTING
                __sync_sub_and_fetch(&gCjguiAcquiredFileReadScopes, 1);
#endif
            }
            const uint64_t readMicros = (uint64_t)(CACurrentMediaTime() * 1000000.0) - readStartedMicros;
            NSData *bytes = result;
            NSString *reason = failure;
            dispatch_async(dispatch_get_main_queue(), ^{
                CJGuiInternalSession *live = CjguiLookupSession(operation.sessionToken);
                if (!live || live.destroyed || live.sessionGeneration != operation.sessionGeneration) return;
                NSUInteger index = [live.pendingFileTransfers indexOfObjectIdenticalTo:operation];
                if (index == NSNotFound) return;
                [live.pendingFileTransfers removeObjectAtIndex:index];
                NSUInteger reserved = MIN((NSUInteger)operation.target.maximumPayloadBytes, 512u * 1024u);
                live.pendingFileTransferReservedBytes -= MIN(reserved, live.pendingFileTransferReservedBytes);
                NSString *terminalReason = operation.cancelled ? @"file_cancelled" : reason;
                if (CjguiDataTransferTraceEnabled()) {
                    NSLog(@"cjgui: local png file event=%llu target=%llu epoch=%llu expected_owner=%lld bytes=%lu read_us=%llu copy_us=%llu result=%@",
                        (unsigned long long)operation.eventId,
                        (unsigned long long)operation.target.nodeId,
                        (unsigned long long)operation.target.bindingEpoch,
                        (long long)operation.target.expectedOwnerVersion,
                        (unsigned long)bytes.length,
                        (unsigned long long)readMicros,
                        (unsigned long long)copyMicros,
                        terminalReason ?: @"queued");
                }
                if (!terminalReason && !CjguiTransferQueueCanRetain(bytes.length)) {
                    terminalReason = @"png_queue_budget_exceeded";
                }
                if (terminalReason) {
                    (void)CjguiEnqueueFrozenFileTransferFact(live, operation.target, operation.eventId,
                        CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_FILE_TRANSFER_REJECTED,
                        operation.eventKind, terminalReason, nil, operation.deliveryIdentity);
                } else if (!CjguiEnqueueFrozenFileTransferFact(live, operation.target,
                    operation.eventId, operation.eventKind, operation.eventKind, @"", bytes,
                    operation.deliveryIdentity)) {
                    (void)CjguiEnqueueFrozenFileTransferFact(live, operation.target, operation.eventId,
                        CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_FILE_TRANSFER_REJECTED,
                        operation.eventKind, @"file_completion_queue_full", nil,
                        operation.deliveryIdentity);
                }
            });
        }
    });
}

static CjguiInternalRendererStatus CjguiBeginLocalPngFileTransfer(
    CJGuiInternalSession *session, CJGuiInternalComposableDataTransferItem *item,
    NSPasteboard *pasteboard, uint32_t kind) {
    if (!session || !item || session.nextDataTransferEventId == UINT64_MAX) {
        return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    }
    const uint64_t eventId = ++session.nextDataTransferEventId;
    CJGuiInternalTransferDeliveryIdentity *identity = [[CJGuiInternalTransferDeliveryIdentity alloc] init];
    if (!identity) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    CjguiInternalRendererComposableDataTransferItem target = item.item;
    NSString *reason = nil;
    NSURL *url = nil;
    if (pasteboard.pasteboardItems.count != 1) reason = @"file_multiple_items_unsupported";
    else {
        NSArray<NSURL *> *urls = [pasteboard readObjectsForClasses:@[[NSURL class]]
            options:@{NSPasteboardURLReadingFileURLsOnlyKey: @YES}];
        if (urls.count != 1 || ![urls[0] isKindOfClass:[NSURL class]] || !urls[0].isFileURL) {
            reason = @"file_url_unsupported";
        } else url = urls[0];
    }
    if (!reason && (session.pendingFileTransfers.count >= 4 ||
        session.pendingTransferTerminalFacts.count + session.pendingFileTransfers.count >= 64 ||
        !CjguiTransferQueueCanRetain(MIN((NSUInteger)target.maximumPayloadBytes, 512u * 1024u)))) {
        reason = @"file_read_budget_exceeded";
    }
    if (reason) {
        return CjguiEnqueueFrozenFileTransferFact(session, target, eventId,
            CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_FILE_TRANSFER_REJECTED, kind, reason, nil, identity)
            ? CJGUI_INTERNAL_RENDERER_OK : CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    }
    if (!CjguiEnqueueFrozenFileTransferFact(session, target, eventId,
        CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_FILE_TRANSFER_BEGIN, kind, @"", nil, identity)) {
        return CjguiEnqueueFrozenFileTransferFact(session, target, eventId,
            CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_FILE_TRANSFER_REJECTED,
            kind, @"file_begin_queue_full", nil, identity) ? CJGUI_INTERNAL_RENDERER_OK :
            CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    }
    CJGuiInternalFileTransferOperation *operation = [[CJGuiInternalFileTransferOperation alloc] init];
    if (!operation) {
        (void)CjguiEnqueueFrozenFileTransferFact(session, target, eventId,
            CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_FILE_TRANSFER_REJECTED,
            kind, @"file_read_allocation_failed", nil, identity);
        return CJGUI_INTERNAL_RENDERER_OK;
    }
    operation.url = url;
    operation.sessionToken = session.rendererSessionToken;
    operation.sessionGeneration = session.sessionGeneration;
    operation.eventId = eventId;
    operation.deliveryIdentity = identity;
    operation.eventKind = kind;
    operation.target = target;
#ifdef CJGUI_INTERNAL_TESTING
    if (session.testHoldNextFileRead) {
        session.testHoldNextFileRead = NO;
        operation.testReadGate = session.testNextFileReadGate;
        operation.testReadEntered = session.testNextFileReadEntered;
        operation.testPauseAfterFirstRead = session.testHoldNextFileAfterFirstRead;
        session.testHoldNextFileAfterFirstRead = NO;
        session.testNextFileReadGate = nil;
        session.testNextFileReadEntered = nil;
    }
#endif
    NSUInteger reserved = MIN((NSUInteger)target.maximumPayloadBytes, 512u * 1024u);
    session.pendingFileTransferReservedBytes += reserved;
    [session.pendingFileTransfers addObject:operation];
    CjguiReadLocalPngFileAsync(operation);
    return CJGUI_INTERNAL_RENDERER_OK;
}

static CjguiInternalRendererStatus CjguiReadComposableDataTransferItem(
    CJGuiInternalSession *session, CJGuiInternalComposableDataTransferItem *item,
    NSPasteboard *pasteboard, uint32_t kind) {
    if (!session || !item || !pasteboard || item.item.role != CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_TARGET) {
        return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    }
    NSPasteboardType type = CjguiPasteboardTypeForDataTransferFormat(item.format);
    BOOL png = [item.format isEqualToString:@"image/png"];
    if (png && item.item.localPngFileAllowed &&
        [pasteboard availableTypeFromArray:@[NSPasteboardTypeFileURL]]) {
        return CjguiBeginLocalPngFileTransfer(session, item, pasteboard, kind);
    }
    if (png && !CjguiTransferQueueCanRetain(item.item.maximumPayloadBytes)) {
        if (CjguiDataTransferTraceEnabled()) NSLog(@"cjgui: transfer read rejected reason=png_queue_budget_exceeded");
        return CJGUI_INTERNAL_RENDERER_PNG_QUEUE_BUDGET_EXCEEDED;
    }
    uint64_t fetchStarted = (uint64_t)(CACurrentMediaTime() * 1000000.0);
    NSData *data = [pasteboard dataForType:type];
    uint64_t fetchEnded = (uint64_t)(CACurrentMediaTime() * 1000000.0);
    if (!data || data.length > item.item.maximumPayloadBytes) {
        if (png && CjguiDataTransferTraceEnabled()) {
            NSLog(@"cjgui: transfer read rejected reason=%@ materialized_bytes=%lu fetch_us=%llu",
                  data ? @"png_payload_too_large" : @"png_unavailable", (unsigned long)data.length,
                  (unsigned long long)(fetchEnded >= fetchStarted ? fetchEnded - fetchStarted : 0));
        }
        return png && data ? CJGUI_INTERNAL_RENDERER_PNG_PAYLOAD_TOO_LARGE :
            CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    }
#ifdef CJGUI_INTERNAL_TESTING
    session.testDataTransferReadCount += 1;
    session.testDataTransferReadBytes += (uint64_t)data.length;
    session.testDataTransferReadPeakBytes = MAX(session.testDataTransferReadPeakBytes, (uint64_t)data.length);
#endif
    NSString *payload = png ? @"" : [[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];
    if (!payload) return CJGUI_INTERNAL_RENDERER_INVALID_UTF8;
#ifdef CJGUI_INTERNAL_TESTING
    session.testDataTransferParseCount += 1;
    session.testDataTransferParseBytes += (uint64_t)data.length;
    session.testDataTransferParsePeakBytes = MAX(session.testDataTransferParsePeakBytes, (uint64_t)data.length);
#endif
    NSString *sourceKind = nil;
    NSString *sourceIdentity = nil;
    int64_t sourceId = 0;
    CjguiReadDataTransferSourceMetadata(pasteboard, item.format, &sourceKind, &sourceIdentity, &sourceId);
    BOOL queued = CjguiEnqueueComposableDataTransferInteraction(session, kind, item, payload,
                                                                 png ? data : nil,
                                                                 sourceKind, sourceIdentity, sourceId);
    if (png && CjguiDataTransferTraceEnabled()) {
        uint64_t copiedAt = (uint64_t)(CACurrentMediaTime() * 1000000.0);
        NSLog(@"cjgui: transfer read bytes=%lu fetch_us=%llu queue_copy_us=%llu queued=%@",
              (unsigned long)data.length,
              (unsigned long long)(fetchEnded >= fetchStarted ? fetchEnded - fetchStarted : 0),
              (unsigned long long)(copiedAt >= fetchEnded ? copiedAt - fetchEnded : 0),
              queued ? @"true" : @"false");
    }
    return queued ? CJGUI_INTERNAL_RENDERER_OK : CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
}

static NSFont *CjguiComposableFont(CJGuiInternalComposableSceneNode *node);
static NSFont *CjguiComposableFontForStyle(double requested, uint32_t fontWeight, uint32_t fontFamily);

static uint32_t CjguiComposableClipConstraintCount(CjguiInternalRendererComposableNode value) {
    if (value.clipConstraintCount > 0 &&
        value.clipConstraintCount <= CJGUI_INTERNAL_COMPOSABLE_CLIP_CONSTRAINT_CAPACITY) return value.clipConstraintCount;
    return 1;
}

static void CjguiComposableClipConstraintAt(CjguiInternalRendererComposableNode value, uint32_t index,
                                             CGFloat *x, CGFloat *y, CGFloat *width, CGFloat *height, CGFloat *radius) {
    if (value.clipConstraintCount == 0 || value.clipConstraintCount > CJGUI_INTERNAL_COMPOSABLE_CLIP_CONSTRAINT_CAPACITY) {
        *x = value.clipX; *y = value.clipY; *width = value.clipWidth; *height = value.clipHeight;
        *radius = value.clipCornerRadius;
        return;
    }
    switch (index) {
        case 0: *x = value.clip0X; *y = value.clip0Y; *width = value.clip0Width; *height = value.clip0Height; *radius = value.clip0CornerRadius; break;
        case 1: *x = value.clip1X; *y = value.clip1Y; *width = value.clip1Width; *height = value.clip1Height; *radius = value.clip1CornerRadius; break;
        case 2: *x = value.clip2X; *y = value.clip2Y; *width = value.clip2Width; *height = value.clip2Height; *radius = value.clip2CornerRadius; break;
        default: *x = value.clip3X; *y = value.clip3Y; *width = value.clip3Width; *height = value.clip3Height; *radius = value.clip3CornerRadius; break;
    }
}

static void CjguiPopulateMetalClipChain(vector_float4 clips[CJGUI_INTERNAL_COMPOSABLE_CLIP_CONSTRAINT_CAPACITY],
                                        vector_float4 *radii, vector_float4 *count,
                                        CjguiInternalRendererComposableNode value) {
    uint32_t clipCount = CjguiComposableClipConstraintCount(value);
    *radii = (vector_float4){ 0, 0, 0, 0 };
    *count = (vector_float4){ (float)clipCount, 0, 0, 0 };
    for (uint32_t i = 0; i < CJGUI_INTERNAL_COMPOSABLE_CLIP_CONSTRAINT_CAPACITY; i++) {
        CGFloat x = 0, y = 0, width = 0, height = 0, radius = 0;
        if (i < clipCount) CjguiComposableClipConstraintAt(value, i, &x, &y, &width, &height, &radius);
        clips[i] = (vector_float4){ (float)x, (float)y, (float)MAX(0.0, width), (float)MAX(0.0, height) };
        if (i < clipCount) (*radii)[i] = (float)MIN(MAX(0.0, radius), MIN(MAX(0.0, width), MAX(0.0, height)) / 2.0);
    }
}

static void CjguiPopulateMetalVisualClipChain(vector_float4 clips[CJGUI_INTERNAL_COMPOSABLE_CLIP_CONSTRAINT_CAPACITY],
                                              vector_float4 *radii, vector_float4 *count,
                                              CJGuiInternalComposableSceneNode *node) {
    uint32_t clipCount = CjguiComposableClipConstraintCount(node.node);
    *radii = (vector_float4){ 0, 0, 0, 0 };
    *count = (vector_float4){ (float)clipCount, 0, 0, 0 };
    for (uint32_t i = 0; i < CJGUI_INTERNAL_COMPOSABLE_CLIP_CONSTRAINT_CAPACITY; i++) {
        CGFloat x = 0, y = 0, width = 0, height = 0, radius = 0;
        if (i < clipCount) CjguiComposableVisualClipConstraintAt(node, i, &x, &y, &width, &height, &radius);
        clips[i] = (vector_float4){ (float)x, (float)y, (float)MAX(0.0, width), (float)MAX(0.0, height) };
        if (i < clipCount) (*radii)[i] = (float)MIN(MAX(0.0, radius), MIN(MAX(0.0, width), MAX(0.0, height)) / 2.0);
    }
}

static void CjguiAppendMetalShape(NSMutableData *batch, CGFloat pointWidth, CGFloat pointHeight,
                                  CJGuiInternalComposableSceneNode *node,
                                  CjguiInternalRendererComposableNode value, NSRect visualRect,
                                  vector_float4 fill, vector_float4 border) {
    CGFloat x = NSMinX(visualRect), y = NSMinY(visualRect);
    CGFloat width = NSWidth(visualRect), height = NSHeight(visualRect);
    // A linear gradient replaces the fill even when the flat fill color is
    // fully transparent, so it participates in the emptiness test. With
    // gradientPresent == 0 this reduces exactly to the legacy condition.
    BOOL hasGradient = value.gradientPresent != 0 && value.gradientStopCount >= 2;
    if (!batch || width <= 0.0 || height <= 0.0 ||
        (fill.w <= 0.0 && border.w <= 0.0 && !hasGradient)) return;
    float left = -1.0f + (float)(2.0 * x / pointWidth);
    float right = -1.0f + (float)(2.0 * (x + width) / pointWidth);
    float top = 1.0f - (float)(2.0 * y / pointHeight);
    float bottom = 1.0f - (float)(2.0 * (y + height) / pointHeight);
    float radius = (float)MIN(MAX(0.0, value.cornerRadius), MIN(width, height) / 2.0);
    float stroke = (float)MIN(MAX(0.0, (CGFloat)value.borderWidth), MIN(width, height) / 2.0);
    vector_float2 gradientStart = { (float)value.gradientStartX, (float)value.gradientStartY };
    vector_float2 gradientEnd = { (float)value.gradientEndX, (float)value.gradientEndY };
    // Stop xyz is the sRGB color; a parallel vector carries the four alphas so
    // the payload stays vector-aligned with the Metal struct.
    vector_float4 gradientStop0 = { (float)value.gradientStop0Position, (float)value.gradientStop0Red,
        (float)value.gradientStop0Green, (float)value.gradientStop0Blue };
    vector_float4 gradientStop1 = { (float)value.gradientStop1Position, (float)value.gradientStop1Red,
        (float)value.gradientStop1Green, (float)value.gradientStop1Blue };
    vector_float4 gradientStop2 = { (float)value.gradientStop2Position, (float)value.gradientStop2Red,
        (float)value.gradientStop2Green, (float)value.gradientStop2Blue };
    vector_float4 gradientStop3 = { (float)value.gradientStop3Position, (float)value.gradientStop3Red,
        (float)value.gradientStop3Green, (float)value.gradientStop3Blue };
    vector_float4 gradientStopAlphas = { (float)value.gradientStop0Alpha, (float)value.gradientStop1Alpha,
        (float)value.gradientStop2Alpha, (float)value.gradientStop3Alpha };
    float gradientPresent = hasGradient ? 1.0f : 0.0f;
    float gradientStopCount = hasGradient ? (float)value.gradientStopCount : 0.0f;
    CJGuiInternalMetalVertex vertices[6] = {0};
    vector_float2 positions[6] = { { left, top }, { right, top }, { left, bottom }, { right, top }, { right, bottom }, { left, bottom } };
    vector_float2 scenePoints[6] = { { (float)x, (float)y }, { (float)(x + width), (float)y }, { (float)x, (float)(y + height) }, { (float)(x + width), (float)y }, { (float)(x + width), (float)(y + height) }, { (float)x, (float)(y + height) } };
    vector_float2 localPoints[6] = { { 0, 0 }, { (float)width, 0 }, { 0, (float)height }, { (float)width, 0 }, { (float)width, (float)height }, { 0, (float)height } };
    for (uint32_t i = 0; i < 6; i++) {
        vertices[i].position = positions[i]; vertices[i].scenePoint = scenePoints[i]; vertices[i].localPoint = localPoints[i];
        vertices[i].size = (vector_float2){ (float)width, (float)height };
        CjguiPopulateMetalVisualClipChain(vertices[i].clips, &vertices[i].clipRadii, &vertices[i].clipCount, node);
        vertices[i].cornerRadius = radius; vertices[i].borderWidth = stroke; vertices[i].fill = fill; vertices[i].border = border;
        vertices[i].passKind = 0.0f;
        vertices[i].gradientPresent = gradientPresent;
        vertices[i].gradientStopCount = gradientStopCount;
        vertices[i].gradientStart = gradientStart;
        vertices[i].gradientEnd = gradientEnd;
        vertices[i].gradientStop0 = gradientStop0;
        vertices[i].gradientStop1 = gradientStop1;
        vertices[i].gradientStop2 = gradientStop2;
        vertices[i].gradientStop3 = gradientStop3;
        vertices[i].gradientStopAlphas = gradientStopAlphas;
    }
    [batch appendBytes:vertices length:sizeof(vertices)];
}

// Appends one outer-shadow quad for a node that requested `shadowPresent`.
// The quad spans the union of the node bounds and the offset/expanded shadow
// shape pushed out by three blur radii, so the soft falloff is never clipped
// by the node's own rectangle. Only the inherited ancestor clip chain is
// applied: the fragment evaluates the clip SDF against `scenePoint` exactly
// like an ordinary shape. The shadow shape itself is expressed in local SDF
// space (`localPoint` relative to the expanded shape origin, `size` its
// extent), which keeps the fragment free of an extra origin uniform.
static void CjguiAppendMetalShadow(NSMutableData *batch, CGFloat pointWidth, CGFloat pointHeight,
                                   CJGuiInternalComposableSceneNode *node,
                                   CjguiInternalRendererComposableNode value) {
    if (!batch || value.shadowPresent == 0 || !(value.shadowAlpha > 0.0)) return;
    CGFloat width = value.width, height = value.height;
    if (width <= 0.0 || height <= 0.0) return;
    CGFloat blur = MIN(MAX(0.0, (CGFloat)value.shadowBlurRadius), 256.0);
    CGFloat spread = MIN(MAX(0.0, (CGFloat)value.shadowSpread), 128.0);
    // Shadow shape = node bounds translated by the offset, expanded by spread.
    NSRect visualRect = CjguiComposableVisualNodeRect(node);
    CGFloat shapeX = NSMinX(visualRect) + (CGFloat)value.shadowOffsetX - spread;
    CGFloat shapeY = NSMinY(visualRect) + (CGFloat)value.shadowOffsetY - spread;
    CGFloat shapeW = width + 2.0 * spread;
    CGFloat shapeH = height + 2.0 * spread;
    // Output range = shadow shape expanded by 3*blur, unioned with the node
    // bounds so the node's own pixels are always covered by the shadow quad
    // and the following fill can overwrite the shadow center.
    CGFloat expand = 3.0 * blur;
    CGFloat outX = MIN(NSMinX(visualRect), shapeX - expand);
    CGFloat outY = MIN(NSMinY(visualRect), shapeY - expand);
    CGFloat outRight = MAX(NSMaxX(visualRect), shapeX + shapeW + expand);
    CGFloat outBottom = MAX(NSMaxY(visualRect), shapeY + shapeH + expand);
    CGFloat outW = outRight - outX;
    CGFloat outH = outBottom - outY;
    if (outW <= 0.0 || outH <= 0.0) return;
    float radius = (float)MIN(MAX(0.0, value.cornerRadius), MIN(shapeW, shapeH) / 2.0);
    float left = -1.0f + (float)(2.0 * outX / pointWidth);
    float right = -1.0f + (float)(2.0 * (outX + outW) / pointWidth);
    float top = 1.0f - (float)(2.0 * outY / pointHeight);
    float bottom = 1.0f - (float)(2.0 * (outY + outH) / pointHeight);
    vector_float4 shadowColor = { (float)value.shadowRed, (float)value.shadowGreen,
        (float)value.shadowBlue, (float)value.shadowAlpha };
    CJGuiInternalMetalVertex vertices[6] = {0};
    vector_float2 positions[6] = { { left, top }, { right, top }, { left, bottom }, { right, top }, { right, bottom }, { left, bottom } };
    vector_float2 scenePoints[6] = { { (float)outX, (float)outY }, { (float)(outX + outW), (float)outY }, { (float)outX, (float)(outY + outH) },
        { (float)(outX + outW), (float)outY }, { (float)(outX + outW), (float)(outY + outH) }, { (float)outX, (float)(outY + outH) } };
    for (uint32_t i = 0; i < 6; i++) {
        vertices[i].position = positions[i]; vertices[i].scenePoint = scenePoints[i];
        // localPoint is relative to the shadow shape origin and size spans the
        // expanded shape, so the fragment SDF has no separate origin field.
        vertices[i].localPoint = (vector_float2){ scenePoints[i].x - (float)shapeX, scenePoints[i].y - (float)shapeY };
        vertices[i].size = (vector_float2){ (float)shapeW, (float)shapeH };
        CjguiPopulateMetalVisualClipChain(vertices[i].clips, &vertices[i].clipRadii, &vertices[i].clipCount, node);
        vertices[i].cornerRadius = radius;
        vertices[i].borderWidth = 0.0f;
        vertices[i].passKind = 1.0f;
        vertices[i].shadowBlurRadius = (float)blur;
        vertices[i].shadowColor = shadowColor;
    }
    [batch appendBytes:vertices length:sizeof(vertices)];
}

// Output range of one node's outer shadow in scene (flipped, top-left origin)
// coordinates: the node bounds unioned with the offset/spread shadow shape
// pushed out by three blur radii. This mirrors the quad extent built inside
// CjguiAppendMetalShadow so the paint gate below can never disagree with the
// geometry actually submitted. A shadow may extend past the node's own bounds;
// only the inherited ancestor clip chain limits it.
static NSRect CjguiComposableShadowOutputRect(CJGuiInternalComposableSceneNode *node) {
    CjguiInternalRendererComposableNode value = node.node;
    NSRect visualRect = CjguiComposableVisualNodeRect(node);
    CGFloat width = value.width, height = value.height;
    CGFloat blur = MIN(MAX(0.0, (CGFloat)value.shadowBlurRadius), 256.0);
    CGFloat spread = MIN(MAX(0.0, (CGFloat)value.shadowSpread), 128.0);
    CGFloat shapeX = NSMinX(visualRect) + (CGFloat)value.shadowOffsetX - spread;
    CGFloat shapeY = NSMinY(visualRect) + (CGFloat)value.shadowOffsetY - spread;
    CGFloat shapeW = width + 2.0 * spread;
    CGFloat shapeH = height + 2.0 * spread;
    CGFloat expand = 3.0 * blur;
    CGFloat outX = MIN(NSMinX(visualRect), shapeX - expand);
    CGFloat outY = MIN(NSMinY(visualRect), shapeY - expand);
    CGFloat outRight = MAX(NSMaxX(visualRect), shapeX + shapeW + expand);
    CGFloat outBottom = MAX(NSMaxY(visualRect), shapeY + shapeH + expand);
    return NSMakeRect(outX, outY, MAX(0.0, outRight - outX), MAX(0.0, outBottom - outY));
}

// Decides whether the shadow output range can survive the inherited ancestor
// clip chain. The chain INTERSECTS, so the visible region is the common
// intersection of every non-empty constraint and the shadow is submitted only
// when its range meets that common region. Requiring each constraint to meet
// the range individually is NOT equivalent: two disjoint clips can both meet a
// wide output while their common region does not, which would submit a quad the
// fragment then discards for every pixel. Rounded corners are ignored on
// purpose - this only decides whether to submit the quad, so a false positive
// merely adds a quad the fragment SDF discards, while a false negative would
// drop a genuinely visible shadow. The node's own bounds are never consulted,
// which is what lets a fully clipped-out body still paint its shadow.
static BOOL CjguiComposableShadowOutputIntersectsAncestorClip(CJGuiInternalComposableSceneNode *node,
                                                              NSRect shadowOutput) {
    if (NSIsEmptyRect(shadowOutput)) return NO;
    uint32_t clipCount = CjguiComposableClipConstraintCount(node.node);
    if (clipCount == 0) return NO;
    NSRect visibleRegion = NSMakeRect(0.0, 0.0, 0.0, 0.0);
    BOOL haveRegion = NO;
    for (uint32_t index = 0; index < clipCount; index++) {
        CGFloat x = 0, y = 0, width = 0, height = 0, radius = 0;
        CjguiComposableVisualClipConstraintAt(node, index, &x, &y, &width, &height, &radius);
        NSRect clipRect = NSMakeRect(x, y, MAX(0.0, width), MAX(0.0, height));
        if (NSIsEmptyRect(clipRect)) return NO;
        visibleRegion = haveRegion ? NSIntersectionRect(visibleRegion, clipRect) : clipRect;
        haveRegion = YES;
        if (NSIsEmptyRect(visibleRegion)) return NO;
    }
    return NSIntersectsRect(visibleRegion, shadowOutput);
}

// Final drawable cull for the shadow-only path: map the logical output range
// into drawable pixels with the same scale used by the body path and require a
// non-empty intersection with the render target.
static BOOL CjguiComposableShadowOutputIntersectsDrawable(NSRect shadowOutput,
                                                          CGFloat scaleX, CGFloat scaleY,
                                                          CGSize drawableSize) {
    if (NSIsEmptyRect(shadowOutput) || scaleX <= 0.0 || scaleY <= 0.0) return NO;
    CGFloat left = MAX(0.0, NSMinX(shadowOutput) * scaleX);
    CGFloat top = MAX(0.0, NSMinY(shadowOutput) * scaleY);
    CGFloat right = MIN((CGFloat)drawableSize.width, NSMaxX(shadowOutput) * scaleX);
    CGFloat bottom = MIN((CGFloat)drawableSize.height, NSMaxY(shadowOutput) * scaleY);
    return right > left && bottom > top;
}

static CjguiInternalComposableVectorPoint CjguiComposableVectorPoint(double x, double y) {
    return (CjguiInternalComposableVectorPoint){ x, y };
}

static CjguiInternalComposableVectorPoint CjguiComposableVectorAdd(CjguiInternalComposableVectorPoint left,
                                                                    CjguiInternalComposableVectorPoint right) {
    return CjguiComposableVectorPoint(left.x + right.x, left.y + right.y);
}

static CjguiInternalComposableVectorPoint CjguiComposableVectorSubtract(CjguiInternalComposableVectorPoint left,
                                                                         CjguiInternalComposableVectorPoint right) {
    return CjguiComposableVectorPoint(left.x - right.x, left.y - right.y);
}

static CjguiInternalComposableVectorPoint CjguiComposableVectorScale(CjguiInternalComposableVectorPoint point,
                                                                      double scalar) {
    return CjguiComposableVectorPoint(point.x * scalar, point.y * scalar);
}

static double CjguiComposableVectorLength(CjguiInternalComposableVectorPoint point) {
    return hypot(point.x, point.y);
}

static BOOL CjguiComposableVectorUnitDirection(CjguiInternalComposableVectorPoint start,
                                               CjguiInternalComposableVectorPoint end,
                                               CjguiInternalComposableVectorPoint *outDirection) {
    if (!outDirection) return NO;
    CjguiInternalComposableVectorPoint delta = CjguiComposableVectorSubtract(end, start);
    double length = CjguiComposableVectorLength(delta);
    if (!isfinite(length) || length <= CjguiComposableVectorEpsilon) return NO;
    *outDirection = CjguiComposableVectorScale(delta, 1.0 / length);
    return YES;
}

// The asynchronous reader never holds a scene node. Its immutable completion
// uses the identity captured at the AppKit callback, even if the accepted
// scene has since removed the target; Cangjie settles that stale receipt.
static BOOL CjguiEnqueueFrozenFileTransferFact(CJGuiInternalSession *session,
    CjguiInternalRendererComposableDataTransferItem target, uint64_t eventId,
    uint32_t kind, uint32_t originKind, NSString *reason, NSData *bytes,
    CJGuiInternalTransferDeliveryIdentity *identity) {
    if (!session || session.destroyed || eventId == 0) return NO;
    if (bytes && !CjguiTransferQueueCanRetain(bytes.length)) return NO;
    CJGuiInternalQueuedInteraction *queued = [[CJGuiInternalQueuedInteraction alloc]
        initWithKind:kind recordIndex:originKind selectionStart:0 selectionEnd:0
        formText:reason ?: @"" nodeId:target.nodeId projectionVersion:target.projectionVersion
        resourceId:target.resourceId nodeKind:target.nodeKind];
    if (!queued) return NO;
    queued.bindingEpoch = target.bindingEpoch;
    queued.expectedOwnerVersion = target.expectedOwnerVersion;
    queued.dataTransferEventId = eventId;
    queued.transferDeliveryIdentity = identity;
    queued.dataTransferFormat = @"image/png";
    queued.dataTransferBytes = bytes;
    queued.dataTransferSourceKind = @"local_file_url";
    queued.dataTransferSourceIdentity = @"macos";
    queued.dataTransferSourceId = 0;
    if (CjguiPendingInteractionOccupancy(session) < kCjguiPendingInteractionCapacity) {
        [session.pendingInteractions addObject:queued];
        CjguiOwnerPumpTicketNoteWork(session);
        return YES;
    }
    // Keep a fallback terminal slot for every admitted asynchronous read.
    // Immediate rejections may only consume the remaining slots, otherwise
    // a full interaction FIFO could strand a public reading receipt.
    NSUInteger reserved = MIN((NSUInteger)64, session.pendingFileTransfers.count);
    if (kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_FILE_TRANSFER_REJECTED &&
        session.pendingTransferTerminalFacts.count < 64 - reserved) {
        [session.pendingTransferTerminalFacts addObject:queued];
        CjguiOwnerPumpTicketNoteWork(session);
        return YES;
    }
    return NO;
}

static void CjguiAppendMetalVectorTriangle(NSMutableData *batch, CGFloat pointWidth, CGFloat pointHeight,
                                           CjguiInternalRendererComposableNode value,
                                           CjguiInternalComposableVectorGeometry geometry,
                                           CjguiInternalComposableVectorPoint first,
                                           CjguiInternalComposableVectorPoint second,
                                           CjguiInternalComposableVectorPoint third,
                                           vector_float4 fill) {
    if (!batch || fill.w <= 0.0 || geometry.viewBoxWidth <= 0.0 || geometry.viewBoxHeight <= 0.0 ||
        pointWidth <= 0.0 || pointHeight <= 0.0) return;
    CjguiInternalComposableVectorPoint local[3] = { first, second, third };
    CJGuiInternalMetalVertex vertices[3] = {0};
    for (uint32_t index = 0; index < 3; index++) {
        double sceneX = (double)value.x + local[index].x * (double)value.width / geometry.viewBoxWidth;
        double sceneY = (double)value.y + local[index].y * (double)value.height / geometry.viewBoxHeight;
        vertices[index].position = (vector_float2){ -1.0f + (float)(2.0 * sceneX / pointWidth),
            1.0f - (float)(2.0 * sceneY / pointHeight) };
        vertices[index].scenePoint = (vector_float2){ (float)sceneX, (float)sceneY };
        vertices[index].localPoint = (vector_float2){ (float)(sceneX - (double)value.x),
            (float)(sceneY - (double)value.y) };
        vertices[index].size = (vector_float2){ (float)value.width, (float)value.height };
        CjguiPopulateMetalClipChain(vertices[index].clips, &vertices[index].clipRadii, &vertices[index].clipCount, value);
        vertices[index].cornerRadius = 0.0f;
        vertices[index].borderWidth = 0.0f;
        vertices[index].isVectorShape = 1.0f;
        vertices[index].vectorPadding = 0.0f;
        vertices[index].fill = fill;
        vertices[index].border = (vector_float4){ 0, 0, 0, 0 };
    }
    [batch appendBytes:vertices length:sizeof(vertices)];
}

static void CjguiAppendMetalVectorQuad(NSMutableData *batch, CGFloat pointWidth, CGFloat pointHeight,
                                       CjguiInternalRendererComposableNode value,
                                       CjguiInternalComposableVectorGeometry geometry,
                                       CjguiInternalComposableVectorPoint first,
                                       CjguiInternalComposableVectorPoint second,
                                       CjguiInternalComposableVectorPoint third,
                                       CjguiInternalComposableVectorPoint fourth,
                                       vector_float4 fill) {
    CjguiAppendMetalVectorTriangle(batch, pointWidth, pointHeight, value, geometry, first, second, third, fill);
    CjguiAppendMetalVectorTriangle(batch, pointWidth, pointHeight, value, geometry, second, fourth, third, fill);
}

static void CjguiAppendMetalVectorStrokeSegment(NSMutableData *batch, CGFloat pointWidth, CGFloat pointHeight,
                                                CjguiInternalRendererComposableNode value,
                                                CjguiInternalComposableVectorGeometry geometry,
                                                CjguiInternalComposableVectorPoint start,
                                                CjguiInternalComposableVectorPoint end,
                                                double halfWidth, vector_float4 stroke) {
    CjguiInternalComposableVectorPoint direction = {0};
    if (stroke.w <= 0.0 || halfWidth <= 0.0 ||
        !CjguiComposableVectorUnitDirection(start, end, &direction)) return;
    CjguiInternalComposableVectorPoint normal = CjguiComposableVectorPoint(-direction.y * halfWidth,
                                                                             direction.x * halfWidth);
    CjguiAppendMetalVectorQuad(batch, pointWidth, pointHeight, value, geometry,
        CjguiComposableVectorAdd(start, normal), CjguiComposableVectorSubtract(start, normal),
        CjguiComposableVectorAdd(end, normal), CjguiComposableVectorSubtract(end, normal), stroke);
}

static BOOL CjguiComposableVectorLineIntersection(CjguiInternalComposableVectorPoint point,
                                                  CjguiInternalComposableVectorPoint direction,
                                                  CjguiInternalComposableVectorPoint otherPoint,
                                                  CjguiInternalComposableVectorPoint otherDirection,
                                                  CjguiInternalComposableVectorPoint *outIntersection) {
    if (!outIntersection) return NO;
    double denominator = direction.x * otherDirection.y - direction.y * otherDirection.x;
    if (fabs(denominator) <= CjguiComposableVectorEpsilon) return NO;
    CjguiInternalComposableVectorPoint difference = CjguiComposableVectorSubtract(otherPoint, point);
    double ratio = (difference.x * otherDirection.y - difference.y * otherDirection.x) / denominator;
    *outIntersection = CjguiComposableVectorAdd(point, CjguiComposableVectorScale(direction, ratio));
    return isfinite(outIntersection->x) && isfinite(outIntersection->y);
}

static void CjguiAppendMetalVectorJoin(NSMutableData *batch, CGFloat pointWidth, CGFloat pointHeight,
                                      CjguiInternalRendererComposableNode value,
                                      CjguiInternalComposableVectorGeometry geometry,
                                      CjguiInternalComposableVectorPoint previous,
                                      CjguiInternalComposableVectorPoint current,
                                      CjguiInternalComposableVectorPoint next,
                                      double halfWidth, vector_float4 stroke) {
    CjguiInternalComposableVectorPoint beforeDirection = {0};
    CjguiInternalComposableVectorPoint afterDirection = {0};
    if (stroke.w <= 0.0 || halfWidth <= 0.0 ||
        !CjguiComposableVectorUnitDirection(previous, current, &beforeDirection) ||
        !CjguiComposableVectorUnitDirection(current, next, &afterDirection)) return;
    double turn = beforeDirection.x * afterDirection.y - beforeDirection.y * afterDirection.x;
    if (fabs(turn) <= CjguiComposableVectorEpsilon) return;
    CjguiInternalComposableVectorPoint beforeNormal = CjguiComposableVectorPoint(-beforeDirection.y * halfWidth,
                                                                                   beforeDirection.x * halfWidth);
    CjguiInternalComposableVectorPoint afterNormal = CjguiComposableVectorPoint(-afterDirection.y * halfWidth,
                                                                                  afterDirection.x * halfWidth);
    CjguiInternalComposableVectorPoint outerBefore = turn > 0.0
        ? CjguiComposableVectorSubtract(current, beforeNormal) : CjguiComposableVectorAdd(current, beforeNormal);
    CjguiInternalComposableVectorPoint outerAfter = turn > 0.0
        ? CjguiComposableVectorSubtract(current, afterNormal) : CjguiComposableVectorAdd(current, afterNormal);
    if (geometry.join == CJGUI_INTERNAL_VECTOR_JOIN_ROUND) {
        double startAngle = atan2(outerBefore.y - current.y, outerBefore.x - current.x);
        double endAngle = atan2(outerAfter.y - current.y, outerAfter.x - current.x);
        double delta = endAngle - startAngle;
        if (turn > 0.0) {
            while (delta < 0.0) delta += 2.0 * M_PI;
        } else {
            while (delta > 0.0) delta -= 2.0 * M_PI;
        }
        uint32_t segments = (uint32_t)MIN(8.0, MAX(1.0, ceil(fabs(delta) / (M_PI / 6.0))));
        CjguiInternalComposableVectorPoint previousArc = outerBefore;
        for (uint32_t index = 1; index <= segments; index++) {
            double angle = startAngle + delta * (double)index / (double)segments;
            CjguiInternalComposableVectorPoint currentArc = CjguiComposableVectorPoint(
                current.x + cos(angle) * halfWidth, current.y + sin(angle) * halfWidth);
            CjguiAppendMetalVectorTriangle(batch, pointWidth, pointHeight, value, geometry,
                                            current, previousArc, currentArc, stroke);
            previousArc = currentArc;
        }
        return;
    }
    if (geometry.join == CJGUI_INTERNAL_VECTOR_JOIN_MITER) {
        CjguiInternalComposableVectorPoint miter = {0};
        if (CjguiComposableVectorLineIntersection(outerBefore, beforeDirection, outerAfter, afterDirection, &miter) &&
            CjguiComposableVectorLength(CjguiComposableVectorSubtract(miter, current)) <=
                halfWidth * CjguiComposableVectorMiterLimit) {
            CjguiAppendMetalVectorTriangle(batch, pointWidth, pointHeight, value, geometry,
                                            outerBefore, miter, outerAfter, stroke);
            return;
        }
    }
    CjguiAppendMetalVectorTriangle(batch, pointWidth, pointHeight, value, geometry,
                                    current, outerBefore, outerAfter, stroke);
}

static void CjguiAppendMetalVectorCap(NSMutableData *batch, CGFloat pointWidth, CGFloat pointHeight,
                                     CjguiInternalRendererComposableNode value,
                                     CjguiInternalComposableVectorGeometry geometry,
                                     CjguiInternalComposableVectorPoint center,
                                     CjguiInternalComposableVectorPoint direction,
                                     BOOL startCap, double halfWidth, vector_float4 stroke) {
    if (stroke.w <= 0.0 || halfWidth <= 0.0 || geometry.cap == CJGUI_INTERNAL_VECTOR_CAP_BUTT) return;
    CjguiInternalComposableVectorPoint outward = startCap ? CjguiComposableVectorScale(direction, -1.0) : direction;
    if (geometry.cap == CJGUI_INTERNAL_VECTOR_CAP_SQUARE) {
        CjguiAppendMetalVectorStrokeSegment(batch, pointWidth, pointHeight, value, geometry,
            CjguiComposableVectorAdd(center, CjguiComposableVectorScale(outward, halfWidth)), center, halfWidth, stroke);
        return;
    }
    double base = atan2(outward.y, outward.x);
    CjguiInternalComposableVectorPoint prior = CjguiComposableVectorPoint(
        center.x + cos(base - M_PI / 2.0) * halfWidth, center.y + sin(base - M_PI / 2.0) * halfWidth);
    for (uint32_t index = 1; index <= 8; index++) {
        double angle = base - M_PI / 2.0 + M_PI * (double)index / 8.0;
        CjguiInternalComposableVectorPoint next = CjguiComposableVectorPoint(
            center.x + cos(angle) * halfWidth, center.y + sin(angle) * halfWidth);
        CjguiAppendMetalVectorTriangle(batch, pointWidth, pointHeight, value, geometry, center, prior, next, stroke);
        prior = next;
    }
}

static void CjguiAppendMetalVectorOpenStroke(NSMutableData *batch, CGFloat pointWidth, CGFloat pointHeight,
                                             CjguiInternalRendererComposableNode value,
                                             CjguiInternalComposableVectorGeometry geometry,
                                             vector_float4 stroke) {
    if (geometry.pointCount < 2 || stroke.w <= 0.0 || geometry.strokeWidth <= 0.0) return;
    double halfWidth = geometry.strokeWidth / 2.0;
    for (uint32_t index = 0; index + 1 < geometry.pointCount; index++) {
        CjguiAppendMetalVectorStrokeSegment(batch, pointWidth, pointHeight, value, geometry,
            geometry.points[index], geometry.points[index + 1], halfWidth, stroke);
    }
    for (uint32_t index = 1; index + 1 < geometry.pointCount; index++) {
        CjguiAppendMetalVectorJoin(batch, pointWidth, pointHeight, value, geometry,
            geometry.points[index - 1], geometry.points[index], geometry.points[index + 1], halfWidth, stroke);
    }
    CjguiInternalComposableVectorPoint firstDirection = {0};
    CjguiInternalComposableVectorPoint lastDirection = {0};
    if (CjguiComposableVectorUnitDirection(geometry.points[0], geometry.points[1], &firstDirection)) {
        CjguiAppendMetalVectorCap(batch, pointWidth, pointHeight, value, geometry,
            geometry.points[0], firstDirection, YES, halfWidth, stroke);
    }
    if (CjguiComposableVectorUnitDirection(geometry.points[geometry.pointCount - 2],
                                           geometry.points[geometry.pointCount - 1], &lastDirection)) {
        CjguiAppendMetalVectorCap(batch, pointWidth, pointHeight, value, geometry,
            geometry.points[geometry.pointCount - 1], lastDirection, NO, halfWidth, stroke);
    }
}

static void CjguiAppendMetalVectorClosedStroke(NSMutableData *batch, CGFloat pointWidth, CGFloat pointHeight,
                                               CjguiInternalRendererComposableNode value,
                                               CjguiInternalComposableVectorGeometry geometry,
                                               const CjguiInternalComposableVectorPoint *points,
                                               uint32_t pointCount, vector_float4 stroke) {
    if (!points || pointCount < 3 || stroke.w <= 0.0 || geometry.strokeWidth <= 0.0) return;
    double halfWidth = geometry.strokeWidth / 2.0;
    for (uint32_t index = 0; index < pointCount; index++) {
        uint32_t next = index + 1 == pointCount ? 0 : index + 1;
        CjguiAppendMetalVectorStrokeSegment(batch, pointWidth, pointHeight, value, geometry,
            points[index], points[next], halfWidth, stroke);
    }
    for (uint32_t index = 0; index < pointCount; index++) {
        uint32_t previous = index == 0 ? pointCount - 1 : index - 1;
        uint32_t next = index + 1 == pointCount ? 0 : index + 1;
        CjguiAppendMetalVectorJoin(batch, pointWidth, pointHeight, value, geometry,
            points[previous], points[index], points[next], halfWidth, stroke);
    }
}

enum { CjguiPreparedVectorPaintFill = 1, CjguiPreparedVectorPaintStroke = 2 };

typedef struct CjguiInternalPreparedVectorTriangle {
    CjguiInternalComposableVectorPoint first;
    CjguiInternalComposableVectorPoint second;
    CjguiInternalComposableVectorPoint third;
    uint8_t paint;
} CjguiInternalPreparedVectorTriangle;

// Local vector topology is immutable between geometry changes. Store only a
// point and paint selector in the resident GPU buffer; layout, clip and paint
// values stay in a small per-draw uniform so a local paint/layout update does
// not rewrite every expanded triangle vertex.
typedef struct CJGuiInternalMetalVectorVertex {
    vector_float2 localPoint;
    uint32_t paint;
    uint32_t padding;
} CJGuiInternalMetalVectorVertex;

typedef struct CJGuiInternalMetalVectorUniform {
    vector_float4 nodeRect;
    // x/y are the declared vector viewBox; z/w are the current point extent.
    vector_float4 viewBoxAndPointExtent;
    vector_float4 clips[CJGUI_INTERNAL_COMPOSABLE_CLIP_CONSTRAINT_CAPACITY];
    vector_float4 clipRadii;
    vector_float4 clipCount;
    vector_float4 fill;
    vector_float4 stroke;
} CJGuiInternalMetalVectorUniform;

static void CjguiAppendPreparedVectorTriangle(NSMutableData *triangles,
                                              CjguiInternalComposableVectorPoint first,
                                              CjguiInternalComposableVectorPoint second,
                                              CjguiInternalComposableVectorPoint third,
                                              uint8_t paint) {
    if (!triangles) return;
    CjguiInternalPreparedVectorTriangle triangle = { first, second, third, paint };
    [triangles appendBytes:&triangle length:sizeof(triangle)];
}

static void CjguiAppendPreparedVectorQuad(NSMutableData *triangles,
                                          CjguiInternalComposableVectorPoint first,
                                          CjguiInternalComposableVectorPoint second,
                                          CjguiInternalComposableVectorPoint third,
                                          CjguiInternalComposableVectorPoint fourth,
                                          uint8_t paint) {
    CjguiAppendPreparedVectorTriangle(triangles, first, second, third, paint);
    CjguiAppendPreparedVectorTriangle(triangles, third, second, fourth, paint);
}

static void CjguiAppendPreparedVectorStrokeSegment(NSMutableData *triangles,
                                                    CjguiInternalComposableVectorPoint start,
                                                    CjguiInternalComposableVectorPoint end,
                                                    double halfWidth) {
    CjguiInternalComposableVectorPoint direction = {0};
    if (halfWidth <= 0.0 || !CjguiComposableVectorUnitDirection(start, end, &direction)) return;
    CjguiInternalComposableVectorPoint normal = CjguiComposableVectorPoint(-direction.y * halfWidth,
                                                                             direction.x * halfWidth);
    CjguiAppendPreparedVectorQuad(triangles, CjguiComposableVectorAdd(start, normal),
                                  CjguiComposableVectorSubtract(start, normal),
                                  CjguiComposableVectorAdd(end, normal),
                                  CjguiComposableVectorSubtract(end, normal), CjguiPreparedVectorPaintStroke);
}

static void CjguiAppendPreparedVectorJoin(NSMutableData *triangles,
                                          CjguiInternalComposableVectorGeometry geometry,
                                          CjguiInternalComposableVectorPoint previous,
                                          CjguiInternalComposableVectorPoint current,
                                          CjguiInternalComposableVectorPoint next,
                                          double halfWidth) {
    CjguiInternalComposableVectorPoint beforeDirection = {0}, afterDirection = {0};
    if (halfWidth <= 0.0 || !CjguiComposableVectorUnitDirection(previous, current, &beforeDirection) ||
        !CjguiComposableVectorUnitDirection(current, next, &afterDirection)) return;
    double turn = beforeDirection.x * afterDirection.y - beforeDirection.y * afterDirection.x;
    if (fabs(turn) <= CjguiComposableVectorEpsilon) return;
    CjguiInternalComposableVectorPoint beforeNormal = CjguiComposableVectorPoint(-beforeDirection.y * halfWidth,
                                                                                   beforeDirection.x * halfWidth);
    CjguiInternalComposableVectorPoint afterNormal = CjguiComposableVectorPoint(-afterDirection.y * halfWidth,
                                                                                  afterDirection.x * halfWidth);
    CjguiInternalComposableVectorPoint outerBefore = turn > 0.0
        ? CjguiComposableVectorSubtract(current, beforeNormal) : CjguiComposableVectorAdd(current, beforeNormal);
    CjguiInternalComposableVectorPoint outerAfter = turn > 0.0
        ? CjguiComposableVectorSubtract(current, afterNormal) : CjguiComposableVectorAdd(current, afterNormal);
    if (geometry.join == CJGUI_INTERNAL_VECTOR_JOIN_ROUND) {
        double startAngle = atan2(outerBefore.y - current.y, outerBefore.x - current.x);
        double endAngle = atan2(outerAfter.y - current.y, outerAfter.x - current.x);
        double delta = endAngle - startAngle;
        if (turn > 0.0) while (delta < 0.0) delta += 2.0 * M_PI;
        else while (delta > 0.0) delta -= 2.0 * M_PI;
        uint32_t segments = (uint32_t)MIN(8.0, MAX(1.0, ceil(fabs(delta) / (M_PI / 6.0))));
        CjguiInternalComposableVectorPoint previousArc = outerBefore;
        for (uint32_t index = 1; index <= segments; index++) {
            double angle = startAngle + delta * (double)index / (double)segments;
            CjguiInternalComposableVectorPoint currentArc = CjguiComposableVectorPoint(
                current.x + cos(angle) * halfWidth, current.y + sin(angle) * halfWidth);
            CjguiAppendPreparedVectorTriangle(triangles, current, previousArc, currentArc, CjguiPreparedVectorPaintStroke);
            previousArc = currentArc;
        }
        return;
    }
    if (geometry.join == CJGUI_INTERNAL_VECTOR_JOIN_MITER) {
        CjguiInternalComposableVectorPoint miter = {0};
        if (CjguiComposableVectorLineIntersection(outerBefore, beforeDirection, outerAfter, afterDirection, &miter) &&
            CjguiComposableVectorLength(CjguiComposableVectorSubtract(miter, current)) <= halfWidth * CjguiComposableVectorMiterLimit) {
            CjguiAppendPreparedVectorTriangle(triangles, outerBefore, miter, outerAfter, CjguiPreparedVectorPaintStroke);
            return;
        }
    }
    CjguiAppendPreparedVectorTriangle(triangles, current, outerBefore, outerAfter, CjguiPreparedVectorPaintStroke);
}

static void CjguiAppendPreparedVectorCap(NSMutableData *triangles,
                                         CjguiInternalComposableVectorGeometry geometry,
                                         CjguiInternalComposableVectorPoint center,
                                         CjguiInternalComposableVectorPoint direction,
                                         BOOL startCap, double halfWidth) {
    if (halfWidth <= 0.0 || geometry.cap == CJGUI_INTERNAL_VECTOR_CAP_BUTT) return;
    CjguiInternalComposableVectorPoint outward = startCap ? CjguiComposableVectorScale(direction, -1.0) : direction;
    if (geometry.cap == CJGUI_INTERNAL_VECTOR_CAP_SQUARE) {
        CjguiAppendPreparedVectorStrokeSegment(triangles,
            CjguiComposableVectorAdd(center, CjguiComposableVectorScale(outward, halfWidth)), center, halfWidth);
        return;
    }
    double base = atan2(outward.y, outward.x);
    CjguiInternalComposableVectorPoint prior = CjguiComposableVectorPoint(
        center.x + cos(base - M_PI / 2.0) * halfWidth, center.y + sin(base - M_PI / 2.0) * halfWidth);
    for (uint32_t index = 1; index <= 8; index++) {
        double angle = base - M_PI / 2.0 + M_PI * (double)index / 8.0;
        CjguiInternalComposableVectorPoint next = CjguiComposableVectorPoint(
            center.x + cos(angle) * halfWidth, center.y + sin(angle) * halfWidth);
        CjguiAppendPreparedVectorTriangle(triangles, center, prior, next, CjguiPreparedVectorPaintStroke);
        prior = next;
    }
}

static void CjguiAppendPreparedVectorOpenStroke(NSMutableData *triangles,
                                                CjguiInternalComposableVectorGeometry geometry) {
    if (geometry.pointCount < 2 || geometry.strokeWidth <= 0.0) return;
    double halfWidth = geometry.strokeWidth / 2.0;
    for (uint32_t index = 0; index + 1 < geometry.pointCount; index++)
        CjguiAppendPreparedVectorStrokeSegment(triangles, geometry.points[index], geometry.points[index + 1], halfWidth);
    for (uint32_t index = 1; index + 1 < geometry.pointCount; index++)
        CjguiAppendPreparedVectorJoin(triangles, geometry, geometry.points[index - 1], geometry.points[index], geometry.points[index + 1], halfWidth);
    CjguiInternalComposableVectorPoint firstDirection = {0}, lastDirection = {0};
    if (CjguiComposableVectorUnitDirection(geometry.points[0], geometry.points[1], &firstDirection))
        CjguiAppendPreparedVectorCap(triangles, geometry, geometry.points[0], firstDirection, YES, halfWidth);
    if (CjguiComposableVectorUnitDirection(geometry.points[geometry.pointCount - 2], geometry.points[geometry.pointCount - 1], &lastDirection))
        CjguiAppendPreparedVectorCap(triangles, geometry, geometry.points[geometry.pointCount - 1], lastDirection, NO, halfWidth);
}

static void CjguiAppendPreparedVectorClosedStroke(NSMutableData *triangles,
                                                  CjguiInternalComposableVectorGeometry geometry,
                                                  const CjguiInternalComposableVectorPoint *points,
                                                  uint32_t pointCount) {
    if (!points || pointCount < 3 || geometry.strokeWidth <= 0.0) return;
    double halfWidth = geometry.strokeWidth / 2.0;
    for (uint32_t index = 0; index < pointCount; index++) {
        uint32_t next = index + 1 == pointCount ? 0 : index + 1;
        CjguiAppendPreparedVectorStrokeSegment(triangles, points[index], points[next], halfWidth);
    }
    for (uint32_t index = 0; index < pointCount; index++) {
        uint32_t previous = index == 0 ? pointCount - 1 : index - 1;
        uint32_t next = index + 1 == pointCount ? 0 : index + 1;
        CjguiAppendPreparedVectorJoin(triangles, geometry, points[previous], points[index], points[next], halfWidth);
    }
}

static BOOL CjguiComposableVectorPreparationGeometryEquals(CjguiInternalComposableVectorGeometry first,
                                                            CjguiInternalComposableVectorGeometry second) {
    if (first.kind != second.kind || first.pointCount != second.pointCount || first.cap != second.cap || first.join != second.join ||
        first.viewBoxWidth != second.viewBoxWidth || first.viewBoxHeight != second.viewBoxHeight ||
        first.strokeWidth != second.strokeWidth || first.center.x != second.center.x || first.center.y != second.center.y ||
        first.radiusX != second.radiusX || first.radiusY != second.radiusY ||
        first.triangleIndexCount != second.triangleIndexCount) return NO;
    return memcmp(first.points, second.points, sizeof(CjguiInternalComposableVectorPoint) * first.pointCount) == 0 &&
        memcmp(first.triangleIndices, second.triangleIndices, first.triangleIndexCount) == 0;
}

static NSData *CjguiComposablePreparedVectorTrianglesForNode(CJGuiInternalMetalView *metalView,
                                                              CJGuiInternalComposableSceneNode *node) {
    if (!node || !node.hasVectorGeometry) return nil;
    CjguiInternalComposableVectorGeometry geometry = node.vectorGeometry;
    if (node.vectorPreparedTriangles && node.hasVectorPreparedGeometry &&
        CjguiComposableVectorPreparationGeometryEquals(node.vectorPreparedGeometry, geometry)) return node.vectorPreparedTriangles;
    NSMutableData *triangles = [NSMutableData data];
    if (!triangles) return nil;
    if (geometry.kind == CJGUI_INTERNAL_VECTOR_SIMPLE_POLYGON) {
        for (uint32_t index = 0; index + 2 < geometry.triangleIndexCount; index += 3) {
            uint8_t first = geometry.triangleIndices[index], second = geometry.triangleIndices[index + 1], third = geometry.triangleIndices[index + 2];
            if (first < geometry.pointCount && second < geometry.pointCount && third < geometry.pointCount)
                CjguiAppendPreparedVectorTriangle(triangles, geometry.points[first], geometry.points[second], geometry.points[third], CjguiPreparedVectorPaintFill);
        }
    } else if (geometry.kind == CJGUI_INTERNAL_VECTOR_ELLIPSE) {
        CjguiInternalComposableVectorPoint ring[CJGUI_INTERNAL_COMPOSABLE_VECTOR_ELLIPSE_SEGMENTS] = {0};
        for (uint32_t index = 0; index < CJGUI_INTERNAL_COMPOSABLE_VECTOR_ELLIPSE_SEGMENTS; index++) {
            double angle = 2.0 * M_PI * (double)index / (double)CJGUI_INTERNAL_COMPOSABLE_VECTOR_ELLIPSE_SEGMENTS;
            ring[index] = CjguiComposableVectorPoint(geometry.center.x + cos(angle) * geometry.radiusX,
                                                      geometry.center.y + sin(angle) * geometry.radiusY);
        }
        for (uint32_t index = 0; index < CJGUI_INTERNAL_COMPOSABLE_VECTOR_ELLIPSE_SEGMENTS; index++) {
            uint32_t next = index + 1 == CJGUI_INTERNAL_COMPOSABLE_VECTOR_ELLIPSE_SEGMENTS ? 0 : index + 1;
            CjguiAppendPreparedVectorTriangle(triangles, geometry.center, ring[index], ring[next], CjguiPreparedVectorPaintFill);
        }
        CjguiAppendPreparedVectorClosedStroke(triangles, geometry, ring, CJGUI_INTERNAL_COMPOSABLE_VECTOR_ELLIPSE_SEGMENTS);
    }
    if (geometry.kind == CJGUI_INTERNAL_VECTOR_LINE || geometry.kind == CJGUI_INTERNAL_VECTOR_POLYLINE)
        CjguiAppendPreparedVectorOpenStroke(triangles, geometry);
    else if (geometry.kind == CJGUI_INTERNAL_VECTOR_SIMPLE_POLYGON)
        CjguiAppendPreparedVectorClosedStroke(triangles, geometry, geometry.points, geometry.pointCount);
    node.vectorPreparedTriangles = triangles;
    // A new topology must never retain the prior topology's GPU allocation.
    // The old COW node is retained by an in-flight command buffer if needed.
    node.vectorPreparedVertexBuffer = nil;
    node.vectorPreparedVertexCount = 0;
    node.vectorPreparedVertexBytes = 0;
    node.vectorPreparedGeometry = geometry;
    node.hasVectorPreparedGeometry = YES;
#ifdef CJGUI_INTERNAL_TESTING
    if (metalView && metalView.testComposableVectorGeometryPreparationCount < UINT64_MAX)
        metalView.testComposableVectorGeometryPreparationCount += 1;
    if (metalView && triangles.length <= UINT64_MAX - metalView.testComposableVectorGeometryPreparedBytes)
        metalView.testComposableVectorGeometryPreparedBytes += triangles.length;
#endif
    return triangles;
}

static id<MTLBuffer> CjguiComposableVectorVertexBufferForNode(CJGuiInternalMetalView *metalView,
                                                               CJGuiInternalComposableSceneNode *node,
                                                               BOOL *outUploaded) {
    if (outUploaded) *outUploaded = NO;
    if (!metalView || !metalView.device || !node || !node.hasVectorGeometry) return nil;
    NSData *prepared = CjguiComposablePreparedVectorTrianglesForNode(metalView, node);
    if (!prepared || prepared.length % sizeof(CjguiInternalPreparedVectorTriangle) != 0) return nil;
    NSUInteger triangleCount = prepared.length / sizeof(CjguiInternalPreparedVectorTriangle);
    if (triangleCount == 0 || triangleCount > NSUIntegerMax / 3u) return nil;
    NSUInteger vertexCount = triangleCount * 3u;
    if (vertexCount > NSUIntegerMax / sizeof(CJGuiInternalMetalVectorVertex)) return nil;
    NSUInteger byteCount = vertexCount * sizeof(CJGuiInternalMetalVectorVertex);
    // Every currently supported geometry is bounded to twelve logical points
    // and 32 ellipse segments. Keep the native allocation cap explicit even
    // if future parser limits drift; the 1,024-node scene limit then bounds a
    // whole accepted scene to at most 16 MiB of resident vector buffers.
    if (byteCount == 0 || byteCount > 16u * 1024u) return nil;
    if (node.vectorPreparedVertexBuffer && node.vectorPreparedVertexCount == vertexCount &&
        node.vectorPreparedVertexBytes == byteCount) {
#ifdef CJGUI_INTERNAL_TESTING
        if (metalView.testComposableVectorBufferReuseCount < UINT32_MAX)
            metalView.testComposableVectorBufferReuseCount += 1;
#endif
        return node.vectorPreparedVertexBuffer;
    }
    NSMutableData *vertices = [NSMutableData dataWithLength:byteCount];
    if (!vertices) return nil;
    const CjguiInternalPreparedVectorTriangle *triangles = prepared.bytes;
    CJGuiInternalMetalVectorVertex *target = vertices.mutableBytes;
    for (NSUInteger index = 0; index < triangleCount; index++) {
        const CjguiInternalPreparedVectorTriangle triangle = triangles[index];
        const NSUInteger base = index * 3u;
        target[base] = (CJGuiInternalMetalVectorVertex){
            { (float)triangle.first.x, (float)triangle.first.y }, triangle.paint, 0 };
        target[base + 1u] = (CJGuiInternalMetalVectorVertex){
            { (float)triangle.second.x, (float)triangle.second.y }, triangle.paint, 0 };
        target[base + 2u] = (CJGuiInternalMetalVectorVertex){
            { (float)triangle.third.x, (float)triangle.third.y }, triangle.paint, 0 };
    }
    id<MTLBuffer> buffer = [metalView.device newBufferWithBytes:vertices.bytes length:byteCount
                                                         options:MTLResourceStorageModeShared];
    if (!buffer) return nil;
    node.vectorPreparedVertexBuffer = buffer;
    node.vectorPreparedVertexCount = vertexCount;
    node.vectorPreparedVertexBytes = byteCount;
#ifdef CJGUI_INTERNAL_TESTING
    if (metalView.testComposableVectorBufferUploadCount < UINT32_MAX)
        metalView.testComposableVectorBufferUploadCount += 1;
    metalView.testComposableVectorBufferUploadBytes = byteCount > UINT64_MAX - metalView.testComposableVectorBufferUploadBytes
        ? UINT64_MAX : metalView.testComposableVectorBufferUploadBytes + byteCount;
#endif
    if (outUploaded) *outUploaded = YES;
    return buffer;
}

// Decorations are regular scene rectangles with the text node's resolved
// clip chain. They deliberately do not become public nodes or textures:
// their sole owner is the active native input projection.
static void CjguiAppendMetalTextDecoration(NSMutableData *batch, CGFloat pointWidth, CGFloat pointHeight,
                                           CJGuiInternalComposableSceneNode *node, NSRect rect,
                                           vector_float4 fill) {
    if (NSIsEmptyRect(rect) || fill.w <= 0.0) return;
    CjguiInternalRendererComposableNode owner = node.node;
    CjguiInternalRendererComposableNode decoration = owner;
    decoration.x = (int64_t)floor(NSMinX(rect));
    decoration.y = (int64_t)floor(NSMinY(rect));
    decoration.width = (int64_t)ceil(NSWidth(rect));
    decoration.height = (int64_t)ceil(NSHeight(rect));
    decoration.cornerRadius = 0.0;
    decoration.borderWidth = 0.0;
    // Text decorations (selection, caret, scrollbar) are flat overlays and
    // must never inherit the owner's shadow or gradient.
    decoration.shadowPresent = 0;
    decoration.gradientPresent = 0;
    decoration.fillAlpha = fill.w;
    decoration.borderAlpha = 0.0;
    CjguiAppendMetalShape(batch, pointWidth, pointHeight, node, decoration, rect,
                          fill, (vector_float4){ 0, 0, 0, 0 });
}

static vector_float4 CjguiMetalColorFromNSColor(NSColor *color) {
    NSColor *srgb = [color colorUsingColorSpace:NSColorSpace.sRGBColorSpace];
    if (!srgb) return (vector_float4){ 0, 0, 0, 0 };
    return (vector_float4){ (float)srgb.redComponent, (float)srgb.greenComponent,
                             (float)srgb.blueComponent, (float)srgb.alphaComponent };
}

static NSString *CjguiComposableSceneShaderSource(void) {
        NSString *source = @"#include <metal_stdlib>\nusing namespace metal;\n"
            "struct Vertex { float2 position; float2 scenePoint; float2 localPoint; float2 size; float4 clips[4]; float4 clipRadii; float4 clipCount; float cornerRadius; float borderWidth; float isVectorShape; float vectorPadding; float4 fill; float4 border; float passKind; float shadowBlurRadius; float gradientPresent; float gradientStopCount; float2 gradientStart; float2 gradientEnd; float4 shadowColor; float4 gradientStop0; float4 gradientStop1; float4 gradientStop2; float4 gradientStop3; float4 gradientStopAlphas; };\n"
            "struct Out { float4 position [[position]]; float2 scenePoint; float2 localPoint; float2 size; float4 clip0; float4 clip1; float4 clip2; float4 clip3; float4 clipRadii; float4 clipCount; float cornerRadius; float borderWidth; float isVectorShape; float4 fill; float4 border; float passKind; float shadowBlurRadius; float gradientPresent; float gradientStopCount; float2 gradientStart; float2 gradientEnd; float4 shadowColor; float4 gradientStop0; float4 gradientStop1; float4 gradientStop2; float4 gradientStop3; float4 gradientStopAlphas; };\n"
            "float roundedDistance(float2 point, float2 origin, float2 size, float radius) { float r=min(max(radius,0.0),min(size.x,size.y)*0.5); float2 q=abs((point-origin)-size*0.5)-(size*0.5-r); return length(max(q,float2(0.0)))+min(max(q.x,q.y),0.0)-r; }\n"
            // Linear gradient in normalized node-local space: P in [0,1]^2,
            // t projected on the start->end axis, then piecewise sRGB lerp.
            "float4 cjgui_gradient_color(Out in) { float2 P=in.localPoint/max(in.size,float2(1e-6)); float2 dir=in.gradientEnd-in.gradientStart; float denom=max(dot(dir,dir),1e-6); float t=clamp(dot(P-in.gradientStart,dir)/denom,0.0,1.0); float4 c0=float4(in.gradientStop0.yzw,in.gradientStopAlphas.x); float4 c1=float4(in.gradientStop1.yzw,in.gradientStopAlphas.y); float4 c2=float4(in.gradientStop2.yzw,in.gradientStopAlphas.z); float4 c3=float4(in.gradientStop3.yzw,in.gradientStopAlphas.w); float4 r=mix(c0,c1,clamp((t-in.gradientStop0.x)/max(in.gradientStop1.x-in.gradientStop0.x,1e-6),0.0,1.0)); if (in.gradientStopCount>2.5 && t>=in.gradientStop1.x) r=mix(c1,c2,clamp((t-in.gradientStop1.x)/max(in.gradientStop2.x-in.gradientStop1.x,1e-6),0.0,1.0)); if (in.gradientStopCount>3.5 && t>=in.gradientStop2.x) r=mix(c2,c3,clamp((t-in.gradientStop2.x)/max(in.gradientStop3.x-in.gradientStop2.x,1e-6),0.0,1.0)); return r; }\n"
            "vertex Out cjgui_scene_vertex(uint i [[vertex_id]], const device Vertex *v [[buffer(0)]]) { Out o; o.position=float4(v[i].position,0,1); o.scenePoint=v[i].scenePoint; o.localPoint=v[i].localPoint; o.size=v[i].size; o.clip0=v[i].clips[0]; o.clip1=v[i].clips[1]; o.clip2=v[i].clips[2]; o.clip3=v[i].clips[3]; o.clipRadii=v[i].clipRadii; o.clipCount=v[i].clipCount; o.cornerRadius=v[i].cornerRadius; o.borderWidth=v[i].borderWidth; o.isVectorShape=v[i].isVectorShape; o.fill=v[i].fill; o.border=v[i].border; o.passKind=v[i].passKind; o.shadowBlurRadius=v[i].shadowBlurRadius; o.gradientPresent=v[i].gradientPresent; o.gradientStopCount=v[i].gradientStopCount; o.gradientStart=v[i].gradientStart; o.gradientEnd=v[i].gradientEnd; o.shadowColor=v[i].shadowColor; o.gradientStop0=v[i].gradientStop0; o.gradientStop1=v[i].gradientStop1; o.gradientStop2=v[i].gradientStop2; o.gradientStop3=v[i].gradientStop3; o.gradientStopAlphas=v[i].gradientStopAlphas; return o; }\n"
            // Clip chain first (shadows obey ancestor clips, never the node's own
            // rect). Shadow quads then evaluate a rounded-rect SDF in the expanded
            // shadow-shape space: the signed distance is clamped at zero so the
            // shadow shape interior (including any spread/offset area exposed
            // outside the node) stays at full shadow alpha, while the exterior
            // falls off with a Gaussian tail. Samples past 3*blur are discarded
            // early. Ordinary quads keep the legacy rounded fill/border path,
            // with the fill optionally replaced by a gradient.
            "fragment float4 cjgui_scene_fragment(Out in [[stage_in]]) { for(uint j=0;j<uint(in.clipCount.x);j++) { float4 clip=j==0?in.clip0:(j==1?in.clip1:(j==2?in.clip2:in.clip3)); if (roundedDistance(in.scenePoint,clip.xy,clip.zw,in.clipRadii[j])>0.0) discard_fragment(); } if (in.passKind>0.5) { float d=roundedDistance(in.localPoint,float2(0.0),in.size,in.cornerRadius); float blur=max(in.shadowBlurRadius,0.0); if (d>blur*3.0) discard_fragment(); float sigma=max(blur*0.5,0.5); float dd=max(d,0.0); return float4(in.shadowColor.rgb,in.shadowColor.a*exp(-(dd*dd)/(2.0*sigma*sigma))); } if (in.isVectorShape>0.5) return in.fill; float outer=roundedDistance(in.localPoint,float2(0.0),in.size,in.cornerRadius); if (outer>0.0) discard_fragment(); if (in.borderWidth>0.0 && in.border.a>0.0) { float2 innerSize=max(in.size-float2(in.borderWidth*2.0),float2(0.0)); float innerRadius=max(0.0,in.cornerRadius-in.borderWidth); float inner=roundedDistance(in.localPoint-float2(in.borderWidth),float2(0.0),innerSize,innerRadius); if (inner>0.0) return in.border; } if (in.gradientPresent>0.5 && in.gradientStopCount>1.5) return cjgui_gradient_color(in); return in.fill; }\n";

    return source;
}
static NSString *CjguiComposableImageShaderSource(void) {
    NSString *source = @"#include <metal_stdlib>\nusing namespace metal;\n"
        "struct Vertex { float2 position; float2 texCoord; float2 scenePoint; float4 clips[4]; float4 clipRadii; float4 clipCount; float4 nodeRect; float nodeCornerRadius; float paintAlpha; };\n"
        "struct Out { float4 position [[position]]; float2 texCoord; float2 point; float4 clip0; float4 clip1; float4 clip2; float4 clip3; float4 clipRadii; float4 clipCount; float4 nodeRect; float nodeCornerRadius; float paintAlpha; };\n"
        "float roundedDistance(float2 point, float2 origin, float2 size, float radius) { float r=min(max(radius,0.0),min(size.x,size.y)*0.5); float2 q=abs((point-origin)-size*0.5)-(size*0.5-r); return length(max(q,float2(0.0)))+min(max(q.x,q.y),0.0)-r; }\n"
        "vertex Out cjgui_image_vertex(uint i [[vertex_id]], const device Vertex *v [[buffer(0)]]) { Out o; o.position=float4(v[i].position,0,1); o.texCoord=v[i].texCoord; o.point=v[i].scenePoint; o.clip0=v[i].clips[0]; o.clip1=v[i].clips[1]; o.clip2=v[i].clips[2]; o.clip3=v[i].clips[3]; o.clipRadii=v[i].clipRadii; o.clipCount=v[i].clipCount; o.nodeRect=v[i].nodeRect; o.nodeCornerRadius=v[i].nodeCornerRadius; o.paintAlpha=v[i].paintAlpha; return o; }\n"
        // Normalized (non-premultiplied) texels: scale only alpha, never RGB, so
        // the blended colour is exactly the declared colour at the animated
        // opacity. Image quads pass paintAlpha=1 and are unchanged.
        "fragment float4 cjgui_image_fragment(Out in [[stage_in]], texture2d<float> image [[texture(0)]]) { for(uint j=0;j<uint(in.clipCount.x);j++) { float4 clip=j==0?in.clip0:(j==1?in.clip1:(j==2?in.clip2:in.clip3)); if (roundedDistance(in.point,clip.xy,clip.zw,in.clipRadii[j])>0.0) discard_fragment(); } if (roundedDistance(in.point,in.nodeRect.xy,in.nodeRect.zw,in.nodeCornerRadius)>0.0) discard_fragment(); constexpr sampler s(coord::normalized, address::clamp_to_edge, filter::linear); float4 c=image.sample(s, in.texCoord); c.a*=in.paintAlpha; return c; }\n";

    return source;
}

// Immutable Metal resources, keyed by the real device object and sample count.
// Four bounded sets cover the normal device's 1x/4x pipelines without retaining
// any window, input graph, candidate source or borrowed Cangjie storage.
@interface CjguiPreparedFramePipelines : NSObject
@property(nonatomic,strong) id<MTLDevice> device;
@property(nonatomic,assign) NSUInteger sampleCount;
@property(nonatomic,strong) id<MTLRenderPipelineState> scene;
@property(nonatomic,strong) id<MTLRenderPipelineState> image;
@property(nonatomic,assign) NSUInteger completed;
@property(nonatomic,assign) BOOL failed;
@property(nonatomic,assign) uint64_t startedNs;
@property(nonatomic,assign) uint64_t readyNs;
@end
@implementation CjguiPreparedFramePipelines
@end
static NSMutableArray<CjguiPreparedFramePipelines *> *gCjguiPreparedFramePipelines;

static void CjguiStartPreparedFramePipeline(CjguiPreparedFramePipelines *set,BOOL image,
    uint64_t session,uint64_t generation,uint64_t request,uint64_t turn) {
    uint32_t libraryPhase=image?385:383,pipelinePhase=image?386:384;
    NSString *source=image?CjguiComposableImageShaderSource():CjguiComposableSceneShaderSource();
    uint64_t librarySpan=CjguiOwnerTraceAppend(CJGUI_OWNER_TRACE_PHASE_BEGIN,session,turn,request,0,
        generation,libraryPhase,0);
    [set.device newLibraryWithSource:source options:nil completionHandler:^(id<MTLLibrary> library,NSError *error) {
        CjguiOwnerTraceAppend(CJGUI_OWNER_TRACE_PHASE_END,session,turn,request,0,generation,libraryPhase,librarySpan);
        if(!library || library.device!=set.device) {
            dispatch_async(dispatch_get_main_queue(),^{set.failed=YES;set.completed++;});
            return;
        }
        MTLRenderPipelineDescriptor *descriptor=[MTLRenderPipelineDescriptor new];
        descriptor.vertexFunction=[library newFunctionWithName:image?@"cjgui_image_vertex":@"cjgui_scene_vertex"];
        descriptor.fragmentFunction=[library newFunctionWithName:image?@"cjgui_image_fragment":@"cjgui_scene_fragment"];
        descriptor.colorAttachments[0].pixelFormat=MTLPixelFormatBGRA8Unorm;
        descriptor.rasterSampleCount=set.sampleCount;
        descriptor.colorAttachments[0].blendingEnabled=YES;
        descriptor.colorAttachments[0].sourceRGBBlendFactor=MTLBlendFactorSourceAlpha;
        descriptor.colorAttachments[0].destinationRGBBlendFactor=MTLBlendFactorOneMinusSourceAlpha;
        descriptor.colorAttachments[0].sourceAlphaBlendFactor=MTLBlendFactorOne;
        descriptor.colorAttachments[0].destinationAlphaBlendFactor=MTLBlendFactorOneMinusSourceAlpha;
        uint64_t pipelineSpan=CjguiOwnerTraceAppend(CJGUI_OWNER_TRACE_PHASE_BEGIN,session,turn,request,0,
            generation,pipelinePhase,0);
        [set.device newRenderPipelineStateWithDescriptor:descriptor completionHandler:^(id<MTLRenderPipelineState> pipeline,NSError *pipelineError) {
            CjguiOwnerTraceAppend(CJGUI_OWNER_TRACE_PHASE_END,session,turn,request,0,generation,pipelinePhase,pipelineSpan);
            // Only this main-queue publication mutates the bounded cache. A
            // late result can warm it, but cannot accept a retired scene/view.
            dispatch_async(dispatch_get_main_queue(),^{
                if(!pipeline || pipeline.device!=set.device)set.failed=YES;
                else if(image)set.image=pipeline;
                else set.scene=pipeline;
                set.completed++;
                if(set.completed==2) {
                    set.readyNs=cjgui_internal_renderer_owner_clock_ns();
                    fprintf(stderr,"CJGUI_FRAME_PIPELINES_READY device=%llu samples=%lu wall_ns=%llu failed=%d source=actual_async_metal\n",
                        (unsigned long long)set.device.registryID,(unsigned long)set.sampleCount,
                        (unsigned long long)(set.readyNs-set.startedNs),set.failed);
                }
            });
        }];
    }];
}

CjguiInternalRendererStatus cjgui_internal_renderer_prepare_frame_resources(uint64_t session,
    uint64_t request,uint64_t deadlineNs,uint32_t *outReady) {
    if(!outReady)return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    *outReady=0;
    return CjguiInstalledRangeRunOnMain(session,^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CJGuiInternalMetalView *view=ctx.view;
        if(!view || view.invalidated)return CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED;
        BOOL multisample=view.composableUsesMultisampling;
        if((multisample?view.composableMultisamplePipeline:view.composablePipeline) &&
            (multisample?view.composableMultisampleImagePipeline:view.composableImagePipeline)) {
            *outReady=1;return CJGUI_INTERNAL_RENDERER_OK;
        }
        if(deadlineNs && cjgui_internal_renderer_owner_clock_ns()>=deadlineNs)return CJGUI_INTERNAL_RENDERER_OK;
        CjguiPreparedFramePipelines *set=nil;
        NSUInteger sampleCount=multisample?4:1;
        for(CjguiPreparedFramePipelines *candidate in gCjguiPreparedFramePipelines) {
            if(candidate.device==view.device && candidate.sampleCount==sampleCount){set=candidate;break;}
        }
        if(!set) {
            if(gCjguiPreparedFramePipelines.count>=4)return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
            if(!gCjguiPreparedFramePipelines)gCjguiPreparedFramePipelines=[NSMutableArray array];
            set=[CjguiPreparedFramePipelines new];set.device=view.device;set.sampleCount=sampleCount;
            set.startedNs=cjgui_internal_renderer_owner_clock_ns();
            [gCjguiPreparedFramePipelines addObject:set];
            uint64_t generation=ctx.sessionGeneration;
            uint64_t turn=atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn,memory_order_acquire);
            CjguiStartPreparedFramePipeline(set,NO,session,generation,request,turn);
            CjguiStartPreparedFramePipeline(set,YES,session,generation,request,turn);
        }
        if(set.failed)return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        if(set.completed!=2)return CJGUI_INTERNAL_RENDERER_OK;
        if(!set.scene || !set.image || set.scene.device!=view.device || set.image.device!=view.device)
            return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        if(multisample) {view.composableMultisamplePipeline=set.scene;view.composableMultisampleImagePipeline=set.image;}
        else {view.composablePipeline=set.scene;view.composableImagePipeline=set.image;}
        *outReady=1;return CJGUI_INTERNAL_RENDERER_OK;
    });
}

static BOOL CjguiEnsureComposableImagePipeline(CJGuiInternalMetalView *metalView) {
    BOOL usesMultisampling = metalView.composableUsesMultisampling;
    id<MTLRenderPipelineState> existing = usesMultisampling
        ? metalView.composableMultisampleImagePipeline : metalView.composableImagePipeline;
    if (existing) return YES;
    NSError *error = nil;
    NSString *source = CjguiComposableImageShaderSource();
    id<MTLLibrary> library = [metalView.device newLibraryWithSource:source options:nil error:&error];
    if (!library) { NSLog(@"cjgui: composable image metal library failed %@", error); return NO; }
    MTLRenderPipelineDescriptor *descriptor = [[MTLRenderPipelineDescriptor alloc] init];
    descriptor.vertexFunction = [library newFunctionWithName:@"cjgui_image_vertex"];
    descriptor.fragmentFunction = [library newFunctionWithName:@"cjgui_image_fragment"];
    descriptor.colorAttachments[0].pixelFormat = MTLPixelFormatBGRA8Unorm;
    descriptor.sampleCount = usesMultisampling ? 4 : 1;
    descriptor.colorAttachments[0].blendingEnabled = YES;
    descriptor.colorAttachments[0].sourceRGBBlendFactor = MTLBlendFactorSourceAlpha;
    descriptor.colorAttachments[0].destinationRGBBlendFactor = MTLBlendFactorOneMinusSourceAlpha;
    descriptor.colorAttachments[0].sourceAlphaBlendFactor = MTLBlendFactorOne;
    descriptor.colorAttachments[0].destinationAlphaBlendFactor = MTLBlendFactorOneMinusSourceAlpha;
    id<MTLRenderPipelineState> pipeline = [metalView.device newRenderPipelineStateWithDescriptor:descriptor error:&error];
    if (!pipeline) { NSLog(@"cjgui: composable image pipeline failed %@", error); return NO; }
    if (usesMultisampling) metalView.composableMultisampleImagePipeline = pipeline;
    else metalView.composableImagePipeline = pipeline;
#ifdef CJGUI_INTERNAL_TESTING
    if (metalView.testComposablePipelineBuildCount < UINT64_MAX) metalView.testComposablePipelineBuildCount += 1;
#endif
    return YES;
}

static BOOL CjguiEnsureComposableVectorPipeline(CJGuiInternalMetalView *metalView) {
    if (!metalView || !metalView.device) return NO;
    BOOL usesMultisampling = metalView.composableUsesMultisampling;
    id<MTLRenderPipelineState> existing = usesMultisampling
        ? metalView.composableMultisampleVectorPipeline : metalView.composableVectorPipeline;
    if (existing) return YES;
    NSError *error = nil;
    NSString *source = @"#include <metal_stdlib>\nusing namespace metal;\n"
        "struct VectorVertex { float2 localPoint; uint paint; uint padding; };\n"
        "struct VectorUniform { float4 nodeRect; float4 viewBoxAndPointExtent; float4 clips[4]; float4 clipRadii; float4 clipCount; float4 fill; float4 stroke; };\n"
        "struct VectorOut { float4 position [[position]]; float2 point; float4 clip0; float4 clip1; float4 clip2; float4 clip3; float4 clipRadii; float4 clipCount; float4 color; };\n"
        "float roundedDistance(float2 point, float2 origin, float2 size, float radius) { float r=min(max(radius,0.0),min(size.x,size.y)*0.5); float2 q=abs((point-origin)-size*0.5)-(size*0.5-r); return length(max(q,float2(0.0)))+min(max(q.x,q.y),0.0)-r; }\n"
        "vertex VectorOut cjgui_vector_vertex(uint i [[vertex_id]], const device VectorVertex *v [[buffer(0)]], constant VectorUniform &u [[buffer(1)]]) { VectorOut o; float2 point=u.nodeRect.xy+(v[i].localPoint/u.viewBoxAndPointExtent.xy)*u.nodeRect.zw; o.position=float4(-1.0+2.0*point.x/u.viewBoxAndPointExtent.z,1.0-2.0*point.y/u.viewBoxAndPointExtent.w,0,1); o.point=point; o.clip0=u.clips[0]; o.clip1=u.clips[1]; o.clip2=u.clips[2]; o.clip3=u.clips[3]; o.clipRadii=u.clipRadii; o.clipCount=u.clipCount; o.color=v[i].paint==1u?u.fill:u.stroke; return o; }\n"
        "fragment float4 cjgui_vector_fragment(VectorOut in [[stage_in]]) { for(uint j=0;j<uint(in.clipCount.x);j++) { float4 clip=j==0?in.clip0:(j==1?in.clip1:(j==2?in.clip2:in.clip3)); if (roundedDistance(in.point,clip.xy,clip.zw,in.clipRadii[j])>0.0) discard_fragment(); } return in.color; }\n";
    id<MTLLibrary> library = [metalView.device newLibraryWithSource:source options:nil error:&error];
    if (!library) { NSLog(@"cjgui: composable vector metal library failed %@", error); return NO; }
    MTLRenderPipelineDescriptor *descriptor = [[MTLRenderPipelineDescriptor alloc] init];
    descriptor.vertexFunction = [library newFunctionWithName:@"cjgui_vector_vertex"];
    descriptor.fragmentFunction = [library newFunctionWithName:@"cjgui_vector_fragment"];
    descriptor.colorAttachments[0].pixelFormat = MTLPixelFormatBGRA8Unorm;
    descriptor.sampleCount = usesMultisampling ? 4 : 1;
    descriptor.colorAttachments[0].blendingEnabled = YES;
    descriptor.colorAttachments[0].sourceRGBBlendFactor = MTLBlendFactorSourceAlpha;
    descriptor.colorAttachments[0].destinationRGBBlendFactor = MTLBlendFactorOneMinusSourceAlpha;
    descriptor.colorAttachments[0].sourceAlphaBlendFactor = MTLBlendFactorOne;
    descriptor.colorAttachments[0].destinationAlphaBlendFactor = MTLBlendFactorOneMinusSourceAlpha;
    id<MTLRenderPipelineState> pipeline = [metalView.device newRenderPipelineStateWithDescriptor:descriptor error:&error];
    if (!pipeline) { NSLog(@"cjgui: composable vector metal pipeline failed %@", error); return NO; }
    if (usesMultisampling) metalView.composableMultisampleVectorPipeline = pipeline;
    else metalView.composableVectorPipeline = pipeline;
#ifdef CJGUI_INTERNAL_TESTING
    if (metalView.testComposablePipelineBuildCount < UINT64_MAX) metalView.testComposablePipelineBuildCount += 1;
#endif
    return YES;
}

static BOOL CjguiEncodeMetalVectorShape(id<MTLRenderCommandEncoder> encoder,
                                        CGFloat pointWidth, CGFloat pointHeight,
                                        CJGuiInternalMetalView *metalView,
                                        CJGuiInternalComposableSceneNode *node) {
    if (!encoder || !metalView || !node || !node.hasVectorGeometry || pointWidth <= 0.0 || pointHeight <= 0.0) return NO;
    CjguiInternalComposableVectorGeometry geometry = node.vectorGeometry;
    if (geometry.viewBoxWidth <= 0.0 || geometry.viewBoxHeight <= 0.0) return NO;
    if (geometry.fillAlpha <= 0.0 && geometry.strokeAlpha <= 0.0) return YES;
    if (!CjguiEnsureComposableVectorPipeline(metalView)) return NO;
    BOOL uploaded = NO;
    id<MTLBuffer> buffer = CjguiComposableVectorVertexBufferForNode(metalView, node, &uploaded);
    if (!buffer || node.vectorPreparedVertexCount == 0) return NO;
    CjguiInternalRendererComposableNode value = node.node;
    CJGuiInternalMetalVectorUniform uniform = {0};
    NSRect visualRect = CjguiComposableVisualNodeRect(node);
    uniform.nodeRect = (vector_float4){ (float)NSMinX(visualRect), (float)NSMinY(visualRect),
                                        (float)value.width, (float)value.height };
    uniform.viewBoxAndPointExtent = (vector_float4){ (float)geometry.viewBoxWidth, (float)geometry.viewBoxHeight,
                                                      (float)pointWidth, (float)pointHeight };
    CjguiPopulateMetalVisualClipChain(uniform.clips, &uniform.clipRadii, &uniform.clipCount, node);
    uniform.fill = (vector_float4){ (float)geometry.fillRed, (float)geometry.fillGreen,
                                    (float)geometry.fillBlue, (float)geometry.fillAlpha };
    uniform.stroke = (vector_float4){ (float)geometry.strokeRed, (float)geometry.strokeGreen,
                                      (float)geometry.strokeBlue, (float)geometry.strokeAlpha };
    id<MTLRenderPipelineState> pipeline = metalView.composableUsesMultisampling
        ? metalView.composableMultisampleVectorPipeline : metalView.composableVectorPipeline;
    if (!pipeline) return NO;
    [encoder setRenderPipelineState:pipeline];
    [encoder setVertexBuffer:buffer offset:0 atIndex:0];
    [encoder setVertexBytes:&uniform length:sizeof(uniform) atIndex:1];
    [encoder drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:node.vectorPreparedVertexCount];
#ifdef CJGUI_INTERNAL_TESTING
    if (metalView.testComposableVectorDrawCount < UINT32_MAX)
        metalView.testComposableVectorDrawCount += 1;
#endif
    (void)uploaded;
    return YES;
}

static void CjguiEncodeMetalTexture(id<MTLRenderCommandEncoder> encoder, CGFloat pointWidth, CGFloat pointHeight,
                                    CGFloat x, CGFloat y, CGFloat width, CGFloat height, id<MTLTexture> texture,
                                    CJGuiInternalComposableSceneNode *node, BOOL appKitBitmapRows,
                                    float paintAlpha) {
    if (!texture || width <= 0.0 || height <= 0.0) return;
    CjguiInternalRendererComposableNode value = node.node;
    x += (CGFloat)node.geometry.translateX;
    y += (CGFloat)node.geometry.translateY;
    float left = -1.0f + (float)(2.0 * x / pointWidth);
    float right = -1.0f + (float)(2.0 * (x + width) / pointWidth);
    float top = 1.0f - (float)(2.0 * y / pointHeight);
    float bottom = 1.0f - (float)(2.0 * (y + height) / pointHeight);
    CJGuiInternalMetalTextureVertex vertices[6] = {0};
    vector_float2 positions[6] = { { left, top }, { right, top }, { left, bottom }, { right, top }, { right, bottom }, { left, bottom } };
    // CGBitmapContext's first byte row is the opposite vertical origin from
    // the normalized rows consumed by this Metal texture sampler. AppKit text
    // is rasterized into that raw BGRA memory, while decoded image resources
    // already use Metal's expected row orientation. Keep the distinction at
    // the sole texture-encoding boundary so neither TextKit nor image loading
    // gains a second coordinate model.
    float textureTop = appKitBitmapRows ? 1.0f : 0.0f;
    float textureBottom = appKitBitmapRows ? 0.0f : 1.0f;
    vector_float2 texCoords[6] = { { 0, textureTop }, { 1, textureTop }, { 0, textureBottom },
                                   { 1, textureTop }, { 1, textureBottom }, { 0, textureBottom } };
    vector_float2 scenePoints[6] = { { (float)x, (float)y }, { (float)(x + width), (float)y }, { (float)x, (float)(y + height) }, { (float)(x + width), (float)y }, { (float)(x + width), (float)(y + height) }, { (float)x, (float)(y + height) } };
    for (uint32_t i = 0; i < 6; i++) {
        vertices[i].position = positions[i]; vertices[i].texCoord = texCoords[i]; vertices[i].scenePoint = scenePoints[i];
        CjguiPopulateMetalVisualClipChain(vertices[i].clips, &vertices[i].clipRadii, &vertices[i].clipCount, node);
        NSRect visual = CjguiComposableVisualNodeRect(node);
        vertices[i].nodeRect = (vector_float4){ (float)NSMinX(visual), (float)NSMinY(visual),
                                                (float)value.width, (float)value.height };
        vertices[i].nodeCornerRadius = (float)MIN(MAX(0.0, value.cornerRadius), MIN((CGFloat)value.width, (CGFloat)value.height) / 2.0);
        vertices[i].paintAlpha = paintAlpha;
    }
    [encoder setVertexBytes:vertices length:sizeof(vertices) atIndex:0];
    [encoder setFragmentTexture:texture atIndex:0];
    [encoder drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:6];
}

static NSString *CjguiComposableGpuTextValueWithActiveValue(CJGuiInternalComposableSceneNode *node,
                                                             NSString *activeValue) {
    if (!node) return @"";
    NSString *value = activeValue ?: node.value ?: @"";
    uint32_t kind = node.node.nodeKind;
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) return value;
    // A tab page title is a LABEL. Its value carries the page key that Cangjie
    // resolves the activation against, so painting "label value" would put a
    // machine key on screen next to the human title.
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE) return node.label ?: @"";
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT) {
        NSString *mark = [value isEqualToString:@"true"] ? @"☑" : @"☐";
        return node.label.length > 0 ? [NSString stringWithFormat:@"%@ %@", mark, node.label] : mark;
    }
    // Buttons carry their visible action in both projection fields: label is
    // the semantic name and value remains the ordinary display value.  Paint
    // it once when those fields agree, without changing either the accessible
    // label/value pair or distinct form-control label/value rendering.
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BUTTON && node.label.length > 0 &&
        [node.label isEqualToString:value]) return value;
    return node.label.length > 0 ? [NSString stringWithFormat:@"%@ %@", node.label, value] : value;
}

static NSString *CjguiComposableGpuTextValue(CJGuiInternalComposableSceneNode *node) {
    return CjguiComposableGpuTextValueWithActiveValue(node, nil);
}

// The composable node kinds whose visible text is owned by the framework:
// admission, scene text-resource accounting, encoding, CPU-overlay exclusion and
// readback classification all ask THIS predicate. A tab page title belongs here
// with the buttons: it is an actionable control that carries a scoped identity
// and an accessible label, so leaving it out made the title reachable by
// pointer/AX/keyboard while never painting its own text.
//
// The active-TextKit paths (active-input refresh, decoration restore and
// focus-loss preparation) must NOT ask this predicate: those paths need a caret,
// selection and marked text, and a title has none. They ask
// `CjguiComposableNodeIsTextInput` instead, so a focused title cannot reach a
// focus-loss reraster that is charged outside the scene text-budget check.
static BOOL CjguiComposableNodeHasGpuText(uint32_t kind) {
    return kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BUTTON ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT_INPUT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_INTEGER_INPUT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT;
}

// Bound an ordinary composable text candidate before full TextKit shaping,
// focused layout or raster preparation. A range-backed editor normally sends
// a smaller viewport, but direct consumers must receive the same refusal.
enum { CjguiComposableLayoutMaxUtf8Bytes = 262144, CjguiComposableLayoutMaxParagraphBytes = 131072 };
static BOOL CjguiComposableTextWithinLayoutBudget(const char *value) {
    if (!value) return YES;
    size_t length = strnlen(value, CjguiComposableLayoutMaxUtf8Bytes + 1u);
    if (length > CjguiComposableLayoutMaxUtf8Bytes) return NO;
    size_t paragraphBytes = 0;
    for (size_t index = 0; index < length; index++) {
        if (value[index] == '\n' || value[index] == '\r') {
            paragraphBytes = 0;
        } else if (++paragraphBytes > CjguiComposableLayoutMaxParagraphBytes) {
            return NO;
        }
    }
    return YES;
}

// A plain text label and a tab page title draw their own single line inside the
// declared rect, so both use the tight label inset. Inputs and buttons keep the
// larger control-chrome inset. Measurement and both raster paths must agree.
static BOOL CjguiComposableNodeUsesLabelTextInset(uint32_t kind) {
    return kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE;
}

// The rect the empty-text layout preparation would use. An empty result is the
// named "no preparable geometry" state for a text node (zero-sized or thinner
// than the text inset): it is NOT a change, so the caller must not clone and
// retry next refresh.
static BOOL CjguiComposableEmptyTextLayoutRect(CJGuiInternalComposableSceneNode *node, NSRect *outRect) {
    if (!node) return NO;
    NSRect bounds = NSMakeRect(0.0, 0.0, (CGFloat)node.node.width, (CGFloat)node.node.height);
    CGFloat verticalInset = CjguiComposableNodeUsesLabelTextInset(node.node.nodeKind) ? 2.0 : 6.0;
    NSRect textRect = NSInsetRect(bounds, 7.0, verticalInset);
    if (outRect) *outRect = textRect;
    return !NSIsEmptyRect(textRect) && textRect.size.width > 0 && textRect.size.height > 0;
}

// A text texture is only a projection of the pixels that can reach the
// drawable in this scene.  Keep its logical rectangle in scene coordinates:
// the encoder can then place the tile without changing TextKit/NSString
// layout coordinates, while the allocation is bounded by the resolved clip.
static NSRect CjguiComposableTextTextureRectForNodeWithText(CJGuiInternalComposableSceneNode *node,
                                                             NSString *displayText) {
    if (!node) return NSZeroRect;
    CjguiInternalRendererComposableNode value = node.node;
    NSRect nodeRect = NSMakeRect((CGFloat)value.x, (CGFloat)value.y,
                                 MAX(0.0, (CGFloat)value.width), MAX(0.0, (CGFloat)value.height));
    NSRect clipRect = NSMakeRect((CGFloat)value.clipX, (CGFloat)value.clipY,
                                 MAX(0.0, (CGFloat)value.clipWidth), MAX(0.0, (CGFloat)value.clipHeight));
    // Extent measurement can only shrink this raw node rectangle. If the raw
    // translated bounds cannot reach the visual clip, skip the expensive
    // measurement and return the same empty GPU coverage immediately.
    NSRect visualClip = CjguiComposableVisualClipBounds(node);
    if (node.geometry.clipCount == 0) visualClip = clipRect;
    NSRect rawVisualBody = NSOffsetRect(nodeRect, (CGFloat)node.geometry.translateX,
                                       (CGFloat)node.geometry.translateY);
    if (NSIsEmptyRect(NSIntersectionRect(rawVisualBody, visualClip))) return NSZeroRect;
    if (value.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT &&
        NSWidth(nodeRect) > 14.0 && NSHeight(nodeRect) > 4.0) {
        NSString *text = displayText ?: CjguiComposableGpuTextValue(node);
        if (text.length == 0) return NSZeroRect;
        CGFloat insetY = CjguiComposableNodeUsesLabelTextInset(value.nodeKind) ? 2.0 : 6.0;
        NSRect drawRect = NSInsetRect(nodeRect, 7.0, insetY);
        BOOL sameMeasure = node.textMeasureValid &&
            node.textMeasuredWidth == NSWidth(drawRect) &&
            node.textMeasuredFontSize == value.fontSize &&
            node.textMeasuredFontWeight == value.fontWeight &&
            node.textMeasuredFontFamily == value.fontFamily &&
            node.textMeasuredNodeKind == value.nodeKind &&
            [node.textMeasuredSource isEqualToString:text];
        NSSize measuredExtent = node.textMeasuredExtent;
        if (!sameMeasure) {
            NSMutableParagraphStyle *paragraph = [[NSMutableParagraphStyle alloc] init];
            paragraph.lineBreakStrategy = NSLineBreakStrategyPushOut;
            // Prose wraps by word on both pixel and extent paths. Ideographs
            // still break per character; translation never changes this rule.
            paragraph.lineBreakMode = value.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT
                ? NSLineBreakByWordWrapping : NSLineBreakByTruncatingTail;
            NSDictionary *attributes = @{NSFontAttributeName: CjguiComposableFont(node),
                                         NSParagraphStyleAttributeName: paragraph};
            NSRect measured = [text boundingRectWithSize:NSMakeSize(NSWidth(drawRect), CGFLOAT_MAX / 4.0)
                                                 options:NSStringDrawingUsesLineFragmentOrigin | NSStringDrawingUsesFontLeading
                                              attributes:attributes];
#ifdef CJGUI_INTERNAL_TESTING
            node.testTextExtentMeasurementCount += 1;
#endif
            measuredExtent = measured.size;
            // This memo is derived, never a text owner or GPU resource. A
            // failed candidate may leave it on a shared accepted node without
            // changing pixels, geometry, focus, or any accepted version.
            node.textMeasuredSource = text;
            node.textMeasuredWidth = NSWidth(drawRect);
            node.textMeasuredFontSize = value.fontSize;
            node.textMeasuredFontWeight = value.fontWeight;
            node.textMeasuredFontFamily = value.fontFamily;
            node.textMeasuredNodeKind = value.nodeKind;
            node.textMeasuredExtent = measuredExtent;
            node.textMeasureValid = YES;
        }
        // Glyph antialiasing and fallback font overhang need a small guard band.
        // The measurement uses precisely the same font, paragraph rule and
        // original draw width as the raster path; it never changes wrapping.
        CGFloat drawnWidth = MIN(NSWidth(drawRect), MAX(1.0, ceil(measuredExtent.width) + 2.0));
        CGFloat drawnHeight = MIN(NSHeight(drawRect), MAX(1.0, ceil(measuredExtent.height) + 2.0));
        nodeRect = NSIntersectionRect(nodeRect,
            NSMakeRect(NSMinX(drawRect) - 1.0, NSMinY(drawRect) - 1.0,
                       drawnWidth + 2.0, drawnHeight + 2.0));
    }
    // Coverage is a projection of the accepted visual clip into the node's
    // unchanged layout space. A moving clip owner and a moving node are
    // separate transforms; subtract only the node's cumulative translation.
    // Recompute after extent measurement has shrunk nodeRect so clips outside
    // the measured coverage cannot become a guard-only raster sliver.
    NSRect visualBody = NSOffsetRect(nodeRect, (CGFloat)node.geometry.translateX,
                                    (CGFloat)node.geometry.translateY);
    NSRect visible = NSIntersectionRect(visualBody, visualClip);
    if (NSIsEmptyRect(visible)) return NSZeroRect;
    NSRect layoutVisible = NSOffsetRect(visible, -(CGFloat)node.geometry.translateX,
                                       -(CGFloat)node.geometry.translateY);
    // Finite glyph/AA guard around the visible region. Tile selection snaps
    // this range to a stable node-local grid; the Metal clip stays exact.
    return NSIntersectionRect(nodeRect, NSInsetRect(layoutVisible, -2.0, -2.0));
}

static NSRect CjguiComposableTextTextureRectForNode(CJGuiInternalComposableSceneNode *node) {
    return CjguiComposableTextTextureRectForNodeWithText(node, nil);
}

// The rectangular texture allocation is only a conservative intersection;
// its pixels are still rasterized through every rounded ancestor clip. Keep a
// canonical copy of that chain in each text-resource key so a radius-only
// projection update cannot reuse stale pixels from the same rectangle.
static NSString *CjguiComposableTextClipSignature(CJGuiInternalComposableSceneNode *node) {
    (void)node;
    // Ancestor clips, including rounded corners, are applied by the visual
    // shader. No moving ancestor clip is baked into a body tile.
    return @"visual_shader_clip_tile_v2";
}

// The key must cover EVERYTHING that changes the rasterized pixels. Style runs
// are part of that: a run-only change (an inline-code tint, a caret mark, a
// newly bold span) left the key identical and reused a stale texture, so the
// window kept painting the previous appearance.
// A tagged selection background is a scene decoration. It does not change a
// glyph pixel or TextKit layout and must not evict the immutable body tiles.
static NSString *CjguiComposableRasterStyleSignature(NSString *signature) {
    if (signature.length == 0) return @"";
    NSMutableArray<NSString *> *raster = [NSMutableArray array];
    for (NSString *entry in [signature componentsSeparatedByString:@";"]) {
        NSArray<NSString *> *fields = [entry componentsSeparatedByString:@":"];
        if (fields.count == 15 && ([fields[14] isEqualToString:@"1"] ||
            [fields[14] isEqualToString:@"2"])) continue;
        [raster addObject:entry];
    }
    return [raster componentsJoinedByString:@";"];
}

static NSString *CjguiComposableTextTextureKey(CJGuiInternalComposableSceneNode *node, CGFloat scaleX, CGFloat scaleY,
                                               NSString *displayText, NSRect textureRect) {
    if (!node) return @"";
    (void)textureRect;
    CjguiInternalRendererComposableNode value = node.node;
    // The node's dynamic text alpha is deliberately NOT part of the key: it is
    // applied as a per-draw multiplier on the cached glyph texture, so an
    // opacity animation never re-prepares TextKit or re-rasterizes. The static
    // colour channels DO participate, so a real colour change still invalidates.
    NSString *key = [NSString stringWithFormat:@"tile_v2:%u:%lld:%lld:%0.3f:%0.3f:%0.3f:%u:%u:%0.4f:%0.4f:%0.4f:%@:%@:%@",
            value.nodeKind, value.width, value.height,
            scaleX, scaleY, value.fontSize, value.fontWeight, value.fontFamily,
            value.textRed, value.textGreen, value.textBlue,
            displayText ?: @"", CjguiComposableTextClipSignature(node),
            value.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT
                ? CjguiComposableRasterStyleSignature(node.styleRunsSignature) : (node.styleRunsSignature ?: @"")];
    return key;
}

static BOOL CjguiAttributedTextRasterAttributesEqual(NSAttributedString *left,
                                                       NSAttributedString *right) {
    if (!left || !right || left.length != right.length || ![left.string isEqualToString:right.string]) return NO;
    NSUInteger cursor = 0;
    while (cursor < left.length) {
        NSRange leftRange = NSMakeRange(0, 0), rightRange = NSMakeRange(0, 0);
        NSDictionary *leftAttributes = [left attributesAtIndex:cursor effectiveRange:&leftRange];
        NSDictionary *rightAttributes = [right attributesAtIndex:cursor effectiveRange:&rightRange];
        if (![leftAttributes isEqualToDictionary:rightAttributes]) return NO;
        NSUInteger next = MIN(NSMaxRange(leftRange), NSMaxRange(rightRange));
        if (next <= cursor) return NO;
        // Attribute values alone are insufficient: the drawing source also
        // records the effective run boundaries, including NSOriginalFont.
        if (NSMaxRange(leftRange) != NSMaxRange(rightRange)) return NO;
        cursor = next;
    }
    return YES;
}

static BOOL CjguiCheckedComposableTextTextureBytes(CGFloat logicalWidth, CGFloat logicalHeight,
                                                    CGFloat scaleX, CGFloat scaleY,
                                                    NSUInteger *outWidth, NSUInteger *outHeight,
                                                    NSUInteger *outBytesPerRow, uint64_t *outBytes) {
    if (!outWidth || !outHeight || !outBytesPerRow || !outBytes || logicalWidth <= 0.0 || logicalHeight <= 0.0 ||
        !isfinite(scaleX) || !isfinite(scaleY) || scaleX <= 0.0 || scaleY <= 0.0) return NO;
    CGFloat scaledWidth = ceil(logicalWidth * scaleX), scaledHeight = ceil(logicalHeight * scaleY);
    if (!isfinite(scaledWidth) || !isfinite(scaledHeight) || scaledWidth < 1.0 || scaledHeight < 1.0 ||
        scaledWidth > CjguiComposableTextTextureDimensionCapacity || scaledHeight > CjguiComposableTextTextureDimensionCapacity ||
        scaledWidth > (CGFloat)NSUIntegerMax || scaledHeight > (CGFloat)NSUIntegerMax) return NO;
    NSUInteger width = (NSUInteger)scaledWidth, height = (NSUInteger)scaledHeight;
    if (width > NSUIntegerMax / 4u) return NO;
    NSUInteger bytesPerRow = width * 4u;
    if (height > NSUIntegerMax / bytesPerRow) return NO;
    NSUInteger bytes = bytesPerRow * height;
    if (bytes > CjguiComposableTextTexturePerNodeByteCapacity) return NO;
    *outWidth = width; *outHeight = height; *outBytesPerRow = bytesPerRow; *outBytes = bytes;
    return YES;
}

// Work in integer logical points so adjacent tiles share an exact edge at
// both supported display scales. The last tile may be smaller. Each returned
// rect is independently admitted by the old 8 MiB allocation check; the sum
// is charged to the 24 MiB accepted scene before any texture is created.
static NSRect CjguiComposableTextNodeLayoutRect(CJGuiInternalComposableSceneNode *node) {
    CjguiInternalRendererComposableNode value = node.node;
    return NSMakeRect((CGFloat)value.x, (CGFloat)value.y,
                      MAX(0.0, (CGFloat)value.width), MAX(0.0, (CGFloat)value.height));
}

static NSArray<NSValue *> *CjguiPlanComposableTextTiles(NSRect visibleRect, NSRect nodeRect,
                                                        CGFloat scale, uint64_t *outBytes) {
    if (outBytes) *outBytes = 0;
    if (NSIsEmptyRect(visibleRect) || NSIsEmptyRect(nodeRect) ||
        !isfinite(scale) || scale <= 0.0) return nil;
    NSRect coverage = NSIntersectionRect(visibleRect, nodeRect);
    if (NSIsEmptyRect(coverage)) return nil;
    // Fixed grid in node-local logical points. A changed clip or a fractional
    // translation changes which cells are requested, never a retained cell's
    // raster coordinates. Each cell is under the old 8 MiB allocation cap.
    CGFloat tileWidth = MIN(512.0, floor(CjguiComposableTextTextureDimensionCapacity / scale));
    CGFloat tileHeight = MIN(256.0, floor(CjguiComposableTextTexturePerNodeByteCapacity /
                                               (tileWidth * scale * scale * 4.0)));
    if (tileWidth < 1.0 || tileHeight < 1.0) return nil;
    NSInteger firstColumn = (NSInteger)floor((NSMinX(coverage) - NSMinX(nodeRect)) / tileWidth);
    NSInteger lastColumn = (NSInteger)ceil((NSMaxX(coverage) - NSMinX(nodeRect)) / tileWidth);
    NSInteger firstRow = (NSInteger)floor((NSMinY(coverage) - NSMinY(nodeRect)) / tileHeight);
    NSInteger lastRow = (NSInteger)ceil((NSMaxY(coverage) - NSMinY(nodeRect)) / tileHeight);
    if (lastColumn <= firstColumn || lastRow <= firstRow ||
        lastColumn - firstColumn > 64 || lastRow - firstRow > 64 ||
        (lastColumn - firstColumn) * (lastRow - firstRow) > 64) return nil;
    NSMutableArray<NSValue *> *tiles = [NSMutableArray array];
    uint64_t total = 0;
    for (NSInteger column = firstColumn; column < lastColumn; column++) {
        for (NSInteger row = firstRow; row < lastRow; row++) {
            NSRect tile = NSIntersectionRect(nodeRect, NSMakeRect(
                NSMinX(nodeRect) + column * tileWidth,
                NSMinY(nodeRect) + row * tileHeight, tileWidth, tileHeight));
            NSUInteger checkedWidth = 0, checkedHeight = 0, rowBytes = 0;
            uint64_t bytes = 0;
            if (NSIsEmptyRect(tile) || !CjguiCheckedComposableTextTextureBytes(
                                                        NSWidth(tile), NSHeight(tile), scale, scale,
                                                        &checkedWidth, &checkedHeight, &rowBytes, &bytes) ||
                bytes > CjguiComposableTextTextureByteCapacity - total || tiles.count >= 64) return nil;
            [tiles addObject:[NSValue valueWithRect:tile]];
            total += bytes;
        }
    }
    if (outBytes) *outBytes = total;
    return tiles;
}

static NSRect CjguiComposableTextTileUnion(NSArray<NSValue *> *tiles) {
    NSRect result = NSZeroRect;
    for (NSValue *tile in tiles)
        result = NSIsEmptyRect(result) ? tile.rectValue : NSUnionRect(result, tile.rectValue);
    return result;
}

static id<MTLTexture> CjguiComposableFindTextTileByLocalRect(CJGuiInternalComposableSceneNode *node,
    NSRect requested, CGFloat scale) {
    if (!node) return nil;
    NSRect localRequested = NSOffsetRect(requested, -(CGFloat)node.node.x, -(CGFloat)node.node.y);
    NSUInteger count = node.textTileTextures.count > 0 ? node.textTileTextures.count : (node.textTexture ? 1 : 0);
    for (NSUInteger index = 0; index < count; index++) {
        NSRect oldRect = node.textTileRects.count > 0 ? node.textTileRects[index].rectValue : node.textTextureRect;
        if (!NSEqualRects(localRequested, NSOffsetRect(oldRect,
                -node.textTileLayoutOrigin.x, -node.textTileLayoutOrigin.y))) continue;
        id<MTLTexture> retained = node.textTileTextures.count > 0 ? node.textTileTextures[index] : node.textTexture;
        NSUInteger width = 0, height = 0, rowBytes = 0;
        uint64_t bytes = 0;
        if (retained && CjguiCheckedComposableTextTextureBytes(NSWidth(requested), NSHeight(requested),
                scale, scale, &width, &height, &rowBytes, &bytes) &&
            retained.width == width && retained.height == height) return retained;
    }
    return nil;
}

static id<MTLTexture> CjguiComposableRetainedTextTile(CJGuiInternalComposableSceneNode *node,
    NSString *key, NSRect requested, CGFloat scale) {
    return [node.textTextureCacheKey isEqualToString:key]
        ? CjguiComposableFindTextTileByLocalRect(node, requested, scale) : nil;
}

static BOOL CjguiComposableTextTilesAlreadyCovered(CJGuiInternalComposableSceneNode *node,
    NSString *key, NSArray<NSValue *> *tiles, CGFloat scale) {
    NSUInteger oldCount = node.textTileTextures.count > 0 ? node.textTileTextures.count : (node.textTexture ? 1 : 0);
    if (oldCount != tiles.count || oldCount == 0) return NO;
    for (NSValue *tile in tiles)
        if (!CjguiComposableRetainedTextTile(node, key, tile.rectValue, scale)) return NO;
    return YES;
}

static uint64_t CjguiComposableFreshTextTileBytes(CJGuiInternalComposableSceneNode *node,
    NSString *key, NSArray<NSValue *> *tiles, CGFloat scale) {
    uint64_t missing = 0;
    for (NSValue *tile in tiles) {
        if (CjguiComposableRetainedTextTile(node, key, tile.rectValue, scale)) continue;
        NSUInteger width = 0, height = 0, row = 0;
        uint64_t bytes = 0;
        if (!CjguiCheckedComposableTextTextureBytes(NSWidth(tile.rectValue), NSHeight(tile.rectValue),
            scale, scale, &width, &height, &row, &bytes) || UINT64_MAX - missing < bytes) return UINT64_MAX;
        missing += bytes;
    }
    return missing;
}

