static BOOL CjguiSelectionBInputsShareLayoutIdentity(CjguiTextPreparationWorkerInput *a,
                                                       CjguiTextPreparationWorkerInput *b) {
    if (!a || !b) return NO;
    // This is a layout-cache key, not permission to adopt the cached graph.
    // The current transfer's owner/scene/binding/selection credential is
    // checked independently by CjguiSelectionTransferBStillMatches and the
    // commit precheck. Only fields that can change this immutable TextKit
    // layout belong in the cache key; projection version, binding epoch,
    // coordinates and unrelated node POD fields do not.
    BOOL sameSession = a.sessionToken == b.sessionToken && a.sessionGeneration == b.sessionGeneration;
    BOOL sameNode = a.nodeId == b.nodeId && a.nodeKind == b.nodeKind && a.node.resourceId == b.node.resourceId;
    BOOL sameBody = [a.body isEqualToString:b.body];
    BOOL sameAttributed = [a.sourceAttributedBody isEqualToAttributedString:b.sourceAttributedBody];
    BOOL sameTemporary = [(a.sourceTemporaryAttributeRuns ?: @[]) isEqualToArray:(b.sourceTemporaryAttributeRuns ?: @[])];
    BOOL sameRuns = [(a.sourceAttributeRuns ?: @[]) isEqualToArray:(b.sourceAttributeRuns ?: @[])];
    BOOL sameTextRect = NSEqualRects(a.textRect, b.textRect);
    BOOL sameContainer = NSEqualSizes(a.containerSize, b.containerSize) &&
        a.containerPadding == b.containerPadding && a.containerLineBreakMode == b.containerLineBreakMode &&
        a.containerMaximumNumberOfLines == b.containerMaximumNumberOfLines &&
        a.containerHeightTracksTextView == b.containerHeightTracksTextView &&
        a.sourceGraphConfigurationPresent == b.sourceGraphConfigurationPresent;
    BOOL sameLayoutFlags = a.layoutAllowsNonContiguous == b.layoutAllowsNonContiguous &&
        a.layoutUsesFontLeading == b.layoutUsesFontLeading &&
        a.layoutShowsInvisibleCharacters == b.layoutShowsInvisibleCharacters &&
        a.layoutShowsControlCharacters == b.layoutShowsControlCharacters;
    BOOL sameEnvironment = a.scale == b.scale && [a.appearanceName isEqualToString:b.appearanceName];
    BOOL sameStyle = [a.extentAttributes isEqualToDictionary:b.extentAttributes] && [a.baseFont isEqual:b.baseFont];
    BOOL matches = sameSession && sameNode && sameBody && sameAttributed && sameTemporary && sameRuns &&
        sameTextRect && sameContainer && sameLayoutFlags && sameEnvironment && sameStyle;
    if (!matches && getenv("CJGUI_TEXT_PREPARE_TRACE")) fprintf(stderr,
        "CJGUI_SELECTION_B_IDENTITY_DIFF session=%u node=%u body=%u attributed=%u temporary=%u runs=%u text_rect=%u container=%u layout_flags=%u environment=%u style=%u scene_ignored=%llu/%llu binding_ignored=%llu/%llu\n",
        (unsigned)sameSession,(unsigned)sameNode,(unsigned)sameBody,(unsigned)sameAttributed,
        (unsigned)sameTemporary,(unsigned)sameRuns,(unsigned)sameTextRect,(unsigned)sameContainer,
        (unsigned)sameLayoutFlags,(unsigned)sameEnvironment,(unsigned)sameStyle,
        (unsigned long long)a.baseSceneVersion,(unsigned long long)b.baseSceneVersion,
        (unsigned long long)a.bindingEpoch,(unsigned long long)b.bindingEpoch);
    return matches;
}

static BOOL CjguiSelectionBSpareLayoutMatches(CjguiPreparedTextNodeLayout *layout,
                                                CjguiTextPreparationWorkerInput *input) {
    return layout && input && layout.storage && layout.layoutManager && layout.container &&
        [layout.storage.string isEqualToString:input.body] &&
        [layout.storage isEqualToAttributedString:input.sourceAttributedBody] &&
        NSEqualRects(layout.textRect, input.textRect) &&
        NSEqualSizes(layout.container.containerSize, input.containerSize) &&
        layout.container.lineFragmentPadding == input.containerPadding &&
        layout.container.lineBreakMode == input.containerLineBreakMode &&
        layout.container.maximumNumberOfLines == input.containerMaximumNumberOfLines &&
        layout.container.heightTracksTextView == input.containerHeightTracksTextView &&
        layout.layoutManager.allowsNonContiguousLayout == input.layoutAllowsNonContiguous &&
        layout.layoutManager.usesFontLeading == input.layoutUsesFontLeading &&
        layout.layoutManager.firstUnlaidCharacterIndex >= layout.storage.length;
}

static void CjguiDiscardSelectionBSpare(CJGuiInternalSession *ctx) {
    CjguiSelectionTransferBSpare *spare = ctx.selectionBSpare;
    if (!spare || spare.inUse) return;
    ctx.selectionBSpare = nil;
    pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
    uint64_t charge = spare.chargedBytes;
    if (charge <= gCjguiTextPreparationReservedBytes) gCjguiTextPreparationReservedBytes -= charge;
    else gCjguiTextPreparationReservedBytes = 0;
    spare.chargedBytes = 0;
    pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
    // Keep the detached graphs alive through the unlocked accounting update.
    (void)spare;
}

static void CjguiDiscardIdleSelectionBSpares(void) {
    for (NSUInteger index = 0; index < sizeof(gCjguiSessions) / sizeof(gCjguiSessions[0]); index++)
        CjguiDiscardSelectionBSpare(gCjguiSessions[index]);
}

