                attributeRuns:(NSArray<NSDictionary *> *)attributeRuns
         frozenAttributedBody:(NSAttributedString *)frozenAttributedBody
      temporaryAttributeRuns:(NSArray<NSDictionary *> *)temporaryAttributeRuns
            layoutDescription:(NSDictionary<NSString *, id> *)layoutDescription
                         tiles:(NSArray<NSValue *> *)tiles
                      coverage:(NSRect)coverage
                        origin:(NSPoint)origin
                         scale:(CGFloat)scale
                 bodyGeneration:(uint64_t)bodyGeneration
          attributedGeneration:(uint64_t)attributedGeneration {
    self = [super init];
