    _body = [body copy];
    _attributeRuns = [attributeRuns copy];
    _frozenAttributedBody = [frozenAttributedBody copy];
    _temporaryAttributeRuns = [temporaryAttributeRuns copy];
    _layoutDescription = [layoutDescription copy];
    _tiles = [tiles copy];
    _coverage = coverage;
    _origin = origin;
    _scale = scale;
    _bodyGeneration = bodyGeneration;
    _attributedGeneration = attributedGeneration;
    return self;
}
