static id CjguiFreezeRasterAttributeValue(id value, NSUInteger depth) {
    if (!value || depth > 24) return nil;
    if ([value isKindOfClass:NSString.class] || [value isKindOfClass:NSNumber.class] ||
        [value isKindOfClass:NSData.class] || [value isKindOfClass:NSNull.class] ||
        [value isKindOfClass:NSFont.class] || [value isKindOfClass:NSColor.class] ||
        [value isKindOfClass:NSParagraphStyle.class] || [value isKindOfClass:NSValue.class])
        return [value copy];
    if ([value isKindOfClass:NSArray.class]) {
        NSMutableArray *items = [NSMutableArray arrayWithCapacity:[value count]];
        for (id item in value) {
            id frozen = CjguiFreezeRasterAttributeValue(item, depth + 1);
            if (!frozen) return nil;
            [items addObject:frozen];
        }
        return [items copy];
    }
    if ([value isKindOfClass:NSDictionary.class]) {
        NSMutableDictionary *items = [NSMutableDictionary dictionaryWithCapacity:[value count]];
        for (id key in value) {
            if (![key isKindOfClass:NSString.class]) return nil;
            id frozenKey = [key copy];
            id frozenValue = CjguiFreezeRasterAttributeValue(value[key], depth + 1);
            if (!frozenValue) return nil;
            items[frozenKey] = frozenValue;
        }
        return [items copy];
    }
    // Custom attachments, delegates, mutable drawing objects and unknown
    // platform values have no closed immutable-copy contract here.
    return nil;
}

static NSArray<NSDictionary *> *CjguiFreezeRasterAttributeRuns(
    NSTextStorage *storage, NSAttributedString **outAttributedBody) {
    if (outAttributedBody) *outAttributedBody = nil;
    if (!storage) return nil;
    NSString *body = [storage.string copy] ?: @"";
    NSMutableArray<NSDictionary *> *runs = [NSMutableArray array];
    NSMutableAttributedString *frozenBody = [[NSMutableAttributedString alloc] initWithString:@""];
    NSUInteger cursor = 0;
    while (cursor < storage.length) {
        NSRange range = NSMakeRange(0, 0);
        NSDictionary *attributes = [storage attributesAtIndex:cursor effectiveRange:&range];
        range = NSIntersectionRange(range, NSMakeRange(0, storage.length));
        id frozenValue = CjguiFreezeRasterAttributeValue(attributes ?: @{}, 0);
        if (![frozenValue isKindOfClass:NSDictionary.class] || range.location != cursor || range.length == 0)
            return nil;
        NSDictionary *run = @{ @"range": [NSValue valueWithRange:range], @"attributes": frozenValue };
        [runs addObject:run];
        NSString *substring = [body substringWithRange:range];
        [frozenBody appendAttributedString:[[NSAttributedString alloc]
            initWithString:substring attributes:frozenValue]];
        cursor = NSMaxRange(range);
    }
    if (outAttributedBody) *outAttributedBody = [frozenBody copy];
    return [runs copy];
}

// Count the actual closed immutable input tree without archiving or copying it
// again on the main thread. Payload lengths and collection cardinalities are
// exact; fixed per-object/map costs are intentionally conservative. Unknown
// values fail admission instead of being charged as zero.
static BOOL CjguiFrozenRasterValueBytes(id value, NSUInteger depth,
    NSHashTable *seenSharedValues, uint64_t *outBytes, uint64_t *outContainerBytes) {
    if (outBytes) *outBytes = 0;
    if (outContainerBytes) *outContainerBytes = 0;
    if (!value || !seenSharedValues || !outBytes || !outContainerBytes || depth > 24) return NO;
    uint64_t bytes = 0, containerBytes = 0;
    BOOL shareableLeaf = [value isKindOfClass:NSString.class] || [value isKindOfClass:NSData.class] ||
        [value isKindOfClass:NSNumber.class] || [value isKindOfClass:NSFont.class] ||
        [value isKindOfClass:NSColor.class] || [value isKindOfClass:NSParagraphStyle.class] ||
        [value isKindOfClass:NSNull.class];
    if (shareableLeaf && [seenSharedValues containsObject:value]) return YES;
    if (shareableLeaf) [seenSharedValues addObject:value];
    if ([value isKindOfClass:NSString.class]) {
        NSUInteger length = [value lengthOfBytesUsingEncoding:NSUTF8StringEncoding];
        bytes = CjguiSaturatingAddU64(32u, (uint64_t)length);
    } else if ([value isKindOfClass:NSData.class]) {
        bytes = CjguiSaturatingAddU64(32u, (uint64_t)[value length]);
    } else if ([value isKindOfClass:NSNumber.class]) {
        bytes = 32u;
    } else if ([value isKindOfClass:NSFont.class]) {
        NSFont *font = value;
        NSUInteger name = [font.fontName lengthOfBytesUsingEncoding:NSUTF8StringEncoding];
        NSUInteger family = [font.familyName lengthOfBytesUsingEncoding:NSUTF8StringEncoding];
        bytes = CjguiSaturatingAddU64(256u, CjguiSaturatingAddU64(name, family));
    } else if ([value isKindOfClass:NSColor.class]) {
        bytes = 256u;
    } else if ([value isKindOfClass:NSParagraphStyle.class]) {
        NSParagraphStyle *paragraph = value;
        bytes = CjguiSaturatingAddU64(256u, (uint64_t)paragraph.tabStops.count * 64u);
    } else if ([value isKindOfClass:NSValue.class]) {
        NSValue *boxed = value;
        const char *type = boxed.objCType;
        NSUInteger typeBytes = type ? strlen(type) : NSUIntegerMax;
        NSUInteger payloadBytes = 0;
        if (type) NSGetSizeAndAlignment(type, &payloadBytes, NULL);
        if (typeBytes == NSUIntegerMax || payloadBytes == NSUIntegerMax) return NO;
        bytes = CjguiSaturatingAddU64(48u, CjguiSaturatingAddU64(typeBytes, payloadBytes));
        containerBytes = bytes;
    } else if ([value isKindOfClass:NSArray.class]) {
        bytes = CjguiSaturatingAddU64(32u, (uint64_t)[value count] * 16u);
        containerBytes = bytes;
        for (id item in value) {
            uint64_t child = 0, childContainer = 0;
            if (!CjguiFrozenRasterValueBytes(item, depth + 1, seenSharedValues, &child, &childContainer)) return NO;
            bytes = CjguiSaturatingAddU64(bytes, child);
            containerBytes = CjguiSaturatingAddU64(containerBytes, childContainer);
        }
    } else if ([value isKindOfClass:NSDictionary.class]) {
        bytes = CjguiSaturatingAddU64(48u, (uint64_t)[value count] * 32u);
        containerBytes = bytes;
        for (id key in value) {
            if (![key isKindOfClass:NSString.class]) return NO;
            uint64_t keyBytes = 0, keyContainer = 0, child = 0, childContainer = 0;
            if (!CjguiFrozenRasterValueBytes(key, depth + 1, seenSharedValues, &keyBytes, &keyContainer) ||
                !CjguiFrozenRasterValueBytes(value[key], depth + 1, seenSharedValues, &child, &childContainer)) return NO;
            bytes = CjguiSaturatingAddU64(bytes, CjguiSaturatingAddU64(keyBytes, child));
            containerBytes = CjguiSaturatingAddU64(containerBytes,
                CjguiSaturatingAddU64(keyContainer, childContainer));
        }
    } else if ([value isKindOfClass:NSNull.class]) {
        bytes = 16u;
    } else {
        return NO;
    }
    if (bytes == UINT64_MAX) return NO;
    *outBytes = bytes;
    *outContainerBytes = containerBytes;
    return YES;
}

static NSArray<NSDictionary *> *CjguiFreezeTemporaryAttributeRuns(
    NSLayoutManager *layoutManager, NSUInteger length) {
    if (!layoutManager) return nil;
    NSMutableArray<NSDictionary *> *runs = [NSMutableArray array];
    NSUInteger cursor = 0;
    while (cursor < length) {
        NSRange range = NSMakeRange(0, 0);
        NSDictionary *attributes = [layoutManager temporaryAttributesAtCharacterIndex:cursor
            effectiveRange:&range];
        range = NSIntersectionRange(range, NSMakeRange(0, length));
        id frozenValue = CjguiFreezeRasterAttributeValue(attributes ?: @{}, 0);
        if (![frozenValue isKindOfClass:NSDictionary.class] || range.location != cursor || range.length == 0)
            return nil;
        [runs addObject:@{@"range": [NSValue valueWithRange:range], @"attributes": frozenValue}];
        cursor = NSMaxRange(range);
    }
    return [runs copy];
}

static CjguiTextRasterSourceCredential *CjguiCreateTextRasterSourceCredentialWithAppearance(
    CJGuiInternalComposableSceneNode *node, NSTextStorage *storage, NSLayoutManager *layoutManager,
    NSTextContainer *container, NSTextView *textView, NSString *expectedBody,
    CGFloat scale, NSRect coverage,
    NSArray<NSValue *> *tiles, NSPoint origin, CGFloat scroll,
    uint64_t bodyGeneration, uint64_t attributedGeneration, NSString *appearanceName) {
    if (!node || !storage || !layoutManager || !container || !isfinite(scale) || scale <= 0.0 || tiles.count == 0)
        return nil;
    // The frozen painter below has no private copy contract for arbitrary
    // delegate callbacks. Keep drawing through the live path, but never issue
    // a reusable credential while either callback can affect rasterization.
    if (layoutManager.delegate || storage.delegate) return nil;
    NSAttributedString *frozenBody = nil;
    NSArray<NSDictionary *> *attributeRuns = CjguiFreezeRasterAttributeRuns(storage, &frozenBody);
    NSArray<NSDictionary *> *temporaryRuns = CjguiFreezeTemporaryAttributeRuns(layoutManager, storage.length);
    NSString *body = expectedBody ?: node.value ?: @"";
    if (!attributeRuns || !frozenBody || !temporaryRuns || ![frozenBody.string isEqualToString:body])
        return nil;
    NSRect bounds = NSMakeRect(0, 0, node.node.width, node.node.height);
    CGFloat insetY = CjguiComposableNodeUsesLabelTextInset(node.node.nodeKind) ? 2.0 : 6.0;
    NSRect textRect = NSInsetRect(bounds, 7.0, insetY);
    NSAppearance *appearance = textView.effectiveAppearance;
    NSString *resolvedAppearanceName = appearanceName;
    if (!resolvedAppearanceName && appearance) resolvedAppearanceName = appearance.name;
    if (!resolvedAppearanceName && CjguiIsMainThread()) {
        appearance = NSApp.effectiveAppearance;
        resolvedAppearanceName = appearance.name;
    }
    NSDictionary *viewTyping = textView ?
        CjguiFreezeRasterAttributeValue(textView.typingAttributes ?: @{}, 0) : @{};
    if (![viewTyping isKindOfClass:NSDictionary.class]) return nil;
    NSDictionary *layout = @{
        @"node_id": @(node.node.nodeId), @"resource_id": @(node.node.resourceId),
        @"kind": @(node.node.nodeKind),
        @"body": body, @"bounds": [NSValue valueWithRect:bounds],
        @"text_rect": [NSValue valueWithRect:textRect], @"coverage": [NSValue valueWithRect:coverage],
        @"origin": [NSValue valueWithPoint:origin], @"tiles": [tiles copy], @"scale": @(scale),
        @"scroll": @(scroll), @"node_x": @(node.node.x), @"node_y": @(node.node.y),
        @"clip_x": @(node.node.clipX), @"clip_y": @(node.node.clipY),
        @"clip_width": @(node.node.clipWidth), @"clip_height": @(node.node.clipHeight),
        @"translate_x": @(node.geometry.translateX), @"translate_y": @(node.geometry.translateY),
        @"font_size": @(node.node.fontSize), @"font_weight": @(node.node.fontWeight),
        @"font_family": @(node.node.fontFamily), @"text_rgb": @[@(node.node.textRed), @(node.node.textGreen), @(node.node.textBlue)],
        @"container_size": [NSValue valueWithSize:container.containerSize],
        @"container_padding": @(container.lineFragmentPadding),
        @"container_line_break": @(container.lineBreakMode),
        @"container_max_lines": @(container.maximumNumberOfLines),
        @"container_tracks_width": @(container.widthTracksTextView),
        @"container_tracks_height": @(container.heightTracksTextView),
        @"lm_noncontiguous": @(layoutManager.allowsNonContiguousLayout),
        @"lm_background": @(layoutManager.backgroundLayoutEnabled),
        @"lm_font_leading": @(layoutManager.usesFontLeading),
        @"lm_invisible": @(layoutManager.showsInvisibleCharacters),
        @"lm_controls": @(layoutManager.showsControlCharacters),
        @"lm_delegate": @((uintptr_t)(__bridge void *)layoutManager.delegate),
        @"storage_delegate": @((uintptr_t)(__bridge void *)storage.delegate),
        @"container": @((uintptr_t)(__bridge void *)container),
        @"text_view": @((uintptr_t)(__bridge void *)textView),
        @"typing_attributes": viewTyping,
        @"text_container_inset": textView ? [NSValue valueWithSize:textView.textContainerInset] : [NSValue valueWithSize:NSZeroSize],
        @"appearance": resolvedAppearanceName ?: @"",
        @"bitmap_context": @"sRGB;BGRA-premultiplied-first;byte-order-little;flipped;glyph-background-then-glyph"
    };
    return [[CjguiTextRasterSourceCredential alloc] initWithBody:body
        attributeRuns:attributeRuns frozenAttributedBody:frozenBody temporaryAttributeRuns:temporaryRuns
        layoutDescription:layout tiles:tiles coverage:coverage origin:origin scale:scale
        bodyGeneration:bodyGeneration attributedGeneration:attributedGeneration];
}

static CjguiTextRasterSourceCredential *CjguiCreateTextRasterSourceCredential(
    CJGuiInternalComposableSceneNode *node, NSTextStorage *storage, NSLayoutManager *layoutManager,
    NSTextContainer *container, NSTextView *textView, NSString *expectedBody,
    CGFloat scale, NSRect coverage,
    NSArray<NSValue *> *tiles, NSPoint origin, CGFloat scroll,
    uint64_t bodyGeneration, uint64_t attributedGeneration) {
    return CjguiCreateTextRasterSourceCredentialWithAppearance(node, storage, layoutManager,
        container, textView, expectedBody, scale, coverage, tiles, origin, scroll,
        bodyGeneration, attributedGeneration, nil);
}

static BOOL CjguiTextRasterSourceCredentialsEqual(CjguiTextRasterSourceCredential *left,
                                                   CjguiTextRasterSourceCredential *right) {
    if (!left || !right) return NO;
    return [left.body isEqualToString:right.body] &&
        [left.attributeRuns isEqualToArray:right.attributeRuns] &&
        [left.temporaryAttributeRuns isEqualToArray:right.temporaryAttributeRuns] &&
        [left.layoutDescription isEqualToDictionary:right.layoutDescription] &&
        [left.tiles isEqualToArray:right.tiles] && NSEqualRects(left.coverage, right.coverage) &&
        NSEqualPoints(left.origin, right.origin) && left.scale == right.scale;
}

static BOOL CjguiTextRasterSourceCanSeal(CjguiTextRasterSourceCredential *source) {
    if (!source || !source.frozenAttributedBody || !source.layoutDescription) return NO;
    NSDictionary *description = source.layoutDescription;
    return [description[@"container_size"] isKindOfClass:NSValue.class] &&
        [description[@"container_line_break"] isKindOfClass:NSNumber.class] &&
        [description[@"container_max_lines"] isKindOfClass:NSNumber.class] &&
        [description[@"container_padding"] isKindOfClass:NSNumber.class] &&
        [description[@"container_tracks_width"] isKindOfClass:NSNumber.class] &&
        [description[@"container_tracks_height"] isKindOfClass:NSNumber.class] &&
        [description[@"text_rect"] isKindOfClass:NSValue.class] &&
        [description[@"scroll"] isKindOfClass:NSNumber.class];
}

#ifdef CJGUI_INTERNAL_TESTING
static atomic_uint_fast64_t CjguiTestSealedRasterLayoutCreateCount = ATOMIC_VAR_INIT(0);
#endif

static CjguiPreparedTextNodeLayout *CjguiCreateSealedRasterLayout(
    CjguiTextRasterSourceCredential *source) {
#ifdef CJGUI_INTERNAL_TESTING
    atomic_fetch_add_explicit(&CjguiTestSealedRasterLayoutCreateCount, 1, memory_order_relaxed);
#endif
    if (!CjguiTextRasterSourceCanSeal(source)) return nil;
    NSDictionary *description = source.layoutDescription;
    NSValue *containerSizeValue = description[@"container_size"];
    NSNumber *lineBreakValue = description[@"container_line_break"];
    NSNumber *maximumLinesValue = description[@"container_max_lines"];
    NSNumber *paddingValue = description[@"container_padding"];
    NSNumber *tracksWidthValue = description[@"container_tracks_width"];
    NSNumber *tracksHeightValue = description[@"container_tracks_height"];
    NSValue *textRectValue = description[@"text_rect"];
    if (!containerSizeValue || !lineBreakValue || !maximumLinesValue || !paddingValue ||
        !tracksWidthValue || !tracksHeightValue || !textRectValue) return nil;
    NSTextStorage *storage = [[NSTextStorage alloc] initWithAttributedString:source.frozenAttributedBody];
    NSLayoutManager *layoutManager = [NSLayoutManager new];
    layoutManager.allowsNonContiguousLayout = [description[@"lm_noncontiguous"] boolValue];
    layoutManager.backgroundLayoutEnabled = [description[@"lm_background"] boolValue];
    layoutManager.usesFontLeading = [description[@"lm_font_leading"] boolValue];
    layoutManager.showsInvisibleCharacters = [description[@"lm_invisible"] boolValue];
    layoutManager.showsControlCharacters = [description[@"lm_controls"] boolValue];
    [storage addLayoutManager:layoutManager];
    NSTextContainer *container = [[NSTextContainer alloc] initWithSize:containerSizeValue.sizeValue];
    container.lineFragmentPadding = paddingValue.doubleValue;
    container.lineBreakMode = (NSLineBreakMode)lineBreakValue.integerValue;
    container.maximumNumberOfLines = maximumLinesValue.unsignedIntegerValue;
    container.widthTracksTextView = tracksWidthValue.boolValue;
    container.heightTracksTextView = tracksHeightValue.boolValue;
    [layoutManager addTextContainer:container];
    for (NSDictionary *run in source.temporaryAttributeRuns) {
        NSRange range = [run[@"range"] rangeValue];
        NSDictionary *attributes = run[@"attributes"];
        if (range.location > storage.length || range.length > storage.length - range.location ||
            ![attributes isKindOfClass:NSDictionary.class]) return nil;
        if (range.length > 0) [layoutManager addTemporaryAttributes:attributes forCharacterRange:range];
    }
    CjguiPreparedTextNodeLayout *prepared = [CjguiPreparedTextNodeLayout new];
    prepared.storage = storage;
    prepared.layoutManager = layoutManager;
    prepared.container = container;
    prepared.textRect = textRectValue.rectValue;
    prepared.sourceScroll = [description[@"scroll"] doubleValue];
    prepared.positionLines = [NSMutableDictionary dictionary];
    if (storage.length > 0) {
        NSFont *font = [storage attribute:NSFontAttributeName atIndex:0 effectiveRange:NULL];
        if (font) prepared.defaultLineHeight = ceil([layoutManager defaultLineHeightForFont:font]);
    }
    return prepared;
}

static dispatch_queue_t CjguiTextPreparationWorkerQueue(void) {
    dispatch_once(&gCjguiTextPreparationQueueOnce, ^{
        dispatch_queue_attr_t attributes = dispatch_queue_attr_make_with_qos_class(
            DISPATCH_QUEUE_CONCURRENT, QOS_CLASS_USER_INITIATED, 0);
        gCjguiTextPreparationQueue = dispatch_queue_create(
            "org.cjgui.composable-text-preparation", attributes);
    });
    return gCjguiTextPreparationQueue;
}

static void CjguiTextPreparationRemoveWaiterLocked(CjguiComposablePreparation *preparation) {
    if (!preparation || !preparation.textLayoutWaitTicket) return;
    for (NSUInteger index = 0; index < gCjguiTextPreparationWaiterCount; index++) {
        CjguiTextPreparationWaiter waiter = gCjguiTextPreparationWaiters[index];
        if (waiter.sessionToken != preparation.sessionToken ||
            waiter.sessionGeneration != preparation.sessionGeneration ||
            waiter.preparationId != preparation.preparationId ||
            waiter.ticket != preparation.textLayoutWaitTicket) continue;
        for (NSUInteger move = index + 1; move < gCjguiTextPreparationWaiterCount; move++)
            gCjguiTextPreparationWaiters[move - 1] = gCjguiTextPreparationWaiters[move];
        gCjguiTextPreparationWaiterCount--;
        memset(&gCjguiTextPreparationWaiters[gCjguiTextPreparationWaiterCount], 0,
               sizeof(gCjguiTextPreparationWaiters[0]));
        uint64_t charge = waiter.reservedBytes;
        if (charge <= gCjguiTextPreparationReservedBytes)
            gCjguiTextPreparationReservedBytes -= charge;
        else
            gCjguiTextPreparationReservedBytes = 0;
        break;
    }
    preparation.textLayoutWaitTicket = 0;
    preparation.textLayoutReservedBytes = 0;
}

static void CjguiTextPreparationReleaseSlotLocked(CjguiTextPreparationWorkerJob *job) {
    if (!job || job.workerLive || job.consumerLive || job.slotIndex >= CjguiTextPreparationWorkerSlotCount ||
        gCjguiTextPreparationWorkerSlots[job.slotIndex] != job) return;
    gCjguiTextPreparationWorkerSlots[job.slotIndex] = nil;
    if (job.reservedBytes <= gCjguiTextPreparationReservedBytes)
        gCjguiTextPreparationReservedBytes -= job.reservedBytes;
    else
        gCjguiTextPreparationReservedBytes = 0;
    job.reservedBytes = 0;
    job.input = nil;
    job.sourceLayout = nil;
    job.painter = nil;
    job.sourceCredential = nil;
    job.tiles = nil;
}

// Transfers the conservative two-graph reservation from a completed worker
// job to a detached B spare. The worker has exited and the spare owns both
// graphs before this is called; the byte charge remains globally accounted.
static uint64_t CjguiTextPreparationReleaseSlotKeepingChargeLocked(CjguiTextPreparationWorkerJob *job) {
    if (!job || job.workerLive || job.slotIndex >= CjguiTextPreparationWorkerSlotCount ||
        gCjguiTextPreparationWorkerSlots[job.slotIndex] != job) return 0;
    uint64_t charge = job.reservedBytes;
    gCjguiTextPreparationWorkerSlots[job.slotIndex] = nil;
    job.consumerLive = NO;
    job.reservedBytes = 0;
    job.input = nil;
    job.sourceLayout = nil;
    job.painter = nil;
    job.sourceCredential = nil;
    job.tiles = nil;
    return charge;
}

static NSUInteger CjguiTextPreparationAvailableSlotLocked(void) {
    for (NSUInteger index = 0; index < CjguiTextPreparationWorkerSlotCount; index++)
        if (!gCjguiTextPreparationWorkerSlots[index]) return index;
    return NSNotFound;
}

typedef NS_ENUM(uint32_t, CjguiTextPreparationAdmission) {
    CjguiTextPreparationAdmissionStarted = 1,
    CjguiTextPreparationAdmissionWaiting = 2,
    CjguiTextPreparationAdmissionNotAdmitted = 3
};

static CjguiTextPreparationWorkerJob *CjguiTextPreparationReserve(
    CjguiComposablePreparation *preparation, uint64_t reservedBytes,
    CjguiTextPreparationAdmission *outAdmission) {
    if (outAdmission) *outAdmission = CjguiTextPreparationAdmissionNotAdmitted;
    if (!preparation || !outAdmission) return nil;
    pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
    if (!preparation.textLayoutWaitTicket) {
        if (reservedBytes == 0 || reservedBytes > CjguiTextPreparationWorkerMaxBytesPerJob ||
            reservedBytes > CjguiTextPreparationWorkerMaxReservedBytes -
                MIN(gCjguiTextPreparationReservedBytes, (uint64_t)CjguiTextPreparationWorkerMaxReservedBytes)) {
            preparation.textLayoutAdmissionState = CjguiTextPreparationAdmissionNotAdmitted;
            pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
            return nil;
        }
        if (gCjguiTextPreparationWaiterCount >= CjguiTextPreparationWorkerWaiterCapacity) {
            preparation.textLayoutAdmissionState = CjguiTextPreparationAdmissionNotAdmitted;
            pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
            return nil;
        }
        uint64_t ticket = gCjguiTextPreparationNextTicket++;
        if (!ticket || !gCjguiTextPreparationNextTicket) {
            gCjguiTextPreparationNextTicket = 1;
            ticket = gCjguiTextPreparationNextTicket++;
        }
        preparation.textLayoutWaitTicket = ticket;
        gCjguiTextPreparationWaiters[gCjguiTextPreparationWaiterCount++] =
            (CjguiTextPreparationWaiter){preparation.sessionToken, preparation.sessionGeneration,
                                         preparation.preparationId, ticket, reservedBytes};
        preparation.textLayoutReservedBytes = reservedBytes;
        gCjguiTextPreparationReservedBytes = CjguiSaturatingAddU64(
            gCjguiTextPreparationReservedBytes, reservedBytes);
    }
    CjguiTextPreparationWaiter first = gCjguiTextPreparationWaiters[0];
    BOOL isHead = first.sessionToken == preparation.sessionToken &&
        first.sessionGeneration == preparation.sessionGeneration &&
        first.preparationId == preparation.preparationId &&
        first.ticket == preparation.textLayoutWaitTicket;
    NSUInteger slotIndex = isHead ? CjguiTextPreparationAvailableSlotLocked() : NSNotFound;
    if (slotIndex == NSNotFound) {
        preparation.textLayoutAdmissionState = CjguiTextPreparationAdmissionWaiting;
        *outAdmission = CjguiTextPreparationAdmissionWaiting;
        pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
        return nil;
    }
    CjguiTextPreparationWorkerJob *job = [CjguiTextPreparationWorkerJob new];
    job.generation = gCjguiTextPreparationNextGeneration++;
    if (!job.generation || !gCjguiTextPreparationNextGeneration) {
        gCjguiTextPreparationNextGeneration = 1;
        job.generation = gCjguiTextPreparationNextGeneration++;
    }
    job.slotIndex = slotIndex;
    job.reservedBytes = preparation.textLayoutReservedBytes;
    job.state = CjguiTextPreparationWorkerStateQueued;
    job.consumerLive = YES;
    gCjguiTextPreparationWorkerSlots[slotIndex] = job;
    for (NSUInteger move = 1; move < gCjguiTextPreparationWaiterCount; move++)
        gCjguiTextPreparationWaiters[move - 1] = gCjguiTextPreparationWaiters[move];
    gCjguiTextPreparationWaiterCount--;
    memset(&gCjguiTextPreparationWaiters[gCjguiTextPreparationWaiterCount], 0,
           sizeof(gCjguiTextPreparationWaiters[0]));
    preparation.textLayoutWaitTicket = 0;
    preparation.textLayoutReservedBytes = 0;
    preparation.textLayoutAdmissionState = CjguiTextPreparationAdmissionStarted;
    *outAdmission = CjguiTextPreparationAdmissionStarted;
    pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
    return job;
}

static CJGuiInternalComposableSceneNode *CjguiTextPreparationNodeSnapshot(
    CjguiTextPreparationWorkerInput *input, NSSize extent) {
    if (!input) return nil;
    CJGuiInternalComposableSceneNode *node = [CJGuiInternalComposableSceneNode new];
    node.node = input.node;
    node.geometry = input.geometry;
    node.value = input.body;
    node.textMeasuredSource = input.body;
    node.textMeasuredWidth = NSWidth(input.textRect);
    node.textMeasuredFontSize = input.node.fontSize;
    node.textMeasuredFontWeight = input.node.fontWeight;
    node.textMeasuredFontFamily = input.node.fontFamily;
    node.textMeasuredNodeKind = input.node.nodeKind;
    node.textMeasuredExtent = extent;
    node.textMeasureValid = YES;
    return node;
}

static CjguiPreparedTextNodeLayout *CjguiTextPreparationLayoutFromAttributedBody(
    CjguiTextPreparationWorkerInput *input, NSAttributedString *attributedBody) {
    if (!input || !attributedBody || ![attributedBody.string isEqualToString:input.body]) return nil;
    NSTextStorage *storage = [[NSTextStorage alloc] initWithAttributedString:attributedBody];
    NSLayoutManager *layoutManager = [NSLayoutManager new];
    if (input.sourceGraphConfigurationPresent) {
        layoutManager.allowsNonContiguousLayout = input.layoutAllowsNonContiguous;
        layoutManager.usesFontLeading = input.layoutUsesFontLeading;
        layoutManager.showsInvisibleCharacters = input.layoutShowsInvisibleCharacters;
        layoutManager.showsControlCharacters = input.layoutShowsControlCharacters;
    }
    layoutManager.backgroundLayoutEnabled = NO;
    [storage addLayoutManager:layoutManager];
    NSTextContainer *container = [[NSTextContainer alloc] initWithSize:input.containerSize];
    container.widthTracksTextView = NO;
    container.lineFragmentPadding = input.sourceGraphConfigurationPresent ? input.containerPadding : 0.0;
    if (input.sourceGraphConfigurationPresent) {
        container.lineBreakMode = input.containerLineBreakMode;
        container.maximumNumberOfLines = input.containerMaximumNumberOfLines;
        container.heightTracksTextView = input.containerHeightTracksTextView;
    }
    [layoutManager addTextContainer:container];
    for (NSDictionary *run in input.sourceTemporaryAttributeRuns ?: @[]) {
        NSRange range = [run[@"range"] rangeValue];
        NSDictionary *attributes = run[@"attributes"];
        if (range.location > storage.length || range.length > storage.length - range.location ||
            ![attributes isKindOfClass:NSDictionary.class]) return nil;
        if (range.length) [layoutManager addTemporaryAttributes:attributes forCharacterRange:range];
    }
    CjguiPreparedTextNodeLayout *prepared = [CjguiPreparedTextNodeLayout new];
    prepared.storage = storage;
    prepared.layoutManager = layoutManager;
    prepared.container = container;
    prepared.textRect = input.textRect;
    prepared.positionLines = [NSMutableDictionary dictionary];
    prepared.defaultLineHeight = ceil([layoutManager defaultLineHeightForFont:input.baseFont]);
    return prepared;
}

static BOOL CjguiTextPreparationForceCompleteLayout(CjguiPreparedTextNodeLayout *layout) {
    if (!layout || !layout.storage || !layout.layoutManager || !layout.container) return NO;
    [layout.layoutManager ensureLayoutForTextContainer:layout.container];
    return layout.storage.length == 0 ||
        layout.layoutManager.firstUnlaidCharacterIndex >= layout.storage.length;
}

static void CjguiTextPreparationTestWorkerGate(void) {
#ifdef CJGUI_INTERNAL_TESTING
    pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
    if (gCjguiTextPreparationTestGateClosed) {
        gCjguiTextPreparationTestWorkerAtGate = YES;
        pthread_cond_broadcast(&gCjguiTextPreparationTestGateCondition);
        while (gCjguiTextPreparationTestGateClosed)
            pthread_cond_wait(&gCjguiTextPreparationTestGateCondition,
                              &gCjguiTextPreparationWorkerLock);
        gCjguiTextPreparationTestWorkerAtGate = NO;
        pthread_cond_broadcast(&gCjguiTextPreparationTestGateCondition);
    }
    pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
#endif
}

static uint64_t CjguiSelectionBWorkerTrace(CjguiTextPreparationWorkerJob *job,
    CjguiTextPreparationWorkerInput *input, uint32_t kind, uint32_t phase, uint64_t span) {
    if (!CjguiOwnerPhaseTraceEnabled() || !job || !input) return 0;
    if (kind == CJGUI_OWNER_TRACE_PHASE_END && !span) return 0;
    // `dispatch` here is this private worker's real reservation generation.
    // No view or mutable graph is read, no watch or formatted I/O is installed.
    return CjguiOwnerTraceAppend(kind, input.sessionToken, job.traceOwnerTurn,
        job.traceTransferId, job.generation, input.sessionGeneration, phase, span);
}

static void CjguiRunTextPreparationWorker(CjguiTextPreparationWorkerJob *job) {
    CjguiTextPreparationTestWorkerGate();
    pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
    if (!job || job.cancelled || !job.consumerLive) {
        if (job) {
            job.workerLive = NO;
            job.state = CjguiTextPreparationWorkerStateCancelled;
            CjguiTextPreparationReleaseSlotLocked(job);
        }
#ifdef CJGUI_INTERNAL_TESTING
        pthread_cond_broadcast(&gCjguiTextPreparationTestGateCondition);
#endif
        pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
        return;
    }
    job.state = CjguiTextPreparationWorkerStateRunning;
    job.workerStartedMicros = cjgui_internal_renderer_owner_clock_ns() / UINT64_C(1000);
#ifdef CJGUI_INTERNAL_TESTING
    gCjguiTextPreparationTestJobsStarted = CjguiSaturatingAddU64(
        gCjguiTextPreparationTestJobsStarted, 1);
#endif
    CjguiTextPreparationWorkerInput *input = job.input;
    pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);

    CjguiPreparedTextNodeLayout *sourceLayout = nil;
    CjguiPreparedTextNodeLayout *painter = nil;
    CjguiTextRasterSourceCredential *credential = nil;
    NSRect coverage = NSZeroRect;
    NSSize extent = NSZeroSize;
    uint64_t plannedBytes = 0;
    NSArray<NSValue *> *tiles = nil;
    NSString *failure = @"textkit_worker_failed";
    uint64_t extentTrace = 0, sourceTrace = 0, painterTrace = 0;
    @autoreleasepool {
        @try {
            extentTrace = CjguiSelectionBWorkerTrace(job, input, CJGUI_OWNER_TRACE_PHASE_BEGIN, 321, 0);
            NSRect measured = [input.body boundingRectWithSize:
                NSMakeSize(NSWidth(input.textRect), CGFLOAT_MAX / 4.0)
                options:NSStringDrawingUsesLineFragmentOrigin | NSStringDrawingUsesFontLeading
                attributes:input.extentAttributes];
            CjguiSelectionBWorkerTrace(job, input, CJGUI_OWNER_TRACE_PHASE_END, 321, extentTrace);
            extentTrace = 0;
            extent = measured.size;
            if (!isfinite(extent.width) || !isfinite(extent.height) || extent.width < 0 || extent.height < 0) {
                failure = @"textkit_extent_invalid";
            } else {
                CJGuiInternalComposableSceneNode *snapshot = CjguiTextPreparationNodeSnapshot(input, extent);
                coverage = CjguiComposableTextTextureRectForNodeWithText(snapshot, input.body);
                tiles = CjguiPlanComposableTextTiles(
                    coverage, CjguiComposableTextNodeLayoutRect(snapshot), input.scale, &plannedBytes);
                sourceTrace = CjguiSelectionBWorkerTrace(job, input, CJGUI_OWNER_TRACE_PHASE_BEGIN, 322, 0);
                sourceLayout = CjguiTextPreparationLayoutFromAttributedBody(input, input.sourceAttributedBody);
                if (!sourceLayout || !tiles.count || !plannedBytes) {
                    failure = @"textkit_source_or_tile_prepare_failed";
                } else {
                        credential = CjguiCreateTextRasterSourceCredentialWithAppearance(
                        snapshot, sourceLayout.storage, sourceLayout.layoutManager, sourceLayout.container,
                        nil, input.body, input.scale, coverage, tiles,
                        NSMakePoint(input.node.x, input.node.y), 0.0, 0, 0, input.appearanceName);
                    if (!credential) {
                        failure = @"textkit_source_credential_failed";
                    } else if (!CjguiTextPreparationForceCompleteLayout(sourceLayout)) {
                        failure = @"textkit_source_layout_incomplete";
                    } else {
                        CjguiSelectionBWorkerTrace(job, input, CJGUI_OWNER_TRACE_PHASE_END, 322, sourceTrace);
                        sourceTrace = 0;
                        painterTrace = CjguiSelectionBWorkerTrace(job, input, CJGUI_OWNER_TRACE_PHASE_BEGIN, 323, 0);
                        painter = CjguiCreateSealedRasterLayout(credential);
                        if (!painter || !CjguiTextPreparationForceCompleteLayout(painter))
                            failure = @"textkit_painter_layout_incomplete";
                        else
                            failure = @"none";
                    }
                }
            }
        } @catch (__unused NSException *exception) {
            failure = @"textkit_worker_exception";
        } @finally {
            CjguiSelectionBWorkerTrace(job, input, CJGUI_OWNER_TRACE_PHASE_END, 321, extentTrace);
            CjguiSelectionBWorkerTrace(job, input, CJGUI_OWNER_TRACE_PHASE_END, 322, sourceTrace);
            CjguiSelectionBWorkerTrace(job, input, CJGUI_OWNER_TRACE_PHASE_END, 323, painterTrace);
        }
    }
    uint64_t workerCompletedMicros = cjgui_internal_renderer_owner_clock_ns() / UINT64_C(1000);

#ifdef CJGUI_INTERNAL_TESTING
    pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
    gCjguiTextPreparationTestWeakSourceLayout = sourceLayout;
    gCjguiTextPreparationTestWeakPainter = painter;
    if (gCjguiTextPreparationTestPublicationGateClosed) {
        gCjguiTextPreparationTestWorkerAtPublicationGate = YES;
        pthread_cond_broadcast(&gCjguiTextPreparationTestGateCondition);
        while (gCjguiTextPreparationTestPublicationGateClosed)
            pthread_cond_wait(&gCjguiTextPreparationTestGateCondition,
                              &gCjguiTextPreparationWorkerLock);
        gCjguiTextPreparationTestWorkerAtPublicationGate = NO;
    }
    pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
#endif

    // Retain only the immutable input for the terminal diagnostic record.
    CjguiTextPreparationWorkerInput *traceInput = input;
    // The autorelease pool is gone. Keep the reservation charged until all
    // worker-local graph references have either moved into the job or dropped.
    pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
#ifdef CJGUI_INTERNAL_TESTING
    gCjguiTextPreparationTestJobsCompleted = CjguiSaturatingAddU64(
        gCjguiTextPreparationTestJobsCompleted, 1);
#endif
    if (job.cancelled || !job.consumerLive) {
        job.state = CjguiTextPreparationWorkerStateCancelled;
        job.input = nil;
        job.sourceLayout = nil;
        job.painter = nil;
        job.sourceCredential = nil;
        job.tiles = nil;
        input = nil;
        sourceLayout = nil;
        painter = nil;
        credential = nil;
        tiles = nil;
#ifdef CJGUI_INTERNAL_TESTING
        gCjguiTextPreparationTestDiscardedGraphsReleased =
            gCjguiTextPreparationTestWeakSourceLayout == nil &&
            gCjguiTextPreparationTestWeakPainter == nil;
#endif
        job.workerLive = NO;
        CjguiTextPreparationReleaseSlotLocked(job);
    } else if (![failure isEqualToString:@"none"]) {
        job.failure = failure;
        job.input = nil;
        input = nil;
        sourceLayout = nil;
        painter = nil;
        credential = nil;
        tiles = nil;
        job.workerLive = NO;
        job.state = CjguiTextPreparationWorkerStateFailed;
    } else {
        job.sourceLayout = sourceLayout;
        job.painter = painter;
        job.sourceCredential = credential;
        job.coverage = coverage;
        job.tiles = tiles;
        job.measuredExtent = extent;
        job.plannedBytes = plannedBytes;
        job.workerCompletedMicros = workerCompletedMicros;
        input = nil;
        sourceLayout = nil;
        painter = nil;
        credential = nil;
        tiles = nil;
        job.workerLive = NO;
        job.state = CjguiTextPreparationWorkerStateReady;
    }
#ifdef CJGUI_INTERNAL_TESTING
    pthread_cond_broadcast(&gCjguiTextPreparationTestGateCondition);
#endif
    CjguiTextPreparationWorkerState terminalState = job.state;
    pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
    CjguiSelectionBWorkerTrace(job, traceInput, CJGUI_OWNER_TRACE_OBSERVATION_SCALAR, 324,
        (uint64_t)terminalState);
}

#ifdef CJGUI_INTERNAL_TESTING
static void CjguiTextPreparationTestCloseWorkerGate(void) {
    pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
    gCjguiTextPreparationTestGateClosed = YES;
    gCjguiTextPreparationTestWorkerAtGate = NO;
    pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
}
static BOOL CjguiTextPreparationTestWaitForWorkerGate(uint32_t timeoutMs) {
    struct timespec deadline;
    clock_gettime(CLOCK_REALTIME, &deadline);
    deadline.tv_sec += timeoutMs / 1000;
    deadline.tv_nsec += (long)(timeoutMs % 1000) * 1000000L;
    if (deadline.tv_nsec >= 1000000000L) { deadline.tv_sec++; deadline.tv_nsec -= 1000000000L; }
    pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
    int result = 0;
    while (!gCjguiTextPreparationTestWorkerAtGate && result == 0)
        result = pthread_cond_timedwait(&gCjguiTextPreparationTestGateCondition,
            &gCjguiTextPreparationWorkerLock, &deadline);
    BOOL reached = gCjguiTextPreparationTestWorkerAtGate;
    pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
    return reached;
}
static void CjguiTextPreparationTestOpenWorkerGate(void) {
    pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
    gCjguiTextPreparationTestGateClosed = NO;
    pthread_cond_broadcast(&gCjguiTextPreparationTestGateCondition);
    pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
}
static BOOL CjguiTextPreparationTestWaitForFinished(uint32_t timeoutMs) {
    struct timespec deadline;
    clock_gettime(CLOCK_REALTIME, &deadline);
    deadline.tv_sec += timeoutMs / 1000;
    deadline.tv_nsec += (long)(timeoutMs % 1000) * 1000000L;
    if (deadline.tv_nsec >= 1000000000L) { deadline.tv_sec++; deadline.tv_nsec -= 1000000000L; }
    pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
    int result = 0;
    for (;;) {
        BOOL running = NO;
        for (NSUInteger index = 0; index < CjguiTextPreparationWorkerSlotCount; index++)
            running |= gCjguiTextPreparationWorkerSlots[index].workerLive;
        if (!running || result != 0) break;
        result = pthread_cond_timedwait(&gCjguiTextPreparationTestGateCondition,
            &gCjguiTextPreparationWorkerLock, &deadline);
    }
    BOOL finished = YES;
    for (NSUInteger index = 0; index < CjguiTextPreparationWorkerSlotCount; index++)
        finished &= !gCjguiTextPreparationWorkerSlots[index].workerLive;
    pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
    return finished;
}
// Narrow test-only exports for managed cancellation tests. Production builds
// omit these symbols and the gate itself remains inert unless explicitly
// closed by an internal test.
void cjgui_internal_renderer_test_close_text_preparation_worker_gate(void) {
    CjguiTextPreparationTestCloseWorkerGate();
}
int32_t cjgui_internal_renderer_test_wait_for_text_preparation_worker_gate(uint32_t timeoutMs) {
    return CjguiTextPreparationTestWaitForWorkerGate(timeoutMs) ? 1 : 0;
}
void cjgui_internal_renderer_test_open_text_preparation_worker_gate(void) {
    CjguiTextPreparationTestOpenWorkerGate();
}
int32_t cjgui_internal_renderer_test_wait_for_text_preparation_finished(uint32_t timeoutMs) {
    return CjguiTextPreparationTestWaitForFinished(timeoutMs) ? 1 : 0;
}
static void CjguiTextPreparationTestClosePublicationGate(void) {
    pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
    gCjguiTextPreparationTestPublicationGateClosed = YES;
    gCjguiTextPreparationTestWorkerAtPublicationGate = NO;
    gCjguiTextPreparationTestWeakSourceLayout = nil;
    gCjguiTextPreparationTestWeakPainter = nil;
    gCjguiTextPreparationTestDiscardedGraphsReleased = NO;
    pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
}
static BOOL CjguiTextPreparationTestWaitForPublicationGate(uint32_t timeoutMs) {
    struct timespec deadline;
    clock_gettime(CLOCK_REALTIME, &deadline);
    deadline.tv_sec += timeoutMs / 1000;
    deadline.tv_nsec += (long)(timeoutMs % 1000) * 1000000L;
    if (deadline.tv_nsec >= 1000000000L) { deadline.tv_sec++; deadline.tv_nsec -= 1000000000L; }
    pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
    int result = 0;
    while (!gCjguiTextPreparationTestWorkerAtPublicationGate && result == 0)
        result = pthread_cond_timedwait(&gCjguiTextPreparationTestGateCondition,
            &gCjguiTextPreparationWorkerLock, &deadline);
    BOOL reached = gCjguiTextPreparationTestWorkerAtPublicationGate;
    pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
    return reached;
}
static void CjguiTextPreparationTestOpenPublicationGate(void) {
    pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
    gCjguiTextPreparationTestPublicationGateClosed = NO;
    pthread_cond_broadcast(&gCjguiTextPreparationTestGateCondition);
    pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
}
#endif

static BOOL CjguiTextPreparationRawGeometryVisible(CJGuiInternalComposableSceneNode *node) {
    if (!node) return NO;
    NSRect nodeRect = NSMakeRect(node.node.x, node.node.y,
        MAX(0.0, node.node.width), MAX(0.0, node.node.height));
    NSRect clip = node.geometry.clipCount == 0
        ? NSMakeRect(node.node.clipX, node.node.clipY,
            MAX(0.0, node.node.clipWidth), MAX(0.0, node.node.clipHeight))
        : CjguiComposableVisualClipBounds(node);
    NSRect rawVisual = NSOffsetRect(nodeRect, node.geometry.translateX, node.geometry.translateY);
    return !NSIsEmptyRect(NSIntersectionRect(rawVisual, clip));
}

static BOOL CjguiTextPreparationExtentMemoMatches(CJGuiInternalComposableSceneNode *node,
                                                   NSString *text) {
    if (!node || !text || !node.textMeasureValid) return NO;
    NSRect drawRect = NSInsetRect(NSMakeRect(0.0, 0.0, node.node.width, node.node.height), 7.0, 6.0);
    return node.textMeasuredWidth == NSWidth(drawRect) &&
        node.textMeasuredFontSize == node.node.fontSize &&
        node.textMeasuredFontWeight == node.node.fontWeight &&
        node.textMeasuredFontFamily == node.node.fontFamily &&
        node.textMeasuredNodeKind == node.node.nodeKind &&
        [node.textMeasuredSource isEqualToString:text];
}

static CjguiTextPreparationWorkerInput *CjguiCreateTextPreparationWorkerInput(
    CJGuiInternalSession *ctx, CjguiComposablePreparation *preparation,
    CJGuiInternalComposableSceneNode *node, NSString *body, NSString *encodedRuns,
    uint64_t *outReservedBytes);

static BOOL CjguiTextPreparationInputMatches(CJGuiInternalSession *ctx,
    CjguiComposablePreparation *preparation, CJGuiInternalComposableSceneNode *node,
    CjguiTextPreparationWorkerInput *input) {
    if (!ctx || !preparation || !node || !input || ctx.destroyed ||
        input.sessionToken != preparation.sessionToken ||
        input.sessionGeneration != ctx.sessionGeneration ||
        input.sessionGeneration != preparation.sessionGeneration ||
        input.preparationId != preparation.preparationId ||
        input.baseSceneVersion != preparation.baseSceneVersion ||
        input.projectionVersion != preparation.projectionVersion ||
        input.bindingEpoch != preparation.bindingEpoch ||
        input.nodeId != node.node.nodeId || input.nodeKind != node.node.nodeKind ||
        ![input.body isEqualToString:node.value] ||
        !NSEqualSizes(input.containerSize, (^{
            NSRect bounds = NSMakeRect(0, 0, node.node.width, node.node.height);
            CGFloat insetY = CjguiComposableNodeUsesLabelTextInset(node.node.nodeKind) ? 2.0 : 6.0;
            NSSize size = NSInsetRect(bounds, 7.0, insetY).size;
            if (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT)
                size.height = CGFLOAT_MAX;
            return size;
        })()) ||
        input.scale != preparation.scale) return NO;
    CjguiInternalRendererComposableNode inputNode = input.node;
    CjguiInternalRendererComposableNode currentNode = node.node;
    CjguiInternalRendererComposableGeometry inputGeometry = input.geometry;
    CjguiInternalRendererComposableGeometry currentGeometry = node.geometry;
    if (memcmp(&inputNode, &currentNode, sizeof(inputNode)) != 0 ||
        memcmp(&inputGeometry, &currentGeometry, sizeof(inputGeometry)) != 0) return NO;
    return YES;
}

static void CjguiCancelTextPreparationWorker(CjguiComposablePreparation *preparation) {
    if (!preparation) return;
    pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
    CjguiTextPreparationRemoveWaiterLocked(preparation);
    preparation.textLayoutPendingInput = nil;
    preparation.textLayoutPendingBytes = 0;
    CjguiTextPreparationWorkerJob *job = preparation.textLayoutJob;
    if (job) {
        job.cancelled = YES;
        job.consumerLive = NO;
        if (!job.workerLive) {
            job.state = CjguiTextPreparationWorkerStateCancelled;
            CjguiTextPreparationReleaseSlotLocked(job);
            preparation.textLayoutJob = nil;
        }
    }
    preparation.textLayoutAdmissionState = CjguiTextPreparationAdmissionNotAdmitted;
    pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
}

static CjguiInternalRendererStatus CjguiStartOrAdoptColdTextLayout(
    CJGuiInternalSession *ctx, CjguiComposablePreparation *preparation,
    CJGuiInternalComposableSceneNode *node, NSString *text, NSString *desiredRuns,
    BOOL *outHandled) {
    if (outHandled) *outHandled = NO;
    if (!ctx || !preparation || !node || !text || !outHandled ||
        node.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT || text.length < 1024)
        return CJGUI_INTERNAL_RENDERER_OK;
    if (!CjguiTextPreparationRawGeometryVisible(node)) return CJGUI_INTERNAL_RENDERER_OK;
    *outHandled = YES;
    if (text.length > CjguiTextPreparationWorkerMaxUtf16Length ||
        !CjguiTextPreparationRawGeometryVisible(node))
        return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;

    CjguiTextPreparationWorkerJob *job = preparation.textLayoutJob;
    if (!job) {
        uint64_t reservedBytes = preparation.textLayoutPendingBytes;
        CjguiTextPreparationWorkerInput *input = preparation.textLayoutPendingInput;
        if (!input) input = CjguiCreateTextPreparationWorkerInput(
            ctx, preparation, node, text, desiredRuns, &reservedBytes);
        if (!input || !reservedBytes)
            return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
        CjguiTextPreparationAdmission admission = CjguiTextPreparationAdmissionNotAdmitted;
        job = CjguiTextPreparationReserve(preparation, reservedBytes, &admission);
        if (!job) {
            if (admission == CjguiTextPreparationAdmissionWaiting) {
                preparation.textLayoutPendingInput = input;
                preparation.textLayoutPendingBytes = reservedBytes;
            }
            return admission == CjguiTextPreparationAdmissionWaiting
                ? CJGUI_INTERNAL_RENDERER_OK
                : CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
        }
        preparation.textLayoutPendingInput = nil;
        preparation.textLayoutPendingBytes = 0;
        pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
        job.input = input;
        job.workerLive = YES;
        job.traceOwnerTurn = atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn, memory_order_acquire);
        preparation.textLayoutJob = job;
        pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
        CjguiSelectionBWorkerTrace(job, input, CJGUI_OWNER_TRACE_OBSERVATION_SCALAR, 320, reservedBytes);
        dispatch_async(CjguiTextPreparationWorkerQueue(), ^{
            CjguiRunTextPreparationWorker(job);
        });
        return CJGUI_INTERNAL_RENDERER_OK;
    }

    CjguiTextPreparationWorkerInput *input = nil;
    CjguiPreparedTextNodeLayout *sourceLayout = nil;
    CjguiPreparedTextNodeLayout *painter = nil;
    CjguiTextRasterSourceCredential *credential = nil;
    NSRect coverage = NSZeroRect;
    NSArray<NSValue *> *tiles = nil;
    NSSize extent = NSZeroSize;
    uint64_t plannedBytes = 0;
    NSString *failure = nil;
    CjguiTextPreparationWorkerState state;
    pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
    state = job.state;
    if (job.workerLive || state == CjguiTextPreparationWorkerStateQueued ||
        state == CjguiTextPreparationWorkerStateRunning) {
        pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
        return CJGUI_INTERNAL_RENDERER_OK;
    }
    input = job.input;
    sourceLayout = job.sourceLayout;
    painter = job.painter;
    credential = job.sourceCredential;
    coverage = job.coverage;
    tiles = job.tiles;
    extent = job.measuredExtent;
    plannedBytes = job.plannedBytes;
    failure = job.failure;
    pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);

    if (!CjguiTextPreparationInputMatches(ctx, preparation, node, input)) {
        CjguiCancelTextPreparationWorker(preparation);
        return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    }
    if (state != CjguiTextPreparationWorkerStateReady || !sourceLayout || !painter ||
        !credential || !tiles.count || !plannedBytes || !isfinite(extent.height) ||
        (failure && failure.length)) {
        CjguiCancelTextPreparationWorker(preparation);
        return CJGUI_INTERNAL_RENDERER_TEXT_SERVICE_UNSUPPORTED;
    }

    // This is the sole graph ownership transfer. The worker has published only
    // after its autorelease pool drained and workerLive became false.
    sourceLayout.positionLease = ++gCjguiNextPreparedTextPositionLease;
    sourceLayout.diagnosticSession = ctx;
    painter.positionLease = ++gCjguiNextPreparedTextPositionLease;
    painter.diagnosticSession = ctx;
    ctx.positionPrepareCount = CjguiSaturatingAddU64(ctx.positionPrepareCount, 1);
    node.textMeasuredSource = text;
    node.textMeasuredWidth = NSWidth(input.textRect);
    node.textMeasuredFontSize = node.node.fontSize;
    node.textMeasuredFontWeight = node.node.fontWeight;
    node.textMeasuredFontFamily = node.node.fontFamily;
    node.textMeasuredNodeKind = node.node.nodeKind;
    node.textMeasuredExtent = extent;
    node.textMeasureValid = YES;

    preparation.text = text;
    preparation.coverage = coverage;
    preparation.tiles = tiles;
    preparation.plannedBytes = plannedBytes;
    preparation.key = CjguiComposableTextTextureKey(node, preparation.scale,
        preparation.scale, text, coverage);
    preparation.sourceLayout = sourceLayout;
    preparation.painter = painter;
    preparation.sourceCredential = credential;
    preparation.textures = [NSMutableArray arrayWithCapacity:tiles.count];
    preparation.phase = 2;

    pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
    job.consumerLive = NO;
    job.state = CjguiTextPreparationWorkerStateReady;
    CjguiTextPreparationReleaseSlotLocked(job);
    preparation.textLayoutJob = nil;
    pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
    return CJGUI_INTERNAL_RENDERER_OK;
}

static const NSUInteger CjguiVisualNavMaxLinePositions = 8192;
static CjguiInternalRendererStatus
CjguiReadLineInsertionPointsEx(NSLayoutManager *lm, NSUInteger anchorChar, BOOL alternate,
                               NSUInteger *outCount, CGFloat **outPos, NSUInteger **outIdx);

// R2（Astra 裁决，2026-09-30）：平台行终止符判定（\n \r NEL U+2028 U+2029；
// CRLF 的后随位置前一字符是 \n，同样命中）。位置在硬终止符之后 ⇒ 该位置唯一
// 属于下一行（Downstream 语义）；软折行边界才有双侧渲染（Upstream 上一折出行末）。
static BOOL CjguiIsHardLineTerminatorBefore(NSString *text, NSUInteger character) {
    if (character == 0 || character > text.length) return NO;
    unichar c = [text characterAtIndex:character - 1];
    return c == (unichar)'\n' || c == (unichar)'\r' ||
           c == (unichar)0x0085 || c == (unichar)0x2028 || c == (unichar)0x2029;
}

// R1（2026-09-30）：统一的行插入点读取——先以 NULL 缓冲从**同一查询行**取得
// 真实插入点数（SDK 契约：无容量参数，NULL=只计数；插入点数 ≤ 行字符数+1），
// 预算准入后才按 pointCount 精确分配并二次调用填充。旧行为按"命中行"容量
// 分配、却查询"anchorChar 所在行"（软折行末 anchor 已是下一行首）——宽短行
// 后接窄长折行时 heap-buffer-overflow（ASan 实证，asan-r1-red.log）。预算或
// 分配失败具名拒绝，调用方保状态；两次调用计数不一致（同布局不应发生）同样
// 具名拒绝，不以截短数组冒充预算。
static CjguiInternalRendererStatus
CjguiReadLineInsertionPoints(NSLayoutManager *lm, NSUInteger anchorChar,
                             NSUInteger *outCount, CGFloat **outPos, NSUInteger **outIdx) {
    return CjguiReadLineInsertionPointsEx(lm, anchorChar, NO, outCount, outPos, outIdx);
}

// Astra 裁决（正式）：primary 与 alternate **分别**有界读取（各自 NULL 取数→
// 预算准入→精确分配），不能拿 primary 的容量填 alternate。
static CjguiInternalRendererStatus
CjguiReadLineInsertionPointsEx(NSLayoutManager *lm, NSUInteger anchorChar, BOOL alternate,
                               NSUInteger *outCount, CGFloat **outPos, NSUInteger **outIdx) {
    *outCount = 0;
    *outPos = NULL;
    *outIdx = NULL;
    NSUInteger count = [lm getLineFragmentInsertionPointsForCharacterAtIndex:anchorChar
                                                           alternatePositions:alternate
                                                                inDisplayOrder:YES
                                                                    positions:NULL
                                                              characterIndexes:NULL];
    if (count == 0) return CJGUI_INTERNAL_RENDERER_OK;
    if (count > CjguiVisualNavMaxLinePositions) {
        return CJGUI_INTERNAL_RENDERER_VISUAL_NAV_UNSUPPORTED;
    }
    CGFloat *pos = (CGFloat *)calloc(count, sizeof(CGFloat));
    NSUInteger *idx = (NSUInteger *)calloc(count, sizeof(NSUInteger));
    if (!pos || !idx) {
        free(pos);
        free(idx);
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    NSUInteger filled = [lm getLineFragmentInsertionPointsForCharacterAtIndex:anchorChar
                                                               alternatePositions:alternate
                                                                    inDisplayOrder:YES
                                                                        positions:pos
                                                                  characterIndexes:idx];
    if (filled != count) {
        free(pos);
        free(idx);
        return CJGUI_INTERNAL_RENDERER_VISUAL_NAV_UNSUPPORTED;
    }
    *outCount = count;
    *outPos = pos;
    *outIdx = idx;
    return CJGUI_INTERNAL_RENDERER_OK;
}

// ---- Astra 正式裁决：共同 accepted 停靠点解析器 ----
// 一行的一组停靠点：primary 与 alternate 各自有界读取（R1 同款 NULL 取数→
// 预算准入→精确分配），按显示序 x 归并；相同 charIndex 且 x 重合的 alternate
// 条目视为 primary 的**别名**（不增加一次按键停靠），不按 byte/x 盲目去重，
// 也不把 alternate 直接解释为 Upstream。
typedef struct {
    NSUInteger charIndex;   // UTF-16 边界
    uint8_t branch;         // 0 = primary，1 = alternate（独有条目）
    CGFloat x;
} CjguiStopPoint;

typedef struct {
    CjguiStopPoint *points; // 显示序（x 升序）
    NSUInteger count;
    NSUInteger lineLocation;
    NSUInteger lineLength;
    NSRange lineGlyphRange;
} CjguiStopLine;

static void CjguiFreeStopLine(CjguiStopLine *line) {
    if (line->points) free(line->points);
    line->points = NULL;
    line->count = 0;
}

// 解析一行（anchorChar 所属行）的停靠点。失败返回具名状态；调用方释放。
static CjguiInternalRendererStatus
CjguiResolveStopLine(NSLayoutManager *lm, NSString *text, NSUInteger anchorChar,
                     CjguiStopLine *outLine) {
    memset(outLine, 0, sizeof(*outLine));
    NSUInteger glyphCount = lm.numberOfGlyphs;
    if (glyphCount == 0) return CJGUI_INTERNAL_RENDERER_GEOMETRY_EMPTY;
    NSUInteger anchorGlyph = MIN([lm glyphIndexForCharacterAtIndex:MIN(anchorChar, lm.textStorage.length ? lm.textStorage.length - 1 : 0)], glyphCount - 1);
    NSRange lineGlyphRange = NSMakeRange(0, 0);
    [lm lineFragmentRectForGlyphAtIndex:anchorGlyph effectiveRange:&lineGlyphRange];
    NSRange lineCharRange = [lm characterRangeForGlyphRange:lineGlyphRange actualGlyphRange:NULL];
    CGFloat *pPos = NULL; NSUInteger *pIdx = NULL; NSUInteger pCount = 0;
    CGFloat *aPos = NULL; NSUInteger *aIdx = NULL; NSUInteger aCount = 0;
    CjguiInternalRendererStatus st =
        CjguiReadLineInsertionPointsEx(lm, anchorChar, NO, &pCount, &pPos, &pIdx);
    if (st != CJGUI_INTERNAL_RENDERER_OK) { free(pPos); free(pIdx); return st; }
    st = CjguiReadLineInsertionPointsEx(lm, anchorChar, YES, &aCount, &aPos, &aIdx);
    if (st != CJGUI_INTERNAL_RENDERER_OK) {
        free(pPos); free(pIdx); free(aPos); free(aIdx);
        return st;
    }
    // 归并：primary 全保留；alternate 仅保留无 primary 别名（同 charIndex 且
    // x 重合 < 0.25pt）的条目。
    NSUInteger cap = pCount + aCount;
    CjguiStopPoint *merged = cap ? calloc(cap, sizeof(CjguiStopPoint)) : NULL;
    if (cap && !merged) {
        free(pPos); free(pIdx); free(aPos); free(aIdx);
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    NSUInteger n = 0;
    for (NSUInteger i = 0; i < pCount; i++) {
        merged[n].charIndex = pIdx[i]; merged[n].branch = 0; merged[n].x = pPos[i]; n++;
    }
    for (NSUInteger i = 0; i < aCount; i++) {
        BOOL aliased = NO;
        for (NSUInteger j = 0; j < pCount; j++) {
            if (pIdx[j] == aIdx[i] && fabs(pPos[j] - aPos[i]) < 0.25) { aliased = YES; break; }
        }
        if (!aliased) {
            merged[n].charIndex = aIdx[i]; merged[n].branch = 1; merged[n].x = aPos[i]; n++;
        }
    }
    // 显示序：x 升序，稳定。
    for (NSUInteger i = 1; i < n; i++) {
        CjguiStopPoint key = merged[i];
        NSUInteger j = i;
        while (j > 0 && merged[j - 1].x > key.x) { merged[j] = merged[j - 1]; j--; }
        merged[j] = key;
    }
    free(pPos); free(pIdx); free(aPos); free(aIdx);
    outLine->points = merged;
    outLine->count = n;
    outLine->lineLocation = lineCharRange.location;
    outLine->lineLength = lineCharRange.length;
    outLine->lineGlyphRange = lineGlyphRange;
    return CJGUI_INTERNAL_RENDERER_OK;
}

// 在停靠点行内找 charIndex 的条目；branchIn(2=AUTO) 时取**首选**（primary 优先，
// 无 primary 条目才取 alternate），branchIn 0/1 时精确匹配该分支。
static BOOL CjguiStopLineFind(const CjguiStopLine *line, NSUInteger charIndex,
                              uint32_t branchIn, NSUInteger *outOrdinal) {
    NSUInteger best = NSNotFound;
    for (NSUInteger i = 0; i < line->count; i++) {
        if (line->points[i].charIndex != charIndex) continue;
        if (branchIn == 2) {
            if (best == NSNotFound || line->points[i].branch == 0) best = i;
            if (line->points[i].branch == 0) break;
        } else if (line->points[i].branch == branchIn) {
            best = i; break;
        }
    }
    if (best == NSNotFound) return NO;
    *outOrdinal = best;
    return YES;
}

// Forward declaration: the UTF-8 byte -> UTF-16 offset helper is defined below
// its first use in the accepted-caret query, so it must be declared before that
// caller (C99 forbids implicit function declarations).
static NSUInteger CjguiComposableUtf16OffsetForByte(const char *utf8, NSUInteger utf8Length, NSUInteger byteOffset);

// Accepted caret geometry is resolved by text_position_v1 below, using the
// same canonical stop records as hit and visual navigation.

// A presentation style run: display byte range plus its permitted attributes.
// Ordinary runs retain their declaration order. Explicit selection-background
// runs may overlap them, but have no authority to change layout or foreground.
// Byte offsets are UTF-8. This struct is private to paired source builds.
typedef struct CjguiInternalTextStyleRun {
    uint32_t start;
    uint32_t end;
    double fontSize;
    uint32_t fontWeight;      // 0/1 legacy boolean, or 100..1000 numeric weight
    uint32_t fontFamily;      // 0 system, 1 monospaced
    float red;
    float green;
    float blue;
    float alpha;
    // Optional run background (inline code, highlighted spans). hasBackground
    // distinguishes "no background" from a fully transparent one.
    uint32_t hasBackground;
    float backgroundRed;
    float backgroundGreen;
    float backgroundBlue;
    float backgroundAlpha;
    uint32_t selectionBackground;
} CjguiInternalTextStyleRun;

static const NSUInteger CjguiSelectionBackgroundRunCapacity = 1024;
static const NSUInteger CjguiSelectionBackgroundTotalRunCapacity = 2048;
static const NSUInteger CjguiSelectionBackgroundTextByteCapacity = 65536;
static const NSUInteger CjguiTextStyleRunWireByteCapacity = 2u * 1024u * 1024u;

static BOOL CjguiSelectionBackgroundParseByte(NSString *field, uint32_t *outValue) {
    const char *bytes = field.UTF8String;
    if (!bytes || !bytes[0]) return NO;
    uint32_t value = 0;
    for (const unsigned char *cursor = (const unsigned char *)bytes; *cursor; cursor++) {
        if (*cursor < '0' || *cursor > '9') return NO;
        uint32_t digit = *cursor - '0';
        if (value > (UINT32_MAX - digit) / 10u) return NO;
        value = value * 10u + digit;
    }
    *outValue = value;
    return YES;
}

static BOOL CjguiSelectionBackgroundParseColor(NSString *field, float *outValue) {
    const char *bytes = field.UTF8String;
    if (!bytes || !bytes[0] || (unsigned char)bytes[0] <= ' ') return NO;
    char *end = NULL;
    double value = strtod(bytes, &end);
    if (end == bytes || !end || *end ||
        !isfinite(value) || value < 0.0 || value > 1.0) return NO;
    *outValue = (float)value;
    return YES;
}

static CjguiInternalRendererStatus CjguiSelectionBackgroundRunFromFields(
    NSArray<NSString *> *fields, CjguiInternalTextStyleRun *outRun) {
    if (fields.count != 15 ||
        (![fields[14] isEqualToString:@"1"] && ![fields[14] isEqualToString:@"2"]) ||
        ![fields[9] isEqualToString:@"1"]) return CJGUI_INTERNAL_RENDERER_STYLE_RUN_INVALID;
    CjguiInternalTextStyleRun run = {0};
    if (!CjguiSelectionBackgroundParseByte(fields[0], &run.start) ||
        !CjguiSelectionBackgroundParseByte(fields[1], &run.end) || run.end <= run.start)
        return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    if (!CjguiSelectionBackgroundParseColor(fields[10], &run.backgroundRed) ||
        !CjguiSelectionBackgroundParseColor(fields[11], &run.backgroundGreen) ||
        !CjguiSelectionBackgroundParseColor(fields[12], &run.backgroundBlue) ||
        !CjguiSelectionBackgroundParseColor(fields[13], &run.backgroundAlpha))
        return CJGUI_INTERNAL_RENDERER_STYLE_RUN_INVALID;
    // Fields 2..8 are wire placeholders, never font/foreground permissions.
    run.hasBackground = 1;
    run.selectionBackground = [fields[14] isEqualToString:@"2"] ? 2 : 1;
    if (outRun) *outRun = run;
    return CJGUI_INTERNAL_RENDERER_OK;
}

static NSColor *CjguiComposablePlatformSelectionColor(void) {
    return NSColor.selectedTextBackgroundColor;
}

static NSColor *CjguiSelectionBackgroundColorForRun(const CjguiInternalTextStyleRun *run) {
    if (run->selectionBackground == 2) return CjguiComposablePlatformSelectionColor();
    return [NSColor colorWithSRGBRed:run->backgroundRed green:run->backgroundGreen
                              blue:run->backgroundBlue alpha:run->backgroundAlpha];
}

// A nil text validates the wire before it is staged. Final admission MUST use
// the actual candidate text: set_text_runs can precede set_scene_node, so an
// older node's value is not a valid range witness for this candidate.
static CjguiInternalRendererStatus CjguiComposableValidateSelectionBackgroundRuns(
    NSString *encoded, NSString *displayText) {
    if (!encoded.length) return CJGUI_INTERNAL_RENDERER_OK;
    if ([encoded lengthOfBytesUsingEncoding:NSUTF8StringEncoding] > CjguiTextStyleRunWireByteCapacity)
        return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
    NSUInteger selectionCount = 0, totalCount = 0;
    NSUInteger textLength = 0;
    const unsigned char *textBytes = NULL;
    BOOL readText = NO;
    for (NSString *item in [encoded componentsSeparatedByString:@";"]) {
        if (!item.length) continue;
        totalCount++;
        NSArray<NSString *> *fields = [item componentsSeparatedByString:@":"];
        if (fields.count <= 14) continue; // Existing ordinary-run interpretation.
        CjguiInternalTextStyleRun run = {0};
        CjguiInternalRendererStatus status = CjguiSelectionBackgroundRunFromFields(fields, &run);
        if (status != CJGUI_INTERNAL_RENDERER_OK) return status;
        if (displayText && !readText) {
            // Only the new tag pays for a bounded UTF-8 witness. Ordinary
            // large-document runs keep their existing preparation behavior.
            if (displayText.length > CjguiSelectionBackgroundTextByteCapacity)
                return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
            textLength = [displayText lengthOfBytesUsingEncoding:NSUTF8StringEncoding];
            if (textLength > CjguiSelectionBackgroundTextByteCapacity)
                return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
            textBytes = (const unsigned char *)displayText.UTF8String;
            readText = YES;
        }
        selectionCount++;
        if (selectionCount > CjguiSelectionBackgroundRunCapacity ||
            totalCount > CjguiSelectionBackgroundTotalRunCapacity ||
            (displayText && textLength > CjguiSelectionBackgroundTextByteCapacity))
            return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
        if (displayText && (!textBytes || run.end > textLength ||
            (run.start < textLength && (textBytes[run.start] & 0xC0) == 0x80) ||
            (run.end < textLength && (textBytes[run.end] & 0xC0) == 0x80)))
            return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    }
    if (selectionCount && totalCount > CjguiSelectionBackgroundTotalRunCapacity)
        return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
    return CJGUI_INTERNAL_RENDERER_OK;
}

static NSAttributedString *CjguiComposableAttributedText(CJGuiInternalComposableSceneNode *node,
    NSString *displayText, NSDictionary *baseAttributes, const CjguiInternalTextStyleRun *runs,
    uint32_t runCount);
static NSData *CjguiComposableRasterStyleRunData(CJGuiInternalComposableSceneNode *node,
                                                  NSData *decoded) {
    if (node.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT ||
        decoded.length < sizeof(CjguiInternalTextStyleRun)) return decoded;
    const CjguiInternalTextStyleRun *runs = decoded.bytes;
    NSUInteger count = decoded.length / sizeof(CjguiInternalTextStyleRun);
    NSMutableData *raster = [NSMutableData dataWithCapacity:decoded.length];
    for (NSUInteger index = 0; index < count; index++) {
        if (!runs[index].selectionBackground) [raster appendBytes:&runs[index] length:sizeof(runs[index])];
    }
    return raster;
}
static CjguiPreparedTextNodeLayout *CjguiPrepareTextNodeLayout(
    CJGuiInternalComposableSceneNode *node, NSString *displayText, CGFloat scaleX,
    NSData *styleRunData, CJGuiInternalSession *diagnosticSession) {
    BOOL timing = diagnosticSession && diagnosticSession.diagnosticTimingEnabled;
    uint64_t timingStarted = timing ? CjguiDiagnosticMonotonicNanoseconds() : 0;
    NSRect bounds = NSMakeRect(0.0, 0.0, (CGFloat)node.node.width, (CGFloat)node.node.height);
    CGFloat verticalInset = CjguiComposableNodeUsesLabelTextInset(node.node.nodeKind) ? 2.0 : 6.0;
    NSRect textRect = NSInsetRect(bounds, 7.0, verticalInset);
    if (NSIsEmptyRect(textRect) || textRect.size.width <= 0 || textRect.size.height <= 0) return nil;
    NSMutableParagraphStyle *paragraph = [[NSMutableParagraphStyle alloc] init];
    paragraph.lineBreakMode = node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT
        ? NSLineBreakByWordWrapping : (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT
            ? NSLineBreakByWordWrapping : NSLineBreakByTruncatingTail);
    paragraph.lineBreakStrategy = node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT
        ? NSLineBreakStrategyNone : NSLineBreakStrategyPushOut;
    // Glyph textures are rasterized with an OPAQUE colour and the node's text
    // alpha is re-applied as a per-draw multiplier (CjguiEncodeMetalTexture).
    // This keeps the cached texture and the prepared layout valid across an
    // opacity animation instead of rebuilding TextKit and re-rasterizing every
    // frame; a static colour change still invalidates through the texture key.
    NSColor *textColor = [NSColor colorWithSRGBRed:node.node.textRed green:node.node.textGreen
                                               blue:node.node.textBlue alpha:1.0];
    NSFont *baseFont = CjguiComposableFont(node);
    NSDictionary *attributes = @{ NSFontAttributeName: baseFont,
                                  NSForegroundColorAttributeName: textColor,
                                  NSParagraphStyleAttributeName: paragraph };
    // B4(2026-09-26): the shared prepared layout must carry the node's style
// runs. Since B2 made EVERY text node draw through this prepared TextKit
// stack, run-based paint (selection background, caret tint, inline code)
// was silently dropped here while the non-prepared path still applied it.
// Apply the SAME decoded runs the drawWithRect path uses.
    NSAttributedString *preparedAttributed = nil;
    if (getenv("PHAROS_TRACE_RUNS")) {
        fprintf(stderr, "PHAROS_PREP_RUNS node=%llu rawDataLen=%lu\n",
                (unsigned long long)node.node.nodeId,
                (unsigned long)styleRunData.length);
    }
    styleRunData = CjguiComposableRasterStyleRunData(node, styleRunData);
    if (styleRunData.length >= (NSUInteger)sizeof(CjguiInternalTextStyleRun)) {
        preparedAttributed = CjguiComposableAttributedText(node, displayText ?: @"", attributes,
            (const CjguiInternalTextStyleRun *)styleRunData.bytes,
            (uint32_t)(styleRunData.length / sizeof(CjguiInternalTextStyleRun)));
    }
    NSTextStorage *storage = preparedAttributed
        ? [[NSTextStorage alloc] initWithAttributedString:preparedAttributed]
        : [[NSTextStorage alloc] initWithString:displayText ?: @""
                                     attributes:attributes];
    NSLayoutManager *layoutManager = [NSLayoutManager new];
    [storage addLayoutManager:layoutManager];
    NSSize containerSize = textRect.size;
    // The focused multiline proxy lays out the whole paragraph in a finite
    // width and unbounded height. Keep the inactive shared layout on that
    // same vertical geometry; the node's textRect and tiles still bound what
    // can paint or contribute accepted pixels.
    if (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT)
        containerSize.height = CGFLOAT_MAX;
    NSTextContainer *container = [[NSTextContainer alloc] initWithSize:containerSize];
    container.widthTracksTextView = NO;
    // drawWithRect uses the complete inset rectangle for line breaking. The
    // default TextKit padding would narrow that width by 10pt and move glyphs
    // whenever the same node crosses the single/multiple tile boundary.
    container.lineFragmentPadding = 0.0;
    [layoutManager addTextContainer:container];
    CjguiPreparedTextNodeLayout *prepared = [CjguiPreparedTextNodeLayout new];
    prepared.storage = storage;
    prepared.layoutManager = layoutManager;
    prepared.container = container;
    prepared.textRect = textRect;
    prepared.defaultLineHeight = ceil([layoutManager defaultLineHeightForFont:baseFont]);
    prepared.positionLease = ++gCjguiNextPreparedTextPositionLease; // AppKit work is serialized on main.
    prepared.diagnosticSession = diagnosticSession;
    if (diagnosticSession) {
        diagnosticSession.positionPrepareCount = CjguiSaturatingAddU64(
            diagnosticSession.positionPrepareCount, 1);
        if (timing) diagnosticSession.positionPrepareNanoseconds = CjguiSaturatingAddU64(
            diagnosticSession.positionPrepareNanoseconds,
            CjguiDiagnosticMonotonicNanoseconds() - timingStarted);
    }
    prepared.positionLines = [NSMutableDictionary dictionary];
    return prepared;
}

static BOOL CjguiObserveAllTextSurfaceFrames(void) {
    const char *value = getenv("CJGUI_TEXT_SURFACE_TRACE_ALL_FRAMES");
    return value && strcmp(value, "1") == 0;
}

// AppKit bitmap contexts here produce premultiplied BGRA8. Normalize RGB in
// place for the Metal text sampler. Text tiles are mostly transparent black;
// opaque pixels are also unchanged by the exact integer formula, so skip both
// cases before doing the per-channel division.
static void CjguiNormalizeTextBitmapBGRA(uint8_t *pixels, NSUInteger width,
                                         NSUInteger height, NSUInteger bytesPerRow) {
    if (!pixels || width == 0 || height == 0 || bytesPerRow < width * 4) return;
    for (NSUInteger y = 0; y < height; y++) {
        uint8_t *row = pixels + y * bytesPerRow;
        for (NSUInteger x = 0; x < width; x++) {
            uint8_t *pixel = row + x * 4;
            uint32_t packed = 0;
            memcpy(&packed, pixel, sizeof(packed));
            if (packed == 0) continue;
            uint8_t alpha = pixel[3];
            if (alpha == 255) continue;
            if (alpha == 0) {
                pixel[0] = 0;
                pixel[1] = 0;
                pixel[2] = 0;
                continue;
            }
            pixel[0] = (uint8_t)MIN(255, (pixel[0] * 255 + alpha / 2) / alpha);
            pixel[1] = (uint8_t)MIN(255, (pixel[1] * 255 + alpha / 2) / alpha);
            pixel[2] = (uint8_t)MIN(255, (pixel[2] * 255 + alpha / 2) / alpha);
        }
    }
}

// NOTE(P1 verify): the CjguiInternalTextStyleRun definition was moved above
// CjguiPrepareTextNodeLayout, which takes sizeof of the complete struct; a
// forward declaration alone left it incomplete at the use site.

// Build the attributed string for a node: base attributes plus every run. With
// runCount == 0 this yields exactly the base attributes the single-style path
// uses, which is what makes the "one run covering the whole text" comparison a
// real equivalence check rather than a tautology.
// The product speaks UTF-8 byte offsets (that is what the SourceMap is built
// on), but NSRange is measured in UTF-16 code units. Treating bytes as units
// shifted every run after the first non-ASCII character, so a link or an inline
// code span was coloured in the wrong place (or not visibly at all).
static NSUInteger CjguiComposableUtf16OffsetForByte(const char *utf8, NSUInteger utf8Length,
                                                    NSUInteger byteOffset) {
    if (!utf8) return 0;
    NSUInteger clamped = MIN(byteOffset, utf8Length);
    while (clamped > 0) {
        NSString *prefix = [[NSString alloc] initWithBytes:utf8 length:clamped encoding:NSUTF8StringEncoding];
        if (prefix) return prefix.length;
        // A mid-scalar offset cannot be honoured: walk back to a boundary.
        clamped--;
    }
    return 0;
}

static NSAttributedString *CjguiComposableAttributedText(CJGuiInternalComposableSceneNode *node,
                                                         NSString *displayText,
                                                         NSDictionary *baseAttributes,
                                                         const CjguiInternalTextStyleRun *runs,
                                                         uint32_t runCount) {
    NSMutableAttributedString *attributed = [[NSMutableAttributedString alloc]
        initWithString:displayText attributes:baseAttributes];
    if (!attributed || runCount == 0 || !runs) return attributed;
    NSUInteger length = attributed.length;
    const char *utf8 = displayText.UTF8String;
    NSUInteger utf8Length = utf8 ? strlen(utf8) : 0;
    for (uint32_t i = 0; i < runCount; i++) {
        const CjguiInternalTextStyleRun *run = &runs[i];
        NSUInteger start = MIN(CjguiComposableUtf16OffsetForByte(utf8, utf8Length, run->start), length);
        NSUInteger end = MIN(CjguiComposableUtf16OffsetForByte(utf8, utf8Length, run->end), length);
        if (end <= start) continue;
        NSRange range = NSMakeRange(start, end - start);
        if (run->selectionBackground) {
            // Admission has already proved the exact scalar boundaries and
            // color. This branch precedes every font, foreground, paragraph,
            // and obliqueness write; none of the placeholders has authority.
            NSColor *background = CjguiSelectionBackgroundColorForRun(run);
            [attributed addAttribute:NSBackgroundColorAttributeName value:background range:range];
            continue;
        }
        NSMutableParagraphStyle *paragraph = [[NSMutableParagraphStyle alloc] init];
        paragraph.lineBreakMode = node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT
            ? NSLineBreakByWordWrapping : (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT
                ? NSLineBreakByWordWrapping : NSLineBreakByTruncatingTail);
        // CJK line-break prohibition: push trailing punctuation onto the previous
        // line instead of letting it start a line. Without this the layout
        // orphaned characters like "，" at the beginning of a line.
        paragraph.lineBreakStrategy = NSLineBreakStrategyPushOut;
        NSFont *font = CjguiComposableFontForStyle(run->fontSize, run->fontWeight, run->fontFamily);
        NSColor *color = [NSColor colorWithSRGBRed:run->red green:run->green blue:run->blue alpha:run->alpha];
        [attributed addAttribute:NSFontAttributeName value:font ?: [NSFont systemFontOfSize:13.0] range:range];
        [attributed addAttribute:NSForegroundColorAttributeName value:color range:range];
        [attributed addAttribute:NSParagraphStyleAttributeName value:paragraph range:range];
        if (run->fontFamily == 2 || run->fontFamily == 3) {
            // Synthetic oblique. Asking NSFontManager for an italic face returns
            // the upright system font for San Francisco, so emphasis had no
            // visible slant; NSObliqueness always produces one.
            [attributed addAttribute:NSObliquenessAttributeName value:@0.20 range:range];
        }
        if (run->hasBackground) {
            NSColor *background = [NSColor colorWithSRGBRed:run->backgroundRed
                                                       green:run->backgroundGreen
                                                        blue:run->backgroundBlue
                                                       alpha:run->backgroundAlpha];
            if (background) {
                [attributed addAttribute:NSBackgroundColorAttributeName value:background range:range];
            }
        }
    }
    return attributed;
}

// Decode "start:end:fontSize:weight:family:r:g:b:a;..." into a C array. The
// caller owns the buffer via the returned NSData.
static NSData *CjguiComposableDecodeStyleRuns(NSString *encoded) {
    if (encoded.length == 0) return nil;
    if (CjguiComposableValidateSelectionBackgroundRuns(encoded, nil) != CJGUI_INTERNAL_RENDERER_OK)
        return nil;
    NSMutableData *buffer = [NSMutableData data];
    for (NSString *item in [encoded componentsSeparatedByString:@";"]) {
        if (item.length == 0) continue;
        NSArray<NSString *> *fields = [item componentsSeparatedByString:@":"];
        if (fields.count < 9) continue;
        CjguiInternalTextStyleRun run = {0};
        if (fields.count == 15) {
            // Validation rejects every other extended tag before any decode;
            // an unknown extension cannot be reinterpreted as an ordinary run.
            if (CjguiSelectionBackgroundRunFromFields(fields, &run) != CJGUI_INTERNAL_RENDERER_OK)
                return nil;
            [buffer appendBytes:&run length:sizeof(run)];
            continue;
        }
        run.start = (uint32_t)fields[0].intValue;
        run.end = (uint32_t)fields[1].intValue;
        run.fontSize = fields[2].doubleValue;
        run.fontWeight = (uint32_t)fields[3].intValue;
        run.fontFamily = (uint32_t)fields[4].intValue;
        run.red = fields[5].floatValue;
        run.green = fields[6].floatValue;
        run.blue = fields[7].floatValue;
        run.alpha = fields[8].floatValue;
        if (fields.count >= 13) {
            run.hasBackground = (uint32_t)fields[9].intValue;
            run.backgroundRed = fields[10].floatValue;
            run.backgroundGreen = fields[11].floatValue;
            run.backgroundBlue = fields[12].floatValue;
            run.backgroundAlpha = fields.count >= 14 ? fields[13].floatValue : 1.0f;
        }
        [buffer appendBytes:&run length:sizeof(run)];
    }
    return buffer.length > 0 ? buffer : nil;
}

static CjguiTextPreparationWorkerInput *CjguiCreateTextPreparationWorkerInput(
    CJGuiInternalSession *ctx, CjguiComposablePreparation *preparation,
    CJGuiInternalComposableSceneNode *node, NSString *body, NSString *encodedRuns,
    uint64_t *outReservedBytes) {
    if (outReservedBytes) *outReservedBytes = 0;
    if (!ctx || !preparation || !node || !body || body.length < 1024 ||
        body.length > CjguiTextPreparationWorkerMaxUtf16Length ||
        (node.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT &&
         node.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) ||
        !CjguiTextPreparationRawGeometryVisible(node)) return nil;
    const char *utf8 = body.UTF8String;
    NSUInteger utf8Length = utf8 ? strlen(utf8) : NSUIntegerMax;
    if (!utf8 || utf8Length > 65536) return nil;
    NSData *decoded = CjguiComposableDecodeStyleRuns(encodedRuns ?: @"");
    uint64_t styleRunCount = decoded.length / sizeof(CjguiInternalTextStyleRun);
    uint64_t estimate = (uint64_t)body.length * 256u + (uint64_t)utf8Length +
        styleRunCount * 2048u + 262144u;
    if (estimate > CjguiTextPreparationWorkerMaxBytesPerJob) return nil;

    NSRect bounds = NSMakeRect(0.0, 0.0, node.node.width, node.node.height);
    CGFloat verticalInset = CjguiComposableNodeUsesLabelTextInset(node.node.nodeKind) ? 2.0 : 6.0;
    NSRect textRect = NSInsetRect(bounds, 7.0, verticalInset);
    if (NSIsEmptyRect(textRect) || NSWidth(textRect) <= 0 || NSHeight(textRect) <= 0) return nil;
    NSFont *font = CjguiComposableFont(node);
    if (!font) return nil;
    NSMutableParagraphStyle *paragraph = [[NSMutableParagraphStyle alloc] init];
    paragraph.lineBreakMode = NSLineBreakByWordWrapping;
    paragraph.lineBreakStrategy = node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT
        ? NSLineBreakStrategyNone : NSLineBreakStrategyPushOut;
    NSColor *color = [NSColor colorWithSRGBRed:node.node.textRed green:node.node.textGreen
        blue:node.node.textBlue alpha:1.0];
    NSDictionary *attributes = @{NSFontAttributeName: font,
        NSForegroundColorAttributeName: color,
        NSParagraphStyleAttributeName: paragraph};
    NSData *rasterRuns = CjguiComposableRasterStyleRunData(node, decoded);
    NSAttributedString *attributed = nil;
    if (rasterRuns.length >= sizeof(CjguiInternalTextStyleRun)) {
        attributed = CjguiComposableAttributedText(node, body, attributes,
            (const CjguiInternalTextStyleRun *)rasterRuns.bytes,
            (uint32_t)(rasterRuns.length / sizeof(CjguiInternalTextStyleRun)));
    } else {
        attributed = [[NSAttributedString alloc] initWithString:body attributes:attributes];
    }
    if (!attributed || ![attributed.string isEqualToString:body]) return nil;

    CjguiTextPreparationWorkerInput *input = [CjguiTextPreparationWorkerInput new];
    input.sessionToken = preparation.sessionToken;
    input.sessionGeneration = preparation.sessionGeneration;
    input.preparationId = preparation.preparationId;
    input.baseSceneVersion = preparation.baseSceneVersion;
    input.projectionVersion = preparation.projectionVersion;
    input.bindingEpoch = preparation.bindingEpoch;
    input.nodeId = node.node.nodeId;
    input.nodeKind = node.node.nodeKind;
    input.node = node.node;
    input.geometry = node.geometry;
    input.body = body;
    input.baseFont = font;
    input.extentAttributes = attributes;
    input.sourceAttributedBody = attributed;
    input.textRect = textRect;
    NSSize containerSize = textRect.size;
    // Make the normal TEXT graph's effective TextKit defaults explicit in the
    // immutable input identity. This is the same configuration used by the
    // accepted painter (zero padding, wrapping, unbounded lines/height, and
    // the renderer's noncontiguous-layout choice); stating it here lets a
    // fully retired private graph be matched without weakening identity.
    input.sourceGraphConfigurationPresent = YES;
    input.containerPadding = 0.0;
    input.containerLineBreakMode = NSLineBreakByWordWrapping;
    input.containerMaximumNumberOfLines = 0;
    input.containerHeightTracksTextView = NO;
    input.layoutAllowsNonContiguous = NO;
    input.layoutUsesFontLeading = YES;
    if (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) {
        containerSize.height = CGFLOAT_MAX;
    }
    input.containerSize = containerSize;
    input.scale = preparation.scale;
    input.appearanceName = NSApp.effectiveAppearance.name ?: @"";
    if (outReservedBytes) *outReservedBytes = estimate;
    return input;
}

// Selection-only runs are painted from the candidate's own immutable TextKit
// layout. A nil result means that visible geometry could not be proved; the
// candidate must fail rather than display stale or partly updated selection.
static _Atomic(uint32_t) gCjguiSelectionDecorationNilTraceCount = 0;
static BOOL CjguiSelectionDecorationNilTraceHasCapacity(void) {
    const uint32_t capacity = 128;
    uint32_t current = atomic_load_explicit(&gCjguiSelectionDecorationNilTraceCount,
        memory_order_relaxed);
    while (current < capacity) {
        if (atomic_compare_exchange_weak_explicit(&gCjguiSelectionDecorationNilTraceCount,
            &current, current + 1, memory_order_relaxed, memory_order_relaxed)) return YES;
    }
    return NO;
}
static NSArray<NSDictionary *> *CjguiComposableDeclaredSelectionDecorations(
    CJGuiInternalComposableSceneNode *node, NSData *decoded) {
#define CJGUI_TRACE_DECLARED_SELECTION_NIL(branchName, actualValue, expectedValue, detailA, detailB) do { \
    if ((getenv("CJGUI_CANDIDATE_FIRST_FAILURE") || getenv("CJGUI_TEXT_PREPARE_TRACE")) && \
        CjguiSelectionDecorationNilTraceHasCapacity()) \
        fprintf(stderr, "CJGUI_SELECTION_DECORATION_NIL branch=%s node=%llu actual=%llu expected=%llu " \
            "decoded_bytes=%lu run_count=%lu storage_chars=%lu glyphs=%lu container=%d " \
            "geometry=%lldx%lld detail_a=%llu detail_b=%llu\n", (branchName), \
            (unsigned long long)(node ? node.node.nodeId : 0), \
            (unsigned long long)(actualValue), (unsigned long long)(expectedValue), \
            (unsigned long)(decoded.length), \
            (unsigned long)(decoded.length / sizeof(CjguiInternalTextStyleRun)), \
            (unsigned long)node.preparedTextLayout.storage.string.length, \
            (unsigned long)node.preparedTextLayout.layoutManager.numberOfGlyphs, \
            node.preparedTextLayout.container != nil, (long long)node.node.width, \
            (long long)node.node.height, (unsigned long long)(detailA), \
            (unsigned long long)(detailB)); \
} while (0)
    if (node.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT || !decoded.length) return @[];
    const CjguiInternalTextStyleRun *runs = decoded.bytes;
    NSUInteger count = decoded.length / sizeof(CjguiInternalTextStyleRun);
    BOOL hasSelection = NO;
    for (NSUInteger index = 0; index < count; index++) hasSelection |= runs[index].selectionBackground != 0;
    if (!hasSelection) return @[];
    // Clipped text deliberately owns no prepared glyph graph. A document-wide
    // source choice can still include it; only visible fragments need paint
    // geometry. This test uses accepted node/clip geometry and cannot trigger
    // measurement or borrow another fragment's layout.
    if (NSIsEmptyRect(CjguiComposableTextTextureRectForNodeWithText(node, node.value))) return @[];
    CjguiPreparedTextNodeLayout *prepared = node.preparedTextLayout;
    if (!prepared.storage || !prepared.layoutManager || !prepared.container ||
        ![prepared.storage.string isEqualToString:node.value ?: @""]) {
        CJGUI_TRACE_DECLARED_SELECTION_NIL("layout_identity", prepared.storage != nil, 1,
            prepared.layoutManager != nil, prepared.container != nil);
        return nil;
    }
    NSString *body = prepared.storage.string;
    if (body.length == 0) return @[];
    NSMutableAttributedString *colors = [[NSMutableAttributedString alloc] initWithString:body];
    const char *utf8 = body.UTF8String;
    NSUInteger utf8Length = utf8 ? strlen(utf8) : 0;
    for (NSUInteger index = 0; index < count; index++) {
        const CjguiInternalTextStyleRun *run = &runs[index];
        if (!run->selectionBackground) continue;
        NSUInteger start = MIN(CjguiComposableUtf16OffsetForByte(utf8, utf8Length, run->start), body.length);
        NSUInteger end = MIN(CjguiComposableUtf16OffsetForByte(utf8, utf8Length, run->end), body.length);
        if (end <= start) {
            CJGUI_TRACE_DECLARED_SELECTION_NIL("empty_span", end, start + 1, start, end);
            return nil;
        }
        NSColor *color = CjguiSelectionBackgroundColorForRun(run);
        if (!color) {
            CJGUI_TRACE_DECLARED_SELECTION_NIL("color_creation", 0, 1, index,
                (uint64_t)llround(run->backgroundAlpha * 1000000.0));
            if (getenv("CJGUI_CANDIDATE_FIRST_FAILURE") || getenv("CJGUI_TEXT_PREPARE_TRACE"))
                fprintf(stderr, "CJGUI_SELECTION_DECORATION_COLOR node=%llu run=%lu rgba=%.6f,%.6f,%.6f,%.6f\n",
                    (unsigned long long)node.node.nodeId, (unsigned long)index,
                    run->backgroundRed, run->backgroundGreen, run->backgroundBlue, run->backgroundAlpha);
            return nil;
        }
        [colors addAttribute:NSBackgroundColorAttributeName value:color range:NSMakeRange(start, end - start)];
    }
    NSRect nodeRect = CjguiComposableVisualNodeRect(node);
    NSRect textRect = NSOffsetRect(prepared.textRect, NSMinX(nodeRect), NSMinY(nodeRect));
    NSRect visible = NSIntersectionRect(textRect, CjguiComposableVisualClipBounds(node));
    if (NSIsEmptyRect(visible)) return @[];
    NSRect visibleLocal = NSOffsetRect(visible, -NSMinX(textRect), -NSMinY(textRect));
    NSLayoutManager *layout = prepared.layoutManager;
    NSTextContainer *container = prepared.container;
    NSRange visibleGlyphs = [layout glyphRangeForBoundingRect:visibleLocal inTextContainer:container];
    if (visibleGlyphs.length == 0) return @[];
    NSRange visibleCharacters = [layout characterRangeForGlyphRange:visibleGlyphs actualGlyphRange:NULL];
    visibleCharacters = NSIntersectionRange(visibleCharacters, NSMakeRange(0, body.length));
    NSMutableArray<NSDictionary *> *decorations = [NSMutableArray array];
    [colors enumerateAttribute:NSBackgroundColorAttributeName inRange:visibleCharacters options:0
                    usingBlock:^(id color, NSRange characters, BOOL *stop) {
        if (!color || ![color isKindOfClass:NSColor.class] || *stop) return;
        NSRange glyphs = [layout glyphRangeForCharacterRange:characters actualCharacterRange:NULL];
        glyphs = NSIntersectionRange(glyphs, visibleGlyphs);
        if (glyphs.length == 0) return;
        [layout enumerateLineFragmentsForGlyphRange:glyphs usingBlock:^(NSRect lineRect, NSRect usedRect,
            NSTextContainer *lineContainer, NSRange lineGlyphs, BOOL *lineStop) {
            (void)lineRect; (void)usedRect; (void)lineContainer;
            NSRange onLine = NSIntersectionRange(glyphs, lineGlyphs);
            if (onLine.length == 0) return;
            NSRect rect = [layout boundingRectForGlyphRange:onLine inTextContainer:container];
            rect = NSIntersectionRect(NSOffsetRect(rect, NSMinX(textRect), NSMinY(textRect)), visible);
            if (!NSIsEmptyRect(rect)) [decorations addObject:@{@"rect":[NSValue valueWithRect:rect], @"color":color}];
            if (decorations.count > 1024) { *lineStop = YES; *stop = YES; }
        }];
    }];
    if (decorations.count > 1024)
        CJGUI_TRACE_DECLARED_SELECTION_NIL("rect_budget", decorations.count, 1024,
            visibleGlyphs.length, visibleCharacters.length);
#undef CJGUI_TRACE_DECLARED_SELECTION_NIL
    return decorations.count > 1024 ? nil : [decorations copy];
}

static id<MTLTexture> CjguiRasterComposableTextTexture(CJGuiInternalMetalView *metalView,
                                                        CJGuiInternalComposableSceneNode *node,
                                                        CGFloat scaleX, CGFloat scaleY,
                                                        NSString *displayText,
                                                        NSRect textureRect,
                                                        uint64_t *outByteCount,
                                                        CjguiPreparedTextNodeLayout *prepared
#ifdef CJGUI_INTERNAL_TESTING
                                                        , CjguiInternalTextWorkReason reason
#endif
                                                        , const CjguiInternalTextStyleRun *styleRuns
                                                        , uint32_t styleRunCount
                                                        ) {
    if (outByteCount) *outByteCount = 0;
    uint64_t rasterStarted = CjguiMonotonicMicros();
    CJGuiInternalSession *diagnosticSession = CjguiLookupSession(metalView.sessionToken);
    BOOL diagnosticTiming = diagnosticSession && diagnosticSession.diagnosticTimingEnabled;
    uint64_t diagnosticRasterStarted = diagnosticTiming ? CjguiDiagnosticMonotonicNanoseconds() : 0;
    if (!metalView.device || !node || node.node.width <= 0 || node.node.height <= 0) return nil;
    NSString *text = displayText ?: @"";
    if (text.length == 0 || node.node.textAlpha <= 0.0) return nil;
    NSUInteger width = 0, height = 0, bytesPerRow = 0;
    uint64_t byteCount = 0;
    if (NSIsEmptyRect(textureRect)) return nil;
    if (!CjguiCheckedComposableTextTextureBytes(NSWidth(textureRect), NSHeight(textureRect),
                                                scaleX, scaleY, &width, &height, &bytesPerRow, &byteCount)) return nil;
    // The AppKit bitmap and Metal upload share one bounded BGRA allocation.
    // Normalize premultiplied components in place before upload instead of
    // retaining a second full-sized conversion buffer.
    NSMutableData *bgra = [NSMutableData dataWithLength:(NSUInteger)byteCount];
    CjguiAddTextCpuScratch(metalView, bgra ? byteCount : 0);
    CGColorSpaceRef colorSpace = CGColorSpaceCreateWithName(kCGColorSpaceSRGB);
    CGContextRef bitmapContext = colorSpace ? CGBitmapContextCreate(bgra.mutableBytes, width, height, 8, bytesPerRow,
        colorSpace, kCGImageAlphaPremultipliedFirst | kCGBitmapByteOrder32Little) : NULL;
    if (colorSpace) CGColorSpaceRelease(colorSpace);
    NSGraphicsContext *context = bitmapContext ? [NSGraphicsContext graphicsContextWithCGContext:bitmapContext flipped:YES] : nil;
    if (!bgra || !bitmapContext || !context) {
        if (bitmapContext) CGContextRelease(bitmapContext);
        CjguiDropTextCpuScratch(metalView, byteCount);
        return nil;
    }
    NSMutableParagraphStyle *paragraph = [[NSMutableParagraphStyle alloc] init];
    paragraph.lineBreakMode = node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT
        ? NSLineBreakByWordWrapping : (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT
            ? NSLineBreakByWordWrapping : NSLineBreakByTruncatingTail);
    paragraph.lineBreakStrategy = node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT
        ? NSLineBreakStrategyNone : NSLineBreakStrategyPushOut;
    // Glyph textures are rasterized with an OPAQUE colour and the node's text
    // alpha is re-applied as a per-draw multiplier (CjguiEncodeMetalTexture).
    // This keeps the cached texture and the prepared layout valid across an
    // opacity animation instead of rebuilding TextKit and re-rasterizing every
    // frame; a static colour change still invalidates through the texture key.
    NSColor *textColor = [NSColor colorWithSRGBRed:node.node.textRed green:node.node.textGreen
                                               blue:node.node.textBlue alpha:1.0];
    NSFont *baseFont = CjguiComposableFont(node);
    NSDictionary *attributes = @{ NSFontAttributeName: baseFont,
                                  NSForegroundColorAttributeName: textColor,
                                  NSParagraphStyleAttributeName: paragraph };
    NSGraphicsContext *previousContext = NSGraphicsContext.currentContext;
    [NSGraphicsContext setCurrentContext:context];
    [NSGraphicsContext saveGraphicsState];
    NSAffineTransform *transform = [NSAffineTransform transform];
    [transform scaleXBy:scaleX yBy:scaleY];
    // Keep the original node-local layout width.  Only the backing bitmap is
    // translated to the resolved visible tile, so line wrapping and selection
    // geometry do not reflow when an ancestor clip moves.
    [transform translateXBy:(NSMinX(textureRect) - (CGFloat)node.node.x) * -1.0
                       yBy:(NSMinY(textureRect) - (CGFloat)node.node.y) * -1.0];
    [transform concat];
    NSRect bounds = NSMakeRect(0.0, 0.0, (CGFloat)node.node.width, (CGFloat)node.node.height);
    CGFloat verticalInset = CjguiComposableNodeUsesLabelTextInset(node.node.nodeKind) ? 2.0 : 6.0;
    NSRect textRect = NSInsetRect(bounds, 7.0, verticalInset);
#ifdef CJGUI_INTERNAL_TESTING
    // `drawWithRect` fuses layout and glyph drawing in one AppKit API, so this
    // interval is honest "draw-with-layout" work only. Splitting layout from
    // drawing requires the explicit TextKit path and is NOT claimed here.
    uint64_t drawStarted = CjguiMonotonicMicros();
#endif
    if (prepared) {
        // Shared-layout tile draw: the candidate prepared this node's TextKit
        // stack once, so this tile only draws the glyphs whose bounding rect
        // intersects it — no per-tile full-string layout.
        // textureRect is in scene coordinates; TextKit's container begins at
        // the node-local inset. Subtract both origins before selecting glyphs.
        NSRect tileInContainer = NSMakeRect(textureRect.origin.x - (CGFloat)node.node.x - prepared.textRect.origin.x,
                                            textureRect.origin.y - (CGFloat)node.node.y - prepared.textRect.origin.y,
                                            textureRect.size.width, textureRect.size.height);
        NSRange glyphRange = [prepared.layoutManager
            glyphRangeForBoundingRect:tileInContainer inTextContainer:prepared.container];
        if (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) {
            // Match the focused tile path: glyphs may contribute only inside
            // the node's inset text area and this tile. Bitmap bounds alone
            // also admit antialias fringe outside the textRect.
            NSRect tileInNode = NSOffsetRect(textureRect,
                -(CGFloat)node.node.x, -(CGFloat)node.node.y);
            NSRect visibleTextRect = NSIntersectionRect(prepared.textRect, tileInNode);
            if (!NSIsEmptyRect(visibleTextRect)) NSRectClip(visibleTextRect);
        }
        // B4(2026-09-26, Sol consult): AppKit splits run backgrounds and glyphs into
        // TWO draw calls on NSLayoutManager. Drawing glyphs only silently dropped every
        // run-based paint on this shared-layout path -- selection background, caret tint,
        // inline-code background (pixel-identical screenshots even with an opaque red
        // selection run). Background first, then glyphs, same range and origin.
        [prepared.layoutManager drawBackgroundForGlyphRange:glyphRange
                                                    atPoint:prepared.textRect.origin];
        [prepared.layoutManager drawGlyphsForGlyphRange:glyphRange
                                                atPoint:prepared.textRect.origin];
    } else {
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t drawStarted = CjguiMonotonicMicros();
#endif
    if (styleRunCount == 0) {
        // A scene node may carry its runs through the session table instead.
        CJGuiInternalSession *sessionContext = CjguiLookupSession(metalView.sessionToken);
        NSData *decoded = CjguiComposableDecodeStyleRuns(
            sessionContext.composableTextStyleRunsRaw[@(node.node.nodeId)]);
        if (getenv("PHAROS_TRACE_RUNS")) {
            fprintf(stderr, "PHAROS_RUNS_CONSUME node=%llu token=%llu bytes=%lu\n",
                    (unsigned long long)node.node.nodeId,
                    (unsigned long long)metalView.sessionToken, (unsigned long)decoded.length);
        }
        if (decoded.length > 0) {
            styleRuns = (const CjguiInternalTextStyleRun *)decoded.bytes;
            styleRunCount = (uint32_t)(decoded.length / sizeof(CjguiInternalTextStyleRun));
            // The runs are part of the texture key. Stamp them on the very node
            // being rasterized, so a run-only change (a caret mark, a tint, a new
            // bold span) invalidates the cached texture on the next frame.
            node.styleRunsSignature = sessionContext.composableTextStyleRunsRaw[@(node.node.nodeId)];
        }
    }
    if (styleRunCount > 0) {
        NSData *rasterRuns = CjguiComposableRasterStyleRunData(node,
            [NSData dataWithBytes:styleRuns length:(NSUInteger)styleRunCount * sizeof(CjguiInternalTextStyleRun)]);
        NSAttributedString *attributed = CjguiComposableAttributedText(node, text, attributes,
            rasterRuns.bytes, (uint32_t)(rasterRuns.length / sizeof(CjguiInternalTextStyleRun)));
        [attributed drawWithRect:textRect
                         options:NSStringDrawingUsesLineFragmentOrigin | NSStringDrawingUsesFontLeading];
    } else {
        // Unchanged single-style path: no attributed string is built at all.
        [text drawWithRect:textRect
                   options:NSStringDrawingUsesLineFragmentOrigin | NSStringDrawingUsesFontLeading
                attributes:attributes];
    }
#ifdef CJGUI_INTERNAL_TESTING
    metalView.testComposableTextStaticDrawWithLayoutMicros = CjguiSaturatingAddU64(
        metalView.testComposableTextStaticDrawWithLayoutMicros, CjguiMonotonicMicros() - drawStarted);
#endif
    }
    [NSGraphicsContext restoreGraphicsState];
    [NSGraphicsContext setCurrentContext:previousContext];

    uint8_t *pixels = bgra.mutableBytes;
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t normalizeStarted = CjguiMonotonicMicros();
#endif
    CjguiNormalizeTextBitmapBGRA(pixels, width, height, bytesPerRow);
#ifdef CJGUI_INTERNAL_TESTING
    metalView.testComposableTextNormalizeMicros = CjguiSaturatingAddU64(
        metalView.testComposableTextNormalizeMicros, CjguiMonotonicMicros() - normalizeStarted);
#endif
    CGContextRelease(bitmapContext);
    MTLTextureDescriptor *descriptor = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm
                                                                                            width:width height:height mipmapped:NO];
    descriptor.usage = MTLTextureUsageShaderRead;
    descriptor.storageMode = MTLStorageModeShared;
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t textureCreateStarted = CjguiMonotonicMicros();
#endif
    id<MTLTexture> texture = [metalView.device newTextureWithDescriptor:descriptor];
#ifdef CJGUI_INTERNAL_TESTING
    metalView.testComposableTextTextureCreateMicros = CjguiSaturatingAddU64(
        metalView.testComposableTextTextureCreateMicros, CjguiMonotonicMicros() - textureCreateStarted);
#endif
    if (!texture) {
        CjguiDropTextCpuScratch(metalView, byteCount);
        return nil;
    }
    uint64_t workloadUploadStarted = CjguiMonotonicMicros();
    uint64_t diagnosticUploadStarted = diagnosticTiming ? CjguiDiagnosticMonotonicNanoseconds() : 0;
    if (diagnosticTiming) diagnosticSession.diagnosticRasterNanoseconds = CjguiSaturatingAddU64(
        diagnosticSession.diagnosticRasterNanoseconds, diagnosticUploadStarted - diagnosticRasterStarted);
    metalView.textRasterCount = CjguiSaturatingAddU64(metalView.textRasterCount, 1);
    metalView.textRasterBytes = CjguiSaturatingAddU64(metalView.textRasterBytes, byteCount);
    metalView.textRasterMicros = CjguiSaturatingAddU64(metalView.textRasterMicros,
                                                        workloadUploadStarted - rasterStarted);
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t uploadStarted = workloadUploadStarted;
    CjguiRecordTextWork(metalView, node.node.projectionVersion,
                        [displayText lengthOfBytesUsingEncoding:NSUTF8StringEncoding], reason);
    metalView.testComposableTextRasterCount = CjguiSaturatingAddU64(metalView.testComposableTextRasterCount, 1);
    metalView.testComposableTextRasterBytes = CjguiSaturatingAddU64(metalView.testComposableTextRasterBytes, byteCount);
    metalView.testComposableTextRasterMicros = CjguiSaturatingAddU64(metalView.testComposableTextRasterMicros,
                                                                       uploadStarted - rasterStarted);
#endif
    [texture replaceRegion:MTLRegionMake2D(0, 0, width, height) mipmapLevel:0 withBytes:bgra.bytes bytesPerRow:bytesPerRow];
    uint64_t diagnosticUploadEnded = diagnosticTiming ? CjguiDiagnosticMonotonicNanoseconds() : 0;
    if (diagnosticTiming) diagnosticSession.diagnosticUploadNanoseconds = CjguiSaturatingAddU64(
        diagnosticSession.diagnosticUploadNanoseconds, diagnosticUploadEnded - diagnosticUploadStarted);
    uint64_t workloadUploadEnded = CjguiMonotonicMicros();
    metalView.textUploadCount = CjguiSaturatingAddU64(metalView.textUploadCount, 1);
    metalView.textUploadBytes = CjguiSaturatingAddU64(metalView.textUploadBytes, byteCount);
    metalView.textUploadMicros = CjguiSaturatingAddU64(metalView.textUploadMicros,
                                                        workloadUploadEnded - workloadUploadStarted);
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t uploadEnded = workloadUploadEnded;
    metalView.testComposableTextUploadCount = CjguiSaturatingAddU64(metalView.testComposableTextUploadCount, 1);
    metalView.testComposableTextUploadBytes = CjguiSaturatingAddU64(metalView.testComposableTextUploadBytes, byteCount);
    metalView.testComposableTextUploadMicros = CjguiSaturatingAddU64(metalView.testComposableTextUploadMicros,
                                                                       uploadEnded - uploadStarted);
#endif
    CjguiDropTextCpuScratch(metalView, byteCount);
    if (outByteCount) *outByteCount = byteCount;
    return texture;
}

static CjguiInternalRendererStatus CjguiCandidateFailure(CJGuiInternalSession *ctx,
    CjguiInternalRendererStatus status, const char *branch, uint64_t actual, uint64_t expected);

static id<MTLTexture> CjguiComposableTextTexture(CJGuiInternalMetalView *metalView,
                                                  CJGuiInternalComposableSceneNode *node,
                                                  CGFloat scaleX, CGFloat scaleY,
                                                  NSString *displayText
#ifdef CJGUI_INTERNAL_TESTING
                                                  , CjguiInternalTextWorkReason reason
#endif
                                                  ) {
    CJGuiInternalSession *candidateCtx = metalView
        ? CjguiLookupSession(metalView.sessionToken) : nil;
#define CJGUI_RECORD_COMPOSABLE_TEXTURE_FAILURE(name, actualValue, expectedValue) do { \
    char candidateFailureBranch[128]; \
    snprintf(candidateFailureBranch, sizeof(candidateFailureBranch), "%s/node=%llu", (name), \
        (unsigned long long)(node ? node.node.nodeId : 0)); \
    (void)CjguiCandidateFailure(candidateCtx, CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR, \
        candidateFailureBranch, (uint64_t)(actualValue), (uint64_t)(expectedValue)); \
} while (0)
    NSRect textureRect = CjguiComposableTextTextureRectForNodeWithText(node, displayText);
    if (NSIsEmptyRect(textureRect)) {
        CJGUI_RECORD_COMPOSABLE_TEXTURE_FAILURE("text_texture.empty_rect", 0, 1);
        return nil;
    }
    NSString *key = CjguiComposableTextTextureKey(node, scaleX, scaleY, displayText, textureRect);
    if (key.length == 0) {
        CJGUI_RECORD_COMPOSABLE_TEXTURE_FAILURE("text_texture.empty_key", key.length, 1);
        return nil;
    }
    uint64_t plannedBytes = 0;
    NSArray<NSValue *> *tiles = CjguiPlanComposableTextTiles(textureRect,
        CjguiComposableTextNodeLayoutRect(node), scaleX, &plannedBytes);
    if (tiles.count == 0 || plannedBytes == 0) {
        CJGUI_RECORD_COMPOSABLE_TEXTURE_FAILURE("text_texture.no_tiles", tiles.count, plannedBytes);
        return nil;
    }
    // M1（resize 层失效）：tile 覆盖提前复用同样要求**容器宽度未变**——同文字
    // 改宽时 tile 纹理可逐像素复用，但持留排版必须按新宽度重排，否则几何查询
    // 以旧宽度排版作答。
    BOOL retainedLayoutWidthMatches = NO;
    if (node.preparedTextLayout.container) {
        NSRect coverBounds = NSMakeRect(0.0, 0.0, (CGFloat)node.node.width, (CGFloat)node.node.height);
        CGFloat coverInset = CjguiComposableNodeUsesLabelTextInset(node.node.nodeKind) ? 2.0 : 6.0;
        retainedLayoutWidthMatches =
            fabs(node.preparedTextLayout.container.size.width -
                 NSWidth(NSInsetRect(coverBounds, 7.0, coverInset))) < 0.001;
    }
    CjguiTextRasterSourceCredential *retainedSource = retainedLayoutWidthMatches
        ? CjguiCreateTextRasterSourceCredential(node, node.preparedTextLayout.storage,
            node.preparedTextLayout.layoutManager, node.preparedTextLayout.container, nil,
            nil, scaleX, textureRect, tiles, NSMakePoint((CGFloat)node.node.x, (CGFloat)node.node.y),
            0.0, 0, 0) : nil;
    BOOL retainedSourceMatches = CjguiTextRasterSourceCredentialsEqual(
        node.textTextureSourceCredential, retainedSource);
    if (retainedLayoutWidthMatches && retainedSourceMatches &&
        CjguiComposableTextTilesAlreadyCovered(node, key, tiles, scaleX)) {
        node.textTileRects = tiles.count > 1 ? tiles : nil;
        node.textTextureRect = tiles.count == 1 ? tiles.firstObject.rectValue : CjguiComposableTextTileUnion(tiles);
        node.textTileLayoutOrigin = NSMakePoint((CGFloat)node.node.x, (CGFloat)node.node.y);
        id<MTLTexture> retainedTexture = node.textTexture ?: node.textTileTextures.firstObject;
        if (!retainedTexture) {
            CJGUI_RECORD_COMPOSABLE_TEXTURE_FAILURE("text_texture.covered_resource_nil",
                node.textTileTextures.count, 1);
            return nil;
        }
        return retainedTexture;
    }
    NSMutableArray<id<MTLTexture>> *prepared = [NSMutableArray arrayWithCapacity:tiles.count];
    uint64_t actualBytes = 0;
    // Multiline text uses one candidate-scoped TextKit layout regardless of
    // tile count. Otherwise a narrow single tile takes drawWithRect's full
    // document layout while the same node split into two tiles stays bounded.
    // Small single-tile controls retain their fused drawWithRect path.
    // 2026-09-26(B2):**所有文本节点一律准备并持留排版产物** —— 契约要求几何查询
    // "取自绘制实际使用的 accepted 排版、且查询不重排",故每个文本节点都必须有可查索引;
    // 原先只覆盖多行 / 多 tile,导致单 tile 文本走 drawWithRect、查询恒得 GEOMETRY_EMPTY(实测 2 MiB 夹具)。
    BOOL needsSharedLayout = YES;
    // M1（resize 层失效）：持留排版只在**容器宽度未变**时复用——缓存键含文字/
    // 样式/缩放但不含节点宽度，同文字改宽（resize）会把旧宽度排的版当当前事实
    // 回答（native 反例：宽 160→320 后同字节区段行数不变）。
    CGFloat reusedContentWidth = 0.0;
    if (node.preparedTextLayout.container) {
        NSRect reuseBounds = NSMakeRect(0.0, 0.0, (CGFloat)node.node.width, (CGFloat)node.node.height);
        CGFloat reuseInset = CjguiComposableNodeUsesLabelTextInset(node.node.nodeKind) ? 2.0 : 6.0;
        reusedContentWidth = NSWidth(NSInsetRect(reuseBounds, 7.0, reuseInset));
    }
    CjguiPreparedTextNodeLayout *sharedLayout =
        ([node.textTextureCacheKey isEqualToString:key] && node.preparedTextLayout.container &&
         fabs(node.preparedTextLayout.container.size.width - reusedContentWidth) < 0.001)
        ? node.preparedTextLayout : nil;
    if (!sharedLayout) sharedLayout = needsSharedLayout ?
        CjguiPrepareTextNodeLayout(node, displayText, scaleX,
            CjguiComposableDecodeStyleRuns(
                [CjguiLookupSession(metalView.sessionToken) composableTextStyleRunsRaw][@(node.node.nodeId)]),
            CjguiLookupSession(metalView.sessionToken)) : nil;
#ifdef CJGUI_INTERNAL_TESTING
    if (needsSharedLayout && metalView.testForceSharedTextLayoutNilOnce) {
        metalView.testForceSharedTextLayoutNilOnce = NO;
        sharedLayout = nil;
    }
#endif
    if (needsSharedLayout && !sharedLayout) {
        NSRect bounds = NSMakeRect(0.0, 0.0, (CGFloat)node.node.width, (CGFloat)node.node.height);
        CGFloat verticalInset = CjguiComposableNodeUsesLabelTextInset(node.node.nodeKind) ? 2.0 : 6.0;
        NSRect textRect = NSInsetRect(bounds, 7.0, verticalInset);
        // An empty inset has no glyphs to prepare. For a drawable text area,
        // nil means preparation failed: reject the candidate instead of
        // silently switching the multiline node to per-tile drawWithRect.
        if (!NSIsEmptyRect(textRect) && textRect.size.width > 0 && textRect.size.height > 0) {
            CJGUI_RECORD_COMPOSABLE_TEXTURE_FAILURE("text_texture.layout_prepare_nil",
                (uint64_t)node.node.width, (uint64_t)node.node.height);
            return nil;
        }
    }
    CjguiTextRasterSourceCredential *candidateSource = sharedLayout
        ? CjguiCreateTextRasterSourceCredential(node, sharedLayout.storage,
            sharedLayout.layoutManager, sharedLayout.container, nil, nil, scaleX, textureRect,
            tiles, NSMakePoint((CGFloat)node.node.x, (CGFloat)node.node.y), 0.0, 0, 0) : nil;
    CjguiPreparedTextNodeLayout *sealedRasterLayout = candidateSource
        ? CjguiCreateSealedRasterLayout(candidateSource) : nil;
    if (candidateSource && !sealedRasterLayout) candidateSource = nil;
    CjguiPreparedTextNodeLayout *painterLayout = sealedRasterLayout ?: sharedLayout;
    BOOL sourceMatchesRetainedTiles = CjguiTextRasterSourceCredentialsEqual(
        node.textTextureSourceCredential, candidateSource);
    for (NSValue *rectValue in tiles) {
        @autoreleasepool {
            id<MTLTexture> retained = sourceMatchesRetainedTiles
                ? CjguiComposableRetainedTextTile(node, key, rectValue.rectValue, scaleX) : nil;
            if (retained) {
                uint64_t retainedBytes = (uint64_t)retained.width * (uint64_t)retained.height * 4u;
                [prepared addObject:retained];
                actualBytes += retainedBytes;
                continue;
            }
            uint64_t tileBytes = 0;
            id<MTLTexture> texture = CjguiRasterComposableTextTexture(metalView, node, scaleX, scaleY, displayText,
                                                               rectValue.rectValue, &tileBytes,
                                                               painterLayout
#ifdef CJGUI_INTERNAL_TESTING
                                                               , reason
#endif
                                                               , NULL, 0);
            if (!texture || tileBytes == 0) {
                CJGUI_RECORD_COMPOSABLE_TEXTURE_FAILURE(
                    texture ? "text_texture.tile_raster_zero_bytes" : "text_texture.tile_raster_nil",
                    texture ? tileBytes : 0, 1);
                return nil;
            }
            [prepared addObject:texture];
            actualBytes += tileBytes;
        }
    }
    if (actualBytes != plannedBytes) {
        CJGUI_RECORD_COMPOSABLE_TEXTURE_FAILURE("text_texture.actual_planned_mismatch",
            actualBytes, plannedBytes);
        return nil;
    }
    node.textTexture = prepared.count == 1 ? prepared.firstObject : nil;
    node.textTileTextures = prepared.count > 1 ? [prepared copy] : nil;
    node.textTileRects = prepared.count > 1 ? tiles : nil;
    node.textTextureByteCount = actualBytes; node.textTextureCacheKey = key;
    node.textTextureRect = prepared.count == 1 ? tiles.firstObject.rectValue : CjguiComposableTextTileUnion(tiles);
    node.textTileLayoutOrigin = NSMakePoint((CGFloat)node.node.x, (CGFloat)node.node.y);
    node.preparedTextLayout = sharedLayout;
    // The credential becomes the texture's provenance only after every tile
    // has completed rasterization and upload.
    node.textTextureSourceCredential = candidateSource;
    node.textVisibilityRasterLayout = CjguiObserveAllTextSurfaceFrames() ? sealedRasterLayout : nil;
    id<MTLTexture> firstPreparedTexture = prepared.firstObject;
    if (!firstPreparedTexture) {
        CJGUI_RECORD_COMPOSABLE_TEXTURE_FAILURE("text_texture.prepared_array_empty", prepared.count, 1);
        return nil;
    }
#undef CJGUI_RECORD_COMPOSABLE_TEXTURE_FAILURE
    return firstPreparedTexture;
}

// An owner acknowledgement for the still-focused, same-identity input is not
// a new visual candidate.  The Cangjie bridge deliberately omits its value so
// setNodesFromProjection can retain the already accepted NSTextView value;
// replacing the retained active texture here would rasterize and upload that
// exact text/caret state again immediately afterwards.  Keep the existing
// scene-owned resource through this narrow hand-off. Any identity, kind,
// style, scale, tile, external-value, or retry difference still reaches
// refreshGpuTextForActiveInput and gets its normal body-cache-key check;
// selection, marked ranges and the caret are direct scene geometry.
static BOOL CjguiComposableTextResourceAcknowledgesActiveLocalInput(
    CJGuiInternalComposableSceneNode *node, CJGuiInternalComposableSceneNode *live) {
    if (!node || !live || node.node.preservesActiveLocalText == 0) return NO;
    // `preservesActiveLocalText` is the one-shot transport hint, while an
    // empty staged value is its concrete Cangjie-to-NSString hand-off form.
    // A non-empty value remains a visual candidate (including geometry or
    // tile changes in native scene probes) and must prepare normally.
    if (node.value.length != 0) return NO;
    uint32_t kind = node.node.nodeKind;
    if (kind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT_INPUT &&
        kind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_INTEGER_INPUT &&
        kind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) return NO;
    return node.node.nodeId == live.node.nodeId &&
        node.node.resourceId == live.node.resourceId && kind == live.node.nodeKind;
}

// Clears ONE node's derived text resource fields. Semantic content (value,
// label, geometry, identity) is untouched, so the node can be re-prepared
// verbatim. ARC releases only this holder's strong references; a texture
// object shared with another node stays alive through that other holder.
static void CjguiReleaseComposableTextResource(CJGuiInternalComposableSceneNode *node) {
    if (!node) return;
    node.textTexture = nil;
    node.textTileTextures = nil;
    node.textTileRects = nil;
    node.textTextureCacheKey = @"";
    node.textTextureSourceCredential = nil; node.textVisibilityRasterLayout = nil;
    node.textTextureByteCount = 0;
    node.textTextureRect = NSZeroRect;
}

// A rejected scene transaction must not keep candidate-unique derived text
// resources alive until the next configure or close. Only staged entries that
// are NOT the committed node at the same index are cleared: a COW-shared
// entry IS the accepted scene's own holder and is never touched. Clearing
// derived fields only (never semantic content) keeps even a direct same-
// candidate retry correct, because empty derived state is simply re-prepared.
// When a staged clone still shares the accepted texture object, the committed
// node's own strong reference keeps that texture alive; this helper releases
// the candidate's hold, never the accepted scene's.
static void CjguiReleaseFailedCandidateTextResources(CJGuiInternalSession *ctx) {
    if (!ctx) return;
    for (NSUInteger index = 0; index < ctx.stagedComposableNodes.count; index++) {
        CJGuiInternalComposableSceneNode *node = ctx.stagedComposableNodes[index];
        CJGuiInternalComposableSceneNode *live = index < ctx.composableNodes.count ? ctx.composableNodes[index] : nil;
        if (!node || node == live) continue;
        CjguiReleaseComposableTextResource(node);
    }
}

// Defined after the overlay @interface (it reads the active-input identity
// properties); declared here because the prepare pass runs earlier in file.
static BOOL CjguiStagedNodeIsFocusedInput(CJGuiInternalSession *ctx,
    CJGuiInternalComposableSceneNode *node);
static BOOL CjguiStagedFocusedMultilineTilesNeedPreparation(CJGuiInternalSession *ctx,
    CJGuiInternalComposableSceneNode *node, CGFloat scale);
static CjguiInternalRendererStatus CjguiPrepareStagedFocusedMultilineTiles(CJGuiInternalSession *ctx,
    CJGuiInternalComposableSceneNode *node, CGFloat scale, uint64_t retainedAcceptedBytes,
    uint64_t alreadyFreshBytes, uint64_t *outFreshBytes);
static BOOL CjguiStagedFocusedSingleLineTilesNeedPreparation(CJGuiInternalSession *ctx,
    CJGuiInternalComposableSceneNode *node, CGFloat scale);
static CjguiInternalRendererStatus CjguiPrepareStagedFocusedSingleLineTiles(CJGuiInternalSession *ctx,
    CJGuiInternalComposableSceneNode *node, CGFloat scale, uint64_t retainedAcceptedBytes,
    uint64_t alreadyFreshBytes, uint64_t *outFreshBytes);

// Defined later in the file but needed by the prepare pass, which converts a
// node-local declared caret into the view-space rect decorations are stored in.
static NSRect CjguiComposableRect(CJGuiInternalComposableSceneNode *node, NSView *view);

static NSArray<id<MTLTexture>> *CjguiComposableTextTexturesInNodes(
    NSArray<CJGuiInternalComposableSceneNode *> *nodes) {
    NSMutableArray<id<MTLTexture>> *textures = [NSMutableArray array];
    for (CJGuiInternalComposableSceneNode *node in nodes) {
        if (node.textTexture) [textures addObject:node.textTexture];
        for (id<MTLTexture> texture in node.textTileTextures)
            if (texture) [textures addObject:texture];
    }
    return [textures copy];
}

// Count physical texture generations exactly once across the accepted scene
// and all GPU submissions. An old generation can outlive its scene node; a
// shared tile or cache hit must not be charged twice. Candidate fresh bytes
// are added by the caller before any allocation.
static uint64_t CjguiComposableRetainedTextTextureBytes(CJGuiInternalSession *ctx) {
    // Main-thread admission can run many consecutive frames without servicing
    // the main dispatch queue. Count only GPU-in-flight generations: the
    // completion handler drops its captures before setting this atomic flag.
    for (NSNumber *frame in [ctx.submittedTextCompletionFlags allKeys]) {
        if (ctx.submittedTextCompletionFlags[frame].resourcesReleased) {
            [ctx.submittedTextTextures removeObjectForKey:frame];
            [ctx.submittedTextCompletionFlags removeObjectForKey:frame];
        }
    }
    NSHashTable<id<MTLTexture>> *unique = [NSHashTable hashTableWithOptions:
        NSPointerFunctionsObjectPointerPersonality | NSPointerFunctionsStrongMemory];
    for (id<MTLTexture> texture in CjguiComposableTextTexturesInNodes(ctx.composableNodes))
        [unique addObject:texture];
    for (NSArray<id<MTLTexture>> *submission in ctx.submittedTextTextures.allValues)
        for (id<MTLTexture> texture in submission) [unique addObject:texture];
    NSMutableArray<CjguiComposablePreparation *> *preparations =
        [ctx.retiringComposablePreparations mutableCopy] ?: [NSMutableArray array];
    if (ctx.composablePreparation) [preparations addObject:ctx.composablePreparation];
    for (CjguiComposablePreparation *preparation in preparations) {
        for (id<MTLTexture> texture in CjguiComposableTextTexturesInNodes(preparation.nodes))
            [unique addObject:texture];
        for (id<MTLTexture> texture in preparation.textures) [unique addObject:texture];
    }
    NSMutableArray<CjguiSourceProxyPreparation *> *sourcePreparations =
        [ctx.retiringSourceProxyPreparations mutableCopy] ?: [NSMutableArray array];
    if (ctx.sourceProxyPreparation) [sourcePreparations addObject:ctx.sourceProxyPreparation];
    for (CjguiSourceProxyPreparation *preparation in sourcePreparations) {
        if (preparation.target)
            for (id<MTLTexture> texture in CjguiComposableTextTexturesInNodes(@[preparation.target]))
                [unique addObject:texture];
        for (id<MTLTexture> texture in preparation.textures) [unique addObject:texture];
    }
    uint64_t bytes = 0;
    for (id<MTLTexture> texture in unique) {
        uint64_t value = (uint64_t)texture.width * (uint64_t)texture.height * 4u;
        if (value > CjguiComposableTextTextureByteCapacity - bytes)
            return CjguiComposableTextTextureByteCapacity + 1u;
        bytes += value;
    }
    return bytes;
}

// Defined after the concrete overlay interface. These are read-only source
// proofs; unlike focused staging helpers they never configure a live proxy.
static BOOL CjguiPreparationNativeSourceMatches(CJGuiInternalSession *ctx,
    CjguiComposablePreparation *preparation);
static BOOL CjguiPreparationActiveNodeCanReuse(CJGuiInternalSession *ctx,
    CJGuiInternalComposableSceneNode *node, NSString *desiredRuns, CGFloat scale);

static void CjguiResetPreparationNodeCursor(CjguiComposablePreparation *p) {
    p.phase = 0; p.tileCursor = 0; p.text = nil; p.key = nil; p.tiles = nil;
    p.textures = nil; p.sourceLayout = nil; p.painter = nil; p.sourceCredential = nil;
    p.plannedBytes = 0; p.producedBytes = 0;
}

static BOOL CjguiRetireComposablePreparationUnit(CJGuiInternalSession *ctx) {
    CjguiComposablePreparation *p = ctx.retiringComposablePreparations.firstObject;
    if (!p) return NO;
    if (p.textLayoutJob || p.textLayoutWaitTicket) {
        CjguiCancelTextPreparationWorker(p);
        if (p.textLayoutJob) {
            pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
            BOOL workerLive = p.textLayoutJob.workerLive;
            pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
            if (workerLive) return NO;
            p.textLayoutJob = nil;
        }
    }
    if (p.textures.count) { [p.textures removeLastObject]; return YES; }
    // Release at most one bounded node/layout graph per unit, including its
    // textures. An accepted/GPU-shared resource retains its independent hold.
    if (p.nodes.count) { [p.nodes removeLastObject]; return YES; }
    CjguiResetPreparationNodeCursor(p);
    [ctx.retiringComposablePreparations removeObjectAtIndex:0];
    return YES;
}

// Reclamation owns a bounded allowance as well as the unchanged two-graph
// quota. A live worker yields immediately; retirement is never busy-waited.
static BOOL CjguiDrainComposableRetirement(CJGuiInternalSession *ctx, uint64_t ownerDeadline) {
    uint64_t now = cjgui_internal_renderer_owner_clock_ns();
    uint64_t limit = now + 1000000ull;
    if (ownerDeadline && ownerDeadline < limit) limit = ownerDeadline;
    for (NSUInteger unit = 0; unit < 256 && ctx.retiringComposablePreparations.count; ++unit) {
        if (cjgui_internal_renderer_owner_clock_ns() >= limit ||
            !CjguiRetireComposablePreparationUnit(ctx)) break;
    }
    return ctx.retiringComposablePreparations.count < 2;
}

static CjguiInternalRendererStatus CjguiAdvanceComposablePreparationUnit(
    CJGuiInternalSession *ctx, CjguiComposablePreparation *p) {
    if (p.ready) return CJGUI_INTERNAL_RENDERER_OK;
    if (p.filled.count != p.nodes.count) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    if (p.nodeCursor >= p.nodes.count) { p.ready = YES; return CJGUI_INTERNAL_RENDERER_OK; }
    CJGuiInternalComposableSceneNode *node = p.nodes[p.nodeCursor];
    if (p.phase == 0) {
        NSString *desiredRuns = p.runs[@(node.node.nodeId)] ?: @"";
        if (CjguiStagedNodeIsFocusedInput(ctx, node)) {
            if (!CjguiPreparationActiveNodeCanReuse(ctx, node, desiredRuns, p.scale))
                return CJGUI_INTERNAL_RENDERER_TEXT_SERVICE_UNSUPPORTED;
            // This is the SAME actual live source and coverage, never a
            // texture transferred from another view/container/layout graph.
            p.nodeCursor++; return CJGUI_INTERNAL_RENDERER_OK;
        }
        CjguiClearComposableTextDecorations(node);
        node.styleRunsSignature = desiredRuns;
        if (!CjguiComposableNodeHasGpuText(node.node.nodeKind)) {
            CjguiReleaseComposableTextResource(node); node.preparedTextLayout = nil;
            p.nodeCursor++; return CJGUI_INTERNAL_RENDERER_OK;
        }
        NSString *text = CjguiComposableGpuTextValue(node);
        BOOL longColdText = node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT &&
            text.length >= 1024;
        if (longColdText && !CjguiTextPreparationExtentMemoMatches(node, text)) {
            BOOL handled = NO;
            CjguiInternalRendererStatus workerStatus = CjguiStartOrAdoptColdTextLayout(
                ctx, p, node, text, desiredRuns, &handled);
            if (handled) return workerStatus;
        }
        NSRect coverage = CjguiComposableTextTextureRectForNodeWithText(node, text);
        if (!text.length || node.node.textAlpha <= 0.0 || NSIsEmptyRect(coverage)) {
            CjguiReleaseComposableTextResource(node);
            if (!text.length && CjguiComposableEmptyTextLayoutRect(node, NULL))
                node.preparedTextLayout = CjguiPrepareTextNodeLayout(node, @"", p.scale, nil, ctx);
            p.nodeCursor++; return CJGUI_INTERNAL_RENDERER_OK;
        }
        // The original renderer accepts a nonempty semantic text node whose
        // inset has no preparable geometry. Keep that original path intact;
        // only this known geometry is unsupported by the private TextKit
        // preparation. A nil layout with drawable geometry remains an error.
        if (!CjguiComposableEmptyTextLayoutRect(node, NULL))
            return CJGUI_INTERNAL_RENDERER_TEXT_SERVICE_UNSUPPORTED;
        p.text = text; p.coverage = coverage;
        p.key = CjguiComposableTextTextureKey(node, p.scale, p.scale, text, coverage);
        uint64_t plannedBytes = 0;
        p.tiles = CjguiPlanComposableTextTiles(coverage, CjguiComposableTextNodeLayoutRect(node),
            p.scale, &plannedBytes);
        p.plannedBytes = plannedBytes;
        if (!p.tiles.count || !p.plannedBytes)
            return CjguiTextPreparationBudgetRefusal(__func__, __LINE__);
        CjguiPreparedTextNodeLayout *old = node.preparedTextLayout;
        BOOL widthMatches = old.container && fabs(old.container.size.width -
            ((CGFloat)node.node.width - 14.0)) < 0.001;
        CjguiTextRasterSourceCredential *retained = widthMatches
            ? CjguiCreateTextRasterSourceCredential(node, old.storage, old.layoutManager, old.container,
                nil, text, p.scale, coverage, p.tiles,
                NSMakePoint(node.node.x, node.node.y), 0.0, 0, 0) : nil;
        if (widthMatches && CjguiTextRasterSourceCredentialsEqual(node.textTextureSourceCredential, retained) &&
            CjguiComposableTextTilesAlreadyCovered(node, p.key, p.tiles, p.scale)) {
            node.textTileRects = p.tiles.count > 1 ? p.tiles : nil;
            node.textTextureRect = p.tiles.count == 1 ? p.tiles.firstObject.rectValue : CjguiComposableTextTileUnion(p.tiles);
            node.textTileLayoutOrigin = NSMakePoint(node.node.x, node.node.y);
            CjguiResetPreparationNodeCursor(p); p.nodeCursor++; return CJGUI_INTERNAL_RENDERER_OK;
        }
        if (longColdText) {
            BOOL handled = NO;
            CjguiInternalRendererStatus workerStatus = CjguiStartOrAdoptColdTextLayout(
                ctx, p, node, text, desiredRuns, &handled);
            if (handled) return workerStatus;
        }
        // A changed source gets its OWN TextKit stack. Never mutate the
        // accepted COW layout or rely on the session's mutable run table.
        p.sourceLayout = CjguiPrepareTextNodeLayout(node, text, p.scale,
            CjguiComposableDecodeStyleRuns(desiredRuns), ctx);
        if (!p.sourceLayout) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        p.phase = 1;
        return CJGUI_INTERNAL_RENDERER_OK;
    }
    if (p.phase == 1) {
        NSRect coverage = p.coverage;
        p.sourceCredential = CjguiCreateTextRasterSourceCredential(node, p.sourceLayout.storage,
            p.sourceLayout.layoutManager, p.sourceLayout.container, nil, p.text, p.scale,
            coverage, p.tiles, NSMakePoint(node.node.x, node.node.y), 0.0, 0, 0);
        if (!p.sourceCredential) return CJGUI_INTERNAL_RENDERER_TEXT_SERVICE_UNSUPPORTED;
        p.painter = CjguiCreateSealedRasterLayout(p.sourceCredential);
        if (!p.painter) return CJGUI_INTERNAL_RENDERER_TEXT_SERVICE_UNSUPPORTED;
        p.textures = [NSMutableArray arrayWithCapacity:p.tiles.count];
        p.phase = 2; return CJGUI_INTERNAL_RENDERER_OK;
    }
    if (p.phase == 2) {
        // One real tile per unit. Pixel normalization and upload stay inside
        // that unit and are counted; they cannot disguise an oversized draw.
        if (p.tileCursor < p.tiles.count) {
            NSRect rect = p.tiles[p.tileCursor].rectValue;
            NSUInteger width = 0, height = 0, rowBytes = 0; uint64_t tileBytes = 0;
            if (!CjguiCheckedComposableTextTextureBytes(NSWidth(rect), NSHeight(rect), p.scale, p.scale,
                &width, &height, &rowBytes, &tileBytes))
                return CjguiTextPreparationBudgetRefusal(__func__, __LINE__);
            uint64_t retained = CjguiComposableRetainedTextTextureBytes(ctx);
            if (retained > CjguiComposableTextTextureByteCapacity ||
                tileBytes > CjguiComposableTextTextureByteCapacity - retained)
                return CjguiTextPreparationBudgetRefusal(__func__, __LINE__);
            uint64_t actualBytes = 0;
#ifdef CJGUI_INTERNAL_TESTING
            if (ctx.forcedComposableTextPreparationFailures > 0) {
                ctx.forcedComposableTextPreparationFailures--;
                return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
            }
#endif
            id<MTLTexture> texture = CjguiRasterComposableTextTexture(ctx.view, node, p.scale, p.scale,
                p.text, rect, &actualBytes, p.painter
#ifdef CJGUI_INTERNAL_TESTING
                , CjguiInternalTextWorkReasonStaticCandidate
#endif
                , NULL, 0);
            if (!texture || !actualBytes) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
            [p.textures addObject:texture]; p.producedBytes += actualBytes; p.tileCursor++;
            ctx.composableTextCandidatePeakBytes = MAX(ctx.composableTextCandidatePeakBytes,
                CjguiComposableRetainedTextTextureBytes(ctx));
            return CJGUI_INTERNAL_RENDERER_OK;
        }
        if (p.producedBytes != p.plannedBytes) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        node.textTexture = p.textures.count == 1 ? p.textures.firstObject : nil;
        node.textTileTextures = p.textures.count > 1 ? [p.textures copy] : nil;
        node.textTileRects = p.tiles.count > 1 ? p.tiles : nil;
        node.textTextureCacheKey = p.key; node.textTextureByteCount = p.producedBytes;
        node.textTextureRect = p.tiles.count == 1 ? p.tiles.firstObject.rectValue : CjguiComposableTextTileUnion(p.tiles);
        node.textTileLayoutOrigin = NSMakePoint(node.node.x, node.node.y);
        node.preparedTextLayout = p.sourceLayout;
        // Publish the provenance to this PRIVATE node only after all tiles.
        node.textTextureSourceCredential = p.sourceCredential;
        node.textVisibilityRasterLayout = CjguiObserveAllTextSurfaceFrames() ? p.painter : nil;
        ctx.composableTextLayoutPreparationCount = CjguiSaturatingAddU64(ctx.composableTextLayoutPreparationCount, 1);
        CjguiResetPreparationNodeCursor(p); p.nodeCursor++;
        return CJGUI_INTERNAL_RENDERER_OK;
    }
    return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
}

static CjguiInternalRendererStatus CjguiPrepareComposableTextResources(CJGuiInternalSession *ctx) {
    if (!ctx || !ctx.view) {
        if (ctx) (void)CjguiCandidateFailure(ctx, CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR,
            "text_prepare.missing_view/node=0", ctx.view != nil, 1);
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
#define CJGUI_RECORD_TEXT_PREP_FAILURE(name, nodeIdValue, statusValue, actualValue, expectedValue) do { \
    char candidateFailureBranch[128]; \
    snprintf(candidateFailureBranch, sizeof(candidateFailureBranch), "%s:line=%d/node=%llu", (name), \
        __LINE__, (unsigned long long)(nodeIdValue)); \
    (void)CjguiCandidateFailure(ctx, (statusValue), candidateFailureBranch, \
        (uint64_t)(actualValue), (uint64_t)(expectedValue)); \
} while (0)
    // Run declarations are sent before new node values. Prove all new tagged
    // ranges against the final staged values before any TextKit/texture work,
    // including sparse/empty/transparent nodes that later take a fast path.
    for (CJGuiInternalComposableSceneNode *candidate in ctx.stagedComposableNodes) {
        CjguiInternalRendererStatus runStatus = CjguiComposableValidateSelectionBackgroundRuns(
            ctx.composableTextStyleRunsRaw[@(candidate.node.nodeId)] ?: @"", candidate.value ?: @"");
        if (runStatus != CJGUI_INTERNAL_RENDERER_OK) {
            char candidateFailureBranch[128];
            snprintf(candidateFailureBranch, sizeof(candidateFailureBranch),
                "text_prepare.selection_run_validation/node=%llu", (unsigned long long)candidate.node.nodeId);
            (void)CjguiCandidateFailure(ctx, runStatus, candidateFailureBranch,
                (uint64_t)runStatus, (uint64_t)CJGUI_INTERNAL_RENDERER_OK);
            return runStatus;
        }
    }
    CJGuiInternalMetalView *metalView = ctx.view;
    CGFloat scale = [metalView currentBackingScale];
    scale = MAX(1.0, scale);
    uint64_t sceneBytes = 0, candidateFreshBytes = 0;
    uint64_t retainedAcceptedBytes = CjguiComposableRetainedTextTextureBytes(ctx);
    if (retainedAcceptedBytes > CjguiComposableTextTextureByteCapacity) {
        CJGUI_RECORD_TEXT_PREP_FAILURE("text_prepare.budget_retained_accepted_total", 0,
            CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED,
            retainedAcceptedBytes, CjguiComposableTextTextureByteCapacity);
        return CjguiTextPreparationBudgetRefusal(__func__, __LINE__);
    }
    for (NSUInteger index = 0; index < ctx.stagedComposableNodes.count; index++) {
        CJGuiInternalComposableSceneNode *node = ctx.stagedComposableNodes[index];
        CJGuiInternalComposableSceneNode *live = index < ctx.composableNodes.count ? ctx.composableNodes[index] : nil;
        if (CjguiComposableTextResourceAcknowledgesActiveLocalInput(node, live)) {
            // The empty value acknowledges the native draft, not the old
            // texture coverage. Admit any newly visible multiline cells from
            // that same draft before accepting the candidate geometry.
            BOOL focusedMultiline = node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT;
            BOOL focusedSingleLine = node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT_INPUT ||
                node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_INTEGER_INPUT;
            if ((focusedMultiline || focusedSingleLine) && CjguiStagedNodeIsFocusedInput(ctx, node) &&
                (focusedMultiline ? CjguiStagedFocusedMultilineTilesNeedPreparation(ctx, node, scale)
                                  : CjguiStagedFocusedSingleLineTilesNeedPreparation(ctx, node, scale))) {
                if (node == live) {
                    node = CjguiCloneComposableSceneNode(ctx, live, (uint32_t)index,
                                                          ctx.stagedComposableSceneVersion);
                    if (!node) {
                        CJGUI_RECORD_TEXT_PREP_FAILURE("text_prepare.clone_focused_ack",
                            live ? live.node.nodeId : 0, CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR, 0, 1);
                        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
                    }
                    ctx.stagedComposableNodes[index] = node;
                }
                uint64_t freshBytes = 0;
                CjguiInternalRendererStatus focusedStatus = focusedMultiline
                    ? CjguiPrepareStagedFocusedMultilineTiles(ctx, node, scale, retainedAcceptedBytes,
                        candidateFreshBytes, &freshBytes)
                    : CjguiPrepareStagedFocusedSingleLineTiles(ctx, node, scale, retainedAcceptedBytes,
                        candidateFreshBytes, &freshBytes);
                if (focusedStatus != CJGUI_INTERNAL_RENDERER_OK) {
                    if (focusedStatus == CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR)
                        CJGUI_RECORD_TEXT_PREP_FAILURE("text_prepare.focused_ack_status", node.node.nodeId,
                            focusedStatus, focusedStatus, CJGUI_INTERNAL_RENDERER_OK);
                    return focusedStatus;
                }
                if (node.textTextureByteCount > CjguiComposableTextTextureByteCapacity - sceneBytes) {
                    CJGUI_RECORD_TEXT_PREP_FAILURE("text_prepare.budget_ack_scene_sum", node.node.nodeId,
                        CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED,
                        sceneBytes, node.textTextureByteCount <= CjguiComposableTextTextureByteCapacity
                            ? CjguiComposableTextTextureByteCapacity - node.textTextureByteCount : 0);
                    return CjguiTextPreparationBudgetRefusal(__func__, __LINE__);
                }
                sceneBytes += node.textTextureByteCount;
                candidateFreshBytes += freshBytes;
                ctx.composableTextCandidatePeakBytes = MAX(ctx.composableTextCandidatePeakBytes,
                    retainedAcceptedBytes + candidateFreshBytes);
                continue;
            }
            // The staged COW node already retains the last active resource.
            // Count it like every other scene-owned texture so this reuse
            // cannot evade the accepted-scene resource cap.
            uint64_t retainedBytes = node.textTextureByteCount;
            if (retainedBytes > 0) {
                if (retainedBytes > CjguiComposableTextTextureByteCapacity ||
                    sceneBytes > CjguiComposableTextTextureByteCapacity - retainedBytes) {
                    CJGUI_RECORD_TEXT_PREP_FAILURE(
                        retainedBytes > CjguiComposableTextTextureByteCapacity
                            ? "text_prepare.budget_ack_retained_bytes" : "text_prepare.budget_ack_retained_scene_sum",
                        node.node.nodeId,
                        CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED,
                        retainedBytes > CjguiComposableTextTextureByteCapacity ? retainedBytes : sceneBytes,
                        retainedBytes > CjguiComposableTextTextureByteCapacity
                            ? CjguiComposableTextTextureByteCapacity
                            : CjguiComposableTextTextureByteCapacity - retainedBytes);
                    return CjguiTextPreparationBudgetRefusal(__func__, __LINE__);
                }
                sceneBytes += retainedBytes;
            }
            continue;
        }
        // Decorations are meaningful only while the native TextKit proxy is
        // focused. A sparse staged candidate can still share an accepted
        // active-input node. Copy it before clearing presentation geometry so
        // a failed candidate cannot mutate the accepted selection/caret.
        BOOL hasDecorations = node.textSelectionRects.count > 0 ||
            node.textDeclaredSelectionDecorations.count > 0 ||
            node.textMarkedRects.count > 0 || !NSIsEmptyRect(node.textCaretRect);
        if (node == live && hasDecorations) {
            node = CjguiCloneComposableSceneNode(ctx, live, (uint32_t)index,
                                                  ctx.stagedComposableSceneVersion);
            if (!node) {
                CJGUI_RECORD_TEXT_PREP_FAILURE("text_prepare.clone_decorated_live_node",
                    live ? live.node.nodeId : 0, CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR, 0, 1);
                return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
            }
            ctx.stagedComposableNodes[index] = node;
        }
        CjguiClearComposableTextDecorations(node);
        // Candidate caret is applied after all private layouts are ready. No
        // live overlay declaration is consulted during candidate preparation.
        // Focused single-line and integer bodies use the same preaccept tile
        // admission as multiline. Their native draft can differ from the
        // staged owner value, including the empty preserve acknowledgement.
        if ((node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT_INPUT ||
             node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_INTEGER_INPUT) &&
            CjguiStagedNodeIsFocusedInput(ctx, node)) {
            if (CjguiStagedFocusedSingleLineTilesNeedPreparation(ctx, node, scale)) {
                if (node == live) {
                    node = CjguiCloneComposableSceneNode(ctx, live, (uint32_t)index,
                                                          ctx.stagedComposableSceneVersion);
                    if (!node) {
                        CJGUI_RECORD_TEXT_PREP_FAILURE("text_prepare.clone_focused_single_line",
                            live ? live.node.nodeId : 0, CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR, 0, 1);
                        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
                    }
                    ctx.stagedComposableNodes[index] = node;
                }
                uint64_t freshBytes = 0;
                CjguiInternalRendererStatus focusedStatus = CjguiPrepareStagedFocusedSingleLineTiles(
                    ctx, node, scale, retainedAcceptedBytes, candidateFreshBytes, &freshBytes);
                if (focusedStatus != CJGUI_INTERNAL_RENDERER_OK) {
                    if (focusedStatus == CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR)
                        CJGUI_RECORD_TEXT_PREP_FAILURE("text_prepare.focused_single_line_status", node.node.nodeId,
                            focusedStatus, focusedStatus, CJGUI_INTERNAL_RENDERER_OK);
                    return focusedStatus;
                }
                candidateFreshBytes += freshBytes;
            }
            if (node.textTextureByteCount > CjguiComposableTextTextureByteCapacity - sceneBytes) {
                CJGUI_RECORD_TEXT_PREP_FAILURE("text_prepare.budget_focused_single_scene_sum", node.node.nodeId,
                    CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED,
                    sceneBytes, node.textTextureByteCount <= CjguiComposableTextTextureByteCapacity
                        ? CjguiComposableTextTextureByteCapacity - node.textTextureByteCount : 0);
                return CjguiTextPreparationBudgetRefusal(__func__, __LINE__);
            }
            sceneBytes += node.textTextureByteCount;
            ctx.composableTextCandidatePeakBytes = MAX(ctx.composableTextCandidatePeakBytes,
                retainedAcceptedBytes + candidateFreshBytes);
            continue;
        }
        BOOL shouldClear = NO;
        if (!CjguiComposableNodeHasGpuText(node.node.nodeKind)) {
            shouldClear = YES;
        } else if (NSIsEmptyRect(CjguiComposableTextTextureRectForNode(node))) {
            // A fully clipped node cannot contribute pixels this turn. Its
            // immutable Cangjie value remains available for a later retry.
            shouldClear = YES;
        }
        NSString *text = shouldClear ? @"" : CjguiComposableGpuTextValue(node);
        if (text.length == 0 || node.node.textAlpha <= 0.0) shouldClear = YES;
        if (shouldClear) {
            if (node.textTexture || node.textTileTextures.count > 0 ||
                node.textTextureCacheKey.length > 0 || node.textTextureSourceCredential || node.textTextureByteCount > 0) {
                if (node == live) {
                    node = CjguiCloneComposableSceneNode(ctx, live, (uint32_t)index, ctx.stagedComposableSceneVersion);
                    if (!node) {
                        CJGUI_RECORD_TEXT_PREP_FAILURE("text_prepare.clone_clear_stale_resources",
                            live ? live.node.nodeId : 0, CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR, 0, 1);
                        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
                    }
                    ctx.stagedComposableNodes[index] = node;
                }
                node.textTexture = nil; node.textTileTextures = nil; node.textTileRects = nil;
                node.textTextureCacheKey = @""; node.textTextureByteCount = 0;
                node.textTextureSourceCredential = nil; node.textVisibilityRasterLayout = nil;
                node.textTextureRect = NSZeroRect;
            }
            // An EMPTY value that is still inside its clip owns a caret, and the B2
            // invariant says every text node keeps a queryable accepted layout. The
            // pixel path cannot supply one (no tiles, so it never prepares), which
            // left the first empty paragraph answering `pending` forever: no caret on
            // click. Retain the same prepared layout the raster path would have used —
            // zero glyphs, so no texture bytes and no raster work.
            if (text.length > 0) continue;
            // Only a node that can own a caret/paragraph belongs in this path. A
            // structure, layer, vector or image node has no text at all; entering it
            // anyway clones the node, and when the rect is thinner than the text
            // inset the preparation returns nil, so the guard below never holds and
            // EVERY refresh clones it again (measured: 18 such nodes x 30 refreshes
            // produced 540 of 570 reported clones).
            if (!CjguiComposableNodeHasGpuText(node.node.nodeKind)) {
                // A same-slot kind replacement may inherit accepted text
                // layout state through COW. Retire it once on the candidate;
                // ordinary non-text nodes stay shared verbatim.
                if (node.preparedTextLayout || node.styleRunsSignature.length > 0) {
                    if (node == live) {
                        node = CjguiCloneComposableSceneNode(ctx, live, (uint32_t)index,
                                                              ctx.stagedComposableSceneVersion);
                        if (!node) {
                            CJGUI_RECORD_TEXT_PREP_FAILURE("text_prepare.clone_clear_nontext_state",
                                live ? live.node.nodeId : 0, CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR, 0, 1);
                            return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
                        }
                        ctx.stagedComposableNodes[index] = node;
                    }
                    node.preparedTextLayout = nil;
                    node.styleRunsSignature = @"";
                }
                continue;
            }
            // A text node whose rect cannot hold the inset has a named "no
            // preparable geometry" state: assigning nil is not a change, so do not
            // pay a COW clone for it on every refresh either.
            if (!CjguiComposableEmptyTextLayoutRect(node, NULL)) continue;
            if (node.preparedTextLayout && node.preparedTextLayout.storage.length == 0) continue;
            if (node == live) {
                node = CjguiCloneComposableSceneNode(ctx, live, (uint32_t)index, ctx.stagedComposableSceneVersion);
                if (!node) {
                    CJGUI_RECORD_TEXT_PREP_FAILURE("text_prepare.clone_empty_layout",
                        live ? live.node.nodeId : 0, CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR, 0, 1);
                    return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
                }
                ctx.stagedComposableNodes[index] = node;
            }
            node.preparedTextLayout = CjguiPrepareTextNodeLayout(node, @"", scale, nil, ctx);
            if (ctx.composableTextLayoutPreparationCount < UINT64_MAX) {
                ctx.composableTextLayoutPreparationCount += 1;
            }
            continue;
        }
        NSRect textureRect = CjguiComposableTextTextureRectForNode(node);
        // Runs participate in the key, and the scene nodes are rebuilt every
        // frame, so the signature must be attached to THIS node before the key
        // is computed; stamping it later can never invalidate the cached texture.
        NSString *desiredRuns = ctx.composableTextStyleRunsRaw[@(node.node.nodeId)] ?: @"";
        if (node == live && ![(node.styleRunsSignature ?: @"") isEqualToString:desiredRuns]) {
            node = CjguiCloneComposableSceneNode(ctx, live, (uint32_t)index,
                                                  ctx.stagedComposableSceneVersion);
            if (!node) {
                CJGUI_RECORD_TEXT_PREP_FAILURE("text_prepare.clone_style_signature",
                    live ? live.node.nodeId : 0, CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR, 0, 1);
                return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
            }
            ctx.stagedComposableNodes[index] = node;
        }
        node.styleRunsSignature = desiredRuns;
        // The declared caret deliberately does NOT participate in the key: caret arrival,
        // move and leave must not invalidate body pixels. It is drawn as a decoration after
        // the texture (see the shape batch), so only the caret's own rect changes.
        NSString *key = CjguiComposableTextTextureKey(node, scale, scale, text, textureRect);
        uint64_t nodeBytes = 0;
        NSArray<NSValue *> *plannedTiles = CjguiPlanComposableTextTiles(textureRect,
            CjguiComposableTextNodeLayoutRect(node), scale, &nodeBytes);
        if (plannedTiles.count == 0 || nodeBytes == 0) {
            CJGUI_RECORD_TEXT_PREP_FAILURE(plannedTiles.count == 0
                    ? "text_prepare.budget_plan_has_no_tiles" : "text_prepare.budget_plan_has_zero_bytes",
                node.node.nodeId,
                CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED,
                plannedTiles.count == 0 ? plannedTiles.count : nodeBytes, 1);
            return CjguiTextPreparationBudgetRefusal(__func__, __LINE__);
        }
        BOOL needsPreparation = !CjguiComposableTextTilesAlreadyCovered(node, key, plannedTiles, scale);
        if (needsPreparation && getenv("CJGUI_TEXT_PREPARE_TRACE")) {
            fprintf(stderr, "CJGUI_TEXT_PREPARE node=%llu kind=%u size=%lldx%lld tiles=%lu "
                "text_chars=%lu key_same=%d retained_tiles=%lu width_match=%d\n",
                (unsigned long long)node.node.nodeId, node.node.nodeKind,
                (long long)node.node.width, (long long)node.node.height,
                (unsigned long)plannedTiles.count, (unsigned long)text.length,
                [node.textTextureCacheKey isEqualToString:key],
                (unsigned long)(node.textTileTextures.count ?: (node.textTexture ? 1 : 0)),
                node.preparedTextLayout && fabs(node.preparedTextLayout.container.size.width -
                    ((CGFloat)node.node.width - 14.0)) < 0.001);
        }
        if (getenv("PHAROS_TRACE_RUNS") && node.node.nodeId == 200) {
            fprintf(stderr, "PHAROS_TEXTURE node=200 prep=%d sig=%s cached=%s keyLen=%lu\n",
                    (int)needsPreparation,
                    node.styleRunsSignature ? node.styleRunsSignature.UTF8String : "(nil)",
                    node.textTextureCacheKey ? node.textTextureCacheKey.UTF8String : "(nil)",
                    (unsigned long)key.length);
        }
        // The focused input's visible body comes from the active TextKit
        // refresh that the same commit triggers right after this loop; its
        // static candidate form is never drawn this turn. Keep the previous
        // resource (the safe fallback if focus moves first) and charge its
        // retained bytes like the acknowledge path instead of rasterizing the
        // same body twice per geometry or content turn. The active refresh
        // re-admits its own body against the scene budget afterwards.
        if (needsPreparation && CjguiStagedNodeIsFocusedInput(ctx, node)) {
            if (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) {
                if (node == live) {
                    node = CjguiCloneComposableSceneNode(ctx, live, (uint32_t)index,
                                                          ctx.stagedComposableSceneVersion);
                    if (!node) {
                        CJGUI_RECORD_TEXT_PREP_FAILURE("text_prepare.clone_focused_multiline",
                            live ? live.node.nodeId : 0, CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR, 0, 1);
                        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
                    }
                    ctx.stagedComposableNodes[index] = node;
                }
                uint64_t focusedFreshBytes = 0;
                CjguiInternalRendererStatus focusedStatus = CjguiPrepareStagedFocusedMultilineTiles(
                    ctx, node, scale, retainedAcceptedBytes, candidateFreshBytes, &focusedFreshBytes);
                if (focusedStatus != CJGUI_INTERNAL_RENDERER_OK) {
                    if (focusedStatus == CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR)
                        CJGUI_RECORD_TEXT_PREP_FAILURE("text_prepare.focused_multiline_status", node.node.nodeId,
                            focusedStatus, focusedStatus, CJGUI_INTERNAL_RENDERER_OK);
                    return focusedStatus;
                }
                if (node.textTextureByteCount > CjguiComposableTextTextureByteCapacity - sceneBytes) {
                    CJGUI_RECORD_TEXT_PREP_FAILURE("text_prepare.budget_focused_multiline_scene_sum", node.node.nodeId,
                        CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED,
                        sceneBytes, node.textTextureByteCount <= CjguiComposableTextTextureByteCapacity
                            ? CjguiComposableTextTextureByteCapacity - node.textTextureByteCount : 0);
                    return CjguiTextPreparationBudgetRefusal(__func__, __LINE__);
                }
                sceneBytes += node.textTextureByteCount;
                candidateFreshBytes += focusedFreshBytes;
                ctx.composableTextCandidatePeakBytes = MAX(ctx.composableTextCandidatePeakBytes,
                    retainedAcceptedBytes + candidateFreshBytes);
                continue;
            }
            uint64_t retainedBytes = node.textTextureByteCount;
                if (retainedBytes > CjguiComposableTextTextureByteCapacity ||
                    sceneBytes > CjguiComposableTextTextureByteCapacity - retainedBytes) {
                CJGUI_RECORD_TEXT_PREP_FAILURE(
                    retainedBytes > CjguiComposableTextTextureByteCapacity
                        ? "text_prepare.budget_focused_retained_bytes"
                        : "text_prepare.budget_focused_retained_scene_sum", node.node.nodeId,
                    CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED,
                    retainedBytes > CjguiComposableTextTextureByteCapacity ? retainedBytes : sceneBytes,
                    retainedBytes > CjguiComposableTextTextureByteCapacity
                        ? CjguiComposableTextTextureByteCapacity
                        : CjguiComposableTextTextureByteCapacity - retainedBytes);
                return CjguiTextPreparationBudgetRefusal(__func__, __LINE__);
            }
            sceneBytes += retainedBytes;
            continue;
        }
        if (nodeBytes == 0 || sceneBytes > CjguiComposableTextTextureByteCapacity - nodeBytes) {
            fprintf(stderr, "PHAROS_BUDGET_REJECT node=%llu nodeBytes=%lu sceneBytes=%lu capacity=%lu "
                    "rectW=%.1f rectH=%.1f textUtf16=%lu kind=%u\n",
                    (unsigned long long)node.node.nodeId, (unsigned long)nodeBytes,
                    (unsigned long)sceneBytes, (unsigned long)CjguiComposableTextTextureByteCapacity,
                    (double)NSWidth(textureRect), (double)NSHeight(textureRect),
                    (unsigned long)(text ? text.length : 0), (unsigned)node.node.nodeKind);
            CJGUI_RECORD_TEXT_PREP_FAILURE(nodeBytes == 0
                    ? "text_prepare.budget_scene_node_plan_zero" : "text_prepare.budget_scene_plus_node_plan",
                node.node.nodeId, CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED,
                nodeBytes == 0 ? nodeBytes : sceneBytes,
                nodeBytes == 0 ? 1 : nodeBytes <= CjguiComposableTextTextureByteCapacity
                    ? CjguiComposableTextTextureByteCapacity - nodeBytes : 0);
            return CjguiTextPreparationBudgetRefusal(__func__, __LINE__);
        }
        sceneBytes += nodeBytes;
        if (!needsPreparation) {
            NSRect tileUnion = plannedTiles.count == 1 ? plannedTiles.firstObject.rectValue :
                CjguiComposableTextTileUnion(plannedTiles);
            if (!NSEqualRects(node.textTextureRect, tileUnion) ||
                !NSEqualPoints(node.textTileLayoutOrigin,
                    NSMakePoint((CGFloat)node.node.x, (CGFloat)node.node.y))) {
                if (node == live) {
                    node = CjguiCloneComposableSceneNode(ctx, live, (uint32_t)index,
                                                          ctx.stagedComposableSceneVersion);
                    if (!node) {
                        CJGUI_RECORD_TEXT_PREP_FAILURE("text_prepare.clone_tile_metadata",
                            live ? live.node.nodeId : 0, CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR, 0, 1);
                        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
                    }
                    ctx.stagedComposableNodes[index] = node;
                }
                node.textTileRects = plannedTiles.count > 1 ? plannedTiles : nil;
                node.textTextureRect = tileUnion;
                node.textTileLayoutOrigin = NSMakePoint((CGFloat)node.node.x, (CGFloat)node.node.y);
            }
            continue;
        }
        if (node == live) {
            node = CjguiCloneComposableSceneNode(ctx, live, (uint32_t)index, ctx.stagedComposableSceneVersion);
            if (!node) {
                CJGUI_RECORD_TEXT_PREP_FAILURE("text_prepare.clone_candidate_resources",
                    live ? live.node.nodeId : 0, CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR, 0, 1);
                return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
            }
            ctx.stagedComposableNodes[index] = node;
        }
        uint64_t freshBytes = CjguiComposableFreshTextTileBytes(node, key, plannedTiles, scale);
        if (freshBytes > CjguiComposableTextTextureByteCapacity - retainedAcceptedBytes - candidateFreshBytes) {
            CJGUI_RECORD_TEXT_PREP_FAILURE("text_prepare.budget_fresh_candidate_bytes", node.node.nodeId,
                CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED,
                freshBytes, CjguiComposableTextTextureByteCapacity - retainedAcceptedBytes - candidateFreshBytes);
            return CjguiTextPreparationBudgetRefusal(__func__, __LINE__);
        }
        candidateFreshBytes += freshBytes;
#ifdef CJGUI_INTERNAL_TESTING
        if (ctx.forcedComposableTextPreparationFailures > 0) {
            ctx.forcedComposableTextPreparationFailures -= 1;
            CJGUI_RECORD_TEXT_PREP_FAILURE("text_prepare.forced_test_failure", node.node.nodeId,
                CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR, 1, 0);
            return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        }
#endif
        if (!CjguiComposableTextTexture(metalView, node, scale, scale, text
#ifdef CJGUI_INTERNAL_TESTING
                                        , CjguiInternalTextWorkReasonStaticCandidate
#endif
                                        )) {
            CJGUI_RECORD_TEXT_PREP_FAILURE("text_prepare.texture_returned_nil", node.node.nodeId,
                CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR, 0, 1);
            return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        }
        ctx.composableTextCandidatePeakBytes = MAX(ctx.composableTextCandidatePeakBytes,
            retainedAcceptedBytes + candidateFreshBytes);
        if (ctx.composableTextLayoutPreparationCount < UINT64_MAX) {
            ctx.composableTextLayoutPreparationCount += 1;
        }
    }
    // A selection-only candidate reuses body tiles and the accepted TextKit
    // layout. Derive paint rectangles only after every node has passed resource
    // admission, then publish all of them with this one scene transaction.
    for (NSUInteger index = 0; index < ctx.stagedComposableNodes.count; index++) {
        CJGuiInternalComposableSceneNode *node = ctx.stagedComposableNodes[index];
        if (node.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT) continue;
        NSData *decoded = CjguiComposableDecodeStyleRuns(
            ctx.composableTextStyleRunsRaw[@(node.node.nodeId)] ?: @"");
        NSArray<NSDictionary *> *decorations = CjguiComposableDeclaredSelectionDecorations(node, decoded);
        if (!decorations) {
            char candidateFailureBranch[96];
            snprintf(candidateFailureBranch, sizeof(candidateFailureBranch),
                "declared_selection_decorations/node=%llu", (unsigned long long)node.node.nodeId);
            (void)CjguiCandidateFailure(ctx, CJGUI_INTERNAL_RENDERER_TEXT_SERVICE_UNSUPPORTED,
                candidateFailureBranch,
                decoded.length / sizeof(CjguiInternalTextStyleRun),
                node.preparedTextLayout.layoutManager.numberOfGlyphs);
            return CJGUI_INTERNAL_RENDERER_TEXT_SERVICE_UNSUPPORTED;
        }
        if ([(node.textDeclaredSelectionDecorations ?: @[]) isEqualToArray:decorations]) continue;
        CJGuiInternalComposableSceneNode *live = index < ctx.composableNodes.count ? ctx.composableNodes[index] : nil;
        if (node == live) {
            node = CjguiCloneComposableSceneNode(ctx, live, (uint32_t)index,
                                                  ctx.stagedComposableSceneVersion);
            if (!node) {
                CJGUI_RECORD_TEXT_PREP_FAILURE("text_prepare.clone_selection_decorations",
                    live ? live.node.nodeId : 0, CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR, 0, 1);
                return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
            }
            ctx.stagedComposableNodes[index] = node;
        }
        node.textDeclaredSelectionDecorations = decorations;
    }
#undef CJGUI_RECORD_TEXT_PREP_FAILURE
    CjguiCandidateCaretProjection *caret = ctx.stagedCaretProjection;
    for (NSUInteger index = 0; index < ctx.stagedComposableNodes.count; ++index) {
        CJGuiInternalComposableSceneNode *node = ctx.stagedComposableNodes[index];
        BOOL target = caret.present && caret.nodeId == (int64_t)node.node.nodeId &&
            CjguiComposableNodeHasGpuText(node.node.nodeKind);
        if (!target && !node.textCaretIsDeclared) continue;
        if ([ctx.composableNodes containsObject:node]) {
            node = CjguiCloneComposableSceneNode(ctx, node, (uint32_t)index, ctx.stagedComposableSceneVersion);
            if (!node) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
            ctx.stagedComposableNodes[index] = node;
        }
        if (node.textCaretIsDeclared) { node.textCaretRect = NSZeroRect; node.textCaretIsDeclared = NO; }
        if (!target) continue;
        NSRect local = caret.rect;
        if (caret.usesByteOffset) {
            CjguiInternalRendererStatus status = CjguiCandidateCaretRect(node, caret.localByte, caret.affinity, &local);
            if (status != CJGUI_INTERNAL_RENDERER_OK) return status;
        }
        NSRect nodeRect = CjguiComposableVisualNodeRect(node);
        caret.rect = local;
        // Preserve position geometry even when the focus line is outside the
        // viewport. The normal GPU decoration path applies the node's clip;
        // clipping must not turn a proved layout position into unknown input.
        node.textCaretRect = NSOffsetRect(local, NSMinX(nodeRect), NSMinY(nodeRect));
        node.textCaretIsDeclared = !NSIsEmptyRect(node.textCaretRect);
    }
    return CJGUI_INTERNAL_RENDERER_OK;
}

// Active TextKit updates bypass a Cangjie scene transaction, but they still
// replace a scene-owned derived texture. Apply the same accepted-scene budget
// before swapping it so a focused field cannot evade the admission limit.
static BOOL CjguiComposableTextTextureFitsSceneBudget(CJGuiInternalSession *ctx,
                                                       NSArray<CJGuiInternalComposableSceneNode *> *nodes,
                                                       CJGuiInternalComposableSceneNode *replacing,
                                                       uint64_t candidateBytes,
                                                       uint64_t reusableBytes) {
    if (candidateBytes == 0 || candidateBytes > CjguiComposableTextTextureByteCapacity) return NO;
    if (reusableBytes > candidateBytes) return NO;
    uint64_t retained = CjguiComposableRetainedTextTextureBytes(ctx), finalTotal = candidateBytes;
    if (retained > CjguiComposableTextTextureByteCapacity) return NO;
    for (CJGuiInternalComposableSceneNode *node in nodes) {
        if (!CjguiComposableNodeHasGpuText(node.node.nodeKind)) continue;
        uint64_t bytes = node.textTextureByteCount;
        if (node == replacing) continue;
        if (bytes > CjguiComposableTextTextureByteCapacity - finalTotal) return NO;
        finalTotal += bytes;
    }
    return finalTotal <= CjguiComposableTextTextureByteCapacity &&
        candidateBytes - reusableBytes <= CjguiComposableTextTextureByteCapacity - retained;
}

static const uint32_t CjguiEffectGroupCapacity = 16;
enum { CjguiEffectGroupDepthCapacity = 4 };
static const uint32_t CjguiEffectTargetDimensionCapacity = 4096;
static const uint64_t CjguiEffectTargetPixelCapacity = 4u * 1024u * 1024u;
static const uint64_t CjguiEffectTargetByteCapacity = 96u * 1024u * 1024u;

static BOOL CjguiEffectFiniteUnit(double value) {
    return isfinite(value) && value >= 0.0 && value <= 1.0;
}

// No group span may cross a containing group's end. Relative subtree counts
// survive Cangjie layout COW replay without index relocation. Validate this
// before any text preparation or target allocation so malformed FFI values
// cannot publish a partially composited candidate.
static CjguiInternalRendererStatus CjguiValidateEffectGroupTopology(
    NSArray<CJGuiInternalComposableSceneNode *> *nodes) {
    NSUInteger ends[CjguiEffectGroupDepthCapacity] = {0};
    uint32_t depth = 0, groupCount = 0, backdropCount = 0;
    for (NSUInteger index = 0; index < nodes.count; index++) {
        while (depth > 0 && index >= ends[depth - 1]) depth--;
        CjguiInternalRendererComposableNode value = nodes[index].node;
        if (value.effectGroupPresent == 0) continue;
        if (value.effectGroupPresent != 1 || ++groupCount > CjguiEffectGroupCapacity ||
            depth >= CjguiEffectGroupDepthCapacity || value.effectGroupSubtreeCount == 0 ||
            value.effectGroupSubtreeCount > nodes.count - index ||
            (depth > 0 && value.effectGroupSubtreeCount > ends[depth - 1] - index) ||
            !CjguiEffectFiniteUnit(value.effectGroupOpacity) || value.effectGroupBlendMode > 1 ||
            value.effectMaskPresent > 1 || value.effectBackdropBlurRadiusPoints > 16 ||
            value.effectBackdropBlurFallback != 0) return CJGUI_INTERNAL_RENDERER_EFFECT_DECLARATION_REJECTED;
        // The first bounded backdrop slice has one root-level sampling group.
        // Nested/multiple backdrop readers need a separate dependency graph.
        if (value.effectBackdropBlurRadiusPoints > 0 && (depth > 0 || ++backdropCount > 1))
            return CJGUI_INTERNAL_RENDERER_EFFECT_DECLARATION_REJECTED;
        if (value.effectMaskPresent) {
            if (value.effectMaskStopCount < 2 || value.effectMaskStopCount > 4 ||
                !CjguiEffectFiniteUnit(value.effectMaskStartX) ||
                !CjguiEffectFiniteUnit(value.effectMaskStartY) ||
                !CjguiEffectFiniteUnit(value.effectMaskEndX) ||
                !CjguiEffectFiniteUnit(value.effectMaskEndY))
                return CJGUI_INTERNAL_RENDERER_EFFECT_DECLARATION_REJECTED;
            double dx = value.effectMaskEndX - value.effectMaskStartX;
            double dy = value.effectMaskEndY - value.effectMaskStartY;
            if (dx * dx + dy * dy <= 1.0e-12)
                return CJGUI_INTERNAL_RENDERER_EFFECT_DECLARATION_REJECTED;
            double positions[4] = {value.effectMaskStop0Position, value.effectMaskStop1Position,
                                   value.effectMaskStop2Position, value.effectMaskStop3Position};
            double alphas[4] = {value.effectMaskStop0Alpha, value.effectMaskStop1Alpha,
                                value.effectMaskStop2Alpha, value.effectMaskStop3Alpha};
            for (uint32_t stop = 0; stop < value.effectMaskStopCount; stop++) {
                if (!CjguiEffectFiniteUnit(positions[stop]) || !CjguiEffectFiniteUnit(alphas[stop]) ||
                    (stop > 0 && positions[stop] < positions[stop - 1]))
                    return CJGUI_INTERNAL_RENDERER_EFFECT_DECLARATION_REJECTED;
            }
        } else if (value.effectMaskStopCount != 0) {
            return CJGUI_INTERNAL_RENDERER_EFFECT_DECLARATION_REJECTED;
        }
        ends[depth++] = index + value.effectGroupSubtreeCount;
    }
    return CJGUI_INTERNAL_RENDERER_OK;
}

static NSRect CjguiEffectNodeOutputBounds(CJGuiInternalSession *ctx,
                                         CJGuiInternalComposableSceneNode *node) {
    CjguiInternalRendererComposableNode value = node.node;
    NSRect output = NSZeroRect;
    NSRect visualClip = CjguiComposableVisualClipBounds(node);
    if (value.width > 0 && value.height > 0) {
        output = NSIntersectionRect(CjguiComposableVisualNodeRect(node), visualClip);
    }
    if (value.shadowPresent && value.shadowAlpha > 0.0) {
        NSRect shadow = CjguiComposableShadowOutputRect(node);
        uint32_t count = CjguiComposableClipConstraintCount(value);
        for (uint32_t clip = 0; clip < count && !NSIsEmptyRect(shadow); clip++) {
            CGFloat x, y, width, height, radius;
            CjguiComposableVisualClipConstraintAt(node, clip, &x, &y, &width, &height, &radius);
            shadow = NSIntersectionRect(shadow, NSMakeRect(x, y, width, height));
        }
        if (!NSIsEmptyRect(shadow)) output = NSIsEmptyRect(output) ? shadow : NSUnionRect(output, shadow);
    }
    // Native input decorations are paint, not layout, but can extend a pixel
    // beyond the text body's clip before their own shader applies that clip.
    NSArray<NSValue *> *decorationRects = [CjguiEffectiveTransferTextSelectionRects(ctx, node)
                                             arrayByAddingObjectsFromArray:(node.textMarkedRects ?: @[])];
    for (NSValue *rectValue in decorationRects) {
        NSRect rect = NSIntersectionRect(rectValue.rectValue, visualClip);
        if (!NSIsEmptyRect(rect)) output = NSIsEmptyRect(output) ? rect : NSUnionRect(output, rect);
    }
    for (NSDictionary *decoration in CjguiEffectiveDeclaredSelectionDecorations(ctx, node)) {
        NSValue *rectValue = decoration[@"rect"];
        if (![rectValue isKindOfClass:NSValue.class]) continue;
        NSRect rect = NSIntersectionRect(rectValue.rectValue, visualClip);
        if (!NSIsEmptyRect(rect)) output = NSIsEmptyRect(output) ? rect : NSUnionRect(output, rect);
    }
    NSRect caret = NSIntersectionRect(CjguiEffectiveTransferTextCaretRect(ctx, node), visualClip);
    if (!NSIsEmptyRect(caret)) output = NSIsEmptyRect(output) ? caret : NSUnionRect(output, caret);
    NSRect scrollbar = NSIntersectionRect(node.textScrollbarRect, visualClip);
    if (!NSIsEmptyRect(scrollbar)) output = NSIsEmptyRect(output) ? scrollbar : NSUnionRect(output, scrollbar);
    return output;
}

static NSRect CjguiEffectGroupOutputBounds(CJGuiInternalSession *ctx,
                                          NSArray<CJGuiInternalComposableSceneNode *> *nodes,
                                          NSUInteger start, NSUInteger end) {
    NSRect output = NSZeroRect;
    for (NSUInteger index = start; index < end;) {
        CjguiInternalRendererComposableNode value = nodes[index].node;
        NSRect next = NSZeroRect;
        if (index != start && value.effectGroupPresent) {
            NSUInteger childEnd = index + value.effectGroupSubtreeCount;
            next = CjguiEffectGroupOutputBounds(ctx, nodes, index, childEnd);
            index = childEnd;
        } else {
            next = CjguiEffectNodeOutputBounds(ctx, nodes[index]);
            index++;
        }
        if (!NSIsEmptyRect(next)) output = NSIsEmptyRect(output) ? next : NSUnionRect(output, next);
    }
    CjguiInternalRendererComposableNode group = nodes[start].node;
    if (group.effectMaskPresent && !NSIsEmptyRect(output))
        // Content, the mask shader and its allocated target share the same
        // accepted visual coordinates, including inherited translations.
        output = NSIntersectionRect(output, CjguiComposableVisualNodeRect(nodes[start]));
    return output;
}

static uint64_t CjguiEffectHashBytes(uint64_t hash, const void *bytes, NSUInteger length) {
    const uint8_t *cursor = (const uint8_t *)bytes;
    for (NSUInteger index = 0; index < length; index++) {
        hash ^= cursor[index];
        hash *= UINT64_C(1099511628211);
    }
    return hash;
}

static uint64_t CjguiEffectHashString(uint64_t hash, NSString *value) {
    NSData *data = [(value ?: @"") dataUsingEncoding:NSUTF8StringEncoding];
    uint64_t size = data.length;
    hash = CjguiEffectHashBytes(hash, &size, sizeof(size));
    return CjguiEffectHashBytes(hash, data.bytes, data.length);
}

static uint64_t CjguiEffectHashRectArray(uint64_t hash, NSArray<NSValue *> *rects) {
    uint64_t count = rects.count;
    hash = CjguiEffectHashBytes(hash, &count, sizeof(count));
    for (NSValue *value in rects) {
        NSRect rect = value.rectValue;
        hash = CjguiEffectHashBytes(hash, &rect, sizeof(rect));
    }
    return hash;
}

// Both foreground targets and sampled backdrops depend on these exact node
// paint inputs. Keep one list: native decorations, texture generations and
// their sampled rectangles cannot silently diverge between the two caches.
static uint64_t CjguiEffectHashPaintNodeForSession(CJGuiInternalSession *ctx, uint64_t hash,
                                                   CJGuiInternalComposableSceneNode *node,
                                                   CjguiInternalRendererComposableNode value) {
    value.projectionVersion = 0;
    hash = CjguiEffectHashBytes(hash, &value, sizeof(value));
    // The accepted visual transform lives beside the legacy integer POD.
    // Both a group's rendered content and a backdrop's earlier paint prefix
    // depend on it even when the quantized target/sample ROI is unchanged.
    // Hash values explicitly, avoiding padding in the FFI sidecar.
    double visual[10] = {node.geometry.translateX, node.geometry.translateY,
                         node.geometry.clip0X, node.geometry.clip0Y,
                         node.geometry.clip1X, node.geometry.clip1Y,
                         node.geometry.clip2X, node.geometry.clip2Y,
                         node.geometry.clip3X, node.geometry.clip3Y};
    hash = CjguiEffectHashBytes(hash, visual, sizeof(visual));
    hash = CjguiEffectHashString(hash, node.semanticId);
    hash = CjguiEffectHashString(hash, node.label);
    hash = CjguiEffectHashString(hash, node.value);
    hash = CjguiEffectHashString(hash, node.styleRunsSignature);
    hash = CjguiEffectHashString(hash, node.textTextureCacheKey);
    hash = CjguiEffectHashString(hash, node.imageTextureContentKey);
    uintptr_t resources[2] = {(uintptr_t)node.textTexture, (uintptr_t)node.imageTexture};
    hash = CjguiEffectHashBytes(hash, resources, sizeof(resources));
    uint64_t imageResourceVersion = node.imageResourceVersion;
    hash = CjguiEffectHashBytes(hash, &imageResourceVersion, sizeof(imageResourceVersion));
    uint64_t tileCount = node.textTileTextures.count;
    hash = CjguiEffectHashBytes(hash, &tileCount, sizeof(tileCount));
    for (id<MTLTexture> tile in node.textTileTextures) {
        uintptr_t pointer = (uintptr_t)tile;
        hash = CjguiEffectHashBytes(hash, &pointer, sizeof(pointer));
    }
    hash = CjguiEffectHashRectArray(hash, CjguiEffectiveTransferTextSelectionRects(ctx, node));
    NSArray<NSDictionary *> *declared = CjguiEffectiveDeclaredSelectionDecorations(ctx, node);
    uint64_t declaredCount = declared.count;
    hash = CjguiEffectHashBytes(hash, &declaredCount, sizeof(declaredCount));
    for (NSDictionary *decoration in declared) {
        NSRect rect = [decoration[@"rect"] rectValue];
        vector_float4 color = CjguiMetalColorFromNSColor(decoration[@"color"]);
        hash = CjguiEffectHashBytes(hash, &rect, sizeof(rect));
        hash = CjguiEffectHashBytes(hash, &color, sizeof(color));
    }
    hash = CjguiEffectHashRectArray(hash, node.textMarkedRects);
    hash = CjguiEffectHashRectArray(hash, node.textTileRects);
    NSRect decorationRects[3] = {node.textTextureRect, CjguiEffectiveTransferTextCaretRect(ctx, node), node.textScrollbarRect};
    hash = CjguiEffectHashBytes(hash, decorationRects, sizeof(decorationRects));
    BOOL caretIsDeclared = node.textCaretIsDeclared;
    hash = CjguiEffectHashBytes(hash, &caretIsDeclared, sizeof(caretIsDeclared));
    BOOL caretHidden = node.textCaretHidden;
    hash = CjguiEffectHashBytes(hash, &caretHidden, sizeof(caretHidden));
    BOOL hasVector = node.hasVectorGeometry;
    hash = CjguiEffectHashBytes(hash, &hasVector, sizeof(hasVector));
    // The immutable copied vector value determines the lazily uploaded GPU
    // buffer. Do not hash the buffer pointer: first encoding may create it
    // after this signature is calculated, causing a false miss next frame.
    return hash;
}

// Tests and context-free fixtures retain the original declaration-only key.
// Production cache callers pass their session through the contextual form.
static uint64_t CjguiEffectHashPaintNode(uint64_t hash,
                                         CJGuiInternalComposableSceneNode *node,
                                         CjguiInternalRendererComposableNode value) {
    return CjguiEffectHashPaintNodeForSession(NULL, hash, node, value);
}

static uint64_t CjguiEffectHashPaintEnvironment(uint64_t hash, NSSize viewSize,
                                                 CGSize drawableSize, BOOL multisample) {
    double scale[2] = {drawableSize.width / MAX(1.0, viewSize.width),
                       drawableSize.height / MAX(1.0, viewSize.height)};
    uint64_t drawable[3] = {(uint64_t)drawableSize.width, (uint64_t)drawableSize.height,
                            multisample ? 4u : 1u};
    hash = CjguiEffectHashBytes(hash, drawable, sizeof(drawable));
    hash = CjguiEffectHashBytes(hash, scale, sizeof(scale));
    vector_float4 selection = CjguiMetalColorFromNSColor(CjguiComposablePlatformSelectionColor());
    vector_float4 accent = CjguiMetalColorFromNSColor(NSColor.keyboardFocusIndicatorColor);
    hash = CjguiEffectHashBytes(hash, &selection, sizeof(selection));
    return CjguiEffectHashBytes(hash, &accent, sizeof(accent));
}

// A complete source key, not sceneVersion: the root's final group settings
// are deliberately excluded so an opacity/mask/blend-only update reuses its
// transparent content. Descendant group settings remain in the bytes and
// invalidate ancestors. Native text decorations and resource generations are
// included even when Cangjie's scene tree did not change.
static NSString *CjguiEffectContentSignature(CJGuiInternalSession *ctx,
                                             NSArray<CJGuiInternalComposableSceneNode *> *nodes,
                                             NSUInteger start, NSUInteger end,
                                             uint32_t x, uint32_t y, uint32_t width, uint32_t height,
                                             BOOL multisample, NSSize viewSize, CGSize drawableSize) {
    uint64_t hash = UINT64_C(1469598103934665603);
    uint64_t geometry[5] = {x, y, width, height, multisample ? 4 : 1};
    hash = CjguiEffectHashBytes(hash, geometry, sizeof(geometry));
    hash = CjguiEffectHashPaintEnvironment(hash, viewSize, drawableSize, multisample);
    for (NSUInteger index = start; index < end; index++) {
        CJGuiInternalComposableSceneNode *node = nodes[index];
        CjguiInternalRendererComposableNode value = node.node;
        value.projectionVersion = 0;
        if (index == start) {
            value.effectGroupOpacity = 1.0;
            value.effectGroupBlendMode = 0;
            value.effectMaskPresent = 0;
            value.effectMaskStopCount = 0;
            value.effectMaskStartX = value.effectMaskStartY = 0.0;
            value.effectMaskEndX = value.effectMaskEndY = 0.0;
            value.effectMaskStop0Position = value.effectMaskStop0Alpha = 0.0;
            value.effectMaskStop1Position = value.effectMaskStop1Alpha = 0.0;
            value.effectMaskStop2Position = value.effectMaskStop2Alpha = 0.0;
            value.effectMaskStop3Position = value.effectMaskStop3Alpha = 0.0;
            value.effectBackdropBlurRadiusPoints = 0;
            value.effectBackdropBlurFallback = 0;
        }
        hash = CjguiEffectHashPaintNodeForSession(ctx, hash, node, value);
    }
    return [NSString stringWithFormat:@"%016llx", (unsigned long long)hash];
}

static uint64_t CjguiEffectLiveTargetBytes(CJGuiInternalMetalView *view) {
    uint64_t bytes = 0;
    // Enumerate the weak ledger directly. allObjects creates an autoreleased
    // strong array, which would itself keep retired targets alive for the
    // enclosing run-loop pool and make the budget observation change lifetime.
    for (CJGuiInternalComposableEffectTarget *target in view.effectTargetLedger) {
        if (target.byteCount > UINT64_MAX - bytes) return UINT64_MAX;
        bytes += target.byteCount;
    }
#ifdef CJGUI_INTERNAL_TESTING
    view.testEffectTargetCurrentBytes = bytes;
    if (bytes > view.testEffectTargetPeakBytes) view.testEffectTargetPeakBytes = bytes;
#endif
    return bytes;
}

static BOOL CjguiEffectPixelBounds(NSRect bounds, NSSize viewSize, CGSize drawableSize,
                                   uint32_t *outX, uint32_t *outY, uint32_t *outWidth, uint32_t *outHeight) {
    *outX = *outY = *outWidth = *outHeight = 0;
    if (NSIsEmptyRect(bounds) || viewSize.width <= 0.0 || viewSize.height <= 0.0 ||
        drawableSize.width <= 0.0 || drawableSize.height <= 0.0) return YES;
    double scaleX = drawableSize.width / viewSize.width, scaleY = drawableSize.height / viewSize.height;
    double left = MAX(0.0, floor(NSMinX(bounds) * scaleX));
    double top = MAX(0.0, floor(NSMinY(bounds) * scaleY));
    double right = MIN(drawableSize.width, ceil(NSMaxX(bounds) * scaleX));
    double bottom = MIN(drawableSize.height, ceil(NSMaxY(bounds) * scaleY));
    if (right <= left || bottom <= top) return YES;
    if (!isfinite(left) || !isfinite(top) || !isfinite(right) || !isfinite(bottom) ||
        right - left > CjguiEffectTargetDimensionCapacity ||
        bottom - top > CjguiEffectTargetDimensionCapacity ||
        (right - left) * (bottom - top) > CjguiEffectTargetPixelCapacity ||
        right > UINT32_MAX || bottom > UINT32_MAX) return NO;
    *outX = (uint32_t)left;
    *outY = (uint32_t)top;
    *outWidth = (uint32_t)(right - left);
    *outHeight = (uint32_t)(bottom - top);
    return YES;
}

static CjguiInternalRendererStatus CjguiPrepareEffectTargets(CJGuiInternalMetalView *view,
                                                               CGSize drawableSize) {
    CJGuiInternalSession *ctx = CjguiLookupSession(view.sessionToken);
    NSArray<CJGuiInternalComposableSceneNode *> *nodes = view.composableNodes;
    NSMutableArray<NSNumber *> *newIndices = [NSMutableArray array];
    NSMutableArray<NSString *> *newSignatures = [NSMutableArray array];
    NSMutableArray<NSValue *> *newRects = [NSMutableArray array];
    uint64_t neededBytes = 0;
    uint64_t liveBytes = CjguiEffectLiveTargetBytes(view);
    BOOL msaa = view.composableUsesMultisampling;
    for (NSUInteger index = 0; index < nodes.count; index++) {
        CJGuiInternalComposableSceneNode *node = nodes[index];
        CjguiInternalRendererComposableNode value = node.node;
        if (!value.effectGroupPresent) continue;
        NSRect bounds = CjguiEffectGroupOutputBounds(ctx, nodes, index, index + value.effectGroupSubtreeCount);
        uint32_t x, y, width, height;
        if (!CjguiEffectPixelBounds(bounds, view.bounds.size, drawableSize, &x, &y, &width, &height))
            return CJGUI_INTERNAL_RENDERER_EFFECT_RESOURCE_BUDGET_EXCEEDED;
        if (width == 0 || height == 0) { node.effectTarget = nil; continue; }
        NSString *signature = CjguiEffectContentSignature(ctx, nodes, index,
            index + value.effectGroupSubtreeCount, x, y, width, height, msaa,
            view.bounds.size, drawableSize);
        CJGuiInternalComposableEffectTarget *old = node.effectTarget;
        if (!old || ![old.contentSignature isEqualToString:signature] || old.invalidatedByGpuFailure)
            old = view.effectGroupCache[@(value.nodeId)];
        if (old && [old.contentSignature isEqualToString:signature] && !old.invalidatedByGpuFailure &&
            old.pixelX == x && old.pixelY == y && old.pixelWidth == width && old.pixelHeight == height) {
            node.effectTarget = old;
#ifdef CJGUI_INTERNAL_TESTING
            view.testEffectTargetReuseCount++;
#endif
            continue;
        }
        node.effectTarget = nil;
        uint64_t pixels = (uint64_t)width * height;
        uint64_t bytes = pixels * (msaa ? 20u : 4u);
        if (bytes > CjguiEffectTargetByteCapacity || neededBytes > CjguiEffectTargetByteCapacity - bytes)
            return CJGUI_INTERNAL_RENDERER_EFFECT_RESOURCE_BUDGET_EXCEEDED;
        neededBytes += bytes;
        [newIndices addObject:@(index)];
        [newSignatures addObject:signature];
        [newRects addObject:[NSValue valueWithRect:NSMakeRect(x, y, width, height)]];
    }
    if (liveBytes > CjguiEffectTargetByteCapacity ||
        neededBytes > CjguiEffectTargetByteCapacity - liveBytes)
        return CJGUI_INTERNAL_RENDERER_EFFECT_RESOURCE_BUDGET_EXCEEDED;
    for (NSUInteger plan = 0; plan < newIndices.count; plan++) {
        NSRect rect = newRects[plan].rectValue;
        uint32_t width = (uint32_t)rect.size.width, height = (uint32_t)rect.size.height;
        MTLTextureDescriptor *descriptor = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm
            width:width height:height mipmapped:NO];
        descriptor.storageMode = MTLStorageModePrivate;
        descriptor.usage = MTLTextureUsageRenderTarget | MTLTextureUsageShaderRead;
        id<MTLTexture> resolved = [view.device newTextureWithDescriptor:descriptor];
        if (!resolved) return CJGUI_INTERNAL_RENDERER_EFFECT_RESOURCE_BUDGET_EXCEEDED;
        id<MTLTexture> multisample = nil;
        if (msaa) {
            descriptor.textureType = MTLTextureType2DMultisample;
            descriptor.sampleCount = 4;
            descriptor.usage = MTLTextureUsageRenderTarget;
            multisample = [view.device newTextureWithDescriptor:descriptor];
            if (!multisample) return CJGUI_INTERNAL_RENDERER_EFFECT_RESOURCE_BUDGET_EXCEEDED;
        }
        CJGuiInternalComposableEffectTarget *target = [[CJGuiInternalComposableEffectTarget alloc] init];
        target.resolvedTexture = resolved;
        target.multisampleTexture = multisample;
        target.contentSignature = newSignatures[plan];
        target.pixelX = (uint32_t)rect.origin.x;
        target.pixelY = (uint32_t)rect.origin.y;
        target.pixelWidth = width;
        target.pixelHeight = height;
        target.byteCount = (uint64_t)width * height * (msaa ? 20u : 4u);
        target.needsRedraw = YES;
        [view.effectTargetLedger addObject:target];
        nodes[newIndices[plan].unsignedIntegerValue].effectTarget = target;
#ifdef CJGUI_INTERNAL_TESTING
        view.testEffectTargetAllocationCount++;
#endif
    }
    (void)CjguiEffectLiveTargetBytes(view);
    return CJGUI_INTERNAL_RENDERER_OK;
}

static BOOL CjguiEncodeEffectGroupComposite(CJGuiInternalMetalView *view, id<MTLRenderCommandEncoder> encoder,
                                            CGSize drawableSize, CJGuiInternalComposableSceneNode *node);

static BOOL CjguiEncodeComposableNodesRange(id view, id<MTLRenderCommandEncoder> encoder,
                                            CGSize drawableSize, uint32_t targetX, uint32_t targetY,
                                            uint32_t targetWidth, uint32_t targetHeight,
                                            NSUInteger start, NSUInteger end, NSUInteger ownGroupIndex) {
    CJGuiInternalMetalView *metalView = (CJGuiInternalMetalView *)view;
    if (metalView.composableNodes.count == 0 || start >= end) return YES;
    CJGuiInternalSession *ctx = CjguiLookupSession(metalView.sessionToken);
#ifdef CJGUI_INTERNAL_TESTING
    metalView.testComposableShapeNodeCount = 0;
    metalView.testComposableShapeBatchCount = 0;
    metalView.testComposableTextureDrawCount = 0;
    metalView.testComposableShapeVertexBytes = 0;
    metalView.testComposableMaxShapeBatchVertexBytes = 0;
    metalView.testComposableShapeVertexStride = (uint32_t)sizeof(CJGuiInternalMetalVertex);
    metalView.testComposableVectorDrawCount = 0;
    metalView.testComposableVectorBufferUploadCount = 0;
    metalView.testComposableVectorBufferReuseCount = 0;
    metalView.testComposableVectorBufferUploadBytes = 0;
#endif
    BOOL usesMultisampling = metalView.composableUsesMultisampling;
    id<MTLRenderPipelineState> scenePipeline = usesMultisampling
        ? metalView.composableMultisamplePipeline : metalView.composablePipeline;
    if (!scenePipeline) {
        NSError *error = nil;
        NSString *source = CjguiComposableSceneShaderSource();
        uint64_t librarySpan = CjguiFrameCallBegin(ctx, 379);
        id<MTLLibrary> library = [metalView.device newLibraryWithSource:source options:nil error:&error];
        CjguiFrameCallEnd(ctx, 379, librarySpan);
        if (!library) { NSLog(@"cjgui: composable metal library failed %@", error); return NO; }
        MTLRenderPipelineDescriptor *descriptor = [[MTLRenderPipelineDescriptor alloc] init];
        descriptor.vertexFunction = [library newFunctionWithName:@"cjgui_scene_vertex"];
        descriptor.fragmentFunction = [library newFunctionWithName:@"cjgui_scene_fragment"];
        descriptor.colorAttachments[0].pixelFormat = MTLPixelFormatBGRA8Unorm;
        descriptor.sampleCount = usesMultisampling ? 4 : 1;
        // Scene rectangles carry ordinary, non-premultiplied RGBA values from
        // the public Cangjie style.  They must compose in painter order just
        // like image texels, rather than overwriting the drawable with their
        // raw source alpha.
        descriptor.colorAttachments[0].blendingEnabled = YES;
        descriptor.colorAttachments[0].sourceRGBBlendFactor = MTLBlendFactorSourceAlpha;
        descriptor.colorAttachments[0].destinationRGBBlendFactor = MTLBlendFactorOneMinusSourceAlpha;
        descriptor.colorAttachments[0].sourceAlphaBlendFactor = MTLBlendFactorOne;
        descriptor.colorAttachments[0].destinationAlphaBlendFactor = MTLBlendFactorOneMinusSourceAlpha;
        uint64_t pipelineSpan = CjguiFrameCallBegin(ctx, 380);
        scenePipeline = [metalView.device newRenderPipelineStateWithDescriptor:descriptor error:&error];
        CjguiFrameCallEnd(ctx, 380, pipelineSpan);
        if (!scenePipeline) { NSLog(@"cjgui: composable metal pipeline failed %@", error); return NO; }
        if (usesMultisampling) metalView.composableMultisamplePipeline = scenePipeline;
        else metalView.composablePipeline = scenePipeline;
#ifdef CJGUI_INTERNAL_TESTING
        if (metalView.testComposablePipelineBuildCount < UINT64_MAX) metalView.testComposablePipelineBuildCount += 1;
#endif
    }
    CGFloat pointWidth = MAX(1.0, metalView.bounds.size.width);
    CGFloat pointHeight = MAX(1.0, metalView.bounds.size.height);
    CGFloat scaleX = drawableSize.width / pointWidth;
    CGFloat scaleY = drawableSize.height / pointHeight;
    [encoder setRenderPipelineState:scenePipeline];
    // Consecutive shape commands share one pipeline and vertex submission.
    // Texture nodes are explicit painter-order boundaries; we flush before
    // them rather than globally sorting by resource or alpha.
    NSMutableData *shapeBatch = [NSMutableData data];
    // Keep the historical six-vertex alignment: it preserves complete
    // rectangle submissions and is also a multiple of three, so vector
    // triangles never split across a `setVertexBytes` boundary.
    const NSUInteger maxShapeVerticesPerUpload =
        ((NSUInteger)CJGUI_INTERNAL_METAL_SET_VERTEX_BYTES_CAPACITY / sizeof(CJGuiInternalMetalVertex) / 6u) * 6u;
    if (maxShapeVerticesPerUpload < 6u) {
        NSLog(@"cjgui: composable shape vertex exceeds Metal setVertexBytes capacity");
        return NO;
    }
    BOOL (^flushShapeBatch)(void) = ^BOOL {
        if (shapeBatch.length == 0) return YES;
        const uint8_t *batchBytes = shapeBatch.bytes;
        NSUInteger remainingVertices = shapeBatch.length / sizeof(CJGuiInternalMetalVertex);
        NSUInteger vertexOffset = 0;
        while (remainingVertices > 0) {
            NSUInteger vertexCount = MIN(maxShapeVerticesPerUpload, remainingVertices);
            NSUInteger byteCount = vertexCount * sizeof(CJGuiInternalMetalVertex);
#ifdef CJGUI_INTERNAL_TESTING
            if (metalView.testComposableShapeBatchCount < UINT32_MAX) metalView.testComposableShapeBatchCount += 1;
            uint64_t bytes = byteCount;
            metalView.testComposableShapeVertexBytes = bytes > UINT64_MAX - metalView.testComposableShapeVertexBytes
                ? UINT64_MAX : metalView.testComposableShapeVertexBytes + bytes;
            metalView.testComposableMaxShapeBatchVertexBytes = MAX(metalView.testComposableMaxShapeBatchVertexBytes, bytes);
#endif
            [encoder setRenderPipelineState:scenePipeline];
            [encoder setVertexBytes:batchBytes + vertexOffset * sizeof(CJGuiInternalMetalVertex) length:byteCount atIndex:0];
            [encoder drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:vertexCount];
            vertexOffset += vertexCount;
            remainingVertices -= vertexCount;
        }
        [shapeBatch setLength:0];
        return YES;
    };
    [encoder setViewport:(MTLViewport){-(double)targetX, -(double)targetY,
                                      (double)drawableSize.width, (double)drawableSize.height, 0.0, 1.0}];
    [encoder setScissorRect:(MTLScissorRect){ 0, 0, targetWidth, targetHeight }];
    for (NSUInteger index = start; index < end; index++) {
        CJGuiInternalComposableSceneNode *node = metalView.composableNodes[index];
        CjguiInternalRendererComposableNode value = node.node;
        if (index != ownGroupIndex && value.effectGroupPresent) {
            if (!flushShapeBatch()) return NO;
            if (node.effectTarget && !CjguiEncodeEffectGroupComposite(metalView, encoder, drawableSize, node)) return NO;
            [encoder setRenderPipelineState:scenePipeline];
            index += value.effectGroupSubtreeCount - 1;
            continue;
        }
        if (value.width <= 0 || value.height <= 0) continue;
        // An empty own clip (ancestor chain ∩ bounds) hides the node's body,
        // but an outer shadow can still paint outside those bounds and remain
        // visible in the viewport. Gate that case on the shadow's own output
        // range against the ancestor clip chain and the drawable, then submit
        // only the shadow pass; no body pixel can survive the ancestor clip,
        // so fill/border/vector/text/image passes are skipped below.
        NSRect visualClip = CjguiComposableVisualClipBounds(node);
        NSRect visualBody = NSIntersectionRect(CjguiComposableVisualNodeRect(node), visualClip);
        if (NSIsEmptyRect(visualBody)) {
            if (value.shadowPresent == 0 || !(value.shadowAlpha > 0.0)) continue;
            NSRect shadowOutput = CjguiComposableShadowOutputRect(node);
            if (!CjguiComposableShadowOutputIntersectsAncestorClip(node, shadowOutput)) continue;
            if (!CjguiComposableShadowOutputIntersectsDrawable(shadowOutput, scaleX, scaleY, drawableSize)) continue;
            CjguiAppendMetalShadow(shapeBatch, pointWidth, pointHeight, node, value);
            continue;
        }
        uint64_t sx = (uint64_t)MAX(0.0, floor(NSMinX(visualClip) * scaleX));
        uint64_t sy = (uint64_t)MAX(0.0, floor(NSMinY(visualClip) * scaleY));
        uint64_t ex = (uint64_t)MAX(0.0, ceil(NSMaxX(visualClip) * scaleX));
        uint64_t ey = (uint64_t)MAX(0.0, ceil(NSMaxY(visualClip) * scaleY));
        uint64_t sw = ex > sx ? ex - sx : 0;
        uint64_t sh = ey > sy ? ey - sy : 0;
        if (sx >= drawableSize.width || sy >= drawableSize.height) continue;
        if (sx + sw > drawableSize.width) sw = drawableSize.width - sx;
        if (sy + sh > drawableSize.height) sh = drawableSize.height - sy;
        if (sw == 0 || sh == 0) continue;
        vector_float4 fill = { (float)value.fillRed, (float)value.fillGreen, (float)value.fillBlue, (float)value.fillAlpha };
        vector_float4 border = { (float)value.borderRed, (float)value.borderGreen, (float)value.borderBlue, (float)value.borderAlpha };
        NSUInteger shapeBytesBefore = shapeBatch.length;
        // Outer shadow paints before the node's own fill so the node covers the
        // shadow center, preserving painter order within the node. The shadow
        // quad only obeys the inherited ancestor clip chain.
        CjguiAppendMetalShadow(shapeBatch, pointWidth, pointHeight, node, value);
        CjguiAppendMetalShape(shapeBatch, pointWidth, pointHeight, node, value,
                              CjguiComposableVisualNodeRect(node), fill, border);
        // A vector's immutable local topology lives in its own retained Metal
        // buffer. Flush preceding generic shapes at this exact painter-order
        // boundary, then bind only the compact topology plus one small node
        // uniform; never expand it into 176-byte generic vertices each frame.
        if (node.hasVectorGeometry) {
            if (!flushShapeBatch()) return NO;
            if (!CjguiEncodeMetalVectorShape(encoder, pointWidth, pointHeight, metalView, node)) return NO;
            [encoder setRenderPipelineState:scenePipeline];
        }
#ifdef CJGUI_INTERNAL_TESTING
        if (shapeBatch.length > shapeBytesBefore && metalView.testComposableShapeNodeCount < UINT32_MAX) {
            metalView.testComposableShapeNodeCount += 1;
        }
        // The comparison path is still legal: every complete rectangle is
        // uploaded as six vertices, well below Metal's 4 KiB setVertexBytes
        // ceiling. It differs only in submission granularity; painter order,
        // vertex data and all resource boundaries stay identical.
        if (shapeBatch.length > shapeBytesBefore && metalView.testComposableShapeSubmissionMode == 1) {
            if (!flushShapeBatch()) return NO;
        }
#endif
        if (CjguiComposableNodeHasGpuText(value.nodeKind)) {
            // Selection backgrounds must paint after this node's fill but
            // before its immutable glyph texture. Foreground decorations are
            // appended after the texture and flushed before the next scene
            // node, preserving the same per-node painter order as a fully
            // rasterized active input.
            NSUInteger decorationsBefore = shapeBatch.length;
            vector_float4 selectionFill = CjguiMetalColorFromNSColor(CjguiComposablePlatformSelectionColor());
            for (NSValue *valueRect in CjguiEffectiveTransferTextSelectionRects(ctx, node)) {
                CjguiAppendMetalTextDecoration(shapeBatch, pointWidth, pointHeight, node, valueRect.rectValue, selectionFill);
            }
            for (NSDictionary *decoration in CjguiEffectiveDeclaredSelectionDecorations(ctx, node)) {
                NSValue *valueRect = decoration[@"rect"];
                NSColor *color = decoration[@"color"];
                if (![valueRect isKindOfClass:NSValue.class] || ![color isKindOfClass:NSColor.class]) continue;
                vector_float4 fill = CjguiMetalColorFromNSColor(color);
                fill.w *= (float)value.textAlpha;
                CjguiAppendMetalTextDecoration(shapeBatch, pointWidth, pointHeight, node, valueRect.rectValue, fill);
            }
            BOOL hasTextTexture = node.textTexture || node.textTileTextures.count > 0;
            if (hasTextTexture && !flushShapeBatch()) return NO;
            if (hasTextTexture && !CjguiEnsureComposableImagePipeline(metalView)) return NO;
            if (hasTextTexture) [encoder setRenderPipelineState:usesMultisampling
                ? metalView.composableMultisampleImagePipeline : metalView.composableImagePipeline];
#ifdef CJGUI_INTERNAL_TESTING
            if (hasTextTexture && metalView.testComposableTextureDrawCount < UINT32_MAX)
                metalView.testComposableTextureDrawCount += 1;
#endif
            NSRect textureRect = node.textTextureRect;
            if (node.textTexture && !NSIsEmptyRect(textureRect)) {
                CjguiEncodeMetalTexture(encoder, pointWidth, pointHeight,
                                        NSMinX(textureRect), NSMinY(textureRect),
                                        NSWidth(textureRect), NSHeight(textureRect), node.textTexture, node, YES,
                                        (float)value.textAlpha);
            }
            for (NSUInteger tileIndex = 0; tileIndex < node.textTileTextures.count; tileIndex++) {
                NSRect tileRect = node.textTileRects[tileIndex].rectValue;
                CjguiEncodeMetalTexture(encoder, pointWidth, pointHeight,
                                        NSMinX(tileRect), NSMinY(tileRect),
                                        NSWidth(tileRect), NSHeight(tileRect),
                                        node.textTileTextures[tileIndex], node, YES, (float)value.textAlpha);
            }
            if (hasTextTexture) [encoder setRenderPipelineState:scenePipeline];
            vector_float4 foregroundFill = CjguiMetalColorFromNSColor(NSColor.keyboardFocusIndicatorColor);
            // An owner-declared caret keeps the colour it had while it was baked into the body
            // texture (the node's own text colour, opaque -- the texture is rasterized opaque
            // and re-multiplied by textAlpha at encode). The accent colour stays for composition
            // underlines and for the caret the hidden proxy derives for itself.
            vector_float4 caretFill = { (float)value.textRed, (float)value.textGreen, (float)value.textBlue, 1.0f };
            for (NSValue *valueRect in node.textMarkedRects) {
                CjguiAppendMetalTextDecoration(shapeBatch, pointWidth, pointHeight, node, valueRect.rectValue, foregroundFill);
            }
            if (!node.textCaretHidden) {
                CjguiAppendMetalTextDecoration(shapeBatch, pointWidth, pointHeight, node,
                                               CjguiEffectiveTransferTextCaretRect(ctx, node),
                                               node.textCaretIsDeclared ? caretFill : foregroundFill);
            }
            vector_float4 scrollbarFill = {0.75f, 0.75f, 0.75f, 0.48f};
            CjguiAppendMetalTextDecoration(shapeBatch, pointWidth, pointHeight, node, node.textScrollbarRect, scrollbarFill);
            if (shapeBatch.length > decorationsBefore && !flushShapeBatch()) return NO;
            [encoder setRenderPipelineState:scenePipeline];
        }
        if (value.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_IMAGE && node.imageTexture) {
            if (!flushShapeBatch()) return NO;
            if (!CjguiEnsureComposableImagePipeline(metalView)) return NO;
            if (metalView.encodedImageTextures &&
                [metalView.encodedImageTextures indexOfObjectIdenticalTo:node.imageTexture] == NSNotFound) {
                [metalView.encodedImageTextures addObject:node.imageTexture];
            }
            CGFloat sourceWidth = MAX(1.0, (CGFloat)node.imageTexture.width);
            CGFloat sourceHeight = MAX(1.0, (CGFloat)node.imageTexture.height);
            CGFloat scale = value.imageContentMode == 2 ? MAX((CGFloat)value.width / sourceWidth, (CGFloat)value.height / sourceHeight)
                                                        : MIN((CGFloat)value.width / sourceWidth, (CGFloat)value.height / sourceHeight);
            CGFloat drawWidth = sourceWidth * scale;
            CGFloat drawHeight = sourceHeight * scale;
            [encoder setRenderPipelineState:usesMultisampling
                ? metalView.composableMultisampleImagePipeline : metalView.composableImagePipeline];
#ifdef CJGUI_INTERNAL_TESTING
            if (metalView.testComposableTextureDrawCount < UINT32_MAX) metalView.testComposableTextureDrawCount += 1;
#endif
            CjguiEncodeMetalTexture(encoder, pointWidth, pointHeight,
                                    value.x + ((CGFloat)value.width - drawWidth) / 2.0,
                                    value.y + ((CGFloat)value.height - drawHeight) / 2.0,
                                    drawWidth, drawHeight, node.imageTexture, node, NO, 1.0f);
            [encoder setRenderPipelineState:scenePipeline];
        }
    }
    return flushShapeBatch();
}

static BOOL CjguiEncodeComposableNodes(id view, id<MTLRenderCommandEncoder> encoder, CGSize drawableSize) {
    CJGuiInternalMetalView *metalView = (CJGuiInternalMetalView *)view;
    return CjguiEncodeComposableNodesRange(view, encoder, drawableSize, 0, 0,
        (uint32_t)drawableSize.width, (uint32_t)drawableSize.height,
        0, metalView.composableNodes.count, NSUIntegerMax);
}

typedef struct CjguiEffectCompositeVertex {
    vector_float2 position;
    vector_float2 scenePoint;
    vector_float2 texCoord;
} CjguiEffectCompositeVertex;

typedef struct CjguiEffectCompositeUniform {
    vector_float4 maskRect;
    vector_float4 endpoints;
    vector_float4 positions;
    vector_float4 alphas;
    float opacity;
    uint32_t maskPresent;
    uint32_t stopCount;
    uint32_t reserved;
    vector_float4 foregroundPixels;
    vector_float4 backdropPixels;
    vector_float4 scaleAndBackdrop;
    vector_float4 clips[CJGUI_INTERNAL_COMPOSABLE_CLIP_CONSTRAINT_CAPACITY];
    vector_float4 clipRadii;
    vector_float4 clipCount;
} CjguiEffectCompositeUniform;

// Phase 0: normal premult source-over. Phases 1 and 2 are adjacent fixed
// blending draws for the exact premult multiply formula. They read the prior
// attachment only via Metal's defined blend unit, not by sampling the bound
// render target in a fragment shader.
static id<MTLRenderPipelineState> CjguiEffectPipeline(CJGuiInternalMetalView *view, uint32_t phase) {
    NSString *key = [NSString stringWithFormat:@"%u-%u", view.composableUsesMultisampling ? 4u : 1u, phase];
    id<MTLRenderPipelineState> pipeline = view.effectPipelines[key];
    if (pipeline) return pipeline;
    NSString *source = @"#include <metal_stdlib>\nusing namespace metal;\n"
        "struct V { float2 position; float2 scenePoint; float2 uv; };\n"
        "struct U { float4 maskRect; float4 endpoints; float4 positions; float4 alphas; float opacity; uint maskPresent; uint stopCount; uint reserved; float4 foregroundPixels; float4 backdropPixels; float4 scaleAndBackdrop; float4 clips[4]; float4 clipRadii; float4 clipCount; };\n"
        "struct O { float4 position [[position]]; float2 point; float2 uv; };\n"
        "vertex O effect_vertex(uint i [[vertex_id]], const device V *v [[buffer(0)]]) { O o; o.position=float4(v[i].position,0,1); o.point=v[i].scenePoint; o.uv=v[i].uv; return o; }\n"
        "float roundedDistance(float2 point, float2 origin, float2 size, float radius) { float r=min(max(radius,0.0),min(size.x,size.y)*0.5); float2 q=abs((point-origin)-size*0.5)-(size*0.5-r); return length(max(q,float2(0.0)))+min(max(q.x,q.y),0.0)-r; }\n"
        "fragment float4 effect_fragment(O in [[stage_in]], constant U &u [[buffer(1)]], texture2d<float> image [[texture(0)]], texture2d<float> backdrop [[texture(1)]]) { constexpr sampler s(coord::normalized,address::clamp_to_edge,filter::nearest); float4 c; if(u.scaleAndBackdrop.z>0.5) { float2 px=in.point*u.scaleAndBackdrop.xy; float4 f=float4(0); if(px.x>=u.foregroundPixels.x&&px.y>=u.foregroundPixels.y&&px.x<u.foregroundPixels.x+u.foregroundPixels.z&&px.y<u.foregroundPixels.y+u.foregroundPixels.w) f=image.sample(s,(px-u.foregroundPixels.xy)/u.foregroundPixels.zw); float4 b=float4(0); if(in.point.x>=u.maskRect.x&&in.point.y>=u.maskRect.y&&in.point.x<u.maskRect.x+u.maskRect.z&&in.point.y<u.maskRect.y+u.maskRect.w&&px.x>=u.backdropPixels.x&&px.y>=u.backdropPixels.y&&px.x<u.backdropPixels.x+u.backdropPixels.z&&px.y<u.backdropPixels.y+u.backdropPixels.w) { bool inside=true; for(uint j=0;j<uint(u.clipCount.x);j++) { if(roundedDistance(in.point,u.clips[j].xy,u.clips[j].zw,u.clipRadii[j])>0.0) { inside=false; break; } } if(inside) b=backdrop.sample(s,(px-u.backdropPixels.xy)/u.backdropPixels.zw); } c=f+(1.0-f.a)*b; } else c=image.sample(s,in.uv); float q=u.opacity; if(u.maskPresent!=0u) { float2 p=in.point; float4 r=u.maskRect; if(p.x<r.x||p.y<r.y||p.x>=r.x+r.z||p.y>=r.y+r.w) q=0.0; else { float2 local=(p-r.xy)/max(r.zw,float2(1e-6)); float2 axis=u.endpoints.zw-u.endpoints.xy; float t=clamp(dot(local-u.endpoints.xy,axis)/dot(axis,axis),0.0,1.0); float a=u.alphas[0]; for(uint i=1u;i<u.stopCount;i++) { if(t<u.positions[i]) { float d=u.positions[i]-u.positions[i-1u]; if(d>0.0) a=mix(u.alphas[i-1u],u.alphas[i],clamp((t-u.positions[i-1u])/d,0.0,1.0)); break; } a=u.alphas[i]; } q*=a; } } return c*q; }\n";
    NSError *error = nil;
    id<MTLLibrary> library = [view.device newLibraryWithSource:source options:nil error:&error];
    if (!library) { NSLog(@"cjgui: effect metal library failed %@", error); return nil; }
    MTLRenderPipelineDescriptor *descriptor = [[MTLRenderPipelineDescriptor alloc] init];
    descriptor.vertexFunction = [library newFunctionWithName:@"effect_vertex"];
    descriptor.fragmentFunction = [library newFunctionWithName:@"effect_fragment"];
    descriptor.colorAttachments[0].pixelFormat = MTLPixelFormatBGRA8Unorm;
    descriptor.sampleCount = view.composableUsesMultisampling ? 4 : 1;
    descriptor.colorAttachments[0].blendingEnabled = YES;
    descriptor.colorAttachments[0].rgbBlendOperation = MTLBlendOperationAdd;
    descriptor.colorAttachments[0].alphaBlendOperation = MTLBlendOperationAdd;
    if (phase == 0) {
        descriptor.colorAttachments[0].sourceRGBBlendFactor = MTLBlendFactorOne;
        descriptor.colorAttachments[0].destinationRGBBlendFactor = MTLBlendFactorOneMinusSourceAlpha;
        descriptor.colorAttachments[0].sourceAlphaBlendFactor = MTLBlendFactorOne;
        descriptor.colorAttachments[0].destinationAlphaBlendFactor = MTLBlendFactorOneMinusSourceAlpha;
    } else if (phase == 1) {
        descriptor.colorAttachments[0].sourceRGBBlendFactor = MTLBlendFactorDestinationColor;
        descriptor.colorAttachments[0].destinationRGBBlendFactor = MTLBlendFactorOneMinusSourceAlpha;
        descriptor.colorAttachments[0].sourceAlphaBlendFactor = MTLBlendFactorZero;
        descriptor.colorAttachments[0].destinationAlphaBlendFactor = MTLBlendFactorOne;
    } else {
        descriptor.colorAttachments[0].sourceRGBBlendFactor = MTLBlendFactorOneMinusDestinationAlpha;
        descriptor.colorAttachments[0].destinationRGBBlendFactor = MTLBlendFactorOne;
        descriptor.colorAttachments[0].sourceAlphaBlendFactor = MTLBlendFactorOne;
        descriptor.colorAttachments[0].destinationAlphaBlendFactor = MTLBlendFactorOneMinusSourceAlpha;
    }
    pipeline = [view.device newRenderPipelineStateWithDescriptor:descriptor error:&error];
    if (!pipeline) { NSLog(@"cjgui: effect pipeline failed %@", error); return nil; }
    view.effectPipelines[key] = pipeline;
#ifdef CJGUI_INTERNAL_TESTING
    view.testComposablePipelineBuildCount++;
#endif
    return pipeline;
}

static BOOL CjguiEncodeEffectGroupComposite(CJGuiInternalMetalView *view, id<MTLRenderCommandEncoder> encoder,
                                            CGSize drawableSize, CJGuiInternalComposableSceneNode *node) {
    CjguiInternalRendererComposableNode value = node.node;
    CJGuiInternalComposableEffectTarget *target = node.effectTarget;
    CJGuiInternalComposableEffectTarget *backdrop = value.effectBackdropBlurRadiusPoints > 0 ? node.backdropTarget : nil;
    BOOL hasForeground = target && target.resolvedTexture && target.pixelWidth > 0 && target.pixelHeight > 0;
    BOOL hasBackdrop = backdrop && backdrop.resolvedTexture && backdrop.pixelWidth > 0 && backdrop.pixelHeight > 0;
    if (!hasForeground && !hasBackdrop) return YES;
    double scaleX = drawableSize.width / MAX(1.0, view.bounds.size.width);
    double scaleY = drawableSize.height / MAX(1.0, view.bounds.size.height);
    double left = hasForeground ? target.pixelX : backdrop.pixelX;
    double top = hasForeground ? target.pixelY : backdrop.pixelY;
    double right = left + (hasForeground ? target.pixelWidth : backdrop.pixelWidth);
    double bottom = top + (hasForeground ? target.pixelHeight : backdrop.pixelHeight);
    if (hasBackdrop) {
        left = MIN(left, backdrop.pixelX); top = MIN(top, backdrop.pixelY);
        right = MAX(right, backdrop.pixelX + backdrop.pixelWidth);
        bottom = MAX(bottom, backdrop.pixelY + backdrop.pixelHeight);
    }
    CjguiEffectCompositeVertex vertices[6] = {
        {{-1.0f + 2.0f * left / drawableSize.width, 1.0f - 2.0f * top / drawableSize.height},
         {left / scaleX, top / scaleY}, {0, 0}},
        {{-1.0f + 2.0f * right / drawableSize.width, 1.0f - 2.0f * top / drawableSize.height},
         {right / scaleX, top / scaleY}, {1, 0}},
        {{-1.0f + 2.0f * left / drawableSize.width, 1.0f - 2.0f * bottom / drawableSize.height},
         {left / scaleX, bottom / scaleY}, {0, 1}},
        {{-1.0f + 2.0f * right / drawableSize.width, 1.0f - 2.0f * top / drawableSize.height},
         {right / scaleX, top / scaleY}, {1, 0}},
        {{-1.0f + 2.0f * right / drawableSize.width, 1.0f - 2.0f * bottom / drawableSize.height},
         {right / scaleX, bottom / scaleY}, {1, 1}},
        {{-1.0f + 2.0f * left / drawableSize.width, 1.0f - 2.0f * bottom / drawableSize.height},
         {left / scaleX, bottom / scaleY}, {0, 1}},
    };
    CjguiEffectCompositeUniform uniform = {
        .maskRect = {(float)((double)value.x + node.geometry.translateX),
                     (float)((double)value.y + node.geometry.translateY),
                     (float)value.width, (float)value.height},
        .endpoints = {(float)value.effectMaskStartX, (float)value.effectMaskStartY,
                      (float)value.effectMaskEndX, (float)value.effectMaskEndY},
        .positions = {(float)value.effectMaskStop0Position, (float)value.effectMaskStop1Position,
                      (float)value.effectMaskStop2Position, (float)value.effectMaskStop3Position},
        .alphas = {(float)value.effectMaskStop0Alpha, (float)value.effectMaskStop1Alpha,
                   (float)value.effectMaskStop2Alpha, (float)value.effectMaskStop3Alpha},
        .opacity = (float)value.effectGroupOpacity,
        .maskPresent = value.effectMaskPresent,
        .stopCount = value.effectMaskStopCount,
        .foregroundPixels = hasForeground ? (vector_float4){target.pixelX, target.pixelY, target.pixelWidth, target.pixelHeight} : (vector_float4){0, 0, 0, 0},
        .backdropPixels = hasBackdrop ? (vector_float4){backdrop.pixelX, backdrop.pixelY, backdrop.pixelWidth, backdrop.pixelHeight} : (vector_float4){0, 0, 0, 0},
        .scaleAndBackdrop = {(float)scaleX, (float)scaleY, hasBackdrop ? 1.0f : 0.0f, 0.0f},
    };
    CjguiPopulateMetalVisualClipChain(uniform.clips, &uniform.clipRadii, &uniform.clipCount, node);
    [encoder setVertexBytes:vertices length:sizeof(vertices) atIndex:0];
    [encoder setFragmentBytes:&uniform length:sizeof(uniform) atIndex:1];
    [encoder setFragmentTexture:hasForeground ? target.resolvedTexture : backdrop.resolvedTexture atIndex:0];
    [encoder setFragmentTexture:hasBackdrop ? backdrop.resolvedTexture : nil atIndex:1];
    uint32_t startPhase = value.effectGroupBlendMode == 1 ? 1 : 0;
    uint32_t endPhase = value.effectGroupBlendMode == 1 ? 2 : 0;
    for (uint32_t phase = startPhase; phase <= endPhase; phase++) {
        id<MTLRenderPipelineState> pipeline = CjguiEffectPipeline(view, phase);
        if (!pipeline) return NO;
        [encoder setRenderPipelineState:pipeline];
        [encoder drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:6];
#ifdef CJGUI_INTERNAL_TESTING
        view.testEffectCompositeDrawCount++;
#endif
    }
    return YES;
}

static BOOL CjguiComposableSceneHasEffectGroups(NSArray<CJGuiInternalComposableSceneNode *> *nodes) {
    for (CJGuiInternalComposableSceneNode *node in nodes) {
        if (node.node.effectGroupPresent) return YES;
    }
    return NO;
}

// Bottom-up rendering makes every child target available before a parent's
// content pass. Encoding is only a preparation fact: a target stays dirty
// until the command buffer actually submits, and a changed content signature
// allocates a different generation.
static CjguiInternalRendererStatus CjguiEncodeEffectGroupContents(
    CJGuiInternalMetalView *view, id<MTLCommandBuffer> commandBuffer, CGSize drawableSize,
    NSMutableArray<CJGuiInternalComposableEffectTarget *> *redrawnTargets) {
    CjguiInternalRendererStatus prepared = CjguiPrepareEffectTargets(view, drawableSize);
    if (prepared != CJGUI_INTERNAL_RENDERER_OK) return prepared;
    NSArray<CJGuiInternalComposableSceneNode *> *nodes = view.composableNodes;
    for (NSUInteger reverse = nodes.count; reverse > 0; reverse--) {
        NSUInteger index = reverse - 1;
        CJGuiInternalComposableSceneNode *node = nodes[index];
        CjguiInternalRendererComposableNode value = node.node;
        CJGuiInternalComposableEffectTarget *target = node.effectTarget;
        if (!value.effectGroupPresent || !target || !target.needsRedraw) continue;
        MTLRenderPassDescriptor *pass = [MTLRenderPassDescriptor renderPassDescriptor];
        pass.colorAttachments[0].texture = target.multisampleTexture ?: target.resolvedTexture;
        pass.colorAttachments[0].resolveTexture = target.multisampleTexture ? target.resolvedTexture : nil;
        pass.colorAttachments[0].loadAction = MTLLoadActionClear;
        pass.colorAttachments[0].clearColor = MTLClearColorMake(0, 0, 0, 0);
        pass.colorAttachments[0].storeAction = target.multisampleTexture
            ? MTLStoreActionMultisampleResolve : MTLStoreActionStore;
        id<MTLRenderCommandEncoder> encoder = [commandBuffer renderCommandEncoderWithDescriptor:pass];
        if (!encoder) return CJGUI_INTERNAL_RENDERER_METAL_ENCODER_UNAVAILABLE;
        BOOL encoded = CjguiEncodeComposableNodesRange(view, encoder, drawableSize,
            target.pixelX, target.pixelY, target.pixelWidth, target.pixelHeight,
            index, index + value.effectGroupSubtreeCount, index);
        [encoder endEncoding];
        if (!encoded) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        [redrawnTargets addObject:target];
#ifdef CJGUI_INTERNAL_TESTING
        view.testEffectContentRedrawCount++;
        view.testEffectPassCount++;
#endif
    }
    return CJGUI_INTERNAL_RENDERER_OK;
}

// The in-app backdrop is the resolved root painter prefix immediately before
// the one admitted blur group. This key deliberately excludes later siblings
// and group foreground, while retaining every actual earlier contributor in
// the sampled halo. Rendering configuration and native decoration colours are
// part of the environment even when sceneVersion does not change.
static NSString *CjguiBackdropSignature(CJGuiInternalMetalView *view, NSUInteger groupIndex,
                                        uint32_t qx, uint32_t qy, uint32_t qw, uint32_t qh,
                                        uint32_t sy, uint32_t sh, uint32_t radius,
                                        float sigmaX, float sigmaY, uint32_t haloX, uint32_t haloY,
                                        CGSize drawableSize, MTLClearColor clearColor) {
    CJGuiInternalSession *ctx = CjguiLookupSession(view.sessionToken);
    uint64_t hash = UINT64_C(1469598103934665603);
    uint64_t geometry[] = {qx, qy, qw, qh, sy, sh, radius,
                           (uint64_t)drawableSize.width, (uint64_t)drawableSize.height,
                           view.composableUsesMultisampling ? 4u : 1u};
    hash = CjguiEffectHashBytes(hash, geometry, sizeof(geometry));
    hash = CjguiEffectHashPaintEnvironment(hash, view.bounds.size, drawableSize,
                                           view.composableUsesMultisampling);
    float sigma[2] = {sigmaX, sigmaY};
    uint32_t support[2] = {haloX, haloY};
    hash = CjguiEffectHashBytes(hash, sigma, sizeof(sigma));
    hash = CjguiEffectHashBytes(hash, support, sizeof(support));
    double clear[] = {clearColor.red, clearColor.green, clearColor.blue, clearColor.alpha};
    hash = CjguiEffectHashBytes(hash, clear, sizeof(clear));
    double scaleX = drawableSize.width / MAX(1.0, view.bounds.size.width);
    double scaleY = drawableSize.height / MAX(1.0, view.bounds.size.height);
    // Use the encoder's actual float kernel support for dependency filtering.
    // Re-deriving it with double rounding can miss a halo-only painter.
    double sampleLeft = MAX(0.0, (double)qx - haloX) / scaleX;
    double sampleRight = MIN(drawableSize.width, (double)qx + qw + haloX) / scaleX;
    NSRect sample = NSMakeRect(sampleLeft, sy / scaleY, sampleRight - sampleLeft, sh / scaleY);
    NSArray<CJGuiInternalComposableSceneNode *> *nodes = view.composableNodes;
    for (NSUInteger index = 0; index < groupIndex;) {
        CJGuiInternalComposableSceneNode *node = nodes[index];
        CjguiInternalRendererComposableNode value = node.node;
        BOOL group = value.effectGroupPresent != 0;
        NSRect output = group
            ? CjguiEffectGroupOutputBounds(ctx, nodes, index, index + value.effectGroupSubtreeCount)
            : CjguiEffectNodeOutputBounds(ctx, node);
        NSUInteger next = group ? index + value.effectGroupSubtreeCount : index + 1;
        if (!NSIsEmptyRect(NSIntersectionRect(output, sample))) {
            hash = CjguiEffectHashBytes(hash, &index, sizeof(index));
            hash = CjguiEffectHashPaintNodeForSession(ctx, hash, node, value);
            if (group) hash = CjguiEffectHashString(hash, node.effectTarget.contentSignature);
        }
        index = next;
    }
    return [NSString stringWithFormat:@"%016llx", (unsigned long long)hash];
}

static BOOL CjguiEnsureBackdropPipelines(CJGuiInternalMetalView *view) {
    if (view.backdropHorizontalPipeline && view.backdropVerticalPipeline) return YES;
    NSString *source = @"#include <metal_stdlib>\nusing namespace metal;\n"
        "kernel void backdrop_horizontal(texture2d<float,access::read> src [[texture(0)]], texture2d<float,access::write> dst [[texture(1)]], constant uint *p [[buffer(0)]], constant float *w [[buffer(1)]], uint2 id [[thread_position_in_grid]]) { if(id.x>=p[2]||id.y>=p[5]) return; int x=int(p[0]+id.x), y=int(p[4]+id.y); float4 c=float4(0); for(int k=-int(p[8]);k<=int(p[8]);k++) c+=src.read(uint2(uint(clamp(x+k,0,int(p[6])-1)),uint(y)))*w[k+int(p[8])]; dst.write(c,id); }\n"
        "kernel void backdrop_vertical(texture2d<float,access::read> src [[texture(0)]], texture2d<float,access::write> dst [[texture(1)]], constant uint *p [[buffer(0)]], constant float *w [[buffer(1)]], uint2 id [[thread_position_in_grid]]) { if(id.x>=p[2]||id.y>=p[3]) return; int y=int(p[1]+id.y); float4 c=float4(0); for(int k=-int(p[8]);k<=int(p[8]);k++) { int sourceY=clamp(y+k,0,int(p[7])-1)-int(p[4]); c+=src.read(uint2(id.x,uint(sourceY)))*w[k+int(p[8])]; } dst.write(c,id); }\n";
    NSError *error = nil;
    id<MTLLibrary> library = [view.device newLibraryWithSource:source options:nil error:&error];
    if (!library) { NSLog(@"cjgui: backdrop metal library failed %@", error); return NO; }
    id<MTLFunction> horizontal = [library newFunctionWithName:@"backdrop_horizontal"];
    id<MTLFunction> vertical = [library newFunctionWithName:@"backdrop_vertical"];
    if (!horizontal || !vertical) return NO;
    view.backdropHorizontalPipeline = [view.device newComputePipelineStateWithFunction:horizontal error:&error];
    view.backdropVerticalPipeline = [view.device newComputePipelineStateWithFunction:vertical error:&error];
    if (!view.backdropHorizontalPipeline || !view.backdropVerticalPipeline) {
        NSLog(@"cjgui: backdrop compute pipeline failed %@", error);
        return NO;
    }
    return YES;
}

static void CjguiBackdropWeights(uint32_t kernelRadius, float sigma, float weights[97]) {
    float sum = 0.0f;
    for (uint32_t index = 0; index <= 2 * kernelRadius; index++) {
        int distance = (int)index - (int)kernelRadius;
        weights[index] = expf(-0.5f * (float)(distance * distance) / (sigma * sigma));
        sum += weights[index];
    }
    for (uint32_t index = 0; index <= 2 * kernelRadius; index++) weights[index] /= sum;
}

typedef struct CjguiInternalBackdropOutcome {
    uint32_t requestedRadiusPoints;
    uint32_t mode;
    uint32_t reason;
} CjguiInternalBackdropOutcome;

// Returns YES only after both blur passes were encoded. On failure the caller
// abandons this command buffer and submits a fresh, unblurred accepted frame;
// a partial target is never published as a cache hit.
static BOOL CjguiEncodeBackdrop(CJGuiInternalMetalView *view, id<MTLCommandBuffer> commandBuffer,
                                CGSize drawableSize, MTLClearColor clearColor,
                                NSMutableArray<CJGuiInternalComposableEffectTarget *> *scratch,
                                NSMutableArray<CJGuiInternalComposableEffectTarget *> *written,
                                CjguiInternalBackdropOutcome *outcome) {
    *outcome = (CjguiInternalBackdropOutcome){0, CJGUI_INTERNAL_BACKDROP_NONE,
                                              CJGUI_INTERNAL_BACKDROP_REASON_NOT_REQUESTED};
    NSArray<CJGuiInternalComposableSceneNode *> *nodes = view.composableNodes;
    NSUInteger groupIndex = NSNotFound;
    for (NSUInteger i = 0; i < nodes.count; i++) {
        if (nodes[i].node.effectBackdropBlurRadiusPoints > 0) groupIndex = i;
        else nodes[i].backdropTarget = nil;
    }
    if (groupIndex == NSNotFound) return YES;
    CJGuiInternalComposableSceneNode *node = nodes[groupIndex];
    CjguiInternalRendererComposableNode value = node.node;
    outcome->requestedRadiusPoints = value.effectBackdropBlurRadiusPoints;
    outcome->mode = CJGUI_INTERNAL_BACKDROP_BLURRED;
    outcome->reason = CJGUI_INTERNAL_BACKDROP_REASON_NONE;
    node.backdropTarget = nil;
    if (clearColor.alpha < 1.0) {
        outcome->mode = CJGUI_INTERNAL_BACKDROP_UNBLURRED;
        outcome->reason = CJGUI_INTERNAL_BACKDROP_REASON_NON_OPAQUE_CLEAR;
#ifdef CJGUI_INTERNAL_TESTING
        view.testBackdropFallbackCount++;
#endif
        return YES;
    }
    NSRect bounds = NSIntersectionRect(CjguiComposableVisualNodeRect(node),
                                      CjguiComposableVisualClipBounds(node));
    uint32_t qx, qy, qw, qh;
    if (!CjguiEffectPixelBounds(bounds, view.bounds.size, drawableSize, &qx, &qy, &qw, &qh) || !qw || !qh) {
        outcome->mode = CJGUI_INTERNAL_BACKDROP_NONE;
        outcome->reason = CJGUI_INTERNAL_BACKDROP_REASON_EMPTY_ROI;
#ifdef CJGUI_INTERNAL_TESTING
        view.testBackdropFallbackCount++;
#endif
        return YES;
    }
    double scaleX = drawableSize.width / MAX(1.0, view.bounds.size.width);
    double scaleY = drawableSize.height / MAX(1.0, view.bounds.size.height);
    float sigmaX = (float)(value.effectBackdropBlurRadiusPoints * scaleX / 2.0);
    float sigmaY = (float)(value.effectBackdropBlurRadiusPoints * scaleY / 2.0);
    uint32_t haloX = (uint32_t)ceilf(3.0f * sigmaX), haloY = (uint32_t)ceilf(3.0f * sigmaY);
    if (!isfinite(sigmaX) || !isfinite(sigmaY) || sigmaX <= 0 || sigmaY <= 0 ||
        haloX > 48 || haloY > 48 || drawableSize.width > CjguiEffectTargetDimensionCapacity ||
        drawableSize.height > CjguiEffectTargetDimensionCapacity ||
        drawableSize.width * drawableSize.height > CjguiEffectTargetPixelCapacity) {
        outcome->mode = CJGUI_INTERNAL_BACKDROP_UNBLURRED;
        outcome->reason = CJGUI_INTERNAL_BACKDROP_REASON_KERNEL_LIMIT;
#ifdef CJGUI_INTERNAL_TESTING
        view.testBackdropFallbackCount++;
#endif
        return YES;
    }
    uint32_t sy = qy > haloY ? qy - haloY : 0;
    uint32_t ey = MIN((uint32_t)drawableSize.height, qy + qh + haloY);
    uint32_t sh = ey - sy;
    NSString *signature = CjguiBackdropSignature(view, groupIndex, qx, qy, qw, qh, sy, sh,
                                                 value.effectBackdropBlurRadiusPoints,
                                                 sigmaX, sigmaY, haloX, haloY, drawableSize, clearColor);
    CJGuiInternalComposableEffectTarget *old = view.backdropCache[@(value.nodeId)];
    if (old && old.gpuCompleted && !old.invalidatedByGpuFailure && !old.needsRedraw &&
        [old.contentSignature isEqualToString:signature]) {
        node.backdropTarget = old;
#ifdef CJGUI_INTERNAL_TESTING
        view.testBackdropCacheHitCount++;
#endif
        return YES;
    }
    uint64_t pixels = (uint64_t)drawableSize.width * (uint64_t)drawableSize.height;
    uint64_t replayBytes = pixels * (view.composableUsesMultisampling ? 20u : 4u);
    uint64_t pingBytes = (uint64_t)qw * sh * 8u;
    uint64_t resultBytes = (uint64_t)qw * qh * 4u;
    uint64_t liveBytes = CjguiEffectLiveTargetBytes(view);
    if (liveBytes > CjguiEffectTargetByteCapacity ||
        replayBytes > CjguiEffectTargetByteCapacity - liveBytes ||
        pingBytes > CjguiEffectTargetByteCapacity - liveBytes - replayBytes ||
        resultBytes > CjguiEffectTargetByteCapacity - liveBytes - replayBytes - pingBytes) {
        outcome->mode = CJGUI_INTERNAL_BACKDROP_UNBLURRED;
        outcome->reason = CJGUI_INTERNAL_BACKDROP_REASON_RESOURCE_BUDGET;
#ifdef CJGUI_INTERNAL_TESTING
        view.testBackdropFallbackCount++;
#endif
        return YES;
    }
    if (!CjguiEnsureBackdropPipelines(view)) {
        outcome->mode = CJGUI_INTERNAL_BACKDROP_UNBLURRED;
        outcome->reason = CJGUI_INTERNAL_BACKDROP_REASON_PIPELINE_UNAVAILABLE;
#ifdef CJGUI_INTERNAL_TESTING
        view.testBackdropFallbackCount++;
#endif
        return YES;
    }
    MTLTextureDescriptor *desc = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm
        width:(NSUInteger)drawableSize.width height:(NSUInteger)drawableSize.height mipmapped:NO];
    desc.storageMode = MTLStorageModePrivate;
    desc.usage = MTLTextureUsageRenderTarget | MTLTextureUsageShaderRead;
    id<MTLTexture> replay = [view.device newTextureWithDescriptor:desc];
    id<MTLTexture> replayMSAA = nil;
    if (replay && view.composableUsesMultisampling) {
        desc.textureType = MTLTextureType2DMultisample;
        desc.sampleCount = 4;
        desc.usage = MTLTextureUsageRenderTarget;
        replayMSAA = [view.device newTextureWithDescriptor:desc];
    }
    desc = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA16Float
        width:qw height:sh mipmapped:NO];
    desc.storageMode = MTLStorageModePrivate;
    desc.usage = MTLTextureUsageShaderRead | MTLTextureUsageShaderWrite;
    id<MTLTexture> ping = [view.device newTextureWithDescriptor:desc];
    desc = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm
        width:qw height:qh mipmapped:NO];
    desc.storageMode = MTLStorageModePrivate;
    desc.usage = MTLTextureUsageShaderWrite | MTLTextureUsageShaderRead;
    id<MTLTexture> blurred = [view.device newTextureWithDescriptor:desc];
    if (!replay || (view.composableUsesMultisampling && !replayMSAA) || !ping || !blurred) {
        outcome->mode = CJGUI_INTERNAL_BACKDROP_UNBLURRED;
        outcome->reason = CJGUI_INTERNAL_BACKDROP_REASON_ALLOCATION_FAILED;
#ifdef CJGUI_INTERNAL_TESTING
        view.testBackdropFallbackCount++;
#endif
        return YES;
    }
    CJGuiInternalComposableEffectTarget *replayOwner = [[CJGuiInternalComposableEffectTarget alloc] init];
    replayOwner.resolvedTexture = replay; replayOwner.multisampleTexture = replayMSAA;
    replayOwner.byteCount = replayBytes;
    CJGuiInternalComposableEffectTarget *pingOwner = [[CJGuiInternalComposableEffectTarget alloc] init];
    pingOwner.resolvedTexture = ping; pingOwner.byteCount = pingBytes;
    CJGuiInternalComposableEffectTarget *result = [[CJGuiInternalComposableEffectTarget alloc] init];
    result.resolvedTexture = blurred; result.byteCount = resultBytes;
    result.pixelX = qx; result.pixelY = qy; result.pixelWidth = qw; result.pixelHeight = qh;
    result.samplePixelX = qx > haloX ? qx - haloX : 0;
    result.samplePixelY = sy;
    result.samplePixelWidth = MIN((uint32_t)drawableSize.width, qx + qw + haloX) - result.samplePixelX;
    result.samplePixelHeight = sh;
    result.contentSignature = signature; result.needsRedraw = YES;
    [view.effectTargetLedger addObject:replayOwner];
    [view.effectTargetLedger addObject:pingOwner];
    [view.effectTargetLedger addObject:result];
    [scratch addObject:replayOwner]; [scratch addObject:pingOwner];
    MTLRenderPassDescriptor *pass = [MTLRenderPassDescriptor renderPassDescriptor];
    pass.colorAttachments[0].texture = replayMSAA ?: replay;
    pass.colorAttachments[0].resolveTexture = replayMSAA ? replay : nil;
    pass.colorAttachments[0].loadAction = MTLLoadActionClear;
    pass.colorAttachments[0].storeAction = replayMSAA ? MTLStoreActionMultisampleResolve : MTLStoreActionStore;
    pass.colorAttachments[0].clearColor = clearColor;
    id<MTLRenderCommandEncoder> prefix = [commandBuffer renderCommandEncoderWithDescriptor:pass];
    if (!prefix) return NO;
    BOOL prefixEncoded = CjguiEncodeComposableNodesRange(view, prefix, drawableSize, 0, 0,
        (uint32_t)drawableSize.width, (uint32_t)drawableSize.height, 0, groupIndex, NSUIntegerMax);
    [prefix endEncoding];
    if (!prefixEncoded) return NO;
#ifdef CJGUI_INTERNAL_TESTING
    view.testBackdropPrefixPassCount++;
#endif
    uint32_t params[9] = {qx, qy, qw, qh, sy, sh, (uint32_t)drawableSize.width,
                          (uint32_t)drawableSize.height, haloX};
    float weights[97] = {0};
    CjguiBackdropWeights(haloX, sigmaX, weights);
    id<MTLComputeCommandEncoder> compute = [commandBuffer computeCommandEncoder];
    if (!compute) return NO;
    [compute setComputePipelineState:view.backdropHorizontalPipeline];
    [compute setTexture:replay atIndex:0]; [compute setTexture:ping atIndex:1];
    [compute setBytes:params length:sizeof(params) atIndex:0];
    [compute setBytes:weights length:(2 * haloX + 1) * sizeof(float) atIndex:1];
    [compute dispatchThreads:MTLSizeMake(qw, sh, 1) threadsPerThreadgroup:MTLSizeMake(8, 8, 1)];
    [compute endEncoding];
#ifdef CJGUI_INTERNAL_TESTING
    view.testBackdropHorizontalPassCount++;
#endif
    params[8] = haloY;
    CjguiBackdropWeights(haloY, sigmaY, weights);
    compute = [commandBuffer computeCommandEncoder];
    if (!compute) return NO;
    [compute setComputePipelineState:view.backdropVerticalPipeline];
    [compute setTexture:ping atIndex:0]; [compute setTexture:blurred atIndex:1];
    [compute setBytes:params length:sizeof(params) atIndex:0];
    [compute setBytes:weights length:(2 * haloY + 1) * sizeof(float) atIndex:1];
    [compute dispatchThreads:MTLSizeMake(qw, qh, 1) threadsPerThreadgroup:MTLSizeMake(8, 8, 1)];
    [compute endEncoding];
#ifdef CJGUI_INTERNAL_TESTING
    view.testBackdropVerticalPassCount++;
#endif
    node.backdropTarget = result;
    [written addObject:result];
    (void)CjguiEffectLiveTargetBytes(view);
    return YES;
}

static void CjguiPublishAcceptedEffectCache(CJGuiInternalMetalView *view) {
    NSMutableDictionary<NSNumber *, CJGuiInternalComposableEffectTarget *> *accepted = [NSMutableDictionary dictionary];
    NSMutableDictionary<NSNumber *, CJGuiInternalComposableEffectTarget *> *backdrops = [NSMutableDictionary dictionary];
    for (CJGuiInternalComposableSceneNode *node in view.composableNodes) {
        if (node.node.effectGroupPresent && node.effectTarget)
            accepted[@(node.node.nodeId)] = node.effectTarget;
        if (node.node.effectBackdropBlurRadiusPoints > 0 && node.backdropTarget)
            backdrops[@(node.node.nodeId)] = node.backdropTarget;
    }
    view.effectGroupCache = accepted;
    view.backdropCache = backdrops;
    (void)CjguiEffectLiveTargetBytes(view);
}

static void CjguiReleaseFailedCandidateEffectTargets(CJGuiInternalSession *ctx) {
    if (!ctx) return;
    NSSet<CJGuiInternalComposableSceneNode *> *accepted = [NSSet setWithArray:ctx.composableNodes ?: @[]];
    for (CJGuiInternalComposableSceneNode *node in ctx.stagedComposableNodes) {
        // COW may have reused the exact accepted node object. Clearing its
        // target would mutate the old scene, so release only candidate copies.
        if (![accepted containsObject:node]) {
            node.effectTarget = nil;
            node.backdropTarget = nil;
        }
    }
    (void)CjguiEffectLiveTargetBytes(ctx.view);
}

static NSRect CjguiComposableRect(CJGuiInternalComposableSceneNode *node, NSView *view) {
    (void)view;
    // The composable overlay is flipped, as is the Cangjie layout space: both
    // start at the window's top-left.  Do not invert here; doing so made text,
    // hit testing and AX frames disagree with the Metal scene.
    return CjguiComposableVisualNodeRect(node);
}

static NSRect CjguiComposableClipConstraintRect(CJGuiInternalComposableSceneNode *node, uint32_t index) {
    CGFloat x = 0, y = 0, width = 0, height = 0, radius = 0;
    CjguiComposableVisualClipConstraintAt(node, index, &x, &y, &width, &height, &radius);
    return NSMakeRect(x, y, MAX(0.0, width), MAX(0.0, height));
}

// The layout projection also supplies this rectangle intersection for cheap
// culling and AX bounds.  It is never used as the final rounded clip: every
// draw and hit test below evaluates the complete ancestor chain.
static NSRect CjguiComposableClipBounds(CJGuiInternalComposableSceneNode *node) {
    return CjguiComposableVisualClipBounds(node);
}

// Scene geometry is expressed in the overlay's flipped coordinate space.  A
// rounded inherited clip must therefore have the same meaning for Metal,
// TextKit's remaining multiline path, and pointer routing.  A decoration
// radius alone is not consulted here: only the resolved clip radius controls
// whether children may draw or receive an event.
static BOOL CjguiPointInRoundedRect(NSPoint point, NSRect rect, CGFloat requestedRadius) {
    if (!NSPointInRect(point, rect)) return NO;
    CGFloat radius = MIN(MAX(0.0, requestedRadius), MIN(NSWidth(rect), NSHeight(rect)) / 2.0);
    if (radius <= 0.0) return YES;
    CGFloat minX = NSMinX(rect), maxX = NSMaxX(rect);
    CGFloat minY = NSMinY(rect), maxY = NSMaxY(rect);
    CGFloat centreX = point.x < minX + radius ? minX + radius :
                      (point.x > maxX - radius ? maxX - radius : point.x);
    CGFloat centreY = point.y < minY + radius ? minY + radius :
                      (point.y > maxY - radius ? maxY - radius : point.y);
    CGFloat dx = point.x - centreX, dy = point.y - centreY;
    return dx * dx + dy * dy <= radius * radius;
}

static BOOL CjguiPointInComposableNodeClip(NSPoint point, CJGuiInternalComposableSceneNode *node, NSView *view) {
    (void)view;
    return node && CjguiComposablePointInClipChain(point.x, point.y, node);
}

static BOOL CjguiComposableVectorPointInSimplePolygon(CjguiInternalComposableVectorPoint point,
                                                      const CjguiInternalComposableVectorPoint *points,
                                                      uint32_t pointCount) {
    if (!points || pointCount < 3) return NO;
    BOOL inside = NO;
    for (uint32_t index = 0, previous = pointCount - 1; index < pointCount; previous = index++) {
        CjguiInternalComposableVectorPoint start = points[previous];
        CjguiInternalComposableVectorPoint end = points[index];
        if (fabs(CjguiComposableVectorCross(start, end, point)) <= CjguiComposableVectorEpsilon &&
            CjguiComposableVectorBetween(point.x, start.x, end.x) &&
            CjguiComposableVectorBetween(point.y, start.y, end.y)) return YES;
        BOOL crosses = ((start.y > point.y) != (end.y > point.y));
        if (crosses && point.x < (end.x - start.x) * (point.y - start.y) / (end.y - start.y) + start.x) {
            inside = !inside;
        }
    }
    return inside;
}

static BOOL CjguiComposableVectorPointNearSegment(CjguiInternalComposableVectorPoint point,
                                                  CjguiInternalComposableVectorPoint start,
                                                  CjguiInternalComposableVectorPoint end,
                                                  double halfWidth, uint32_t cap,
                                                  BOOL startCap, BOOL endCap) {
    if (halfWidth <= 0.0) return NO;
    CjguiInternalComposableVectorPoint direction = {0};
    if (!CjguiComposableVectorUnitDirection(start, end, &direction)) return NO;
    CjguiInternalComposableVectorPoint delta = CjguiComposableVectorSubtract(point, start);
    double length = CjguiComposableVectorLength(CjguiComposableVectorSubtract(end, start));
    double along = delta.x * direction.x + delta.y * direction.y;
    double across = fabs(delta.x * -direction.y + delta.y * direction.x);
    if (along >= 0.0 && along <= length && across <= halfWidth) return YES;
    if (cap == CJGUI_INTERNAL_VECTOR_CAP_SQUARE) {
        if (startCap && along >= -halfWidth && along < 0.0 && across <= halfWidth) return YES;
        if (endCap && along > length && along <= length + halfWidth && across <= halfWidth) return YES;
    }
    if (cap == CJGUI_INTERNAL_VECTOR_CAP_ROUND) {
        if (startCap && along < 0.0 && CjguiComposableVectorLength(delta) <= halfWidth) return YES;
        CjguiInternalComposableVectorPoint endDelta = CjguiComposableVectorSubtract(point, end);
        if (endCap && along > length && CjguiComposableVectorLength(endDelta) <= halfWidth) return YES;
    }
    return NO;
}

static BOOL CjguiComposableVectorContainsPoint(CJGuiInternalComposableSceneNode *node, NSPoint point) {
    if (!node || !node.hasVectorGeometry) return NO;
    CjguiInternalRendererComposableNode value = node.node;
    CjguiInternalComposableVectorGeometry geometry = node.vectorGeometry;
    if (value.width <= 0 || value.height <= 0 || geometry.viewBoxWidth <= 0.0 || geometry.viewBoxHeight <= 0.0) return NO;
    CjguiInternalComposableVectorPoint local = CjguiComposableVectorPoint(
        ((double)point.x - ((double)value.x + node.geometry.translateX)) * geometry.viewBoxWidth / (double)value.width,
        ((double)point.y - ((double)value.y + node.geometry.translateY)) * geometry.viewBoxHeight / (double)value.height);
    BOOL fillVisible = geometry.fillAlpha > 0.0;
    BOOL strokeVisible = geometry.strokeAlpha > 0.0 && geometry.strokeWidth > 0.0;
    if (geometry.kind == CJGUI_INTERNAL_VECTOR_ELLIPSE) {
        double normalizedX = (local.x - geometry.center.x) / geometry.radiusX;
        double normalizedY = (local.y - geometry.center.y) / geometry.radiusY;
        double normalizedDistance = normalizedX * normalizedX + normalizedY * normalizedY;
        if (fillVisible && normalizedDistance <= 1.0) return YES;
        if (strokeVisible) {
            double radial = sqrt(MAX(0.0, normalizedDistance));
            return fabs(radial - 1.0) * MIN(geometry.radiusX, geometry.radiusY) <= geometry.strokeWidth / 2.0;
        }
        return NO;
    }
    if (geometry.kind == CJGUI_INTERNAL_VECTOR_SIMPLE_POLYGON && fillVisible &&
        CjguiComposableVectorPointInSimplePolygon(local, geometry.points, geometry.pointCount)) return YES;
    if (!strokeVisible || geometry.pointCount < 2) return NO;
    double halfWidth = geometry.strokeWidth / 2.0;
    if (geometry.kind == CJGUI_INTERNAL_VECTOR_SIMPLE_POLYGON) {
        for (uint32_t index = 0; index < geometry.pointCount; index++) {
            uint32_t next = index + 1 == geometry.pointCount ? 0 : index + 1;
            if (CjguiComposableVectorPointNearSegment(local, geometry.points[index], geometry.points[next],
                                                       halfWidth, CJGUI_INTERNAL_VECTOR_CAP_BUTT, NO, NO)) return YES;
        }
        return NO;
    }
    for (uint32_t index = 0; index + 1 < geometry.pointCount; index++) {
        if (CjguiComposableVectorPointNearSegment(local, geometry.points[index], geometry.points[index + 1], halfWidth,
                                                   geometry.cap, index == 0, index + 2 == geometry.pointCount)) return YES;
    }
    return NO;
}

static BOOL CjguiComposableNodeContainsPoint(CJGuiInternalComposableSceneNode *node, NSPoint point, NSView *view) {
    if (!node || !NSPointInRect(point, CjguiComposableRect(node, view))) return NO;
    if (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_VECTOR_GRAPHIC) {
        return CjguiComposableVectorContainsPoint(node, point);
    }
    return YES;
}

static void CjguiClipComposableNode(CJGuiInternalComposableSceneNode *node, NSView *view) {
    if (!node) return;
    (void)view;
    uint32_t count = CjguiComposableClipConstraintCount(node.node);
    for (uint32_t i = 0; i < count; i++) {
        NSRect rect = CjguiComposableClipConstraintRect(node, i);
        CGFloat x = 0, y = 0, width = 0, height = 0, radius = 0;
        CjguiComposableVisualClipConstraintAt(node, i, &x, &y, &width, &height, &radius);
        radius = MIN(MAX(0.0, radius), MIN(NSWidth(rect), NSHeight(rect)) / 2.0);
        if (radius <= 0.0) {
            NSRectClip(rect);
        } else {
            [[NSBezierPath bezierPathWithRoundedRect:rect xRadius:radius yRadius:radius] addClip];
        }
    }
}

// Font family codes: 0 system, 1 monospaced, 2 system italic, 3 monospaced
// italic. Italic rides the family field so no native node field has to change.
static NSFont *CjguiComposableFontForStyle(double requested, uint32_t fontWeight, uint32_t fontFamily) {
    return CjguiComposableFontSnapshotForStyle(requested, fontWeight, fontFamily);
}

static NSFont *CjguiComposableFont(CJGuiInternalComposableSceneNode *node) {
    return CjguiComposableFontForStyle(
        node ? node.node.fontSize : 13.0,
        node ? node.node.fontWeight : 0,
        node ? node.node.fontFamily : 0
    );
}

#ifdef CJGUI_INTERNAL_TESTING
static CGRect CjguiMapMultilineDiagnosticRect(CGRect rect, CGAffineTransform transform) {
    CGPoint corners[4] = {
        CGPointApplyAffineTransform(CGPointMake(CGRectGetMinX(rect), CGRectGetMinY(rect)), transform),
        CGPointApplyAffineTransform(CGPointMake(CGRectGetMaxX(rect), CGRectGetMinY(rect)), transform),
        CGPointApplyAffineTransform(CGPointMake(CGRectGetMinX(rect), CGRectGetMaxY(rect)), transform),
        CGPointApplyAffineTransform(CGPointMake(CGRectGetMaxX(rect), CGRectGetMaxY(rect)), transform),
    };
    CGFloat minX = corners[0].x, maxX = corners[0].x, minY = corners[0].y, maxY = corners[0].y;
    for (NSUInteger index = 1; index < 4; index++) {
        minX = MIN(minX, corners[index].x); maxX = MAX(maxX, corners[index].x);
        minY = MIN(minY, corners[index].y); maxY = MAX(maxY, corners[index].y);
    }
    return CGRectMake(minX, minY, maxX - minX, maxY - minY);
}

static void CjguiLogMultilineGlyphDrawingState(uint64_t nodeId, NSLayoutManager *layoutManager,
                                                NSTextContainer *container, NSRange visibleGlyphs,
                                                NSPoint origin, NSString *value) {
    // All diagnostics below include whole-document UTF-16 formatting, font
    // enumeration and CoreText fallback lookup. The opt-in must guard the
    // work itself, not just the final NSLog, or TESTING builds distort raster
    // latency by tens of milliseconds per tile.
    if (!CjguiTestVerboseGlyphDiagnosticsEnabled()) return;
    CGContextRef context = NSGraphicsContext.currentContext.CGContext;
    if (!context || !layoutManager || !container || visibleGlyphs.location == NSNotFound || visibleGlyphs.length == 0) return;
    CGAffineTransform ctm = CGContextGetCTM(context);
    CGAffineTransform textMatrix = CGContextGetTextMatrix(context);
    CGPoint textPosition = CGContextGetTextPosition(context);
    NSRange containerGlyphs = [layoutManager glyphRangeForTextContainer:container];
    NSGlyph glyph = [layoutManager glyphAtIndex:visibleGlyphs.location];
    NSGlyphProperty property = [layoutManager propertyForGlyphAtIndex:visibleGlyphs.location];
    NSRect line = [layoutManager lineFragmentRectForGlyphAtIndex:visibleGlyphs.location effectiveRange:NULL];
    NSRect used = [layoutManager lineFragmentUsedRectForGlyphAtIndex:visibleGlyphs.location effectiveRange:NULL];
    NSPoint glyphLocation = [layoutManager locationForGlyphAtIndex:visibleGlyphs.location];
    NSRect glyphBounds = [layoutManager boundingRectForGlyphRange:NSMakeRange(visibleGlyphs.location, 1)
                                                   inTextContainer:container];
    NSRect glyphUserBounds = NSOffsetRect(glyphBounds, origin.x, origin.y);
    CGRect glyphDeviceBounds = CjguiMapMultilineDiagnosticRect(NSRectToCGRect(glyphUserBounds), ctm);
    CGRect clipUserBounds = CGContextGetClipBoundingBox(context);
    NSMutableString *utf16 = [NSMutableString string];
    for (NSUInteger index = 0; index < value.length; index++) [utf16 appendFormat:@"%04X", [value characterAtIndex:index]];
    NSDictionary *attributes = value.length > 0 ? [layoutManager.textStorage attributesAtIndex:0 effectiveRange:NULL] : @{};
    NSMutableString *fontRuns = [NSMutableString string];
    [layoutManager.textStorage enumerateAttributesInRange:NSMakeRange(0, value.length) options:0
                                               usingBlock:^(NSDictionary<NSAttributedStringKey, id> *runAttributes,
                                                            NSRange range, BOOL *stop) {
        (void)stop;
        NSFont *runFont = runAttributes[NSFontAttributeName];
        [fontRuns appendFormat:@"%lu:%lu=%@;", (unsigned long)range.location, (unsigned long)range.length,
         runFont.fontName ?: @"(none)"];
    }];
    NSMutableString *glyphs = [NSMutableString string];
    NSUInteger glyphEnd = MIN(NSMaxRange(visibleGlyphs), visibleGlyphs.location + 8);
    for (NSUInteger index = visibleGlyphs.location; index < glyphEnd; index++) {
        [glyphs appendFormat:@"%lu:%u/%lu;", (unsigned long)index, [layoutManager glyphAtIndex:index],
         (unsigned long)[layoutManager propertyForGlyphAtIndex:index]];
    }
    NSFont *font = attributes[NSFontAttributeName];
    CGGlyph directGlyph = 0;
    BOOL hasDirectGlyph = NO;
    CTFontRef fallback = NULL;
    if (font && value.length > 0) {
        CTFontRef baseFont = (__bridge CTFontRef)font;
        UniChar firstCharacter = [value characterAtIndex:0];
        hasDirectGlyph = CTFontGetGlyphsForCharacters(baseFont, &firstCharacter, &directGlyph, 1);
        fallback = CTFontCreateForString(baseFont, (__bridge CFStringRef)value, CFRangeMake(0, value.length));
    }
    NSString *fallbackName = fallback ? CFBridgingRelease(CTFontCopyPostScriptName(fallback)) : @"(none)";
    if (fallback) CFRelease(fallback);
    if (CjguiTestVerboseGlyphDiagnosticsEnabled()) NSLog(@"cjgui: multiline glyph-draw node=%llu context=%p flipped=%d ctm=(%.3f,%.3f,%.3f,%.3f,%.3f,%.3f) textMatrix=(%.3f,%.3f,%.3f,%.3f,%.3f,%.3f) textPosition=(%.3f,%.3f) clipUser=%@ origin=%@ value=%@ utf16=%@ font=%@ fontRuns=%@ directGlyph=%u direct=%d cascadeCandidate=%@ containerGlyphs=%lu:%lu visible=%lu:%lu glyphs=%@ glyph0=%u property=%lu line=%@ used=%@ location=%@ glyphBounds=%@ glyphUser=%@ glyphDevice=%@",
          nodeId, context, NSGraphicsContext.currentContext.isFlipped,
          ctm.a, ctm.b, ctm.c, ctm.d, ctm.tx, ctm.ty,
          textMatrix.a, textMatrix.b, textMatrix.c, textMatrix.d, textMatrix.tx, textMatrix.ty,
          textPosition.x, textPosition.y, NSStringFromRect(NSRectFromCGRect(clipUserBounds)), NSStringFromPoint(origin),
          value ?: @"", utf16, font, fontRuns, directGlyph, hasDirectGlyph, fallbackName,
          (unsigned long)containerGlyphs.location, (unsigned long)containerGlyphs.length,
          (unsigned long)visibleGlyphs.location, (unsigned long)visibleGlyphs.length, glyphs,
          glyph, (unsigned long)property, NSStringFromRect(line), NSStringFromRect(used),
          NSStringFromPoint(glyphLocation), NSStringFromRect(glyphBounds), NSStringFromRect(glyphUserBounds),
          NSStringFromRect(NSRectFromCGRect(glyphDeviceBounds)));
}
#endif

@class CJGuiInternalComposableSceneOverlay;

// A self-drawn multiline node needs TextKit for exactly the same glyph and
// line-fragment geometry used by input hit testing.  Keep that layout bounded
// and projection-owned rather than allocating a second TextKit graph on every
// display pass.  The current projection version is part of the cache key, so
// a changed projection cannot reuse an older semantic snapshot.
@interface CJGuiInternalComposableMultilineLayoutCacheEntry : NSObject
@property(nonatomic, strong) NSTextStorage *storage;
@property(nonatomic, strong) NSLayoutManager *layoutManager;
@property(nonatomic, strong) NSTextContainer *container;
@property(nonatomic, strong) NSString *value;
@property(nonatomic, assign) CGFloat contentWidth;
@property(nonatomic, assign) CGFloat maximumScroll;
@end

@implementation CJGuiInternalComposableMultilineLayoutCacheEntry
@end

static BOOL CjguiComposableNodeIsTextInput(uint32_t kind) {
    return kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT_INPUT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_INTEGER_INPUT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT;
}

static BOOL CjguiComposableNodeAcceptsPointerCapture(uint32_t kind) {
    // 2026-09-26: TEXT 必须能开始指针捕获。此前白名单只有分隔条/滑块,文本节点在
    // beginPointerCaptureForNode 的第三条件被拒 ⇒ 从不产出 POINTER_* ⇒ 点击不落光标、
    // 无法拖选(用户实机反馈 + tools/check-hit-routing.sh FAIL:caretNode=-1)。
    // 文本输入类(MULTILINE/INTEGER)已有各自的输入处理,不在此纳入,避免双重捕获。
    return kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_SPLIT_DIVIDER ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_SLIDER ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT;
}

static BOOL CjguiComposableNodeIsPressable(uint32_t kind) {
    return kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BUTTON ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_VECTOR_GRAPHIC;
}

static BOOL CjguiComposableNodeIsAccessibilityElement(CJGuiInternalComposableSceneNode *node) {
    if (!node) return NO;
    // Disabled controls remain discoverable so an assistive client can tell
    // why the visible action cannot run. Static text is likewise a first
    // class semantic object even though it never receives pointer input.
    uint32_t kind = node.node.nodeKind;
    return node.node.isInteractive != 0 || kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT ||
        CjguiComposableNodeIsTextInput(kind) || kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BUTTON ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TABS ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_SCROLL_AREA ||
        node.node.semanticRole == 4 || node.node.semanticRole == 5;
}

@interface CJGuiInternalComposableAccessibilityAction : NSAccessibilityElement
@property(nonatomic, weak) CJGuiInternalComposableSceneOverlay *overlay;
@property(nonatomic, strong) CJGuiInternalComposableSceneNode *node;
@property(nonatomic, copy) NSString *identityKey;
@property(nonatomic, weak) CJGuiInternalComposableAccessibilityAction *semanticParent;
@property(nonatomic, strong) NSMutableArray<CJGuiInternalComposableAccessibilityAction *> *semanticChildren;
- (instancetype)initWithOverlay:(CJGuiInternalComposableSceneOverlay *)overlay node:(CJGuiInternalComposableSceneNode *)node;
@end

#ifdef CJGUI_INTERNAL_TESTING
// This test-only accumulator keeps scalar timings on the existing TextKit
// graph. It never becomes a text-system delegate or content owner.
@interface CJGuiInternalComposableActiveLayoutTrace : NSObject
@property(nonatomic, assign) uint64_t characterEnsureCount;
@property(nonatomic, assign) uint64_t characterEnsureMicros;
@property(nonatomic, assign) uint64_t boundingEnsureCount;
@property(nonatomic, assign) uint64_t boundingEnsureMicros;
@property(nonatomic, assign) uint64_t glyphIndexCount;
@property(nonatomic, assign) uint64_t glyphIndexMicros;
@property(nonatomic, assign) uint64_t lineFragmentCount;
@property(nonatomic, assign) uint64_t lineFragmentMicros;
@property(nonatomic, assign) uint64_t glyphLocationCount;
@property(nonatomic, assign) uint64_t glyphLocationMicros;
@property(nonatomic, assign) uint64_t positionProxyMicros;
@property(nonatomic, assign) uint64_t positionNoopWrites;
@property(nonatomic, assign) uint64_t positionChangedWrites;
@property(nonatomic, assign) uint64_t firstUnlaidBefore;
@property(nonatomic, assign) uint64_t firstUnlaidAfter;
@property(nonatomic, assign) uint64_t invalidatedLocation;
@property(nonatomic, assign) uint64_t invalidatedLength;
@property(nonatomic, assign) uint64_t revealMicros;
@property(nonatomic, assign) uint64_t candidateMicros;
@property(nonatomic, assign) uint64_t positionFirstUnlaidBefore;
@property(nonatomic, assign) uint64_t positionFirstUnlaidAfter;
@property(nonatomic, assign) uint64_t positionChangedMask;
- (void)reset;
@end

@implementation CJGuiInternalComposableActiveLayoutTrace
- (instancetype)init {
    self = [super init];
    if (self) [self reset];
    return self;
}
- (void)reset {
    self.characterEnsureCount = 0; self.characterEnsureMicros = 0;
    self.boundingEnsureCount = 0; self.boundingEnsureMicros = 0;
    self.glyphIndexCount = 0; self.glyphIndexMicros = 0;
    self.lineFragmentCount = 0; self.lineFragmentMicros = 0;
    self.glyphLocationCount = 0; self.glyphLocationMicros = 0;
    self.positionProxyMicros = 0; self.positionNoopWrites = 0; self.positionChangedWrites = 0;
    self.firstUnlaidBefore = UINT64_MAX; self.firstUnlaidAfter = UINT64_MAX;
    self.invalidatedLocation = UINT64_MAX; self.invalidatedLength = 0;
    self.revealMicros = 0; self.candidateMicros = 0;
    self.positionFirstUnlaidBefore = UINT64_MAX; self.positionFirstUnlaidAfter = UINT64_MAX;
    self.positionChangedMask = 0;
}
@end

// This trace is intentionally scoped to one test-driven normal insertion.
// It records nested timing separately from the enclosing NSTextView call, so
// consumers do not add the fields together as an E2E duration.
@interface CJGuiInternalComposableInputCallbackTrace : NSObject
@property(nonatomic, assign) uint64_t superInsertMicros;
@property(nonatomic, assign) uint64_t modeChangeCount;
@property(nonatomic, assign) uint64_t modeChangeMicros;
@property(nonatomic, assign) uint64_t textCallbackCount;
@property(nonatomic, assign) uint64_t textCallbackMicros;
@property(nonatomic, assign) uint64_t selectionCallbackCount;
@property(nonatomic, assign) uint64_t pendingEditSelectionCount;
@property(nonatomic, assign) uint64_t selectionCallbackMicros;
@property(nonatomic, assign) uint64_t selectionRevealMicros;
@property(nonatomic, assign) uint64_t selectionQueueMicros;
@property(nonatomic, assign) uint64_t selectionAccessibilityMicros;
@property(nonatomic, assign) uint64_t refreshMicros;
@property(nonatomic, assign) uint64_t preparationMicros;
@property(nonatomic, assign) uint64_t wholeAttributeWriteCount;
@property(nonatomic, assign) uint64_t wholeAttributeCharacters;
@property(nonatomic, assign) uint64_t fallbackApplyCount;
@property(nonatomic, assign) uint64_t fallbackCharacters;
@property(nonatomic, assign) uint64_t fallbackMicros;
@property(nonatomic, assign) uint64_t decorationsMicros;
@property(nonatomic, assign) uint64_t keyConstructionMicros;
- (void)reset;
@end

@implementation CJGuiInternalComposableInputCallbackTrace
- (instancetype)init {
    self = [super init];
    if (self) [self reset];
    return self;
}
- (void)reset {
    self.superInsertMicros = 0; self.modeChangeCount = 0; self.modeChangeMicros = 0;
    self.textCallbackCount = 0; self.textCallbackMicros = 0;
    self.selectionCallbackCount = 0; self.pendingEditSelectionCount = 0;
    self.selectionCallbackMicros = 0; self.selectionRevealMicros = 0;
    self.selectionQueueMicros = 0; self.selectionAccessibilityMicros = 0;
    self.refreshMicros = 0; self.preparationMicros = 0;
    self.wholeAttributeWriteCount = 0; self.wholeAttributeCharacters = 0;
    self.fallbackApplyCount = 0; self.fallbackCharacters = 0; self.fallbackMicros = 0;
    self.decorationsMicros = 0; self.keyConstructionMicros = 0;
}
@end
#endif

