static BOOL CjguiInputProxyIsFirstResponder(CJGuiInternalComposableSceneOverlay *overlay) {
    NSWindow *window = overlay.window;
    return window && overlay.inputHost && window.firstResponder == overlay.inputHost &&
        overlay.inputHost.composableOverlay == overlay && overlay.inputProxy != nil;
}

// Narrow opt-in observation for the responder-chain Select All investigation.
// This reports routing scalars only; it never includes text or changes the
// action's admission, scope, queue, or selection behavior.
static BOOL CjguiSelectAllTraceEnabled(void) {
    const char *enabled = getenv("CJGUI_TRACE_IME_PUMP");
    return enabled && strcmp(enabled, "1") == 0;
}
static void CjguiTraceSelectAllDecision(const char *stage,
    CJGuiInternalComposableSceneOverlay *overlay, const char *reason,
    CJGuiInternalComposableSceneNode *scopeNode, BOOL hasEnqueueResult,
    BOOL enqueueResult, NSUInteger queueBefore) {
    if (!CjguiSelectAllTraceEnabled()) return;
    CJGuiInternalSession *session = overlay.session;
    NSWindow *window = overlay.window;
    NSResponder *first = window.firstResponder;
    NSString *firstClass = first ? NSStringFromClass([first class]) : @"none";
    BOOL activeValid = NO;
    for (CJGuiInternalComposableSceneNode *node in overlay.nodes) {
        if (node.index == overlay.activeNodeIndex && node.node.nodeId == overlay.activeNodeId &&
            node.node.resourceId == overlay.activeNodeResourceId &&
            node.node.nodeKind == overlay.activeNodeKind &&
            node.node.projectionVersion == overlay.activeProjectionVersion) {
            activeValid = YES;
            break;
        }
    }
    fprintf(stderr,
        "CJGUI_SELECT_ALL_TRACE stage=%s reason=%s session=%llu scene=%llu responder=%s "
        "host_first=%d proxy_first=%d active_valid=%d active_kind=%u active_id=%llu active_index=%ld "
        "active_resource=%lld active_projection=%llu scope_kind=%u scope_id=%llu scope_index=%ld "
        "enqueue_known=%d enqueue=%d queue_before=%lu queue_after=%lu\n",
        stage ?: "unknown", reason ?: "unknown",
        (unsigned long long)(session ? session.rendererSessionToken : 0),
        (unsigned long long)(session ? session.composableSceneVersion : 0),
        firstClass.UTF8String ?: "none",
        window && first == (NSResponder *)overlay.inputHost,
        CjguiInputProxyIsFirstResponder(overlay), activeValid, overlay.activeNodeKind,
        (unsigned long long)overlay.activeNodeId, (long)overlay.activeNodeIndex,
        (long long)overlay.activeNodeResourceId, (unsigned long long)overlay.activeProjectionVersion,
        scopeNode ? scopeNode.node.nodeKind : 0,
        (unsigned long long)(scopeNode ? scopeNode.node.nodeId : 0),
        (long)(scopeNode ? scopeNode.index : NSNotFound), hasEnqueueResult,
        enqueueResult, (unsigned long)queueBefore,
        (unsigned long)(session.pendingInteractions.count));
}

@implementation CJGuiInternalComposableInputHost
- (BOOL)acceptsFirstResponder { return YES; }
- (BOOL)isAccessibilityElement { return NO; }
// The hidden NSTextInputClient is the actual first responder. App-level AX
// focus ascends through ignored views, so its accessible parent must be the
// current semantic input owner, rather than falling through to AXWindow.
// The overlay's focus predicate checks this exact host and accepted binding.
- (id)accessibilityParent {
    CJGuiInternalComposableSceneOverlay *overlay = self.composableOverlay;
    if (overlay && CjguiInputProxyIsFirstResponder(overlay)) {
        id focused = [overlay accessibilityFocusedUIElement];
        if (focused && focused != overlay) return focused;
    }
    return [super accessibilityParent];
}
- (NSTextInputContext *)inputContext {
    if (!_ownedInputContext) _ownedInputContext = [[NSTextInputContext alloc] initWithClient:self];
    return _ownedInputContext;
}
- (void)keyDown:(NSEvent *)event {
    // The host is the actual first responder; overlay-only traces miss keys
    // interpreted by the parked adapter's text input context.
    if (getenv("CJGUI_KEY_ENTRY_TRACE")) {
        static _Atomic(uint64_t) gHostKeySequence = 0;
        uint64_t sequence = atomic_fetch_add_explicit(&gHostKeySequence, 1, memory_order_relaxed) + 1;
        if (sequence <= 512) {
            CJGuiInternalComposableSceneOverlay *o = self.composableOverlay;
            fprintf(stderr, "CJGUI_KEY_HOST seq=%llu mono_ns=%llu event_time=%.9f keyCode=%u first_responder=%d parked=%d pending_caret=%d source_install=%d marked=%d node=%llu scene=%llu\n",
                (unsigned long long)sequence, (unsigned long long)cjgui_internal_renderer_owner_clock_ns(),
                event.timestamp, (unsigned)event.keyCode, (int)(self.window.firstResponder == self),
                (int)o.sourceInputParked, (int)(CjguiPendingOwnerCaretSource(o.session) != nil),
                (int)CjguiSourceInstallPending(o.session), (int)o.inputProxy.hasMarkedText,
                (unsigned long long)o.activeNodeId, (unsigned long long)o.session.composableSceneVersion);
        }
    }
    [self.composableOverlay.inputProxy keyDown:event];
}
- (void)insertText:(id)text replacementRange:(NSRange)range {
    [self.composableOverlay.inputProxy insertText:text replacementRange:range];
}
- (void)setMarkedText:(id)text selectedRange:(NSRange)selection replacementRange:(NSRange)range {
    [self.composableOverlay.inputProxy setMarkedText:text selectedRange:selection replacementRange:range];
}
- (void)unmarkText { [self.composableOverlay.inputProxy unmarkText]; }
- (BOOL)hasMarkedText { return self.composableOverlay.inputProxy.hasMarkedText; }
- (NSRange)markedRange { return self.composableOverlay.inputProxy.markedRange; }
- (NSRange)selectedRange { return self.composableOverlay.inputProxy.selectedRange; }
- (NSArray<NSAttributedStringKey> *)validAttributesForMarkedText {
    return self.composableOverlay.inputProxy.validAttributesForMarkedText;
}
- (NSAttributedString *)attributedSubstringForProposedRange:(NSRange)range actualRange:(NSRangePointer)actual {
    return [self.composableOverlay.inputProxy attributedSubstringForProposedRange:range actualRange:actual];
}
- (NSRect)firstRectForCharacterRange:(NSRange)range actualRange:(NSRangePointer)actual {
    return [self.composableOverlay.inputProxy firstRectForCharacterRange:range actualRange:actual];
}
- (NSUInteger)characterIndexForPoint:(NSPoint)point {
    return [self.composableOverlay.inputProxy characterIndexForPoint:point];
}
- (void)doCommandBySelector:(SEL)selector { [self.composableOverlay.inputProxy doCommandBySelector:selector]; }
- (void)selectAll:(id)sender {
    CJGuiInternalComposableSceneOverlay *overlay = self.composableOverlay;
    NSUInteger queueBefore = CjguiSelectAllTraceEnabled() ? overlay.session.pendingInteractions.count : 0;
    CjguiTraceSelectAllDecision("host", overlay, "forward_proxy", nil, NO, NO,
                                queueBefore);
    [overlay.inputProxy selectAll:sender];
}
- (void)copy:(id)sender { [self.composableOverlay.inputProxy copy:sender]; }
- (void)cut:(id)sender { [self.composableOverlay.inputProxy cut:sender]; }
- (void)paste:(id)sender { [self.composableOverlay.inputProxy paste:sender]; }
- (void)undo:(id)sender { [self.composableOverlay.inputProxy doCommandBySelector:@selector(undo:)]; }
- (void)redo:(id)sender { [self.composableOverlay.inputProxy doCommandBySelector:@selector(redo:)]; }
- (BOOL)validateUserInterfaceItem:(id<NSValidatedUserInterfaceItem>)item {
    return [self.composableOverlay.inputProxy validateUserInterfaceItem:item];
}
