CjguiInternalRendererStatus cjgui_internal_renderer_source_handoff_arm(
    uint64_t session, const CjguiInternalInstalledRangeCandidate *candidate,
    uint64_t expectedBindingEpoch, uint64_t expectedNodeId,
    int64_t expectedResourceId, uint32_t expectedNodeKind) {
    if (!candidate || !candidate->nonce || !candidate->windowInstanceToken || !candidate->bindingEpoch ||
        !candidate->nodeId || candidate->ownerVersion < 0 || candidate->sourceEndByte < candidate->sourceStartByte ||
        (!candidate->sourceTextUtf8 && candidate->sourceTextUtf8Length) ||
        candidate->sourceTextUtf8Length > CJGUI_INSTALLED_RANGE_BYTE_CAPACITY ||
        candidate->sourceEndByte - candidate->sourceStartByte != candidate->sourceTextUtf8Length ||
        expectedBindingEpoch == UINT64_MAX || candidate->bindingEpoch != expectedBindingEpoch + 1 ||
        !expectedNodeId || expectedNodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT)
        return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    NSData *sourceBytes = candidate->sourceTextUtf8Length
        ? [NSData dataWithBytes:candidate->sourceTextUtf8 length:candidate->sourceTextUtf8Length]
        : [NSData data];
    NSString *sourceText = [[NSString alloc] initWithData:sourceBytes encoding:NSUTF8StringEncoding];
    if (!sourceBytes || !sourceText) return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    CjguiInternalInstalledRangeCandidate frozen = *candidate;
    frozen.sourceTextUtf8 = NULL;
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
        if (!ctx.ownedTextSessionEnabled || !ctx.rangeTextEditDeltaDeliveryEnabled || !overlay ||
            ctx.sessionGeneration == 0 ||
            (frozen.rendererSessionGeneration && frozen.rendererSessionGeneration != ctx.sessionGeneration) ||
            ctx.ownedTextSessionBindingEpoch != expectedBindingEpoch ||
            ctx.ownedTextSessionNodeId != expectedNodeId ||
            ctx.ownedTextSessionResourceId != expectedResourceId ||
            ctx.ownedTextSessionNodeKind != expectedNodeKind ||
            ctx.ownedTextSourceNodeId != frozen.nodeId ||
            ctx.ownedTextSourceResourceId != frozen.resourceId ||
            ctx.ownedTextSourceNodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT ||
            frozen.installedSceneVersion != ctx.composableSceneVersion ||
            ctx.sourceHandoffCommitted || ctx.installedRangeReservation || ctx.claimedInstalledRangeIntent ||
            ctx.installedRangeLocalTailSequence != ctx.installedRangeObservedAckSequence ||
            overlay.inputProxy.hasMarkedText || overlay.compositionTerminalInFlight ||
            CjguiInstalledRangeHasUnconsumedLegacyRange(ctx, frozen))
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        for (CJGuiInternalQueuedInteraction *queued in ctx.pendingInteractions) {
            if (queued.nodeId == frozen.nodeId && queued.resourceId == frozen.resourceId &&
                (queued.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_CHANGED ||
                 queued.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_RANGE_CHANGED ||
                 queued.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_COMPOSITION))
                return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        }
        CjguiInstalledRangeState *old = ctx.sourceHandoffProvisional ?: ctx.sourceHandoffCandidate;
        uint64_t oldBytes = CjguiInstalledRangeStateBytes(old);
        uint64_t used = ctx.installedRangeBytesUsed >= oldBytes ? ctx.installedRangeBytesUsed - oldBytes : 0;
        if (used > CJGUI_INSTALLED_RANGE_BYTE_CAPACITY ||
            ctx.installedRangeBytesReserved > CJGUI_INSTALLED_RANGE_BYTE_CAPACITY - used ||
            sourceBytes.length > CJGUI_INSTALLED_RANGE_BYTE_CAPACITY - used - ctx.installedRangeBytesReserved)
            return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
        CjguiInstalledRangeState *state = [CjguiInstalledRangeState new];
        if (!state) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        CjguiInternalInstalledRangeCandidate actual = frozen;
        actual.rendererSessionGeneration = ctx.sessionGeneration;
        state.candidate = actual;
        state.sourceUtf8 = sourceBytes;
        state.handoffExpectedBindingEpoch = expectedBindingEpoch;
        state.handoffExpectedNodeId = expectedNodeId;
        state.handoffExpectedResourceId = expectedResourceId;
        state.handoffExpectedNodeKind = expectedNodeKind;
        state.handoffOldActiveNodeId = overlay.activeNodeId;
        state.handoffOldActiveResourceId = overlay.activeNodeResourceId;
        state.handoffOldActiveNodeKind = overlay.activeNodeKind;
        state.handoffOldSelection = overlay.inputProxy.selectedRange;
        ctx.sourceHandoffCandidate = state;
        ctx.sourceHandoffProvisional = nil;
        ctx.installedRangeBytesUsed = used + sourceBytes.length;
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_source_handoff_activate(
    uint64_t session, uint64_t nonce, uint64_t proxyGeneration, uint64_t selectionRevision) {
    if (!nonce || !proxyGeneration) return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
        CjguiInstalledRangeState *state = ctx.sourceHandoffProvisional;
        if (!overlay || !state || state.candidate.nonce != nonce || !state.hasReceipt || !state.proxy ||
            state.proxyGeneration != proxyGeneration || state.selectionRevision != selectionRevision ||
            state.proxy != overlay.inputProxy || overlay.installedRangeSelectionRevision != selectionRevision ||
            ctx.installedRangeProxyGeneration != proxyGeneration ||
            ctx.sessionGeneration != state.candidate.rendererSessionGeneration ||
            ctx.composableSceneVersion != state.candidate.installedSceneVersion ||
            ctx.ownedTextSessionBindingEpoch != state.handoffExpectedBindingEpoch ||
            ctx.ownedTextSessionNodeId != state.handoffExpectedNodeId ||
            ctx.ownedTextSessionResourceId != state.handoffExpectedResourceId ||
            ctx.ownedTextSessionNodeKind != state.handoffExpectedNodeKind ||
            ctx.ownedTextSourceNodeId != state.candidate.nodeId ||
            ctx.ownedTextSourceResourceId != state.candidate.resourceId ||
            overlay.activeNodeId != state.candidate.nodeId ||
            overlay.activeNodeResourceId != state.candidate.resourceId ||
            overlay.activeNodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT ||
            !CjguiInputProxyIsFirstResponder(overlay) || overlay.inputProxy.hasMarkedText ||
            overlay.compositionTerminalInFlight ||
            overlay.inputProxy.selectedRange.location != state.actualSelectionStart16 ||
            NSMaxRange(overlay.inputProxy.selectedRange) != state.actualSelectionEnd16 ||
            CjguiInstalledRangeHasUnconsumedLegacyRange(ctx, state.candidate))
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        NSData *actual = [overlay.inputProxy.string dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
        if (!actual || ![actual isEqualToData:state.sourceUtf8]) return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        for (CJGuiInternalQueuedInteraction *queued in ctx.pendingInteractions) {
            if (queued.nodeId == state.candidate.nodeId && queued.resourceId == state.candidate.resourceId &&
                (queued.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_CHANGED ||
                 queued.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_RANGE_CHANGED ||
                 queued.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_COMPOSITION))
                return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        }
        if (ctx.installedRangeLocalTailSequence != ctx.installedRangeObservedAckSequence ||
            ctx.installedRangeReservation || ctx.claimedInstalledRangeIntent)
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        ctx.sourceHandoffRollbackBasis = ctx.installedRangeBasis;
        ctx.installedRangeBasis = state;
        state.active = YES;
        state.chainClosed = NO;
        ctx.sourceHandoffCommitted = state;
        ctx.sourceHandoffProvisional = nil;
        ctx.sourceHandoffCandidate = nil;
        ctx.installedRangeNextSequence = 0;
        ctx.installedRangeLocalTailSequence = 0;
        ctx.installedRangeObservedAckSequence = 0;
        ctx.installedRangeObservedAckVersion = state.candidate.ownerVersion;
        ctx.ownedTextSessionNodeId = state.candidate.nodeId;
        ctx.ownedTextSessionResourceId = state.candidate.resourceId;
        ctx.ownedTextSessionNodeKind = CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT;
        ctx.ownedTextSessionBindingEpoch = state.candidate.bindingEpoch;
        ctx.sourceHandoffInputBlocked = YES;
        CjguiMarkInstalledRangeSourceParked(ctx, YES);
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_source_handoff_confirm_selection(
    uint64_t session, uint64_t nonce, uint32_t selectionStart16, uint32_t selectionEnd16) {
    if (!nonce || selectionEnd16 < selectionStart16)
        return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
        CjguiInstalledRangeState *state = ctx.sourceHandoffProvisional;
        if (!overlay || !state || state.candidate.nonce != nonce || !state.hasReceipt || !state.proxy ||
            state.proxy != overlay.inputProxy || ctx.sessionGeneration != state.candidate.rendererSessionGeneration ||
            ctx.installedRangeProxyGeneration != state.proxyGeneration ||
            ctx.composableSceneVersion != state.candidate.installedSceneVersion ||
            ctx.ownedTextSessionBindingEpoch != state.handoffExpectedBindingEpoch ||
            ctx.ownedTextSessionNodeId != state.handoffExpectedNodeId ||
            ctx.ownedTextSessionResourceId != state.handoffExpectedResourceId ||
            ctx.ownedTextSessionNodeKind != state.handoffExpectedNodeKind ||
            ctx.ownedTextSourceNodeId != state.candidate.nodeId ||
            ctx.ownedTextSourceResourceId != state.candidate.resourceId ||
            overlay.activeNodeId != state.candidate.nodeId ||
            overlay.activeNodeResourceId != state.candidate.resourceId ||
            overlay.activeNodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT ||
            !CjguiInputProxyIsFirstResponder(overlay) || overlay.inputProxy.hasMarkedText ||
            overlay.compositionTerminalInFlight || overlay.inputProxy.selectedRange.location != selectionStart16 ||
            NSMaxRange(overlay.inputProxy.selectedRange) != selectionEnd16 ||
            overlay.installedRangeSelectionRevision == UINT64_MAX ||
            CjguiInstalledRangeHasUnconsumedLegacyRange(ctx, state.candidate))
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        NSData *actual = [overlay.inputProxy.string dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
        if (!actual || ![actual isEqualToData:state.sourceUtf8]) return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        state.actualSelectionStart16 = selectionStart16;
        state.actualSelectionEnd16 = selectionEnd16;
        state.selectionRevision = overlay.installedRangeSelectionRevision;
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_source_handoff_finish(
    uint64_t session, uint64_t nonce) {
    if (!nonce) return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiInstalledRangeState *state = ctx.sourceHandoffCommitted;
        if (!state || state.candidate.nonce != nonce || ctx.installedRangeBasis != state ||
            ctx.ownedTextSessionNodeId != state.candidate.nodeId ||
            ctx.ownedTextSessionResourceId != state.candidate.resourceId ||
            ctx.ownedTextSessionBindingEpoch != state.candidate.bindingEpoch ||
            ctx.ownedTextSessionNodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT ||
            !CjguiInstalledRangeBasisMatchesActual(ctx, ctx.composableSceneOverlay))
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        uint64_t oldBytes = CjguiInstalledRangeStateBytes(ctx.sourceHandoffRollbackBasis);
        if (ctx.installedRangeBytesUsed >= oldBytes) ctx.installedRangeBytesUsed -= oldBytes;
        ctx.sourceHandoffRollbackBasis = nil;
        ctx.sourceHandoffCommitted = nil;
        ctx.sourceHandoffInputBlocked = NO;
        CjguiMarkInstalledRangeSourceParked(ctx, NO);
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_source_handoff_cancel(
    uint64_t session, uint64_t nonce) {
    if (!nonce) return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiInstalledRangeState *candidate = ctx.sourceHandoffCandidate;
        CjguiInstalledRangeState *provisional = ctx.sourceHandoffProvisional;
        CjguiInstalledRangeState *committed = ctx.sourceHandoffCommitted;
        if (committed && committed.candidate.nonce == nonce) {
            CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
            if (!overlay || ![overlay focusCommittedNodeId:committed.handoffOldActiveNodeId])
                return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
            uint64_t bytes = CjguiInstalledRangeStateBytes(committed);
            ctx.installedRangeBytesUsed = ctx.installedRangeBytesUsed >= bytes
                ? ctx.installedRangeBytesUsed - bytes : 0;
            ctx.installedRangeBasis = ctx.sourceHandoffRollbackBasis;
            ctx.sourceHandoffRollbackBasis = nil;
            ctx.ownedTextSessionBindingEpoch = committed.handoffExpectedBindingEpoch;
            ctx.ownedTextSessionNodeId = committed.handoffExpectedNodeId;
            ctx.ownedTextSessionResourceId = committed.handoffExpectedResourceId;
            ctx.ownedTextSessionNodeKind = committed.handoffExpectedNodeKind;
            ctx.sourceHandoffCommitted = nil;
            ctx.sourceHandoffInputBlocked = NO;
            CjguiMarkInstalledRangeSourceParked(ctx, NO);
            return CJGUI_INTERNAL_RENDERER_OK;
        }
        if ((candidate && candidate.candidate.nonce == nonce) ||
            (provisional && provisional.candidate.nonce == nonce)) {
            CjguiInstalledRangeState *state = provisional ?: candidate;
            CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
            if (overlay && overlay.activeNodeId == state.candidate.nodeId &&
                overlay.activeNodeResourceId == state.candidate.resourceId &&
                overlay.activeNodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT &&
                state.handoffOldActiveNodeId != 0 &&
                ![overlay focusCommittedNodeId:state.handoffOldActiveNodeId])
                return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
            uint64_t bytes = CjguiInstalledRangeStateBytes(state);
            ctx.installedRangeBytesUsed = ctx.installedRangeBytesUsed >= bytes
                ? ctx.installedRangeBytesUsed - bytes : 0;
            if (candidate.candidate.nonce == nonce) ctx.sourceHandoffCandidate = nil;
            if (provisional.candidate.nonce == nonce) ctx.sourceHandoffProvisional = nil;
            return CJGUI_INTERNAL_RENDERER_OK;
        }
        return CJGUI_INTERNAL_RENDERER_NODE_NOT_FOUND;
    });
}

static BOOL CjguiInstalledRangeActivationMatches(CJGuiInternalSession *ctx,
    CjguiInstalledRangeState *state, uint64_t proxyGeneration, uint64_t selectionRevision) {
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    if (!ctx || ctx.destroyed || !overlay || !state || !state.hasReceipt || !state.proxy ||
        state.proxyGeneration != proxyGeneration || state.selectionRevision != selectionRevision ||
        state.proxy != overlay.inputProxy || overlay.installedRangeSelectionRevision != selectionRevision ||
        ctx.installedRangeProxyGeneration != proxyGeneration ||
        ctx.sessionGeneration != state.candidate.rendererSessionGeneration ||
        ctx.composableSceneVersion != state.candidate.installedSceneVersion ||
        ctx.ownedTextSessionBindingEpoch != state.candidate.bindingEpoch ||
        ctx.ownedTextSessionNodeId != state.candidate.nodeId ||
        ctx.ownedTextSessionResourceId != state.candidate.resourceId ||
        overlay.activeNodeId != state.candidate.nodeId ||
        overlay.activeNodeResourceId != state.candidate.resourceId ||
        overlay.activeNodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT ||
        !CjguiInputProxyIsFirstResponder(overlay) || overlay.inputProxy.hasMarkedText ||
        overlay.compositionTerminalInFlight)
        return NO;
    NSData *actual = [overlay.inputProxy.string dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
    return actual && [actual isEqualToData:state.sourceUtf8] &&
        overlay.inputProxy.selectedRange.location == state.actualSelectionStart16 &&
        NSMaxRange(overlay.inputProxy.selectedRange) == state.actualSelectionEnd16;
}

static void CjguiMarkInstalledRangeSourceParked(CJGuiInternalSession *ctx, BOOL parked) {
    if (ctx.composableSceneOverlay) ctx.composableSceneOverlay.sourceInputParked = parked;
}

static BOOL CjguiInstalledRangeBasisMatchesActual(CJGuiInternalSession *ctx,
    CJGuiInternalComposableSceneOverlay *overlay) {
    CjguiInstalledRangeState *basis = ctx.installedRangeBasis;
    return ctx && !ctx.destroyed && overlay && basis && basis.active && !basis.chainClosed && basis.proxy &&
        basis.proxy == overlay.inputProxy && ctx.sessionGeneration == basis.candidate.rendererSessionGeneration &&
        ctx.installedRangeProxyGeneration == basis.proxyGeneration &&
        ctx.ownedTextSessionEnabled && ctx.ownedTextSessionNodeId == basis.candidate.nodeId &&
        ctx.ownedTextSessionResourceId == basis.candidate.resourceId &&
        ctx.ownedTextSessionBindingEpoch == basis.candidate.bindingEpoch &&
        (ctx.ownedTextSessionNodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT ||
         (basis.selectionTransferId && ctx.ownedTextSessionNodeKind == basis.proxyNodeKind)) &&
        overlay.activeNodeId == basis.candidate.nodeId && overlay.activeNodeResourceId == basis.candidate.resourceId &&
        (overlay.activeNodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT ||
         (basis.selectionTransferId && overlay.activeNodeKind == basis.proxyNodeKind)) &&
        CjguiInputProxyIsFirstResponder(overlay) && !overlay.inputProxy.hasMarkedText &&
        !overlay.compositionTerminalInFlight;
}

static const uint64_t kCjguiAfterCaretByteCapacity=262144;

static void CjguiTraceOwnerHandoffProducerIdentity(CJGuiInternalSession *ctx,
    CjguiOwnerSelectionHandoff *h,CjguiCaretInputSnapshot *actual) {
    CJGuiInternalComposableSceneOverlay *overlay=ctx.composableSceneOverlay;
    fprintf(stderr,"CJGUI_OWNER_HANDOFF_PRODUCER_IDENTITY id=%llu actual_binding=%llu owner_binding=%llu original_binding=%llu actual_nonce=%llu original_nonce=%llu actual_kind=%u active_kind=%u active_node=%llu first_responder=%u\n",
        (unsigned long long)h.identity,(unsigned long long)actual.candidate.bindingEpoch,
        (unsigned long long)h.bindingEpoch,(unsigned long long)h.initialA.candidate.bindingEpoch,
        (unsigned long long)actual.candidate.nonce,(unsigned long long)h.initialA.candidate.nonce,
        actual.nodeKind,overlay.activeNodeKind,(unsigned long long)overlay.activeNodeId,
        CjguiInputProxyIsFirstResponder(overlay)?1u:0u);
}

static CjguiCaretInputSnapshot *CjguiCaptureCaretInputSnapshot(CJGuiInternalSession *ctx) {
    CjguiInstalledRangeState *basis=ctx.installedRangeBasis;
    CJGuiInternalComposableSceneOverlay *overlay=ctx.composableSceneOverlay;
    if(!ctx || ctx.destroyed || !basis || !overlay.inputProxy ||
        basis.proxy!=overlay.inputProxy || !ctx.sessionGeneration ||
        basis.candidate.rendererSessionGeneration!=ctx.sessionGeneration ||
        overlay.activeNodeId!=basis.candidate.nodeId ||
        overlay.activeNodeResourceId!=basis.candidate.resourceId ||
        overlay.activeNodeKind!=(basis.proxyNodeKind ?: CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) ||
        !CjguiInputProxyIsFirstResponder(overlay)) return nil;
    NSString *actual=overlay.inputProxy.string ?: @"";
    if([actual lengthOfBytesUsingEncoding:NSUTF8StringEncoding]>kCjguiAfterCaretByteCapacity) return nil;
    NSData *body=[actual dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
    NSRange selection=overlay.inputProxy.selectedRange;
    if(!body || selection.location==NSNotFound || NSMaxRange(selection)>actual.length) return nil;
    CjguiCaretInputSnapshot *snapshot=[CjguiCaretInputSnapshot new];
    CjguiInternalInstalledRangeCandidate origin=basis.candidate;
    origin.sourceTextUtf8=NULL;
    snapshot.candidate=origin;snapshot.body=body;snapshot.proxy=overlay.inputProxy;
    snapshot.proxyGeneration=ctx.installedRangeProxyGeneration;
    snapshot.selectionRevision=overlay.installedRangeSelectionRevision;
    snapshot.selection=selection;
    snapshot.nodeKind=basis.proxyNodeKind ?: CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT;
    snapshot.acceptedSequence=ctx.installedRangeObservedAckSequence;
    snapshot.acceptedVersion=ctx.installedRangeObservedAckVersion;
    return snapshot;
}

// Residency is an actual installed A fact, independent of the current target
// declaration. It does not authorize an edit or turn A into the new owner B.
// A missing paint node can leave this real responder parked; a real focus,
// proxy, context, body or selection change cannot inherit its responsibility.
static BOOL CjguiFrozenCaretSourceMatchesActual(CJGuiInternalSession *ctx,
    CjguiCaretInputSnapshot *snapshot) {
    CjguiInstalledRangeState *basis=ctx.installedRangeBasis;
    CjguiCaretInputSnapshot *actual=CjguiCaptureCaretInputSnapshot(ctx);
    if(!snapshot || !actual || !basis.active || basis.chainClosed ||
        ctx.composableSceneOverlay.inputProxy.hasMarkedText ||
        ctx.composableSceneOverlay.compositionTerminalInFlight) return NO;
    CjguiInternalInstalledRangeCandidate a=actual.candidate,s=snapshot.candidate;
    return a.nonce==s.nonce && a.rendererSessionGeneration==s.rendererSessionGeneration &&
        a.windowInstanceToken==s.windowInstanceToken && a.contextEpoch==s.contextEpoch &&
        a.bindingEpoch==s.bindingEpoch && a.nodeId==s.nodeId && a.resourceId==s.resourceId &&
        a.sourceStartByte==s.sourceStartByte && a.sourceEndByte==s.sourceEndByte &&
        actual.proxy==snapshot.proxy && actual.proxyGeneration==snapshot.proxyGeneration &&
        actual.nodeKind==snapshot.nodeKind && actual.selectionRevision==snapshot.selectionRevision &&
        NSEqualRanges(actual.selection,snapshot.selection) && [actual.body isEqualToData:snapshot.body];
}

static CjguiCaretInputSnapshot *CjguiPendingOwnerCaretSource(CJGuiInternalSession *ctx) {
    CjguiOwnerSelectionHandoff *h=ctx.ownerSelectionHandoff;
    if(h.valid && !h.completed && h.branch.valid && ctx.caretInputBranch==h.branch)
        return h.branch.result;
    CJGuiInternalQueuedInteraction *edit=ctx.activeCaretNavigation;
    if(edit.caretEditApplied && edit.caretInputBranch.valid && ctx.caretInputBranch==edit.caretInputBranch) {
        CjguiCaretInputSnapshot *installed=edit.caretInstalledResult;
        CjguiInstalledRangeState *basis=ctx.installedRangeBasis;
        if(installed && installed.acceptedVersion==edit.caretEditAfterVersion &&
            installed.candidate.ownerVersion==edit.caretEditAfterVersion &&
            ctx.installedRangeObservedAckVersion==installed.acceptedVersion && basis.hasReceipt &&
            basis.selectionTransferId==installed.candidate.nonce &&
            CjguiFrozenCaretSourceMatchesActual(ctx,installed)) return installed;
        return edit.caretInputBranch.result;
    }
    return nil;
}

CjguiInternalRendererStatus cjgui_internal_renderer_parked_text_input_focus(uint64_t session,
    uint64_t window,uint64_t context,uint64_t node,int64_t resource,uint32_t kind) {
    return CjguiInstalledRangeRunOnMain(session,^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiCaretInputSnapshot *a=CjguiPendingOwnerCaretSource(ctx);
        return a && a.candidate.windowInstanceToken==window && a.candidate.contextEpoch==context &&
            a.candidate.nodeId==node && a.candidate.resourceId==resource && a.nodeKind==kind &&
            CjguiFrozenCaretSourceMatchesActual(ctx,a)
            ? CJGUI_INTERNAL_RENDERER_OK : CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    });
}

static void CjguiAdvanceCaretInputFromOwnerRangeAck(CJGuiInternalSession *ctx,
    CjguiInstalledRangeIntentState *state, CjguiInternalInstalledRangeIntent value) {
    CjguiCaretInputBranch *caret=state.caretInputBranch;
    if(caret.valid && caret.result.candidate.nonce==value.nonce &&
        caret.result.proxyGeneration==value.proxyGeneration &&
        caret.result.acceptedSequence==value.previousSeq &&
        [caret.result.body isEqualToData:state.preBody] &&
        ctx.composableSceneOverlay.installedRangeSelectionRevision==value.selectionRevision) {
        // Only this exact range's real owner result advances the prefix.
        CjguiCaretInputSnapshot *after=CjguiCaptureCaretInputSnapshot(ctx);
        if(after && [after.body isEqualToData:state.postBody]) caret.result=after;
    }
    CjguiOwnerSelectionHandoff *h=ctx.ownerSelectionHandoff;
    if(h.valid && !h.completed && !h.sealed && h.branch.valid &&
        ctx.caretInputBranch==h.branch && h.rangeNonce==value.nonce &&
        h.cutoffRange==value.seq && h.generation==value.rendererSessionGeneration &&
        h.windowToken==value.windowInstanceToken && h.contextEpoch==value.contextEpoch &&
        h.initialA.candidate.nonce==value.nonce &&
        [h.initialA.body isEqualToData:state.postBody]) {
        // This exact cutoff ACK advances the installed source extent. Keep
        // every producer's original snapshot immutable; only the branch's
        // result receives the real ACK receipt. A later scene/mirror cannot
        // reconstruct it, and a body/selection/focus change cannot borrow it.
        CjguiCaretInputSnapshot *a=h.initialA;
        CjguiCaretInputSnapshot *after=CjguiCaptureCaretInputSnapshot(ctx);
        if(!after)return;
        CjguiInternalInstalledRangeCandidate before=a.candidate,next=after.candidate;
        if(after.acceptedSequence==value.seq &&
            after.acceptedVersion==ctx.installedRangeObservedAckVersion &&
            next.nonce==before.nonce && next.rendererSessionGeneration==before.rendererSessionGeneration &&
            next.windowInstanceToken==before.windowInstanceToken && next.contextEpoch==before.contextEpoch &&
            next.bindingEpoch==before.bindingEpoch && next.nodeId==before.nodeId &&
            next.resourceId==before.resourceId && after.proxy==a.proxy &&
            after.proxyGeneration==a.proxyGeneration && after.nodeKind==a.nodeKind &&
            after.selectionRevision==a.selectionRevision && NSEqualRanges(after.selection,a.selection) &&
            [after.body isEqualToData:state.postBody]) {
            h.branch.result=after;
        }
    }
}

static BOOL CjguiCaretSnapshotMatchesActual(CJGuiInternalSession *ctx,
    CjguiCaretInputSnapshot *snapshot) {
    CJGuiInternalComposableSceneOverlay *overlay=ctx.composableSceneOverlay;
    CjguiInstalledRangeState *basis=ctx.installedRangeBasis;
    if(!snapshot || !CjguiInstalledRangeBasisMatchesActual(ctx,overlay) ||
        ctx.installedRangeReservation || ctx.claimedInstalledRangeIntent ||
        ctx.installedRangeLocalTailSequence!=ctx.installedRangeObservedAckSequence ||
        basis.candidate.nonce!=snapshot.candidate.nonce ||
        basis.candidate.windowInstanceToken!=snapshot.candidate.windowInstanceToken ||
        basis.candidate.contextEpoch!=snapshot.candidate.contextEpoch ||
        basis.candidate.bindingEpoch!=snapshot.candidate.bindingEpoch ||
        basis.candidate.sourceStartByte!=snapshot.candidate.sourceStartByte ||
        basis.candidate.sourceEndByte!=snapshot.candidate.sourceEndByte ||
        overlay.inputProxy!=snapshot.proxy ||
        ctx.installedRangeProxyGeneration!=snapshot.proxyGeneration ||
        overlay.installedRangeSelectionRevision!=snapshot.selectionRevision ||
        ctx.installedRangeObservedAckSequence!=snapshot.acceptedSequence ||
        ctx.installedRangeObservedAckVersion!=snapshot.acceptedVersion ||
        !NSEqualRanges(overlay.inputProxy.selectedRange,snapshot.selection)) return NO;
    NSData *actual=[overlay.inputProxy.string dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
    return actual && [actual isEqualToData:snapshot.body] && [actual isEqualToData:basis.sourceUtf8];
}

// A relative key's After(previous) result names an actual installed source.
// Resolve its current accepted node only by the same full body and native
// binding. Installation scene numbers remain immutable input evidence; they
// are not the current paint scene, and cannot be substituted for that scene.
static CJGuiInternalComposableSceneNode *CjguiCaretPrefixAcceptedNode(
    CJGuiInternalSession *ctx, CjguiCaretInputSnapshot *snapshot) {
    if (!ctx.view || !snapshot || !CjguiCaretSnapshotMatchesActual(ctx, snapshot)) return nil;
    CjguiInstalledRangeState *basis = ctx.installedRangeBasis;
    for (CJGuiInternalComposableSceneNode *node in ctx.composableNodes) {
        if (node.node.nodeId != basis.candidate.nodeId ||
            node.node.resourceId != basis.candidate.resourceId ||
            node.node.nodeKind != ctx.composableSceneOverlay.activeNodeKind ||
            node.node.projectionVersion != ctx.composableSceneVersion ||
            node.index >= ctx.view.composableNodes.count ||
            ctx.view.composableNodes[node.index] != node) continue;
        NSData *body = [(node.value ?: @"") dataUsingEncoding:NSUTF8StringEncoding
                                               allowLossyConversion:NO];
        if (body && [body isEqualToData:snapshot.body]) return node;
    }
    return nil;
}

static BOOL CjguiQueuedCaretSuccessorOfInflight(CJGuiInternalSession *ctx,
    CJGuiInternalQueuedInteraction *queued) {
    CjguiOwnerSelectionHandoff *h=ctx.ownerSelectionHandoff;
    if(h.valid && !h.completed && queued.ownerHandoff==h && queued.caretInputBranch==h.branch &&
        queued.inputSessionGeneration==h.generation && queued.inputSequence>h.branch.settledSequence &&
        queued.inputPreviousSequence>=h.branch.settledSequence &&
        queued.inputPreviousSequence+1==queued.inputSequence && queued.caretInputOrigin)
        return YES;
    CJGuiInternalQueuedInteraction *active=ctx.activeCaretNavigation;
    return active && active.caretInputBranch.valid &&
        (queued.kind==CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_NAVIGATE ||
         CjguiInteractionIsTextHistory(queued)) &&
        queued.caretInputBranch==active.caretInputBranch &&
        queued.inputSessionGeneration==ctx.sessionGeneration &&
        queued.inputSequence>active.inputSequence &&
        queued.inputPreviousSequence>=active.inputSequence &&
        queued.inputPreviousSequence+1==queued.inputSequence;
}

static void CjguiRejectCaretInputBranch(CJGuiInternalSession *ctx,
    CjguiCaretInputBranch *branch, const char *reason) {
    if(!ctx || !branch) return;
    BOOL unfinished=branch.settledSequence!=branch.lastProducedSequence ||
        ctx.activeCaretNavigation.caretInputBranch==branch;
    BOOL removedCaret=NO;
    branch.valid=NO;
    if(!ctx.rejectedAfterCaretInputs) ctx.rejectedAfterCaretInputs=[NSMutableArray array];
    NSMutableArray<CjguiAfterCaretTextInput *> *rejected=[NSMutableArray array];
    for(NSInteger index=(NSInteger)ctx.pendingInteractions.count-1;index>=0;index--) {
        CJGuiInternalQueuedInteraction *queued=ctx.pendingInteractions[(NSUInteger)index];
        if(queued.afterCaretTextInput.branch==branch) {
            // The complete payload and its original source remain owned. It
            // is never replayed into a newer selection, binding or document.
            queued.afterCaretTextInput.refusalReason=reason ? @(reason) : @"caret_prefix_refused";
            [rejected insertObject:queued.afterCaretTextInput atIndex:0];
            [ctx.pendingInteractions removeObjectAtIndex:(NSUInteger)index];
        } else if(queued.caretInputBranch==branch) {
            removedCaret=YES;
            [ctx.pendingInteractions removeObjectAtIndex:(NSUInteger)index];
        }
    }
    [ctx.rejectedAfterCaretInputs addObjectsFromArray:rejected];
    if(ctx.activeCaretNavigation.caretInputBranch==branch) ctx.activeCaretNavigation=nil;
    if(ctx.caretInputBranch==branch) ctx.caretInputBranch=nil;
    // A fully settled branch has no refused input. Its ordinary focus
    // retirement cannot emit a delayed failure that cancels a newer press.
    // Never clear an independently pending failure notice here.
    BOOL refused=unfinished || removedCaret || rejected.count!=0;
    if(refused) {
        ctx.pendingInputQueueFullNotice=YES;
        CjguiOwnerPumpTicketNoteWork(ctx);
    }
    fprintf(stderr,"CJGUI_CARET_PREFIX_%s reason=%s generation=%llu settled=%llu produced=%llu retained=%lu bytes=%llu wrote_owner=false\n",
        refused ? "REFUSED" : "RETIRED",reason,
        (unsigned long long)ctx.sessionGeneration,(unsigned long long)branch.settledSequence,
        (unsigned long long)branch.lastProducedSequence,(unsigned long)ctx.rejectedAfterCaretInputs.count,
        (unsigned long long)ctx.retainedAfterCaretInputBytes);
    if(branch.ownerHandoff.valid && !branch.ownerHandoff.completed)
        CjguiRetireOwnerHandoff(ctx,branch.ownerHandoff,reason);
}

static void CjguiRetireOwnerHandoff(CJGuiInternalSession *ctx, CjguiOwnerSelectionHandoff *h,
    const char *reason) {
    if(!h || !h.valid || h.completed)return;
    h.valid=NO;
    if(h.transferId)
        (void)cjgui_internal_renderer_selection_transfer_request_cancel(ctx.rendererSessionToken,h.transferId);
    if(h.branch.valid)CjguiRejectCaretInputBranch(ctx,h.branch,reason);
    ctx.retainedAfterCaretInputBytes-=h.chargedBytes;h.chargedBytes=0;h.initialA=nil;
    if(ctx.ownerSelectionHandoff==h)ctx.ownerSelectionHandoff=nil;
    fprintf(stderr,"CJGUI_OWNER_HANDOFF_ABORT id=%llu reason=%s wrote_owner=false\n",
        (unsigned long long)h.identity,reason ?: "owner_handoff_aborted");
}

CjguiInternalRendererStatus cjgui_internal_renderer_owner_handoff_begin(uint64_t session,
    const char *document,int64_t documentEpoch,uint64_t window,uint64_t context,
    uint64_t binding,int64_t beforeVersion,uint64_t rangeNonce,uint64_t rangeSequence,uint64_t *outId) {
    if(outId)*outId=0;
    if(!outId || !document || strlen(document)>4096 || documentEpoch<=0 || !window ||
        !context || !binding || beforeVersion<0)return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    NSString *doc=[[NSString alloc] initWithUTF8String:document];
    if(!doc.length)return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    return CjguiInstalledRangeRunOnMain(session,^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiOwnerSelectionHandoff *h=ctx.ownerSelectionHandoff;
        CjguiInstalledRangeIntentState *claim=ctx.claimedInstalledRangeIntent;
        if(rangeNonce && (!claim || claim.value.nonce!=rangeNonce || claim.value.seq!=rangeSequence))
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        // Original range events captured before the cutoff keep their own
        // coordinates/FIFO. They settle before this root can be sealed.
        if(h.valid && !h.sealed && rangeNonce && h.rangeNonce==rangeNonce &&
            rangeSequence<=h.cutoffRange && h.windowToken==window && h.contextEpoch==context &&
            h.bindingEpoch==binding && [h.document isEqualToString:doc] && h.documentEpoch==documentEpoch) {
            *outId=h.identity;return CJGUI_INTERNAL_RENDERER_OK;
        }
        if(h)CjguiRetireOwnerHandoff(ctx,h,"new_owner_transaction");
        if(!rangeNonce && ctx.caretInputBranch)
            CjguiRejectCaretInputBranch(ctx,ctx.caretInputBranch,"owner_transaction_superseded_prefix");
        CjguiCaretInputSnapshot *a=CjguiCaptureCaretInputSnapshot(ctx);
        if(!a)return CJGUI_INTERNAL_RENDERER_TEXT_SERVICE_UNSUPPORTED;
        if(!CjguiFrozenCaretSourceMatchesActual(ctx,a) ||
            a.candidate.windowInstanceToken!=window || a.candidate.contextEpoch!=context ||
            ctx.ownedTextSessionBindingEpoch!=binding || ctx.nextOwnerSelectionHandoff==UINT64_MAX)
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        uint64_t charge=a.body.length;
        if(charge>kCjguiAfterCaretByteCapacity ||
            ctx.retainedAfterCaretInputBytes>kCjguiAfterCaretByteCapacity-charge ||
            CjguiPendingInteractionOccupancy(ctx)>=kCjguiPendingInteractionCapacity)
            return CJGUI_INTERNAL_RENDERER_PRESENT_PENDING;
        h=[CjguiOwnerSelectionHandoff new];h.identity=++ctx.nextOwnerSelectionHandoff;
        h.document=doc;h.documentEpoch=documentEpoch;h.generation=ctx.sessionGeneration;
        h.windowToken=window;h.contextEpoch=context;h.bindingEpoch=binding;h.beforeVersion=beforeVersion;
        h.afterVersion=-1;h.choiceRevision=-1;h.rangeNonce=rangeNonce;
        h.cutoffCaret=ctx.lastVerticalInputSequence;
        h.cutoffRange=rangeNonce ? ctx.installedRangeLocalTailSequence : 0;
        h.initialA=a;h.valid=YES;h.chargedBytes=charge;
        CjguiCaretInputBranch *branch=rangeNonce ? ctx.caretInputBranch : nil;
        if(!branch || !branch.valid) {
            branch=[CjguiCaretInputBranch new];branch.origin=a;branch.result=a;branch.valid=YES;
            branch.settledSequence=h.cutoffCaret;branch.lastProducedSequence=h.cutoffCaret;
        }
        h.branch=branch;branch.ownerHandoff=h;ctx.caretInputBranch=branch;
        ctx.ownerSelectionHandoff=h;ctx.retainedAfterCaretInputBytes+=charge;
        // A relative successor may have arrived after the range producer but
        // before its Sink was called. Enrol its original record at this fixed
        // cutoff; never replace its producer snapshot with the current A/B.
        if(rangeNonce)for(CJGuiInternalQueuedInteraction *queued in ctx.pendingInteractions) {
            CjguiCaretInputSnapshot *origin=queued.caretInputOrigin;
            if(queued.caretInputBranch==branch && origin &&
                queued.inputSessionGeneration==h.generation && queued.inputSequence<=h.cutoffCaret &&
                queued.inputSequence>branch.settledSequence &&
                origin.candidate.contextEpoch==context && origin.candidate.windowInstanceToken==window) {
                queued.ownerHandoff=h;
            } else if(queued.afterCaretTextInput.branch==branch &&
                queued.afterCaretTextInput.previousSequence<=h.cutoffCaret &&
                queued.afterCaretTextInput.origin.candidate.contextEpoch==context &&
                queued.afterCaretTextInput.origin.candidate.windowInstanceToken==window) {
                queued.afterCaretTextInput.ownerHandoff=h;queued.ownerHandoff=h;
            }
        }
        *outId=h.identity;
        fprintf(stderr,"CJGUI_OWNER_HANDOFF_BEGIN id=%llu before=%lld actual_A=%lld cutoff_caret=%llu cutoff_range=%llu nonce=%llu\n",
            (unsigned long long)h.identity,(long long)beforeVersion,(long long)a.acceptedVersion,
            (unsigned long long)h.cutoffCaret,(unsigned long long)h.cutoffRange,(unsigned long long)rangeNonce);
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_owner_handoff_seal(uint64_t session,uint64_t id,
    int64_t afterVersion,int64_t revision,int64_t anchor,int64_t focus,int64_t editTicket) {
    return CjguiInstalledRangeRunOnMain(session,^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiOwnerSelectionHandoff *h=ctx.ownerSelectionHandoff;
        if(!h.valid || h.identity!=id || h.generation!=ctx.sessionGeneration ||
            afterVersion<=h.beforeVersion || revision<0 || anchor<0 || focus<0)
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        if(h.sealed)return h.afterVersion==afterVersion && h.choiceRevision==revision &&
            h.anchorByte==anchor && h.focusByte==focus && h.editTicket==editTicket
            ? CJGUI_INTERNAL_RENDERER_OK : CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        if(h.rangeNonce && ctx.installedRangeObservedAckSequence<h.cutoffRange)
            return CJGUI_INTERNAL_RENDERER_PRESENT_PENDING;
        if(h.rangeNonce && (ctx.installedRangeBasis.candidate.nonce!=h.rangeNonce ||
            ctx.installedRangeObservedAckVersion!=afterVersion))return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        h.afterVersion=afterVersion;h.choiceRevision=revision;h.anchorByte=anchor;h.focusByte=focus;
        h.editTicket=editTicket;h.sealed=YES;
        fprintf(stderr,"CJGUI_OWNER_HANDOFF_SEAL id=%llu after=%lld revision=%lld source=%lld:%lld receipt=%lld\n",
            (unsigned long long)id,(long long)afterVersion,(long long)revision,
            (long long)anchor,(long long)focus,(long long)editTicket);
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_owner_handoff_abort(uint64_t session,uint64_t id) {
    return CjguiInstalledRangeRunOnMain(session,^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiOwnerSelectionHandoff *h=ctx.ownerSelectionHandoff;
        if(!h || h.identity!=id)return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        CjguiRetireOwnerHandoff(ctx,h,"owner_authority_superseded");return CJGUI_INTERNAL_RENDERER_OK;
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_owner_handoff_state(uint64_t session,uint64_t id) {
    return CjguiInstalledRangeRunOnMain(session,^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiOwnerSelectionHandoff *h=ctx.ownerSelectionHandoff;
        return h.valid && !h.completed && h.identity==id && h.generation==ctx.sessionGeneration
            ? CJGUI_INTERNAL_RENDERER_OK : CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_owner_handoff_bind(uint64_t session,uint64_t id,uint64_t transfer) {
    return CjguiInstalledRangeRunOnMain(session,^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiOwnerSelectionHandoff *h=ctx.ownerSelectionHandoff;
        CjguiSelectionTransferCapsule *c=ctx.selectionTransferCapsule;
        if(!h.valid || !h.sealed || h.completed || h.identity!=id || !h.branch.valid ||
            ctx.caretInputBranch!=h.branch || h.generation!=ctx.sessionGeneration ||
            !c || c.transferId!=transfer || !c.bInputBasis ||
            c.bInputBasis.candidate.ownerVersion!=h.afterVersion ||
            c.bInputBasis.candidate.contextEpoch!=h.contextEpoch ||
            c.bInputBasis.candidate.windowInstanceToken!=h.windowToken ||
            c.proxy!=h.initialA.proxy || c.aProxyGeneration!=h.initialA.proxyGeneration ||
            ![[c.aBody.string dataUsingEncoding:NSUTF8StringEncoding] isEqualToData:h.initialA.body])
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        uint32_t state=0,refs=0;uint8_t cancelled=0;
        if(cjgui_internal_renderer_selection_transfer_state(session,transfer,&state,&cancelled,&refs)!=0 ||
            cancelled || state!=CJGUI_SELECTION_TRANSFER_PREPARING)
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        c.ownerHandoff=h;h.transferId=transfer;
        fprintf(stderr,"CJGUI_OWNER_HANDOFF_BIND id=%llu transfer=%llu actual_A=%lld target=%lld\n",
            (unsigned long long)id,(unsigned long long)transfer,(long long)c.aObservedAckVersion,
            (long long)h.afterVersion);
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_owner_handoff_complete(uint64_t session,uint64_t id,
    uint64_t transfer,int64_t version,int64_t revision,int64_t anchor,int64_t focus) {
    return CjguiInstalledRangeRunOnMain(session,^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiOwnerSelectionHandoff *h=ctx.ownerSelectionHandoff;
        CjguiInstalledRangeState *b=ctx.installedRangeBasis;
        if(!h.valid || !h.sealed || h.completed || h.identity!=id || h.transferId!=transfer ||
            h.afterVersion!=version || h.choiceRevision!=revision || h.anchorByte!=anchor || h.focusByte!=focus ||
            !h.branch.valid || ctx.caretInputBranch!=h.branch || !b.hasReceipt ||
            b.selectionTransferId!=transfer || b.candidate.nonce!=transfer ||
            b.candidate.contextEpoch!=h.contextEpoch || b.candidate.windowInstanceToken!=h.windowToken ||
            ctx.installedRangeObservedAckVersion!=version ||
            !CjguiInstalledRangeBasisMatchesActual(ctx,ctx.composableSceneOverlay))
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        CjguiCaretInputSnapshot *actual=CjguiCaptureCaretInputSnapshot(ctx);
        if(!actual || ![actual.body isEqualToData:b.sourceUtf8])return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        h.branch.result=actual;h.completed=YES;
        ctx.retainedAfterCaretInputBytes-=h.chargedBytes;h.chargedBytes=0;h.initialA=nil;
        ctx.ownerSelectionHandoff=nil;ctx.composableSceneOverlay.sourceInputParked=NO;
        fprintf(stderr,"CJGUI_OWNER_HANDOFF_COMPLETE id=%llu transfer=%llu owner=%lld original_origin=%lld cutoff=%llu\n",
            (unsigned long long)id,(unsigned long long)transfer,(long long)version,
            (long long)h.branch.origin.acceptedVersion,(unsigned long long)h.cutoffCaret);
        CjguiOwnerPumpTicketNoteWork(ctx);
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

static BOOL CjguiRetainAfterCaretText(CJGuiInternalComposableInputProxy *proxy,
    id argument, NSRange replacementRange, uint32_t kind) {
    CJGuiInternalComposableSceneOverlay *overlay=proxy.composableOverlay;
    CJGuiInternalSession *ctx=overlay.session;
    CjguiCaretInputBranch *branch=ctx.caretInputBranch;
    CjguiOwnerSelectionHandoff *h=ctx.ownerSelectionHandoff;
    BOOL rootPending=h.valid && !h.completed && branch==h.branch;
    if(!branch || !branch.valid || ctx.materializingAfterCaretInput) return NO;
    if(branch.lastProducedSequence==branch.settledSequence && !rootPending) {
        // Publication settles the root, not the original admitted suffix.
        // A new producer must remain behind any earlier held text; otherwise
        // its local range tail prevents that FIFO head from ever reaching ACK.
        BOOL heldText=NO;
        for(CJGuiInternalQueuedInteraction *queued in ctx.pendingInteractions) {
            if(queued.afterCaretTextInput.branch==branch) { heldText=YES;break; }
        }
        if(!heldText)return NO;
    }
    NSString *payload=CjguiInputArgumentText(argument) ?: @"";
    uint64_t payloadBytes=[payload lengthOfBytesUsingEncoding:NSUTF8StringEncoding];
    uint64_t bodyBytes=[proxy.string lengthOfBytesUsingEncoding:NSUTF8StringEncoding];
    // Reserve the one bounded handoff copy before admission. Native releases
    // its source/payload only after the consumer confirms owning that copy.
    uint64_t charged=(payloadBytes<=kCjguiAfterCaretByteCapacity && bodyBytes<=kCjguiAfterCaretByteCapacity)
        ? 2*payloadBytes+bodyBytes : UINT64_MAX;
    if(payloadBytes>kCjguiAfterCaretByteCapacity || bodyBytes>kCjguiAfterCaretByteCapacity ||
        charged>kCjguiAfterCaretByteCapacity ||
        ctx.retainedAfterCaretInputBytes>kCjguiAfterCaretByteCapacity-charged ||
        ctx.nextCaretRecoveryId>=((1ull<<48)-1) ||
        CjguiPendingInteractionOccupancy(ctx)>=
            kCjguiPendingInteractionCapacity) {
        ctx.pendingInputQueueFullNotice=YES;
        CjguiOwnerPumpTicketNoteWork(ctx);
        fprintf(stderr,"CJGUI_CARET_INPUT_NOT_ADMITTED reason=capacity generation=%llu wrote_proxy=false\n",
            (unsigned long long)ctx.sessionGeneration);
        return YES;
    }
    CjguiAfterCaretTextInput *input=[CjguiAfterCaretTextInput new];
    input.branch=branch;input.origin=CjguiCaptureCaretInputSnapshot(ctx);
    if(!input.origin) {
        ctx.pendingInputQueueFullNotice=YES;
        CjguiOwnerPumpTicketNoteWork(ctx);
        fprintf(stderr,"CJGUI_CARET_INPUT_NOT_ADMITTED reason=origin_unavailable wrote_proxy=false\n");
        return YES;
    }
    input.payload=payload;input.replacementRange=replacementRange;input.kind=kind;
    input.ownerHandoff=rootPending ? h : nil;
    input.previousSequence=branch.lastProducedSequence;input.chargedBytes=charged;
    input.recoveryId=++ctx.nextCaretRecoveryId;
    CjguiInternalInstalledRangeCandidate origin=input.origin.candidate;
    CJGuiInternalQueuedInteraction *queued=[[CJGuiInternalQueuedInteraction alloc]
        initWithKind:CJGUI_INTERNAL_RENDERER_EVENT_NONE recordIndex:0 selectionStart:0 selectionEnd:0
        formText:@"" nodeId:origin.nodeId projectionVersion:origin.installedSceneVersion
        resourceId:origin.resourceId nodeKind:overlay.activeNodeKind];
    queued.afterCaretTextInput=input;
    queued.ownerHandoff=input.ownerHandoff;
    ctx.retainedAfterCaretInputBytes+=charged;
    [ctx.pendingInteractions addObject:queued];
    CjguiOwnerPumpTicketNoteWork(ctx);
    if(rootPending)fprintf(stderr,"CJGUI_OWNER_HANDOFF_INPUT id=%llu kind=text previous=%llu original_A=%lld bytes=%llu\n",
        (unsigned long long)h.identity,(unsigned long long)input.previousSequence,
        (long long)input.origin.acceptedVersion,(unsigned long long)payloadBytes);
    fprintf(stderr,"CJGUI_CARET_INPUT_RETAINED generation=%llu after=%llu origin_nonce=%llu owner=%lld context=%llu binding=%llu proxy=%llu selection_revision=%llu source=%llu:%llu bytes=%llu implicit=%d\n",
        (unsigned long long)ctx.sessionGeneration,(unsigned long long)input.previousSequence,
        (unsigned long long)origin.nonce,(long long)input.origin.acceptedVersion,
        (unsigned long long)origin.contextEpoch,(unsigned long long)origin.bindingEpoch,
        (unsigned long long)input.origin.proxyGeneration,(unsigned long long)input.origin.selectionRevision,
        (unsigned long long)origin.sourceStartByte,(unsigned long long)origin.sourceEndByte,
        (unsigned long long)payloadBytes,replacementRange.location==NSNotFound);
    return YES;
}

// Package-private copy/confirm handoff. Metadata and payload always name the
// actual input origin; neither a new mirror nor a current caret interprets it.
// The fixed 21-word metadata is scalar-only, separate from Node/Event PODs.
CjguiInternalRendererStatus cjgui_internal_renderer_peek_caret_recovery(uint64_t session,
    uint64_t *metadata,uint32_t count) {
    if(!metadata || count!=21)return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    memset(metadata,0,21*sizeof(uint64_t));
    return CjguiInstalledRangeRunOnMain(session,^CjguiInternalRendererStatus(CJGuiInternalSession *ctx){
        CjguiAfterCaretTextInput *input=ctx.rejectedAfterCaretInputs.firstObject;
        if(!input)return CJGUI_INTERNAL_RENDERER_OK;
        CjguiCaretInputSnapshot *origin=input.origin;
        if(!origin || !input.recoveryId)return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        CjguiInternalInstalledRangeCandidate c=origin.candidate;
        metadata[0]=input.recoveryId;metadata[1]=ctx.sessionGeneration;
        metadata[2]=c.windowInstanceToken;metadata[3]=c.bindingEpoch;metadata[4]=c.contextEpoch;
        metadata[5]=(uint64_t)origin.acceptedVersion;metadata[6]=c.sourceStartByte;metadata[7]=c.sourceEndByte;
        metadata[8]=origin.proxyGeneration;metadata[9]=origin.selectionRevision;
        metadata[10]=input.previousSequence;metadata[11]=input.kind;
        metadata[12]=[input.payload lengthOfBytesUsingEncoding:NSUTF8StringEncoding];
        metadata[13]=c.nodeId;metadata[14]=(uint64_t)c.resourceId;metadata[15]=c.nonce;
        metadata[16]=origin.selection.location;metadata[17]=origin.selection.length;
        metadata[18]=[input.refusalReason lengthOfBytesUsingEncoding:NSUTF8StringEncoding];
        metadata[19]=origin.acceptedSequence;metadata[20]=origin.nodeKind;
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}
CjguiInternalRendererStatus cjgui_internal_renderer_copy_caret_recovery(uint64_t session,
    uint64_t generation,uint64_t recoveryId,uint8_t *payload,uint32_t payloadLength,
    uint8_t *reason,uint32_t reasonLength) {
    return CjguiInstalledRangeRunOnMain(session,^CjguiInternalRendererStatus(CJGuiInternalSession *ctx){
        CjguiAfterCaretTextInput *input=ctx.rejectedAfterCaretInputs.firstObject;
        if(ctx.sessionGeneration!=generation || !input || input.recoveryId!=recoveryId)
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        NSData *p=[input.payload dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
        NSData *r=[input.refusalReason dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
        if(p.length!=payloadLength || r.length!=reasonLength ||
           (payloadLength && !payload) || (reasonLength && !reason))return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
        if(payloadLength)memcpy(payload,p.bytes,payloadLength);
        if(reasonLength)memcpy(reason,r.bytes,reasonLength);
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}
CjguiInternalRendererStatus cjgui_internal_renderer_finish_caret_recovery(uint64_t session,
    uint64_t generation,uint64_t recoveryId,uint32_t disposition) {
    return CjguiInstalledRangeRunOnMain(session,^CjguiInternalRendererStatus(CJGuiInternalSession *ctx){
        if(ctx.sessionGeneration!=generation || !recoveryId)return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        NSNumber *key=@(recoveryId);
        if(disposition==1) {
            // Idempotent confirmation refers to this same retained copy.
            if(ctx.exportedCaretRecoveryBytes[key])return CJGUI_INTERNAL_RENDERER_OK;
            CjguiAfterCaretTextInput *input=ctx.rejectedAfterCaretInputs.firstObject;
            if(!input || input.recoveryId!=recoveryId)return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
            uint64_t bytes=[input.payload lengthOfBytesUsingEncoding:NSUTF8StringEncoding];
            if(!ctx.exportedCaretRecoveryBytes)ctx.exportedCaretRecoveryBytes=[NSMutableDictionary dictionary];
            ctx.exportedCaretRecoveryBytes[key]=@(bytes);
            ctx.retainedAfterCaretInputBytes-=input.chargedBytes-bytes;
            [ctx.rejectedAfterCaretInputs removeObjectAtIndex:0];
            return CJGUI_INTERNAL_RENDERER_OK;
        }
        if(disposition==0 || disposition==2) {
            NSNumber *bytes=ctx.exportedCaretRecoveryBytes[key];
            if(!bytes)return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
            if(disposition==0)return CJGUI_INTERNAL_RENDERER_OK;
            ctx.retainedAfterCaretInputBytes-=bytes.unsignedLongLongValue;
            [ctx.exportedCaretRecoveryBytes removeObjectForKey:key];
            return CJGUI_INTERNAL_RENDERER_OK;
        }
        return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    });
}
CjguiInternalRendererStatus cjgui_internal_renderer_cancel_caret_prefix(uint64_t session,
    uint64_t windowToken,uint64_t bindingEpoch) {
    return CjguiInstalledRangeRunOnMain(session,^CjguiInternalRendererStatus(CJGuiInternalSession *ctx){
        CjguiCaretInputBranch *branch=ctx.caretInputBranch ?: ctx.activeCaretNavigation.caretInputBranch;
        if(!branch)return CJGUI_INTERNAL_RENDERER_OK;
        if(branch.origin.candidate.windowInstanceToken!=windowToken ||
           ctx.ownedTextSessionBindingEpoch!=bindingEpoch)return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        CjguiRejectCaretInputBranch(ctx,branch,"input_binding_or_window_retiring");
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

// Owner terminal follows its real selection transaction. Merely dequeuing a
// physical key, advancing a scene, or reading the current mirror is insufficient.
CjguiInternalRendererStatus cjgui_internal_renderer_mark_caret_edit_applied(
    uint64_t session, uint64_t generation, uint64_t sequence, uint64_t previous,
    int64_t beforeVersion, int64_t afterVersion, uint64_t contextEpoch, uint64_t windowToken) {
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CJGuiInternalQueuedInteraction *active = ctx.activeCaretNavigation;
        CjguiCaretInputBranch *branch = active.caretInputBranch;
        if (ctx.sessionGeneration != generation || !active || !branch.valid ||
            active.inputSequence != sequence || active.inputPreviousSequence != previous ||
            branch.settledSequence != previous || branch.result.acceptedVersion != beforeVersion ||
            beforeVersion == INT64_MAX || afterVersion != beforeVersion + 1 ||
            branch.result.candidate.contextEpoch != contextEpoch ||
            branch.result.candidate.windowInstanceToken != windowToken ||
            (!(active.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_NAVIGATE &&
               ([active.formText isEqualToString:@"deleteBackward"] ||
                [active.formText isEqualToString:@"deleteForward"])) &&
             !CjguiInteractionIsTextHistory(active)))
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        if (active.caretEditApplied && (active.caretEditBeforeVersion != beforeVersion ||
            active.caretEditAfterVersion != afterVersion)) return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        active.caretEditApplied = YES;
        active.caretEditBeforeVersion = beforeVersion;
        active.caretEditAfterVersion = afterVersion;
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_finish_caret_input(uint64_t session,
    uint64_t generation,uint64_t sequence,uint64_t previous,uint32_t outcome,
    uint64_t nonce,uint64_t proxyGeneration,uint64_t selectionRevision,
    int64_t ownerVersion,uint64_t contextEpoch,uint64_t windowToken) {
    if(!generation || !sequence || previous==UINT64_MAX || previous+1!=sequence ||
        outcome<1 || outcome>3) return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    return CjguiInstalledRangeRunOnMain(session,^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CJGuiInternalQueuedInteraction *active=ctx.activeCaretNavigation;
        CjguiCaretInputBranch *branch=active.caretInputBranch;
        if(ctx.sessionGeneration!=generation || !active || !branch.valid ||
            active.inputSequence!=sequence || active.inputPreviousSequence!=previous ||
            branch.settledSequence!=previous) return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        if(outcome==3) {
            CjguiRejectCaretInputBranch(ctx,branch,"owner_navigation_aborted");
            return CJGUI_INTERNAL_RENDERER_OK;
        }
        CjguiInstalledRangeState *basis=ctx.installedRangeBasis;
        CJGuiInternalComposableSceneOverlay *overlay=ctx.composableSceneOverlay;
        if(!CjguiInstalledRangeBasisMatchesActual(ctx,overlay) ||
            ctx.installedRangeReservation || ctx.claimedInstalledRangeIntent ||
            ctx.installedRangeLocalTailSequence!=ctx.installedRangeObservedAckSequence ||
            basis.candidate.nonce!=nonce || ctx.installedRangeProxyGeneration!=proxyGeneration ||
            overlay.installedRangeSelectionRevision!=selectionRevision ||
            basis.candidate.contextEpoch!=contextEpoch || basis.candidate.windowInstanceToken!=windowToken ||
            branch.origin.candidate.contextEpoch!=contextEpoch ||
            branch.origin.candidate.windowInstanceToken!=windowToken ||
            ctx.installedRangeObservedAckVersion!=ownerVersion ||
            (active.caretEditApplied
                ? (outcome != 1 || active.caretEditBeforeVersion != branch.result.acceptedVersion ||
                   active.caretEditAfterVersion != ownerVersion)
                : branch.result.acceptedVersion != ownerVersion) ||
            (outcome==1 && (!basis.selectionTransferId || !basis.hasReceipt ||
                basis.candidate.nonce!=basis.selectionTransferId ||
                basis.selectionRevision!=selectionRevision ||
                !NSEqualRanges(overlay.inputProxy.selectedRange,
                    NSMakeRange(basis.actualSelectionStart16,
                        basis.actualSelectionEnd16-basis.actualSelectionStart16)))) ||
            (outcome==2 && !CjguiCaretSnapshotMatchesActual(ctx,branch.result)))
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        CjguiCaretInputSnapshot *actual=CjguiCaptureCaretInputSnapshot(ctx);
        if(!actual || ![actual.body isEqualToData:basis.sourceUtf8])
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        branch.result=actual;branch.settledSequence=sequence;
        ctx.activeCaretNavigation=nil;
        fprintf(stderr,"CJGUI_CARET_PREFIX_COMMITTED generation=%llu sequence=%llu previous=%llu outcome=%u nonce=%llu owner=%lld binding=%llu proxy=%llu selection_revision=%llu source=%llu:%llu\n",
            (unsigned long long)generation,(unsigned long long)sequence,(unsigned long long)previous,outcome,
            (unsigned long long)nonce,(long long)ownerVersion,(unsigned long long)basis.candidate.bindingEpoch,
            (unsigned long long)proxyGeneration,(unsigned long long)selectionRevision,
            (unsigned long long)basis.candidate.sourceStartByte,(unsigned long long)basis.candidate.sourceEndByte);
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

static BOOL CjguiMaterializeAfterCaretInputAtHead(CJGuiInternalSession *ctx) {
    CJGuiInternalQueuedInteraction *head=ctx.pendingInteractions.firstObject;
    CjguiAfterCaretTextInput *input=head.afterCaretTextInput;
    if(!input) return YES;
    CjguiCaretInputBranch *branch=input.branch;
    if((input.ownerHandoff.valid && !input.ownerHandoff.completed) ||
        (branch.ownerHandoff.valid && !branch.ownerHandoff.completed))return NO;
    if(input.ownerHandoff && !input.ownerHandoff.valid) {
        CjguiRejectCaretInputBranch(ctx,branch,"owner_handoff_input_retired");return NO;
    }
    if(ctx.activeCaretNavigation || branch.settledSequence<input.previousSequence) return NO;
    if(!branch.valid || branch.settledSequence!=input.previousSequence ||
        !input.origin || input.kind!=2 || input.replacementRange.location!=NSNotFound) {
        CjguiRejectCaretInputBranch(ctx,branch,"implicit_prefix_origin_unavailable");return NO;
    }
    // A previous typed edit still owes its genuine owner ACK. Its range event
    // is ahead of this placeholder, never replayed or explained by a mirror.
    if(ctx.installedRangeLocalTailSequence!=ctx.installedRangeObservedAckSequence) return NO;
    if(!CjguiCaretSnapshotMatchesActual(ctx,branch.result)) {
        CjguiRejectCaretInputBranch(ctx,branch,"accepted_prefix_selection_or_binding_changed");return NO;
    }
    [ctx.pendingInteractions removeObjectAtIndex:0];
    NSUInteger laterCount=ctx.pendingInteractions.count;
    ctx.materializingAfterCaretInput=YES;ctx.materializingAfterCaretBranch=branch;
    @try {
        [ctx.composableSceneOverlay.inputProxy insertText:input.payload
            replacementRange:NSMakeRange(NSNotFound,0)];
    } @finally {
        ctx.materializingAfterCaretInput=NO;ctx.materializingAfterCaretBranch=nil;
    }
    if(ctx.pendingInteractions.count==laterCount) {
        // No TextKit mutation escaped a refused delegate. Retain this exact
        // payload with the other recovery inputs, then retire the prefix.
        [ctx.pendingInteractions insertObject:head atIndex:0];
        CjguiRejectCaretInputBranch(ctx,branch,"range_producer_refused_after_predecessor");return NO;
    }
    NSArray *produced=[ctx.pendingInteractions subarrayWithRange:
        NSMakeRange(laterCount,ctx.pendingInteractions.count-laterCount)];
    [ctx.pendingInteractions removeObjectsInRange:NSMakeRange(laterCount,produced.count)];
    [ctx.pendingInteractions insertObjects:produced atIndexes:
        [NSIndexSet indexSetWithIndexesInRange:NSMakeRange(0,produced.count)]];
    ctx.retainedAfterCaretInputBytes-=input.chargedBytes;
    fprintf(stderr,"CJGUI_CARET_INPUT_MATERIALIZED generation=%llu after=%llu native_range_tail=%llu events=%lu once=true\n",
        (unsigned long long)ctx.sessionGeneration,(unsigned long long)input.previousSequence,
        (unsigned long long)ctx.installedRangeLocalTailSequence,(unsigned long)produced.count);
    return YES;
}

// Owner declarations are immutable accepted-scene data. A target proxy can
// override only its own exact installation scene. Other fragments keep their
// accepted declarations; the session publication fence prevents this mixed
// intermediate projection from reaching a frame. A newer full scene supplies
// current declarations for all fragments together, without double proxy paint.
static NSArray<NSDictionary *> *CjguiEffectiveDeclaredSelectionDecorations(
    CJGuiInternalSession *ctx, CJGuiInternalComposableSceneNode *node) {
    NSArray<NSDictionary *> *declared = node.textDeclaredSelectionDecorations ?: @[];
    if (declared.count == 0) return declared;
    if (!ctx || !node || ctx.destroyed || !ctx.view || !ctx.composableSceneOverlay ||
        !ctx.installedRangeBasis ||
        ctx.composableSceneVersion < ctx.installedRangeBasis.candidate.installedSceneVersion)
        return declared;

    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    CjguiInstalledRangeState *basis = ctx.installedRangeBasis;
    if (!basis.active || basis.chainClosed || !basis.hasReceipt || !basis.selectionTransferId ||
        basis.candidate.nonce != basis.selectionTransferId ||
        basis.candidate.rendererSessionGeneration != ctx.sessionGeneration ||
        basis.candidate.bindingEpoch != ctx.ownedTextSessionBindingEpoch ||
        basis.candidate.nodeId != ctx.ownedTextSessionNodeId ||
        basis.candidate.resourceId != ctx.ownedTextSessionResourceId ||
        ctx.installedRangeObservedAckVersion != basis.candidate.ownerVersion ||
        ctx.installedRangeProxyGeneration != basis.proxyGeneration ||
        !overlay.inputProxy || basis.proxy != overlay.inputProxy ||
        overlay.installedRangeSelectionRevision != basis.selectionRevision ||
        !CjguiInstalledRangeBasisMatchesActual(ctx, overlay))
        return declared;

    NSRange actual = overlay.inputProxy.selectedRange;
    if (actual.location != basis.actualSelectionStart16 || NSMaxRange(actual) != basis.actualSelectionEnd16)
        return declared;
    NSData *actualBody = [overlay.inputProxy.string dataUsingEncoding:NSUTF8StringEncoding
                                                   allowLossyConversion:NO];
    if (!actualBody || ![actualBody isEqualToData:basis.sourceUtf8]) return declared;

    NSArray<CJGuiInternalComposableSceneNode *> *nodes = ctx.view.composableNodes;
    if (node.index >= nodes.count || nodes[node.index] != node)
        return declared;

    BOOL targetNode = node.node.nodeId == basis.candidate.nodeId &&
        node.node.resourceId == basis.candidate.resourceId;
    if (targetNode) {
        if (overlay.activeProjectionVersion != node.node.projectionVersion) return declared;
        NSData *nodeBody = [(node.value ?: @"") dataUsingEncoding:NSUTF8StringEncoding
                                                  allowLossyConversion:NO];
        if (!nodeBody || ![nodeBody isEqualToData:basis.sourceUtf8]) return declared;
        // Proxy-derived range geometry belongs only to the exact scene whose
        // transfer installed it. A newer accepted scene carries fresh owner
        // declarations, including any cross-fragment selection, and wins as a
        // whole rather than being replaced by this local proxy projection.
        if (ctx.composableSceneVersion == basis.candidate.installedSceneVersion) return @[];
        return declared;
    }

    // Coverage handoff for every OTHER visible fragment. The transfer proves nothing about these
    // nodes: its proxy range lies inside the target fragment, and their owner declarations were
    // accepted by the very scene that is still current. Retiring them together was an over-reach --
    // it blanked every non-target fragment for the whole window between installing the transfer and
    // accepting the next scene, so a cross-fragment drag lost its highlight on all but the dragged
    // fragment and got it back only when the next scene landed (the user's "cross-fragment highlight
    // repeatedly disappears"). This keeps the owner's LAST ACCEPTED statement, which is what the
    // accepted scene is authoritative for; nothing is remembered from a superseded scene, because a
    // newer accepted scene takes the branch above and each node answers from its own declaration.
    return declared;
}

// Project a candidate proxy range through the exact already-prepared layout
// that will be accepted with the node. This helper is pure with respect to the
// scene: it never lays out text or mutates declared owner decorations.
static BOOL CjguiSelectionGeometryReject(const char *reason) {
    const char *trace = getenv("CJGUI_TEXT_PREPARE_TRACE");
    if (trace && strcmp(trace, "1") == 0)
        fprintf(stderr, "CJGUI_SELECTION_GEOMETRY reject=%s\n", reason ?: "unknown");
    return NO;
}

static uint64_t CjguiSelectionGeometryTextHash(NSString *text) {
    NSData *bytes = [(text ?: @"") dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
    if (!bytes) return 0;
    uint64_t hash = UINT64_C(1469598103934665603);
    const uint8_t *cursor = bytes.bytes;
    for (NSUInteger index = 0; index < bytes.length; index++) {
        hash ^= cursor[index];
        hash *= UINT64_C(1099511628211);
    }
    return hash;
}

static void CjguiLogSelectionGeometryBodyMismatch(CJGuiInternalComposableSceneNode *node,
    CjguiPreparedTextNodeLayout *prepared, NSTextView *proxy) {
    const char *trace = getenv("CJGUI_TEXT_PREPARE_TRACE");
    if (!trace || strcmp(trace, "1") != 0 || !node || !proxy) return;
    NSString *nodeBody = node.value ?: @"";
    NSString *layoutBody = prepared.storage.string ?: @"";
    NSString *proxyBody = proxy.string ?: @"";
    NSRect nodeRect = CjguiComposableVisualNodeRect(node);
    NSRect localTextRect = NSZeroRect;
    (void)CjguiComposableEmptyTextLayoutRect(node, &localTextRect);
    NSRect textRect = NSOffsetRect(localTextRect, NSMinX(nodeRect), NSMinY(nodeRect));
    NSRect layoutRect = prepared ? prepared.textRect : NSZeroRect;
    NSRect clipRect = CjguiComposableVisualClipBounds(node);
    NSRect textureRect = CjguiComposableTextTextureRectForNode(node);
    fprintf(stderr, "CJGUI_SELECTION_GEOMETRY_MISMATCH node=%llu kind=%u "
        "value16=%lu valueHash=%016llx layout16=%lu layoutHash=%016llx "
        "proxy16=%lu proxyHash=%016llx firstUnlaid=%lu "
        "storage=%p proxyStorage=%p sameStorage=%u layoutManager=%p proxyLayoutManager=%p sameLayoutManager=%u "
        "container=%p proxyContainer=%p sameContainer=%u "
        "nodeRect=%.3f,%.3f,%.3f,%.3f textRect=%.3f,%.3f,%.3f,%.3f "
        "layoutRect=%.3f,%.3f,%.3f,%.3f clip=%.3f,%.3f,%.3f,%.3f "
        "texture=%.3f,%.3f,%.3f,%.3f\n",
        (unsigned long long)node.node.nodeId, node.node.nodeKind,
        (unsigned long)nodeBody.length, (unsigned long long)CjguiSelectionGeometryTextHash(nodeBody),
        (unsigned long)layoutBody.length, (unsigned long long)CjguiSelectionGeometryTextHash(layoutBody),
        (unsigned long)proxyBody.length, (unsigned long long)CjguiSelectionGeometryTextHash(proxyBody),
        (unsigned long)(prepared ? prepared.layoutManager.firstUnlaidCharacterIndex : 0),
        prepared.storage, proxy.textStorage, prepared.storage == proxy.textStorage,
        prepared.layoutManager, proxy.layoutManager, prepared.layoutManager == proxy.layoutManager,
        prepared.container, proxy.textContainer, prepared.container == proxy.textContainer,
        NSMinX(nodeRect), NSMinY(nodeRect), NSWidth(nodeRect), NSHeight(nodeRect),
        NSMinX(textRect), NSMinY(textRect), NSWidth(textRect), NSHeight(textRect),
        NSMinX(layoutRect), NSMinY(layoutRect), NSWidth(layoutRect), NSHeight(layoutRect),
        NSMinX(clipRect), NSMinY(clipRect), NSWidth(clipRect), NSHeight(clipRect),
        NSMinX(textureRect), NSMinY(textureRect), NSWidth(textureRect), NSHeight(textureRect));
}

static BOOL CjguiBuildAcceptedTextSelectionGeometry(CJGuiInternalComposableSceneNode *node,
    CjguiPreparedTextNodeLayout *prepared, NSTextView *proxy, NSRange selection,
    NSArray<NSValue *> **outRects, NSRect *outCaret) {
    if (outRects) *outRects = @[];
    if (outCaret) *outCaret = NSZeroRect;
    if (!node || !proxy ||
        !CjguiComposableNodeHasGpuText(node.node.nodeKind))
        return CjguiSelectionGeometryReject("node-layout-proxy-kind");
    NSString *nodeBody = node.value ?: @"";
    NSString *proxyBody = proxy.string ?: @"";
    if (![proxyBody isEqualToString:nodeBody]) {
        CjguiLogSelectionGeometryBodyMismatch(node, prepared, proxy);
        return CjguiSelectionGeometryReject("layout-body-mismatch");
    }
    if (!NSEqualRanges(proxy.selectedRange, selection) || proxy.hasMarkedText)
        return CjguiSelectionGeometryReject("proxy-range-or-marked-text");
    if (selection.location == NSNotFound || selection.location > nodeBody.length ||
        NSMaxRange(selection) > nodeBody.length ||
        !NSEqualRanges(CjguiComposedSelection(nodeBody, selection.location, NSMaxRange(selection)), selection))
        return CjguiSelectionGeometryReject("selection-invalid-or-not-composed");

    NSRect nodeRect = CjguiComposableVisualNodeRect(node);
    NSRect nominalLocalTextRect = NSZeroRect;
    (void)CjguiComposableEmptyTextLayoutRect(node, &nominalLocalTextRect);
    NSRect textRect = NSOffsetRect(nominalLocalTextRect, NSMinX(nodeRect), NSMinY(nodeRect));
    NSRect visible = NSIntersectionRect(textRect, CjguiComposableVisualClipBounds(node));
    // A global accepted selection can target a fragment that is currently
    // fully outside the viewport. Its semantic body and installed proxy range
    // remain authoritative, while the accepted scene has no pixels to paint.
    // Prove that from the node's nominal text box and current clip before
    // consulting its optional/empty raster layout placeholder.
    if (NSIsEmptyRect(visible)) return YES;

    if (!prepared || !prepared.storage || !prepared.layoutManager || !prepared.container)
        return CjguiSelectionGeometryReject("layout-components-missing");
    if (![prepared.storage.string isEqualToString:nodeBody]) {
        CjguiLogSelectionGeometryBodyMismatch(node, prepared, proxy);
        return CjguiSelectionGeometryReject("layout-body-mismatch");
    }
    if (!NSEqualRects(prepared.textRect, nominalLocalTextRect))
        return CjguiSelectionGeometryReject("layout-text-rect-mismatch");
    if (prepared.layoutManager.firstUnlaidCharacterIndex < prepared.storage.length)
        return CjguiSelectionGeometryReject("layout-not-full");

    NSMutableArray<NSValue *> *rects = [NSMutableArray array];
    if (!NSIsEmptyRect(visible) && selection.length > 0) {
        NSLayoutManager *layout = prepared.layoutManager;
        NSRange glyphs = [layout glyphRangeForCharacterRange:selection actualCharacterRange:NULL];
        [layout enumerateEnclosingRectsForGlyphRange:glyphs withinSelectedGlyphRange:glyphs
            inTextContainer:prepared.container usingBlock:^(NSRect rect, BOOL *stop) {
                (void)stop;
                NSRect sceneRect = NSIntersectionRect(
                    NSOffsetRect(rect, NSMinX(textRect), NSMinY(textRect)), visible);
                if (!NSIsEmptyRect(sceneRect)) [rects addObject:[NSValue valueWithRect:sceneRect]];
            }];
        if (rects.count == 0) return CjguiSelectionGeometryReject("selection-has-no-visible-geometry");
        if (rects.count > 1024) return CjguiSelectionGeometryReject("selection-geometry-limit");
    }

    NSRect caret = NSZeroRect;
    if (selection.length == 0 && !NSIsEmptyRect(visible)) {
        if (nodeBody.length == 0) {
            CGFloat lineHeight = MAX(1.0, prepared.defaultLineHeight);
            caret = NSMakeRect(NSMinX(textRect) + prepared.container.lineFragmentPadding,
                NSMinY(textRect) + 2.0, 1.5, MAX(1.0, lineHeight - 4.0));
        } else {
            NSLayoutManager *layout = prepared.layoutManager;
            NSTextContainer *container = prepared.container;
            NSUInteger location = selection.location;
            NSUInteger character = location >= nodeBody.length ? nodeBody.length - 1 : location;
            NSUInteger glyph = [layout glyphIndexForCharacterAtIndex:character];
            BOOL extraLine = location == nodeBody.length && layout.extraLineFragmentTextContainer == container &&
                !NSIsEmptyRect(layout.extraLineFragmentRect);
            NSRect line = extraLine ? layout.extraLineFragmentRect :
                [layout lineFragmentRectForGlyphAtIndex:glyph effectiveRange:NULL];
            NSPoint glyphPoint = extraLine ? layout.extraLineFragmentUsedRect.origin :
                [layout locationForGlyphAtIndex:glyph];
            CGFloat x = extraLine ? glyphPoint.x : (location >= nodeBody.length
                ? NSMaxX([layout boundingRectForGlyphRange:NSMakeRange(glyph, 1) inTextContainer:container])
                : glyphPoint.x);
            caret = NSMakeRect(NSMinX(textRect) + x, NSMinY(textRect) + NSMinY(line) + 2.0,
                1.5, MAX(1.0, NSHeight(line) - 4.0));
        }
        caret = NSIntersectionRect(caret, visible);
    }
    if (outRects) *outRects = [rects copy];
    if (outCaret) *outCaret = caret;
    const char *trace = getenv("CJGUI_TEXT_PREPARE_TRACE");
    if (trace && strcmp(trace, "1") == 0)
        fprintf(stderr, "CJGUI_SELECTION_GEOMETRY prepared node=%llu kind=%u full=%lu range=%lu:%lu rects=%lu caret=%.2f,%.2f,%.2f,%.2f\n",
            (unsigned long long)node.node.nodeId, node.node.nodeKind,
            (unsigned long)prepared.storage.length, (unsigned long)selection.location,
            (unsigned long)selection.length, (unsigned long)rects.count,
            caret.origin.x, caret.origin.y, caret.size.width, caret.size.height);
    return YES;
}

// A transfer-created geometry array is usable only while the exact accepted
// scene, body, proxy, owner acknowledgement, and installed selection receipt
// that produced it remain current. Stale tagged rectangles fail closed; the
// immutable owner declaration path remains independently available.
static BOOL CjguiCandidateSelectionGeometryMatches(CJGuiInternalSession *ctx,
    CJGuiInternalComposableSceneNode *node) {
    CjguiSelectionTransferCapsule *c=ctx.selectionTransferCapsule;
    return c && c.candidateSceneTransfer && c.candidateInstallReady &&
        ctx.selectionPaintPublishingScene==c.bSceneVersion && ctx.composableSceneVersion==c.bSceneVersion &&
        node.textSelectionTransferId==c.transferId && node.node.nodeId==c.bNodeId &&
        node.node.resourceId==c.bResourceId && node.node.nodeKind==c.bNodeKind &&
        node.node.projectionVersion==c.bProjectionVersion && [node.value isEqualToString:c.bBody] &&
        [c.preparedOverlay.inputProxy.string isEqualToString:c.bBody] &&
        NSEqualRanges(c.preparedOverlay.inputProxy.selectedRange,c.bSelection) &&
        !c.preparedOverlay.inputProxy.hasMarkedText;
}

static BOOL CjguiTransferSelectionGeometryReceiptMatches(CJGuiInternalSession *ctx,
    CJGuiInternalComposableSceneOverlay *overlay, CJGuiInternalComposableSceneNode *node) {
    if (!ctx || !overlay || !node) return NO;
    uint64_t geometryTransferId = node.textSelectionTransferId;
    CjguiInstalledRangeState *basis = ctx.installedRangeBasis;
    if (!geometryTransferId || geometryTransferId != overlay.installedSourceSelectionGeometryTransferId ||
        !basis || basis.selectionTransferId != geometryTransferId ||
        node.node.nodeId != basis.candidate.nodeId || node.node.resourceId != basis.candidate.resourceId ||
        ctx.destroyed || !ctx.view || !basis.active || basis.chainClosed || !basis.hasReceipt ||
        !basis.selectionTransferId || basis.candidate.nonce != basis.selectionTransferId ||
        basis.candidate.rendererSessionGeneration != ctx.sessionGeneration ||
        basis.candidate.bindingEpoch != ctx.ownedTextSessionBindingEpoch ||
        basis.candidate.nodeId != ctx.ownedTextSessionNodeId ||
        basis.candidate.resourceId != ctx.ownedTextSessionResourceId ||
        ctx.installedRangeObservedAckVersion != basis.candidate.ownerVersion ||
        ctx.installedRangeProxyGeneration != basis.proxyGeneration ||
        !overlay.inputProxy || basis.proxy != overlay.inputProxy ||
        overlay.installedRangeSelectionRevision != basis.selectionRevision ||
        !CjguiInstalledRangeBasisMatchesActual(ctx, overlay) ||
        ctx.composableSceneVersion != basis.candidate.installedSceneVersion ||
        overlay.activeProjectionVersion != node.node.projectionVersion ||
        node.index >= ctx.view.composableNodes.count || ctx.view.composableNodes[node.index] != node ||
        !CjguiComposableNodeHasGpuText(node.node.nodeKind)) return NO;
    NSData *proxyBody = [overlay.inputProxy.string dataUsingEncoding:NSUTF8StringEncoding
                                                   allowLossyConversion:NO];
    NSData *nodeBody = [(node.value ?: @"") dataUsingEncoding:NSUTF8StringEncoding
                                             allowLossyConversion:NO];
    if (!proxyBody || !nodeBody || ![proxyBody isEqualToData:basis.sourceUtf8] ||
        ![nodeBody isEqualToData:basis.sourceUtf8] ||
        overlay.inputProxy.selectedRange.location != basis.actualSelectionStart16 ||
        NSMaxRange(overlay.inputProxy.selectedRange) != basis.actualSelectionEnd16) return NO;
    return YES;
}

static NSArray<NSValue *> *CjguiEffectiveTransferTextSelectionRects(
    CJGuiInternalSession *ctx, CJGuiInternalComposableSceneNode *node) {
    if (!node) return @[];
    if (!node.textSelectionTransferId) return node.textSelectionRects ?: @[];
    if (!CjguiCandidateSelectionGeometryMatches(ctx,node) &&
        !CjguiTransferSelectionGeometryReceiptMatches(ctx, ctx.composableSceneOverlay, node)) return @[];
    return node.textSelectionRects ?: @[];
}

static NSRect CjguiEffectiveTransferTextCaretRect(CJGuiInternalSession *ctx,
    CJGuiInternalComposableSceneNode *node) {
    if (!node) return NSZeroRect;
    if (!node.textSelectionTransferId || node.textCaretIsDeclared) return node.textCaretRect;
    if (!CjguiCandidateSelectionGeometryMatches(ctx,node) &&
        !CjguiTransferSelectionGeometryReceiptMatches(ctx, ctx.composableSceneOverlay, node)) return NSZeroRect;
    return node.textCaretRect;
}

static BOOL CjguiSourceInstallCanRetainActualProxy(CJGuiInternalSession *ctx,
    CJGuiInternalComposableSceneOverlay *overlay, NSString *expected) {
    if (!ctx || !overlay || !expected) return NO;
    uint64_t expectedBytes=[expected lengthOfBytesUsingEncoding:NSUTF8StringEncoding];
    if (expectedBytes>65536u) return NO;
    NSData *actual=[overlay.inputProxy.string dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
    if (!actual) return NO;
    if (actual.length<=65536u) return YES;
    CjguiInstalledRangeState *basis=ctx.installedRangeBasis;
    if (!basis || !basis.active || basis.chainClosed || ctx.installedRangeProvisional ||
        ctx.installedRangeReservation || ctx.claimedInstalledRangeIntent ||
        ctx.installedRangeLocalTailSequence!=ctx.installedRangeObservedAckSequence ||
        !CjguiInstalledRangeBasisMatchesActual(ctx,overlay) ||
        ![actual isEqualToData:basis.sourceUtf8] ||
        basis.candidate.sourceEndByte<basis.candidate.sourceStartByte ||
        basis.candidate.sourceEndByte-basis.candidate.sourceStartByte!=actual.length ||
        actual.length>CJGUI_INSTALLED_RANGE_BYTE_CAPACITY ||
        ctx.installedRangeBytesUsed<actual.length ||
        ctx.installedRangeBytesUsed>CJGUI_INSTALLED_RANGE_BYTE_CAPACITY ||
        ctx.installedRangeBytesReserved>CJGUI_INSTALLED_RANGE_BYTE_CAPACITY-ctx.installedRangeBytesUsed)
        return NO;
    return YES;
}

static BOOL CjguiInstalledRangeScopeMatchesCurrent(CJGuiInternalSession *ctx,
    CJGuiInternalComposableSceneOverlay *overlay, CjguiInstalledRangeState *state) {
    return ctx && !ctx.destroyed && overlay && state && ctx.ownedTextSessionEnabled &&
        ctx.sessionGeneration == state.candidate.rendererSessionGeneration &&
        ctx.ownedTextSessionNodeId == state.candidate.nodeId &&
        ctx.ownedTextSessionResourceId == state.candidate.resourceId &&
        ctx.ownedTextSessionBindingEpoch == state.candidate.bindingEpoch &&
        (ctx.ownedTextSessionNodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT ||
         (state.selectionTransferId && ctx.ownedTextSessionNodeKind == state.proxyNodeKind)) &&
        overlay.activeNodeId == state.candidate.nodeId &&
        overlay.activeNodeResourceId == state.candidate.resourceId &&
        (overlay.activeNodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT ||
         (state.selectionTransferId && overlay.activeNodeKind == state.proxyNodeKind));
}

static void CjguiRetireInstalledRangeReservation(CJGuiInternalSession *ctx,
    CjguiInstalledRangeIntentState *reservation) {
    if (!ctx || !reservation || ctx.installedRangeReservation != reservation) return;
    ctx.installedRangeBytesReserved = ctx.installedRangeBytesReserved >= reservation.chargedBytes
        ? ctx.installedRangeBytesReserved - reservation.chargedBytes : 0;
    ctx.installedRangeSlotsReserved = ctx.installedRangeSlotsReserved >= reservation.reservedSlots
        ? ctx.installedRangeSlotsReserved - reservation.reservedSlots : 0;
    ctx.installedRangeReservation = nil;
}

static BOOL CjguiEnqueueInstalledRangeInteraction(CJGuiInternalSession *ctx,
    CjguiInstalledRangeIntentState *intent, BOOL ownedInvalid) {
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    CjguiInternalInstalledRangeIntent c = intent.value;
    NSString *replacement = intent.replacement
        ? [[NSString alloc] initWithData:intent.replacement encoding:NSUTF8StringEncoding] : @"";
    CJGuiInternalQueuedInteraction *queued = [[CJGuiInternalQueuedInteraction alloc]
        initWithKind:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_RANGE_CHANGED
        recordIndex:overlay.activeNodeIndex >= 0 ? (uint32_t)overlay.activeNodeIndex : 0
        selectionStart:intent.value.rangeStart16
        selectionEnd:intent.value.rangeStart16 + intent.value.rangeLength16
        formText:replacement ?: @"" nodeId:c.nodeId projectionVersion:c.installedSceneVersion
        resourceId:c.resourceId nodeKind:overlay.activeNodeKind];
    if (!queued || ctx.pendingInteractions.count >= kCjguiPendingInteractionCapacity) return NO;
    queued.bindingEpoch = c.bindingEpoch;
    queued.installedRangeNonce = c.nonce;
    queued.installedRangeOwnedInvalid = ownedInvalid;
    if (!ownedInvalid) queued.installedRangeIntent = intent;
    [ctx.pendingInteractions addObject:queued];
    CjguiOwnerPumpTicketNoteWork(ctx);
    return YES;
}

static BOOL CjguiInstalledRangeAckHasLaterTargetTextInput(CJGuiInternalSession *ctx,
    CjguiInternalInstalledRangeIntent intent) {
    for (CJGuiInternalQueuedInteraction *queued in ctx.pendingInteractions) {
        if (queued.nodeId != intent.nodeId || queued.resourceId != intent.resourceId) continue;
        if (queued.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_CHANGED ||
            queued.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_RANGE_CHANGED ||
            queued.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_COMPOSITION) return YES;
    }
    return NO;
}

static void CjguiSettleInstalledRangeLocalEditForAck(CJGuiInternalSession *ctx,
    CjguiInstalledRangeIntentState *state, CjguiInternalInstalledRangeIntent intent) {
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    if (!overlay || !state || !state.localEditRecorded ||
        state.localEditGeneration == 0 || state.localEditProxy != overlay.inputProxy ||
        state.localEditBindingEpoch != intent.bindingEpoch ||
        state.localEditNodeId != intent.nodeId || state.localEditResourceId != intent.resourceId ||
        state.localEditNodeKind != overlay.activeNodeKind ||
        overlay.activeLocalEditGeneration != state.localEditGeneration ||
        overlay.activeLocalEditSettledGeneration == state.localEditGeneration ||
        overlay.activeLocalEditProxy != state.localEditProxy ||
        overlay.activeLocalEditBindingEpoch != state.localEditBindingEpoch ||
        overlay.activeLocalEditNodeId != state.localEditNodeId ||
        overlay.activeLocalEditResourceId != state.localEditResourceId ||
        overlay.activeLocalEditNodeKind != state.localEditNodeKind ||
        ctx.installedRangeLocalTailSequence != intent.seq ||
        ctx.installedRangeReservation || overlay.inputProxy.hasMarkedText ||
        overlay.compositionTerminalInFlight || overlay.activeTextRangeEditPending ||
        overlay.activeTextFallbackHasPendingEdit || CjguiInstalledRangeAckHasLaterTargetTextInput(ctx, intent))
        return;
    NSData *actual = [overlay.inputProxy.string dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
    if (!actual || ![actual isEqualToData:state.postBody]) return;
    // Selection is a separate owner ticket. A later caret/selection change does
    // not revoke this body's exact ACK and must not make its generation immortal.
    overlay.activeLocalEditSettledGeneration = state.localEditGeneration;
}

static BOOL CjguiReserveInstalledRangeEdit(CJGuiInternalComposableSceneOverlay *overlay,
    NSRange range, NSString *replacementText) {
    CJGuiInternalSession *ctx = overlay.session;
    // Named attribution for the CAPTURE decision: if no reservation is made, the text change reaches
    // the Cangjie seam unclaimed and is refused as `installed_range_sideband_invalid`, which is the
    // keystroke-after-an-external-write failure. `CjguiInstalledRangeBasisMatchesActual` was verified
    // all-true at that moment, so the cause is one of these other conditions.
    if (getenv("CJGUI_INSTALLED_RANGE_TRACE")) {
        BOOL basisOk = CjguiInstalledRangeBasisMatchesActual(ctx, overlay);
        fprintf(stderr, "CJGUI_RESERVE_GATE basisOk=%d deltaEnabled=%d provisional=%d installActive=%d seqMax=%d\n",
            basisOk?1:0, (ctx&&ctx.rangeTextEditDeltaDeliveryEnabled)?1:0,
            (ctx&&ctx.installedRangeProvisional)?1:0, overlay?((overlay.sourceSelectionInstallActive)?1:0):-1,
            (ctx&&ctx.installedRangeNextSequence==UINT64_MAX)?1:0);
        fflush(stderr);
    }
    if (!CjguiInstalledRangeBasisMatchesActual(ctx, overlay) || !ctx.rangeTextEditDeltaDeliveryEnabled ||
        ctx.installedRangeProvisional || overlay.sourceSelectionInstallActive ||
        ctx.installedRangeNextSequence == UINT64_MAX) return NO;
    CjguiInstalledRangeState *basis = ctx.installedRangeBasis;
    NSString *preString = overlay.inputProxy.string ?: @"";
    if (range.location > preString.length || NSMaxRange(range) > preString.length ||
        !NSEqualRanges(CjguiComposedSelection(preString, range.location, NSMaxRange(range)), range)) return NO;
    NSString *replacement = replacementText ?: @"";
    NSMutableString *postString = [preString mutableCopy];
    [postString replaceCharactersInRange:range withString:replacement];
    NSData *pre = [preString dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
    NSData *insert = [replacement dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
    NSData *post = [postString dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
    if (!pre || !insert || !post) return NO;
    uint64_t total = pre.length + insert.length + post.length;
    if (total > CJGUI_INSTALLED_RANGE_BYTE_CAPACITY / 3u) return NO;
    uint64_t charged = total * 3u;
    if (ctx.installedRangeBytesUsed > CJGUI_INSTALLED_RANGE_BYTE_CAPACITY - charged ||
        ctx.installedRangeBytesReserved > CJGUI_INSTALLED_RANGE_BYTE_CAPACITY - charged - ctx.installedRangeBytesUsed ||
        CjguiPendingInteractionOccupancy(ctx) + CJGUI_INSTALLED_RANGE_RESERVED_FIFO_SLOTS >
            kCjguiPendingInteractionCapacity) return NO;
    if (ctx.installedRangeReservation)
        CjguiRetireInstalledRangeReservation(ctx, ctx.installedRangeReservation);
    CjguiInstalledRangeIntentState *state = [CjguiInstalledRangeIntentState new];
    if (!state) return NO;
    state.caretInputBranch = ctx.materializingAfterCaretBranch;
    CjguiInternalInstalledRangeIntent value = {0};
    value.nonce = basis.candidate.nonce;
    if (basis.selectionTransferId) value.flags |= 2u; // owner choice required; prohibit legacy range mapping
    value.rendererSessionGeneration = basis.candidate.rendererSessionGeneration;
    value.windowInstanceToken = basis.candidate.windowInstanceToken;
    value.bindingEpoch = basis.candidate.bindingEpoch;
    value.contextEpoch = basis.candidate.contextEpoch;
    value.mirrorRevision = basis.candidate.mirrorRevision;
    value.ownerVersion = basis.candidate.ownerVersion;
    value.installedSceneVersion = basis.candidate.installedSceneVersion;
    value.nodeId = basis.candidate.nodeId;
    value.resourceId = basis.candidate.resourceId;
    value.sourceStartByte = basis.candidate.sourceStartByte;
    value.sourceEndByte = basis.candidate.sourceEndByte;
    value.proxyGeneration = basis.proxyGeneration;
    value.selectionRevision = overlay.installedRangeSelectionRevision;
    value.seq = ++ctx.installedRangeNextSequence;
    value.previousSeq = ctx.installedRangeLocalTailSequence;
    value.observedAckSeq = ctx.installedRangeObservedAckSequence;
    value.observedAckVersion = ctx.installedRangeObservedAckVersion;
    if (ctx.installedWholeChoiceNonce &&
        ctx.installedWholeChoiceRevision == overlay.installedRangeSelectionRevision &&
        ctx.installedWholeChoicePrevious == ctx.installedRangeLocalTailSequence &&
        range.location == 0 && range.length == preString.length) {
        value.wholeChoiceNonce = ctx.installedWholeChoiceNonce;
        value.wholeChoicePreviousSeq = ctx.installedWholeChoicePrevious;
    }
    value.rangeStart16 = (uint32_t)range.location;
    value.rangeLength16 = (uint32_t)range.length;
    NSRange actualSelection = overlay.inputProxy.selectedRange;
    if (actualSelection.location == NSNotFound || NSMaxRange(actualSelection) > preString.length ||
        actualSelection.location > UINT32_MAX || NSMaxRange(actualSelection) > UINT32_MAX) return NO;
    value.selectionStart16 = (uint32_t)actualSelection.location;
    value.selectionEnd16 = (uint32_t)NSMaxRange(actualSelection);
    value.preBodyUtf8Length = (uint32_t)pre.length;
    value.replacementUtf8Length = (uint32_t)insert.length;
    value.postBodyUtf8Length = (uint32_t)post.length;
    state.value = value;
    state.preBody = pre; state.replacement = insert; state.postBody = post;
    state.chargedBytes = charged;
    state.reservedSlots = CJGUI_INSTALLED_RANGE_RESERVED_FIFO_SLOTS;
    ctx.installedRangeBytesReserved += charged;
    ctx.installedRangeSlotsReserved += state.reservedSlots;
    ctx.installedRangeReservation = state;
    return YES;
}

static BOOL CjguiCompleteInstalledRangeReservation(CJGuiInternalComposableSceneOverlay *overlay) {
    CJGuiInternalSession *ctx = overlay.session;
    CjguiInstalledRangeIntentState *state = ctx.installedRangeReservation;
    if (!state) return NO;
    uint64_t reservedBytes = state.chargedBytes;
    NSData *actual = [overlay.inputProxy.string dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
    if (overlay.inputProxy.hasMarkedText || overlay.compositionTerminalInFlight) {
        // A composition is represented only by its kind-52 lifecycle. The
        // ordinary shouldChange reservation must not leak a second kind-51.
        if (ctx.installedRangeBasis) ctx.installedRangeBasis.chainClosed = YES;
        CjguiRetireInstalledRangeReservation(ctx, state);
        overlay.installedRangeSuppressSelectionPending = YES;
        dispatch_async(dispatch_get_main_queue(), ^{ overlay.installedRangeSuppressSelectionPending = NO; });
        return YES;
    }
    if (actual && [actual isEqualToData:state.preBody] && !state.value.wholeChoiceNonce) {
        CjguiRetireInstalledRangeReservation(ctx, state);
        return YES;
    }
    // `textDidChange` can run after a projection removed the target from the
    // visible node array. The reservation still names the real proxy mutation,
    // so record its generation here, before the later legacy active-node lookup.
    if (!overlay.applyingProjection && state.value.seq != 0) {
        [overlay recordActiveLocalEdit];
        state.localEditProxy = overlay.inputProxy;
        state.localEditGeneration = overlay.activeLocalEditGeneration;
        state.localEditBindingEpoch = state.value.bindingEpoch;
        state.localEditNodeId = state.value.nodeId;
        state.localEditResourceId = state.value.resourceId;
        state.localEditNodeKind = overlay.activeNodeKind;
        state.localEditRecorded = YES;
    }
    BOOL exact = CjguiInstalledRangeBasisMatchesActual(ctx, overlay) && actual &&
        [actual isEqualToData:state.postBody] && !overlay.inputProxy.hasMarkedText &&
        !overlay.compositionTerminalInFlight && !overlay.applyingProjection;
    if (exact) {
        if (!CjguiEnqueueInstalledRangeInteraction(ctx, state, NO)) exact = NO;
    }
    if (!exact) {
        if (ctx.installedRangeBasis) ctx.installedRangeBasis.chainClosed = YES;
        CjguiInternalInstalledRangeIntent invalidValue = state.value;
        invalidValue.flags |= 1u;
        state.value = invalidValue;
        state.preBody = [NSData data]; state.replacement = [NSData data]; state.postBody = [NSData data];
        invalidValue.preBodyUtf8Length = 0; invalidValue.replacementUtf8Length = 0;
        invalidValue.postBodyUtf8Length = 0; state.value = invalidValue;
        state.chargedBytes = 0; state.settled = YES;
        // The slot was reserved before AppKit mutated storage. This marker
        // keeps an unprovable owned kind-51 from entering the legacy route.
        (void)CjguiEnqueueInstalledRangeInteraction(ctx, state, YES);
    } else {
        ctx.installedRangeBytesUsed += state.chargedBytes;
        ctx.installedRangeLocalTailSequence = state.value.seq;
    }
    if (state.value.wholeChoiceNonce == ctx.installedWholeChoiceNonce)
        ctx.installedWholeChoiceNonce = 0;
    uint32_t slots = state.reservedSlots;
    ctx.installedRangeBytesReserved = ctx.installedRangeBytesReserved >= reservedBytes
        ? ctx.installedRangeBytesReserved - reservedBytes : 0;
    ctx.installedRangeSlotsReserved = ctx.installedRangeSlotsReserved >= slots
        ? ctx.installedRangeSlotsReserved - slots : 0;
    ctx.installedRangeReservation = nil;
    CjguiCancelSourceProxyPreparation(ctx);
    overlay.installedRangeSuppressSelectionPending = YES;
    dispatch_async(dispatch_get_main_queue(), ^{
        overlay.installedRangeSuppressSelectionPending = NO;
    });
    return YES;
}

static void CjguiExpireUncompletedInstalledRangeReservation(CJGuiInternalSession *ctx,
    CJGuiInternalComposableSceneOverlay *overlay, CjguiInstalledRangeIntentState *state) {
    if (!ctx || !overlay || !state || ctx.installedRangeReservation != state) return;
    NSData *actual = [overlay.inputProxy.string dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
    BOOL mutated = !actual || ![actual isEqualToData:state.preBody];
    if (mutated) {
        if (ctx.installedRangeBasis) ctx.installedRangeBasis.chainClosed = YES;
        CjguiRetireInstalledRangeReservation(ctx, state);
        state.chargedBytes = 0;
        state.preBody = [NSData data]; state.replacement = [NSData data]; state.postBody = [NSData data];
        CjguiInternalInstalledRangeIntent invalidValue = state.value;
        invalidValue.flags |= 1u;
        invalidValue.preBodyUtf8Length = 0; invalidValue.replacementUtf8Length = 0;
        invalidValue.postBodyUtf8Length = 0;
        state.value = invalidValue;
        (void)CjguiEnqueueInstalledRangeInteraction(ctx, state, YES);
    } else {
        CjguiRetireInstalledRangeReservation(ctx, state);
    }
}

static void CjguiCancelInstalledRangeCandidateForInput(CJGuiInternalSession *ctx) {
    CjguiInstalledRangeState *candidate = ctx.installedRangeCandidate;
    if (!candidate) return;
    uint64_t bytes = CjguiInstalledRangeStateBytes(candidate);
    ctx.installedRangeBytesUsed = ctx.installedRangeBytesUsed >= bytes
        ? ctx.installedRangeBytesUsed - bytes : 0;
    ctx.installedRangeCandidate = nil;
    // An edit against the still-installed old adapter invalidates only the
    // pending source candidate. Keep the active basis and its FIFO identity.
    if (ctx.installedRangeBasis) CjguiMarkInstalledRangeSourceParked(ctx, NO);
}


// The focused input's staged static candidate is never drawn this turn: the
// active TextKit refresh that the same commit triggers owns the visible body.
// Only a real text input is continued by that refresh. A focused tab title or
// button has no caret, selection or marked text, so its static candidate must
// still rasterize here — skipping it left a same-commit label or textColor
// change rendering the previous texture.
static BOOL CjguiStagedNodeIsFocusedInput(CJGuiInternalSession *ctx,
    CJGuiInternalComposableSceneNode *node) {
    if (!ctx || !node) return NO;
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    if (!overlay || !CjguiComposableNodeIsTextInput(overlay.activeNodeKind)) return NO;
    if (overlay.sourceInputParked) return NO;
    // E's static candidate must not depend on installing a different live
    // body during projection admission. Its own graph is prepared instead.
    if (CjguiSourceInstallPending(ctx) &&
        node.node.nodeId == ctx.ownedTextSessionNodeId &&
        node.node.resourceId == ctx.ownedTextSessionResourceId &&
        node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT &&
        !node.node.preservesActiveLocalText &&
        (![node.value isEqualToString:overlay.inputProxy.string ?: @""] ||
         ![(node.styleRunsSignature ?: @"") isEqualToString:overlay.activeTextRunsSignature ?: @""]))
        return NO;
    return node.node.nodeId == overlay.activeNodeId &&
        node.node.resourceId == overlay.activeNodeResourceId &&
        node.node.nodeKind == overlay.activeNodeKind;
}

@implementation CJGuiInternalComposableAccessibilityAction
- (instancetype)initWithOverlay:(CJGuiInternalComposableSceneOverlay *)overlay node:(CJGuiInternalComposableSceneNode *)node {
    self = [super init]; if (!self) return nil; self.overlay = overlay; self.node = node;
    self.semanticChildren = [NSMutableArray array];
    return self;
}
- (CJGuiInternalComposableSceneNode *)currentNode {
    // Once published, a retired wrapper may never acquire a later node that
    // happens to reuse its numeric id or projection version.
    if (self.identityKey.length > 0 && self.overlay.accessibilityActionsByIdentity[self.identityKey] != self) return nil;
    return [self.overlay accessibilityLiveNodeForNode:self.node];
}
- (id)accessibilityParent { return [self currentNode] ? (self.semanticParent ?: self.overlay) : nil; }
- (NSArray<id> *)accessibilityChildren { return [self currentNode] ? [self.semanticChildren copy] : @[]; }
- (id)accessibilityWindow { return [self currentNode] ? self.overlay.window : nil; }
- (id)accessibilityTopLevelUIElement { return [self currentNode] ? self.overlay.window : nil; }
- (BOOL)isAccessibilityElement { return [self currentNode] != nil; }
- (NSAccessibilityRole)accessibilityRole {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    uint32_t kind = node ? node.node.nodeKind : 0;
    uint32_t semanticRole = node ? node.node.semanticRole : 0;
    if (semanticRole == 1) return NSAccessibilityTabGroupRole;
    if (semanticRole == 2) return NSAccessibilityRadioButtonRole;
    if (semanticRole == 3) return NSAccessibilityScrollAreaRole;
    if (semanticRole == 4) return NSAccessibilityOutlineRole;
    if (semanticRole == 5) return NSAccessibilityRowRole;
    if (semanticRole == 6) return NSAccessibilityButtonRole;
    if (semanticRole == 7) return NSAccessibilityCheckBoxRole;
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT) return NSAccessibilityStaticTextRole;
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BUTTON ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_VECTOR_GRAPHIC) return NSAccessibilityButtonRole;
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT) return NSAccessibilityCheckBoxRole;
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TABS) return NSAccessibilityTabGroupRole;
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE) return NSAccessibilityRadioButtonRole;
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_SCROLL_AREA) return NSAccessibilityScrollAreaRole;
    // AppKit's own split: NSTextField is a single-line `AXTextField`, NSTextView is an `AXTextArea`.
    // A multi-line text input is the second kind. Answering `AXTextField` for the document body told
    // assistive tech (and the acceptance probe that asks the application for its focused element)
    // that the editor was a one-line field.
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) return NSAccessibilityTextAreaRole;
    if (CjguiComposableNodeIsTextInput(kind)) return NSAccessibilityTextFieldRole;
    return NSAccessibilityGroupRole;
}
- (NSString *)accessibilityLabel {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    return node ? (node.semanticLabel.length > 0 ? node.semanticLabel :
        (node.label.length > 0 ? node.label : node.value)) : @"";
}
- (NSString *)accessibilityTitle {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    return node && node.label.length > 0 ? node.label : nil;
}
- (NSString *)accessibilityIdentifier {
    // The accepted public semantic identity is the exact address of this
    // instance. A driver or assistant targets one node by its stable id instead
    // of guessing from the rendered caption, which two rows may share.
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    return node.semanticId.length > 0 ? node.semanticId : nil;
}
- (id)accessibilityValue {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    if (!node) return nil;
    if (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT) {
        return @([node.value isEqualToString:@"true"]);
    }
    if (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE) {
        return @(node.node.tabSelected != 0);
    }
    return CjguiComposableNodeIsTextInput(node.node.nodeKind) ? [self.overlay accessibilityCurrentTextForNode:node] : node.value;
}
- (BOOL)isAccessibilitySelected {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    if (!node) return NO;
    if (node.node.semanticRole == 5) return (node.node.semanticState & 1u) != 0;
    return node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE && node.node.tabSelected != 0;
}
- (BOOL)isAccessibilityDisclosed {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    return node && node.node.semanticRole == 5 && (node.node.semanticState & 4u) != 0;
}
- (BOOL)isAccessibilityExpanded { return [self isAccessibilityDisclosed]; }
- (NSInteger)accessibilityDisclosureLevel {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    return node && node.node.semanticRole == 5 ? (NSInteger)node.node.semanticLevel : 0;
}
- (BOOL)accessibilityIsAttributeSettable:(NSAccessibilityAttributeName)attribute {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    if (!node) return NO;
    uint32_t kind = node.node.nodeKind;
    if ([attribute isEqualToString:NSAccessibilitySelectedTextRangeAttribute]) {
        return CjguiComposableNodeIsTextInput(kind) && node.node.isInteractive != 0;
    }
    if (![attribute isEqualToString:NSAccessibilityValueAttribute]) return NO;
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT) return [self.overlay accessibilityNodeIsActionable:node];
    return CjguiComposableNodeIsTextInput(kind) && [self.overlay accessibilityNodeIsActionable:node];
}

- (BOOL)accessibilityIsEnabled {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    if (!node) return NO;
    if (node.node.semanticRole == 5) return (node.node.semanticState & 8u) == 0;
    if (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE ||
        node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BUTTON ||
        node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT) return node.node.isInteractive != 0;
    return (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT ||
        node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TABS ||
        node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_SCROLL_AREA ||
        node.node.semanticRole == 4 || node.node.isInteractive != 0);
}
- (BOOL)isAccessibilityEnabled {
    // AppKit accessibility clients query this legacy selector when deciding
    // whether an exposed self-drawn element can receive an action.
    return [self accessibilityIsEnabled];
}
- (BOOL)accessibilityIsEditable {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    return node && CjguiComposableNodeIsTextInput(node.node.nodeKind) && [self.overlay accessibilityNodeIsActionable:node];
}
- (NSArray<NSAccessibilityActionName> *)accessibilityActionNames {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    if (!node || ![self.overlay accessibilityNodeIsActionable:node]) return @[];
    uint32_t kind = node.node.nodeKind;
    // A tab TITLE and a vector graphic are pressable exactly like a button: the
    // press enqueues the generic ACTIVATE interaction and Cangjie resolves it
    // against the accepted state. An action that can be performed but is never
    // ADVERTISED is invisible to an accessibility client, so this list and
    // accessibilityPerformPressForNode must agree.
    return (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BUTTON ||
            kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT ||
            kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_VECTOR_GRAPHIC ||
            kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE)
        ? @[ NSAccessibilityPressAction ] : @[];
}
- (NSRect)accessibilityFrame {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    return node ? NSAccessibilityFrameInView(self.overlay,
        NSIntersectionRect(CjguiComposableRect(node, self.overlay), CjguiComposableClipBounds(node))) : NSZeroRect;
}
- (NSPoint)accessibilityPosition { return [self accessibilityFrame].origin; }
- (NSSize)accessibilitySize { return [self accessibilityFrame].size; }
- (NSRect)accessibilityFrameInParentSpace {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    if (!node) return NSZeroRect;
    NSRect rect = NSIntersectionRect(CjguiComposableRect(node, self.overlay), CjguiComposableClipBounds(node));
    CJGuiInternalComposableSceneNode *parent = [self.semanticParent currentNode];
    if (parent) {
        NSRect parentRect = CjguiComposableRect(parent, self.overlay);
        rect.origin.x -= parentRect.origin.x;
        rect.origin.y -= parentRect.origin.y;
    }
    return rect;
}
- (BOOL)accessibilityFocused { return [self.overlay accessibilityNodeIsFocused:[self currentNode]]; }
- (BOOL)isAccessibilityFocused { return [self accessibilityFocused]; }
- (void)setAccessibilityFocused:(BOOL)focused { [self accessibilitySetFocused:focused]; }
- (void)accessibilitySetFocused:(BOOL)focused {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    if (!focused || !node) return;
    if (CjguiComposableNodeIsTextInput(node.node.nodeKind) && node.node.isInteractive != 0) {
        [self.overlay focusNode:node enqueue:YES];
    } else if ([self.overlay accessibilityNodeIsActionable:node]) {
        [self.overlay focusNode:node enqueue:YES];
    }
}
- (NSRange)accessibilitySelectedTextRange {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    if (!node || !CjguiComposableNodeIsTextInput(node.node.nodeKind) || ![self.overlay accessibilityNodeIsFocused:node]) {
        return NSMakeRange(NSNotFound, 0);
    }
    return self.overlay.inputProxy.selectedRange;
}
- (void)accessibilitySetSelectedTextRange:(NSValue *)value {
    if (![value respondsToSelector:@selector(rangeValue)]) return;
    [self.overlay accessibilitySetSelectedTextRange:value.rangeValue forNode:[self currentNode]];
}
- (void)setAccessibilitySelectedTextRange:(NSRange)range {
    [self.overlay accessibilitySetSelectedTextRange:range forNode:[self currentNode]];
}
- (NSString *)accessibilitySelectedText {
    NSString *text = [self accessibilityValue];
    NSRange selection = [self accessibilitySelectedTextRange];
    if (!text || selection.location == NSNotFound || NSMaxRange(selection) > text.length) return @"";
    return [text substringWithRange:selection];
}
- (NSRange)accessibilityVisibleCharacterRange {
    NSString *text = [self accessibilityValue];
    return NSMakeRange(0, text.length);
}
- (NSInteger)accessibilityNumberOfCharacters { return [[self accessibilityValue] length]; }
- (BOOL)accessibilityPerformPress { return [self.overlay accessibilityPerformPressForNode:[self currentNode]]; }
- (void)accessibilityPerformAction:(NSAccessibilityActionName)action {
    if ([action isEqualToString:NSAccessibilityPressAction]) [self accessibilityPerformPress];
}
- (void)accessibilitySetValue:(id)value {
    [self.overlay accessibilitySetValue:value forNode:[self currentNode]];
}
// AppKit's NSAccessibility protocol calls setAccessibilityValue:, not the
// legacy-named helper above. The inherited NSAccessibilityElement setter
// merely stores an unrelated AX value and never reaches the accepted FIFO.
- (void)setAccessibilityValue:(id)value { [self accessibilitySetValue:value]; }
@end

// Resolve the CURRENT scene index of one node identity. The composition
// snapshot stores identity, never an index: a reconfigured scene may reorder
// nodes, and a stale index would silently address a different control.
static NSInteger CjguiIndexOfComposableNodeIdentity(CJGuiInternalComposableSceneOverlay *overlay,
                                                    uint64_t nodeId, int64_t resourceId,
                                                    uint32_t nodeKind) {
    if (!overlay || nodeId == 0) return NSNotFound;
    for (CJGuiInternalComposableSceneNode *node in overlay.nodes) {
        if (node.node.nodeId == nodeId && node.node.resourceId == resourceId &&
            node.node.nodeKind == nodeKind) {
            return node.index;
        }
    }
    return NSNotFound;
}

// Emit one phase of the composition this proxy currently tracks. Ranges are
// forwarded in the proxy's own UTF-16 coordinates; NSNotFound is converted
// explicitly (never through NSUInteger overflow). A missing node identity means
// the intent has no target left and must not be re-addressed by index.
static BOOL CjguiEmitProxyCompositionPhase(CJGuiInternalComposableInputProxy *proxy, uint32_t phase,
                                           NSString *text, NSRange inner, NSRange replacement,
                                           NSRange marked) {
    CJGuiInternalComposableSceneOverlay *overlay = proxy.composableOverlay;
    CJGuiInternalSession *session = overlay.session;
    if (!session) return NO;
    NSInteger nodeIndex = CjguiIndexOfComposableNodeIdentity(overlay, proxy.compositionSessionNodeId,
                                                             proxy.compositionSessionResourceId,
                                                             proxy.compositionSessionNodeKind);
    if (nodeIndex == NSNotFound || nodeIndex < 0) return NO;
    return CjguiEnqueueCompositionPhase(session, phase, (uint32_t)nodeIndex, text, inner,
        replacement.location == NSNotFound ? -1 : (int64_t)replacement.location,
        replacement.location == NSNotFound ? 0 : (int64_t)replacement.length,
        marked.location == NSNotFound ? -1 : (int64_t)marked.location,
        marked.location == NSNotFound ? 0 : (int64_t)marked.length,
        proxy.compositionSessionId, proxy.compositionSessionEpoch);
}

static BOOL CjguiAccessibilitySameText(NSString *left, NSString *right) {
    return left == right || (left != nil && right != nil && [left isEqualToString:right]);
}

// Opt-in scalar input observations, bounded per process. They never fetch an
// event, mutate a window/press, request a frame, or claim physical display time.
static void CjguiTraceWindowInputGeometry(CJGuiInternalSession *session, const char *phase, NSEvent *event) {
    if (!session || getenv("CJGUI_TRACE_POINTER_GEOMETRY") == NULL) return;
    static uint32_t count = 0, skippedCount = 0;
    if (strcmp(phase, "owner_skip") == 0) {
        if (skippedCount >= 64) return;
        skippedCount += 1;
    }
    if (count >= 512) return;
    count += 1;
    NSRect frame = session.window.frame;
    BOOL mouseEvent = event && (event.type == NSEventTypeLeftMouseDown || event.type == NSEventTypeLeftMouseUp ||
        event.type == NSEventTypeLeftMouseDragged || event.type == NSEventTypeMouseMoved ||
        event.type == NSEventTypeRightMouseDown || event.type == NSEventTypeRightMouseUp ||
        event.type == NSEventTypeRightMouseDragged || event.type == NSEventTypeOtherMouseDown ||
        event.type == NSEventTypeOtherMouseUp || event.type == NSEventTypeOtherMouseDragged);
    NSPoint point = mouseEvent ? event.locationInWindow : NSZeroPoint;
    NSPoint actualPoint = session.window.mouseLocationOutsideOfEventStream;
    NSPoint globalPoint = NSEvent.mouseLocation;
    NSString *runloopMode = NSRunLoop.currentRunLoop.currentMode;
    fprintf(stderr, "CJGUI_POINTER_GEOMETRY mono_ns=%llu sample=%u phase=%s session=%llu scene=%llu resize=%llu "
        "in_live=%d view_live=%d type=%lu pressed=%llu sequence=%llu pending=%lu "
        "point_window=%.3f,%.3f frame_cocoa=%.3f,%.3f,%.3f,%.3f "
        "event_window=%ld target_window=%ld event_number=%ld click_count=%ld pressure=%.3f "
        "buttons=%llu actual_window=%.3f,%.3f actual_global_cocoa=%.3f,%.3f runloop=%s\n",
        (unsigned long long)CjguiOwnerTraceNanoseconds(), count, phase, (unsigned long long)session.rendererSessionToken,
        (unsigned long long)session.composableSceneVersion, (unsigned long long)session.resizeVersion,
        session.window.inLiveResize ? 1 : 0, session.view.inLiveResize ? 1 : 0,
        (unsigned long)(event ? event.type : 0),
        (unsigned long long)session.composableSceneOverlay.pressedNodeId,
        (unsigned long long)session.composableSceneOverlay.pressedSequence,
        (unsigned long)session.pendingInteractions.count, point.x, point.y,
        frame.origin.x, frame.origin.y, frame.size.width, frame.size.height,
        (long)(event ? event.windowNumber : 0), (long)session.window.windowNumber,
        (long)(mouseEvent ? event.eventNumber : 0), (long)(mouseEvent ? event.clickCount : 0),
        mouseEvent ? event.pressure : 0.0, (unsigned long long)NSEvent.pressedMouseButtons,
        actualPoint.x, actualPoint.y, globalPoint.x, globalPoint.y,
        runloopMode ? runloopMode.UTF8String : "none");
}

static NSDictionary *CjguiCapturePrivateFields(id object, NSArray<NSString *> *keys);
static void CjguiRestorePrivateFields(id object, NSDictionary *values);
static NSArray<NSString *> *CjguiSourceProxyOverlayKeys(void);

enum { kCjguiSelectionTransferRetainedInputCapacity = 64,
       kCjguiSelectionTransferRetainedInputByteCapacity = 4 * 1024 * 1024 };

static NSInteger CjguiSelectionTransferFindNodeIndex(CJGuiInternalComposableSceneOverlay *overlay,
    uint64_t nodeId, uint64_t projectionVersion, int64_t resourceId, uint32_t nodeKind) {
    if (!overlay || !nodeId) return NSNotFound;
    for (CJGuiInternalComposableSceneNode *node in overlay.nodes) {
        if (node.node.nodeId == nodeId && node.node.projectionVersion == projectionVersion &&
            node.node.resourceId == resourceId && node.node.nodeKind == nodeKind) return (NSInteger)node.index;
    }
    return NSNotFound;
}

static BOOL CjguiSelectionTransferCellState(uint64_t session, uint64_t transferId,
    uint32_t *outState, uint8_t *outCancelled) {
    if (!session || session > kCjguiSessionCapacity || !transferId) return NO;
    CjguiSelectionTransferCell *cell = &gCjguiSelectionTransferCells[session - 1];
    CjguiLockSelectionTransferCell(cell);
    if (!CjguiSelectionTransferCellMatchesLocked(cell, session, transferId)) {
        CjguiUnlockSelectionTransferCell(cell);
        return NO;
    }
    uint64_t word = atomic_load_explicit(&cell->decision, memory_order_acquire);
    if (outState) *outState = CjguiSelectionTransferStateOf(word);
    if (outCancelled) *outCancelled = CjguiSelectionTransferCancelled(word);
    CjguiUnlockSelectionTransferCell(cell);
    return YES;
}

static CjguiInternalRendererStatus CjguiSelectionTransferBeginFinalizingWithPrecheck(
    uint64_t session, uint64_t transferId) {
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiSelectionTransferCapsule *capsule = ctx.selectionTransferCapsule;
        if (capsule) {
            CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
            if (capsule.transferId != transferId || ctx.selectionTransferId != transferId ||
                !overlay || capsule.overlay != overlay || capsule.proxy != overlay.inputProxy)
                return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
            if (!ctx.window || !CjguiInputProxyIsFirstResponder(overlay))
                return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
            if (overlay.inputProxy.hasMarkedText || overlay.compositionTerminalInFlight ||
                ctx.installedRangeReservation || ctx.claimedInstalledRangeIntent || ctx.pumpedInstalledRangeIntent ||
                ctx.installedRangeLocalTailSequence != ctx.installedRangeObservedAckSequence)
                return CJGUI_INTERNAL_RENDERER_PRESENT_PENDING;
            for (CJGuiInternalQueuedInteraction *queued in ctx.pendingInteractions) {
                if (CjguiQueuedCaretSuccessorOfInflight(ctx,queued)) continue;
                if (queued.nodeId == capsule.aNodeId && queued.resourceId == capsule.aResourceId &&
                    (queued.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_SELECTION_CHANGED ||
                     queued.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_CHANGED ||
                     queued.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_RANGE_CHANGED ||
                     queued.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_COMPOSITION ||
                     queued.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_NAVIGATE))
                    return CJGUI_INTERNAL_RENDERER_PRESENT_PENDING;
            }
        }
        // The cell transition is the total-order point against producer and
        // owner-writer admission. This runs on main so no already-enqueued
        // AppKit selection/range intent can slip between the FIFO proof and it.
        return CjguiSelectionTransferTransition(session, transferId,
            CJGUI_SELECTION_TRANSFER_PENDING, CJGUI_SELECTION_TRANSFER_FINALIZING, YES);
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_selection_transfer_capture_a(
    uint64_t session, const CjguiInternalSelectionTransferCandidate *candidate) {
    if (!candidate || !candidate->transferId || !candidate->sourceNodeId || !candidate->targetNodeId ||
        !candidate->sourceInstalledNonce || !candidate->sourceRendererSessionGeneration ||
        !candidate->sourceWindowInstanceToken || !candidate->sourceBindingEpoch ||
        !candidate->sourceProxyGeneration ||
        candidate->sourceOwnerVersion < 0 || candidate->sourceAcceptedVersion < candidate->sourceOwnerVersion ||
        candidate->sourceEndByte < candidate->sourceStartByte ||
        candidate->sourceSelectionEnd16 < candidate->sourceSelectionStart16 ||
        (!candidate->sourceBodyUtf8 && candidate->sourceBodyUtf8Length) ||
        (!candidate->targetBodyUtf8 && candidate->targetBodyUtf8Length) ||
        candidate->sourceBodyUtf8Length > CJGUI_INSTALLED_RANGE_BYTE_CAPACITY ||
        candidate->targetBodyUtf8Length > CJGUI_INSTALLED_RANGE_BYTE_CAPACITY)
        return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    NSData *sourceBytes = candidate->sourceBodyUtf8Length
        ? [NSData dataWithBytes:candidate->sourceBodyUtf8 length:candidate->sourceBodyUtf8Length] : [NSData data];
    NSData *targetBytes = candidate->targetBodyUtf8Length
        ? [NSData dataWithBytes:candidate->targetBodyUtf8 length:candidate->targetBodyUtf8Length] : [NSData data];
    NSString *sourceText = [[NSString alloc] initWithData:sourceBytes encoding:NSUTF8StringEncoding];
    NSString *targetText = [[NSString alloc] initWithData:targetBytes encoding:NSUTF8StringEncoding];
    if (!sourceText || !targetText || candidate->targetFocus16 > targetText.length ||
        candidate->targetAnchor16 > targetText.length) return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    CjguiInternalSelectionTransferCandidate frozen = *candidate;
    frozen.sourceBodyUtf8 = NULL;
    frozen.targetBodyUtf8 = NULL;
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
        CJGuiInternalComposableInputProxy *proxy = overlay.inputProxy;
        uint32_t state = CJGUI_SELECTION_TRANSFER_EMPTY;
        uint8_t cancelled = 0;
        if (!overlay || !proxy || !ctx.window || ctx.selectionTransferCapsule ||
            ctx.selectionTransferId != 0 ||
            !CjguiSelectionTransferCellState(session, frozen.transferId, &state, &cancelled) ||
            state != CJGUI_SELECTION_TRANSFER_PREPARING || cancelled ||
            ctx.composableSceneVersion != frozen.sourceSceneVersion ||
            overlay.activeNodeId != frozen.sourceNodeId ||
            overlay.activeProjectionVersion != frozen.sourceProjectionVersion ||
            overlay.activeNodeResourceId != frozen.sourceResourceId ||
            overlay.activeNodeKind != frozen.sourceNodeKind ||
            !CjguiInputProxyIsFirstResponder(overlay) || proxy.hasMarkedText || overlay.compositionTerminalInFlight ||
            CjguiSelectionTransferFindNodeIndex(overlay, frozen.sourceNodeId,
                frozen.sourceProjectionVersion, frozen.sourceResourceId, frozen.sourceNodeKind) == NSNotFound ||
            proxy.selectedRange.location != frozen.sourceSelectionStart16 ||
            NSMaxRange(proxy.selectedRange) != frozen.sourceSelectionEnd16)
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        CjguiInstalledRangeState *installedSource = ctx.installedRangeBasis;
        uint64_t actualAcceptedVersion = ctx.installedRangeObservedAckVersion >= 0
            ? (uint64_t)ctx.installedRangeObservedAckVersion
            : (uint64_t)(installedSource ? installedSource.candidate.ownerVersion : -1);
        if (!installedSource || !installedSource.active || installedSource.chainClosed ||
            installedSource.candidate.nonce != frozen.sourceInstalledNonce ||
            installedSource.candidate.rendererSessionGeneration != frozen.sourceRendererSessionGeneration ||
            installedSource.candidate.windowInstanceToken != frozen.sourceWindowInstanceToken ||
            installedSource.candidate.bindingEpoch != frozen.sourceBindingEpoch ||
            installedSource.candidate.contextEpoch != frozen.sourceContextEpoch ||
            installedSource.candidate.mirrorRevision != frozen.sourceMirrorRevision ||
            installedSource.candidate.ownerVersion != frozen.sourceOwnerVersion ||
            installedSource.candidate.sourceStartByte != frozen.sourceStartByte ||
            installedSource.candidate.sourceEndByte != frozen.sourceEndByte ||
            installedSource.proxyGeneration != frozen.sourceProxyGeneration ||
            ctx.installedRangeObservedAckSequence != frozen.sourceAcceptedSequence ||
            actualAcceptedVersion != (uint64_t)frozen.sourceAcceptedVersion ||
            overlay.installedRangeSelectionRevision != frozen.sourceSelectionRevision ||
            installedSource.proxy != proxy ||
            ![installedSource.sourceUtf8 isEqualToData:sourceBytes] ||
            !CjguiInstalledRangeBasisMatchesActual(ctx, overlay) || overlay.sourceInputParked ||
            ctx.installedRangeLocalTailSequence != ctx.installedRangeObservedAckSequence ||
            ctx.installedRangeReservation || ctx.claimedInstalledRangeIntent || ctx.pumpedInstalledRangeIntent ||
            ctx.composableSceneVersion != installedSource.candidate.installedSceneVersion ||
            frozen.sourceSceneVersion != installedSource.candidate.installedSceneVersion ||
            frozen.sourceProjectionVersion != overlay.activeProjectionVersion)
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        NSData *actual = [proxy.string dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
        if (!actual || ![actual isEqualToData:sourceBytes]) return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        CjguiSelectionTransferCapsule *capsule = [CjguiSelectionTransferCapsule new];
        capsule.transferId = frozen.transferId;
        capsule.overlay = overlay;
        capsule.window = ctx.window;
        capsule.proxy = proxy;
        capsule.firstResponder = ctx.window.firstResponder;
        capsule.aBody = [proxy.attributedString copy];
        capsule.aSelection = proxy.selectedRange;
        capsule.aNodeId = overlay.activeNodeId;
        capsule.aProjectionVersion = overlay.activeProjectionVersion;
        capsule.aResourceId = overlay.activeNodeResourceId;
        capsule.aNodeKind = overlay.activeNodeKind;
        capsule.aSceneVersion = ctx.composableSceneVersion;
        capsule.aInstalledRangeBasis = ctx.installedRangeBasis;
        capsule.aInstalledRangeProvisional = ctx.installedRangeProvisional;
        capsule.aInstalledRangeRecoveryBlock = ctx.installedRangeRecoveryBlock;
        capsule.aProxyGeneration = ctx.installedRangeProxyGeneration;
        capsule.aSelectionRevision = overlay.installedRangeSelectionRevision;
        capsule.aBytesUsed = ctx.installedRangeBytesUsed;
        capsule.aOverlayFields = CjguiCapturePrivateFields(overlay,CjguiSourceProxyOverlayKeys());
        capsule.aProxyFields = CjguiCapturePrivateFields(proxy,
            @[@"frame", @"minSize", @"maxSize", @"textContainerInset", @"font", @"textColor", @"typingAttributes",
              @"editable", @"selectable", @"verticallyResizable", @"horizontallyResizable", @"alphaValue"]);
        capsule.aContainerFields = CjguiCapturePrivateFields(proxy.textContainer,
            @[@"containerSize", @"maximumNumberOfLines", @"lineBreakMode", @"lineFragmentPadding",
              @"widthTracksTextView", @"heightTracksTextView"]);
        capsule.aScrollFields = CjguiCapturePrivateFields(overlay.inputScrollProxy,@[@"frame", @"alphaValue"]);
        capsule.aOffsets = [overlay.multilineScrollOffsets mutableCopy];
        capsule.aLayoutCache = [overlay.multilineLayoutCache mutableCopy];
        capsule.aLayoutOrder = [overlay.multilineLayoutCacheOrder mutableCopy];
        capsule.aNextSequence = ctx.installedRangeNextSequence;
        capsule.aLocalTailSequence = ctx.installedRangeLocalTailSequence;
        capsule.aObservedAckSequence = ctx.installedRangeObservedAckSequence;
        capsule.aObservedAckVersion = ctx.installedRangeObservedAckVersion;
        capsule.aOwnedTextSessionBindingEpoch = ctx.ownedTextSessionBindingEpoch;
        capsule.aOwnedTextSessionNodeId = ctx.ownedTextSessionNodeId;
        capsule.aOwnedTextSessionResourceId = ctx.ownedTextSessionResourceId;
        capsule.aOwnedTextSessionNodeKind = ctx.ownedTextSessionNodeKind;
        capsule.aSourceInputParked = overlay.sourceInputParked;
        capsule.aSourceHandoffInputBlocked = ctx.sourceHandoffInputBlocked;
        capsule.bNodeId = frozen.targetNodeId;
        capsule.bProjectionVersion = frozen.targetProjectionVersion;
        capsule.bResourceId = frozen.targetResourceId;
        capsule.bNodeKind = frozen.targetNodeKind;
        capsule.bSceneVersion = frozen.targetSceneVersion;
        capsule.bBody = [targetText copy];
        capsule.bSelection = NSMakeRange(MIN(frozen.targetAnchor16, frozen.targetFocus16),
            (NSUInteger)llabs((int64_t)frozen.targetFocus16 - (int64_t)frozen.targetAnchor16));
        capsule.retainedInputs = [NSMutableArray array];
        ctx.selectionTransferCapsule = capsule;
        ctx.selectionTransferId = frozen.transferId;
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}


static CjguiInternalRendererStatus CjguiCandidateFailure(CJGuiInternalSession *ctx,
    CjguiInternalRendererStatus status, const char *branch, uint64_t actual, uint64_t expected);

// Snapshot the ACTUAL current proxy. No Cangjie mirror bytes are substituted for
// AppKit A. The caller supplies only the owner version/context and accepted B.
// The bounded copied A body and scalar identity are returned in caller storage.
static CjguiInternalRendererStatus CjguiCaptureSelectionTransferCurrent(
    uint64_t session, CjguiInternalSelectionTransferCandidate *candidate,
    uint8_t *aBytes, uint32_t capacity, BOOL candidateScene,
    const CjguiInternalSelectionTransferReceipt *sourceReceipt,
    uint64_t targetContextEpoch, uint64_t targetMirrorRevision, int64_t ownerRevision, uint64_t gestureEpoch) {
    if (!candidate || !candidate->transferId || !aBytes || capacity < 65536u ||
        !candidate->sourceWindowInstanceToken || candidate->sourceOwnerVersion < 0 ||
        !candidate->targetBodyUtf8 || candidate->targetBodyUtf8Length > 65536u)
        return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    NSData *targetBytes=[NSData dataWithBytes:candidate->targetBodyUtf8 length:candidate->targetBodyUtf8Length];
    NSString *targetText=[[NSString alloc] initWithData:targetBytes encoding:NSUTF8StringEncoding];
    if (!targetText || candidate->targetAnchor16>targetText.length || candidate->targetFocus16>targetText.length)
        return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CJGuiInternalComposableSceneOverlay *overlay=ctx.composableSceneOverlay;
        CJGuiInternalComposableInputProxy *proxy=overlay.inputProxy;
        uint32_t state=0; uint8_t cancelled=0;
        // Scene identity and immutable COW payload identity are separate.
        // Resolve only within the exact accepted scene below, while retaining
        // resource/kind/body checks. Explicit projection requests stay strict.
        NSInteger targetIndex = NSNotFound;
        NSUInteger targetIdentityCount = 0;
        NSArray<CJGuiInternalComposableSceneNode *> *targets = candidateScene ? ctx.stagedComposableNodes : overlay.nodes;
        for (CJGuiInternalComposableSceneNode *node in targets) {
            if (node.node.nodeId != candidate->targetNodeId) continue;
            targetIdentityCount += 1;
            if (node.node.projectionVersion != 0 &&
                node.node.resourceId == candidate->targetResourceId &&
                node.node.nodeKind == candidate->targetNodeKind &&
                (!candidate->targetProjectionVersion ||
                 node.node.projectionVersion == candidate->targetProjectionVersion) &&
                [node.value isEqualToString:targetText]) {
                targetIndex = (NSInteger)node.index;
            }
        }
        if (targetIdentityCount != 1) targetIndex = NSNotFound;
        BOOL captureRejected = !overlay || !proxy || !ctx.window || ctx.selectionTransferCapsule || ctx.selectionTransferId ||
            !CjguiSelectionTransferCellState(session,candidate->transferId,&state,&cancelled) ||
            state!=CJGUI_SELECTION_TRANSFER_PREPARING || cancelled ||
            (candidateScene ? ctx.stagedComposableSceneVersion : ctx.composableSceneVersion)!=candidate->targetSceneVersion ||
            (candidateScene && (!sourceReceipt || !ctx.installedRangeBasis || !ctx.installedRangeBasis.hasReceipt ||
                ctx.selectionReceiptTransferId != sourceReceipt->transferId ||
                ctx.selectionReceiptSceneVersion != sourceReceipt->sceneVersion ||
                ctx.selectionReceiptBindingEpoch != sourceReceipt->bindingEpoch ||
                ctx.installedRangeBasis.candidate.nonce != sourceReceipt->transferId ||
                ctx.installedRangeProxyGeneration != sourceReceipt->proxyGeneration ||
                overlay.installedRangeSelectionRevision != sourceReceipt->selectionRevision ||
                overlay.activeNodeId != sourceReceipt->nodeId || overlay.activeNodeResourceId != sourceReceipt->resourceId ||
                overlay.activeNodeKind != sourceReceipt->nodeKind ||
                proxy.selectedRange.location != sourceReceipt->selectionStart16 ||
                NSMaxRange(proxy.selectedRange) != sourceReceipt->selectionEnd16 ||
                !CjguiInputProxyIsFirstResponder(overlay) || ctx.selectionReceiptOwnerRevision != ownerRevision ||
                ctx.selectionReceiptOwnerVersion != candidate->sourceOwnerVersion ||
                (gestureEpoch && (!overlay.pointerCaptureActive || overlay.pointerCaptureGestureEpoch != gestureEpoch)))) ||
            proxy.hasMarkedText ||
            overlay.compositionTerminalInFlight || ctx.installedRangeReservation ||
            ctx.claimedInstalledRangeIntent || ctx.pumpedInstalledRangeIntent ||
            ctx.installedRangeLocalTailSequence!=ctx.installedRangeObservedAckSequence ||
            targetIndex == NSNotFound;
        if (captureRejected) {
            // Diagnostic facts follow the actual candidate branch. A future B
            // is checked in staged nodes, while its receipt still proves A.
            // Keep this mask separate from the admission predicate above.
            uint64_t sourceMismatch = 0;
            if (candidateScene) {
                if (!sourceReceipt) sourceMismatch |= UINT64_C(1) << 0;
                if (!ctx.installedRangeBasis || !ctx.installedRangeBasis.hasReceipt)
                    sourceMismatch |= UINT64_C(1) << 1;
                if (sourceReceipt) {
                    if (ctx.selectionReceiptTransferId != sourceReceipt->transferId) sourceMismatch |= UINT64_C(1) << 2;
                    if (ctx.selectionReceiptSceneVersion != sourceReceipt->sceneVersion) sourceMismatch |= UINT64_C(1) << 3;
                    if (ctx.selectionReceiptBindingEpoch != sourceReceipt->bindingEpoch) sourceMismatch |= UINT64_C(1) << 4;
                    if (!ctx.installedRangeBasis || ctx.installedRangeBasis.candidate.nonce != sourceReceipt->transferId) sourceMismatch |= UINT64_C(1) << 5;
                    if (ctx.installedRangeProxyGeneration != sourceReceipt->proxyGeneration) sourceMismatch |= UINT64_C(1) << 6;
                    if (overlay.installedRangeSelectionRevision != sourceReceipt->selectionRevision) sourceMismatch |= UINT64_C(1) << 7;
                    if (overlay.activeNodeId != sourceReceipt->nodeId) sourceMismatch |= UINT64_C(1) << 8;
                    if (overlay.activeNodeResourceId != sourceReceipt->resourceId) sourceMismatch |= UINT64_C(1) << 9;
                    if (overlay.activeNodeKind != sourceReceipt->nodeKind) sourceMismatch |= UINT64_C(1) << 10;
                    if (!proxy || proxy.selectedRange.location != sourceReceipt->selectionStart16) sourceMismatch |= UINT64_C(1) << 11;
                    if (!proxy || NSMaxRange(proxy.selectedRange) != sourceReceipt->selectionEnd16) sourceMismatch |= UINT64_C(1) << 12;
                }
                if (!CjguiInputProxyIsFirstResponder(overlay)) sourceMismatch |= UINT64_C(1) << 13;
                if (ctx.selectionReceiptOwnerRevision != ownerRevision) sourceMismatch |= UINT64_C(1) << 14;
                if (ctx.selectionReceiptOwnerVersion != candidate->sourceOwnerVersion) sourceMismatch |= UINT64_C(1) << 15;
                if (gestureEpoch && (!overlay.pointerCaptureActive || overlay.pointerCaptureGestureEpoch != gestureEpoch))
                    sourceMismatch |= UINT64_C(1) << 16;
            }
            if (sourceMismatch) CjguiCandidateFailure(ctx, CJGUI_INTERNAL_RENDERER_SCENE_STALE,
                "candidate_capture_actual_source", sourceMismatch, 0);
            const char *trace = getenv("CJGUI_TRACE_IME_PUMP");
            if (trace && strcmp(trace, "1") == 0) {
                uint32_t traceState = 0;
                uint8_t traceCancelled = 0;
                BOOL traceCellMatches = CjguiSelectionTransferCellState(session,candidate->transferId,
                    &traceState,&traceCancelled);
                NSInteger exactIndex = targetIndex;
                NSInteger nodeIdIndex = NSNotFound;
                uint64_t actualProjection = 0;
                int64_t actualResource = 0;
                uint32_t actualKind = 0;
                if (overlay) {
                    for (CJGuiInternalComposableSceneNode *node in targets) {
                        if (node.node.nodeId == candidate->targetNodeId) {
                            nodeIdIndex = (NSInteger)node.index;
                            actualProjection = node.node.projectionVersion;
                            actualResource = node.node.resourceId;
                            actualKind = node.node.nodeKind;
                            break;
                        }
                    }
                }
                uint32_t rejectMask = 0;
                if (!overlay) rejectMask |= 1u << 0;
                if (!proxy) rejectMask |= 1u << 1;
                if (!ctx.window) rejectMask |= 1u << 2;
                if (ctx.selectionTransferCapsule) rejectMask |= 1u << 3;
                if (ctx.selectionTransferId) rejectMask |= 1u << 4;
                if (!traceCellMatches) rejectMask |= 1u << 5;
                if (traceState != CJGUI_SELECTION_TRANSFER_PREPARING) rejectMask |= 1u << 6;
                if (traceCancelled) rejectMask |= 1u << 7;
                if ((candidateScene ? ctx.stagedComposableSceneVersion : ctx.composableSceneVersion) !=
                    candidate->targetSceneVersion) rejectMask |= 1u << 8;
                if (proxy.hasMarkedText) rejectMask |= 1u << 9;
                if (overlay.compositionTerminalInFlight) rejectMask |= 1u << 10;
                if (ctx.installedRangeReservation) rejectMask |= 1u << 11;
                if (ctx.claimedInstalledRangeIntent) rejectMask |= 1u << 12;
                if (ctx.pumpedInstalledRangeIntent) rejectMask |= 1u << 13;
                if (ctx.installedRangeLocalTailSequence != ctx.installedRangeObservedAckSequence)
                    rejectMask |= 1u << 14;
                if (exactIndex == NSNotFound) rejectMask |= 1u << 15;
                fprintf(stderr, "CJGUI_SELECTION_TRANSFER_CAPTURE_GUARD session=%llu transfer=%llu reject_mask=0x%08x source_mismatch=0x%llx candidate_scene=%d scene=%llu target_scene=%llu target_projection=%llu exact_index=%ld node_id_index=%ld actual_projection=%llu actual_resource=%lld actual_kind=%u active_node=%llu active_projection=%llu active_resource=%lld active_kind=%u cell_match=%d cell_state=%u cancelled=%u marked=%d capsule=%d transfer_active=%d reservation=%d claimed=%d pumped=%d tail=%llu ack=%llu\n",
                    (unsigned long long)session, (unsigned long long)candidate->transferId,
                    rejectMask, (unsigned long long)sourceMismatch, candidateScene,
                    (unsigned long long)ctx.composableSceneVersion,
                    (unsigned long long)candidate->targetSceneVersion,
                    (unsigned long long)candidate->targetProjectionVersion,
                    (long)exactIndex, (long)nodeIdIndex, (unsigned long long)actualProjection,
                    (long long)actualResource, actualKind,
                    (unsigned long long)overlay.activeNodeId,
                    (unsigned long long)overlay.activeProjectionVersion,
                    (long long)overlay.activeNodeResourceId, overlay.activeNodeKind,
                    traceCellMatches, traceState, traceCancelled, proxy.hasMarkedText,
                    ctx.selectionTransferCapsule != nil, ctx.selectionTransferId != 0,
                    ctx.installedRangeReservation != nil, ctx.claimedInstalledRangeIntent != nil,
                    ctx.pumpedInstalledRangeIntent != nil,
                    (unsigned long long)ctx.installedRangeLocalTailSequence,
                    (unsigned long long)ctx.installedRangeObservedAckSequence);
            }
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        }
        NSData *sourceBytes=[proxy.string dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
        if (!sourceBytes || sourceBytes.length>65536u || proxy.selectedRange.location==NSNotFound ||
            NSMaxRange(proxy.selectedRange)>proxy.string.length ||
            ctx.installedRangeBytesUsed+ctx.installedRangeBytesReserved+targetBytes.length>
                CJGUI_INSTALLED_RANGE_BYTE_CAPACITY) return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
        CjguiInternalSelectionTransferCandidate frozen=*candidate;
        if (candidateScene && [ctx.composableNodes containsObject:targets[targetIndex]]) {
            CJGuiInternalComposableSceneNode *copy = CjguiCloneComposableSceneNode(ctx, targets[targetIndex],
                (uint32_t)targetIndex, ctx.stagedComposableSceneVersion);
            if (!copy) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
            ctx.stagedComposableNodes[targetIndex] = copy;
            targets = ctx.stagedComposableNodes;
        }
        frozen.targetProjectionVersion = targets[targetIndex].node.projectionVersion;
        CjguiInstalledRangeState *old=ctx.installedRangeBasis;
        if (candidateScene) {
            frozen.sourceContextEpoch = old.candidate.contextEpoch;
            frozen.sourceMirrorRevision = old.candidate.mirrorRevision;
        }
        BOOL sourceBasis=CjguiInstalledRangeBasisMatchesActual(ctx,overlay) &&
            old.sourceUtf8 && [old.sourceUtf8 isEqualToData:sourceBytes];
        frozen.sourceInstalledNonce=sourceBasis?old.candidate.nonce:frozen.transferId;
        frozen.sourceRendererSessionGeneration=ctx.sessionGeneration;
        frozen.sourceBindingEpoch=ctx.ownedTextSessionBindingEpoch;
        frozen.sourceAcceptedSequence=ctx.installedRangeObservedAckSequence;
        frozen.sourceAcceptedVersion=frozen.sourceOwnerVersion;
        // For a presentation A, these are proxy byte extent evidence ONLY.
        frozen.sourceStartByte=sourceBasis?old.candidate.sourceStartByte:0;
        frozen.sourceEndByte=sourceBasis?old.candidate.sourceEndByte:sourceBytes.length;
        frozen.sourceProxyGeneration=ctx.installedRangeProxyGeneration;
        frozen.sourceSelectionRevision=overlay.installedRangeSelectionRevision;
        frozen.sourceNodeId=overlay.activeNodeId; frozen.sourceResourceId=overlay.activeNodeResourceId;
        frozen.sourceProjectionVersion=overlay.activeProjectionVersion;
        frozen.sourceNodeKind=overlay.activeNodeKind; frozen.sourceSceneVersion=ctx.composableSceneVersion;
        frozen.sourceSelectionStart16=(uint32_t)proxy.selectedRange.location;
        frozen.sourceSelectionEnd16=(uint32_t)NSMaxRange(proxy.selectedRange);
        frozen.sourceBodyUtf8Length=(uint32_t)sourceBytes.length;
        frozen.sourceBodyUtf8=NULL; frozen.targetBodyUtf8=NULL;
        CjguiSelectionTransferCapsule *capsule = [CjguiSelectionTransferCapsule new];
        capsule.transferId = frozen.transferId;
        capsule.overlay = overlay;
        capsule.window = ctx.window;
        capsule.proxy = proxy;
        capsule.firstResponder = ctx.window.firstResponder;
        capsule.aBody = [proxy.attributedString copy];
        capsule.aSelection = proxy.selectedRange;
        capsule.aNodeId = overlay.activeNodeId;
        capsule.aProjectionVersion = overlay.activeProjectionVersion;
        capsule.aResourceId = overlay.activeNodeResourceId;
        capsule.aNodeKind = overlay.activeNodeKind;
        capsule.aSceneVersion = ctx.composableSceneVersion;
        capsule.aInstalledRangeBasis = ctx.installedRangeBasis;
        capsule.aInstalledRangeProvisional = ctx.installedRangeProvisional;
        capsule.aInstalledRangeRecoveryBlock = ctx.installedRangeRecoveryBlock;
        capsule.aProxyGeneration = ctx.installedRangeProxyGeneration;
        capsule.aSelectionRevision = overlay.installedRangeSelectionRevision;
        capsule.aBytesUsed = ctx.installedRangeBytesUsed;
        capsule.aOverlayFields = CjguiCapturePrivateFields(overlay,CjguiSourceProxyOverlayKeys());
        capsule.aProxyFields = CjguiCapturePrivateFields(proxy,
            @[@"frame", @"minSize", @"maxSize", @"textContainerInset", @"font", @"textColor", @"typingAttributes",
              @"editable", @"selectable", @"verticallyResizable", @"horizontallyResizable", @"alphaValue"]);
        capsule.aContainerFields = CjguiCapturePrivateFields(proxy.textContainer,
            @[@"containerSize", @"maximumNumberOfLines", @"lineBreakMode", @"lineFragmentPadding",
              @"widthTracksTextView", @"heightTracksTextView"]);
        capsule.aScrollFields = CjguiCapturePrivateFields(overlay.inputScrollProxy,@[@"frame", @"alphaValue"]);
        capsule.aOffsets = [overlay.multilineScrollOffsets mutableCopy];
        capsule.aLayoutCache = [overlay.multilineLayoutCache mutableCopy];
        capsule.aLayoutOrder = [overlay.multilineLayoutCacheOrder mutableCopy];
        capsule.aNextSequence = ctx.installedRangeNextSequence;
        capsule.aLocalTailSequence = ctx.installedRangeLocalTailSequence;
        capsule.aObservedAckSequence = ctx.installedRangeObservedAckSequence;
        capsule.aObservedAckVersion = ctx.installedRangeObservedAckVersion;
        capsule.aOwnedTextSessionBindingEpoch = ctx.ownedTextSessionBindingEpoch;
        capsule.aOwnedTextSessionNodeId = ctx.ownedTextSessionNodeId;
        capsule.aOwnedTextSessionResourceId = ctx.ownedTextSessionResourceId;
        capsule.aOwnedTextSessionNodeKind = ctx.ownedTextSessionNodeKind;
        capsule.aSourceInputParked = overlay.sourceInputParked;
        capsule.aSourceHandoffInputBlocked = ctx.sourceHandoffInputBlocked;
        capsule.bNodeId = frozen.targetNodeId;
        capsule.bProjectionVersion = frozen.targetProjectionVersion;
        capsule.bResourceId = frozen.targetResourceId;
        capsule.bNodeKind = frozen.targetNodeKind;
        capsule.bSceneVersion = frozen.targetSceneVersion;
        capsule.bBody = [targetText copy];
        capsule.bSelection = NSMakeRange(MIN(frozen.targetAnchor16, frozen.targetFocus16),
            (NSUInteger)llabs((int64_t)frozen.targetFocus16 - (int64_t)frozen.targetAnchor16));
        capsule.retainedInputs = [NSMutableArray array];

        // Reserve the complete B input basis before entering Finalizing. It is
        // private proxy provenance: flag 2 forces the directed owner-choice route.
        CjguiInstalledRangeState *basis=[CjguiInstalledRangeState new];
        if (!basis) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        CjguiInternalInstalledRangeCandidate b={0};
        b.nonce=frozen.transferId; b.rendererSessionGeneration=ctx.sessionGeneration;
        b.windowInstanceToken=frozen.sourceWindowInstanceToken;
        b.bindingEpoch=ctx.ownedTextSessionBindingEpoch+1;
        if (!b.bindingEpoch) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        b.contextEpoch=frozen.sourceContextEpoch; b.mirrorRevision=frozen.sourceMirrorRevision;
        b.ownerVersion=frozen.sourceOwnerVersion; b.installedSceneVersion=frozen.targetSceneVersion;
        b.nodeId=frozen.targetNodeId; b.resourceId=frozen.targetResourceId;
        b.sourceStartByte=0; b.sourceEndByte=targetBytes.length;
        basis.candidate=b; basis.sourceUtf8=targetBytes;
        basis.selectionTransferId=frozen.transferId; basis.proxyNodeKind=frozen.targetNodeKind;
        capsule.bInputBasis=basis; capsule.bBindingEpoch=b.bindingEpoch;
        if (candidateScene) {
            capsule.candidateSceneTransfer = YES; capsule.ownerSelectionRevision = ownerRevision;
            capsule.sourceGestureEpoch = gestureEpoch;
            b.contextEpoch = targetContextEpoch; b.mirrorRevision = targetMirrorRevision;
            basis.candidate = b;
        }
        ctx.selectionTransferCapsule=capsule; ctx.selectionTransferId=frozen.transferId;
        if (sourceBytes.length) memcpy(aBytes,sourceBytes.bytes,sourceBytes.length);
        *candidate=frozen;
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_selection_transfer_capture_current(
    uint64_t session, CjguiInternalSelectionTransferCandidate *candidate, uint8_t *aBytes, uint32_t capacity) {
    return CjguiCaptureSelectionTransferCurrent(session, candidate, aBytes, capacity, NO, NULL, 0, 0, -1, 0);
}
CjguiInternalRendererStatus cjgui_internal_renderer_capture_candidate_selection(uint64_t session,
    CjguiInternalSelectionTransferCandidate *candidate, const CjguiInternalSelectionTransferReceipt *sourceReceipt,
    uint8_t *aBytes, uint32_t capacity, uint64_t targetContextEpoch, uint64_t targetMirrorRevision,
    int64_t ownerRevision, uint64_t gestureEpoch) {
    if (!sourceReceipt || !sourceReceipt->transferId || !targetContextEpoch || !targetMirrorRevision || ownerRevision < 0)
        return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    return CjguiCaptureSelectionTransferCurrent(session, candidate, aBytes, capacity, YES, sourceReceipt,
        targetContextEpoch, targetMirrorRevision, ownerRevision, gestureEpoch);
}

static BOOL CjguiCandidateSelectionActualSourceReadbackMatches(CJGuiInternalSession *ctx, CjguiSelectionTransferCapsule *c) {
    CJGuiInternalComposableSceneOverlay *o=ctx.composableSceneOverlay;
    return c && c.candidateSceneTransfer && !ctx.destroyed && c.overlay==o && c.window==ctx.window &&
        c.proxy==o.inputProxy && CjguiInputProxyIsFirstResponder(o) && !o.inputProxy.hasMarkedText &&
        !o.compositionTerminalInFlight && [c.proxy.textStorage isEqualToAttributedString:c.aBody] &&
        NSEqualRanges(c.proxy.selectedRange,c.aSelection) && ctx.installedRangeBasis==c.aInstalledRangeBasis &&
        ctx.installedRangeProxyGeneration==c.aProxyGeneration && o.installedRangeSelectionRevision==c.aSelectionRevision &&
        ctx.ownedTextSessionBindingEpoch==c.aOwnedTextSessionBindingEpoch &&
        ctx.selectionReceiptOwnerVersion==c.bInputBasis.candidate.ownerVersion &&
        ctx.selectionReceiptOwnerRevision==c.ownerSelectionRevision &&
        (!c.sourceGestureEpoch || (o.pointerCaptureActive && o.pointerCaptureGestureEpoch==c.sourceGestureEpoch));
}

static BOOL CjguiCandidateSelectionSourceReadbackMatches(CJGuiInternalSession *ctx, CjguiSelectionTransferCapsule *c) {
    uint32_t state=CJGUI_SELECTION_TRANSFER_EMPTY; uint8_t cancelled=0;
    return CjguiCandidateSelectionActualSourceReadbackMatches(ctx,c) &&
        CjguiSelectionTransferCellState(ctx.rendererSessionToken,c.transferId,&state,&cancelled) &&
        state==CJGUI_SELECTION_TRANSFER_PENDING && !cancelled;
}

// GPU preparation can call platform objects after Finalizing was acquired.
// A real reentrant input keeps its original A payload and cancels the proposal.
// Test that decision again before submission; an uncommitted buffer is safely
// discarded and the existing abort path consumes that input on A once.
static BOOL CjguiCandidateSelectionMaySubmitFrame(CJGuiInternalSession *ctx) {
    CjguiSelectionTransferCapsule *c=ctx.selectionTransferCapsule;
    if (!c.candidateSceneTransfer || ctx.selectionPaintPublishingScene!=c.bSceneVersion) return YES;
    uint32_t state=CJGUI_SELECTION_TRANSFER_EMPTY; uint8_t cancelled=0;
    return CjguiCandidateSelectionActualSourceReadbackMatches(ctx,c) &&
        CjguiSelectionTransferCellState(ctx.rendererSessionToken,c.transferId,&state,&cancelled) &&
        state==CJGUI_SELECTION_TRANSFER_FINALIZING && !cancelled && c.retainedInputs.count==0;
}

static BOOL CjguiSelectionTransferSourceSceneMatches(CJGuiInternalSession *ctx, CjguiSelectionTransferCapsule *c) {
    return c.candidateSceneTransfer
        ? ctx.composableSceneVersion == c.aSceneVersion && ctx.stagedComposableSceneVersion == c.bSceneVersion
        : ctx.composableSceneVersion == c.bSceneVersion;
}
static CJGuiInternalComposableSceneNode *CjguiSelectionTransferTargetNode(CJGuiInternalSession *ctx,
    CjguiSelectionTransferCapsule *c) {
    NSArray<CJGuiInternalComposableSceneNode *> *nodes = c.candidateSceneTransfer ? ctx.stagedComposableNodes : c.overlay.nodes;
    if (!c || !CjguiSelectionTransferSourceSceneMatches(ctx, c)) return nil;
    CJGuiInternalComposableSceneNode *found = nil;
    for (CJGuiInternalComposableSceneNode *node in nodes) {
        if (node.node.nodeId != c.bNodeId) continue;
        if (found || node.node.projectionVersion != c.bProjectionVersion || node.node.resourceId != c.bResourceId ||
            node.node.nodeKind != c.bNodeKind || ![node.value isEqualToString:c.bBody]) return nil;
        found = node;
    }
    return found;
}

CjguiInternalRendererStatus cjgui_internal_renderer_selection_transfer_verify_b(
    uint64_t session, uint64_t transferId, CjguiInternalSelectionTransferReceipt *outReceipt) {
    if (outReceipt) *outReceipt = (CjguiInternalSelectionTransferReceipt){0};
    if (!outReceipt || !transferId) return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiSelectionTransferCapsule *capsule = ctx.selectionTransferCapsule;
        CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
        CJGuiInternalComposableInputProxy *proxy = overlay.inputProxy;
        uint32_t state = CJGUI_SELECTION_TRANSFER_EMPTY;
        if (!capsule || capsule.transferId != transferId || ctx.selectionTransferId != transferId ||
            !proxy || capsule.overlay != overlay || capsule.window != ctx.window ||
            !CjguiSelectionTransferCellState(session, transferId, &state, NULL) ||
            (state != CJGUI_SELECTION_TRANSFER_FINALIZING && state != CJGUI_SELECTION_TRANSFER_PENDING) ||
            ctx.composableSceneVersion != capsule.bSceneVersion ||
            overlay.activeNodeId != capsule.bNodeId || overlay.activeProjectionVersion != capsule.bProjectionVersion ||
            overlay.activeNodeResourceId != capsule.bResourceId || overlay.activeNodeKind != capsule.bNodeKind ||
            CjguiSelectionTransferFindNodeIndex(overlay, capsule.bNodeId, capsule.bProjectionVersion,
                capsule.bResourceId, capsule.bNodeKind) == NSNotFound ||
            !CjguiInputProxyIsFirstResponder(overlay) || proxy.hasMarkedText || overlay.compositionTerminalInFlight)
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        NSData *actual = [proxy.string dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
        NSData *expected = [capsule.bBody dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
        NSRange selected = proxy.selectedRange;
        if (!actual || !expected || ![actual isEqualToData:expected] ||
            selected.location != capsule.bSelection.location || NSMaxRange(selected) != NSMaxRange(capsule.bSelection))
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        outReceipt->transferId = transferId;
        outReceipt->sceneVersion = ctx.composableSceneVersion;
        outReceipt->bindingEpoch = ctx.ownedTextSessionBindingEpoch;
        outReceipt->nodeId = overlay.activeNodeId;
        outReceipt->projectionVersion = overlay.activeProjectionVersion;
        outReceipt->resourceId = overlay.activeNodeResourceId;
        outReceipt->nodeKind = overlay.activeNodeKind;
        outReceipt->selectionStart16 = (uint32_t)selected.location;
        outReceipt->selectionEnd16 = (uint32_t)NSMaxRange(selected);
        outReceipt->selectionRevision = overlay.installedRangeSelectionRevision;
        outReceipt->proxyGeneration = CjguiInstalledRangeBasisMatchesActual(ctx, overlay)
            ? ctx.installedRangeProxyGeneration : 0;
        outReceipt->firstResponder = CjguiInputProxyIsFirstResponder(overlay) ? 1u : 0u;
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

// This older record proves the local input proxy only. In particular an
// offscreen proxy says nothing about cross-fragment declared backgrounds.
static void CjguiTraceSelectionDrawEncodedIfMatching(CJGuiInternalSession *ctx,
    CJGuiInternalMetalView *view, uint64_t frameIndex) {
    if (!ctx || !view || !CjguiOwnerPhaseTraceEnabled() || !ctx.selectionTraceTransferId ||
        ctx.selectionTraceDrawEncoded || ctx.sessionGeneration != ctx.selectionTraceSessionGeneration ||
        ctx.composableSceneVersion != ctx.selectionTraceSceneVersion ||
        ctx.ownedTextSessionBindingEpoch != ctx.selectionTraceBindingEpoch ||
        ctx.installedRangeProxyGeneration != ctx.selectionTraceProxyGeneration) return;
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    CjguiInstalledRangeState *basis = ctx.installedRangeBasis;
    if (!overlay || !basis || overlay.installedRangeSelectionRevision != ctx.selectionTraceSelectionRevision ||
        !CjguiInstalledRangeBasisMatchesActual(ctx, overlay) || !overlay.inputProxy) return;
    NSRange actualSelection = overlay.inputProxy.selectedRange;
    if (actualSelection.location != ctx.selectionTraceStart16 ||
        NSMaxRange(actualSelection) != ctx.selectionTraceEnd16) return;

    CJGuiInternalComposableSceneNode *matched = nil;
    for (CJGuiInternalComposableSceneNode *candidate in view.composableNodes) {
        CjguiInternalRendererComposableNode raw = candidate.node;
        if (raw.nodeId == ctx.selectionTraceNodeId && raw.resourceId == ctx.selectionTraceResourceId &&
            raw.projectionVersion == ctx.selectionTraceProjectionVersion) {
            matched = candidate;
            break;
        }
    }
    if (!matched || matched.node.projectionVersion != ctx.composableSceneVersion) return;
    NSString *value = matched.value ?: @"";
    const char *valueUtf8 = value.UTF8String;
    NSUInteger valueLength = [value lengthOfBytesUsingEncoding:NSUTF8StringEncoding];
    if (valueLength != basis.sourceUtf8.length ||
        (valueLength && (!valueUtf8 || memcmp(valueUtf8, basis.sourceUtf8.bytes, valueLength) != 0))) return;

    NSRect selectionBounds = NSZeroRect;
    NSArray<NSValue *> *selectionRects = CjguiEffectiveTransferTextSelectionRects(ctx, matched);
    for (NSValue *valueRect in selectionRects) {
        NSRect rect = valueRect.rectValue;
        if (NSIsEmptyRect(rect)) continue;
        selectionBounds = NSIsEmptyRect(selectionBounds) ? rect : NSUnionRect(selectionBounds, rect);
    }
    NSRect caret = CjguiEffectiveTransferTextCaretRect(ctx, matched);
    uint64_t transferId = ctx.selectionTraceTransferId;
    uint64_t ownerTurn = ctx.selectionTraceOwnerTurn;
    uint64_t sceneVersion = ctx.selectionTraceSceneVersion;
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_DRAW_ENCODED, frameIndex);
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_FRAME_INDEX, frameIndex);
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_DRAW_OWNER_TURN,
        atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn, memory_order_acquire));
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_BINDING_EPOCH, ctx.selectionTraceBindingEpoch);
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_NODE_ID, ctx.selectionTraceNodeId);
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_RESOURCE_ID, (uint64_t)ctx.selectionTraceResourceId);
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_PROJECTION_VERSION, ctx.selectionTraceProjectionVersion);
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_PROXY_GENERATION, ctx.selectionTraceProxyGeneration);
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_REVISION, ctx.selectionTraceSelectionRevision);
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_START16, ctx.selectionTraceStart16);
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_END16, ctx.selectionTraceEnd16);
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_RANGE_RECT_COUNT, selectionRects.count);
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_RANGE_RECT_X_MILLI, CjguiSelectionTraceMilliPoints(NSMinX(selectionBounds)));
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_RANGE_RECT_Y_MILLI, CjguiSelectionTraceMilliPoints(NSMinY(selectionBounds)));
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_RANGE_RECT_WIDTH_MILLI, CjguiSelectionTraceMilliPoints(NSWidth(selectionBounds)));
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_RANGE_RECT_HEIGHT_MILLI, CjguiSelectionTraceMilliPoints(NSHeight(selectionBounds)));
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_CARET_RECT_X_MILLI, CjguiSelectionTraceMilliPoints(NSMinX(caret)));
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_CARET_RECT_Y_MILLI, CjguiSelectionTraceMilliPoints(NSMinY(caret)));
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_CARET_RECT_WIDTH_MILLI, CjguiSelectionTraceMilliPoints(NSWidth(caret)));
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_CARET_RECT_HEIGHT_MILLI, CjguiSelectionTraceMilliPoints(NSHeight(caret)));
    CjguiTraceSelectionTransferScalar(ctx, transferId, ownerTurn, sceneVersion,
        CJGUI_OWNER_PHASE_SELECTION_CARET_HIDDEN, matched.textCaretHidden ? 1u : 0u);
    ctx.selectionTraceDrawEncoded = YES;
}

typedef struct {
    BOOL available;
    BOOL empty;
    const char *reason;
    NSRect textRect;
    NSRect clip;
    NSUInteger utf8Start;
    NSUInteger utf8End;
} CjguiAcceptedTextVisibility;

static BOOL CjguiAcceptedTextVisibilityUtf8Offset(NSString *body, NSUInteger utf16Offset,
                                                  NSUInteger *outUtf8Offset) {
    if (!body || !outUtf8Offset || utf16Offset > body.length) return NO;
    NSUInteger index = 0;
    NSUInteger bytes = 0;
    while (index < utf16Offset) {
        unichar first = [body characterAtIndex:index];
        if (first >= 0xD800 && first <= 0xDBFF) {
            if (index + 1 >= body.length || index + 1 >= utf16Offset) return NO;
            unichar second = [body characterAtIndex:index + 1];
            if (second < 0xDC00 || second > 0xDFFF) return NO;
            bytes += 4;
            index += 2;
            continue;
        }
        if (first >= 0xDC00 && first <= 0xDFFF) return NO;
        bytes += first <= 0x7F ? 1 : (first <= 0x7FF ? 2 : 3);
        index++;
    }
    *outUtf8Offset = bytes;
    return YES;
}

static BOOL CjguiAcceptedTextVisibilityExtentMemoMatches(
    CJGuiInternalComposableSceneNode *node, NSString *body) {
    if (!node || !body || !node.textMeasureValid ||
        ![node.textMeasuredSource isEqualToString:body]) return NO;
    CGFloat verticalInset = CjguiComposableNodeUsesLabelTextInset(node.node.nodeKind) ? 2.0 : 6.0;
    NSRect drawRect = NSInsetRect(NSMakeRect(0.0, 0.0,
        MAX(0.0, (CGFloat)node.node.width), MAX(0.0, (CGFloat)node.node.height)),
        7.0, verticalInset);
    return node.textMeasuredWidth == NSWidth(drawRect) &&
        node.textMeasuredFontSize == node.node.fontSize &&
        node.textMeasuredFontWeight == node.node.fontWeight &&
        node.textMeasuredFontFamily == node.node.fontFamily &&
        node.textMeasuredNodeKind == node.node.nodeKind;
}

// Read only the already accepted TextKit graph. The no-additional-layout query
// is important here: diagnostics must never prepare glyphs or change the paint
// candidate whose visibility they describe.
static CjguiAcceptedTextVisibility CjguiAcceptedTextVisibilityForNode(
    CJGuiInternalComposableSceneNode *node, NSRect viewBounds) {
    CjguiAcceptedTextVisibility result = {0};
    result.reason = "missing_node";
    if (!node) return result;
    result.clip = NSIntersectionRect(CjguiComposableVisualClipBounds(node), viewBounds);
    result.reason = "missing_node_value";
    if (!node.value) return result;
    NSString *body = node.value;
    // An accepted candidate whose actual GPU coverage is empty needs no glyph
    // graph to prove visibility. Require its current intrinsic extent memo to
    // match the exact body and style first, so this geometry query can reuse
    // the existing memo without measuring or laying out anything.
    BOOL noPaintedResources = !node.textTexture && node.textTileTextures.count == 0 &&
        node.textTileRects.count == 0 && node.textTextureByteCount == 0;
    if (noPaintedResources && CjguiAcceptedTextVisibilityExtentMemoMatches(node, body) &&
        NSIsEmptyRect(CjguiComposableTextTextureRectForNodeWithText(node, body))) {
        NSRect currentLayoutBounds = NSOffsetRect(CjguiComposableTextNodeLayoutRect(node),
            (CGFloat)node.geometry.translateX, (CGFloat)node.geometry.translateY);
        CGFloat verticalInset = CjguiComposableNodeUsesLabelTextInset(node.node.nodeKind) ? 2.0 : 6.0;
        result.textRect = NSInsetRect(currentLayoutBounds, 7.0, verticalInset);
        if (!isfinite(NSMinX(result.textRect)) || !isfinite(NSMinY(result.textRect)) ||
            !isfinite(NSWidth(result.textRect)) || !isfinite(NSHeight(result.textRect)) ||
            !isfinite(NSMinX(result.clip)) || !isfinite(NSMinY(result.clip)) ||
            !isfinite(NSWidth(result.clip)) || !isfinite(NSHeight(result.clip))) {
            result.reason = "invalid_text_geometry";
            return result;
        }
        result.available = YES;
        result.empty = YES;
        result.reason = "empty_gpu_coverage";
        return result;
    }
    CjguiPreparedTextNodeLayout *prepared = node.textVisibilityRasterLayout ?: node.preparedTextLayout;
    result.reason = "missing_painted_layout";
    if ((node.textTexture || node.textTileTextures.count > 0) && !node.textVisibilityRasterLayout)
        return result;
    result.reason = "missing_prepared_layout";
    if (!prepared || !prepared.storage || !prepared.layoutManager || !prepared.container) return result;

    NSRect nodeRect = CjguiComposableVisualNodeRect(node);
    result.textRect = NSOffsetRect(prepared.textRect, NSMinX(nodeRect), NSMinY(nodeRect));
    result.reason = "prepared_body_mismatch";
    if (![prepared.storage.string isEqualToString:body] ||
        prepared.layoutManager.textStorage != prepared.storage ||
        ![prepared.layoutManager.textContainers containsObject:prepared.container]) return result;

    // Empty accepted text has no glyph visibility to query, but its exact body
    // identity and prepared graph are still required.
    if (body.length == 0) {
        result.available = YES;
        result.empty = YES;
        result.reason = "none";
        return result;
    }
    result.reason = "layout_incomplete";
    NSUInteger firstUnlaid = prepared.layoutManager.firstUnlaidCharacterIndex;
    // A clipped multiline tile legitimately paints only a laid prefix. The
    // retained raster graph proves that paint; the editable lazy graph does
    // not. Query only glyphs already laid by that actual raster operation.
    if (firstUnlaid < body.length && !node.textVisibilityRasterLayout) return result;

    result.reason = "invalid_text_geometry";
    if (!isfinite(NSMinX(result.textRect)) || !isfinite(NSMinY(result.textRect)) ||
        !isfinite(NSWidth(result.textRect)) || !isfinite(NSHeight(result.textRect)) ||
        !isfinite(NSMinX(result.clip)) || !isfinite(NSMinY(result.clip)) ||
        !isfinite(NSWidth(result.clip)) || !isfinite(NSHeight(result.clip))) return result;

    result.available = YES;
    result.reason = "none";
    NSRect visible = NSIntersectionRect(result.textRect, result.clip);
    if (NSIsEmptyRect(visible)) {
        result.empty = YES;
        return result;
    }
    BOOL checkPaintedCoverage = node.textVisibilityRasterLayout &&
        (node.textTexture || node.textTileTextures.count > 0);
    NSRect paintedCoverage = NSZeroRect;
    if (checkPaintedCoverage) {
        paintedCoverage = NSOffsetRect(node.textTextureRect,
            NSMinX(nodeRect) - node.textTileLayoutOrigin.x,
            NSMinY(nodeRect) - node.textTileLayoutOrigin.y);
    }
    NSRect visibleLocal = NSOffsetRect(visible, -NSMinX(result.textRect), -NSMinY(result.textRect));
    if (!isfinite(prepared.sourceScroll) || prepared.sourceScroll < 0.0) {
        result.available = NO;
        result.reason = "invalid_raster_scroll";
        return result;
    }
    visibleLocal.origin.y += prepared.sourceScroll;
    NSLayoutManager *layout = prepared.layoutManager;
    NSUInteger glyphCount = firstUnlaid < body.length
        ? layout.firstUnlaidGlyphIndex : layout.numberOfGlyphs;
    NSRange glyphs = [layout glyphRangeForBoundingRectWithoutAdditionalLayout:visibleLocal
                                                              inTextContainer:prepared.container];
    if (glyphs.location == NSNotFound || glyphs.location > glyphCount ||
        glyphs.length > glyphCount - glyphs.location) {
        result.available = NO;
        result.reason = "invalid_glyph_range";
        return result;
    }
    if (glyphs.length == 0) {
        result.empty = YES;
        return result;
    }
    NSMutableArray<NSValue *> *visibleCharacterRanges = [NSMutableArray array];
    for (NSUInteger glyph = glyphs.location; glyph < NSMaxRange(glyphs); glyph++) {
        NSRange oneGlyph = NSMakeRange(glyph, 1);
        NSRect glyphBounds = [layout boundingRectForGlyphRange:oneGlyph inTextContainer:prepared.container];
        NSRect glyphIntersection = NSIntersectionRect(glyphBounds, visibleLocal);
        if (NSIsEmptyRect(glyphBounds) || NSIsEmptyRect(glyphIntersection)) continue;
        NSRange lineGlyphs = NSMakeRange(0, 0);
        NSRect lineBounds = [layout lineFragmentRectForGlyphAtIndex:glyph effectiveRange:&lineGlyphs];
        NSRect lineIntersection = NSIntersectionRect(lineBounds, visibleLocal);
        if (lineGlyphs.location == NSNotFound || glyph < lineGlyphs.location ||
            glyph >= NSMaxRange(lineGlyphs) || NSIsEmptyRect(lineIntersection)) continue;
        // A short raster seals its actual ink, not the container's empty
        // horizontal padding. Require every already-laid visible glyph's
        // clipped bounds to belong to that real paint, without preparing more
        // layout or treating missing glyph coverage as an empty selection.
        NSRect visibleGlyphInView = NSOffsetRect(glyphIntersection,
            NSMinX(result.textRect), NSMinY(result.textRect) - prepared.sourceScroll);
        if (checkPaintedCoverage && !NSContainsRect(
                NSInsetRect(paintedCoverage, -0.001, -0.001), visibleGlyphInView)) {
            result.available = NO;
            result.reason = "paint_coverage_incomplete";
            return result;
        }
        NSRange characters = [layout characterRangeForGlyphRange:oneGlyph actualGlyphRange:NULL];
        if (characters.location == NSNotFound || characters.location > body.length ||
            characters.length == 0 || characters.length > body.length - characters.location) {
            result.available = NO;
            result.reason = "invalid_character_range";
            return result;
        }
        [visibleCharacterRanges addObject:[NSValue valueWithRange:characters]];
    }
    if (visibleCharacterRanges.count == 0) {
        result.empty = YES;
        return result;
    }
    [visibleCharacterRanges sortUsingComparator:^NSComparisonResult(NSValue *left, NSValue *right) {
        NSRange a = left.rangeValue, b = right.rangeValue;
        if (a.location < b.location) return NSOrderedAscending;
        if (a.location > b.location) return NSOrderedDescending;
        return NSOrderedSame;
    }];
    NSRange characters = visibleCharacterRanges.firstObject.rangeValue;
    NSUInteger characterEnd = NSMaxRange(characters);
    for (NSUInteger index = 1; index < visibleCharacterRanges.count; index++) {
        NSRange next = visibleCharacterRanges[index].rangeValue;
        if (next.location > characterEnd) {
            result.available = NO;
            result.reason = "noncontiguous_visible_characters";
            return result;
        }
        characterEnd = MAX(characterEnd, NSMaxRange(next));
    }
    characters.length = characterEnd - characters.location;
    NSData *utf8 = [body dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
    NSUInteger start = 0, end = 0;
    if (!utf8 || !CjguiAcceptedTextVisibilityUtf8Offset(body, characters.location, &start) ||
        !CjguiAcceptedTextVisibilityUtf8Offset(body, NSMaxRange(characters), &end) ||
        start > end || end > utf8.length) {
        result.available = NO;
        result.reason = "invalid_utf8_boundary";
        return result;
    }
    result.utf8Start = start;
    result.utf8End = end;
    result.empty = end == start;
    return result;
}

static void CjguiTraceAcceptedTextSurfaceEncoded(CJGuiInternalSession *ctx,
    CJGuiInternalMetalView *view, uint64_t frameIndex) {
    if (!ctx || !view || !CjguiOwnerPhaseTraceEnabled()) return;
    const char *everyFrame = getenv("CJGUI_TEXT_SURFACE_TRACE_ALL_FRAMES");
    BOOL continuous = everyFrame && strcmp(everyFrame, "1") == 0;
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    uint64_t revision = overlay.installedRangeSelectionRevision;
    if (ctx.surfaceTraceSceneVersion == ctx.composableSceneVersion &&
        ctx.surfaceTraceProxyGeneration == ctx.installedRangeProxyGeneration &&
        ctx.surfaceTraceSelectionRevision == revision && !continuous) return;
    ctx.surfaceTraceSceneVersion = ctx.composableSceneVersion;
    ctx.surfaceTraceProxyGeneration = ctx.installedRangeProxyGeneration;
    ctx.surfaceTraceSelectionRevision = revision;
    uint64_t now = cjgui_internal_renderer_owner_trace_ns();
    uint64_t transfer = ctx.installedRangeBasis.selectionTransferId;
    BOOL keyWindow = overlay.window.isKeyWindow;
    BOOL windowVisible = overlay.window.isVisible;
    BOOL windowMiniaturized = overlay.window.isMiniaturized;
    BOOL appActive = NSApp.isActive;
    BOOL proxyFirstResponder = overlay && CjguiInputProxyIsFirstResponder(overlay);
    NSUInteger visible = 0, declared = 0, proxyRects = 0, carets = 0;
    for (CJGuiInternalComposableSceneNode *node in view.composableNodes) {
        if (!CjguiComposableNodeHasGpuText(node.node.nodeKind)) continue;
        if (continuous) {
            CjguiAcceptedTextVisibility textVisibility =
                CjguiAcceptedTextVisibilityForNode(node, view.bounds);
            fprintf(stderr,"CJGUI_TEXT_SURFACE_TEXT_VISIBILITY mono_ns=%llu session=%llu scene=%llu frame=%llu transfer=%llu node=%llu projection=%llu status=%s reason=%s text_rect=%.2f,%.2f,%.2f,%.2f clip=%.2f,%.2f,%.2f,%.2f visible_utf8_start=%lu visible_utf8_end=%lu result=%s\n",
                (unsigned long long)now,(unsigned long long)ctx.rendererSessionToken,
                (unsigned long long)ctx.composableSceneVersion,(unsigned long long)frameIndex,
                (unsigned long long)transfer,(unsigned long long)node.node.nodeId,
                (unsigned long long)node.node.projectionVersion,
                textVisibility.available ? "available" : "unavailable", textVisibility.reason,
                NSMinX(textVisibility.textRect),NSMinY(textVisibility.textRect),
                NSWidth(textVisibility.textRect),NSHeight(textVisibility.textRect),
                NSMinX(textVisibility.clip),NSMinY(textVisibility.clip),
                NSWidth(textVisibility.clip),NSHeight(textVisibility.clip),
                (unsigned long)textVisibility.utf8Start,(unsigned long)textVisibility.utf8End,
                textVisibility.available ? (textVisibility.empty ? "empty" : "range") : "unknown");
        }
        NSRect clip = NSIntersectionRect(CjguiComposableVisualClipBounds(node), view.bounds);
        if (NSIsEmptyRect(NSIntersectionRect(CjguiComposableVisualNodeRect(node), clip))) continue;
        visible++;
        NSUInteger nodeDeclared = 0, nodeProxy = 0;
        for (NSDictionary *decoration in CjguiEffectiveDeclaredSelectionDecorations(ctx, node)) {
            NSRect rect = [decoration[@"rect"] rectValue];
            NSRect visibleRect = NSIntersectionRect(rect, clip);
            if (!NSIsEmptyRect(visibleRect)) {
                nodeDeclared++;
                if (continuous) fprintf(stderr,"CJGUI_TEXT_SURFACE_RECT mono_ns=%llu session=%llu scene=%llu frame=%llu transfer=%llu node=%llu kind=declared rect=%.2f,%.2f,%.2f,%.2f\n",
                    (unsigned long long)now,(unsigned long long)ctx.rendererSessionToken,
                    (unsigned long long)ctx.composableSceneVersion,(unsigned long long)frameIndex,
                    (unsigned long long)transfer,(unsigned long long)node.node.nodeId,
                    NSMinX(visibleRect),NSMinY(visibleRect),NSWidth(visibleRect),NSHeight(visibleRect));
            }
        }
        for (NSValue *value in CjguiEffectiveTransferTextSelectionRects(ctx, node)) {
            NSRect visibleRect = NSIntersectionRect(value.rectValue, clip);
            if (!NSIsEmptyRect(visibleRect)) {
                nodeProxy++;
                if (continuous) fprintf(stderr,"CJGUI_TEXT_SURFACE_RECT mono_ns=%llu session=%llu scene=%llu frame=%llu transfer=%llu node=%llu kind=proxy rect=%.2f,%.2f,%.2f,%.2f\n",
                    (unsigned long long)now,(unsigned long long)ctx.rendererSessionToken,
                    (unsigned long long)ctx.composableSceneVersion,(unsigned long long)frameIndex,
                    (unsigned long long)transfer,(unsigned long long)node.node.nodeId,
                    NSMinX(visibleRect),NSMinY(visibleRect),NSWidth(visibleRect),NSHeight(visibleRect));
            }
        }
        NSRect rawCaret = node.textCaretRect;
        NSRect effectiveCaret = CjguiEffectiveTransferTextCaretRect(ctx, node);
        BOOL rawCaretNonempty = !NSIsEmptyRect(rawCaret);
        BOOL effectiveCaretNonempty = !NSIsEmptyRect(NSIntersectionRect(effectiveCaret, clip));
        BOOL caret = !node.textCaretHidden && effectiveCaretNonempty;
        declared += nodeDeclared; proxyRects += nodeProxy; carets += caret;
        if (continuous) {
            NSRect bounds = CjguiComposableVisualNodeRect(node);
            fprintf(stderr,"CJGUI_TEXT_SURFACE_BOUNDS mono_ns=%llu session=%llu scene=%llu frame=%llu transfer=%llu node=%llu bounds=%.2f,%.2f,%.2f,%.2f\n",
                (unsigned long long)now,(unsigned long long)ctx.rendererSessionToken,
                (unsigned long long)ctx.composableSceneVersion,(unsigned long long)frameIndex,
                (unsigned long long)transfer,(unsigned long long)node.node.nodeId,
                NSMinX(bounds),NSMinY(bounds),NSWidth(bounds),NSHeight(bounds));
        }
        // This is bounded by the materialized scene. No owner read or mutable
        // attributed graph is touched; hashes identify the frozen paint inputs.
        fprintf(stderr,"CJGUI_TEXT_SURFACE_NODE mono_ns=%llu session=%llu scene=%llu frame=%llu transfer=%llu node=%llu resource=%lld projection=%llu body_hash=%llu runs_hash=%llu declared=%lu proxy=%lu raw_caret_nonempty=%u caret_declared=%u caret_hidden=%u effective_caret_nonempty=%u raw_caret=%.2f,%.2f,%.2f,%.2f caret=%u\n",
            (unsigned long long)now,(unsigned long long)ctx.rendererSessionToken,
            (unsigned long long)ctx.composableSceneVersion,(unsigned long long)frameIndex,
            (unsigned long long)transfer,(unsigned long long)node.node.nodeId,
            (long long)node.node.resourceId,(unsigned long long)node.node.projectionVersion,
            (unsigned long long)CjguiEffectHashString(1469598103934665603ull,node.value),
            (unsigned long long)CjguiEffectHashString(1469598103934665603ull,node.styleRunsSignature),
            (unsigned long)nodeDeclared,(unsigned long)nodeProxy,rawCaretNonempty,
            node.textCaretIsDeclared,node.textCaretHidden,effectiveCaretNonempty,
            NSMinX(rawCaret),NSMinY(rawCaret),NSWidth(rawCaret),NSHeight(rawCaret),caret);
    }
    fprintf(stderr,"CJGUI_TEXT_SURFACE_ENCODED mono_ns=%llu session=%llu scene=%llu frame=%llu transfer=%llu proxy_generation=%llu selection_revision=%llu key_window=%u window_visible=%u window_miniaturized=%u app_active=%u proxy_first_responder=%u visible_nodes=%lu declared_rects=%lu proxy_rects=%lu visible_carets=%lu presentation=unobserved\n",
        (unsigned long long)now,(unsigned long long)ctx.rendererSessionToken,
        (unsigned long long)ctx.composableSceneVersion,(unsigned long long)frameIndex,
        (unsigned long long)transfer,(unsigned long long)ctx.installedRangeProxyGeneration,
        (unsigned long long)revision,keyWindow,windowVisible,windowMiniaturized,appActive,
        proxyFirstResponder,(unsigned long)visible,(unsigned long)declared,
        (unsigned long)proxyRects,(unsigned long)carets);
}


// All AppKit work happens while A is still the accepted input graph. Once the
// preflight succeeds, publication has no call out to AppKit, no event pumping,
// no owner callback and no fallible restoration. Cancellation and commit are
// ordered by the existing atomic decision cell; the owner never holds its lock
// while this main-thread operation prepares or publishes the adapter.
static CjguiPreparedTextNodeLayout *CjguiSelectionBRetiredAInputLayout(
    CjguiSelectionTransferCapsule *capsule, CJGuiInternalComposableSceneOverlay *detachedOverlay,
    CjguiTextPreparationWorkerInput *input) {
    if (!capsule || !detachedOverlay || !input || capsule.aNodeId != input.nodeId ||
        capsule.aResourceId != input.node.resourceId || capsule.aNodeKind != input.nodeKind ||
        ![capsule.aBody.string isEqualToString:input.body]) return nil;
    CJGuiInternalComposableInputProxy *proxy = (id)detachedOverlay.inputProxy;
    if (!proxy || ![proxy.textStorage isEqualToAttributedString:input.sourceAttributedBody]) return nil;
    CjguiPreparedTextNodeLayout *layout = [CjguiPreparedTextNodeLayout new];
    layout.storage = proxy.textStorage;
    layout.layoutManager = proxy.layoutManager;
    layout.container = proxy.textContainer;
    layout.textRect = input.textRect;
    layout.diagnosticSession = nil;
    return CjguiSelectionBSpareLayoutMatches(layout, input) ? layout : nil;
}

static void CjguiCancelSelectionTransferBPreparation(CjguiSelectionTransferCapsule *capsule) {
    CjguiSelectionTransferBPreparation *b = capsule.bPreparation;
    if (!b) return;
    b.cancelled = YES;
    CjguiCancelTextPreparationWorker(b.admission);
    CJGuiInternalComposableSceneOverlay *prepared = b.preparedOverlay ?: capsule.preparedOverlay;
    if (prepared && prepared.inputProxy != capsule.overlay.inputProxy) {
        [prepared.inputScrollProxy removeFromSuperview];
        prepared.inputProxy.delegate = nil;
        ((CJGuiInternalComposableInputProxy *)prepared.inputProxy).composableOverlay = nil;
    }
    if (b.acceptedTarget && b.previousTargetLayout &&
        b.acceptedTarget.preparedTextLayout == b.sourceLayout)
        b.acceptedTarget.preparedTextLayout = b.previousTargetLayout;
    if (b.reusedSpare) b.reusedSpare.inUse = NO;
    b.sourceLayout = nil;
    b.painter = nil;
    b.preparedOverlay = nil;
    b.acceptedTarget = nil;
    capsule.preparedOverlay = nil;
    capsule.bPreparation = nil;
}

static _Atomic uint64_t gCjguiNextSelectionBPreparationIdentity = 1;

// Every adapter uses the same plain-input policy, including a newly adopted
// worker graph. NSTextView's defaults enable independent document analysis;
// those defaults must not return when only the backing TextKit graph changes.
// This changes input capabilities, not the prepared attributed text or layout.
static void CjguiConfigurePlainTextInputProxy(NSTextView *proxy) {
    proxy.richText = NO;
    proxy.usesRuler = NO;
    proxy.continuousSpellCheckingEnabled = NO;
    proxy.grammarCheckingEnabled = NO;
    proxy.allowsUndo = NO;
    proxy.automaticSpellingCorrectionEnabled = NO;
    proxy.automaticTextReplacementEnabled = NO;
    proxy.automaticQuoteSubstitutionEnabled = NO;
    proxy.automaticDashSubstitutionEnabled = NO;
}

// Record only the specific main-thread adoption calls under investigation.
// This uses the existing bounded ring and performs no formatting or dispatch.
static uint64_t CjguiSelectionMainPhase(CJGuiInternalSession *ctx,
    CjguiSelectionTransferCapsule *capsule, uint32_t kind, uint32_t phase, uint64_t span) {
    if (!ctx || !capsule || !CjguiOwnerPhaseTraceEnabled()) return 0;
    return CjguiOwnerTraceAppend(kind, ctx.rendererSessionToken,
        atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn, memory_order_acquire),
        capsule.transferId, 0, ctx.sessionGeneration, phase, span);
}

static BOOL CjguiSelectionTransferBStillMatches(CJGuiInternalSession *ctx,
    CjguiSelectionTransferCapsule *capsule, CjguiSelectionTransferBPreparation *b,
    CJGuiInternalComposableSceneNode **outNode, uint32_t *outState) {
    if (outNode) *outNode = nil;
    if (!ctx || !capsule || !b || b.cancelled || ctx.destroyed ||
        capsule.transferId != b.transferId ||
        b.sessionGeneration != ctx.sessionGeneration || !CjguiSelectionTransferSourceSceneMatches(ctx, capsule) ||
        ctx.composableSceneOverlay != capsule.overlay || capsule.window != ctx.window ||
        ctx.selectionTransferId != capsule.transferId || !capsule.bBody ||
        !NSEqualRanges(b.selection, capsule.bSelection)) return NO;
    uint32_t state = CJGUI_SELECTION_TRANSFER_EMPTY;
    uint8_t cancelled = 0;
    if (!CjguiSelectionTransferCellState(ctx.rendererSessionToken, capsule.transferId, &state, &cancelled) ||
        state != CJGUI_SELECTION_TRANSFER_PENDING || cancelled) {
        if (outState) *outState = state;
        return NO;
    }
    CJGuiInternalComposableSceneNode *node = CjguiSelectionTransferTargetNode(ctx, capsule);
    if (!node) return NO;
    NSString *runs = ctx.composableTextStyleRunsRaw[@(capsule.bNodeId)] ?: @"";
    if (node != b.acceptedTarget || ![node.value isEqualToString:capsule.bBody] ||
        ![runs isEqualToString:b.encodedRuns] ||
        (node.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT &&
         node.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) ||
        node.node.nodeKind != capsule.bNodeKind ||
        node.node.nodeId != capsule.bNodeId || node.node.projectionVersion != capsule.bProjectionVersion ||
        node.node.resourceId != capsule.bResourceId || !NSEqualSizes(ctx.view.bounds.size, b.admission.viewport) ||
        b.admission.baseSceneVersion != capsule.bSceneVersion ||
        b.admission.projectionVersion != capsule.bProjectionVersion ||
        b.admission.bindingEpoch != capsule.bBindingEpoch || b.admission.scale != MAX(1.0, [ctx.view currentBackingScale]))
        return NO;
    if (outNode) *outNode = node;
    if (outState) *outState = state;
    return YES;
}

static CjguiInternalRendererStatus CjguiAdvanceSelectionTransferBPreparation(
    CJGuiInternalSession *ctx, CjguiSelectionTransferCapsule *capsule,
    uint64_t deadlineNs, uint8_t *outReady) {
    *outReady = 0;
    if (!ctx || !capsule || !capsule.bBody) return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    if (capsule.bBody.length < 1024) { *outReady = 1; return CJGUI_INTERNAL_RENDERER_OK; }
    if (deadlineNs && cjgui_internal_renderer_owner_clock_ns() >= deadlineNs)
        return CJGUI_INTERNAL_RENDERER_OK;
    if (capsule.bBody.length > CjguiTextPreparationWorkerMaxUtf16Length)
        return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
    uint32_t state = CJGUI_SELECTION_TRANSFER_EMPTY;
    CJGuiInternalComposableSceneNode *node = nil;
    CjguiSelectionTransferBPreparation *b = capsule.bPreparation;
    if (b && !CjguiSelectionTransferBStillMatches(ctx, capsule, b, &node, &state)) {
        CjguiCancelSelectionTransferBPreparation(capsule);
        return state == CJGUI_SELECTION_TRANSFER_PENDING
            ? CJGUI_INTERNAL_RENDERER_SCENE_STALE : CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    }
    if (!b) {
        if (deadlineNs && cjgui_internal_renderer_owner_clock_ns() >= deadlineNs)
            return CJGUI_INTERNAL_RENDERER_OK;
        node = CjguiSelectionTransferTargetNode(ctx, capsule);
        if (!node) return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        if ((node.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT &&
             node.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) ||
            ![node.value isEqualToString:capsule.bBody]) return CJGUI_INTERNAL_RENDERER_TEXT_SERVICE_UNSUPPORTED;
        b = [CjguiSelectionTransferBPreparation new];
        CjguiComposablePreparation *admission = [CjguiComposablePreparation new];
        if (!b || !admission) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        b.transferId = capsule.transferId;
        b.sessionGeneration = ctx.sessionGeneration;
        b.sceneVersion = capsule.bSceneVersion;
        b.selection = capsule.bSelection;
        b.acceptedTarget = node;
        b.previousTargetLayout = node.preparedTextLayout;
        b.startedMonoNs = cjgui_internal_renderer_owner_clock_ns();
        b.encodedRuns = [ctx.composableTextStyleRunsRaw[@(capsule.bNodeId)] copy] ?: @"";
        uint64_t bIdentity = atomic_fetch_add_explicit(&gCjguiNextSelectionBPreparationIdentity, 1,
            memory_order_relaxed);
        if (!bIdentity || bIdentity >= (UINT64_C(1) << 63)) {
            atomic_store_explicit(&gCjguiNextSelectionBPreparationIdentity, 2, memory_order_relaxed);
            bIdentity = 1;
        }
        admission.preparationId = (UINT64_C(1) << 63) | bIdentity;
        admission.sessionToken = ctx.rendererSessionToken;
        admission.sessionGeneration = ctx.sessionGeneration;
        admission.baseSceneVersion = capsule.bSceneVersion;
        admission.projectionVersion = capsule.bProjectionVersion;
        admission.bindingEpoch = capsule.bBindingEpoch;
        admission.scale = MAX(1.0, [ctx.view currentBackingScale]);
        admission.viewport = ctx.view.bounds.size;
        b.admission = admission;
        capsule.bPreparation = b;
    }
    if (!node) node = b.acceptedTarget;
    CjguiComposablePreparation *admission = b.admission;
    CjguiTextPreparationWorkerJob *job = admission.textLayoutJob;
    CjguiTextPreparationWorkerInput *input = nil;
    CjguiPreparedTextNodeLayout *source = nil, *painter = nil;
    NSString *failure = nil;
    CjguiTextPreparationWorkerState jobState = CjguiTextPreparationWorkerStateQueued;
    BOOL reusedSpare = NO;
    if (!job) {
        uint64_t reservedBytes = admission.textLayoutPendingBytes;
        input = admission.textLayoutPendingInput;
        if (!input) input = CjguiCreateTextPreparationWorkerInput(ctx, admission, node,
            capsule.bBody, b.encodedRuns, &reservedBytes);
        if (!input || !reservedBytes) {
            CjguiCancelSelectionTransferBPreparation(capsule);
            return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
        }
        CjguiSelectionTransferBSpare *spare = ctx.selectionBSpare;
        BOOL cacheIdentityMatches = spare && CjguiSelectionBInputsShareLayoutIdentity(spare.identity, input);
        BOOL cacheGraphMatches = spare && CjguiSelectionBSpareLayoutMatches(spare.painter, input);
        if (spare && !spare.inUse && cacheIdentityMatches && cacheGraphMatches) {
            spare.inUse = YES;
            b.reusedSpare = spare;
            b.workerInput = input;
            source = spare.painter;
            painter = spare.painter;
            b.measuredExtent = spare.measuredExtent;
            reusedSpare = YES;
            jobState = CjguiTextPreparationWorkerStateReady;
            admission.textLayoutPendingInput = nil;
            admission.textLayoutPendingBytes = 0;
        } else {
            if (spare && getenv("CJGUI_TEXT_PREPARE_TRACE")) fprintf(stderr,
                "CJGUI_SELECTION_B_SPARE_MISS transfer=%llu in_use=%u identity=%u graph=%u scene=%llu/%llu binding=%llu/%llu projection=%llu/%llu node=%llu/%llu body=%lu/%lu\n",
                (unsigned long long)capsule.transferId,(unsigned)spare.inUse,
                (unsigned)cacheIdentityMatches,(unsigned)cacheGraphMatches,
                (unsigned long long)spare.identity.baseSceneVersion,(unsigned long long)input.baseSceneVersion,
                (unsigned long long)spare.identity.bindingEpoch,(unsigned long long)input.bindingEpoch,
                (unsigned long long)spare.identity.projectionVersion,(unsigned long long)input.projectionVersion,
                (unsigned long long)spare.identity.nodeId,(unsigned long long)input.nodeId,
                (unsigned long)spare.identity.body.length,(unsigned long)input.body.length);
            // A cold/different identity may need the same global bytes held by
            // detached spares. Evict them before it joins the fair worker queue.
            CjguiDiscardIdleSelectionBSpares();
            CjguiTextPreparationAdmission result = CjguiTextPreparationAdmissionNotAdmitted;
            job = CjguiTextPreparationReserve(admission, reservedBytes, &result);
            if (!job) {
                if (result == CjguiTextPreparationAdmissionWaiting) {
                    admission.textLayoutPendingInput = input;
                    admission.textLayoutPendingBytes = reservedBytes;
                    return CJGUI_INTERNAL_RENDERER_OK;
                }
                CjguiCancelSelectionTransferBPreparation(capsule);
                return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
            }
            admission.textLayoutPendingInput = nil;
            admission.textLayoutPendingBytes = 0;
            pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
            job.input = input;
            job.workerLive = YES;
            job.traceTransferId = capsule.transferId;
            job.traceOwnerTurn = atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn, memory_order_acquire);
            admission.textLayoutJob = job;
            pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
            CjguiSelectionBWorkerTrace(job, input, CJGUI_OWNER_TRACE_OBSERVATION_SCALAR, 320, reservedBytes);
            dispatch_async(CjguiTextPreparationWorkerQueue(), ^{ CjguiRunTextPreparationWorker(job); });
            return CJGUI_INTERNAL_RENDERER_OK;
        }
    }
    if (!reusedSpare) {
        pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
        jobState = job.state;
        if (job.workerLive || jobState == CjguiTextPreparationWorkerStateQueued ||
            jobState == CjguiTextPreparationWorkerStateRunning) {
            pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
            return CJGUI_INTERNAL_RENDERER_OK;
        }
        input = job.input; source = job.sourceLayout; painter = job.painter; failure = job.failure;
        pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
    }
    uint64_t identityPhase = CjguiSelectionMainPhase(ctx, capsule, CJGUI_OWNER_TRACE_PHASE_BEGIN, 331, 0);
    BOOL identityMatches = CjguiSelectionTransferBStillMatches(ctx, capsule, b, &node, &state) &&
        CjguiTextPreparationInputMatches(ctx, admission, node, input);
    CjguiSelectionMainPhase(ctx, capsule, CJGUI_OWNER_TRACE_PHASE_END, 331, identityPhase);
    if (!identityMatches) {
        CjguiCancelSelectionTransferBPreparation(capsule);
        return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    }
    if (jobState != CjguiTextPreparationWorkerStateReady || !source || !painter ||
        (!reusedSpare && (source == painter || source.storage == painter.storage ||
         source.layoutManager == painter.layoutManager || source.container == painter.container)) ||
        ![source.storage.string isEqualToString:capsule.bBody] ||
        source.layoutManager.firstUnlaidCharacterIndex < source.storage.length ||
        painter.layoutManager.firstUnlaidCharacterIndex < painter.storage.length ||
        (failure && failure.length)) {
        CjguiCancelSelectionTransferBPreparation(capsule);
        return CJGUI_INTERNAL_RENDERER_TEXT_SERVICE_UNSUPPORTED;
    }

    // The worker is fully retired before the main thread adopts either graph.
    // Keep the reservation/slot live while the private B graphs are pending
    // installation; cancellation or commit releases it exactly once.
    source.positionLease = ++gCjguiNextPreparedTextPositionLease;
    source.diagnosticSession = ctx;
    painter.positionLease = ++gCjguiNextPreparedTextPositionLease;
    painter.diagnosticSession = ctx;
    CJGuiInternalComposableSceneOverlay *accepted = capsule.overlay;
    uint64_t overlayPhase = CjguiSelectionMainPhase(ctx, capsule, CJGUI_OWNER_TRACE_PHASE_BEGIN, 332, 0);
    CJGuiInternalComposableSceneOverlay *prepared = [[CJGuiInternalComposableSceneOverlay alloc]
        initWithFrame:accepted.frame session:ctx];
    CjguiSelectionMainPhase(ctx, capsule, CJGUI_OWNER_TRACE_PHASE_END, 332, overlayPhase);
    if (!prepared) {
        CjguiCancelSelectionTransferBPreparation(capsule);
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    prepared.detachedSourcePreparation = YES;
    prepared.detachedSourceRuns = @{ @(capsule.bNodeId): b.encodedRuns ?: @"" };
    prepared.appearance = accepted.effectiveAppearance;
    prepared.nodes = accepted.nodes;
    prepared.activeNodeIndex = node.index; prepared.activeNodeId = capsule.bNodeId;
    prepared.activeProjectionVersion = capsule.bProjectionVersion;
    prepared.activeNodeResourceId = capsule.bResourceId; prepared.activeNodeKind = capsule.bNodeKind;
    prepared.multilineScrollOffsets = [accepted.multilineScrollOffsets mutableCopy];
    prepared.multilineLayoutCache = [accepted.multilineLayoutCache mutableCopy];
    prepared.multilineLayoutCacheOrder = [accepted.multilineLayoutCacheOrder mutableCopy];
    prepared.activeTextBodyGeneration = accepted.activeTextBodyGeneration;
    prepared.activeLocalEditGeneration = accepted.activeLocalEditGeneration;
    prepared.activeLocalEditSettledGeneration = accepted.activeLocalEditSettledGeneration;
    CJGuiInternalComposableInputProxy *oldProxy = (id)prepared.inputProxy;
    uint64_t proxyPhase = CjguiSelectionMainPhase(ctx, capsule, CJGUI_OWNER_TRACE_PHASE_BEGIN, 333, 0);
    CJGuiInternalComposableInputProxy *proxy = [[CJGuiInternalComposableInputProxy alloc]
        initWithFrame:oldProxy.frame textContainer:source.container];
    CjguiSelectionMainPhase(ctx, capsule, CJGUI_OWNER_TRACE_PHASE_END, 333, proxyPhase);
    if (!proxy || proxy.textStorage != source.storage || proxy.layoutManager != source.layoutManager ||
        proxy.textContainer != source.container || source.layoutManager.firstUnlaidCharacterIndex < source.storage.length) {
        CjguiCancelSelectionTransferBPreparation(capsule);
        return CJGUI_INTERNAL_RENDERER_TEXT_SERVICE_UNSUPPORTED;
    }
    uint64_t attributesPhase = CjguiSelectionMainPhase(ctx, capsule, CJGUI_OWNER_TRACE_PHASE_BEGIN, 334, 0);
    CGFloat width = MAX(1.0, NSWidth(input.textRect)), height = MAX(1.0, NSHeight(input.textRect));
    uint64_t framePhase = CjguiSelectionMainPhase(ctx, capsule, CJGUI_OWNER_TRACE_PHASE_BEGIN, 346, 0);
    proxy.frame = NSMakeRect(0, 0, width, height);
    proxy.minSize = NSMakeSize(width, height); proxy.maxSize = NSMakeSize(width, height);
    proxy.textContainerInset = NSZeroSize;
    CjguiSelectionMainPhase(ctx, capsule, CJGUI_OWNER_TRACE_PHASE_END, 346, framePhase);
    uint64_t flagsPhase = CjguiSelectionMainPhase(ctx, capsule, CJGUI_OWNER_TRACE_PHASE_BEGIN, 347, 0);
    CjguiConfigurePlainTextInputProxy(proxy);
    proxy.editable = node.node.isReadOnly == 0; proxy.selectable = YES;
    proxy.verticallyResizable = NO; proxy.horizontallyResizable = NO;
    CjguiSelectionMainPhase(ctx, capsule, CJGUI_OWNER_TRACE_PHASE_END, 347, flagsPhase);
    uint64_t typingPhase = CjguiSelectionMainPhase(ctx, capsule, CJGUI_OWNER_TRACE_PHASE_BEGIN, 348, 0);
    NSColor *baseColor = [NSColor colorWithSRGBRed:node.node.textRed green:node.node.textGreen
        blue:node.node.textBlue alpha:1.0];
    NSMutableDictionary *typing = [[oldProxy.typingAttributes copy] mutableCopy] ?: [NSMutableDictionary dictionary];
    if (input.baseFont) typing[NSFontAttributeName] = input.baseFont;
    if (baseColor) typing[NSForegroundColorAttributeName] = baseColor;
    proxy.typingAttributes = typing;
    CjguiSelectionMainPhase(ctx, capsule, CJGUI_OWNER_TRACE_PHASE_END, 348, typingPhase);
    uint64_t selectedPhase = CjguiSelectionMainPhase(ctx, capsule, CJGUI_OWNER_TRACE_PHASE_BEGIN, 349, 0);
    proxy.selectedRange = b.selection;
    CjguiSelectionMainPhase(ctx, capsule, CJGUI_OWNER_TRACE_PHASE_END, 349, selectedPhase);
    CjguiSelectionMainPhase(ctx, capsule, CJGUI_OWNER_TRACE_PHASE_END, 334, attributesPhase);
    uint64_t documentPhase = CjguiSelectionMainPhase(ctx, capsule, CJGUI_OWNER_TRACE_PHASE_BEGIN, 335, 0);
    prepared.inputScrollProxy.frame = NSMakeRect(-2, -2, 1, 1);
    [prepared.inputScrollProxy setDocumentView:proxy];
    CjguiSelectionMainPhase(ctx, capsule, CJGUI_OWNER_TRACE_PHASE_END, 335, documentPhase);
    prepared.inputProxy = proxy;
    prepared.activeTextBaseFont = input.baseFont;
    prepared.inputProxyAssignedBaseFont = input.baseFont;
    if (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) {
        CGFloat contentWidth = MAX(1.0, node.node.width - 14.0);
        prepared.activeTextLayoutSignature = [prepared activeTextLayoutSignatureForNode:node contentWidth:contentWidth];
        prepared.activeTextAttributeSignature = [prepared activeTextAttributeSignatureForNode:node];
        prepared.activeTextRunsSignature = [prepared activeTextRunsSignatureForNode:node];
        prepared.activeTextFallbackRunsDirty = NO;
        prepared.activeTextFallbackNeedsFullRefresh = NO;
        prepared.activeTextFallbackHasDirtyRange = NO;
        prepared.activeTextLayoutNeedsVisibleGlyphs = NO;
        prepared.activeTextBodyGeneration = MAX((uint64_t)1, accepted.activeTextBodyGeneration);
        prepared.activeTextAttributedGeneration = MAX((uint64_t)1, accepted.activeTextAttributedGeneration);
    }
    uint64_t readbackPhase = CjguiSelectionMainPhase(ctx, capsule, CJGUI_OWNER_TRACE_PHASE_BEGIN, 336, 0);
    BOOL readbackMatches = !(proxy.textStorage != source.storage || proxy.layoutManager != source.layoutManager ||
        proxy.textContainer != source.container || ![proxy.string isEqualToString:capsule.bBody] ||
        !NSEqualRanges(proxy.selectedRange, b.selection) ||
        source.layoutManager.firstUnlaidCharacterIndex < source.storage.length);
    CjguiSelectionMainPhase(ctx, capsule, CJGUI_OWNER_TRACE_PHASE_END, 336, readbackPhase);
    if (!readbackMatches) {
        CjguiCancelSelectionTransferBPreparation(capsule);
        return CJGUI_INTERNAL_RENDERER_TEXT_SERVICE_UNSUPPORTED;
    }
    b.sourceLayout = source; b.painter = painter;
    // A warm spare owns the matching extent as well as the complete graph.
    // It has no worker job: reading a struct result from nil would replace
    // the retained extent with zero and erase scrolled text coverage.
    if (job) b.measuredExtent = job.measuredExtent;
    b.workerStartedMonoNs = job ? job.workerStartedMicros * UINT64_C(1000) : 0;
    b.workerCompletedMonoNs = job ? job.workerCompletedMicros * UINT64_C(1000) : 0;
    b.workerInput = input;
    b.preparedOverlay = prepared; b.ready = YES;
    capsule.preparedOverlay = prepared;
    admission.textLayoutJob = job;
    if (CjguiOwnerPhaseTraceEnabled()) {
        CjguiOwnerTraceAppend(CJGUI_OWNER_TRACE_OBSERVATION_SCALAR, ctx.rendererSessionToken,
            atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn, memory_order_acquire), capsule.transferId,
            job ? job.generation : 0, b.sessionGeneration, 325, input.body.length);
        CjguiOwnerTraceAppend(CJGUI_OWNER_TRACE_OBSERVATION_SCALAR, ctx.rendererSessionToken,
            atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn, memory_order_acquire), capsule.transferId,
            job ? job.generation : 0, b.sessionGeneration, 326, reusedSpare ? 1 : 0);
    }
    *outReady = 1;
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus cjgui_internal_renderer_selection_transfer_prepare_b(
    uint64_t session, uint64_t transferId, uint64_t deadlineNs, uint8_t *outReady) {
    if (!outReady || !transferId) return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    *outReady = 0;
    uint64_t callerStart = cjgui_internal_renderer_owner_clock_ns();
    __block uint64_t startedMono = 0, mainSpanNs = 0, cumulativeMainNs = 0;
    __block uint64_t workerStartedNs = 0, workerCompletedNs = 0;
    __block BOOL traceCandidate = NO;
    CjguiInternalRendererStatus status = CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        uint64_t serviceStart = cjgui_internal_renderer_owner_clock_ns();
        CjguiSelectionTransferCapsule *capsule = ctx.selectionTransferCapsule;
        uint32_t state = CJGUI_SELECTION_TRANSFER_EMPTY; uint8_t cancelled = 0;
        if (!capsule || capsule.transferId != transferId || ctx.selectionTransferId != transferId ||
            !capsule.bInputBasis || !CjguiSelectionTransferCellState(session, transferId, &state, &cancelled) ||
            state != CJGUI_SELECTION_TRANSFER_PENDING || cancelled) {
            if (capsule && capsule.transferId == transferId) CjguiCancelSelectionTransferBPreparation(capsule);
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        }
        traceCandidate = YES;
        CjguiInternalRendererStatus result = CjguiAdvanceSelectionTransferBPreparation(
            ctx, capsule, deadlineNs, outReady);
        uint64_t serviceEnd = cjgui_internal_renderer_owner_clock_ns();
        mainSpanNs = serviceEnd >= serviceStart ? serviceEnd - serviceStart : 0;
        CjguiSelectionTransferBPreparation *b = capsule.bPreparation;
        if (b) {
            startedMono = b.startedMonoNs;
            b.mainServiceNs = CjguiSaturatingAddU64(b.mainServiceNs, mainSpanNs);
            cumulativeMainNs = b.mainServiceNs;
            CjguiTextPreparationWorkerJob *job = b.admission.textLayoutJob;
            if (job) {
                pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
                b.workerStartedMonoNs = job.workerStartedMicros * UINT64_C(1000);
                b.workerCompletedMonoNs = job.workerCompletedMicros * UINT64_C(1000);
                pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
            }
            workerStartedNs = b.workerStartedMonoNs;
            workerCompletedNs = b.workerCompletedMonoNs;
        }
        return result;
    });
    uint64_t callerEnd = cjgui_internal_renderer_owner_clock_ns();
    if (traceCandidate && getenv("CJGUI_TEXT_PREPARE_TRACE")) {
        uint64_t total = *outReady && startedMono && callerEnd >= startedMono ? callerEnd - startedMono : 0;
        fprintf(stderr, "CJGUI_SELECTION_B_PREPARE transfer=%llu status=%u ready=%u "
            "started_mono_ns=%llu caller_span_ns=%llu main_service_ns=%llu cumulative_main_service_ns=%llu "
            "total_to_ready_ns=%llu worker_started_mono_ns=%llu worker_completed_mono_ns=%llu\n",
            (unsigned long long)transferId, (unsigned)status, *outReady,
            (unsigned long long)startedMono,
            (unsigned long long)(callerEnd >= callerStart ? callerEnd - callerStart : 0),
            (unsigned long long)mainSpanNs, (unsigned long long)cumulativeMainNs,
            (unsigned long long)total, (unsigned long long)workerStartedNs,
            (unsigned long long)workerCompletedNs);
    }
    return status;
}

#ifdef CJGUI_INTERNAL_TESTING
// One-shot FIFO race fixture. The hook is armed by a test for one renderer
// session, then consumed only while its selection B decision is still Pending
// and the accepted overlay has a captured pointer. It exercises the ordinary
// mouseDragged -> selection-transfer admission -> captured UPDATE route.
static uint64_t gCjguiTestPendingSelectionUpdateSession = 0;
static NSPoint gCjguiTestPendingSelectionUpdatePoint = {0, 0};
static BOOL gCjguiTestPendingSelectionUpdateArmed = NO;
static BOOL gCjguiTestPendingSelectionUpdateConsumed = NO;
static uint64_t gCjguiTestSelectionGeometryRejectSession = 0;
static BOOL gCjguiTestSelectionGeometryRejectArmed = NO;
static BOOL gCjguiTestSelectionGeometryRejectConsumed = NO;

static BOOL CjguiTestConsumeSelectionGeometryReject(uint64_t session) {
    if (!gCjguiTestSelectionGeometryRejectArmed ||
        gCjguiTestSelectionGeometryRejectSession != session) return NO;
    gCjguiTestSelectionGeometryRejectArmed = NO;
    gCjguiTestSelectionGeometryRejectConsumed = YES;
    return YES;
}

static BOOL CjguiTestInjectPendingSelectionUpdate(uint64_t session,
    CJGuiInternalComposableSceneOverlay *overlay, uint64_t transferId) {
    if (!gCjguiTestPendingSelectionUpdateArmed ||
        gCjguiTestPendingSelectionUpdateSession != session || !overlay ||
        !overlay.pointerCaptureActive) return NO;
    uint32_t state = CJGUI_SELECTION_TRANSFER_EMPTY;
    uint8_t cancelled = 0;
    if (!CjguiSelectionTransferCellState(session, transferId, &state, &cancelled) ||
        state != CJGUI_SELECTION_TRANSFER_PENDING || cancelled) return NO;
    gCjguiTestPendingSelectionUpdateArmed = NO;
    gCjguiTestPendingSelectionUpdateConsumed = YES;
    NSPoint windowPoint = [overlay convertPoint:gCjguiTestPendingSelectionUpdatePoint toView:nil];
    NSEvent *event = [NSEvent mouseEventWithType:NSEventTypeLeftMouseDragged
        location:windowPoint modifierFlags:0 timestamp:0.01 windowNumber:overlay.window.windowNumber
        context:nil eventNumber:1 clickCount:1 pressure:1.0];
    if (!event) return NO;
    [overlay mouseDragged:event];
    return YES;
}
#endif

// A selection transfer is anchored to its SOURCE identity, not to the display
// generation it happened to be captured in. Zed keeps selections as buffer
// Anchors and re-resolves them against the current DisplaySnapshot
// (crates/editor/src/selections_collection.rs: `Selection<Anchor>`,
// `all_anchors(&snapshot)`), so rebuilding the display never invalidates a
// selection. Here the same node, resource, projection, body and range still
// resolve in the live scene, so a scene published between prepare and install --
// including the one this very selection update causes -- must re-base the
// transfer onto the live scene instead of refusing it. The old-scene gate that
// governs PUBLISHED decorations (CjguiEffectiveDeclaredSelectionDecorations)
// is deliberately untouched: a newer accepted scene still wins as a whole.
static BOOL CjguiRebaseSelectionTransferScene(CJGuiInternalSession *ctx,
    CjguiSelectionTransferCapsule *capsule) {
    if (!ctx || !capsule || capsule.bSceneVersion == ctx.composableSceneVersion) return YES;
    if (!capsule.overlay || capsule.overlay != ctx.composableSceneOverlay) return NO;
    NSInteger index = CjguiSelectionTransferFindNodeIndex(capsule.overlay, capsule.bNodeId,
        capsule.bProjectionVersion, capsule.bResourceId, capsule.bNodeKind);
    if (index == NSNotFound) return NO;
    CJGuiInternalComposableSceneNode *node = capsule.overlay.nodes[index];
    if (node.node.nodeKind != capsule.bNodeKind ||
        node.node.nodeId != capsule.bNodeId ||
        node.node.resourceId != capsule.bResourceId ||
        node.node.projectionVersion != capsule.bProjectionVersion ||
        ![node.value isEqualToString:capsule.bBody]) return NO;
    uint64_t previous = capsule.bSceneVersion;
    capsule.bSceneVersion = ctx.composableSceneVersion;
    if (capsule.bPreparation) {
        capsule.bPreparation.sceneVersion = capsule.bSceneVersion;
        capsule.bPreparation.admission.baseSceneVersion = capsule.bSceneVersion;
    }
    if (getenv("CJGUI_SELECTION_REBASE_TRACE"))
        fprintf(stderr, "CJGUI_SELECTION_REBASE from=%llu to=%llu node=%llu projection=%llu\n",
            (unsigned long long)previous, (unsigned long long)capsule.bSceneVersion,
            (unsigned long long)capsule.bNodeId, (unsigned long long)capsule.bProjectionVersion);
    return YES;
}

static CjguiInternalRendererStatus CjguiPrepareSelectionTransferInstallation(CJGuiInternalSession *ctx,
    CjguiSelectionTransferCapsule *c, CJGuiInternalComposableSceneNode **outNode,
    CJGuiInternalComposableSceneOverlay **outPrepared, NSArray<NSValue *> **outRects,
    NSRect *outCaret, CjguiInternalSelectionTransferReceipt *outReceipt) {
    uint64_t session=ctx.rendererSessionToken, transferId=c.transferId;
        CJGuiInternalComposableSceneOverlay *o=ctx.composableSceneOverlay;
        uint32_t state=0; uint8_t cancelled=0;
        BOOL hasDecision = CjguiSelectionTransferCellState(session,transferId,&state,&cancelled);
        if (!c || c.transferId!=transferId || !c.bInputBasis || c.overlay!=o ||
            c.proxy!=o.inputProxy || c.window!=ctx.window || !hasDecision ||
            state!=CJGUI_SELECTION_TRANSFER_PENDING || cancelled) {
            if (c && c.transferId==transferId && (cancelled || state!=CJGUI_SELECTION_TRANSFER_PENDING))
                CjguiCancelSelectionTransferBPreparation(c);
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        }
        CJGuiInternalComposableSceneNode *node=CjguiSelectionTransferTargetNode(ctx,c);
        if (!node) return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        NSRange wanted=CjguiComposedSelection(c.bBody,c.bSelection.location,NSMaxRange(c.bSelection));
        if (![node.value isEqualToString:c.bBody] || !NSEqualRanges(wanted,c.bSelection) ||
            ctx.installedRangeProxyGeneration==UINT64_MAX || o.installedRangeSelectionRevision==UINT64_MAX)
            return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
        // Source identity is intact, so a scene advance re-bases instead of
        // refusing. A transfer whose node/body/range no longer resolves above
        // still fails, so this is not a gate removal.
        if (!c.candidateSceneTransfer && !CjguiRebaseSelectionTransferScene(ctx, c))
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        if (!CjguiSelectionTransferSourceSceneMatches(ctx,c))
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;

        // Long B bodies consume only a completed private worker graph. The
        // short path keeps its established synchronous setup.
        BOOL longText = c.bBody.length >= 1024;
        CjguiSelectionTransferBPreparation *bPreparation = c.bPreparation;
        CJGuiInternalComposableSceneOverlay *prepared = nil;
        if (longText) {
            uint32_t pendingState = CJGUI_SELECTION_TRANSFER_EMPTY;
            if (!bPreparation || !bPreparation.ready || bPreparation.cancelled ||
                !bPreparation.preparedOverlay || !bPreparation.sourceLayout || !bPreparation.painter ||
                !CjguiSelectionTransferBStillMatches(ctx, c, bPreparation, &node, &pendingState) ||
                bPreparation.preparedOverlay.inputProxy.textStorage != bPreparation.sourceLayout.storage ||
                bPreparation.preparedOverlay.inputProxy.layoutManager != bPreparation.sourceLayout.layoutManager ||
                bPreparation.sourceLayout.layoutManager.firstUnlaidCharacterIndex < bPreparation.sourceLayout.storage.length)
                return CJGUI_INTERNAL_RENDERER_PRESENT_PENDING;
            prepared = bPreparation.preparedOverlay;
        } else {
            prepared=[[CJGuiInternalComposableSceneOverlay alloc] initWithFrame:o.frame session:ctx];
            c.preparedOverlay=prepared;
            prepared.detachedSourcePreparation=YES;
            prepared.detachedSourceRuns=@{ @(c.bNodeId): ctx.composableTextStyleRunsRaw[@(c.bNodeId)] ?: @"" };
            prepared.appearance=o.effectiveAppearance; prepared.nodes=c.candidateSceneTransfer ? ctx.stagedComposableNodes : o.nodes;
            prepared.activeNodeIndex=node.index; prepared.activeNodeId=c.bNodeId;
            prepared.activeProjectionVersion=c.bProjectionVersion; prepared.activeNodeResourceId=c.bResourceId;
            prepared.activeNodeKind=c.bNodeKind;
            prepared.multilineScrollOffsets=[o.multilineScrollOffsets mutableCopy];
            prepared.multilineLayoutCache=[o.multilineLayoutCache mutableCopy];
            prepared.multilineLayoutCacheOrder=[o.multilineLayoutCacheOrder mutableCopy];
            prepared.activeTextBodyGeneration=o.activeTextBodyGeneration;
            prepared.activeLocalEditGeneration=o.activeLocalEditGeneration;
            prepared.activeLocalEditSettledGeneration=o.activeLocalEditSettledGeneration;
            if (![prepared installInputProxyForNode:node sameNode:NO selection:wanted preservingCurrentFirstResponder:YES])
                return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        }
        uint64_t geometryPhase = CjguiSelectionMainPhase(ctx, c, CJGUI_OWNER_TRACE_PHASE_BEGIN, 352, 0);
        NSArray<NSValue *> *candidateSelectionRects = nil;
        NSRect candidateSelectionCaret = NSZeroRect;
        CjguiPreparedTextNodeLayout *candidateSelectionLayout = longText
            ? bPreparation.sourceLayout : node.preparedTextLayout;
        // The accepted node's value can advance WITHOUT its layout being rebuilt in the same scene:
        // a public/external write publishes the new body first. Measured on the failing short-B
        // candidate (same PID/binary/ticket as the 32):
        //   CJGUI_SELECTION_GEOMETRY_MISMATCH node=107 value16=15 valueHash=967f5f93
        //       proxy16=15 proxyHash=967f5f93 layout16=14 layoutHash=423f510a firstUnlaid=14
        //   CJGUI_SELECTION_GEOMETRY reject=layout-body-mismatch
        // The node and its proxy already agreed; only the layout was one body version behind. Feeding
        // that stale layout to the geometry gate (which correctly requires the layout body to BE the
        // node body) turned a waitable "layout not caught up yet" into TEXT_SERVICE_UNSUPPORTED (32),
        // which reads as a permanent platform refusal. Build the candidate layout from the CURRENT
        // body instead: same source as the node and its proxy. CjguiPrepareTextNodeLayout returns its
        // OWN TextKit stack, so the accepted COW layout is never mutated and no version is rewritten.
        if (!longText && getenv("CJGUI_NO_CANDIDATE_REBUILD") == NULL && candidateSelectionLayout &&
            ![candidateSelectionLayout.storage.string isEqualToString:(node.value ?: @"")]) {
            NSString *candidateBody = CjguiComposableGpuTextValue(node);
            CjguiPreparedTextNodeLayout *candidateBodyLayout = CjguiPrepareTextNodeLayout(node,
                candidateBody, MAX(1.0, [ctx.view currentBackingScale]),
                CjguiComposableDecodeStyleRuns(ctx.composableTextStyleRunsRaw[@(node.node.nodeId)] ?: @""),
                ctx);
            if (candidateBodyLayout) candidateSelectionLayout = candidateBodyLayout;
        }
        // Short candidates retain the established synchronous path, but the
        // immutable selection geometry below still requires a complete source
        // map. Complete only this bounded (<1024 UTF-16) accepted layout; the
        // long-body branch must arrive here with the worker's private graph.
        if (!longText && candidateSelectionLayout &&
            candidateSelectionLayout.storage.length < 1024 &&
            candidateSelectionLayout.layoutManager.firstUnlaidCharacterIndex <
                candidateSelectionLayout.storage.length) {
            (void)CjguiTextPreparationForceCompleteLayout(candidateSelectionLayout);
        }
#ifdef CJGUI_INTERNAL_TESTING
        if (CjguiTestConsumeSelectionGeometryReject(session))
            return CJGUI_INTERNAL_RENDERER_TEXT_SERVICE_UNSUPPORTED;
#endif
        BOOL geometryReady = c.candidateSceneTransfer
            ? CjguiBuildAcceptedTextSelectionGeometry(node, candidateSelectionLayout, prepared.inputProxy, wanted,
                &candidateSelectionRects, &candidateSelectionCaret)
            : [prepared prepareSourceSelectionGeometryForNode:node layout:candidateSelectionLayout
                proxy:prepared.inputProxy selection:wanted selectionRects:&candidateSelectionRects caret:&candidateSelectionCaret];
        CjguiSelectionMainPhase(ctx, c, CJGUI_OWNER_TRACE_PHASE_END, 352, geometryPhase);
        if (!geometryReady) return CJGUI_INTERNAL_RENDERER_TEXT_SERVICE_UNSUPPORTED;
#ifdef CJGUI_INTERNAL_TESTING
        // Trigger a real captured UPDATE while this transfer is still Pending,
        // before B takes responder/ownership. Production has no branch here.
        (void)CjguiTestInjectPendingSelectionUpdate(session, o, transferId);
#endif
        // Attach and configure delegates before taking the decision lease.
        uint64_t hostPhase = CjguiSelectionMainPhase(ctx, c, CJGUI_OWNER_TRACE_PHASE_BEGIN, 353, 0);
        [prepared.inputScrollProxy removeFromSuperview];
        [o addSubview:prepared.inputScrollProxy];
        prepared.inputProxy.delegate=o;
        ((CJGuiInternalComposableInputProxy *)prepared.inputProxy).composableOverlay=o;
        BOOL hostReady = [o activateInputHost];
        CjguiSelectionMainPhase(ctx, c, CJGUI_OWNER_TRACE_PHASE_END, 353, hostPhase);
        if (!hostReady) return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        c.firstResponder=ctx.window.firstResponder;
#ifdef CJGUI_INTERNAL_TESTING
        const char *corrupt=getenv("CJGUI_TEST_SELECTION_TRANSFER_CORRUPT_B_BEFORE_VERIFY");
        if (corrupt && strcmp(corrupt,"1")==0) {
            unsetenv("CJGUI_TEST_SELECTION_TRANSFER_CORRUPT_B_BEFORE_VERIFY");
            NSRange bad=wanted; bad.location=bad.location==0?1:0;
            prepared.inputProxy.selectedRange=bad;
        }
#endif
        // These are real readbacks, all before Finalizing. Inputs during any
        // AppKit callback abort Pending and execute once against A's FIFO.
        if (!c.candidateSceneTransfer && !CjguiRebaseSelectionTransferScene(ctx, c))
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        if (!CjguiSelectionTransferSourceSceneMatches(ctx,c) || c.proxy!=o.inputProxy ||
            ![c.proxy.textStorage isEqualToAttributedString:c.aBody] ||
            !NSEqualRanges(c.proxy.selectedRange,c.aSelection) ||
            ![prepared.inputProxy.string isEqualToString:c.bBody] ||
            !NSEqualRanges(prepared.inputProxy.selectedRange,wanted) || prepared.inputProxy.hasMarkedText ||
            (longText && (prepared.inputProxy.layoutManager.firstUnlaidCharacterIndex <
                prepared.inputProxy.textStorage.length || prepared.inputProxy.textStorage != bPreparation.sourceLayout.storage)) ||
            ctx.installedRangeBasis!=c.aInstalledRangeBasis ||
            ctx.installedRangeProxyGeneration!=c.aProxyGeneration ||
            o.installedRangeSelectionRevision!=c.aSelectionRevision ||
            ctx.ownedTextSessionBindingEpoch!=c.aOwnedTextSessionBindingEpoch ||
            !CjguiInputProxyIsFirstResponder(o)) return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        CjguiInstalledRangeState *basis=c.bInputBasis;
        basis.proxy=prepared.inputProxy; basis.proxyGeneration=c.aProxyGeneration+1;
        basis.selectionRevision=c.aSelectionRevision+1;
        basis.actualSelectionStart16=(uint32_t)wanted.location;
        basis.actualSelectionEnd16=(uint32_t)NSMaxRange(wanted);
        basis.hasReceipt=YES; basis.active=YES;
        CjguiInternalSelectionTransferReceipt receipt={0};
        receipt.transferId=transferId; receipt.sceneVersion=c.bSceneVersion; receipt.bindingEpoch=c.bBindingEpoch;
        receipt.nodeId=c.bNodeId; receipt.projectionVersion=c.bProjectionVersion;
        receipt.resourceId=c.bResourceId; receipt.nodeKind=c.bNodeKind;
        receipt.selectionStart16=basis.actualSelectionStart16; receipt.selectionEnd16=basis.actualSelectionEnd16;
        receipt.selectionRevision=basis.selectionRevision; receipt.proxyGeneration=basis.proxyGeneration;
        receipt.firstResponder=1;
        *outNode=node; *outPrepared=prepared; *outRects=candidateSelectionRects;
        *outCaret=candidateSelectionCaret; *outReceipt=receipt;
        return CJGUI_INTERNAL_RENDERER_OK;
}

static void CjguiMovePreparedSelectionTransfer(CJGuiInternalSession *ctx, CjguiSelectionTransferCapsule *c,
    CJGuiInternalComposableSceneOverlay *prepared) {
    CJGuiInternalComposableSceneOverlay *o=ctx.composableSceneOverlay;
    CjguiInstalledRangeState *basis=c.bInputBasis;
        // Callback-free publication. Every released reference is also retained
        // by c/prepared; no resource retirement can run in this interval.
        [o swapPrivateInputGraphWith:prepared];
        ctx.ownedTextSessionNodeId=c.bNodeId; ctx.ownedTextSessionResourceId=c.bResourceId;
        ctx.ownedTextSessionNodeKind=c.bNodeKind; ctx.ownedTextSessionBindingEpoch=c.bBindingEpoch;
        ctx.installedRangeBasis=basis; ctx.installedRangeProvisional=nil; ctx.installedRangeRecoveryBlock=nil;
        ctx.installedRangeProxyGeneration=basis.proxyGeneration;
        o.installedRangeSelectionRevision=basis.selectionRevision;
        ctx.installedRangeBytesUsed=c.aBytesUsed-CjguiInstalledRangeStateBytes(c.aInstalledRangeBasis)+basis.sourceUtf8.length;
        ctx.installedRangeObservedAckVersion=basis.candidate.ownerVersion;
        o.sourceInputParked=NO; ctx.sourceHandoffInputBlocked=NO;
 }

CjguiInternalRendererStatus cjgui_internal_renderer_prepare_candidate_selection(uint64_t session,
    uint64_t transferId, uint64_t deadlineNs, uint8_t *outReady) {
    if (!outReady) return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    *outReady=0;
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiSelectionTransferCapsule *c=ctx.selectionTransferCapsule;
        if (!c || c.transferId!=transferId || !c.candidateSceneTransfer)
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        if (c.candidateInstallReady) { *outReady=1; return CJGUI_INTERNAL_RENDERER_OK; }
        uint8_t prepared=0;
        CjguiInternalRendererStatus status=CjguiAdvanceSelectionTransferBPreparation(ctx,c,deadlineNs,&prepared);
        if (status!=CJGUI_INTERNAL_RENDERER_OK || !prepared) return status;
        CJGuiInternalComposableSceneNode *node=nil; CJGuiInternalComposableSceneOverlay *graph=nil;
        NSArray<NSValue *> *rects=nil; NSRect caret=NSZeroRect; CjguiInternalSelectionTransferReceipt receipt={0};
        status=CjguiPrepareSelectionTransferInstallation(ctx,c,&node,&graph,&rects,&caret,&receipt);
        if (status!=CJGUI_INTERNAL_RENDERER_OK) return status;
        if (c.bBody.length>=1024) node.preparedTextLayout=c.bPreparation.sourceLayout;
        node.textSelectionRects=rects; node.textSelectionTransferId=transferId;
        if (!node.textCaretIsDeclared) node.textCaretRect=caret;
        c.preparedOverlay=graph; c.candidateReceipt=receipt;
        c.candidateSelectionRects=rects; c.candidateSelectionCaret=caret;
        c.candidateInstallReady=YES; *outReady=1;
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

static void CjguiPublishSelectionTransferReceipt(CJGuiInternalSession *ctx,
    CjguiSelectionTransferCapsule *c, CJGuiInternalComposableSceneNode *node) {
    uint64_t transferId=c.transferId; CjguiInstalledRangeState *basis=c.bInputBasis;
            ctx.selectionPaintTransferId = transferId;
            ctx.selectionPaintSessionGeneration = ctx.sessionGeneration;
            ctx.selectionPaintWindowToken = basis.candidate.windowInstanceToken;
            ctx.selectionPaintBindingEpoch = basis.candidate.bindingEpoch;
            ctx.selectionPaintProxyGeneration = basis.proxyGeneration;
            ctx.selectionPaintNativeRevision = basis.selectionRevision;
            ctx.selectionPaintInstalledScene = c.bSceneVersion;
            ctx.selectionPaintOwnerVersion = basis.candidate.ownerVersion;
            ctx.selectionPaintOwnerRevision = -1;
            ctx.selectionReceiptTransferId = transferId;
            ctx.selectionReceiptSceneVersion = c.bSceneVersion;
            ctx.selectionReceiptBindingEpoch = basis.candidate.bindingEpoch;
            ctx.selectionReceiptProxyGeneration = basis.proxyGeneration;
            ctx.selectionReceiptNativeRevision = basis.selectionRevision;
            ctx.selectionReceiptOwnerVersion = basis.candidate.ownerVersion;
            ctx.selectionReceiptOwnerRevision = -1;
            ctx.selectionReceiptFocusNodeId = c.bNodeId;
            ctx.selectionReceiptFocusResourceId = c.bResourceId;
            ctx.selectionReceiptFocusNodeKind = c.bNodeKind;
            ctx.selectionReceiptFocusSemanticId = [node.semanticId copy] ?: @"";
            ctx.selectionReceiptFocusSemanticBindingKey = [node.semanticBindingKey copy] ?: @"";
            ctx.selectionReceiptFocusSemanticIncarnation = node.node.semanticIncarnation;
            ctx.selectionPaintStagedScene = 0;
            ctx.selectionPaintPublishingScene = 0;
}

CjguiInternalRendererStatus cjgui_internal_renderer_selection_transfer_install_b(
    uint64_t session, uint64_t transferId, CjguiInternalSelectionTransferReceipt *outReceipt) {
    if (!outReceipt) return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    *outReceipt=(CjguiInternalSelectionTransferReceipt){0};
    __block uint64_t decisionBeforeNs=0, decisionAfterNs=0;
    __block BOOL traceDecision=NO;
    __block uint64_t decisionScene=0, decisionGeneration=0;
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiSelectionTransferCapsule *c=ctx.selectionTransferCapsule;
        uint64_t installPhase = CjguiSelectionMainPhase(ctx, c, CJGUI_OWNER_TRACE_PHASE_BEGIN, 337, 0);
        @try {
        CJGuiInternalComposableSceneOverlay *o=ctx.composableSceneOverlay, *prepared=nil;
        CJGuiInternalComposableSceneNode *node=nil;
        NSArray<NSValue *> *candidateSelectionRects=nil; NSRect candidateSelectionCaret=NSZeroRect;
        CjguiInternalSelectionTransferReceipt receipt={0};
        CjguiInternalRendererStatus preparedStatus=CjguiPrepareSelectionTransferInstallation(ctx,c,
            &node,&prepared,&candidateSelectionRects,&candidateSelectionCaret,&receipt);
        if (preparedStatus!=CJGUI_INTERNAL_RENDERER_OK) return preparedStatus;
        BOOL longText=c.bBody.length>=1024;
        CjguiSelectionTransferBPreparation *bPreparation=c.bPreparation;
        CjguiInstalledRangeState *basis=c.bInputBasis;
        CjguiInternalRendererStatus status=CjguiSelectionTransferBeginFinalizingWithPrecheck(session,transferId);
        if (status!=CJGUI_INTERNAL_RENDERER_OK) return status;

        CjguiPreparedTextNodeLayout *oldTargetLayout = node.preparedTextLayout;
        if (longText) {
            node.preparedTextLayout = bPreparation.sourceLayout;
            node.textMeasuredSource = c.bBody;
            node.textMeasuredWidth = NSWidth(bPreparation.sourceLayout.textRect);
            node.textMeasuredFontSize = node.node.fontSize;
            node.textMeasuredFontWeight = node.node.fontWeight;
            node.textMeasuredFontFamily = node.node.fontFamily;
            node.textMeasuredNodeKind = node.node.nodeKind;
            node.textMeasuredExtent = bPreparation.measuredExtent;
            node.textMeasureValid = YES;
        }

        CjguiMovePreparedSelectionTransfer(ctx,c,prepared);
        CjguiSelectionTransferCell *cell=&gCjguiSelectionTransferCells[session-1];
        traceDecision = getenv("CJGUI_TEXT_PREPARE_TRACE") != NULL;
        CjguiLockSelectionTransferCell(cell);
        uint64_t word=atomic_load_explicit(&cell->decision,memory_order_acquire);
        BOOL commit=CjguiSelectionTransferCellMatchesLocked(cell,session,transferId) &&
            CjguiSelectionTransferStateOf(word)==CJGUI_SELECTION_TRANSFER_FINALIZING &&
            !CjguiSelectionTransferCancelled(word);
        if (!commit) {
            [o swapPrivateInputGraphWith:prepared];
            if (longText) node.preparedTextLayout = oldTargetLayout;
            ctx.ownedTextSessionNodeId=c.aOwnedTextSessionNodeId; ctx.ownedTextSessionResourceId=c.aOwnedTextSessionResourceId;
            ctx.ownedTextSessionNodeKind=c.aOwnedTextSessionNodeKind; ctx.ownedTextSessionBindingEpoch=c.aOwnedTextSessionBindingEpoch;
            ctx.installedRangeBasis=c.aInstalledRangeBasis; ctx.installedRangeProvisional=c.aInstalledRangeProvisional;
            ctx.installedRangeRecoveryBlock=c.aInstalledRangeRecoveryBlock;
            ctx.installedRangeProxyGeneration=c.aProxyGeneration; o.installedRangeSelectionRevision=c.aSelectionRevision;
            ctx.installedRangeBytesUsed=c.aBytesUsed; ctx.installedRangeObservedAckVersion=c.aObservedAckVersion;
            o.sourceInputParked=c.aSourceInputParked; ctx.sourceHandoffInputBlocked=c.aSourceHandoffInputBlocked;
            cell->restoredProof=YES;
        }
        if (traceDecision) decisionBeforeNs=cjgui_internal_renderer_owner_clock_ns();
        atomic_store_explicit(&cell->decision,commit?CJGUI_SELECTION_TRANSFER_COMMITTED:CJGUI_SELECTION_TRANSFER_ABORTED,
            memory_order_release);
        if (traceDecision) decisionAfterNs=cjgui_internal_renderer_owner_clock_ns();
        CjguiUnlockSelectionTransferCell(cell);
        if (commit) {
            if (o.pointerCaptureContinuation) {
                (void)[o discardPointerCaptureContinuation:o.pointerCaptureGestureEpoch
                    scene:o.pointerCaptureContinuation.offer.candidateSceneVersion];
            }
            CjguiPublishSelectionTransferReceipt(ctx,c,node);
        }
        decisionScene=c.bSceneVersion;
        decisionGeneration=basis.proxyGeneration;
        if (traceDecision) fprintf(stderr,"CJGUI_SELECTION_DECISION transfer=%llu decision_before_ns=%llu decision_after_ns=%llu state=%s scene=%llu proxy_generation=%llu\n",
            (unsigned long long)transferId,(unsigned long long)decisionBeforeNs,(unsigned long long)decisionAfterNs,
            commit?"committed":"aborted",(unsigned long long)decisionScene,(unsigned long long)decisionGeneration);
        // Everything below observes a terminal decision. Cleanup/paint can
        // never downgrade an accepted owner choice or replay its body edit.
        uint64_t retirePhase = CjguiSelectionMainPhase(ctx, c, CJGUI_OWNER_TRACE_PHASE_BEGIN, 354, 0);
        uint64_t detachPhase = CjguiSelectionMainPhase(ctx, c, CJGUI_OWNER_TRACE_PHASE_BEGIN, 356, 0);
        [prepared.inputScrollProxy removeFromSuperview];
        CjguiSelectionMainPhase(ctx, c, CJGUI_OWNER_TRACE_PHASE_END, 356, detachPhase);
        uint64_t delegatePhase = CjguiSelectionMainPhase(ctx, c, CJGUI_OWNER_TRACE_PHASE_BEGIN, 357, 0);
        prepared.inputProxy.delegate=nil;
        ((CJGuiInternalComposableInputProxy *)prepared.inputProxy).composableOverlay=nil;
        CjguiSelectionMainPhase(ctx, c, CJGUI_OWNER_TRACE_PHASE_END, 357, delegatePhase);
        if (!commit) {
            CjguiSelectionMainPhase(ctx, c, CJGUI_OWNER_TRACE_PHASE_END, 354, retirePhase);
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        }
        uint64_t sparePhase = CjguiSelectionMainPhase(ctx, c, CJGUI_OWNER_TRACE_PHASE_BEGIN, 358, 0);
        if (longText) {
            CjguiTextPreparationWorkerInput *workerInput = bPreparation.workerInput;
            CjguiSelectionTransferBSpare *spare = bPreparation.reusedSpare;
            BOOL spareEligible = NO;
            if (bPreparation.reusedSpare) {
                CjguiPreparedTextNodeLayout *retiredA =
                    CjguiSelectionBRetiredAInputLayout(c, prepared, workerInput);
                spareEligible = retiredA != nil;
                if (spareEligible) spare.painter = retiredA;
            } else {
                spareEligible = CjguiSelectionBSpareLayoutMatches(bPreparation.painter, workerInput);
                if (spareEligible && !spare) spare = [CjguiSelectionTransferBSpare new];
                if (!spare) spareEligible = NO;
                if (spareEligible) spare.painter = bPreparation.painter;
            }
            if (spareEligible) {
                spare.identity = workerInput;
                spare.measuredExtent = bPreparation.measuredExtent;
                spare.inUse = NO;
            }
            pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
            CjguiTextPreparationWorkerJob *job = bPreparation.admission.textLayoutJob;
            if (job) {
                job.consumerLive = NO;
                if (spareEligible && !bPreparation.reusedSpare) {
                    spare.chargedBytes = CjguiTextPreparationReleaseSlotKeepingChargeLocked(job);
                } else {
                    CjguiTextPreparationReleaseSlotLocked(job);
                }
                bPreparation.admission.textLayoutJob = nil;
            }
            pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
            if (spareEligible && (bPreparation.reusedSpare || spare.chargedBytes)) ctx.selectionBSpare = spare;
            else if (bPreparation.reusedSpare) {
                bPreparation.reusedSpare.inUse = NO;
                CjguiDiscardSelectionBSpare(ctx);
            }
            bPreparation.sourceLayout = nil;
            bPreparation.painter = nil;
            bPreparation.preparedOverlay = nil;
            c.bPreparation = nil;
        }
        CjguiSelectionMainPhase(ctx, c, CJGUI_OWNER_TRACE_PHASE_END, 358, sparePhase);
        CjguiSelectionMainPhase(ctx, c, CJGUI_OWNER_TRACE_PHASE_END, 354, retirePhase);
        // Keep the exact installed B while its owner prefix still owes the
        // managed terminal ACK. A successor may arrive after this FFI returns,
        // including after c is released. It captures its actual B and remains
        // behind the predecessor; older A inputs retain their own coordinates.
        CJGuiInternalQueuedInteraction *caretOwner=ctx.activeCaretNavigation;
        if(c.caretInputBranch && c.caretInputBranch.valid &&
            c.caretInputBranch==ctx.caretInputBranch && c.caretInputBranch==caretOwner.caretInputBranch &&
            c.caretInputSequence==caretOwner.inputSequence && caretOwner.caretEditApplied &&
            caretOwner.caretEditAfterVersion==basis.candidate.ownerVersion &&
            caretOwner.caretInputBranch.result.acceptedVersion==caretOwner.caretEditBeforeVersion) {
            CjguiCaretInputSnapshot *installed=CjguiCaptureCaretInputSnapshot(ctx);
            if(installed && installed.candidate.nonce==transferId &&
                installed.proxyGeneration==receipt.proxyGeneration &&
                installed.selectionRevision==receipt.selectionRevision &&
                installed.acceptedVersion==caretOwner.caretEditAfterVersion &&
                [installed.body isEqualToData:basis.sourceUtf8]) {
                // The retained bytes are the immutable installed basis itself.
                installed.body=basis.sourceUtf8;
                caretOwner.caretInstalledResult=installed;
            }
        }
        *outReceipt=receipt;
        CjguiTraceSelectionTransferInstalled(ctx,c,basis,receipt.proxyGeneration,receipt.selectionRevision);
        uint64_t gpuPhase = CjguiSelectionMainPhase(ctx, c, CJGUI_OWNER_TRACE_PHASE_BEGIN, 355, 0);
        [o refreshGpuTextForActiveInput];
        CjguiSelectionMainPhase(ctx, c, CJGUI_OWNER_TRACE_PHASE_END, 355, gpuPhase);
        node.textSelectionRects = candidateSelectionRects ?: @[];
        node.textCaretRect = candidateSelectionCaret;
        node.textCaretIsDeclared = NO;
        node.textSelectionTransferId = transferId;
        o.installedSourceSelectionGeometryTransferId = transferId;
        [o resetCaretBlink]; [o setNeedsDisplay:YES];
        return CJGUI_INTERNAL_RENDERER_OK;
        } @finally {
            CjguiSelectionMainPhase(ctx, c, CJGUI_OWNER_TRACE_PHASE_END, 337, installPhase);
        }
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_ack_drag_edge_viewport(
    uint64_t session, uint64_t gesture, uint64_t node, int64_t resource,
    uint64_t binding, uint64_t identity, int64_t requestGeneration,
    int64_t requested, int64_t accepted, uint64_t scene, uint32_t phase) {
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CJGuiInternalComposableSceneOverlay *o = ctx.composableSceneOverlay;
        if (phase == 5) {
            // A terminal candidate only retires the exact phase-2 viewport
            // request it was issued for. This check precedes the general
            // identity path below, which can stop an active residence cycle.
            BOOL matchesOriginalRequest = gesture && identity && binding &&
                o.pointerCaptureActive && o.pointerCaptureGestureEpoch == gesture &&
                scene == ctx.composableSceneVersion && o.dragEdgeScrollActive &&
                o.dragEdgeScrollSource == CJGUI_DRAG_EDGE_SOURCE_POINTER_CAPTURE &&
                o.dragEdgeScrollPhase == 2 &&
                o.dragEdgeViewportIdentity == identity && o.dragEdgeViewportBinding == binding &&
                o.dragEdgeScrollOwnerNode == node && o.dragEdgeScrollOwnerResource == resource &&
                o.dragEdgeScrollRequestSceneVersion == scene &&
                o.dragEdgeScrollRequestGeneration == requestGeneration &&
                o.dragEdgeScrollExpectedOffset == requested &&
                o.dragEdgeScrollRequestAcceptedOffset == accepted;
            if (!matchesOriginalRequest) return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
            [o stopDragEdgeScroll];
            return CJGUI_INTERNAL_RENDERER_OK;
        }
        if (!gesture || !identity || !binding || !o.pointerCaptureActive ||
            o.pointerCaptureGestureEpoch != gesture || scene != ctx.composableSceneVersion)
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        if (o.dragEdgeViewportIdentity && (o.dragEdgeViewportIdentity != identity ||
            o.dragEdgeViewportBinding != binding || o.dragEdgeScrollOwnerNode != node ||
            o.dragEdgeScrollOwnerResource != resource)) {
            [o stopDragEdgeScroll]; return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        }
        o.dragEdgeViewportIdentity = identity; o.dragEdgeViewportBinding = binding;
        o.dragEdgeScrollOwnerNode = node; o.dragEdgeScrollOwnerResource = resource;
        uint32_t previousPhase = o.dragEdgeScrollPhase;
        if (phase == 4 && o.dragEdgeScrollPhase == 1) {
            // The framework consumed precise points into this binding's
            // fraction without moving its already accepted viewport. No new
            // projection or re-hit is owed; allow the next residence tick.
            if (requested != accepted) return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
            o.dragEdgeScrollPhase = 0;
        } else if (phase == 1 && o.dragEdgeScrollPhase == 1) {
            if (requested == accepted) {
                BOOL preservePressedLease = o.pointerCaptureActive &&
                    o.pointerCaptureGestureEpoch == gesture &&
                    o.dragEdgeScrollSource == CJGUI_DRAG_EDGE_SOURCE_POINTER_CAPTURE;
                [o stopDragEdgeScroll];
                if (preservePressedLease) {
                    o.pointerCaptureBoundaryStopped = YES;
                    o.pointerCaptureBoundaryGestureEpoch = gesture;
                    o.pointerCaptureBoundaryViewportIdentity = identity;
                    o.pointerCaptureBoundaryViewportBinding = binding;
                    o.pointerCaptureBoundaryViewportNode = node;
                    o.pointerCaptureBoundaryViewportResource = resource;
                    o.pointerCaptureBoundaryRequestGeneration = requestGeneration;
                    o.pointerCaptureBoundaryAcceptedOffset = accepted;
                }
                return CJGUI_INTERNAL_RENDERER_OK;
            }
            o.pointerCaptureBoundaryStopped = NO;
            o.dragEdgeScrollRequestGeneration = requestGeneration;
            o.dragEdgeScrollExpectedOffset = requested;
            o.dragEdgeScrollRequestAcceptedOffset = accepted;
            o.dragEdgeScrollRequestSceneVersion = scene;
            o.dragEdgeScrollPhase = 2;
        } else if (phase == 2 && o.dragEdgeScrollPhase == 2) {
            if (requestGeneration != o.dragEdgeScrollRequestGeneration) {
                [o stopDragEdgeScroll]; return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
            }
            if (accepted == o.dragEdgeScrollExpectedOffset && requested == accepted) {
                CJGuiInternalComposableSceneNode *target = [o capturedPointerNode];
                NSPoint point = NSMakePoint(o.dragEdgeScrollPointX, o.dragEdgeScrollPointY);
                if (!target || !CjguiEnqueueComposableCapturedPointerInteraction(ctx,
                    CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_UPDATE,
                    target, point, gesture)) { [o stopDragEdgeScroll]; return CJGUI_INTERNAL_RENDERER_SCENE_STALE; }
                o.dragEdgeScrollPhase = 3;
                o.dragEdgeSelectionTransfer = 0;
                o.pointerCaptureBoundaryStopped = NO;
            }
        }
        if (getenv("CJGUI_DRAG_EDGE_TRACE"))
            fprintf(stderr, "CJGUI_POINTER_EDGE_SCROLL_ACK gesture=%llu phase=%u before=%u after=%u active=%d owner=%llu resource=%lld binding=%llu viewport=%llu generation=%lld requested=%lld accepted=%lld scene=%llu\n",
                (unsigned long long)gesture, phase, previousPhase, o.dragEdgeScrollPhase,
                (int)o.dragEdgeScrollActive, (unsigned long long)node, (long long)resource,
                (unsigned long long)binding, (unsigned long long)identity,
                (long long)requestGeneration, (long long)requested, (long long)accepted,
                (unsigned long long)scene);
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_offer_pointer_capture_continuation(
    uint64_t session, const CjguiInternalPointerCaptureContinuationOffer *offer) {
    if (!offer) return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    CjguiInternalPointerCaptureContinuationOffer frozen = *offer;
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        if (!ctx.composableSceneOverlay) return CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED;
        return [ctx.composableSceneOverlay offerPointerCaptureContinuation:&frozen];
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_complete_pointer_capture_continuation(
    uint64_t session, uint64_t gestureEpoch, uint64_t candidateSceneVersion,
    uint64_t selectionTransferId, int64_t ownerVersion, int64_t ownerRevision) {
    if (!gestureEpoch || !candidateSceneVersion || !selectionTransferId || ownerVersion < 0 || ownerRevision < 0)
        return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        if (!ctx.composableSceneOverlay) return CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED;
        return [ctx.composableSceneOverlay completePointerCaptureContinuation:gestureEpoch
            scene:candidateSceneVersion transfer:selectionTransferId ownerVersion:ownerVersion
            ownerRevision:ownerRevision];
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_discard_pointer_capture_continuation(
    uint64_t session, uint64_t gestureEpoch, uint64_t candidateSceneVersion) {
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        if (!ctx.composableSceneOverlay) return CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED;
        return [ctx.composableSceneOverlay discardPointerCaptureContinuation:gestureEpoch
            scene:candidateSceneVersion];
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_finish_selection_paint_publication(
    uint64_t session, uint64_t transferId, uint64_t generation, uint64_t binding,
    uint64_t proxyGeneration, uint64_t nativeRevision, int64_t ownerVersion,
    int64_t ownerRevision, uint8_t proxyOnly, uint8_t *outNeedsProjection) {
    if (!outNeedsProjection) return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    *outNeedsProjection = 0;
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiInstalledRangeState *basis = ctx.installedRangeBasis;
        if (!transferId || ctx.selectionPaintTransferId != transferId ||
            generation != ctx.sessionGeneration || generation != ctx.selectionPaintSessionGeneration ||
            binding != ctx.selectionPaintBindingEpoch || proxyGeneration != ctx.selectionPaintProxyGeneration ||
            nativeRevision != ctx.selectionPaintNativeRevision || ownerVersion != ctx.selectionPaintOwnerVersion ||
            ownerRevision < 0 || !basis.hasReceipt || basis.selectionTransferId != transferId ||
            basis.proxyGeneration != proxyGeneration || basis.selectionRevision != nativeRevision)
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        ctx.selectionPaintOwnerRevision = ownerRevision;
        if (ctx.selectionReceiptTransferId == transferId &&
            ctx.selectionReceiptOwnerVersion == ownerVersion &&
            ctx.selectionReceiptBindingEpoch == binding &&
            ctx.selectionReceiptProxyGeneration == proxyGeneration &&
            ctx.selectionReceiptNativeRevision == nativeRevision) {
            ctx.selectionReceiptOwnerRevision = ownerRevision;
        }
        CJGuiInternalComposableSceneOverlay *edge = ctx.composableSceneOverlay;
        if (edge.dragEdgeScrollActive && edge.pointerCaptureActive && edge.dragEdgeScrollPhase == 3) {
            edge.dragEdgeSelectionTransfer = transferId;
            edge.dragEdgeSelectionAfterFrame = ctx.view.frameIndex;
            if (getenv("CJGUI_DRAG_EDGE_TRACE"))
                fprintf(stderr, "CJGUI_POINTER_EDGE_SCROLL_SELECTION gesture=%llu transfer=%llu owner_version=%lld owner_revision=%lld frame=%llu\n",
                    (unsigned long long)edge.pointerCaptureGestureEpoch, (unsigned long long)transferId,
                    (long long)ownerVersion, (long long)ownerRevision,
                    (unsigned long long)ctx.view.frameIndex);
        }
        BOOL otherDeclaredSelection = NO;
        for (CJGuiInternalComposableSceneNode *node in ctx.composableNodes) {
            if (node.node.nodeId != basis.candidate.nodeId && node.textDeclaredSelectionDecorations.count > 0) {
                otherDeclaredSelection = YES; break;
            }
        }
        if (proxyOnly && !otherDeclaredSelection) {
            ctx.selectionPaintTransferId = 0;
            ctx.selectionPaintStagedScene = 0;
            [ctx.composableSceneOverlay setNeedsDisplay:YES];
        } else {
            *outNeedsProjection = 1;
        }
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_stage_selection_paint_publication(
    uint64_t session, uint64_t transferId, uint64_t generation, uint64_t binding,
    int64_t ownerVersion, int64_t ownerRevision, uint64_t sceneVersion) {
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        // A proxy-only publication has already retired this paint obligation.
        if (!ctx.selectionPaintTransferId) return CJGUI_INTERNAL_RENDERER_OK;
        if (ctx.selectionPaintTransferId != transferId || generation != ctx.sessionGeneration ||
            generation != ctx.selectionPaintSessionGeneration || binding != ctx.selectionPaintBindingEpoch ||
            ownerVersion != ctx.selectionPaintOwnerVersion || ownerRevision != ctx.selectionPaintOwnerRevision ||
            ownerRevision < 0 || sceneVersion <= ctx.selectionPaintInstalledScene ||
            ctx.stagedComposableSceneVersion != sceneVersion)
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        ctx.selectionPaintStagedScene = sceneVersion;
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_selection_transfer_restore_a(
    uint64_t session, uint64_t transferId) {
    if (!transferId) return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiSelectionTransferCapsule *capsule = ctx.selectionTransferCapsule;
        CjguiCancelSelectionTransferBPreparation(capsule);
        CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
        uint32_t state = CJGUI_SELECTION_TRANSFER_EMPTY;
        if (!capsule || capsule.transferId != transferId || ctx.selectionTransferId != transferId ||
            !overlay || capsule.overlay != overlay || capsule.window != ctx.window ||
            !CjguiSelectionTransferCellState(session, transferId, &state, NULL) ||
            (state != CJGUI_SELECTION_TRANSFER_FINALIZING && state != CJGUI_SELECTION_TRANSFER_RECOVERY_BLOCKED) ||
            !capsule.proxy || capsule.proxy != overlay.inputProxy ||
            ctx.composableSceneVersion != capsule.aSceneVersion ||
            (capsule.aNodeId && CjguiSelectionTransferFindNodeIndex(overlay, capsule.aNodeId, capsule.aProjectionVersion,
                capsule.aResourceId, capsule.aNodeKind) == NSNotFound)) {
            (void)cjgui_internal_renderer_selection_transfer_recovery_blocked(session, transferId);
            if (ctx.selectionTransferCapsule) ctx.selectionTransferCapsule.recoveryFailed = YES;
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        }
        NSInteger activeIndex = CjguiSelectionTransferFindNodeIndex(overlay, capsule.aNodeId,
            capsule.aProjectionVersion, capsule.aResourceId, capsule.aNodeKind);
        overlay.applyingProjection = YES;
        CjguiRestorePrivateFields(capsule.proxy,capsule.aProxyFields);
        CjguiRestorePrivateFields(capsule.proxy.textContainer,capsule.aContainerFields);
        CjguiRestorePrivateFields(overlay.inputScrollProxy,capsule.aScrollFields);
        [capsule.proxy.textStorage setAttributedString:capsule.aBody ?: [[NSAttributedString alloc] initWithString:@""]];
        [capsule.proxy setSelectedRange:capsule.aSelection];
        overlay.activeNodeIndex = activeIndex;
        overlay.activeNodeId = capsule.aNodeId;
        overlay.activeProjectionVersion = capsule.aProjectionVersion;
        overlay.activeNodeResourceId = capsule.aResourceId;
        overlay.activeNodeKind = capsule.aNodeKind;
        ctx.installedRangeBasis = capsule.aInstalledRangeBasis;
        ctx.installedRangeProvisional = capsule.aInstalledRangeProvisional;
        ctx.installedRangeRecoveryBlock = capsule.aInstalledRangeRecoveryBlock;
        ctx.installedRangeProxyGeneration = capsule.aProxyGeneration;
        overlay.installedRangeSelectionRevision = capsule.aSelectionRevision;
        ctx.installedRangeBytesUsed = capsule.aBytesUsed;
        ctx.installedRangeNextSequence = capsule.aNextSequence;
        ctx.installedRangeLocalTailSequence = capsule.aLocalTailSequence;
        ctx.installedRangeObservedAckSequence = capsule.aObservedAckSequence;
        ctx.installedRangeObservedAckVersion = capsule.aObservedAckVersion;
        ctx.ownedTextSessionBindingEpoch = capsule.aOwnedTextSessionBindingEpoch;
        ctx.ownedTextSessionNodeId = capsule.aOwnedTextSessionNodeId;
        ctx.ownedTextSessionResourceId = capsule.aOwnedTextSessionResourceId;
        ctx.ownedTextSessionNodeKind = capsule.aOwnedTextSessionNodeKind;
        CjguiRestorePrivateFields(overlay,capsule.aOverlayFields);
        overlay.multilineScrollOffsets=capsule.aOffsets;
        overlay.multilineLayoutCache=capsule.aLayoutCache;
        overlay.multilineLayoutCacheOrder=capsule.aLayoutOrder;
        overlay.sourceInputParked = capsule.aSourceInputParked;
        ctx.sourceHandoffInputBlocked = capsule.aSourceHandoffInputBlocked;
        // A transfer is captured only while this very proxy is the responder;
        // B uses the same proxy. Avoid a fallible no-op responder transition
        // during rollback, and retry only if an observed identity changed.
        if (ctx.window.firstResponder != capsule.firstResponder)
            (void)[ctx.window makeFirstResponder:capsule.firstResponder];
        overlay.applyingProjection = NO;
        NSData *actual = [capsule.proxy.string dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
        BOOL restored = actual && [capsule.proxy.textStorage isEqualToAttributedString:capsule.aBody] &&
            [capsule.proxy.typingAttributes isEqualToDictionary:capsule.aProxyFields[@"typingAttributes"]] &&
            [CjguiCapturePrivateFields(capsule.proxy.textContainer,@[@"containerSize", @"maximumNumberOfLines", @"lineBreakMode", @"lineFragmentPadding", @"widthTracksTextView", @"heightTracksTextView"])
                isEqualToDictionary:capsule.aContainerFields] &&
            NSEqualRanges(capsule.proxy.selectedRange, capsule.aSelection) &&
            overlay.activeNodeId == capsule.aNodeId && overlay.activeProjectionVersion == capsule.aProjectionVersion &&
            overlay.activeNodeResourceId == capsule.aResourceId && overlay.activeNodeKind == capsule.aNodeKind &&
            ctx.window.firstResponder == capsule.firstResponder;
        if (!restored) {
            (void)cjgui_internal_renderer_selection_transfer_recovery_blocked(session, transferId);
            capsule.recoveryFailed = YES;
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        }
        capsule.recoveryFailed = NO;
        CjguiSelectionTransferCell *cell = &gCjguiSelectionTransferCells[session - 1];
        CjguiLockSelectionTransferCell(cell);
        if (CjguiSelectionTransferCellMatchesLocked(cell, session, transferId)) cell->restoredProof = YES;
        CjguiUnlockSelectionTransferCell(cell);
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

static uint64_t CjguiSelectionTransferInputCost(uint32_t kind, id payload) {
    if (kind == 1 && [payload isKindOfClass:[NSEvent class]]) {
        NSEvent *event = payload;
        NSString *characters = event.characters ?: @"";
        return 256u + [characters lengthOfBytesUsingEncoding:NSUTF8StringEncoding];
    }
    if ([payload isKindOfClass:[NSString class]])
        return [(NSString *)payload lengthOfBytesUsingEncoding:NSUTF8StringEncoding];
    if ([payload isKindOfClass:[NSAttributedString class]]) {
        NSAttributedString *text = payload;
        return [text.string lengthOfBytesUsingEncoding:NSUTF8StringEncoding] + text.length * 32u;
    }
    return UINT64_MAX;
}

// Bounded facts precede PKEQ holding; identity stays on the actual NSEvent
// through only the replay already permitted by the original transfer proof.
static char gCjguiEarlyKeyIdentityKey;
static uint64_t gCjguiEarlyKeyNextIdentity = 1;
static uint32_t gCjguiEarlyKeyRecordCount;
static void CjguiEarlyKeyTrace(CJGuiInternalSession *ctx, NSEvent *event,
    const char *phase, uint32_t disposition) {
    if (!getenv("CJGUI_EARLY_KEY_TRACE") || !ctx || ![event isKindOfClass:[NSEvent class]] ||
        (event.type != NSEventTypeKeyDown && event.type != NSEventTypeKeyUp) ||
        gCjguiEarlyKeyRecordCount >= 512) return;
    NSNumber *identity = objc_getAssociatedObject(event, &gCjguiEarlyKeyIdentityKey);
    if (!identity) {
        identity = @(gCjguiEarlyKeyNextIdentity++);
        objc_setAssociatedObject(event, &gCjguiEarlyKeyIdentityKey, identity, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    ++gCjguiEarlyKeyRecordCount;
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    fprintf(stderr, "CJGUI_EARLY_KEY pid=%d session=%llu received=%llu phase=%s disposition=%u "
        "timestamp=%.9f type=%lu key=%u flags=%llu window=%ld target_window=%ld first=%d "
        "scene=%llu transfer=%llu installed=%llu proxy=%llu selection=%llu binding=%llu retained=%lu\n",
        getpid(), (unsigned long long)ctx.rendererSessionToken, identity.unsignedLongLongValue,
        phase, disposition, event.timestamp, (unsigned long)event.type, event.keyCode,
        (unsigned long long)event.modifierFlags, (long)event.windowNumber, (long)ctx.window.windowNumber,
        CjguiInputProxyIsFirstResponder(overlay), (unsigned long long)ctx.composableSceneVersion,
        (unsigned long long)ctx.selectionTransferId, (unsigned long long)ctx.selectionReceiptTransferId,
        (unsigned long long)ctx.installedRangeProxyGeneration,
        (unsigned long long)overlay.installedRangeSelectionRevision,
        (unsigned long long)ctx.selectionReceiptBindingEpoch,
        (unsigned long)ctx.selectionTransferCapsule.retainedInputs.count);
}

@interface CJGuiInternalWindow : NSWindow
@property(nonatomic, weak) CJGuiInternalSession *cjguiSession;
@end
@implementation CJGuiInternalWindow
- (void)sendEvent:(NSEvent *)event {
    CjguiEarlyKeyTrace(self.cjguiSession, event, "window_receive", 0);
    [super sendEvent:event];
    CjguiEarlyKeyTrace(self.cjguiSession, event, "window_return", 0);
}
@end

static BOOL CjguiSelectionTransferRetainInput(CJGuiInternalSession *ctx, uint32_t kind,
    id payload, NSRange selectedRange, NSRange replacementRange) {
    CjguiSelectionTransferCapsule *capsule = ctx.selectionTransferCapsule;
    if (!capsule || !ctx.selectionTransferId || capsule.transferId != ctx.selectionTransferId || !payload)
        return NO;
    uint32_t state = CJGUI_SELECTION_TRANSFER_EMPTY;
    if (!CjguiSelectionTransferCellState(ctx.rendererSessionToken, capsule.transferId, &state, NULL) ||
        (state != CJGUI_SELECTION_TRANSFER_FINALIZING && state != CJGUI_SELECTION_TRANSFER_RECOVERY_BLOCKED))
        return NO;
    uint64_t cost = CjguiSelectionTransferInputCost(kind, payload);
    if (cost == UINT64_MAX || capsule.retainedInputs.count >= kCjguiSelectionTransferRetainedInputCapacity ||
        cost > kCjguiSelectionTransferRetainedInputByteCapacity -
            MIN(capsule.retainedInputBytes, (uint64_t)kCjguiSelectionTransferRetainedInputByteCapacity)) {
        capsule.recoveryFailed = YES;
        return NO;
    }
    if (cjgui_internal_renderer_selection_transfer_retain(ctx.rendererSessionToken, capsule.transferId) !=
        CJGUI_INTERNAL_RENDERER_OK) return NO;
    CjguiSelectionTransferRetainedInput *input = [CjguiSelectionTransferRetainedInput new];
    input.kind = kind;
    if (kind == 1) input.payload = payload;
    else if ([payload isKindOfClass:[NSAttributedString class]]) input.payload = [payload copy];
    else if ([payload conformsToProtocol:@protocol(NSCopying)]) input.payload = [payload copy];
    else input.payload = payload;
    input.selectedRange = selectedRange;
    input.replacementRange = replacementRange;
    // The temporary B installation must never become an input basis. Queries
    // and callbacks during the decision still belong to the captured A.
    input.baseSelection = capsule.aSelection;
    [capsule.retainedInputs addObject:input];
    capsule.retainedInputBytes += cost;
    if (kind == 1) CjguiEarlyKeyTrace(ctx, payload, "transfer_retained", state);
    return YES;
}

CjguiInternalRendererStatus cjgui_internal_renderer_bind_caret_selection_transfer(
    uint64_t session,uint64_t transferId,uint64_t generation,
    uint64_t sequence,uint64_t previousSequence) {
    return CjguiInstalledRangeRunOnMain(session,^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiSelectionTransferCapsule *capsule=ctx.selectionTransferCapsule;
        CJGuiInternalQueuedInteraction *active=ctx.activeCaretNavigation;
        CjguiCaretInputBranch *branch=active.caretInputBranch;
        CjguiCaretInputSnapshot *source=branch.result;
        uint32_t state=0;
        if(!capsule || capsule.transferId!=transferId || ctx.selectionTransferId!=transferId ||
            !active || !branch.valid || ctx.caretInputBranch!=branch ||
            generation!=ctx.sessionGeneration || active.inputSessionGeneration!=generation ||
            !sequence || active.inputSequence!=sequence || active.inputPreviousSequence!=previousSequence ||
            branch.settledSequence!=previousSequence || previousSequence==UINT64_MAX ||
            sequence!=previousSequence+1 || !CjguiCaretSnapshotMatchesActual(ctx,source) ||
            capsule.proxy!=source.proxy || capsule.aProxyGeneration!=source.proxyGeneration ||
            capsule.aSelectionRevision!=source.selectionRevision ||
            capsule.aOwnedTextSessionBindingEpoch!=source.candidate.bindingEpoch ||
            capsule.aNodeId!=source.candidate.nodeId || capsule.aResourceId!=source.candidate.resourceId ||
            capsule.aObservedAckSequence!=source.acceptedSequence ||
            capsule.aObservedAckVersion!=source.acceptedVersion ||
            (active.caretEditApplied && (!capsule.bInputBasis ||
                capsule.bInputBasis.candidate.ownerVersion!=active.caretEditAfterVersion ||
                capsule.bInputBasis.candidate.contextEpoch!=source.candidate.contextEpoch ||
                capsule.bInputBasis.candidate.windowInstanceToken!=source.candidate.windowInstanceToken)) ||
            !NSEqualRanges(capsule.aSelection,source.selection) ||
            !CjguiSelectionTransferCellState(session,transferId,&state,NULL) ||
            state!=CJGUI_SELECTION_TRANSFER_PREPARING)
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        if(capsule.caretInputBranch &&
            (capsule.caretInputBranch!=branch || capsule.caretInputSequence!=sequence))
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        capsule.caretInputBranch=branch;capsule.caretInputSequence=sequence;
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

static BOOL CjguiPendingSelectionInputFollowsCaretOwner(CJGuiInternalSession *ctx,
    CjguiSelectionTransferCapsule *capsule,uint32_t kind,id payload) {
    CJGuiInternalQueuedInteraction *active=ctx.activeCaretNavigation;
    CjguiCaretInputBranch *branch=capsule.caretInputBranch;
    if(!branch || !branch.valid || branch!=ctx.caretInputBranch || branch!=active.caretInputBranch ||
        capsule.caretInputSequence!=active.inputSequence ||
        active.inputSessionGeneration!=ctx.sessionGeneration ||
        branch.lastProducedSequence<=branch.settledSequence ||
        !CjguiCaretSnapshotMatchesActual(ctx,branch.result)) return NO;
    if(kind==2 || kind==3) return YES; // insert/marked callbacks retain their actual source below.
    if(kind==5 && [payload isEqual:@"selectAll"] &&
        ctx.composableSceneOverlay.activeNodeKind==CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT)
        return YES;
    if(kind!=1 || ![payload isKindOfClass:[NSEvent class]]) return NO;
    NSEvent *event=payload;
    // An ordinary declared Undo/Redo is the same relative owner FIFO as its
    // predecessor. Keep it behind that command's bound Pending installation;
    // unrelated command/control/option actions still supersede the choice.
    if(event.type==NSEventTypeKeyDown && event.keyCode==6 &&
        (event.modifierFlags & NSEventModifierFlagCommand) &&
        !(event.modifierFlags & (NSEventModifierFlagControl | NSEventModifierFlagOption))) {
        NSString *history=(event.modifierFlags & NSEventModifierFlagShift)
            ? @"shortcut:shift+command+z" : @"shortcut:command+z";
        if(CjguiComposableActiveScopeDeclaresShortcut(ctx,history))return YES;
    }
    if((event.modifierFlags & (NSEventModifierFlagCommand | NSEventModifierFlagControl))!=0)
        return NO;
    // Relative arrows AND the delete keys join the native caret FIFO: both are
    // ordinary NAVIGATE intents whose target caret is exactly the dequeued
    // navigation this installation belongs to, so neither may cancel it.
    // Printable/line-break input reaches insertText/setMarkedText, which
    // reserves its bounded After copy before mutating any proxy. Other actions
    // still supersede this choice, and an unbound (pointer/external) choice is
    // refused above, so this cannot certify a selection nobody asked for.
    return (event.keyCode>=123 && event.keyCode<=126) ||
        event.keyCode==51 || event.keyCode==117 ||
        CjguiEventCanProduceOrdinaryTextRange(event);
}

// Returns YES when this producer must stop before changing the A/B proxy.
// The atomic cell orders ordinary input against Finalizing; a retained payload
// is kept on the main-thread capsule and carries one native reference until
// replay has been dispatched after a verified A restoration.
static BOOL CjguiSelectionTransferDeferNativeInput(CJGuiInternalSession *ctx, uint32_t kind,
    id payload, NSRange selectedRange, NSRange replacementRange) {
    if (!ctx || !ctx.selectionTransferId) return NO;
    CjguiSelectionTransferCapsule *capsule = ctx.selectionTransferCapsule;
    if (!capsule || capsule.transferId != ctx.selectionTransferId) return NO;
    CjguiOwnerSelectionHandoff *ownerH=capsule.ownerHandoff;
    if(ownerH.valid && ownerH==ctx.ownerSelectionHandoff && !ownerH.completed) {
        BOOL follows=(kind==2 || kind==3);
        if(kind==5 && [payload isEqual:@"selectAll"] &&
            ctx.composableSceneOverlay.activeNodeKind==CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT &&
            CjguiInstalledRangeBasisMatchesActual(ctx,ctx.composableSceneOverlay)) follows=YES;
        if(kind==1 && [payload isKindOfClass:[NSEvent class]]) {
            NSEvent *key=payload;
            follows=key.type==NSEventTypeKeyDown &&
                !(key.modifierFlags&(NSEventModifierFlagCommand|NSEventModifierFlagControl)) &&
                ((key.keyCode>=123 && key.keyCode<=126) || key.keyCode==51 || key.keyCode==117 ||
                 CjguiEventCanProduceOrdinaryTextRange(key));
        }
        uint32_t rootState=0;
        if(follows && CjguiSelectionTransferCellState(ctx.rendererSessionToken,capsule.transferId,&rootState,NULL) &&
            rootState==CJGUI_SELECTION_TRANSFER_PENDING)return NO;
        if(!follows)CjguiRetireOwnerHandoff(ctx,ownerH,"unrelated_native_choice");
    }
    uint32_t prefixState=0;
    if(CjguiSelectionTransferCellState(ctx.rendererSessionToken,ctx.selectionTransferId,&prefixState,NULL) &&
        prefixState==CJGUI_SELECTION_TRANSFER_PENDING &&
        CjguiPendingSelectionInputFollowsCaretOwner(ctx,capsule,kind,payload)) return NO;
    uint32_t admission = CJGUI_SELECTION_INPUT_STALE;
    CjguiInternalRendererStatus status = cjgui_internal_renderer_selection_transfer_admit_input(
        ctx.rendererSessionToken, ctx.selectionTransferId, &admission);
    if (status != CJGUI_INTERNAL_RENDERER_OK) return NO;
    if (admission == CJGUI_SELECTION_INPUT_ALLOW) {
        // Pending was atomically aborted before this producer edits A. Retire
        // B immediately on main; a later prepare/install call cannot revive it.
        CjguiCancelSelectionTransferBPreparation(capsule);
        return NO;
    }
    if (admission == CJGUI_SELECTION_INPUT_RETAINED_CANCEL) {
        return CjguiSelectionTransferRetainInput(ctx, kind, payload, selectedRange, replacementRange);
    }
    if (admission == CJGUI_SELECTION_INPUT_RECOVERY_BLOCKED) {
        return CjguiSelectionTransferRetainInput(ctx, kind, payload, selectedRange, replacementRange);
    }
    return NO;
}

CjguiInternalRendererStatus cjgui_internal_renderer_selection_transfer_replay_input(
    uint64_t session, uint64_t transferId) {
    if (!transferId) return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiSelectionTransferCapsule *capsule = ctx.selectionTransferCapsule;
        CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
        if (!capsule || capsule.transferId != transferId || ctx.selectionTransferId != transferId ||
            !overlay || capsule.overlay != overlay || capsule.proxy != overlay.inputProxy ||
            capsule.recoveryFailed ||
            CjguiSelectionTransferCellState(session, transferId, NULL, NULL) == NO)
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        uint32_t state = CJGUI_SELECTION_TRANSFER_EMPTY;
        if (!CjguiSelectionTransferCellState(session, transferId, &state, NULL) ||
            state != CJGUI_SELECTION_TRANSFER_ABORTED)
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        CjguiCancelSelectionTransferBPreparation(capsule);
        // Pending can be defeated by an A input which is then legally handled.
        // With nothing held, retiring a decision must not restore or compare
        // away that newer input. No proxy mutation occurs in this branch.
        if (capsule.retainedInputs.count == 0) {
            if (capsule.preparedOverlay && capsule.preparedOverlay.inputProxy != overlay.inputProxy) {
                [capsule.preparedOverlay.inputScrollProxy removeFromSuperview];
                capsule.preparedOverlay.inputProxy.delegate=nil;
                ((CJGuiInternalComposableInputProxy *)capsule.preparedOverlay.inputProxy).composableOverlay=nil;
            }
            ctx.selectionTransferCapsule = nil;
            ctx.selectionTransferId = 0;
            return cjgui_internal_renderer_selection_transfer_release(session, transferId);
        }
        if (ctx.composableSceneVersion != capsule.aSceneVersion ||
            overlay.activeNodeId != capsule.aNodeId || overlay.activeProjectionVersion != capsule.aProjectionVersion ||
            overlay.activeNodeResourceId != capsule.aResourceId || overlay.activeNodeKind != capsule.aNodeKind ||
            ctx.window.firstResponder != capsule.firstResponder ||
            !NSEqualRanges(capsule.proxy.selectedRange, capsule.aSelection))
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        NSData *actual = [capsule.proxy.string dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
        NSData *expected = [capsule.aBody.string dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
        if (!actual || !expected || ![actual isEqualToData:expected])
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        for (CjguiSelectionTransferRetainedInput *input in [capsule.retainedInputs copy]) {
            if (input.kind == 1) CjguiEarlyKeyTrace(ctx, input.payload, "transfer_replay", state);
            if (input.kind == 1 && [input.payload isKindOfClass:[NSEvent class]]) {
                [NSApp sendEvent:(NSEvent *)input.payload];
            } else if (input.kind == 2) {
                [capsule.proxy setSelectedRange:input.baseSelection];
                [capsule.proxy insertText:input.payload replacementRange:input.replacementRange];
            } else if (input.kind == 3) {
                [capsule.proxy setSelectedRange:input.baseSelection];
                [capsule.proxy setMarkedText:input.payload selectedRange:input.selectedRange
                    replacementRange:input.replacementRange];
            } else if (input.kind == 4) {
                [capsule.proxy setSelectedRange:input.baseSelection];
                [capsule.proxy insertText:input.payload replacementRange:input.replacementRange];
            } else if (input.kind == 5) {
                [capsule.proxy selectAll:nil];
            } else {
                return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
            }
            (void)cjgui_internal_renderer_selection_transfer_release(session, transferId);
        }
        [capsule.retainedInputs removeAllObjects];
        capsule.retainedInputBytes = 0;
        if (capsule.preparedOverlay && capsule.preparedOverlay.inputProxy != ctx.composableSceneOverlay.inputProxy) {
            [capsule.preparedOverlay.inputScrollProxy removeFromSuperview];
            capsule.preparedOverlay.inputProxy.delegate=nil;
            ((CJGuiInternalComposableInputProxy *)capsule.preparedOverlay.inputProxy).composableOverlay=nil;
        }
        ctx.selectionTransferCapsule = nil;
        ctx.selectionTransferId = 0;
        (void)cjgui_internal_renderer_selection_transfer_release(session, transferId); // native capsule reference
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_selection_transfer_discard_capsule(
    uint64_t session, uint64_t transferId) {
    if (!transferId) return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiSelectionTransferCapsule *capsule = ctx.selectionTransferCapsule;
        uint64_t discardPhase = CjguiSelectionMainPhase(ctx, capsule, CJGUI_OWNER_TRACE_PHASE_BEGIN, 338, 0);
        @try {
        uint32_t state = CJGUI_SELECTION_TRANSFER_EMPTY;
        if (!capsule || capsule.transferId != transferId || ctx.selectionTransferId != transferId ||
            !CjguiSelectionTransferCellState(session, transferId, &state, NULL) ||
            state != CJGUI_SELECTION_TRANSFER_COMMITTED || capsule.retainedInputs.count != 0)
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        CjguiCancelSelectionTransferBPreparation(capsule);
        if (capsule.preparedOverlay && capsule.preparedOverlay.inputProxy != ctx.composableSceneOverlay.inputProxy) {
            [capsule.preparedOverlay.inputScrollProxy removeFromSuperview];
            capsule.preparedOverlay.inputProxy.delegate=nil;
            ((CJGuiInternalComposableInputProxy *)capsule.preparedOverlay.inputProxy).composableOverlay=nil;
        }
        ctx.selectionTransferCapsule = nil;
        ctx.selectionTransferId = 0;
        return cjgui_internal_renderer_selection_transfer_release(session, transferId);
        } @finally {
            CjguiSelectionMainPhase(ctx, capsule, CJGUI_OWNER_TRACE_PHASE_END, 338, discardPhase);
        }
    });
}


CjguiInternalRendererStatus cjgui_internal_renderer_installed_range_active_receipt(
    uint64_t session, uint64_t nonce, CjguiInternalInstalledRangeReceipt *outReceipt) {
    if (!nonce || !outReceipt) return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    memset(outReceipt, 0, sizeof(*outReceipt));
    return CjguiInstalledRangeRunOnMain(session, ^CjguiInternalRendererStatus(CJGuiInternalSession *ctx) {
        CjguiInstalledRangeState *state = ctx.installedRangeBasis;
        CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
        if (!state || state.candidate.nonce != nonce || !state.active || state.chainClosed ||
            !overlay || !CjguiInstalledRangeBasisMatchesActual(ctx, overlay) ||
            ctx.installedRangeReservation || ctx.claimedInstalledRangeIntent || ctx.pumpedInstalledRangeIntent ||
            ctx.installedRangeLocalTailSequence != ctx.installedRangeObservedAckSequence ||
            overlay.inputProxy.hasMarkedText || overlay.compositionTerminalInFlight ||
            overlay.sourceInputParked || overlay.installedRangeSelectionRevision == UINT64_MAX)
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        NSData *actual = [overlay.inputProxy.string dataUsingEncoding:NSUTF8StringEncoding
            allowLossyConversion:NO];
        if (!actual || ![actual isEqualToData:state.sourceUtf8] ||
            state.candidate.sourceEndByte < state.candidate.sourceStartByte ||
            state.candidate.sourceEndByte - state.candidate.sourceStartByte != actual.length)
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        for (CJGuiInternalQueuedInteraction *queued in ctx.pendingInteractions) {
            if (CjguiQueuedCaretSuccessorOfInflight(ctx,queued)) continue;
            if (queued.nodeId == state.candidate.nodeId && queued.resourceId == state.candidate.resourceId &&
                queued.projectionVersion == state.candidate.installedSceneVersion &&
                (queued.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_CHANGED ||
                 queued.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_SELECTION_CHANGED ||
                 queued.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_RANGE_CHANGED ||
                 queued.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_COMPOSITION ||
                 queued.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_NAVIGATE))
                return CJGUI_INTERNAL_RENDERER_PRESENT_PENDING;
        }
        CjguiInternalInstalledRangeCandidate c = state.candidate;
        outReceipt->nonce = c.nonce;
        outReceipt->rendererSessionGeneration = c.rendererSessionGeneration;
        outReceipt->windowInstanceToken = c.windowInstanceToken;
        outReceipt->bindingEpoch = c.bindingEpoch;
        outReceipt->contextEpoch = c.contextEpoch;
        outReceipt->mirrorRevision = c.mirrorRevision;
        outReceipt->ownerVersion = c.ownerVersion;
        outReceipt->installedSceneVersion = c.installedSceneVersion;
        outReceipt->nodeId = c.nodeId;
        outReceipt->resourceId = c.resourceId;
        outReceipt->sourceStartByte = c.sourceStartByte;
        outReceipt->sourceEndByte = c.sourceEndByte;
        outReceipt->proxyGeneration = state.proxyGeneration;
        outReceipt->selectionRevision = overlay.installedRangeSelectionRevision;
        outReceipt->actualSelectionStart16 = (uint32_t)MIN(overlay.inputProxy.selectedRange.location, UINT32_MAX);
        outReceipt->actualSelectionEnd16 = (uint32_t)MIN(NSMaxRange(overlay.inputProxy.selectedRange), UINT32_MAX);
        outReceipt->acceptedSequence = ctx.installedRangeObservedAckSequence;
        outReceipt->acceptedVersion = ctx.installedRangeObservedAckVersion >= 0
            ? ctx.installedRangeObservedAckVersion : c.ownerVersion;
        return CJGUI_INTERNAL_RENDERER_OK;
    });
}


@implementation CJGuiInternalComposableSceneOverlay

static CJGuiInternalComposableSceneNode *CjguiPointerContinuationFindNode(
    NSArray<CJGuiInternalComposableSceneNode *> *nodes, uint64_t nodeId, int64_t resourceId, uint32_t nodeKind) {
    for (CJGuiInternalComposableSceneNode *node in nodes) {
        if (node.node.nodeId == nodeId && node.node.resourceId == resourceId &&
            node.node.nodeKind == nodeKind) return node;
    }
    return nil;
}

static BOOL CjguiPointerContinuationSameIdentity(CJGuiInternalComposableSceneNode *left,
    CJGuiInternalComposableSceneNode *right) {
    if (!left || !right) return NO;
    return left.node.nodeId == right.node.nodeId && left.node.resourceId == right.node.resourceId &&
        left.node.nodeKind == right.node.nodeKind &&
        left.node.semanticIncarnation == right.node.semanticIncarnation &&
        [(left.semanticId ?: @"") isEqualToString:right.semanticId ?: @""] &&
        [(left.semanticBindingKey ?: @"") isEqualToString:right.semanticBindingKey ?: @""] &&
        [(left.value ?: @"") isEqualToString:right.value ?: @""];
}

static BOOL CjguiPointerContinuationFocusMatchesInstalledReceipt(CJGuiInternalSession *ctx,
    CJGuiInternalComposableSceneNode *focus) {
    if (!ctx || !focus || !ctx.installedRangeBasis || !ctx.installedRangeBasis.hasReceipt) return NO;
    NSString *installedBody = ctx.installedRangeBasis.sourceUtf8
        ? [[NSString alloc] initWithData:ctx.installedRangeBasis.sourceUtf8 encoding:NSUTF8StringEncoding] : nil;
    return installedBody &&
        focus.node.nodeId == ctx.selectionReceiptFocusNodeId &&
        focus.node.resourceId == ctx.selectionReceiptFocusResourceId &&
        focus.node.nodeKind == ctx.selectionReceiptFocusNodeKind &&
        focus.node.semanticIncarnation == ctx.selectionReceiptFocusSemanticIncarnation &&
        [(focus.semanticId ?: @"") isEqualToString:ctx.selectionReceiptFocusSemanticId ?: @""] &&
        [(focus.semanticBindingKey ?: @"") isEqualToString:ctx.selectionReceiptFocusSemanticBindingKey ?: @""] &&
        [(focus.value ?: @"") isEqualToString:installedBody];
}

- (BOOL)pointerContinuationReceiptMatches:(CjguiNativePointerCaptureContinuation *)state
                                  context:(CJGuiInternalSession *)ctx {
    if (!state || !ctx || !ctx.installedRangeBasis) return NO;
    CjguiInternalPointerCaptureContinuationOffer offer = state.offer;
    CjguiInstalledRangeState *basis = ctx.installedRangeBasis;
    return basis.hasReceipt && basis.active && !basis.chainClosed &&
        basis.selectionTransferId == offer.selectionTransferId &&
        basis.candidate.rendererSessionGeneration == offer.sessionGeneration &&
        basis.candidate.windowInstanceToken == offer.windowInstanceToken &&
        basis.candidate.bindingEpoch == offer.selectionBindingEpoch &&
        basis.candidate.ownerVersion == offer.ownerVersion &&
        basis.candidate.installedSceneVersion == offer.selectionReceiptSceneVersion &&
        basis.proxyGeneration == offer.proxyGeneration && basis.selectionRevision == offer.nativeSelectionRevision &&
        ctx.selectionReceiptTransferId == offer.selectionTransferId &&
        ctx.selectionReceiptSceneVersion == offer.selectionReceiptSceneVersion &&
        ctx.selectionReceiptBindingEpoch == offer.selectionBindingEpoch &&
        ctx.selectionReceiptProxyGeneration == offer.proxyGeneration &&
        ctx.selectionReceiptNativeRevision == offer.nativeSelectionRevision &&
        ctx.selectionReceiptOwnerVersion == offer.ownerVersion &&
        ctx.selectionReceiptOwnerRevision == offer.ownerRevision &&
        ctx.selectionReceiptFocusNodeId == offer.focusNodeId &&
        ctx.selectionReceiptFocusResourceId == offer.focusResourceId &&
        ctx.selectionReceiptFocusNodeKind == offer.focusNodeKind &&
        ctx.selectionPaintOwnerVersion == offer.ownerVersion &&
        ctx.selectionPaintOwnerRevision == offer.ownerRevision &&
        ctx.sessionGeneration == offer.sessionGeneration &&
        ctx.coordinateLifetimeGeneration == offer.coordinateGeneration &&
        basis.proxy == ctx.composableSceneOverlay.inputProxy &&
        basis.proxyGeneration == ctx.installedRangeProxyGeneration &&
        basis.selectionRevision == ctx.composableSceneOverlay.installedRangeSelectionRevision &&
        ctx.composableSceneOverlay.inputProxy != nil &&
        CjguiInputProxyIsFirstResponder(ctx.composableSceneOverlay) &&
        !ctx.composableSceneOverlay.inputProxy.hasMarkedText &&
        !ctx.composableSceneOverlay.compositionTerminalInFlight &&
        [ctx.composableSceneOverlay.inputProxy.string isEqualToString:
            [[NSString alloc] initWithData:basis.sourceUtf8 encoding:NSUTF8StringEncoding] ?: @""] &&
        ctx.composableSceneOverlay.inputProxy.selectedRange.location == basis.actualSelectionStart16 &&
        NSMaxRange(ctx.composableSceneOverlay.inputProxy.selectedRange) == basis.actualSelectionEnd16;
}

- (BOOL)pointerContinuationMatchesAcceptedScene:(CjguiNativePointerCaptureContinuation *)state
                                        context:(CJGuiInternalSession *)ctx {
    if (!state || !ctx || !state.acceptedSceneInstalled ||
        ctx.composableSceneVersion != state.offer.candidateSceneVersion ||
        ctx.sessionGeneration != state.offer.sessionGeneration ||
        ctx.coordinateLifetimeGeneration != state.offer.coordinateGeneration ||
        !self.pointerCaptureActive || self.pointerCaptureGestureEpoch != state.offer.gestureEpoch ||
        // The immutable logical origin is retained for the gesture history,
        // while each proof-backed continuation advances the current segment's
        // routing target. A later window rebase offers that current segment.
        self.pointerCaptureNodeId != state.offer.originNodeId ||
        self.pointerCaptureResourceId != state.offer.originResourceId ||
        self.pointerCaptureNodeKind != state.offer.originNodeKind ||
        (self.dragEdgeScrollPhase != 0 &&
         !(self.dragEdgeScrollPhase == 3 && self.dragEdgeScrollActive &&
           self.dragEdgeScrollSource == CJGUI_DRAG_EDGE_SOURCE_POINTER_CAPTURE &&
           self.dragEdgeSelectionTransfer == state.offer.selectionTransferId)) ||
        (state.boundaryStopped
            ? (!self.pointerCaptureBoundaryStopped ||
               self.pointerCaptureBoundaryGestureEpoch != state.offer.gestureEpoch ||
               self.pointerCaptureBoundaryViewportIdentity != state.offer.viewportIdentity ||
               self.pointerCaptureBoundaryViewportBinding != state.offer.viewportBindingEpoch ||
               self.pointerCaptureBoundaryViewportNode != state.offer.viewportNodeId ||
               self.pointerCaptureBoundaryViewportResource != state.offer.viewportResourceId ||
               self.pointerCaptureBoundaryAcceptedOffset != state.offer.acceptedOffset)
            : (!self.dragEdgeScrollActive ||
               self.dragEdgeScrollSource != CJGUI_DRAG_EDGE_SOURCE_POINTER_CAPTURE ||
               self.dragEdgeViewportIdentity != state.offer.viewportIdentity ||
               self.dragEdgeViewportBinding != state.offer.viewportBindingEpoch ||
               self.dragEdgeScrollOwnerNode != state.offer.viewportNodeId ||
               self.dragEdgeScrollOwnerResource != state.offer.viewportResourceId ||
               self.dragEdgeScrollRequestGeneration != state.offer.requestGeneration ||
               self.dragEdgeScrollExpectedOffset != state.offer.acceptedOffset)) ||
        ![self pointerContinuationReceiptMatches:state context:ctx]) return NO;

    CJGuiInternalComposableSceneNode *focus = CjguiPointerContinuationFindNode(self.nodes,
        state.offer.focusNodeId, state.offer.focusResourceId, state.offer.focusNodeKind);
    CJGuiInternalComposableSceneNode *viewport = CjguiPointerContinuationFindNode(self.nodes,
        state.offer.viewportNodeId, state.offer.viewportResourceId, state.offer.viewportNodeKind);
    if (!focus || !viewport || focus.node.isInteractive == 0 || focus.node.isReadOnly != 0 ||
        !CjguiComposableNodeAcceptsPointerCapture(focus.node.nodeKind) ||
        (viewport.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_SCROLL_AREA &&
         viewport.node.wheelScrollable == 0) ||
        !CjguiPointerContinuationFocusMatchesInstalledReceipt(ctx, focus) ||
        ![(focus.semanticId ?: @"") isEqualToString:state.focusSemanticId] ||
        ![(focus.semanticBindingKey ?: @"") isEqualToString:state.focusBindingKey] ||
        ![(focus.value ?: @"") isEqualToString:state.focusValue] ||
        focus.node.semanticIncarnation != state.offer.focusSemanticIncarnation ||
        ![(viewport.semanticId ?: @"") isEqualToString:state.viewportSemanticId] ||
        ![(viewport.semanticBindingKey ?: @"") isEqualToString:state.viewportBindingKey] ||
        ![(viewport.value ?: @"") isEqualToString:state.viewportValue]) return NO;
    return YES;
}

- (CjguiInternalRendererStatus)offerPointerCaptureContinuation:(
    const CjguiInternalPointerCaptureContinuationOffer *)offer {
    CJGuiInternalSession *ctx = self.session;
    BOOL activeAcknowledgedCycle = offer && self.dragEdgeScrollActive &&
        self.dragEdgeScrollPhase == 3 &&
        self.dragEdgeScrollSource == CJGUI_DRAG_EDGE_SOURCE_POINTER_CAPTURE &&
        self.dragEdgeScrollRequestGeneration == offer->requestGeneration &&
        self.dragEdgeScrollExpectedOffset == offer->acceptedOffset &&
        self.dragEdgeViewportIdentity == offer->viewportIdentity &&
        self.dragEdgeViewportBinding == offer->viewportBindingEpoch &&
        self.dragEdgeScrollOwnerNode == offer->viewportNodeId &&
        self.dragEdgeScrollOwnerResource == offer->viewportResourceId;
    BOOL boundaryAcknowledgement = offer && self.pointerCaptureBoundaryStopped &&
        self.pointerCaptureBoundaryGestureEpoch == offer->gestureEpoch &&
        self.pointerCaptureBoundaryViewportIdentity == offer->viewportIdentity &&
        self.pointerCaptureBoundaryViewportBinding == offer->viewportBindingEpoch &&
        self.pointerCaptureBoundaryViewportNode == offer->viewportNodeId &&
        self.pointerCaptureBoundaryViewportResource == offer->viewportResourceId &&
        self.pointerCaptureBoundaryAcceptedOffset == offer->acceptedOffset;
    if (!offer || !ctx || ctx.destroyed || ctx.closeRequested || self.pointerCaptureContinuation ||
        !offer->gestureEpoch || !offer->sessionGeneration || !offer->windowInstanceToken ||
        !offer->coordinateGeneration || !offer->candidateSceneVersion || !offer->selectionTransferId ||
        !offer->proxyGeneration || !offer->nativeSelectionRevision || offer->ownerVersion < 0 ||
        offer->ownerRevision < 0 || !offer->focusNodeId || !offer->viewportNodeId ||
        offer->focusNodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT ||
        offer->viewportNodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_SCROLL_AREA ||
        offer->focusSemanticIncarnation < 0 || offer->candidateSceneVersion != ctx.stagedComposableSceneVersion ||
        offer->candidateSceneVersion <= ctx.composableSceneVersion ||
        offer->sessionGeneration != ctx.sessionGeneration ||
        offer->coordinateGeneration != ctx.coordinateLifetimeGeneration ||
        !self.pointerCaptureActive || self.pointerCaptureGestureEpoch != offer->gestureEpoch ||
        self.pointerCaptureNodeId != offer->originNodeId ||
        self.pointerCaptureResourceId != offer->originResourceId ||
        self.pointerCaptureNodeKind != offer->originNodeKind ||
        (!activeAcknowledgedCycle && !boundaryAcknowledgement)) {
        if (getenv("CJGUI_DRAG_EDGE_TRACE") && offer && ctx)
            fprintf(stderr, "CJGUI_POINTER_CAPTURE_CONTINUATION_REJECT status=%u reason=offer_state_validation "
                "gesture=%llu/%llu scene=%llu current=%llu staged=%llu receipt_scene=%llu "
                "phase=%u active=%d active_ack=%d boundary_ack=%d viewport=%llu/%llu binding=%llu/%llu "
                "request=%llu/%llu offset=%lld/%lld origin=%llu/%llu route=%llu/%llu\n",
                (unsigned)CJGUI_INTERNAL_RENDERER_SCENE_STALE,
                (unsigned long long)offer->gestureEpoch, (unsigned long long)self.pointerCaptureGestureEpoch,
                (unsigned long long)offer->candidateSceneVersion,
                (unsigned long long)ctx.composableSceneVersion,
                (unsigned long long)ctx.stagedComposableSceneVersion,
                (unsigned long long)offer->selectionReceiptSceneVersion,
                self.dragEdgeScrollPhase, self.dragEdgeScrollActive, activeAcknowledgedCycle,
                boundaryAcknowledgement, (unsigned long long)self.dragEdgeViewportIdentity,
                (unsigned long long)offer->viewportIdentity,
                (unsigned long long)self.dragEdgeViewportBinding,
                (unsigned long long)offer->viewportBindingEpoch,
                (unsigned long long)self.dragEdgeScrollRequestGeneration,
                (unsigned long long)offer->requestGeneration,
                (long long)self.dragEdgeScrollExpectedOffset, (long long)offer->acceptedOffset,
                (unsigned long long)offer->originNodeId,
                (unsigned long long)self.pointerCaptureOriginNodeId,
                (unsigned long long)offer->originNodeId,
                (unsigned long long)self.pointerCaptureNodeId);
        return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    }

    CjguiInstalledRangeState *basis = ctx.installedRangeBasis;
    if (!basis || !basis.hasReceipt || !basis.active || basis.chainClosed ||
        basis.selectionTransferId != offer->selectionTransferId ||
        basis.candidate.rendererSessionGeneration != offer->sessionGeneration ||
        basis.candidate.windowInstanceToken != offer->windowInstanceToken ||
        basis.candidate.bindingEpoch != offer->selectionBindingEpoch ||
        basis.candidate.ownerVersion != offer->ownerVersion ||
        basis.candidate.installedSceneVersion != offer->selectionReceiptSceneVersion ||
        basis.proxyGeneration != offer->proxyGeneration || basis.selectionRevision != offer->nativeSelectionRevision ||
        ctx.selectionReceiptTransferId != offer->selectionTransferId ||
        ctx.selectionReceiptSceneVersion != offer->selectionReceiptSceneVersion ||
        ctx.selectionReceiptBindingEpoch != offer->selectionBindingEpoch ||
        ctx.selectionReceiptProxyGeneration != offer->proxyGeneration ||
        ctx.selectionReceiptNativeRevision != offer->nativeSelectionRevision ||
        ctx.selectionReceiptOwnerVersion != offer->ownerVersion ||
        ctx.selectionReceiptOwnerRevision != offer->ownerRevision ||
        ctx.selectionReceiptFocusNodeId != offer->focusNodeId ||
        ctx.selectionReceiptFocusResourceId != offer->focusResourceId ||
        ctx.selectionReceiptFocusNodeKind != offer->focusNodeKind ||
        ctx.selectionPaintOwnerVersion != offer->ownerVersion ||
        ctx.selectionPaintOwnerRevision != offer->ownerRevision ||
        basis.proxy != ctx.composableSceneOverlay.inputProxy ||
        basis.proxyGeneration != ctx.installedRangeProxyGeneration ||
        basis.selectionRevision != ctx.composableSceneOverlay.installedRangeSelectionRevision ||
        !CjguiInputProxyIsFirstResponder(ctx.composableSceneOverlay) ||
        ctx.composableSceneOverlay.inputProxy.hasMarkedText ||
        ctx.composableSceneOverlay.compositionTerminalInFlight ||
        ![ctx.composableSceneOverlay.inputProxy.string isEqualToString:
            [[NSString alloc] initWithData:basis.sourceUtf8 encoding:NSUTF8StringEncoding] ?: @""] ||
        ctx.composableSceneOverlay.inputProxy.selectedRange.location != basis.actualSelectionStart16 ||
        NSMaxRange(ctx.composableSceneOverlay.inputProxy.selectedRange) != basis.actualSelectionEnd16) {
        if (getenv("CJGUI_DRAG_EDGE_TRACE"))
            fprintf(stderr, "CJGUI_POINTER_CAPTURE_CONTINUATION_REJECT status=%u reason=installed_receipt_validation "
                "basis=%d receipt=%d active=%d chain_closed=%d transfer=%llu/%llu/%llu "
                "session=%llu/%llu window=%llu/%llu binding=%llu/%llu/%llu "
                "owner=%lld/%lld/%lld revision=%lld/%lld scene=%llu/%llu/%llu "
                "proxy_generation=%llu/%llu/%llu native_revision=%llu/%llu/%llu "
                "proxy_same=%d first_responder=%d marked=%d terminal=%d proxy_body=%d proxy_range=%d "
                "paint_owner=%lld paint_revision=%lld focus=%llu/%llu\n",
                (unsigned)CJGUI_INTERNAL_RENDERER_SCENE_STALE,
                basis != nil, basis.hasReceipt, basis.active, basis.chainClosed,
                (unsigned long long)offer->selectionTransferId, (unsigned long long)basis.selectionTransferId,
                (unsigned long long)ctx.selectionReceiptTransferId,
                (unsigned long long)offer->sessionGeneration, (unsigned long long)basis.candidate.rendererSessionGeneration,
                (unsigned long long)offer->windowInstanceToken, (unsigned long long)basis.candidate.windowInstanceToken,
                (unsigned long long)offer->selectionBindingEpoch, (unsigned long long)basis.candidate.bindingEpoch,
                (unsigned long long)ctx.selectionReceiptBindingEpoch,
                (long long)offer->ownerVersion, (long long)basis.candidate.ownerVersion,
                (long long)ctx.selectionReceiptOwnerVersion,
                (long long)offer->ownerRevision, (long long)ctx.selectionReceiptOwnerRevision,
                (unsigned long long)offer->selectionReceiptSceneVersion,
                (unsigned long long)basis.candidate.installedSceneVersion,
                (unsigned long long)ctx.selectionReceiptSceneVersion,
                (unsigned long long)offer->proxyGeneration, (unsigned long long)basis.proxyGeneration,
                (unsigned long long)ctx.selectionReceiptProxyGeneration,
                (unsigned long long)offer->nativeSelectionRevision, (unsigned long long)basis.selectionRevision,
                (unsigned long long)ctx.selectionReceiptNativeRevision,
                basis.proxy == ctx.composableSceneOverlay.inputProxy,
                CjguiInputProxyIsFirstResponder(ctx.composableSceneOverlay),
                ctx.composableSceneOverlay.inputProxy.hasMarkedText,
                ctx.composableSceneOverlay.compositionTerminalInFlight,
                [ctx.composableSceneOverlay.inputProxy.string isEqualToString:
                    [[NSString alloc] initWithData:basis.sourceUtf8 encoding:NSUTF8StringEncoding] ?: @""],
                ctx.composableSceneOverlay.inputProxy.selectedRange.location == basis.actualSelectionStart16 &&
                    NSMaxRange(ctx.composableSceneOverlay.inputProxy.selectedRange) == basis.actualSelectionEnd16,
                (long long)ctx.selectionPaintOwnerVersion, (long long)ctx.selectionPaintOwnerRevision,
                (unsigned long long)offer->focusNodeId, (unsigned long long)ctx.selectionReceiptFocusNodeId);
        return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    }

    CJGuiInternalComposableSceneNode *origin = CjguiPointerContinuationFindNode(self.nodes,
        offer->originNodeId, offer->originResourceId, offer->originNodeKind);
    CJGuiInternalComposableSceneNode *focus = CjguiPointerContinuationFindNode(self.nodes,
        offer->focusNodeId, offer->focusResourceId, offer->focusNodeKind);
    CJGuiInternalComposableSceneNode *stagedFocus = CjguiPointerContinuationFindNode(ctx.stagedComposableNodes,
        offer->focusNodeId, offer->focusResourceId, offer->focusNodeKind);
    CJGuiInternalComposableSceneNode *viewport = CjguiPointerContinuationFindNode(self.nodes,
        offer->viewportNodeId, offer->viewportResourceId, offer->viewportNodeKind);
    CJGuiInternalComposableSceneNode *stagedViewport = CjguiPointerContinuationFindNode(ctx.stagedComposableNodes,
        offer->viewportNodeId, offer->viewportResourceId, offer->viewportNodeKind);
    if (!origin || origin.node.projectionVersion != offer->originProjectionVersion ||
        !focus || !stagedFocus || focus.node.isInteractive == 0 || focus.node.isReadOnly != 0 ||
        !CjguiComposableNodeAcceptsPointerCapture(focus.node.nodeKind) ||
        !CjguiPointerContinuationSameIdentity(focus, stagedFocus) ||
        focus.node.semanticIncarnation != offer->focusSemanticIncarnation ||
        !CjguiPointerContinuationFocusMatchesInstalledReceipt(ctx, focus) ||
        !viewport || !stagedViewport ||
        (viewport.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_SCROLL_AREA &&
         viewport.node.wheelScrollable == 0) ||
        !CjguiPointerContinuationSameIdentity(viewport, stagedViewport)) {
        if (getenv("CJGUI_DRAG_EDGE_TRACE"))
            fprintf(stderr, "CJGUI_POINTER_CAPTURE_CONTINUATION_REJECT status=%u reason=focus_or_viewport_validation "
                "origin=%d origin_projection=%llu/%llu focus=%d staged_focus=%d interactive=%u readonly=%u "
                "focus_same=%d focus_incarnation=%lld/%lld installed_focus=%d "
                "focus_bytes=%llu installed_bytes=%llu viewport=%d staged_viewport=%d viewport_same=%d\n",
                (unsigned)CJGUI_INTERNAL_RENDERER_SCENE_STALE, origin != nil,
                (unsigned long long)offer->originProjectionVersion, (unsigned long long)origin.node.projectionVersion,
                focus != nil, stagedFocus != nil, focus.node.isInteractive, focus.node.isReadOnly,
                CjguiPointerContinuationSameIdentity(focus, stagedFocus),
                (long long)offer->focusSemanticIncarnation, (long long)focus.node.semanticIncarnation,
                CjguiPointerContinuationFocusMatchesInstalledReceipt(ctx, focus),
                (unsigned long long)[focus.value lengthOfBytesUsingEncoding:NSUTF8StringEncoding],
                (unsigned long long)basis.sourceUtf8.length,
                viewport != nil, stagedViewport != nil, CjguiPointerContinuationSameIdentity(viewport, stagedViewport));
        return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    }

    NSData *focusValue = [(focus.value ?: @"") dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
    NSData *focusKey = [(focus.semanticBindingKey ?: @"") dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
    NSData *focusSemantic = [(focus.semanticId ?: @"") dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
    NSData *viewportValue = [(viewport.value ?: @"") dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
    NSData *viewportKey = [(viewport.semanticBindingKey ?: @"") dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
    NSData *viewportSemantic = [(viewport.semanticId ?: @"") dataUsingEncoding:NSUTF8StringEncoding allowLossyConversion:NO];
    if (!focusValue || focusValue.length > 65536 || !focusKey || focusKey.length > 4096 ||
        !focusSemantic || focusSemantic.length > 4096 || !viewportValue || viewportValue.length > 4096 ||
        !viewportKey || viewportKey.length > 4096 || !viewportSemantic || viewportSemantic.length > 4096)
        return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    CjguiNativePointerCaptureContinuation *state = [CjguiNativePointerCaptureContinuation new];
    state.offer = *offer;
    state.boundaryStopped = boundaryAcknowledgement;
    state.focusSemanticId = [focus.semanticId copy] ?: @"";
    state.focusBindingKey = [focus.semanticBindingKey copy] ?: @"";
    state.focusValue = [focus.value copy] ?: @"";
    state.viewportSemanticId = [viewport.semanticId copy] ?: @"";
    state.viewportBindingKey = [viewport.semanticBindingKey copy] ?: @"";
    state.viewportValue = [viewport.value copy] ?: @"";
    state.paused = YES;
    self.pointerCaptureContinuation = state;
    // Invalidate only the timer callback; keep the accepted lease and phase
    // facts intact until the candidate scene is accepted or discarded.
    self.dragEdgeScrollGeneration += 1;
    self.dragEdgeScrollScheduled = NO;
    self.dragEdgeScrollDeadlineMicros = 0;
    return CJGUI_INTERNAL_RENDERER_OK;
}

- (CjguiInternalRendererStatus)completePointerCaptureContinuation:(uint64_t)gesture
    scene:(uint64_t)scene transfer:(uint64_t)transfer ownerVersion:(int64_t)ownerVersion
    ownerRevision:(int64_t)ownerRevision {
    CjguiNativePointerCaptureContinuation *state = self.pointerCaptureContinuation;
    CJGuiInternalSession *ctx = self.session;
    if (!state || !ctx || state.offer.gestureEpoch != gesture ||
        state.offer.candidateSceneVersion != scene || state.offer.selectionTransferId != transfer ||
        state.offer.ownerVersion != ownerVersion || state.offer.ownerRevision != ownerRevision ||
        ![self pointerContinuationMatchesAcceptedScene:state context:ctx]) {
        if (state && state.offer.gestureEpoch == gesture) {
            BOOL acceptedButInvalid = state.acceptedSceneInstalled &&
                state.offer.candidateSceneVersion == ctx.composableSceneVersion;
            self.pointerCaptureContinuation = nil;
            if (acceptedButInvalid && self.pointerCaptureActive) [self cancelPointerCapture];
            else if (self.dragEdgeScrollActive && self.pointerCaptureActive) {
                CJGuiInternalComposableSceneNode *current = [self capturedPointerNode];
                if (current) [self armDragEdgeScrollForNode:current
                    atPoint:NSMakePoint(self.pointerCaptureX, self.pointerCaptureY)
                    source:CJGUI_DRAG_EDGE_SOURCE_POINTER_CAPTURE];
            }
        }
        return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    }
    CJGuiInternalComposableSceneNode *focus = CjguiPointerContinuationFindNode(self.nodes,
        state.offer.focusNodeId, state.offer.focusResourceId, state.offer.focusNodeKind);
    if (!focus) return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    NSPoint point = NSMakePoint(self.pointerCaptureX, self.pointerCaptureY);
    self.pointerCaptureNodeId = focus.node.nodeId;
    self.pointerCaptureResourceId = focus.node.resourceId;
    self.pointerCaptureNodeKind = focus.node.nodeKind;
    self.pointerCaptureHasContinued = YES;
    self.dragEdgeScrollNodeId = focus.node.nodeId;
    self.dragEdgeScrollResourceId = focus.node.resourceId;
    self.dragEdgeScrollNodeKind = focus.node.nodeKind;
    self.pointerCaptureContinuation = nil;
    // Re-arm from the current accepted geometry. No queued or synthetic MOVE
    // is created here; the next residence tick resolves this point on B.
    [self armDragEdgeScrollForNode:focus atPoint:point source:CJGUI_DRAG_EDGE_SOURCE_POINTER_CAPTURE];
    return CJGUI_INTERNAL_RENDERER_OK;
}

- (CjguiInternalRendererStatus)discardPointerCaptureContinuation:(uint64_t)gesture scene:(uint64_t)scene {
    CjguiNativePointerCaptureContinuation *state = self.pointerCaptureContinuation;
    if (!state) return CJGUI_INTERNAL_RENDERER_OK;
    if (gesture && state.offer.gestureEpoch != gesture) return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    if (scene && state.offer.candidateSceneVersion != scene) return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    BOOL acceptedButUncontinued = state.acceptedSceneInstalled &&
        state.offer.candidateSceneVersion == self.session.composableSceneVersion;
    self.pointerCaptureContinuation = nil;
    if (acceptedButUncontinued && self.pointerCaptureActive) {
        [self cancelPointerCapture];
    } else if (self.dragEdgeScrollActive && self.pointerCaptureActive) {
        CJGuiInternalComposableSceneNode *current = [self capturedPointerNode];
        if (current) [self armDragEdgeScrollForNode:current
            atPoint:NSMakePoint(self.pointerCaptureX, self.pointerCaptureY)
            source:CJGUI_DRAG_EDGE_SOURCE_POINTER_CAPTURE];
    }
    return CJGUI_INTERNAL_RENDERER_OK;
}

- (BOOL)activateInputHost {
    if (self.detachedSourcePreparation || !self.window || self.inputHost.window != self.window) return NO;
    if (CjguiInputProxyIsFirstResponder(self)) return YES;
    return [self.window makeFirstResponder:self.inputHost] && CjguiInputProxyIsFirstResponder(self);
}
