// ---- ABI: generic composable scene ----

static CjguiInternalRendererStatus CjguiConfigureComposableSceneOnMain(uint64_t session, uint64_t projectionVersion, uint32_t nodeCount) {
    if (nodeCount == 0 || nodeCount > 1024) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.view || ctx.view.invalidated) return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t started = CjguiMonotonicMicros();
#endif
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    if (!overlay) {
        overlay = [[CJGuiInternalComposableSceneOverlay alloc] initWithFrame:ctx.view.bounds session:ctx];
        if (!overlay) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        overlay.autoresizingMask = NSViewWidthSizable | NSViewHeightSizable;
        [ctx.view addSubview:overlay];
        ctx.composableSceneOverlay = overlay;
    }
    // Copy only the container. The immutable current node objects are shared
    // with staging until `set_composable_scene_node` writes a changed index.
    // This preserves the all-or-nothing live snapshot while removing the
    // former per-node allocation/string-copy pass for sparse updates.
    NSArray<CJGuiInternalComposableSceneNode *> *currentNodes = ctx.composableNodes;
    NSMutableArray<CJGuiInternalComposableSceneNode *> *nextStaging = [NSMutableArray arrayWithCapacity:nodeCount];
    for (uint32_t index = 0; index < nodeCount; index++) {
        CJGuiInternalComposableSceneNode *node = index < currentNodes.count
            ? currentNodes[index] : nil;
        if (!node) {
            node = [[CJGuiInternalComposableSceneNode alloc] init];
            if (!node) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
            if (ctx.composableSceneNodeAllocationCount < UINT64_MAX) {
                ctx.composableSceneNodeAllocationCount += 1;
            }
            node.index = index; node.label = @""; node.value = @""; node.imageResourcePath = @"";
            node.imageResourceId = @""; node.imageResourceVersion = 0; node.imageTextureCacheKey = @"";
            node.imageTextureContentKey = @""; node.textTextureCacheKey = @"";
            node.textTextureByteCount = 0; node.textTextureRect = NSZeroRect;
        }
        [nextStaging addObject:node];
    }
    CjguiAdvanceComposableImageCandidateLeases(CjguiComposableImageDomainForSession(ctx), ctx, projectionVersion);
    ctx.stagedComposableSceneVersion = projectionVersion;
    ctx.stagedCaretProjection = CjguiFreezeAcceptedCaret(ctx);
    ctx.stagedComposableNodes = nextStaging;
    ctx.stagedComposableGeometryIndices = [NSMutableIndexSet indexSet];
    // Every scene candidate starts with an explicit empty transfer table. A
    // caller that declares transfers replaces it below; legacy consumers
    // therefore cannot accidentally retain a prior scene's paste/drop target.
    ctx.stagedComposableDataTransferItems = [NSMutableArray array];
    ctx.stagedComposableDataTransferVersion = projectionVersion;
#ifdef CJGUI_INTERNAL_TESTING
    ctx.testComposableSceneConfigureMicros += CjguiMonotonicMicros() - started;
#endif
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_configure_composable_scene(uint64_t session, uint64_t projectionVersion, uint32_t nodeCount) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        CjguiOwnerTraceDispatchSync(session, projectionVersion, CJGUI_OWNER_PHASE_NATIVE_SCENE_CONFIGURE, ^{ status = CjguiConfigureComposableSceneOnMain(session, projectionVersion, nodeCount); });
        return status;
    }
    return CjguiConfigureComposableSceneOnMain(session, projectionVersion, nodeCount);
}

static BOOL CjguiComposableGeometryScalarValid(double value) {
    return isfinite(value) && value >= -4096.0 && value <= 4096.0;
}

static CjguiInternalRendererStatus CjguiSetComposableSceneGeometryOnMain(
    uint64_t session, uint64_t projectionVersion, uint32_t nodeIndex,
    const CjguiInternalRendererComposableGeometry *geometry) {
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || ctx.destroyed) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    if (!geometry || projectionVersion == 0 || projectionVersion != ctx.stagedComposableSceneVersion ||
        nodeIndex >= ctx.stagedComposableNodes.count ||
        [ctx.stagedComposableGeometryIndices containsIndex:nodeIndex]) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    CJGuiInternalComposableSceneNode *staged = ctx.stagedComposableNodes[nodeIndex];
    if (!staged || staged.node.nodeId != geometry->nodeId ||
        geometry->clipCount != staged.node.clipConstraintCount ||
        geometry->clipCount > CJGUI_INTERNAL_COMPOSABLE_CLIP_CONSTRAINT_CAPACITY ||
        geometry->reserved != 0 ||
        !CjguiComposableGeometryScalarValid(geometry->translateX) ||
        !CjguiComposableGeometryScalarValid(geometry->translateY) ||
        !CjguiComposableGeometryScalarValid(geometry->clip0X) ||
        !CjguiComposableGeometryScalarValid(geometry->clip0Y) ||
        !CjguiComposableGeometryScalarValid(geometry->clip1X) ||
        !CjguiComposableGeometryScalarValid(geometry->clip1Y) ||
        !CjguiComposableGeometryScalarValid(geometry->clip2X) ||
        !CjguiComposableGeometryScalarValid(geometry->clip2Y) ||
        !CjguiComposableGeometryScalarValid(geometry->clip3X) ||
        !CjguiComposableGeometryScalarValid(geometry->clip3Y) ||
        fabs((double)staged.node.x + geometry->translateX) > 1000000000.0 ||
        fabs((double)staged.node.y + geometry->translateY) > 1000000000.0) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    CjguiInternalRendererComposableGeometry stagedGeometry = staged.geometry;
    if (memcmp(&stagedGeometry, geometry, sizeof(*geometry)) != 0) {
        CJGuiInternalComposableSceneNode *live = nodeIndex < ctx.composableNodes.count
            ? ctx.composableNodes[nodeIndex] : nil;
        if (staged == live) {
            staged = CjguiCloneComposableSceneNode(ctx, live, nodeIndex, projectionVersion);
            if (!staged) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
            ctx.stagedComposableNodes[nodeIndex] = staged;
        }
        staged.geometry = *geometry;
    }
    [ctx.stagedComposableGeometryIndices addIndex:nodeIndex];
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus cjgui_internal_renderer_set_composable_scene_geometry(
    uint64_t session, uint64_t projectionVersion, uint32_t nodeIndex,
    const CjguiInternalRendererComposableGeometry *geometry) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        CjguiOwnerTraceDispatchSync(session, projectionVersion, CJGUI_OWNER_PHASE_NATIVE_SCENE_GEOMETRY, ^{
            status = CjguiSetComposableSceneGeometryOnMain(session, projectionVersion, nodeIndex, geometry);
        });
        return status;
    }
    return CjguiSetComposableSceneGeometryOnMain(session, projectionVersion, nodeIndex, geometry);
}

static void CjguiPruneUnreferencedComposableTransferResources(
    CJGuiInternalComposableImageResourceDomain *domain) {
    if (!domain || domain.destroyed) return;
    NSMutableSet<NSString *> *protected = CjguiComposableImageProtectedKeys(domain, YES);
    for (NSString *key in [domain.resources.allKeys copy]) {
        if (![key hasPrefix:@"cjgui-transfer:"] || [protected containsObject:key]) continue;
        CJGuiInternalComposableImageResource *resource = domain.resources[key];
        resource.texture = nil;
        resource.encodedData = nil;
        [domain.textureCache removeObjectForKey:key];
        [domain.resources removeObjectForKey:key];
    }
    CjguiPruneComposableImageTextureCache(domain, YES);
}

CjguiInternalRendererStatus cjgui_internal_renderer_discard_composable_scene_candidate(uint64_t session) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus result = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        CjguiOwnerTraceDispatchSync(session, 0, CJGUI_OWNER_PHASE_NATIVE_SCENE_DISCARD, ^{
            result = cjgui_internal_renderer_discard_composable_scene_candidate(session);
        });
        return result;
    }
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || ctx.destroyed) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    [ctx.stagedComposableNodes removeAllObjects];
    [ctx.stagedComposableGeometryIndices removeAllIndexes];
    ctx.stagedComposableSceneVersion = 0;
    CjguiRestoreAcceptedComposableImageDemand(ctx);
    // An accepted transfer whose candidate was discarded goes back to ordinary
    // reusable-cache ownership; the lease must not outlive the candidate.
    CjguiSettleComposableImageCandidateLeases(CjguiComposableImageDomainForSession(ctx), ctx, NO);
    CjguiPruneUnreferencedComposableTransferResources(CjguiComposableImageDomainForSession(ctx));
    return CJGUI_INTERNAL_RENDERER_OK;
}

static const NSUInteger kCjguiComposableDataTransferItemCapacity = 128;
static const NSUInteger kCjguiComposableDataTransferPayloadByteCapacity = 512u * 1024u;

static BOOL CjguiComposableDataTransferFormatIsValid(NSString *format) {
    if (!format || format.length == 0 || format.length > 128) return NO;
    if ([format isEqualToString:@"text/plain"]) return YES;
    if ([format isEqualToString:@"image/png"]) return YES;
    if (![format hasPrefix:@"application/"] && ![format hasPrefix:@"cjgui."]) return NO;
    for (NSUInteger index = 0; index < format.length; index++) {
        unichar character = [format characterAtIndex:index];
        BOOL allowed = (character >= 'a' && character <= 'z') ||
            (character >= '0' && character <= '9') || character == '/' ||
            character == '.' || character == '-' || character == '+';
        if (!allowed) return NO;
    }
    return YES;
}

static BOOL CjguiComposableStagedNodeMatchesDataTransferItem(
    CJGuiInternalSession *ctx, const CjguiInternalRendererComposableDataTransferItem *item) {
    if (!ctx || !item) return NO;
    for (CJGuiInternalComposableSceneNode *node in ctx.stagedComposableNodes) {
        if (node.node.nodeId == item->nodeId &&
            node.node.resourceId == item->resourceId &&
            node.node.nodeKind == item->nodeKind &&
            node.node.isInteractive != 0 && node.node.isReadOnly == 0) return YES;
    }
    return NO;
}

static CjguiInternalRendererStatus CjguiConfigureComposableDataTransferOnMain(
    uint64_t session, uint64_t projectionVersion, uint32_t itemCount) {
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.view || ctx.view.invalidated) {
        return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
    if (projectionVersion == 0 || projectionVersion != ctx.stagedComposableSceneVersion ||
        itemCount > kCjguiComposableDataTransferItemCapacity) {
        return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    }
    NSMutableArray<CJGuiInternalComposableDataTransferItem *> *items =
        [NSMutableArray arrayWithCapacity:itemCount];
    for (uint32_t index = 0; index < itemCount; index++) {
        CJGuiInternalComposableDataTransferItem *placeholder =
            [[CJGuiInternalComposableDataTransferItem alloc] init];
        if (!placeholder) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        placeholder.format = @"";
        placeholder.payload = @"";
        [items addObject:placeholder];
    }
    ctx.stagedComposableDataTransferItems = items;
    ctx.stagedComposableDataTransferVersion = projectionVersion;
#ifdef CJGUI_INTERNAL_TESTING
    CjguiUpdateTestDataTransferRetentionPeaks(ctx);
#endif
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_configure_composable_data_transfer(
    uint64_t session, uint64_t projectionVersion, uint32_t itemCount) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        CjguiOwnerTraceDispatchSync(session, projectionVersion, CJGUI_OWNER_PHASE_NATIVE_DATA_TRANSFER_CONFIGURE, ^{
            status = CjguiConfigureComposableDataTransferOnMain(session, projectionVersion, itemCount);
        });
        return status;
    }
    return CjguiConfigureComposableDataTransferOnMain(session, projectionVersion, itemCount);
}

static CjguiInternalRendererStatus CjguiSetComposableDataTransferItemOnMain(
    uint64_t session, uint32_t itemIndex,
    const CjguiInternalRendererComposableDataTransferItem *item,
    const char *formatBytes, const char *payloadBytes,
    const char *sourceKindBytes, const char *sourceIdentityBytes) {
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    if (!item || itemIndex >= ctx.stagedComposableDataTransferItems.count ||
        item->projectionVersion == 0 || item->projectionVersion != ctx.stagedComposableDataTransferVersion ||
        item->projectionVersion != ctx.stagedComposableSceneVersion ||
        (item->role != CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_SOURCE &&
         item->role != CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_TARGET) ||
        item->maximumPayloadBytes == 0 || item->maximumPayloadBytes > kCjguiComposableDataTransferPayloadByteCapacity ||
        !CjguiComposableStagedNodeMatchesDataTransferItem(ctx, item)) {
        return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    }
    NSString *format = formatBytes ? [NSString stringWithUTF8String:formatBytes] : nil;
    NSString *payload = payloadBytes ? [NSString stringWithUTF8String:payloadBytes] : nil;
    NSString *sourceKind = sourceKindBytes ? [NSString stringWithUTF8String:sourceKindBytes] : nil;
    NSString *sourceIdentity = sourceIdentityBytes ? [NSString stringWithUTF8String:sourceIdentityBytes] : nil;
    if (!CjguiComposableDataTransferFormatIsValid(format) || !payload || !sourceKind || !sourceIdentity) {
        return CJGUI_INTERNAL_RENDERER_INVALID_UTF8;
    }
    if (item->localPngFileAllowed > 1 ||
        (item->localPngFileAllowed && (item->role != CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_TARGET ||
         ![format isEqualToString:@"image/png"] || item->expectedOwnerVersion < 0))) {
        return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    }
    NSData *payloadData = [payload dataUsingEncoding:NSUTF8StringEncoding];
    if (!payloadData || payloadData.length > item->maximumPayloadBytes ||
        (item->role == CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_TARGET && (payloadData.length != 0 ||
         sourceKind.length != 0 || sourceIdentity.length != 0 || item->sourceId >= 0)) ||
        (item->role == CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_SOURCE && (sourceKind.length == 0 ||
         sourceKind.length > 128 || sourceIdentity.length == 0 || sourceIdentity.length > 256 || item->sourceId < 0))) {
        return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    }
    CJGuiInternalComposableDataTransferItem *copy =
        ctx.stagedComposableDataTransferItems[itemIndex];
    copy.item = *item;
    copy.format = [format copy];
    copy.payload = [payload copy];
    copy.binaryPayload = nil;
    copy.sourceKind = [sourceKind copy];
    copy.sourceIdentity = [sourceIdentity copy];
#ifdef CJGUI_INTERNAL_TESTING
    [copy markObservationFilled];
    CjguiUpdateTestDataTransferRetentionPeaks(ctx);
#endif
    return CJGUI_INTERNAL_RENDERER_OK;
}

// Only a staged PNG source uses this length-bearing setter. The borrowed FFI
// pointer is copied before return; neither a Cangjie array nor a pasteboard
// provider survives in the native declaration.
static CjguiInternalRendererStatus CjguiSetComposableDataTransferItemBytesOnMain(
    uint64_t session, uint32_t itemIndex, const uint8_t *bytes, uint32_t length) {
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    if (!bytes || length == 0 || length > kCjguiComposableDataTransferPayloadByteCapacity ||
        itemIndex >= ctx.stagedComposableDataTransferItems.count) {
        return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    }
    CJGuiInternalComposableDataTransferItem *item = ctx.stagedComposableDataTransferItems[itemIndex];
    if (item.item.role != CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_SOURCE ||
        item.item.bindingEpoch == 0 || ![item.format isEqualToString:@"image/png"] ||
        length > item.item.maximumPayloadBytes || item.payload.length != 0) {
        return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    }
    NSUInteger retained = 0;
    for (CJGuiInternalComposableDataTransferItem *candidate in ctx.stagedComposableDataTransferItems) {
        if (candidate == item) continue;
        retained += candidate.binaryPayload.length;
        if (retained > 2u * 1024u * 1024u) return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    }
    if (length > 2u * 1024u * 1024u - retained) return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    item.binaryPayload = [NSData dataWithBytes:bytes length:length];
    return item.binaryPayload ? CJGUI_INTERNAL_RENDERER_OK : CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
}

CjguiInternalRendererStatus cjgui_internal_renderer_set_composable_data_transfer_item_bytes(
    uint64_t session, uint32_t itemIndex, const uint8_t *bytes, uint32_t length) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        CjguiOwnerTraceDispatchSync(session, itemIndex, CJGUI_OWNER_PHASE_NATIVE_DATA_TRANSFER_BYTES, ^{
            status = CjguiSetComposableDataTransferItemBytesOnMain(session, itemIndex, bytes, length);
        });
        return status;
    }
    return CjguiSetComposableDataTransferItemBytesOnMain(session, itemIndex, bytes, length);
}

