CjguiInternalRendererStatus
cjgui_internal_renderer_focus_composable_node(uint64_t session, uint64_t nodeId) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        uint64_t dispatchStarted = cjgui_internal_renderer_owner_trace_ns();
        CjguiOwnerTraceDispatchSync(session, nodeId, CJGUI_OWNER_PHASE_NATIVE_FOCUS_NODE, ^{
            status = cjgui_internal_renderer_focus_composable_node(session, nodeId);
        });
        CjguiTraceOwnerPhase(session, "focus_composable_node.dispatch_sync", dispatchStarted);
        return status;
    }
    uint64_t mainStarted = cjgui_internal_renderer_owner_trace_ns();
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.composableSceneOverlay) {
        CjguiInternalRendererStatus status = ctx
            ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
        CjguiTraceOwnerPhase(session, "focus_composable_node.main", mainStarted);
        return status;
    }
    BOOL focused = [ctx.composableSceneOverlay focusCommittedNodeId:nodeId];
    CjguiTraceOwnerPhase(session, "focus_composable_node.main", mainStarted);
    return focused ? CJGUI_INTERNAL_RENDERER_OK : CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
}

static CjguiInternalRendererStatus CjguiRestoreComposableSelectionOnMain(
    uint64_t session, uint64_t nodeId, int64_t resourceId, uint32_t nodeKind,
    uint64_t sceneVersion, const char *expectedValue, uint32_t selectionStart,
    uint32_t selectionEnd, uint32_t *outSelectionStart, uint32_t *outSelectionEnd);

// A bounded native checkpoint for the source-only installation below. KVC is
// restricted to this fixed list of private fields; it does not inspect clients
// or expose an AppKit object across the bridge.
static NSDictionary *CjguiCapturePrivateFields(id object, NSArray<NSString *> *keys) {
    NSMutableDictionary *values = [NSMutableDictionary dictionaryWithCapacity:keys.count];
    for (NSString *key in keys) values[key] = [object valueForKey:key] ?: [NSNull null];
    return values;
}
static void CjguiRestorePrivateFields(id object, NSDictionary *values) {
    for (NSString *key in values) {
        id value = values[key];
        [object setValue:value == [NSNull null] ? nil : value forKey:key];
    }
}

static CjguiInternalRendererStatus CjguiInstallOwnedSourceSelectionLegacyOnMain(
    uint64_t session, uint64_t nodeId, int64_t resourceId, uint64_t sceneVersion,
    uint64_t bindingEpoch, uint64_t requestId, uint64_t deadlineNs,
    const char *expectedValue, uint32_t selectionStart, uint32_t selectionEnd,
    uint32_t *outSelectionStart, uint32_t *outSelectionEnd, uint8_t *outDeferred) {
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.window || !ctx.view || !ctx.composableSceneOverlay)
        return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    if (deadlineNs != 0 && cjgui_internal_renderer_owner_clock_ns() >= deadlineNs) {
        *outDeferred = 1;
        return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    }
    NSUInteger slot = (NSUInteger)(session - 1);
    if (!CjguiSourceInstallPending(ctx) || ctx.ownedTextSessionBindingEpoch != bindingEpoch ||
        ctx.ownedTextSessionNodeId != nodeId || ctx.ownedTextSessionResourceId != resourceId ||
        atomic_load_explicit(&gCjguiSourceInstallRequest[slot], memory_order_acquire) != requestId ||
        ctx.composableSceneVersion != sceneVersion) return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    NSString *expected = [NSString stringWithUTF8String:expectedValue];
    if (!expected || [expected lengthOfBytesUsingEncoding:NSUTF8StringEncoding] > 65536u ||
        [overlay.inputProxy.string lengthOfBytesUsingEncoding:NSUTF8StringEncoding] > 65536u ||
        selectionEnd < selectionStart || selectionEnd > expected.length ||
        overlay.inputProxy.hasMarkedText || overlay.compositionTerminalInFlight ||
        [overlay activeLocalEditNeedsOwnerSettlement] || overlay.activeTextRangeEditPending ||
        overlay.activeTextFallbackHasPendingEdit || overlay.activeTextResourcePreparationScheduled)
        return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    NSRange wanted = CjguiComposedSelection(expected, selectionStart, selectionEnd);
    // Foundation versions can expose CR and LF as separate composed ranges.
    // A source caret inside the two-byte line separator is never admissible.
    BOOL insideCRLF = (selectionStart > 0 && selectionStart < expected.length &&
        [expected characterAtIndex:selectionStart-1] == '\r' && [expected characterAtIndex:selectionStart] == '\n') ||
        (selectionEnd > 0 && selectionEnd < expected.length &&
        [expected characterAtIndex:selectionEnd-1] == '\r' && [expected characterAtIndex:selectionEnd] == '\n');
    if (insideCRLF || wanted.location != selectionStart || NSMaxRange(wanted) != selectionEnd)
        return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    // Already queued input is judged by the owner before this request can
    // install. Never flush it or re-sign this request against a new selection.
    for (CJGuiInternalQueuedInteraction *input in ctx.pendingInteractions) {
        if (input.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_FOCUS ||
            (input.nodeId == nodeId && input.resourceId == resourceId &&
             (input.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_CHANGED ||
              input.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_SELECTION_CHANGED ||
              input.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_NAVIGATE ||
              input.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_RANGE_CHANGED ||
              input.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_COMPOSITION)))
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    }
    CJGuiInternalComposableSceneNode *target = nil;
    for (CJGuiInternalComposableSceneNode *node in ctx.composableNodes) {
        if (node.node.nodeId == nodeId && node.node.resourceId == resourceId &&
            node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT &&
            node.node.isInteractive && [node.value isEqualToString:expected]) { target = node; break; }
    }
    if (!target || ![overlay.nodes containsObject:target] ||
        NSIsEmptyRect(NSIntersectionRect(CjguiComposableRect(target, overlay),
                                                    CjguiComposableClipBounds(target))))
        return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    // Geometry and content are accepted before proxy mutation. This path does
    // not stage style runs or a scene, and does not alter presentation tickets.
    uint64_t checkpointStarted = cjgui_internal_renderer_owner_trace_ns();
    NSArray *overlayKeys = @[@"activeNodeIndex", @"activeNodeId", @"activeProjectionVersion",
        @"activeNodeResourceId", @"activeNodeKind", @"multilineScrollOffset",
        @"activeTextLayoutSignature", @"activeTextAttributeSignature", @"activeTextBaseFont",
        @"inputProxyAssignedBaseFont", @"activeTextFallbackRunsDirty", @"activeTextFallbackNeedsFullRefresh",
        @"activeTextFallbackHasDirtyRange", @"activeTextFallbackDirtyRange", @"activeTextFallbackHasPendingEdit",
        @"activeTextFallbackPendingEditRange", @"activeTextLayoutNeedsVisibleGlyphs",
        @"activeTextHasExactContentHeight", @"activeTextKnownContentHeight", @"activeTextHasScrollAnchor",
        @"activeTextScrollAnchorCharacter", @"activeTextScrollAnchorViewportOffset", @"activeTextBodyGeneration",
        @"activeTextAttributedGeneration", @"activeTextRunsSignature", @"activeTextVisibleParagraphEnd",
        @"activeTextDirtyVisibleRectValid", @"activeTextDirtyVisibleRect", @"activeTextRangeLayoutCount",
        @"activeTextFullLayoutCount", @"activeTextTextureRetryKey", @"activeTextTextureRetryCount",
        @"activeTextTexturePreparationFailed"];
    NSArray *resourceKeys = @[@"textTextureCacheKey", @"textTextureSourceCredential", @"textVisibilityRasterLayout", @"textTexture", @"textTileTextures", @"textTileRects",
        @"textTextureByteCount", @"textTextureRect", @"textTileLayoutOrigin", @"textSelectionRects",
        @"textMarkedRects", @"textCaretRect", @"textCaretIsDeclared", @"textCaretHidden", @"textScrollbarRect"];
    NSDictionary *oldOverlay = CjguiCapturePrivateFields(overlay, overlayKeys);
    NSDictionary *oldResource = CjguiCapturePrivateFields(target, resourceKeys);
    NSDictionary *oldProxy = CjguiCapturePrivateFields(overlay.inputProxy,
        @[@"frame", @"minSize", @"maxSize", @"textContainerInset", @"font", @"textColor", @"typingAttributes", @"editable",
          @"selectable", @"verticallyResizable", @"horizontallyResizable", @"alphaValue"]);
    NSDictionary *oldContainer = CjguiCapturePrivateFields(overlay.inputProxy.textContainer,
        @[@"containerSize", @"maximumNumberOfLines", @"lineBreakMode", @"lineFragmentPadding",
          @"widthTracksTextView", @"heightTracksTextView"]);
    NSDictionary *oldScroll = CjguiCapturePrivateFields(overlay.inputScrollProxy, @[@"frame", @"alphaValue"]);
    NSAttributedString *oldStorage = [overlay.inputProxy.textStorage copy];
    NSRange oldSelection = overlay.inputProxy.selectedRange;
    NSResponder *oldResponder = ctx.window.firstResponder;
    NSMutableDictionary *oldOffsets = [overlay.multilineScrollOffsets mutableCopy];
    NSMutableDictionary *oldLayoutCache = [overlay.multilineLayoutCache mutableCopy];
    NSMutableArray *oldLayoutOrder = [overlay.multilineLayoutCacheOrder mutableCopy];
    CjguiTraceOwnerPhase(session, "source_selection_install.checkpoint", checkpointStarted);
    BOOL same = overlay.activeNodeId == nodeId && overlay.activeNodeResourceId == resourceId &&
                overlay.activeNodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT;
    overlay.sourceSelectionInstallActive = YES;
    overlay.activeNodeId = nodeId; overlay.activeNodeIndex = target.index;
    overlay.activeNodeResourceId = resourceId; overlay.activeNodeKind = target.node.nodeKind;
    overlay.activeProjectionVersion = target.node.projectionVersion;
    BOOL responder = [overlay installInputProxyForNode:target sameNode:same selection:wanted];
    CjguiInternalRendererStatus status = responder && CjguiInputProxyIsFirstResponder(overlay)
        ? CjguiRestoreComposableSelectionOnMain(session, nodeId, resourceId, target.node.nodeKind,
            sceneVersion, expectedValue, selectionStart, selectionEnd, outSelectionStart, outSelectionEnd)
        : CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    if (status == CJGUI_INTERNAL_RENDERER_OK && (overlay.activeTextTexturePreparationFailed ||
        (expected.length > 0 && target.textTextureByteCount == 0)))
        status = CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
    if (status != CJGUI_INTERNAL_RENDERER_OK) {
        overlay.applyingProjection = YES;
        CjguiRestorePrivateFields(overlay.inputProxy, oldProxy);
        [overlay.inputProxy.textStorage setAttributedString:oldStorage];
        CjguiRestorePrivateFields(overlay.inputProxy.textContainer, oldContainer);
        CjguiRestorePrivateFields(overlay.inputScrollProxy, oldScroll);
        overlay.inputProxy.selectedRange = oldSelection;
        CjguiRestorePrivateFields(overlay, oldOverlay);
        CjguiRestorePrivateFields(target, oldResource);
        overlay.multilineScrollOffsets = oldOffsets;
        overlay.multilineLayoutCache = oldLayoutCache;
        overlay.multilineLayoutCacheOrder = oldLayoutOrder;
        BOOL restored = [ctx.window makeFirstResponder:oldResponder];
        overlay.applyingProjection = NO;
        if (!restored || ![overlay.inputProxy.textStorage isEqualToAttributedString:oldStorage] ||
            !NSEqualRanges(overlay.inputProxy.selectedRange, oldSelection) ||
            ctx.window.firstResponder != oldResponder) {
            // An installation failure must never expose a wrong editable proxy.
            overlay.inputProxy.editable = NO;
            fprintf(stderr, "CJGUI_SOURCE_INSTALL_REFUSED reason=rollback_failed session=%llu request=%llu\n",
                (unsigned long long)session, (unsigned long long)requestId);
            status = CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED;
        }
        *outSelectionStart = 0; *outSelectionEnd = 0;
    } else {
        [overlay postAccessibilityFocusChangedForNode:target];
        if (!same) [overlay resetCaretBlink]; else [overlay scheduleCaretBlink];
        if (ctx.window == NSApp.keyWindow) CjguiRebuildComposableCommandMenuForKeyWindow();
    }
    overlay.sourceSelectionInstallActive = NO;
    return status;
}

// The unpublished graph is retired in bounded units and participates in the
// same physical texture union as accepted and GPU-held resources.
static void CjguiCancelSourceProxyPreparation(CJGuiInternalSession *ctx) {
    CjguiSourceProxyPreparation *p = ctx.sourceProxyPreparation;
    if (!p) return;
    CjguiCancelTextPreparationWorker(p.workerAdmission);
    p.workerAdmission = nil;
    ctx.sourceProxyPreparation = nil;
    if (!ctx.retiringSourceProxyPreparations) ctx.retiringSourceProxyPreparations = [NSMutableArray array];
    [ctx.retiringSourceProxyPreparations addObject:p];
}
static void CjguiRetireSourceProxyPreparationUnit(CJGuiInternalSession *ctx) {
    CjguiSourceProxyPreparation *current = ctx.sourceProxyPreparation;
    if (current && (!CjguiSourceInstallPending(ctx) ||
        current.requestId != atomic_load_explicit(&gCjguiSourceInstallRequest[ctx.rendererSessionToken-1], memory_order_acquire) ||
        current.bindingEpoch != ctx.ownedTextSessionBindingEpoch)) CjguiCancelSourceProxyPreparation(ctx);
    CjguiSourceProxyPreparation *p = ctx.retiringSourceProxyPreparations.firstObject;
    if (!p) return;
    if (p.textures.count) { [p.textures removeLastObject]; return; }
    if (p.target) { p.target = nil; return; }
    if (p.painter) { p.painter = nil; return; }
    if (p.sourceLayout) { p.sourceLayout = nil; return; }
    if (p.overlay) { p.overlay = nil; return; }
    [ctx.retiringSourceProxyPreparations removeObjectAtIndex:0];
}

static BOOL CjguiSourceProxyPreparationMatches(CJGuiInternalSession *ctx, CjguiSourceProxyPreparation *p,
    CJGuiInternalComposableSceneNode *target, uint64_t binding, uint64_t request, NSRange wanted) {
    CJGuiInternalComposableSceneOverlay *o = ctx.composableSceneOverlay;
    CjguiInternalRendererComposableNode preparedRaw=p.target.node, acceptedRaw=target.node;
    CjguiInternalRendererComposableGeometry preparedGeometry=p.target.geometry, acceptedGeometry=target.geometry;
    NSRect oldCoverage=CjguiComposableTextTextureRectForNode(target); uint64_t oldBytes=0;
    NSArray<NSValue *> *oldTiles=CjguiPlanComposableTextTiles(oldCoverage,CjguiComposableTextNodeLayoutRect(target),p.scale,&oldBytes);
    CjguiTextRasterSourceCredential *originalNow=CjguiCreateTextRasterSourceCredential(target,o.inputProxy.textStorage,
        o.inputProxy.layoutManager,o.inputProxy.textContainer,o.inputProxy,o.inputProxy.string ?: @"",p.scale,
        oldCoverage,oldTiles,NSMakePoint(target.node.x,target.node.y),[o multilineScrollOffsetForNode:target],
        o.activeTextBodyGeneration,o.activeTextAttributedGeneration);
    return p && p.sessionGeneration == ctx.sessionGeneration && p.bindingEpoch == binding &&
        p.requestId == request && p.sceneVersion == ctx.composableSceneVersion &&
        p.acceptedTarget == target && NSEqualRanges(p.wanted, wanted) &&
        NSEqualSizes(p.viewport, ctx.view.bounds.size) && p.scale == MAX(1.0, [ctx.view currentBackingScale]) &&
        memcmp(&preparedRaw, &acceptedRaw, sizeof(acceptedRaw)) == 0 &&
        memcmp(&preparedGeometry, &acceptedGeometry, sizeof(acceptedGeometry)) == 0 &&
        [p.target.value isEqualToString:target.value] &&
        [p.runs isEqualToString:ctx.composableTextStyleRunsRaw[@(target.node.nodeId)] ?: @""] &&
        o.inputProxy == p.originalProxy && ctx.window.firstResponder == p.originalResponder &&
        o.activeTextBodyGeneration == p.originalBodyGeneration &&
        o.activeTextAttributedGeneration == p.originalAttributedGeneration &&
        o.activeLocalEditGeneration == p.originalLocalEditGeneration &&
        o.activeLocalEditSettledGeneration == p.originalLocalEditSettledGeneration &&
        NSEqualRanges(o.inputProxy.selectedRange, p.originalSelection) &&
        [o.inputProxy.textStorage isEqualToAttributedString:p.originalBody] &&
        [o.inputProxy.typingAttributes isEqualToDictionary:p.originalTypingAttributes] &&
        CjguiTextRasterSourceCredentialsEqual(p.originalSourceCredential,originalNow) &&
        [CjguiFreezeTemporaryAttributeRuns(o.inputProxy.layoutManager, o.inputProxy.textStorage.length)
            isEqualToArray:p.originalTemporaryRuns];
}

static NSArray<NSString *> *CjguiSourceProxyOverlayKeys(void) {
    return @[@"activeNodeIndex", @"activeNodeId", @"activeProjectionVersion", @"activeNodeResourceId", @"activeNodeKind",
        @"multilineScrollOffset", @"activeTextLayoutSignature", @"activeTextAttributeSignature", @"activeTextBaseFont",
        @"inputProxyAssignedBaseFont", @"activeTextFallbackRunsDirty", @"activeTextFallbackNeedsFullRefresh",
        @"activeTextFallbackHasDirtyRange", @"activeTextFallbackDirtyRange", @"activeTextFallbackHasPendingEdit",
        @"activeTextFallbackPendingEditRange", @"activeTextLayoutNeedsVisibleGlyphs", @"activeTextHasExactContentHeight",
        @"activeTextKnownContentHeight", @"activeTextHasScrollAnchor", @"activeTextScrollAnchorCharacter",
        @"activeTextScrollAnchorViewportOffset", @"activeTextBodyGeneration", @"activeTextAttributedGeneration",
        @"activeTextRunsSignature", @"activeTextVisibleParagraphEnd", @"activeTextDirtyVisibleRectValid",
        @"activeTextDirtyVisibleRect", @"activeTextRangeLayoutCount", @"activeTextFullLayoutCount",
        @"activeTextTextureRetryKey", @"activeTextTextureRetryCount", @"activeTextTexturePreparationFailed", @"sourceInputParked",
        @"activeLocalEditAwaitingOwner", @"activeLocalEditProjectionVersion", @"activeLocalEditGeneration",
        @"activeLocalEditSettledGeneration", @"activeLocalEditProxy", @"activeLocalEditBindingEpoch",
        @"activeLocalEditNodeId", @"activeLocalEditResourceId", @"activeLocalEditNodeKind"];
}
static NSArray<NSString *> *CjguiSourceProxyResourceKeys(void) {
    return @[@"textTextureCacheKey", @"textTextureSourceCredential", @"textVisibilityRasterLayout", @"textTexture", @"textTileTextures", @"textTileRects",
        @"textTextureByteCount", @"textTextureRect", @"textTileLayoutOrigin", @"textSelectionRects", @"textMarkedRects",
        @"textCaretRect", @"textCaretIsDeclared", @"textCaretHidden", @"textScrollbarRect"];
}

static CjguiTextPreparationWorkerInput *CjguiCreateSourceProxyWorkerInput(
    CJGuiInternalSession *ctx, CjguiSourceProxyPreparation *p, uint64_t *outReservedBytes) {
    if (outReservedBytes) *outReservedBytes = 0;
    if (!ctx || !p || !p.overlay || !p.target || !p.workerAdmission) return nil;
    NSTextView *proxy = p.overlay.inputProxy;
    NSString *body = p.target.value ?: @"";
    if (!proxy || body.length < 1024 || body.length > CjguiTextPreparationWorkerMaxUtf16Length ||
        ![proxy.string isEqualToString:body]) return nil;
    const char *utf8 = body.UTF8String;
    NSUInteger utf8Length = utf8 ? strlen(utf8) : NSUIntegerMax;
    if (!utf8 || utf8Length > 65536) return nil;
    NSAttributedString *frozenBody = nil;
    NSArray<NSDictionary *> *runs = CjguiFreezeRasterAttributeRuns(proxy.textStorage, &frozenBody);
    NSArray<NSDictionary *> *temporaryRuns = CjguiFreezeTemporaryAttributeRuns(
        proxy.layoutManager, proxy.textStorage.length);
    if (!runs || !frozenBody || !temporaryRuns || ![frozenBody.string isEqualToString:body]) return nil;
    NSFont *font = CjguiComposableFont(p.target);
    if (!font) return nil;
    NSRect bounds = NSMakeRect(0, 0, p.target.node.width, p.target.node.height);
    NSRect textRect = NSInsetRect(bounds, 7.0, 6.0);
    NSTextContainer *container = proxy.textContainer;
    if (NSIsEmptyRect(textRect) || !container ||
        p.target.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT ||
        fabs(container.containerSize.width - NSWidth(textRect)) > 0.5 ||
        container.containerSize.height < NSHeight(textRect) || container.heightTracksTextView) return nil;
    // Source proxies may have thousands of small system-fallback attribute
    // runs (for example mixed CJK/emoji). Bound the two TextKit graphs by
    // character storage plus frozen run records; the cold-scene encoded-run
    // estimator's 2048 bytes per run would reject ordinary fallback text.
    NSDictionary *attributes = body.length
        ? [frozenBody attributesAtIndex:0 effectiveRange:NULL] : @{};
    if (![attributes isKindOfClass:NSDictionary.class] || !attributes[NSFontAttributeName]) return nil;

    CjguiTextPreparationWorkerInput *input = [CjguiTextPreparationWorkerInput new];
    CjguiComposablePreparation *admission = p.workerAdmission;
    input.sessionToken = admission.sessionToken;
    input.sessionGeneration = admission.sessionGeneration;
    input.preparationId = admission.preparationId;
    input.baseSceneVersion = p.sceneVersion;
    input.projectionVersion = p.target.node.projectionVersion;
    input.bindingEpoch = p.bindingEpoch;
    input.nodeId = p.target.node.nodeId;
    input.nodeKind = p.target.node.nodeKind;
    input.node = p.target.node;
    input.geometry = p.target.geometry;
    input.body = body;
    input.baseFont = font;
    input.extentAttributes = attributes;
    input.sourceAttributedBody = frozenBody;
    input.sourceTemporaryAttributeRuns = temporaryRuns;
    input.sourceAttributeRuns = runs;
    input.textRect = textRect;
    input.containerSize = container.containerSize;
    input.containerPadding = container.lineFragmentPadding;
    input.containerLineBreakMode = container.lineBreakMode;
    input.containerMaximumNumberOfLines = container.maximumNumberOfLines;
    input.containerHeightTracksTextView = container.heightTracksTextView;
    input.sourceGraphConfigurationPresent = YES;
    input.layoutAllowsNonContiguous = proxy.layoutManager.allowsNonContiguousLayout;
    input.layoutUsesFontLeading = proxy.layoutManager.usesFontLeading;
    input.layoutShowsInvisibleCharacters = proxy.layoutManager.showsInvisibleCharacters;
    input.layoutShowsControlCharacters = proxy.layoutManager.showsControlCharacters;
    input.scale = p.scale;
    input.appearanceName = p.overlay.effectiveAppearance.name ?: @"";
    CjguiInternalRendererComposableNode snapshotNode = input.node;
    CjguiInternalRendererComposableGeometry snapshotGeometry = input.geometry;
    uint64_t attributeBytes = 0, temporaryBytes = 0, extentBytes = 0;
    uint64_t attributeContainers = 0, temporaryContainers = 0, extentContainers = 0;
    // These frozen leaf values are immutable. Value-personality deduplication
    // reflects the retained input graph: freezing often creates equivalent
    // per-run NSFont/NSColor instances for the same fallback attributes.
    NSHashTable *seenSharedValues = [NSHashTable hashTableWithOptions:
        NSPointerFunctionsObjectPersonality | NSPointerFunctionsStrongMemory];
    if (!CjguiFrozenRasterValueBytes(input.sourceAttributeRuns, 0, seenSharedValues,
            &attributeBytes, &attributeContainers) ||
        !CjguiFrozenRasterValueBytes(input.sourceTemporaryAttributeRuns, 0, seenSharedValues,
            &temporaryBytes, &temporaryContainers) ||
        !CjguiFrozenRasterValueBytes(input.extentAttributes, 0, seenSharedValues,
            &extentBytes, &extentContainers)) return nil;
    uint64_t sharedValues = CjguiSaturatingAddU64(
        attributeBytes - MIN(attributeBytes, attributeContainers),
        temporaryBytes - MIN(temporaryBytes, temporaryContainers));
    sharedValues = CjguiSaturatingAddU64(sharedValues,
        extentBytes - MIN(extentBytes, extentContainers));
    if (attributeContainers > UINT64_MAX / 4u || temporaryContainers > UINT64_MAX / 2u) return nil;
    uint64_t immutableRunBytes = CjguiSaturatingAddU64(utf8Length,
        (uint64_t)body.length * sizeof(unichar) * 3u);
    immutableRunBytes = CjguiSaturatingAddU64(immutableRunBytes, attributeContainers * 4u);
    immutableRunBytes = CjguiSaturatingAddU64(immutableRunBytes, temporaryContainers * 2u);
    immutableRunBytes = CjguiSaturatingAddU64(immutableRunBytes, extentContainers);
    immutableRunBytes = CjguiSaturatingAddU64(immutableRunBytes, sharedValues);
    immutableRunBytes = CjguiSaturatingAddU64(immutableRunBytes,
        sizeof(snapshotNode) + sizeof(snapshotGeometry) + 2048u);
    if (immutableRunBytes == UINT64_MAX) return nil;
    // Four attributed-run container layers cover source input/provenance and
    // worker credential copies; temporary runs are retained by input and
    // credential. Immutable leaves are counted once by value. Each private
    // TextKit graph adds 128 bytes per UTF-16 unit for glyph/layout state.
    uint64_t graphBytes = (uint64_t)body.length * 256u;
    uint64_t estimate = CjguiSaturatingAddU64(immutableRunBytes, graphBytes);
    estimate = CjguiSaturatingAddU64(estimate, 262144u);
    if (estimate > CjguiTextPreparationWorkerMaxBytesPerJob) return nil;
    if (outReservedBytes) *outReservedBytes = estimate;
    return input;
}

static BOOL CjguiSourceProxyWorkerInputStillMatches(CJGuiInternalSession *ctx,
    CjguiSourceProxyPreparation *p, CjguiTextPreparationWorkerInput *input) {
    if (!ctx || !p || !input || ctx.destroyed || !p.overlay || !p.target || !p.workerAdmission ||
        input.sessionToken != ctx.rendererSessionToken ||
        input.sessionGeneration != ctx.sessionGeneration || input.sessionGeneration != p.sessionGeneration ||
        input.preparationId != p.requestId || input.baseSceneVersion != p.sceneVersion ||
        input.bindingEpoch != p.bindingEpoch || input.projectionVersion != p.target.node.projectionVersion ||
        input.nodeId != p.target.node.nodeId || input.nodeKind != p.target.node.nodeKind ||
        input.scale != p.scale || ![input.body isEqualToString:p.target.value] ||
        !NSEqualSizes(input.containerSize, p.overlay.inputProxy.textContainer.containerSize)) return NO;
    CjguiInternalRendererComposableNode inputNode = input.node, currentNode = p.target.node;
    CjguiInternalRendererComposableGeometry inputGeometry = input.geometry, currentGeometry = p.target.geometry;
    if (memcmp(&inputNode, &currentNode, sizeof(inputNode)) != 0 ||
        memcmp(&inputGeometry, &currentGeometry, sizeof(inputGeometry)) != 0) return NO;
    NSAttributedString *currentBody = nil;
    NSArray<NSDictionary *> *currentRuns = CjguiFreezeRasterAttributeRuns(
        p.overlay.inputProxy.textStorage, &currentBody);
    NSArray<NSDictionary *> *currentTemporaryRuns = CjguiFreezeTemporaryAttributeRuns(
        p.overlay.inputProxy.layoutManager, p.overlay.inputProxy.textStorage.length);
    return currentBody && [currentBody isEqualToAttributedString:input.sourceAttributedBody] &&
        [currentRuns isEqualToArray:input.sourceAttributeRuns] &&
        [currentTemporaryRuns isEqualToArray:input.sourceTemporaryAttributeRuns];
}

static BOOL CjguiSourceProxyWorkerCredentialsEquivalent(
    CjguiTextRasterSourceCredential *worker, CjguiTextRasterSourceCredential *adopted) {
    if (!worker || !adopted || ![worker.body isEqualToString:adopted.body] ||
        ![worker.attributeRuns isEqualToArray:adopted.attributeRuns] ||
        ![worker.temporaryAttributeRuns isEqualToArray:adopted.temporaryAttributeRuns] ||
        ![worker.frozenAttributedBody isEqualToAttributedString:adopted.frozenAttributedBody] ||
        ![worker.tiles isEqualToArray:adopted.tiles] || !NSEqualRects(worker.coverage, adopted.coverage) ||
        !NSEqualPoints(worker.origin, adopted.origin) || worker.scale != adopted.scale) return NO;
    NSMutableDictionary *left = [worker.layoutDescription mutableCopy];
    NSMutableDictionary *right = [adopted.layoutDescription mutableCopy];
    [left removeObjectsForKeys:@[@"text_view", @"typing_attributes"]];
    [right removeObjectsForKeys:@[@"text_view", @"typing_attributes"]];
    return [left isEqualToDictionary:right];
}

static CjguiInternalRendererStatus CjguiAdvanceSourceProxyWorkerLayout(
    CJGuiInternalSession *ctx, CjguiSourceProxyPreparation *p) {
    CjguiComposablePreparation *admission = p.workerAdmission;
    if (!ctx || !p || !admission) return CJGUI_INTERNAL_RENDERER_TEXT_SERVICE_UNSUPPORTED;
    CjguiTextPreparationWorkerJob *job = admission.textLayoutJob;
    if (!job) {
        uint64_t reservedBytes = admission.textLayoutPendingBytes;
        CjguiTextPreparationWorkerInput *input = admission.textLayoutPendingInput;
        if (!input) input = CjguiCreateSourceProxyWorkerInput(ctx, p, &reservedBytes);
        if (!input || !reservedBytes) return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
        CjguiTextPreparationAdmission result = CjguiTextPreparationAdmissionNotAdmitted;
        job = CjguiTextPreparationReserve(admission, reservedBytes, &result);
        if (!job) {
            if (result == CjguiTextPreparationAdmissionWaiting) {
                admission.textLayoutPendingInput = input;
                admission.textLayoutPendingBytes = reservedBytes;
                return CJGUI_INTERNAL_RENDERER_OK;
            }
            return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
        }
        admission.textLayoutPendingInput = nil;
        admission.textLayoutPendingBytes = 0;
        pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
        job.input = input;
        job.workerLive = YES;
        admission.textLayoutJob = job;
        pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
        dispatch_async(CjguiTextPreparationWorkerQueue(), ^{ CjguiRunTextPreparationWorker(job); });
        return CJGUI_INTERNAL_RENDERER_OK;
    }

    CjguiTextPreparationWorkerState state;
    CjguiTextPreparationWorkerInput *input = nil;
    CjguiPreparedTextNodeLayout *source = nil, *painter = nil;
    CjguiTextRasterSourceCredential *workerCredential = nil;
    NSArray<NSValue *> *tiles = nil;
    NSRect coverage = NSZeroRect;
    uint64_t plannedBytes = 0;
    NSString *failure = nil;
    pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
    state = job.state;
    if (job.workerLive || state == CjguiTextPreparationWorkerStateQueued ||
        state == CjguiTextPreparationWorkerStateRunning) {
        pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
        return CJGUI_INTERNAL_RENDERER_OK;
    }
    input = job.input; source = job.sourceLayout; painter = job.painter;
    workerCredential = job.sourceCredential; tiles = job.tiles;
    coverage = job.coverage; plannedBytes = job.plannedBytes; failure = job.failure;
    pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
    if (!CjguiSourceProxyWorkerInputStillMatches(ctx, p, input))
        return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    if (state != CjguiTextPreparationWorkerStateReady || !source || !painter ||
        source == painter || source.storage == painter.storage || source.layoutManager == painter.layoutManager ||
        source.container == painter.container || !workerCredential || !tiles.count || !plannedBytes ||
        (failure && failure.length) || source.storage != source.layoutManager.textStorage ||
        source.layoutManager.textContainers.count != 1 || source.layoutManager.textContainers.firstObject != source.container ||
        source.storage.length != input.body.length || source.layoutManager.firstUnlaidCharacterIndex < source.storage.length ||
        painter.storage.length != input.body.length || painter.layoutManager.firstUnlaidCharacterIndex < painter.storage.length)
        return CJGUI_INTERNAL_RENDERER_TEXT_SERVICE_UNSUPPORTED;

    CJGuiInternalComposableSceneOverlay *overlay = p.overlay;
    CJGuiInternalComposableInputProxy *oldProxy = (id)overlay.inputProxy;
    CJGuiInternalComposableInputProxy *proxy = [[CJGuiInternalComposableInputProxy alloc]
        initWithFrame:oldProxy.frame textContainer:source.container];
    if (!proxy || proxy.textStorage != source.storage || proxy.layoutManager != source.layoutManager ||
        proxy.textContainer != source.container || proxy.layoutManager.firstUnlaidCharacterIndex < source.storage.length)
        return CJGUI_INTERNAL_RENDERER_TEXT_SERVICE_UNSUPPORTED;
    CjguiConfigurePlainTextInputProxy(proxy);
    proxy.editable = p.target.node.isReadOnly == 0;
    proxy.selectable = YES;
    proxy.verticallyResizable = NO;
    proxy.horizontallyResizable = NO;
    proxy.textContainerInset = NSZeroSize;
    proxy.typingAttributes = [oldProxy.typingAttributes copy] ?: @{};
    proxy.selectedRange = p.wanted;
    proxy.delegate = overlay;
    proxy.composableOverlay = overlay;
    [overlay.inputScrollProxy setDocumentView:proxy];
    overlay.inputProxy = proxy;
    BOOL retainedGraph = proxy.textStorage == source.storage && proxy.layoutManager == source.layoutManager &&
        proxy.textContainer == source.container && proxy.layoutManager.firstUnlaidCharacterIndex >= source.storage.length &&
        [proxy.string isEqualToString:input.body] && NSEqualRanges(proxy.selectedRange, p.wanted);
    if (!retainedGraph) {
        [overlay.inputScrollProxy setDocumentView:oldProxy];
        oldProxy.delegate = overlay;
        oldProxy.composableOverlay = overlay;
        overlay.inputProxy = oldProxy;
        return CJGUI_INTERNAL_RENDERER_TEXT_SERVICE_UNSUPPORTED;
    }
    source.positionLease = ++gCjguiNextPreparedTextPositionLease;
    source.diagnosticSession = ctx;
    painter.positionLease = ++gCjguiNextPreparedTextPositionLease;
    painter.diagnosticSession = ctx;
    overlay.activeTextBaseFont = input.baseFont;
    overlay.inputProxyAssignedBaseFont = input.baseFont;
    p.sourceLayout = source;
    p.painter = painter;
    p.coverage = coverage;
    p.tiles = tiles;
    p.plannedBytes = plannedBytes;
    p.key = [overlay activeMultilineTileKeyForNode:p.target scale:p.scale];
    p.textures = [NSMutableArray arrayWithCapacity:tiles.count];
    p.characterCursor = 0;
    p.phase = 5;
    pthread_mutex_lock(&gCjguiTextPreparationWorkerLock);
    job.consumerLive = NO;
    CjguiTextPreparationReleaseSlotLocked(job);
    admission.textLayoutJob = nil;
    admission.textLayoutPendingInput = nil;
    admission.textLayoutPendingBytes = 0;
    pthread_mutex_unlock(&gCjguiTextPreparationWorkerLock);
    p.workerAdmission = nil;
    return CJGUI_INTERNAL_RENDERER_OK;
}

static CjguiInternalRendererStatus CjguiAdvanceSourceProxyPreparationUnit(CJGuiInternalSession *ctx,
    CjguiSourceProxyPreparation *p) {
    CJGuiInternalComposableSceneOverlay *o = p.overlay;
    CJGuiInternalComposableSceneNode *node = p.target;
    NSString *text = node.value ?: @"";
    if (p.phase == 0) {
        // This is the eventual input adapter, not a stand-in texture source.
        o = [[CJGuiInternalComposableSceneOverlay alloc] initWithFrame:ctx.composableSceneOverlay.frame session:ctx];
        p.overlay = o; o.detachedSourcePreparation = YES; o.applyingProjection = YES;
        o.detachedSourceRuns = @{ @(node.node.nodeId): p.runs }; o.appearance = ctx.composableSceneOverlay.effectiveAppearance;
        o.nodes = @[node]; o.activeNodeId = node.node.nodeId; o.activeNodeIndex = node.index;
        o.activeNodeResourceId = node.node.resourceId; o.activeNodeKind = node.node.nodeKind;
        o.activeProjectionVersion = node.node.projectionVersion;
        o.inputProxy.editable = node.node.isReadOnly == 0; o.inputProxy.selectable = YES;
        o.inputProxy.verticallyResizable = NO; o.inputProxy.horizontallyResizable = NO;
        o.inputProxy.textContainerInset = NSZeroSize;
        o.inputProxy.textColor = [NSColor colorWithSRGBRed:node.node.textRed green:node.node.textGreen blue:node.node.textBlue alpha:1.0];
        // Geometry is configured while this genuinely empty graph is being
        // created. No content generation or cache credential is claimed yet.
        CJGuiInternalComposableSceneNode *geometry = CjguiCloneComposableSceneNode(ctx, node, node.index, node.node.projectionVersion);
        geometry.value = @""; [o positionInputProxyForNode:geometry];
        o.inputProxy.textContainer.widthTracksTextView = NO;
        o.multilineScrollOffsets = [ctx.composableSceneOverlay.multilineScrollOffsets mutableCopy];
        o.multilineLayoutCache = [ctx.composableSceneOverlay.multilineLayoutCache mutableCopy];
        o.multilineLayoutCacheOrder = [ctx.composableSceneOverlay.multilineLayoutCacheOrder mutableCopy];
        p.phase = 1; return CJGUI_INTERNAL_RENDERER_OK;
    }
    if (p.phase == 1) {
        if (p.characterCursor < text.length) {
            NSUInteger end = MIN(text.length, p.characterCursor + 1024u);
            end = NSMaxRange([text rangeOfComposedCharacterSequenceAtIndex:end-1]);
            NSRange slice = NSMakeRange(p.characterCursor, end-p.characterCursor);
            [o.inputProxy.textStorage appendAttributedString:[[NSAttributedString alloc]
                initWithString:[text substringWithRange:slice]]];
            o.activeTextBodyGeneration++; p.characterCursor = end;
            return CJGUI_INTERNAL_RENDERER_OK;
        }
        o.inputProxy.selectedRange = p.wanted; p.characterCursor = 0; p.phase = 2;
        return CJGUI_INTERNAL_RENDERER_OK;
    }
    if (p.phase == 2) {
        NSFont *font = CjguiComposableFont(node);
        NSMutableParagraphStyle *paragraph = [NSMutableParagraphStyle new]; paragraph.lineBreakMode = NSLineBreakByWordWrapping;
        NSDictionary *attributes = @{ NSFontAttributeName: font,
            NSForegroundColorAttributeName: [NSColor colorWithSRGBRed:node.node.textRed green:node.node.textGreen blue:node.node.textBlue alpha:1.0],
            NSParagraphStyleAttributeName: paragraph };
        [o applyActiveComposableTextAttributesForNode:node baseAttributes:attributes];
        o.inputProxy.typingAttributes = attributes; o.activeTextBaseFont = font;
        o.activeTextLayoutSignature = [o activeTextLayoutSignatureForNode:node contentWidth:MAX(1.0, node.node.width-14.0)];
        o.activeTextAttributeSignature = [o activeTextAttributeSignatureForNode:node];
        o.activeTextRunsSignature = p.runs; o.activeTextAttributedGeneration++;
        o.activeTextLayoutNeedsVisibleGlyphs = YES; p.phase = 3;
        return CJGUI_INTERNAL_RENDERER_OK;
    }
    if (p.phase == 3) {
        if (p.characterCursor < text.length) {
            NSUInteger end = MIN(text.length, p.characterCursor + 1024u);
            end = NSMaxRange([text rangeOfComposedCharacterSequenceAtIndex:end-1]);
            o.activeTextFallbackRunsDirty = YES; o.activeTextFallbackNeedsFullRefresh = NO;
            o.activeTextFallbackHasDirtyRange = YES;
            o.activeTextFallbackDirtyRange = NSMakeRange(p.characterCursor, end-p.characterCursor);
            [o applySystemFallbackRunsToActiveInput]; o.activeTextAttributedGeneration++;
            p.characterCursor = end; return CJGUI_INTERNAL_RENDERER_OK;
        }
        p.characterCursor = 0; p.phase = 4; return CJGUI_INTERNAL_RENDERER_OK;
    }
    if (p.phase == 4) {
        if (text.length >= 1024) {
            CjguiInternalRendererStatus status = CjguiAdvanceSourceProxyWorkerLayout(ctx, p);
            if (status != CJGUI_INTERNAL_RENDERER_OK) return status;
            if (p.phase == 5) return CJGUI_INTERNAL_RENDERER_OK;
            return CJGUI_INTERNAL_RENDERER_OK;
        }
        if (p.characterCursor < text.length) {
            NSUInteger end = MIN(text.length, p.characterCursor + 1024u);
            [o.inputProxy.layoutManager ensureLayoutForCharacterRange:NSMakeRange(p.characterCursor, end-p.characterCursor)];
            p.characterCursor = end; return CJGUI_INTERNAL_RENDERER_OK;
        }
        p.phase = 5; return CJGUI_INTERNAL_RENDERER_OK;
    }
    if (p.phase == 5) {
        [o revealActiveMultilineCaret:node]; [o updateActiveMultilineTextDecorationsForNode:node];
        p.coverage = CjguiComposableTextTextureRectForNode(node);
        uint64_t plannedBytes=0;
        p.tiles = CjguiPlanComposableTextTiles(p.coverage, CjguiComposableTextNodeLayoutRect(node), p.scale, &plannedBytes);
        p.plannedBytes=plannedBytes;
        p.key = [o activeMultilineTileKeyForNode:node scale:p.scale];
        if (!text.length) { p.ready = YES; return CJGUI_INTERNAL_RENDERER_OK; }
        p.sourceCredential = CjguiCreateTextRasterSourceCredential(node, o.inputProxy.textStorage,
            o.inputProxy.layoutManager, o.inputProxy.textContainer, o.inputProxy, text, p.scale,
            p.coverage, p.tiles, NSMakePoint(node.node.x,node.node.y), [o multilineScrollOffsetForNode:node],
            o.activeTextBodyGeneration, o.activeTextAttributedGeneration);
        if (!p.sourceCredential || !p.tiles.count) return CJGUI_INTERNAL_RENDERER_TEXT_SERVICE_UNSUPPORTED;
        if (p.painter) {
            CjguiTextRasterSourceCredential *workerCredential = nil;
            // The frozen painter was made from the same completed source graph;
            // only NSTextView identity and its typing attributes are view-local.
            if (p.sourceLayout && p.sourceLayout.storage == o.inputProxy.textStorage &&
                p.sourceLayout.layoutManager == o.inputProxy.layoutManager &&
                p.sourceLayout.container == o.inputProxy.textContainer &&
                p.sourceLayout.layoutManager.firstUnlaidCharacterIndex >= text.length) {
                workerCredential = CjguiCreateTextRasterSourceCredentialWithAppearance(node,
                    p.sourceLayout.storage, p.sourceLayout.layoutManager, p.sourceLayout.container,
                    nil, text, p.scale, p.coverage, p.tiles, NSMakePoint(node.node.x,node.node.y),
                    [o multilineScrollOffsetForNode:node], o.activeTextBodyGeneration,
                    o.activeTextAttributedGeneration, o.effectiveAppearance.name ?: @"");
            }
            if (!CjguiSourceProxyWorkerCredentialsEquivalent(workerCredential, p.sourceCredential))
                return CJGUI_INTERNAL_RENDERER_TEXT_SERVICE_UNSUPPORTED;
            p.phase = 8; return CJGUI_INTERNAL_RENDERER_OK;
        }
        p.phase = 6; return CJGUI_INTERNAL_RENDERER_OK;
    }
    if (p.phase == 6) {
        p.painter = CjguiCreateSealedRasterLayout(p.sourceCredential);
        if (!p.painter) return CJGUI_INTERNAL_RENDERER_TEXT_SERVICE_UNSUPPORTED;
        p.textures = [NSMutableArray arrayWithCapacity:p.tiles.count];
        p.characterCursor = 0; p.phase = 7; return CJGUI_INTERNAL_RENDERER_OK;
    }
    if (p.phase == 7) {
        // Prepare the frozen painter incrementally too. Raster/upload must
        // not silently lay out the full bounded body inside its first tile.
        if (p.characterCursor < text.length) {
            NSUInteger end = MIN(text.length, p.characterCursor + 1024u);
            [p.painter.layoutManager ensureLayoutForCharacterRange:NSMakeRange(p.characterCursor,end-p.characterCursor)];
            p.characterCursor = end; return CJGUI_INTERNAL_RENDERER_OK;
        }
        p.phase = 8; return CJGUI_INTERNAL_RENDERER_OK;
    }
    if (p.phase == 8) {
        if (p.tileCursor < p.tiles.count) {
            NSRect rect = p.tiles[p.tileCursor].rectValue;
            NSUInteger width=0,height=0,rowBytes=0; uint64_t planned=0;
            if (!CjguiCheckedComposableTextTextureBytes(NSWidth(rect),NSHeight(rect),p.scale,p.scale,
                &width,&height,&rowBytes,&planned)) return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
            uint64_t retained = CjguiComposableRetainedTextTextureBytes(ctx);
            if (retained > CjguiComposableTextTextureByteCapacity || planned > CjguiComposableTextTextureByteCapacity-retained)
                return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
            uint64_t bytes=0;
            id<MTLTexture> texture = [o rasterizeMultilineNode:node active:YES sourceLayout:p.painter scale:p.scale
                tileRect:rect outByteCount:&bytes outTextureRect:NULL
#ifdef CJGUI_INTERNAL_TESTING
                reason:CjguiInternalTextWorkReasonStaticCandidate
#endif
                ];
            if (!texture || !bytes) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
            [p.textures addObject:texture]; p.producedBytes+=bytes; p.tileCursor++;
            ctx.composableTextCandidatePeakBytes = MAX(ctx.composableTextCandidatePeakBytes,CjguiComposableRetainedTextTextureBytes(ctx));
            return CJGUI_INTERNAL_RENDERER_OK;
        }
        if (p.producedBytes != p.plannedBytes) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        node.textTexture=p.textures.count==1?p.textures.firstObject:nil;
        node.textTileTextures=p.textures.count>1?[p.textures copy]:nil;
        node.textTileRects=p.tiles.count>1?p.tiles:nil; node.textTextureByteCount=p.producedBytes;
        node.textTextureCacheKey=p.key; node.textTextureSourceCredential=p.sourceCredential;
        node.textVisibilityRasterLayout=CjguiObserveAllTextSurfaceFrames()?p.painter:nil;
        node.textTextureRect=p.tiles.count==1?p.tiles.firstObject.rectValue:CjguiComposableTextTileUnion(p.tiles);
        node.textTileLayoutOrigin=NSMakePoint(node.node.x,node.node.y);
        p.ready=YES; return CJGUI_INTERNAL_RENDERER_OK;
    }
    return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
}

static CjguiInternalRendererStatus CjguiAdoptSourceProxyPreparation(CJGuiInternalSession *ctx,
    CjguiSourceProxyPreparation *p, uint32_t *outStart, uint32_t *outEnd) {
    CJGuiInternalComposableSceneOverlay *live=ctx.composableSceneOverlay,*prepared=p.overlay;
    CJGuiInternalComposableSceneNode *target=p.acceptedTarget;
    NSDictionary *oldFields=CjguiCapturePrivateFields(live,CjguiSourceProxyOverlayKeys());
    NSDictionary *oldResources=CjguiCapturePrivateFields(target,CjguiSourceProxyResourceKeys());
    CJGuiInternalComposableSceneNode *retiredNode=CjguiCloneComposableSceneNode(ctx,target,target.index,target.node.projectionVersion);
    NSTextView *oldProxy=live.inputProxy; NSScrollView *oldScroll=live.inputScrollProxy;
    NSResponder *oldResponder=ctx.window.firstResponder;
    NSMutableDictionary *oldOffsets=live.multilineScrollOffsets,*oldCache=live.multilineLayoutCache;
    NSMutableArray *oldOrder=live.multilineLayoutCacheOrder;
    live.sourceSelectionInstallActive=YES; live.applyingProjection=YES;
    [prepared.inputScrollProxy removeFromSuperview];
    live.inputProxy=prepared.inputProxy; live.inputScrollProxy=prepared.inputScrollProxy;
    live.inputProxy.delegate=live; ((CJGuiInternalComposableInputProxy *)live.inputProxy).composableOverlay=live;
    [live addSubview:live.inputScrollProxy];
    // Preserve the input generation sequence, while the prepared graph has
    // no speculative local edit. Failure restores the old marker verbatim.
    prepared.activeLocalEditGeneration=live.activeLocalEditGeneration;
    CjguiRestorePrivateFields(live,CjguiCapturePrivateFields(prepared,CjguiSourceProxyOverlayKeys()));
    live.multilineScrollOffsets=prepared.multilineScrollOffsets;
    live.multilineLayoutCache=prepared.multilineLayoutCache; live.multilineLayoutCacheOrder=prepared.multilineLayoutCacheOrder;
    // Real first-responder attachment may change the source. Verify it instead
    // of synchronously repairing/re-rasterizing after the ticket has passed.
    BOOL made=[live activateInputHost];
    live.inputProxy.selectedRange=p.wanted;
    NSRange actual=live.inputProxy.selectedRange;
    CjguiTextRasterSourceCredential *source = p.target.value.length ? CjguiCreateTextRasterSourceCredential(
        target,live.inputProxy.textStorage,live.inputProxy.layoutManager,live.inputProxy.textContainer,live.inputProxy,
        p.target.value,p.scale,p.coverage,p.tiles,NSMakePoint(target.node.x,target.node.y),
        [live multilineScrollOffsetForNode:target],live.activeTextBodyGeneration,live.activeTextAttributedGeneration) : nil;
    BOOL proven=made && CjguiInputProxyIsFirstResponder(live) && NSEqualRanges(actual,p.wanted) &&
        !live.inputProxy.hasMarkedText && [live.inputProxy.string isEqualToString:p.target.value] &&
        (!p.target.value.length || CjguiTextRasterSourceCredentialsEqual(source,p.sourceCredential));
    if (!proven) {
        [live.inputScrollProxy removeFromSuperview];
        live.inputProxy.delegate=prepared; ((CJGuiInternalComposableInputProxy *)live.inputProxy).composableOverlay=prepared;
        [prepared addSubview:live.inputScrollProxy]; live.inputProxy=oldProxy; live.inputScrollProxy=oldScroll;
        CjguiRestorePrivateFields(live,oldFields); CjguiRestorePrivateFields(target,oldResources);
        live.multilineScrollOffsets=oldOffsets; live.multilineLayoutCache=oldCache; live.multilineLayoutCacheOrder=oldOrder;
        BOOL restored=[ctx.window makeFirstResponder:oldResponder];
        live.applyingProjection=NO; live.sourceSelectionInstallActive=NO;
        if (!restored || ctx.window.firstResponder!=oldResponder) {
            live.inputProxy.editable=NO; return CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED;
        }
        return NSEqualRanges(actual,p.wanted)?CJGUI_INTERNAL_RENDERER_SCENE_STALE:CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    }
    // Candidate provenance is committed only from this real proxy adoption
    // readback. The scene/body alone never identifies a source extent.
    [live recordInstalledRangeReceiptForNode:target];
    CjguiRestorePrivateFields(target,CjguiCapturePrivateFields(p.target,CjguiSourceProxyResourceKeys()));
    [oldScroll removeFromSuperview]; oldProxy.delegate=nil;
    ((CJGuiInternalComposableInputProxy *)oldProxy).composableOverlay=nil;
    live.sourceInputParked=NO; live.applyingProjection=NO; live.sourceSelectionInstallActive=NO;
    *outStart=(uint32_t)actual.location; *outEnd=(uint32_t)NSMaxRange(actual);
    // The actual graph is now owned by live. The old actual graph/resources
    // get a separate bounded retirement hold; no cancellation owns the new
    // adapter and physical accounting includes the old generation meanwhile.
    prepared.inputProxy=oldProxy; prepared.inputScrollProxy=oldScroll;
    prepared.nodes=@[]; [prepared addSubview:oldScroll];
    p.target=retiredNode; p.textures=[NSMutableArray array];
    ctx.sourceProxyPreparation=nil;
    if (!ctx.retiringSourceProxyPreparations) ctx.retiringSourceProxyPreparations=[NSMutableArray array];
    [ctx.retiringSourceProxyPreparations addObject:p];
    [live postAccessibilityFocusChangedForNode:target]; [live resetCaretBlink];
    [ctx.view setNeedsDisplay:YES];
    if (ctx.window==NSApp.keyWindow) CjguiRebuildComposableCommandMenuForKeyWindow();
    return CJGUI_INTERNAL_RENDERER_OK;
}

static void CjguiTraceSourceProxyInstallGuard(CJGuiInternalSession *ctx, uint64_t request, uint64_t binding,
                                            uint64_t scene, uint64_t mask) {
    if (!CjguiOwnerPhaseTraceEnabled()) return;
    CJGuiInternalComposableSceneOverlay *o=ctx.composableSceneOverlay;
    if (!mask) { o.sourceInstallGuardTraceSignature=nil; return; }
    NSString *signature=[NSString stringWithFormat:@"%llu:%llu:%llu:%llu:%llu:%llu:%p",
        (unsigned long long)request,(unsigned long long)binding,(unsigned long long)scene,
        (unsigned long long)mask,(unsigned long long)o.activeLocalEditGeneration,
        (unsigned long long)o.activeLocalEditSettledGeneration,o.inputProxy];
    if ([signature isEqualToString:o.sourceInstallGuardTraceSignature]) return;
    o.sourceInstallGuardTraceSignature=signature;
    NSMutableString *fifo=[NSMutableString string]; NSUInteger count=0;
    for (CJGuiInternalQueuedInteraction *input in ctx.pendingInteractions) {
        if (count++==4) break;
        [fifo appendFormat:@"%u@%llu,",input.kind,(unsigned long long)input.projectionVersion];
    }
    fprintf(stderr,"CJGUI_SOURCE_PROXY_INSTALL_GUARD session=%llu request=%llu binding=%llu scene=%llu mask=%llu active_scene=%llu local_scene=%llu generation=%llu settled_generation=%llu proxy=%p edit_proxy=%p parked=%u fifo_count=%lu fifo=%s\n",
        (unsigned long long)ctx.rendererSessionToken,(unsigned long long)request,(unsigned long long)binding,
        (unsigned long long)scene,(unsigned long long)mask,(unsigned long long)o.activeProjectionVersion,
        (unsigned long long)o.activeLocalEditProjectionVersion,(unsigned long long)o.activeLocalEditGeneration,
        (unsigned long long)o.activeLocalEditSettledGeneration,o.inputProxy,o.activeLocalEditProxy,
        o.sourceInputParked,(unsigned long)ctx.pendingInteractions.count,fifo.UTF8String);
}

static CjguiInternalRendererStatus CjguiInstallOwnedSourceSelectionOnMain(
    uint64_t session,uint64_t nodeId,int64_t resourceId,uint64_t sceneVersion,uint64_t bindingEpoch,
    uint64_t requestId,uint64_t deadlineNs,const char *expectedValue,uint32_t selectionStart,uint32_t selectionEnd,
    uint32_t *outStart,uint32_t *outEnd,uint8_t *outDeferred) {
    // The non-budgeted legacy caller keeps its existing synchronous contract.
    if (!deadlineNs) return CjguiInstallOwnedSourceSelectionLegacyOnMain(session,nodeId,resourceId,sceneVersion,
        bindingEpoch,requestId,0,expectedValue,selectionStart,selectionEnd,outStart,outEnd,outDeferred);
    CJGuiInternalSession *ctx=CjguiLookupSession(session);
    if (!ctx || !ctx.window || !ctx.view || !ctx.composableSceneOverlay)
        return ctx?CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED:CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    if (cjgui_internal_renderer_owner_clock_ns()>=deadlineNs) { *outDeferred=1; return CJGUI_INTERNAL_RENDERER_SCENE_STALE; }
    CjguiRetireSourceProxyPreparationUnit(ctx);
    CJGuiInternalComposableSceneOverlay *live=ctx.composableSceneOverlay;
    NSString *expected=[NSString stringWithUTF8String:expectedValue];
    uint64_t guardMask=0;
    if (!CjguiSourceInstallPending(ctx)) guardMask|=1;
    if (ctx.ownedTextSessionBindingEpoch!=bindingEpoch) guardMask|=2;
    if (ctx.ownedTextSessionNodeId!=nodeId || ctx.ownedTextSessionResourceId!=resourceId) guardMask|=4;
    if (atomic_load_explicit(&gCjguiSourceInstallRequest[session-1],memory_order_acquire)!=requestId) guardMask|=8;
    if (ctx.composableSceneVersion!=sceneVersion) guardMask|=16;
    if (!CjguiSourceInstallCanRetainActualProxy(ctx,live,expected)) guardMask|=32;
    if (selectionEnd<selectionStart || selectionEnd>expected.length) guardMask|=64;
    if (live.inputProxy.hasMarkedText) guardMask|=128;
    if (live.compositionTerminalInFlight) guardMask|=256;
    if ([live activeLocalEditNeedsOwnerSettlement]) guardMask|=512;
    if (live.activeTextRangeEditPending || live.activeTextFallbackHasPendingEdit) guardMask|=1024;
    if (live.activeTextResourcePreparationScheduled) guardMask|=2048;
    if (guardMask) {
        CjguiTraceSourceProxyInstallGuard(ctx,requestId,bindingEpoch,sceneVersion,guardMask);
        return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    }
    NSRange wanted=CjguiComposedSelection(expected,selectionStart,selectionEnd);
    BOOL crlf=(selectionStart>0 && selectionStart<expected.length && [expected characterAtIndex:selectionStart-1]=='\r' &&
        [expected characterAtIndex:selectionStart]=='\n') || (selectionEnd>0 && selectionEnd<expected.length &&
        [expected characterAtIndex:selectionEnd-1]=='\r' && [expected characterAtIndex:selectionEnd]=='\n');
    if (crlf || wanted.location!=selectionStart || NSMaxRange(wanted)!=selectionEnd)
        return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    for (CJGuiInternalQueuedInteraction *input in ctx.pendingInteractions)
        if (input.kind==CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_FOCUS ||
            (input.nodeId==nodeId && input.resourceId==resourceId &&
             (input.kind==CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_CHANGED ||
              input.kind==CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_SELECTION_CHANGED ||
              input.kind==CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_NAVIGATE ||
              input.kind==CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_RANGE_CHANGED ||
              input.kind==CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_COMPOSITION))) {
            CjguiTraceSourceProxyInstallGuard(ctx,requestId,bindingEpoch,sceneVersion,4096);
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        }
    CjguiTraceSourceProxyInstallGuard(ctx,requestId,bindingEpoch,sceneVersion,0);
    CJGuiInternalComposableSceneNode *target=nil;
    for (CJGuiInternalComposableSceneNode *node in ctx.composableNodes)
        if (node.node.nodeId==nodeId && node.node.resourceId==resourceId && node.node.nodeKind==CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT &&
            node.node.isInteractive && [node.value isEqualToString:expected]) { target=node; break; }
    if (!target || ![live.nodes containsObject:target] || NSIsEmptyRect(NSIntersectionRect(CjguiComposableRect(target,live),CjguiComposableClipBounds(target))))
        return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    CjguiSourceProxyPreparation *p=ctx.sourceProxyPreparation;
    if (p && !CjguiSourceProxyPreparationMatches(ctx,p,target,bindingEpoch,requestId,wanted)) {
        CjguiCancelSourceProxyPreparation(ctx); return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    }
    if (!p) {
        if (ctx.retiringSourceProxyPreparations.count>=2) return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
        p=[CjguiSourceProxyPreparation new]; p.sessionGeneration=ctx.sessionGeneration; p.bindingEpoch=bindingEpoch;
        p.requestId=requestId; p.sceneVersion=sceneVersion; p.viewport=ctx.view.bounds.size;
        p.scale=MAX(1.0,[ctx.view currentBackingScale]); p.acceptedTarget=target;
        p.target=CjguiCloneComposableSceneNode(ctx,target,target.index,sceneVersion); p.wanted=wanted;
        CjguiReleaseComposableTextResource(p.target); p.target.preparedTextLayout=nil;
        p.runs=ctx.composableTextStyleRunsRaw[@(nodeId)] ?: @"";
        p.originalProxy=live.inputProxy; p.originalBody=[live.inputProxy.textStorage copy];
        p.originalTemporaryRuns=CjguiFreezeTemporaryAttributeRuns(live.inputProxy.layoutManager,live.inputProxy.textStorage.length);
        p.originalTypingAttributes=[live.inputProxy.typingAttributes copy]; p.originalResponder=ctx.window.firstResponder;
        p.originalSelection=live.inputProxy.selectedRange; p.originalBodyGeneration=live.activeTextBodyGeneration;
        p.originalAttributedGeneration=live.activeTextAttributedGeneration;
        p.originalLocalEditGeneration=live.activeLocalEditGeneration;
        p.originalLocalEditSettledGeneration=live.activeLocalEditSettledGeneration;
        p.workerAdmission=[CjguiComposablePreparation new];
        p.workerAdmission.sessionToken=ctx.rendererSessionToken;
        p.workerAdmission.sessionGeneration=ctx.sessionGeneration;
        p.workerAdmission.preparationId=requestId;
        p.workerAdmission.baseSceneVersion=sceneVersion;
        p.workerAdmission.projectionVersion=target.node.projectionVersion;
        p.workerAdmission.bindingEpoch=bindingEpoch;
        p.workerAdmission.scale=p.scale;
        NSRect oldCoverage=CjguiComposableTextTextureRectForNode(target); uint64_t oldBytes=0;
        NSArray<NSValue *> *oldTiles=CjguiPlanComposableTextTiles(oldCoverage,CjguiComposableTextNodeLayoutRect(target),p.scale,&oldBytes);
        p.originalSourceCredential=CjguiCreateTextRasterSourceCredential(target,live.inputProxy.textStorage,
            live.inputProxy.layoutManager,live.inputProxy.textContainer,live.inputProxy,live.inputProxy.string ?: @"",p.scale,
            oldCoverage,oldTiles,NSMakePoint(target.node.x,target.node.y),[live multilineScrollOffsetForNode:target],
            live.activeTextBodyGeneration,live.activeTextAttributedGeneration);
        if (!p.originalSourceCredential) return CJGUI_INTERNAL_RENDERER_TEXT_SERVICE_UNSUPPORTED;
        ctx.sourceProxyPreparation=p;
        // The first invocation creates only private state. The original
        // selection ticket is rechecked by the owner before another unit.
        *outDeferred=1; return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    }
    if (!p.ready) {
        uint64_t started=cjgui_internal_renderer_owner_trace_ns(); NSUInteger phase=p.phase;
        CjguiInternalRendererStatus status=CjguiAdvanceSourceProxyPreparationUnit(ctx,p);
        CjguiTraceOwnerPhase(session,"source_proxy.prepare_unit",started);
        if (getenv("CJGUI_OWNER_PHASE_TRACE")) fprintf(stderr,
            "CJGUI_SOURCE_PROXY_PREPARE session=%llu request=%llu phase=%lu cursor=%lu tile=%lu ready=%u status=%d\n",
            (unsigned long long)session,(unsigned long long)requestId,(unsigned long)phase,
            (unsigned long)p.characterCursor,(unsigned long)p.tileCursor,p.ready,status);
        if (status!=CJGUI_INTERNAL_RENDERER_OK) { CjguiCancelSourceProxyPreparation(ctx); return status; }
        *outDeferred=1; return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    }
    uint64_t started=cjgui_internal_renderer_owner_trace_ns();
    CjguiInternalRendererStatus status=CjguiAdoptSourceProxyPreparation(ctx,p,outStart,outEnd);
    CjguiTraceOwnerPhase(session,"source_proxy.adopt",started);
    if (status!=CJGUI_INTERNAL_RENDERER_OK) CjguiCancelSourceProxyPreparation(ctx);
    return status;
}

CjguiInternalRendererStatus cjgui_internal_renderer_install_owned_source_selection(
    uint64_t session, uint64_t nodeId, int64_t resourceId, uint64_t sceneVersion,
    uint64_t bindingEpoch, uint64_t requestId, uint64_t deadlineNs,
    const char *expectedValue, uint32_t selectionStart, uint32_t selectionEnd,
    uint32_t *outSelectionStart, uint32_t *outSelectionEnd, uint8_t *outDeferred) {
    if (!expectedValue || !outSelectionStart || !outSelectionEnd || !outDeferred)
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    *outSelectionStart = 0; *outSelectionEnd = 0; *outDeferred = 0;
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        uint64_t started = cjgui_internal_renderer_owner_trace_ns();
        uint64_t cpuStarted = started ? cjgui_internal_renderer_owner_thread_cpu_ns() : 0;
        uint64_t traceTurn = atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn, memory_order_acquire);
        uint64_t traceDispatch = cjgui_internal_renderer_owner_trace_dispatch_begin(session, traceTurn,
            requestId, UINT64_MAX, CJGUI_OWNER_PHASE_INSTALL_DISPATCH, 0);
        dispatch_sync(dispatch_get_main_queue(), ^{
            cjgui_internal_renderer_owner_trace_dispatch_event(CJGUI_OWNER_TRACE_MAIN_ENTER,
                session, traceTurn, requestId, traceDispatch, UINT64_MAX,
                CJGUI_OWNER_PHASE_INSTALL_DISPATCH, 0);
            uint64_t mainStarted = cjgui_internal_renderer_owner_trace_ns();
            uint64_t mainCpuStarted = mainStarted ? cjgui_internal_renderer_owner_thread_cpu_ns() : 0;
            status = CjguiInstallOwnedSourceSelectionOnMain(session, nodeId, resourceId, sceneVersion,
                bindingEpoch, requestId, deadlineNs, expectedValue, selectionStart, selectionEnd,
                outSelectionStart, outSelectionEnd, outDeferred);
            CjguiTraceOwnerPhase(session, "source_selection_install.main", mainStarted);
            CjguiTraceOwnerCpuSpan(session, "source_selection_install.main", mainStarted, mainCpuStarted);
            cjgui_internal_renderer_owner_trace_dispatch_event(CJGUI_OWNER_TRACE_MAIN_EXIT,
                session, traceTurn, requestId, traceDispatch, UINT64_MAX,
                CJGUI_OWNER_PHASE_INSTALL_DISPATCH, 0);
        });
        cjgui_internal_renderer_owner_trace_dispatch_event(CJGUI_OWNER_TRACE_OWNER_RETURN,
            session, traceTurn, requestId, traceDispatch, UINT64_MAX,
            CJGUI_OWNER_PHASE_INSTALL_DISPATCH, 0);
        CjguiTraceOwnerPhase(session, "source_selection_install.dispatch_sync", started);
        CjguiTraceOwnerCpuSpan(session, "source_selection_install.owner_dispatch", started, cpuStarted);
        return status;
    }
    return CjguiInstallOwnedSourceSelectionOnMain(session, nodeId, resourceId, sceneVersion,
        bindingEpoch, requestId, deadlineNs, expectedValue, selectionStart, selectionEnd,
        outSelectionStart, outSelectionEnd, outDeferred);
}

static CjguiInternalRendererStatus
CjguiRestoreComposableSelectionOnMain(uint64_t session, uint64_t nodeId,
                                      int64_t resourceId, uint32_t nodeKind,
                                      uint64_t sceneVersion, const char *expectedValue,
                                      uint32_t selectionStart, uint32_t selectionEnd,
                                      uint32_t *outSelectionStart, uint32_t *outSelectionEnd) {
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.composableSceneOverlay || !ctx.window) {
        return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
    if (ctx.composableSceneVersion != sceneVersion || selectionEnd < selectionStart ||
        (nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT_INPUT &&
         nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_INTEGER_INPUT &&
         nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT &&
         nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT)) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    // Opt-in refusal injection exercises retained recovery in a normal build.
    // No selection or ownership is changed by this one failed installation.
    const char *restoreRefusal = getenv("CJGUI_SELECTION_RESTORE_REFUSE_ONCE");
    static NSMutableSet<NSNumber *> *restoreRefusedSessions = nil;
    if (restoreRefusal && strcmp(restoreRefusal,"1") == 0) {
        if (!restoreRefusedSessions) restoreRefusedSessions = [NSMutableSet set];
        if (![restoreRefusedSessions containsObject:@(session)]) {
            [restoreRefusedSessions addObject:@(session)];
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
        }
    }

    NSString *expected = [NSString stringWithUTF8String:expectedValue];
    if (!expected || overlay.inputProxy.hasMarkedText || !CjguiInputProxyIsFirstResponder(overlay)) {
        if (getenv("CJGUI_TRACE_IME_PUMP")) {
            fprintf(stderr, "CJGUI_SEL_RESTORE_NATIVE reason=proxy_not_ready session=%llu scene=%llu node=%llu expected_valid=%d marked=%d proxy_is_responder=%d\n",
                (unsigned long long)session, (unsigned long long)sceneVersion, (unsigned long long)nodeId,
                expected != nil, overlay.inputProxy.hasMarkedText, CjguiInputProxyIsFirstResponder(overlay));
        }
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    for (CJGuiInternalComposableSceneNode *node in ctx.composableNodes) {
        if (node.node.nodeId != nodeId || node.node.resourceId != resourceId ||
            node.node.nodeKind != nodeKind || node.node.isInteractive == 0) continue;
        if (overlay.activeNodeId != nodeId || overlay.activeNodeIndex != node.index ||
            overlay.activeNodeResourceId != resourceId || overlay.activeNodeKind != nodeKind ||
            overlay.activeProjectionVersion != node.node.projectionVersion) continue;
        if (![node.value isEqualToString:expected] || ![overlay.inputProxy.string isEqualToString:expected] ||
            selectionStart > expected.length || selectionEnd > expected.length) {
            if (getenv("CJGUI_TRACE_IME_PUMP")) {
                fprintf(stderr, "CJGUI_SEL_RESTORE_NATIVE reason=value_or_range session=%llu scene=%llu node=%llu node_value_match=%d proxy_value_match=%d expected_units=%lu proxy_units=%lu range=%u:%u\n",
                    (unsigned long long)session, (unsigned long long)sceneVersion, (unsigned long long)nodeId,
                    [node.value isEqualToString:expected], [overlay.inputProxy.string isEqualToString:expected],
                    (unsigned long)expected.length, (unsigned long)overlay.inputProxy.string.length, selectionStart, selectionEnd);
            }
            return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        }
        NSRange applied = CjguiComposedSelection(expected, selectionStart, selectionEnd);
        // A request for an internal grapheme/CRLF point must fail before native
        // selection changes. Clamping then reporting rejection loses the old
        // selection even though the ticket has not been committed.
        if (applied.location != selectionStart || NSMaxRange(applied) != selectionEnd) {
            return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
        }
        NSRange previousSelection = overlay.inputProxy.selectedRange;
        overlay.applyingProjection = YES;
        overlay.inputProxy.selectedRange = applied;
        overlay.applyingProjection = NO;
        applied = overlay.inputProxy.selectedRange;
        if (applied.location != selectionStart || NSMaxRange(applied) != selectionEnd ||
            applied.location > UINT32_MAX || NSMaxRange(applied) > UINT32_MAX) {
            overlay.applyingProjection = YES;
            overlay.inputProxy.selectedRange = previousSelection;
            overlay.applyingProjection = NO;
            return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
        }
        *outSelectionStart = (uint32_t)applied.location;
        *outSelectionEnd = (uint32_t)NSMaxRange(applied);
        [overlay revealActiveMultilineCaret:node];
#ifdef CJGUI_INTERNAL_TESTING
        overlay.testActiveTextWorkReason = CjguiInternalTextWorkReasonSelectionCaret;
#endif
        [overlay refreshGpuTextForActiveInput];
        [overlay setNeedsDisplay:YES];
        return CJGUI_INTERNAL_RENDERER_OK;
    }
    return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_restore_composable_selection(uint64_t session, uint64_t nodeId,
                                                     int64_t resourceId, uint32_t nodeKind,
                                                     uint64_t sceneVersion, const char *expectedValue,
                                                     uint32_t selectionStart, uint32_t selectionEnd,
                                                     uint32_t *outSelectionStart, uint32_t *outSelectionEnd) {
    if (!outSelectionStart || !outSelectionEnd || !expectedValue) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    *outSelectionStart = 0; *outSelectionEnd = 0;
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        uint64_t dispatchStarted = cjgui_internal_renderer_owner_trace_ns();
        CjguiOwnerTraceDispatchSync(session, nodeId, CJGUI_OWNER_PHASE_NATIVE_RESTORE_SELECTION, ^{
            uint64_t mainStarted = cjgui_internal_renderer_owner_trace_ns();
            status = CjguiRestoreComposableSelectionOnMain(session, nodeId, resourceId, nodeKind,
                sceneVersion, expectedValue, selectionStart, selectionEnd, outSelectionStart, outSelectionEnd);
            CjguiTraceOwnerPhase(session, "restore_composable_selection.main", mainStarted);
        });
        CjguiTraceOwnerPhase(session, "restore_composable_selection.dispatch_sync", dispatchStarted);
        return status;
    }
    uint64_t mainStarted = cjgui_internal_renderer_owner_trace_ns();
    CjguiInternalRendererStatus status = CjguiRestoreComposableSelectionOnMain(session, nodeId, resourceId,
        nodeKind, sceneVersion, expectedValue, selectionStart, selectionEnd,
        outSelectionStart, outSelectionEnd);
    CjguiTraceOwnerPhase(session, "restore_composable_selection.main", mainStarted);
    return status;
}

// REANCHOR: see the header. Two mechanisms are attempted in order: (1) keep the
// live marked run and rewrite only the surrounding storage (the input source
// never sees its conversion interrupted), (2) if the storage edits dropped the
// marked state, re-install the same preedit through the ordinary client entry.
// The readback at the end decides: anything that does not match the assembled
// target leaves the caller to cancel instead of continuing on a broken proxy.
//
// `replacementStart16 == UINT32_MAX` infers the range from the proxy itself: the
// marked run keeps its absolute offset, so the text before it (the old head)
// must survive verbatim at the front of `base`; the preedit is then installed at
// that same offset and everything after it is whatever the new base carries
// there. A change inside the head (or a shortened head) is refused, never
// guessed.
static CjguiInternalRendererStatus
CjguiInstallCompositionReanchor(CJGuiInternalComposableSceneOverlay *overlay,
                                CJGuiInternalComposableInputProxy *proxy, NSString *base,
                                uint32_t replacementStart16, uint32_t replacementLength16,
                                uint32_t *outMechanism, NSRange *outMarked, NSRange *outInner) {
    if (!outMechanism || !outMarked || !outInner || !base) {
        fprintf(stderr, "CJGUI_REANCHOR_REFUSED reason=bad_arguments\n");
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    *outMechanism = 0;
    *outMarked = NSMakeRange(0, 0);
    *outInner = NSMakeRange(0, 0);
    if (!proxy || !proxy.hasMarkedText || !proxy.compositionSessionOwned) {
        fprintf(stderr, "CJGUI_REANCHOR_REFUSED reason=no_live_composition proxy=%d marked=%d owned=%d\n",
            (int)(proxy != nil), proxy ? (int)proxy.hasMarkedText : 0,
            proxy ? (int)proxy.compositionSessionOwned : 0);
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    NSString *old = proxy.string ?: @"";
    NSRange marked = proxy.markedRange;
    if (marked.location == NSNotFound || NSMaxRange(marked) > old.length) {
        fprintf(stderr, "CJGUI_REANCHOR_REFUSED reason=marked_range_invalid loc=%ld len=%lu oldLen=%lu\n",
            (long)marked.location, (unsigned long)marked.length, (unsigned long)old.length);
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    NSString *preedit = [old substringWithRange:marked];
    NSRange inner = proxy.selectedRange;
    if (inner.location < marked.location || NSMaxRange(inner) > NSMaxRange(marked)) {
        fprintf(stderr, "CJGUI_REANCHOR_REFUSED reason=inner_outside_marked inner=%lu+%lu marked=%lu+%lu\n",
            (unsigned long)inner.location, (unsigned long)inner.length,
            (unsigned long)marked.location, (unsigned long)marked.length);
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    NSUInteger innerAnchor = inner.location - marked.location;
    NSUInteger innerFocus = NSMaxRange(inner) - marked.location;
    // UINT32_MAX-1: infer the range AND leave the client unmarked (no re-install).
    // The experiment this serves: does the input source itself survive the storage
    // update, or is the conversion buffer already gone?
    BOOL allowReinstall = YES;
    if (replacementStart16 == UINT32_MAX - 1) {
        allowReinstall = NO;
        replacementStart16 = UINT32_MAX;
    }
    if (replacementStart16 == UINT32_MAX) {
        NSString *head = [old substringToIndex:marked.location];
        // `hasPrefix:@""` answers NO on this Foundation, and an empty head is the
        // ordinary "composition at offset 0" case, so test the length explicitly.
        if (head.length > 0 && ![base hasPrefix:head]) {
            fprintf(stderr, "CJGUI_REANCHOR_REFUSED reason=head_changed marked=%lu+%lu baseLen=%lu oldLen=%lu "
                    "base=[%s] old=[%s]\n",
                (unsigned long)marked.location, (unsigned long)marked.length,
                (unsigned long)base.length, (unsigned long)old.length,
                [[base substringToIndex:MIN(base.length, (NSUInteger)48)] UTF8String],
                [[old substringToIndex:MIN(old.length, (NSUInteger)48)] UTF8String]);
            return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        }
        replacementStart16 = (uint32_t)head.length;
        replacementLength16 = 0;
    }
    if ((NSUInteger)replacementStart16 > base.length ||
        (NSUInteger)replacementLength16 > base.length - (NSUInteger)replacementStart16) {
        fprintf(stderr, "CJGUI_REANCHOR_REFUSED reason=range_outside_base start=%u len=%u baseLen=%lu\n",
            replacementStart16, replacementLength16, (unsigned long)base.length);
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    NSString *newPrefix = [base substringToIndex:(NSUInteger)replacementStart16];
    NSString *newSuffix = [base substringFromIndex:(NSUInteger)replacementStart16 + (NSUInteger)replacementLength16];
    NSString *target = [NSString stringWithFormat:@"%@%@%@", newPrefix, preedit, newSuffix];
    NSUInteger expectedMarkedStart = newPrefix.length;
    uint32_t mechanism = 1;
    BOOL targetAlreadyInstalled = [old isEqualToString:target] && marked.location == expectedMarkedStart &&
        marked.length == preedit.length;
    if (!targetAlreadyInstalled) {
        // Mechanism 1: edit only the storage outside the marked run. Tail first, then
        // head; with the marked run untouched the platform composition keeps its
        // segment and attributes. The edits go through shouldChangeTextInRange:/
        // didChangeText so the text view adjusts its own ranges (including the
        // marked run) instead of seeing a raw storage mutation and dropping it.
        overlay.applyingProjection = YES;
        overlay.compositionTerminalInFlight = YES;
        NSTextStorage *storage = proxy.textStorage;
        NSRange tailRange = NSMakeRange(NSMaxRange(marked), old.length - NSMaxRange(marked));
        if ([proxy shouldChangeTextInRange:tailRange replacementString:newSuffix]) {
            [storage replaceCharactersInRange:tailRange withString:newSuffix];
            [proxy didChangeText];
        }
        NSRange headRange = NSMakeRange(0, marked.location);
        if ([proxy shouldChangeTextInRange:headRange replacementString:newPrefix]) {
            [storage replaceCharactersInRange:headRange withString:newPrefix];
            [proxy didChangeText];
        }
        overlay.compositionTerminalInFlight = NO;
        overlay.applyingProjection = NO;
        if (!allowReinstall) {
            mechanism = 3;
        } else if (!proxy.hasMarkedText) {
            // Mechanism 2: the storage edits ended the marked state. Re-install the
            // same preedit through the ordinary client entry, on the same node. The
            // replacement range must describe where the preedit lives NOW: the
            // storage edit already put it in place, so it replaces the run the old
            // preedit occupied instead of inserting a second copy.
            NSString *current = proxy.string ?: @"";
            NSUInteger replaceLength = 0;
            if ([current isEqualToString:target]) {
                replaceLength = preedit.length;
            } else if (![current isEqualToString:base]) {
                return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
            }
            mechanism = 2;
            overlay.applyingProjection = YES;
            overlay.compositionTerminalInFlight = YES;
            [(NSTextView *)proxy setMarkedText:preedit
                                 selectedRange:NSMakeRange(innerAnchor, innerFocus - innerAnchor)
                              replacementRange:NSMakeRange(expectedMarkedStart, replaceLength)];
            overlay.compositionTerminalInFlight = NO;
            overlay.applyingProjection = NO;
        }
    }
    // Read back what the proxy actually holds before reporting success.
    NSString *readBack = proxy.string ?: @"";
    NSRange readMarked = proxy.markedRange;
    if (mechanism == 3) {
        // The client is intentionally left unmarked: only the text has to be right.
        if (![readBack isEqualToString:target]) {
            fprintf(stderr, "CJGUI_REANCHOR_REFUSED reason=readback_mismatch_unmarked readLen=%lu targetLen=%lu\n",
                (unsigned long)readBack.length, (unsigned long)target.length);
            return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        }
        proxy.compositionBaseString = base;
        proxy.compositionBaseSelection = NSMakeRange((NSUInteger)replacementStart16, 0);
        if ([proxy respondsToSelector:@selector(inputContext)]) {
            [(NSTextInputContext *)[proxy inputContext] invalidateCharacterCoordinates];
        }
        // The unmarked route has no marked run to read back; the preedit sits in the
        // storage as ordinary text. Print it so the discriminant record shows which
        // mechanism actually ran.
        fprintf(stderr, "CJGUI_REANCHOR_INSTALL mechanism=%u marked=0+0 inner=0+0 baseLen=%lu "
                "unmarked_preedit=%lu\n",
            mechanism, (unsigned long)base.length, (unsigned long)preedit.length);
        *outMechanism = mechanism;
        *outMarked = NSMakeRange(expectedMarkedStart, preedit.length);
        *outInner = NSMakeRange(expectedMarkedStart + innerAnchor, innerFocus - innerAnchor);
        overlay.activeTextAttributedGeneration += 1;
#ifdef CJGUI_INTERNAL_TESTING
        overlay.testActiveTextWorkReason = CjguiInternalTextWorkReasonActiveContent;
#endif
        [overlay refreshGpuTextForActiveInput];
        [overlay setNeedsDisplay:YES];
        return CJGUI_INTERNAL_RENDERER_OK;
    }
    if (![readBack isEqualToString:target] || !proxy.hasMarkedText ||
        readMarked.location == NSNotFound || readMarked.location != expectedMarkedStart ||
        readMarked.length != preedit.length) {
        fprintf(stderr, "CJGUI_REANCHOR_REFUSED reason=readback_mismatch mechanism=%u marked=%ld+%lu "
                "expected=%lu+%lu readLen=%lu targetLen=%lu\n",
            mechanism, (long)readMarked.location, (unsigned long)readMarked.length,
            (unsigned long)expectedMarkedStart, (unsigned long)preedit.length,
            (unsigned long)readBack.length, (unsigned long)target.length);
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    // The cancel base must roll back to the NEW projection, not the pre-write one.
    proxy.compositionBaseString = base;
    proxy.compositionBaseSelection = NSMakeRange((NSUInteger)replacementStart16, 0);
    NSRange applied = NSMakeRange(readMarked.location + innerAnchor, innerFocus - innerAnchor);
    overlay.applyingProjection = YES;
    proxy.selectedRange = applied;
    overlay.applyingProjection = NO;
    NSRange readSel = proxy.selectedRange;
    if (readSel.location < readMarked.location || NSMaxRange(readSel) > NSMaxRange(readMarked)) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    if ([proxy respondsToSelector:@selector(inputContext)]) {
        [(NSTextInputContext *)[proxy inputContext] invalidateCharacterCoordinates];
    }
    *outMechanism = mechanism;
    *outMarked = readMarked;
    *outInner = readSel;
    fprintf(stderr, "CJGUI_REANCHOR_INSTALL mechanism=%u marked=%lu+%lu inner=%lu+%lu baseLen=%lu\n",
        mechanism, (unsigned long)readMarked.location, (unsigned long)readMarked.length,
        (unsigned long)readSel.location, (unsigned long)(NSMaxRange(readSel) - readSel.location),
        (unsigned long)base.length);
    overlay.activeTextAttributedGeneration += 1;
#ifdef CJGUI_INTERNAL_TESTING
    overlay.testActiveTextWorkReason = CjguiInternalTextWorkReasonActiveContent;
#endif
    [overlay refreshGpuTextForActiveInput];
    [overlay setNeedsDisplay:YES];
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_reanchor_composition(uint64_t session, uint64_t nodeId,
                                             int64_t resourceId, uint32_t nodeKind,
                                             uint64_t sceneVersion, const char *newBaseText,
                                             uint32_t replacementStart16, uint32_t replacementLength16,
                                             uint32_t *outMechanism,
                                             uint32_t *outMarkedStart16, uint32_t *outMarkedLength16,
                                             uint32_t *outInnerStart16, uint32_t *outInnerEnd16) {
    if (!outMechanism || !outMarkedStart16 || !outMarkedLength16 || !outInnerStart16 ||
        !outInnerEnd16 || !newBaseText) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    *outMechanism = 0;
    *outMarkedStart16 = 0; *outMarkedLength16 = 0; *outInnerStart16 = 0; *outInnerEnd16 = 0;
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = cjgui_internal_renderer_reanchor_composition(session, nodeId, resourceId, nodeKind,
                sceneVersion, newBaseText, replacementStart16, replacementLength16, outMechanism,
                outMarkedStart16, outMarkedLength16, outInnerStart16, outInnerEnd16);
        });
        return status;
    }
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.composableSceneOverlay || !ctx.window) {
        return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
    if (ctx.composableSceneVersion != sceneVersion) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    CJGuiInternalComposableInputProxy *proxy = (CJGuiInternalComposableInputProxy *)overlay.inputProxy;
    if (!proxy || !proxy.hasMarkedText || !proxy.compositionSessionOwned ||
        !CjguiInputProxyIsFirstResponder(overlay)) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    if (proxy.compositionSessionNodeId != nodeId || proxy.compositionSessionResourceId != resourceId ||
        proxy.compositionSessionNodeKind != nodeKind) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    NSString *base = [NSString stringWithUTF8String:newBaseText];
    if (!base) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    uint32_t mechanism = 0;
    NSRange readMarked = NSMakeRange(0, 0);
    NSRange readSel = NSMakeRange(0, 0);
    CjguiInternalRendererStatus installed = CjguiInstallCompositionReanchor(overlay, proxy, base,
        replacementStart16, replacementLength16, &mechanism, &readMarked, &readSel);
    if (installed != CJGUI_INTERNAL_RENDERER_OK) {
        return installed;
    }
    *outMechanism = mechanism;
    *outMarkedStart16 = (uint32_t)readMarked.location;
    *outMarkedLength16 = (uint32_t)readMarked.length;
    *outInnerStart16 = (uint32_t)readSel.location;
    *outInnerEnd16 = (uint32_t)NSMaxRange(readSel);
    return CJGUI_INTERNAL_RENDERER_OK;
}

// REANCHOR: arm one request for the NEXT accepted scene of this exact node. The
// window calls this before publishing a candidate whose owner value advanced
// during an arbitrated composition; the accept path then preserves the live
// marked run instead of cancelling it. `baseText == NULL` clears the request.
// Arming changes no proxy state and no owner state.
CjguiInternalRendererStatus
cjgui_internal_renderer_arm_composition_reanchor(uint64_t session, uint64_t nodeId,
                                                 int64_t resourceId, uint32_t nodeKind,
                                                 const char *baseText,
                                                 uint32_t replacementStart16,
                                                 uint32_t replacementLength16) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = cjgui_internal_renderer_arm_composition_reanchor(session, nodeId, resourceId,
                nodeKind, baseText, replacementStart16, replacementLength16);
        });
        return status;
    }
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.composableSceneOverlay) {
        return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    if (!baseText) {
        overlay.armedReanchorBase = nil;
        overlay.armedReanchorActive = NO;
        overlay.armedReanchorNodeId = 0;
        overlay.armedReanchorResourceId = -1;
        overlay.armedReanchorNodeKind = 0;
        return CJGUI_INTERNAL_RENDERER_OK;
    }
    NSString *base = [NSString stringWithUTF8String:baseText];
    if (!base) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    overlay.armedReanchorNodeId = nodeId;
    overlay.armedReanchorResourceId = resourceId;
    overlay.armedReanchorNodeKind = nodeKind;
    overlay.armedReanchorStart16 = replacementStart16;
    overlay.armedReanchorLength16 = replacementLength16;
    overlay.armedReanchorBase = base;
    overlay.armedReanchorActive = YES;
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_read_composable_selection(uint64_t session, uint64_t nodeId,
                                                  int64_t resourceId, uint32_t nodeKind,
                                                  uint64_t sceneVersion, const char *expectedValue,
                                                  uint32_t *outSelectionStart, uint32_t *outSelectionEnd) {
    if (!outSelectionStart || !outSelectionEnd || !expectedValue) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    *outSelectionStart = 0; *outSelectionEnd = 0;
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        CjguiOwnerTraceDispatchSync(session, nodeId, CJGUI_OWNER_PHASE_NATIVE_READ_SELECTION, ^{
            status = cjgui_internal_renderer_read_composable_selection(session, nodeId, resourceId, nodeKind,
                sceneVersion, expectedValue, outSelectionStart, outSelectionEnd);
        });
        return status;
    }
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.composableSceneOverlay || !ctx.window) {
        return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
    if (ctx.composableSceneVersion != sceneVersion) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    NSString *expected = [NSString stringWithUTF8String:expectedValue];
    if (!expected || !CjguiInputProxyIsFirstResponder(overlay) || overlay.inputProxy.hasMarkedText) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    for (CJGuiInternalComposableSceneNode *node in ctx.composableNodes) {
        if (node.node.nodeId != nodeId || node.node.resourceId != resourceId ||
            node.node.nodeKind != nodeKind || node.node.isInteractive == 0 ||
            overlay.activeNodeId != nodeId || overlay.activeNodeIndex != node.index ||
            overlay.activeNodeResourceId != resourceId || overlay.activeNodeKind != nodeKind ||
            overlay.activeProjectionVersion != node.node.projectionVersion) continue;
        if (![node.value isEqualToString:expected] || ![overlay.inputProxy.string isEqualToString:expected]) {
            return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        }
        NSRange selected = overlay.inputProxy.selectedRange;
        if (selected.location > UINT32_MAX || NSMaxRange(selected) > UINT32_MAX) {
            return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        }
        *outSelectionStart = (uint32_t)selected.location;
        *outSelectionEnd = (uint32_t)NSMaxRange(selected);
        return CJGUI_INTERNAL_RENDERER_OK;
    }
    return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
}


// Roll back the hidden text proxy after the application REFUSED a range edit.
//
// A refused edit leaves the platform proxy holding local text the owner never
// accepted. The ordinary projection path cannot repair it: the Cangjie scene is
// unchanged (so the semantic fast path and per-node reuse skip staging), and the
// native value check treats "candidate == previous value" plus "proxy != previous
// value" as a local edit that must be preserved. This entry repairs exactly that
// transient state:
//   - the target must still be the ACTIVE node with the same identity and
//     projection version,
//   - the accepted value must still be the value the committed node carries,
//   - no composition may be in flight.
// It installs the accepted text under projection suppression (so no synthetic
// human edit event is produced), installs a grapheme-safe collapsed caret, and
// invalidates the derived text resources, accessibility value and paint. It
// never invents document truth: it only restores what the owner already
// accepted. Returns the installed UTF-16 selection through the out parameters.
CjguiInternalRendererStatus
cjgui_internal_renderer_recover_active_text_proxy(uint64_t session, uint64_t nodeId,
                                                  int64_t resourceId, uint32_t nodeKind,
                                                  const char *acceptedValue,
                                                  uint32_t *outSelectionStart, uint32_t *outSelectionEnd) {
    if (!outSelectionStart || !outSelectionEnd || !acceptedValue) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    *outSelectionStart = 0; *outSelectionEnd = 0;
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        CjguiOwnerTraceDispatchSync(session, nodeId, CJGUI_OWNER_PHASE_NATIVE_RECOVER_TEXT_PROXY, ^{
            status = cjgui_internal_renderer_recover_active_text_proxy(session, nodeId, resourceId, nodeKind,
                acceptedValue, outSelectionStart, outSelectionEnd);
        });
        return status;
    }
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.composableSceneOverlay || !ctx.window) {
        return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
    if (nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT_INPUT &&
        nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_INTEGER_INPUT &&
        nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT &&
        nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    NSString *accepted = [NSString stringWithUTF8String:acceptedValue];
    if (!accepted) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    // Never clobber an in-flight composition, and never repair an unfocused
    // node: the intent only ever describes the active speculative edit.
    if (overlay.inputProxy.hasMarkedText || !CjguiInputProxyIsFirstResponder(overlay)) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    for (CJGuiInternalComposableSceneNode *node in ctx.composableNodes) {
        if (node.node.nodeId != nodeId || node.node.resourceId != resourceId ||
            node.node.nodeKind != nodeKind || node.node.isInteractive == 0 || node.node.isReadOnly != 0 ||
            overlay.activeNodeId != nodeId || overlay.activeNodeIndex != node.index ||
            overlay.activeNodeResourceId != resourceId || overlay.activeNodeKind != nodeKind ||
            overlay.activeProjectionVersion != node.node.projectionVersion) continue;
        // The committed node is the accepted truth; anything else means the
        // scene moved on and the caller must use the normal projection path.
        if (![node.value isEqualToString:accepted]) {
            return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        }
        NSRange applied = CjguiComposedSelection(accepted, accepted.length, accepted.length);
        overlay.applyingProjection = YES;
        overlay.inputProxy.string = accepted;
        overlay.inputProxy.selectedRange = applied;
        overlay.applyingProjection = NO;
        overlay.activeTextFallbackHasPendingEdit = NO;
        overlay.activeTextRangeEditPending = NO;
        // The accepted value is installed below, so nothing is awaiting the owner any more.
        overlay.activeLocalEditAwaitingOwner = NO;
        overlay.activeLocalEditProjectionVersion = 0;
        overlay.activeTextLayoutNeedsVisibleGlyphs = YES;
        overlay.activeTextHasExactContentHeight = NO;
        if (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) {
            [overlay markActiveTextFallbackRunsDirtyForWholeValue];
        }
        applied = overlay.inputProxy.selectedRange;
        if (applied.location > UINT32_MAX || NSMaxRange(applied) > UINT32_MAX) {
            return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        }
        *outSelectionStart = (uint32_t)applied.location;
        *outSelectionEnd = (uint32_t)NSMaxRange(applied);
        [overlay postAccessibilityValueChangedForNode:node];
        [overlay postAccessibilitySelectionChangedForNode:node];
        [overlay refreshGpuTextForActiveInput];
        [overlay setNeedsDisplay:YES];
        return CJGUI_INTERNAL_RENDERER_OK;
    }
    return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_cancel_composable_pointer_capture(uint64_t session) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = cjgui_internal_renderer_cancel_composable_pointer_capture(session);
        });
        return status;
    }
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.composableSceneOverlay) {
        return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
    [ctx.composableSceneOverlay cancelPointerCapture];
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_cancel_composable_pointer_capture_epoch(uint64_t session,
                                                                 uint64_t gestureEpoch) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = cjgui_internal_renderer_cancel_composable_pointer_capture_epoch(session, gestureEpoch);
        });
        return status;
    }
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.composableSceneOverlay) {
        return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    if (gestureEpoch != 0 && overlay.pointerCaptureActive &&
        overlay.pointerCaptureGestureEpoch == gestureEpoch) [overlay cancelPointerCapture];
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_cancel_composable_pointer_capture_gesture_key(
    uint64_t session, uint64_t appInstance, uint64_t componentInstance,
    uint64_t surfaceGeneration, int64_t pointerId, uint64_t gestureEpoch) {
    (void)session; (void)appInstance; (void)componentInstance;
    (void)surfaceGeneration; (void)pointerId; (void)gestureEpoch;
    return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
