// Main-thread-only, opt-in first rejection facts; no guard or retry policy is
// changed. Each live generation has one latch, including failures in present.
static uint64_t gCjguiCandidateFailureGeneration[kCjguiSessionCapacity];
static CjguiInternalRendererStatus CjguiCandidateFailure(CJGuiInternalSession *ctx,
    CjguiInternalRendererStatus status, const char *branch, uint64_t actual, uint64_t expected) {
    if (!getenv("CJGUI_CANDIDATE_FIRST_FAILURE") || !ctx || ctx.rendererSessionToken == 0 ||
        ctx.rendererSessionToken > kCjguiSessionCapacity) return status;
    NSUInteger index = (NSUInteger)ctx.rendererSessionToken - 1;
    if (gCjguiCandidateFailureGeneration[index] == ctx.sessionGeneration) return status;
    gCjguiCandidateFailureGeneration[index] = ctx.sessionGeneration;
    CJGuiInternalComposableSceneOverlay *edge = ctx.composableSceneOverlay;
    CjguiComposablePreparation *p = ctx.composablePreparation;
    fprintf(stderr, "CJGUI_NATIVE_CANDIDATE_FIRST_FAILURE pid=%d session=%llu generation=%llu "
        "turn=%llu branch=%s status=%u actual=%llu expected=%llu scene=%llu candidate=%llu "
        "prepare=%llu cursor=%lu:%lu ready=%d gesture=%llu edge_phase=%u viewport_generation=%lld "
        "expected_offset=%lld installed=%llu proxy=%llu selection=%llu geometry=%lu nodes=%lu "
        "menu=%llu background=%llu:%d\n", getpid(), (unsigned long long)ctx.rendererSessionToken,
        (unsigned long long)ctx.sessionGeneration,
        (unsigned long long)atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn, memory_order_acquire),
        branch, (unsigned)status, (unsigned long long)actual, (unsigned long long)expected,
        (unsigned long long)ctx.composableSceneVersion, (unsigned long long)ctx.stagedComposableSceneVersion,
        (unsigned long long)p.preparationId, (unsigned long)p.nodeCursor, (unsigned long)p.tileCursor, p.ready,
        (unsigned long long)edge.pointerCaptureGestureEpoch, edge.dragEdgeScrollPhase,
        (long long)edge.dragEdgeScrollRequestGeneration, (long long)edge.dragEdgeScrollExpectedOffset,
        (unsigned long long)ctx.selectionReceiptTransferId, (unsigned long long)ctx.installedRangeProxyGeneration,
        (unsigned long long)edge.installedRangeSelectionRevision,
        (unsigned long)ctx.stagedComposableGeometryIndices.count, (unsigned long)ctx.stagedComposableNodes.count,
        (unsigned long long)ctx.stagedComposableCommandMenuVersion,
        (unsigned long long)ctx.stagedWindowBackgroundVersion, ctx.hasStagedWindowBackground);
    return status;
}

static CjguiInternalRendererStatus CjguiCommitComposableSceneOnMain(uint64_t session) {
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.view || !ctx.composableSceneOverlay || ctx.stagedComposableNodes.count == 0) {
        return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t started = CjguiMonotonicMicros();
#endif
    NSUInteger geometryCount = ctx.stagedComposableGeometryIndices.count;
    if (geometryCount > 0 && geometryCount != ctx.stagedComposableNodes.count) {
        if (getenv("CJGUI_TEXT_PREPARE_TRACE")) fprintf(stderr,
            "CJGUI_SCENE_COMMIT_REFUSED reason=geometry_count geometry=%lu nodes=%lu\n",
            (unsigned long)geometryCount, (unsigned long)ctx.stagedComposableNodes.count);
        return CjguiCandidateFailure(ctx, CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR,
            "commit_geometry_count", geometryCount, ctx.stagedComposableNodes.count);
    }
    // Old native clients that do not stage geometry explicitly get the identity
    // transform. A previous translated scene may not leak into their candidate.
    if (geometryCount == 0) {
        for (NSUInteger index = 0; index < ctx.stagedComposableNodes.count; index++) {
            CJGuiInternalComposableSceneNode *node = ctx.stagedComposableNodes[index];
            CjguiInternalRendererComposableGeometry identity = {0};
            CjguiInternalRendererComposableGeometry oldGeometry = node.geometry;
            if (memcmp(&oldGeometry, &identity, sizeof(identity)) == 0) continue;
            CJGuiInternalComposableSceneNode *live = index < ctx.composableNodes.count ? ctx.composableNodes[index] : nil;
            if (node == live) {
                node = CjguiCloneComposableSceneNode(ctx, live, (uint32_t)index, ctx.stagedComposableSceneVersion);
                if (!node) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
                ctx.stagedComposableNodes[index] = node;
            }
            node.geometry = identity;
        }
    }
    for (CJGuiInternalComposableSceneNode *node in ctx.stagedComposableNodes) {
        // Reused COW entries intentionally keep their original capture
        // version. Only a never-initialized slot is invalid; native FIFO
        // provenance comes from the committed session version below.
        if (node.node.projectionVersion == 0) {
            if (getenv("CJGUI_TEXT_PREPARE_TRACE")) fprintf(stderr,
                "CJGUI_SCENE_COMMIT_REFUSED reason=empty_projection node=%llu\n",
                (unsigned long long)node.node.nodeId);
            return CjguiCandidateFailure(ctx, CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR,
                "commit_empty_projection", node.node.nodeId, ctx.stagedComposableSceneVersion);
        }
    }
    CjguiInternalRendererStatus effectTopology = CjguiValidateEffectGroupTopology(ctx.stagedComposableNodes);
    if (effectTopology != CJGUI_INTERNAL_RENDERER_OK) return effectTopology;
    if (ctx.stagedComposableCommandMenuVersion != 0 &&
        (ctx.stagedComposableCommandMenuVersion != ctx.stagedComposableSceneVersion ||
         !CjguiComposableCommandMenuStagingIsComplete(ctx))) {
        if (getenv("CJGUI_TEXT_PREPARE_TRACE")) fprintf(stderr,
            "CJGUI_SCENE_COMMIT_REFUSED reason=menu_incomplete\n");
        return CjguiCandidateFailure(ctx, CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR,
            "commit_menu_incomplete", ctx.stagedComposableCommandMenuVersion, ctx.stagedComposableSceneVersion);
    }
    if (ctx.stagedComposableDataTransferVersion != ctx.stagedComposableSceneVersion) {
        return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    }
    for (CJGuiInternalComposableDataTransferItem *item in ctx.stagedComposableDataTransferItems) {
        CjguiInternalRendererComposableDataTransferItem itemValue = item.item;
        if (!CjguiComposableDataTransferFormatIsValid(item.format) ||
            itemValue.projectionVersion != ctx.stagedComposableSceneVersion ||
            !CjguiComposableStagedNodeMatchesDataTransferItem(ctx, &itemValue)) {
            return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
        }
        NSData *payload = [item.payload dataUsingEncoding:NSUTF8StringEncoding];
        BOOL png = [item.format isEqualToString:@"image/png"];
        if (!payload || payload.length > item.item.maximumPayloadBytes ||
            (png && item.item.bindingEpoch == 0) ||
            (png && item.item.role == CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_SOURCE &&
             (item.binaryPayload.length == 0 || item.binaryPayload.length > item.item.maximumPayloadBytes)) ||
            (png && item.item.role == CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_TARGET && item.binaryPayload.length != 0) ||
            (item.item.role == CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_TARGET && (payload.length != 0 ||
             item.sourceKind.length != 0 || item.sourceIdentity.length != 0 || item.item.sourceId >= 0)) ||
            (item.item.role == CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_SOURCE && (item.sourceKind.length == 0 ||
             item.sourceIdentity.length == 0 || item.item.sourceId < 0))) {
            return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
        }
    }
    // Text resources are prepared while admitting the immutable scene, never
    // from the Metal encoder.  This keeps AppKit text shaping out of the
    // frame-critical command-buffer path and lets the encoder only reuse a
    // committed texture.
    uint64_t resourceTurn = atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn, memory_order_acquire);
    uint64_t resourceSpan = CjguiOwnerTraceAppend(CJGUI_OWNER_TRACE_PHASE_BEGIN, session,
        resourceTurn, ctx.stagedComposableSceneVersion, 0, ctx.sessionGeneration,
        CJGUI_OWNER_PHASE_NATIVE_SCENE_RESOURCES, 0);
    CjguiInternalRendererStatus textStatus = CjguiPrepareComposableTextResources(ctx);
    CjguiOwnerTraceAppend(CJGUI_OWNER_TRACE_PHASE_END, session, resourceTurn,
        ctx.stagedComposableSceneVersion, 0, ctx.sessionGeneration,
        CJGUI_OWNER_PHASE_NATIVE_SCENE_RESOURCES, resourceSpan);
    if (textStatus != CJGUI_INTERNAL_RENDERER_OK) {
        if (getenv("CJGUI_TEXT_PREPARE_TRACE")) fprintf(stderr,
            "CJGUI_SCENE_COMMIT_REFUSED reason=text_resource status=%u\n", (unsigned)textStatus);
        return CjguiCandidateFailure(ctx, textStatus, "commit_text_resource", textStatus, CJGUI_INTERNAL_RENDERER_OK);
    }
    BOOL imageContentChanged = CjguiComposableImageContentChanged(ctx.composableNodes, ctx.stagedComposableNodes);
    uint64_t previousMenuFocusScope = CjguiComposableCommandMenuActiveFocusScope(ctx);
    BOOL menuProjectionChanged = NO;
    ctx.composableSceneVersion = ctx.stagedComposableSceneVersion;
    ctx.composableNodes = [ctx.stagedComposableNodes mutableCopy];
    ctx.composableDataTransferItems = [ctx.stagedComposableDataTransferItems mutableCopy];
    ctx.composableDataTransferVersion = ctx.stagedComposableDataTransferVersion;
#ifdef CJGUI_INTERNAL_TESTING
    CjguiUpdateTestDataTransferRetentionPeaks(ctx);
#endif
    if (ctx.stagedComposableCommandMenuVersion == ctx.composableSceneVersion) {
        menuProjectionChanged = CjguiCommitStagedComposableCommandMenu(ctx);
    }
    // This is the only promotion boundary for image subscribers. Candidate
    // configure/set failures and present rollback keep the old committed
    // subscriptions intact, while the newly accepted scene replaces them
    // atomically before a later completion can wake this window.
    CjguiReconcileCommittedComposableImageSubscribers(ctx);
    // The candidate cycle ended: a transfer lease that the just-committed
    // scene did not take has no further use holding a texture.
    CjguiSettleComposableImageCandidateLeases(CjguiComposableImageDomainForSession(ctx), ctx, NO);
    CjguiPruneUnreferencedComposableTransferResources(CjguiComposableImageDomainForSession(ctx));
    CjguiPruneComposableImageTextureCache(CjguiComposableImageDomainForSession(ctx), NO);
    ctx.view.composableNodes = [ctx.composableNodes copy];
    if (imageContentChanged) {
        ctx.view.readbackProbeCompleted = NO;
        ctx.view.readbackProbeColorMatched = NO;
        ctx.view.readbackProbeImageTag = [NSObject new];
    }
    // A readback is a first-frame rendering diagnostic, not normal editing
    // work. Scene updates still submit Metal commands, but do not force a
    // synchronous GPU readback after every keystroke or lightweight refresh.
    ctx.sharedOperationOverlay.hidden = YES;
    ctx.sharedEditingFormOverlay.hidden = YES;
    // The renderer may encode this candidate, but AppKit input/AX is still
    // owned by the prior accepted scene until present returns success. A
    // pre-commit encoder failure must not publish focus or AX notifications.
    uint64_t currentMenuFocusScope = CjguiComposableCommandMenuActiveFocusScope(ctx);
    if (ctx.window == NSApp.keyWindow &&
        (menuProjectionChanged || previousMenuFocusScope != currentMenuFocusScope)) {
        CjguiRebuildComposableCommandMenuForKeyWindow();
    }
    // Title ownership is the application-host configuration. A scene commit
    // may refresh business content but must not overwrite that declaration.
#ifdef CJGUI_INTERNAL_TESTING
    ctx.testComposableSceneCommitMicros += CjguiMonotonicMicros() - started;
#endif
    return CJGUI_INTERNAL_RENDERER_OK;
}

static CjguiInternalRendererStatus CjguiStageWindowBackgroundOnMain(uint64_t sessionToken,
                                                                     uint64_t projectionVersion,
                                                                     uint32_t mode,
                                                                     uint32_t colorScheme) {
    CJGuiInternalSession *session = CjguiLookupSession(sessionToken);
    if (!session || session.destroyed || !session.window) {
        return session ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
    if (projectionVersion == 0 || mode > CJGUI_INTERNAL_WINDOW_BACKGROUND_SYSTEM_CONTENT_AREA ||
        (colorScheme != 1 && colorScheme != 2)) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    session.stagedWindowBackgroundVersion = projectionVersion;
    session.stagedWindowBackgroundMode = mode;
    session.stagedWindowBackgroundColorScheme = colorScheme;
    session.stagedWindowBackgroundRequestRevision = session.windowBackgroundRequestRevision +
        ((session.windowBackgroundRequestedMode != mode ||
          session.windowBackgroundColorScheme != colorScheme) ? 1u : 0u);
    session.hasStagedWindowBackground = YES;
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_stage_window_background(uint64_t session, uint64_t projectionVersion,
                                                uint32_t mode, uint32_t colorScheme) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        CjguiOwnerTraceDispatchSync(session, projectionVersion, CJGUI_OWNER_PHASE_NATIVE_BACKGROUND_STAGE, ^{
            status = CjguiStageWindowBackgroundOnMain(session, projectionVersion, mode, colorScheme);
        });
        return status;
    }
    return CjguiStageWindowBackgroundOnMain(session, projectionVersion, mode, colorScheme);
}

CjguiInternalRendererStatus
cjgui_internal_renderer_window_background_snapshot(uint64_t session,
    CjguiInternalRendererWindowBackgroundSnapshot *outSnapshot) {
    if (!outSnapshot) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    memset(outSnapshot, 0, sizeof(*outSnapshot));
    if (!CjguiIsMainThread()) return CjguiReadWindowBackgroundSnapshot(session, outSnapshot);
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || ctx.destroyed || ctx.closeRequested) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    CjguiFillWindowBackgroundSnapshot(ctx, outSnapshot);
    CjguiPublishWindowBackgroundSnapshot(ctx);
    return CJGUI_INTERNAL_RENDERER_OK;
}

static CjguiInternalRendererStatus
CjguiPresentComposableSceneOnMain(uint64_t session, CjguiInternalRendererFrameObservation *outObservation) {
#ifdef CJGUI_INTERNAL_TESTING
    CJGuiInternalSession *candidate = CjguiLookupSession(session);
    if (candidate && candidate.testPendingComposableTicket != 0 &&
        !candidate.testResolvingComposableTicket) {
        if (outObservation) outObservation->ticketId = candidate.testPendingComposableTicket;
        return CJGUI_INTERNAL_RENDERER_PRESENT_PENDING;
    }
    if (candidate && candidate.testHoldNextComposablePresent > 0) {
        if (!candidate.hasStagedWindowBackground ||
            candidate.stagedWindowBackgroundVersion != candidate.stagedComposableSceneVersion)
            return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        candidate.testHoldNextComposablePresent = 0;
        candidate.testNextComposableTicket += 1;
        candidate.testPendingComposableTicket = candidate.testNextComposableTicket;
        CjguiInternalRendererPresentReceipt receipt = {0};
        receipt.ticketId = candidate.testPendingComposableTicket;
        receipt.projectionVersion = candidate.stagedComposableSceneVersion;
        receipt.decision = CJGUI_INTERNAL_RENDERER_PRESENT_DECISION_PENDING;
        candidate.testPendingComposableReceipt = receipt;
        if (outObservation) outObservation->ticketId = receipt.ticketId;
        return CJGUI_INTERNAL_RENDERER_PRESENT_PENDING;
    }
    if (candidate && candidate.forcedComposablePresentFailures > 0) {
        candidate.forcedComposablePresentFailures -= 1;
        // The Cangjie caller will keep its accepted scene on this error.  The
        // staged image setters may already have registered candidate demand,
        // so restore requesters/subscribers from that accepted native scene
        // before returning the test seam's forced rejection.
        CjguiRestoreAcceptedComposableImageDemand(candidate);
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
#endif
    CJGuiInternalSession *beforeCommit = CjguiLookupSession(session);
    if (!beforeCommit || !beforeCommit.hasStagedWindowBackground ||
        beforeCommit.stagedWindowBackgroundVersion != beforeCommit.stagedComposableSceneVersion) {
        return CjguiCandidateFailure(beforeCommit, CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR,
            "present_background_basis", beforeCommit.stagedWindowBackgroundVersion,
            beforeCommit.stagedComposableSceneVersion);
    }
    BOOL hasPreparedSelection=beforeCommit.selectionTransferCapsule.candidateSceneTransfer &&
        beforeCommit.selectionTransferCapsule.candidateInstallReady &&
        CjguiCandidateSelectionSourceReadbackMatches(beforeCommit,beforeCommit.selectionTransferCapsule);
    if (beforeCommit.selectionPaintTransferId && !hasPreparedSelection &&
        (beforeCommit.selectionPaintOwnerRevision < 0 ||
         beforeCommit.selectionPaintStagedScene != beforeCommit.stagedComposableSceneVersion)) {
        return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    }
    CjguiSelectionTransferCapsule *sceneTransfer=beforeCommit.selectionTransferCapsule;
    if (sceneTransfer && sceneTransfer.candidateSceneTransfer) {
        if (!sceneTransfer.candidateInstallReady ||
            beforeCommit.stagedComposableSceneVersion!=sceneTransfer.bSceneVersion ||
            !CjguiCandidateSelectionSourceReadbackMatches(beforeCommit,sceneTransfer))
            return CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    } else { sceneTransfer=nil; }
    NSArray<CJGuiInternalComposableSceneNode *> *previousNodes = [beforeCommit.composableNodes copy];
    uint64_t previousSceneVersion = beforeCommit.composableSceneVersion;
    NSArray<CJGuiInternalComposableDataTransferItem *> *previousDataTransferItems =
        [beforeCommit.composableDataTransferItems copy];
    uint64_t previousDataTransferVersion = beforeCommit.composableDataTransferVersion;
    NSArray<CJGuiInternalComposableCommandMenuItem *> *previousCommandMenuItems =
        [beforeCommit.composableCommandMenuItems copy];
    uint64_t previousCommandMenuVersion = beforeCommit.composableCommandMenuVersion;
    uint64_t previousBackgroundSceneVersion = beforeCommit.windowBackgroundAcceptedSceneVersion;
    uint32_t previousBackgroundRequestedMode = beforeCommit.windowBackgroundRequestedMode;
    uint32_t previousBackgroundColorScheme = beforeCommit.windowBackgroundColorScheme;
    uint32_t previousBackgroundFallbackReason = beforeCommit.windowBackgroundFallbackReason;
    uint32_t previousBackgroundCompletion = beforeCommit.windowBackgroundCompletion;
    uint64_t previousBackgroundSubmittedFrameIndex = beforeCommit.windowBackgroundSubmittedFrameIndex;
    uint64_t previousBackgroundSubmittedRequestRevision = beforeCommit.windowBackgroundSubmittedRequestRevision;
    uint64_t presentTurn = atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn, memory_order_acquire);
    uint64_t commitSpan = CjguiOwnerTraceAppend(CJGUI_OWNER_TRACE_PHASE_BEGIN, session,
        presentTurn, beforeCommit.stagedComposableSceneVersion, 0, beforeCommit.sessionGeneration,
        CJGUI_OWNER_PHASE_NATIVE_SCENE_COMMIT, 0);
    CjguiInternalRendererStatus committed = CjguiCommitComposableSceneOnMain(session);
    CjguiOwnerTraceAppend(CJGUI_OWNER_TRACE_PHASE_END, session, presentTurn,
        beforeCommit.stagedComposableSceneVersion, 0, beforeCommit.sessionGeneration,
        CJGUI_OWNER_PHASE_NATIVE_SCENE_COMMIT, commitSpan);
    if (committed != CJGUI_INTERNAL_RENDERER_OK) {
        // The rejection left partially prepared candidate resources installed
        // on staged-only nodes. Release those holds now, not at the next
        // configure/close; the accepted scene keeps working and the original
        // status is returned unchanged.
        CjguiReleaseFailedCandidateTextResources(CjguiLookupSession(session));
        CjguiReleaseFailedCandidateEffectTargets(CjguiLookupSession(session));
        return committed;
    }
    CJGuiInternalSession *candidateSession = CjguiLookupSession(session);
    uint32_t candidateMode = candidateSession.stagedWindowBackgroundMode;
    uint32_t candidateColorScheme = candidateSession.stagedWindowBackgroundColorScheme;
    uint32_t candidateActualMode = 0;
    uint32_t candidateFallbackReason = 0;
    BOOL hostPrepared = CjguiApplyWindowBackground(candidateSession, candidateMode, candidateColorScheme,
                                                    &candidateActualMode, &candidateFallbackReason);
    CjguiInternalRendererClearColor clear = candidateActualMode == 1
        ? (CjguiInternalRendererClearColor){ 0.0, 0.0, 0.0, 0.0 }
        : candidateColorScheme == 1
            ? (CjguiInternalRendererClearColor){ 0.94, 0.95, 0.97, 1.0 }
            : (CjguiInternalRendererClearColor){ 0.08, 0.16, 0.20, 1.0 };
    BOOL selectionCommitRight=NO;
    if (sceneTransfer && hostPrepared && CjguiCandidateSelectionSourceReadbackMatches(candidateSession,sceneTransfer)) {
        CJGuiInternalComposableSceneNode *target=nil;
        for (CJGuiInternalComposableSceneNode *node in candidateSession.composableNodes) {
            if (node.node.nodeId==sceneTransfer.bNodeId && node.node.resourceId==sceneTransfer.bResourceId &&
                node.node.nodeKind==sceneTransfer.bNodeKind && node.node.projectionVersion==sceneTransfer.bProjectionVersion &&
                [node.value isEqualToString:sceneTransfer.bBody]) { target=node; break; }
        }
        if (target) {
            target.textSelectionRects=sceneTransfer.candidateSelectionRects;
            target.textSelectionTransferId=sceneTransfer.transferId;
            if (!target.textCaretIsDeclared) target.textCaretRect=sceneTransfer.candidateSelectionCaret;
            selectionCommitRight=CjguiSelectionTransferBeginFinalizingWithPrecheck(session,sceneTransfer.transferId)==CJGUI_INTERNAL_RENDERER_OK;
        }
    }
    uint64_t frameSpan = CjguiOwnerTraceAppend(CJGUI_OWNER_TRACE_PHASE_BEGIN, session,
        presentTurn, candidateSession.stagedComposableSceneVersion, 0, candidateSession.sessionGeneration,
        CJGUI_OWNER_PHASE_NATIVE_FRAME_PRESENT, 0);
    candidateSession.selectionPaintPublishingScene = (candidateSession.selectionPaintTransferId || sceneTransfer)
        ? candidateSession.composableSceneVersion : 0;
    CjguiInternalRendererStatus status = hostPrepared && (!sceneTransfer || selectionCommitRight)
        ? cjgui_internal_renderer_present_clear(session, &clear, outObservation)
        : CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    candidateSession.selectionPaintPublishingScene = 0;
    CjguiOwnerTraceAppend(CJGUI_OWNER_TRACE_PHASE_END, session, presentTurn,
        candidateSession.stagedComposableSceneVersion, 0, candidateSession.sessionGeneration,
        CJGUI_OWNER_PHASE_NATIVE_FRAME_PRESENT, frameSpan);
    if (status != CJGUI_INTERNAL_RENDERER_OK && status != CJGUI_INTERNAL_RENDERER_READBACK_FAILED)
        CjguiCandidateFailure(candidateSession, status, hostPrepared ? "present_frame" : "present_host_background",
            status, CJGUI_INTERNAL_RENDERER_OK);
    BOOL accepted = status == CJGUI_INTERNAL_RENDERER_OK || status == CJGUI_INTERNAL_RENDERER_READBACK_FAILED;
    if (accepted) {
        CJGuiInternalSession *ctx = CjguiLookupSession(session);
        if (ctx && !ctx.destroyed) {
            if (sceneTransfer) {
                CjguiMovePreparedSelectionTransfer(ctx,sceneTransfer,sceneTransfer.preparedOverlay);
                CJGuiInternalComposableSceneNode *target=nil;
                // swap leaves A's index in prepared; locate B by its frozen ID.
                for (CJGuiInternalComposableSceneNode *node in ctx.composableNodes) {
                    if (node.node.nodeId==sceneTransfer.bNodeId) { target=node; break; }
                }
                CjguiPublishSelectionTransferReceipt(ctx,sceneTransfer,target);
                ctx.selectionPaintTransferId=0;
                ctx.selectionPaintOwnerRevision=sceneTransfer.ownerSelectionRevision;
                ctx.selectionReceiptOwnerRevision=sceneTransfer.ownerSelectionRevision;
                ctx.candidateSelectionReceipt=sceneTransfer.candidateReceipt;
                CjguiSelectionTransferCell *cell=&gCjguiSelectionTransferCells[session-1];
                CjguiLockSelectionTransferCell(cell);
                cell->installedProof=YES;
                cell->candidateSceneReceipt=sceneTransfer.candidateReceipt;
                atomic_store_explicit(&cell->decision,CJGUI_SELECTION_TRANSFER_COMMITTED,memory_order_release);
                CjguiUnlockSelectionTransferCell(cell);
                CJGuiInternalComposableSceneOverlay *o=ctx.composableSceneOverlay;
                o.installedSourceSelectionGeometryTransferId=sceneTransfer.transferId;
                // These immutable candidate nodes/layouts were just encoded
                // and submitted. Associate that frame with its now actual B
                // receipt, never with A's still-live receipt during encoding.
                CjguiTraceSelectionDrawEncodedIfMatching(ctx,ctx.view,ctx.view.frameIndex);
                CjguiTraceAcceptedTextSurfaceEncoded(ctx,ctx.view,ctx.view.frameIndex);
                if (sceneTransfer.sourceGestureEpoch && o.pointerCaptureActive &&
                    o.pointerCaptureGestureEpoch==sceneTransfer.sourceGestureEpoch) {
                    o.pointerCaptureNodeId=sceneTransfer.bNodeId; o.pointerCaptureResourceId=sceneTransfer.bResourceId;
                    o.pointerCaptureNodeKind=sceneTransfer.bNodeKind; o.pointerCaptureHasContinued=YES;
                    o.pointerCaptureContinuation=nil;
                    o.dragEdgeScrollNodeId=sceneTransfer.bNodeId; o.dragEdgeScrollResourceId=sceneTransfer.bResourceId;
                    o.dragEdgeScrollNodeKind=sceneTransfer.bNodeKind;
                }
            }
            // Only a successfully submitted coherent candidate retires the
            // obligation. Rejection/pending keeps both the fence and old frame.
            ctx.selectionPaintTransferId = 0;
            ctx.selectionPaintStagedScene = 0;
            uint64_t inputSpan = CjguiOwnerTraceAppend(CJGUI_OWNER_TRACE_PHASE_BEGIN, session,
                presentTurn, ctx.composableSceneVersion, 0, ctx.sessionGeneration,
                CJGUI_OWNER_PHASE_NATIVE_INPUT_PUBLICATION, 0);
            CjguiCandidateCaretProjection *caret=ctx.stagedCaretProjection;
            if (caret) {
                NSRect local=caret.rect;
                ctx.composableSceneOverlay.hasDeclaredInputCaret=caret.present;
                ctx.composableSceneOverlay.declaredInputCaretNodeId=caret.nodeId;
                ctx.composableSceneOverlay.declaredInputCaretRect=local;
            }
            [ctx.composableSceneOverlay setNodesFromProjection:ctx.view.composableNodes];
            if (sceneTransfer.sourceGestureEpoch && ctx.composableSceneOverlay.pointerCaptureActive &&
                ctx.composableSceneOverlay.pointerCaptureGestureEpoch==sceneTransfer.sourceGestureEpoch) {
                CJGuiInternalComposableSceneNode *focus=[ctx.composableSceneOverlay capturedPointerNode];
                if (focus) [ctx.composableSceneOverlay armDragEdgeScrollForNode:focus
                    atPoint:NSMakePoint(ctx.composableSceneOverlay.pointerCaptureX,ctx.composableSceneOverlay.pointerCaptureY)
                    source:CJGUI_DRAG_EDGE_SOURCE_POINTER_CAPTURE];
            }
            if (ctx.diagnosticOverlay && !ctx.diagnosticOverlay.hidden)
                [ctx.diagnosticOverlay setNeedsDisplay:YES];
            ctx.windowBackgroundAcceptedSceneVersion = ctx.composableSceneVersion;
            ctx.windowBackgroundRequestedMode = candidateMode;
            ctx.windowBackgroundColorScheme = candidateColorScheme;
            ctx.windowBackgroundRequestRevision = ctx.stagedWindowBackgroundRequestRevision;
            ctx.windowBackgroundActualMode = candidateActualMode;
            ctx.windowBackgroundFallbackReason = candidateFallbackReason;
            ctx.windowBackgroundCompletion = 0;
            ctx.windowBackgroundSubmittedFrameIndex = ctx.view.frameIndex;
            ctx.windowBackgroundSubmittedRequestRevision = ctx.windowBackgroundRequestRevision;
            ctx.hasStagedWindowBackground = NO;
            ctx.windowBackgroundObservationRevision += 1;
            CjguiPublishWindowBackgroundSnapshot(ctx);
            CjguiOwnerTraceAppend(CJGUI_OWNER_TRACE_PHASE_END, session, presentTurn,
                ctx.composableSceneVersion, 0, ctx.sessionGeneration,
                CJGUI_OWNER_PHASE_NATIVE_INPUT_PUBLICATION, inputSpan);
        }
    }
    if (!accepted && sceneTransfer && selectionCommitRight) {
        CjguiSelectionTransferCell *cell=&gCjguiSelectionTransferCells[session-1];
        CjguiLockSelectionTransferCell(cell); cell->restoredProof=YES;
        atomic_store_explicit(&cell->decision,CJGUI_SELECTION_TRANSFER_ABORTED,memory_order_release);
        CjguiUnlockSelectionTransferCell(cell);
    }
    // A missing drawable/encoder means there was no usable replacement
    // frame. Restore the old native input and overlay snapshot before the
    // caller retries; otherwise Cangjie would honestly retain the old scene
    // while AppKit had already started dispatching the staged one.
    if (status != CJGUI_INTERNAL_RENDERER_OK && status != CJGUI_INTERNAL_RENDERER_READBACK_FAILED) {
        CJGuiInternalSession *ctx = CjguiLookupSession(session);
        if (ctx && !ctx.destroyed) {
            uint32_t restoredActual = 0;
            uint32_t restoredReason = 0;
            (void)CjguiApplyWindowBackground(ctx, previousBackgroundRequestedMode,
                                             previousBackgroundColorScheme,
                                             &restoredActual, &restoredReason);
            ctx.windowBackgroundAcceptedSceneVersion = previousBackgroundSceneVersion;
            ctx.windowBackgroundRequestedMode = previousBackgroundRequestedMode;
            ctx.windowBackgroundColorScheme = previousBackgroundColorScheme;
            ctx.windowBackgroundActualMode = restoredActual;
            ctx.windowBackgroundFallbackReason = restoredReason;
            ctx.windowBackgroundCompletion = previousBackgroundCompletion;
            ctx.windowBackgroundSubmittedFrameIndex = previousBackgroundSubmittedFrameIndex;
            ctx.windowBackgroundSubmittedRequestRevision = previousBackgroundSubmittedRequestRevision;
            ctx.windowBackgroundObservationRevision += 1;
            CjguiPublishWindowBackgroundSnapshot(ctx);
            ctx.composableSceneVersion = previousSceneVersion;
            ctx.composableNodes = [previousNodes mutableCopy] ?: [NSMutableArray array];
            ctx.composableDataTransferItems = [previousDataTransferItems mutableCopy] ?: [NSMutableArray array];
            ctx.composableDataTransferVersion = previousDataTransferVersion;
            ctx.composableCommandMenuItems = [previousCommandMenuItems mutableCopy] ?: [NSMutableArray array];
            ctx.composableCommandMenuVersion = previousCommandMenuVersion;
            ctx.view.composableNodes = [ctx.composableNodes copy];
            // AppKit input and AX never observed the rejected candidate. Their
            // accepted graph and focus are already the correct old snapshot.
            if (ctx.window == NSApp.keyWindow) CjguiRebuildComposableCommandMenuForKeyWindow();
            // Commit happened before the Metal presentation verdict. Restore
            // the prior committed subscriber set together with the old scene;
            // a rejected replacement must never receive a completion epoch.
            CjguiReconcileCommittedComposableImageSubscribers(ctx);
            // The committed scene was rolled back to the previous one, so the
            // staged candidate's derived text holds are now candidate-unique
            // the same way a commit rejection leaves them. Release them here
            // too; the shared-texture safety property is identical.
            CjguiReleaseFailedCandidateTextResources(ctx);
            CjguiReleaseFailedCandidateEffectTargets(ctx);
        }
    }
    return status;
}

CjguiInternalRendererStatus cjgui_internal_renderer_candidate_selection_receipt(uint64_t session,
    uint64_t sceneVersion, uint64_t transferId, CjguiInternalSelectionTransferReceipt *outReceipt) {
    if (!outReceipt) return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    *outReceipt=(CjguiInternalSelectionTransferReceipt){0};
    if (!session || session>kCjguiSessionCapacity || !transferId) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    CjguiSelectionTransferCell *cell=&gCjguiSelectionTransferCells[session-1];
    CjguiLockSelectionTransferCell(cell);
    BOOL matches=CjguiSelectionTransferCellMatchesLocked(cell,session,transferId) && cell->installedProof &&
        CjguiSelectionTransferStateOf(atomic_load_explicit(&cell->decision,memory_order_acquire))==CJGUI_SELECTION_TRANSFER_COMMITTED &&
        cell->candidateSceneReceipt.transferId==transferId && cell->candidateSceneReceipt.sceneVersion==sceneVersion;
    if (matches) *outReceipt=cell->candidateSceneReceipt;
    CjguiUnlockSelectionTransferCell(cell);
    return matches ? CJGUI_INTERNAL_RENDERER_OK : CJGUI_INTERNAL_RENDERER_SCENE_STALE;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_present_composable_scene(uint64_t session,
                                                  CjguiInternalRendererFrameObservation *outObservation) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block uint64_t traceGeneration = UINT64_MAX;
        uint64_t turn = atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn, memory_order_acquire);
        uint64_t dispatch = cjgui_internal_renderer_owner_trace_dispatch_begin(session, turn,
            0, UINT64_MAX, CJGUI_OWNER_PHASE_REFRESH_PROJECTION, 0);
        uint64_t dispatchStarted = cjgui_internal_renderer_owner_trace_ns();
        dispatch_sync(dispatch_get_main_queue(), ^{
            CJGuiInternalSession *traceSession = CjguiLookupSession(session);
            traceGeneration = traceSession ? traceSession.sessionGeneration : UINT64_MAX;
            cjgui_internal_renderer_owner_trace_dispatch_event(CJGUI_OWNER_TRACE_MAIN_ENTER,
                session, turn, dispatch, dispatch, traceGeneration, CJGUI_OWNER_PHASE_REFRESH_PROJECTION, 0);
            uint64_t mainStarted = cjgui_internal_renderer_owner_trace_ns();
            status = CjguiPresentComposableSceneOnMain(session, outObservation);
            CjguiTraceOwnerPhase(session, "present_composable_scene.main", mainStarted);
            cjgui_internal_renderer_owner_trace_dispatch_event(CJGUI_OWNER_TRACE_MAIN_EXIT,
                session, turn, dispatch, dispatch, traceGeneration, CJGUI_OWNER_PHASE_REFRESH_PROJECTION, 0);
        });
        CjguiTraceOwnerPhase(session, "present_composable_scene.dispatch_sync", dispatchStarted);
        cjgui_internal_renderer_owner_trace_dispatch_event(CJGUI_OWNER_TRACE_OWNER_RETURN,
            session, turn, dispatch, dispatch, traceGeneration, CJGUI_OWNER_PHASE_REFRESH_PROJECTION, 0);
        return status;
    }
    uint64_t mainStarted = cjgui_internal_renderer_owner_trace_ns();
    CjguiInternalRendererStatus status = CjguiPresentComposableSceneOnMain(session, outObservation);
    CjguiTraceOwnerPhase(session, "present_composable_scene.main", mainStarted);
    return status;
}

static CjguiInternalRendererStatus CjguiPrepareComposableImageResourceAbiOnMain(
    uint64_t sessionToken, const char *resourcePath, const char *resourceId,
    uint64_t resourceVersion, uint32_t *outState) {
    if (!outState) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    *outState = CjguiComposableImageResourceUnrequested;
    CJGuiInternalSession *session = CjguiLookupSession(sessionToken);
    if (!session || session.destroyed || !session.view) {
        return session ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
    NSString *path = resourcePath ? [NSString stringWithUTF8String:resourcePath] : @"";
    NSString *identifier = resourceId ? [NSString stringWithUTF8String:resourceId] : @"";
    if (!path || !identifier) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    *outState = CjguiPrepareComposableImageResourceOnMain(session, sessionToken, path, identifier,
                                                           resourceVersion, nil, YES, YES, NULL);
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_prepare_composable_image_resource(
    uint64_t session, const char *resourcePath, const char *resourceId,
    uint64_t resourceVersion, uint32_t *outState) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = CjguiPrepareComposableImageResourceAbiOnMain(session, resourcePath, resourceId,
                                                                    resourceVersion, outState);
        });
        return status;
    }
    return CjguiPrepareComposableImageResourceAbiOnMain(session, resourcePath, resourceId, resourceVersion, outState);
}

static CjguiInternalRendererStatus CjguiComposableImageResourceStateOnMain(
    uint64_t sessionToken, const char *resourcePath, const char *resourceId,
    uint64_t resourceVersion, uint32_t *outState) {
    if (!outState) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    *outState = CjguiComposableImageResourceUnrequested;
    CJGuiInternalSession *session = CjguiLookupSession(sessionToken);
    if (!session || session.destroyed || !session.view) {
        return session ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
    NSString *path = resourcePath ? [NSString stringWithUTF8String:resourcePath] : @"";
    NSString *identifier = resourceId ? [NSString stringWithUTF8String:resourceId] : @"";
    NSString *cacheKey = CjguiComposableImageCacheKey(path, identifier, resourceVersion, NULL);
    if (!path || !identifier || !cacheKey) {
        *outState = CjguiComposableImageResourceFailed;
        return CJGUI_INTERNAL_RENDERER_OK;
    }
    CJGuiInternalComposableImageResourceDomain *domain = CjguiComposableImageDomainForSession(session);
    if (!domain) return CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED;
    if (domain.textureCache[cacheKey]) {
        CJGuiInternalComposableImageResource *resource = domain.resources[cacheKey];
        if (resource) resource.lastAccess = CjguiComposableImageNextAccess(domain);
        *outState = CjguiComposableImageResourceReady;
        return CJGUI_INTERNAL_RENDERER_OK;
    }
    if (CjguiComposableImageDomainBoundTexture(domain, cacheKey)) {
        CJGuiInternalComposableImageResource *resource = domain.resources[cacheKey];
        if (resource) resource.lastAccess = CjguiComposableImageNextAccess(domain);
        *outState = CjguiComposableImageResourceReady;
        return CJGUI_INTERNAL_RENDERER_OK;
    }
    CJGuiInternalComposableImageResource *resource = domain.resources[cacheKey];
    if (resource) {
        resource.lastAccess = CjguiComposableImageNextAccess(domain);
        *outState = resource.state;
    }
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_composable_image_resource_state(
    uint64_t session, const char *resourcePath, const char *resourceId,
