cjgui_internal_renderer_test_composable_image_pipeline_stats(
    uint64_t session, uint64_t *outPathResolveMicros, uint64_t *outCacheHitCount,
    uint64_t *outAsyncLaunchCount, uint64_t *outAsyncTotalMicros,
