CjguiInternalRendererStatus
cjgui_internal_renderer_test_composable_multiline_proxy_opacity(uint64_t session,
                                                                 float *outScrollAlpha,
                                                                 float *outTextAlpha) {
    if (!outScrollAlpha || !outTextAlpha) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    *outScrollAlpha = 0.0f; *outTextAlpha = 0.0f;
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = cjgui_internal_renderer_test_composable_multiline_proxy_opacity(session, outScrollAlpha, outTextAlpha);
        });
        return status;
    }
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.composableSceneOverlay) return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    CJGuiInternalComposableSceneNode *active = nil;
    for (CJGuiInternalComposableSceneNode *node in ctx.composableNodes) {
        if (node.node.nodeId == overlay.activeNodeId && node.index == overlay.activeNodeIndex &&
            node.node.resourceId == overlay.activeNodeResourceId && node.node.nodeKind == overlay.activeNodeKind &&
            node.node.projectionVersion == overlay.activeProjectionVersion) {
            active = node; break;
        }
    }
    if (!active || active.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    *outScrollAlpha = overlay.inputScrollProxy.alphaValue;
    *outTextAlpha = overlay.inputProxy.alphaValue;
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_test_scroll_composable_multiline(uint64_t session,
                                                          float deltaY,
                                                          float *outScrollOffset,
                                                          uint32_t *outVisibleGlyphCount) {
    if (!outScrollOffset || !outVisibleGlyphCount) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    *outScrollOffset = 0.0f; *outVisibleGlyphCount = 0;
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = cjgui_internal_renderer_test_scroll_composable_multiline(
                session, deltaY, outScrollOffset, outVisibleGlyphCount);
        });
        return status;
    }
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.composableSceneOverlay) return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    CJGuiInternalComposableSceneNode *active = nil;
    for (CJGuiInternalComposableSceneNode *node in ctx.composableNodes) {
        if (node.node.nodeId == overlay.activeNodeId && node.index == overlay.activeNodeIndex &&
            node.node.resourceId == overlay.activeNodeResourceId && node.node.nodeKind == overlay.activeNodeKind &&
            node.node.projectionVersion == overlay.activeProjectionVersion) {
            active = node; break;
        }
    }
    if (!active || active.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    [overlay scrollActiveMultiline:active deltaY:deltaY];
    [overlay positionInputProxyForNode:active];
    NSLayoutManager *layoutManager = overlay.inputProxy.layoutManager;
    NSTextContainer *container = overlay.inputProxy.textContainer;
    NSRect contentRect = NSInsetRect(CjguiComposableRect(active, overlay), 7.0, 6.0);
    NSRect visibleRect = NSMakeRect(0.0, overlay.multilineScrollOffset, NSWidth(contentRect), NSHeight(contentRect));
    [overlay ensureActiveLayoutForBoundingRect:visibleRect container:container layoutManager:layoutManager];
    NSRange visible = [layoutManager glyphRangeForBoundingRectWithoutAdditionalLayout:visibleRect inTextContainer:container];
    *outScrollOffset = (float)overlay.multilineScrollOffset;
    *outVisibleGlyphCount = visible.location == NSNotFound ? 0u : (uint32_t)MIN(UINT32_MAX, visible.length);
    return *outVisibleGlyphCount > 0 ? CJGUI_INTERNAL_RENDERER_OK : CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_test_composable_multiline_viewport(uint64_t session, const char *marker,
                                                            float *outScrollOffset, float *outMaximumOffset,
                                                            uint32_t *outVisibleCharacterStart,
                                                            uint32_t *outVisibleCharacterLength,
                                                            uint64_t *outProjectionVersion,
                                                            int *outMarkerFullyVisible) {
    if (!marker || !outScrollOffset || !outMaximumOffset || !outVisibleCharacterStart ||
        !outVisibleCharacterLength || !outProjectionVersion || !outMarkerFullyVisible)
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    *outScrollOffset = 0.0f; *outMaximumOffset = -1.0f;
    *outVisibleCharacterStart = 0; *outVisibleCharacterLength = 0;
    *outProjectionVersion = 0; *outMarkerFullyVisible = 0;
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = cjgui_internal_renderer_test_composable_multiline_viewport(
                session, marker, outScrollOffset, outMaximumOffset, outVisibleCharacterStart,
                outVisibleCharacterLength, outProjectionVersion, outMarkerFullyVisible);
        });
        return status;
    }
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.composableSceneOverlay)
        return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    CJGuiInternalComposableSceneNode *active = nil;
    for (CJGuiInternalComposableSceneNode *node in ctx.composableNodes) {
        if (node.node.nodeId == overlay.activeNodeId && node.index == overlay.activeNodeIndex &&
            node.node.resourceId == overlay.activeNodeResourceId && node.node.nodeKind == overlay.activeNodeKind &&
            node.node.projectionVersion == overlay.activeProjectionVersion) {
            active = node; break;
        }
    }
    if (!active || active.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT)
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    [overlay positionInputProxyForNode:active];
    NSLayoutManager *layoutManager = overlay.inputProxy.layoutManager;
    NSTextContainer *container = overlay.inputProxy.textContainer;
    NSRect contentRect = NSInsetRect(CjguiComposableRect(active, overlay), 7.0, 6.0);
    NSRect visibleRect = NSMakeRect(0.0, overlay.multilineScrollOffset,
                                    NSWidth(contentRect), NSHeight(contentRect));
    [overlay ensureActiveLayoutForBoundingRect:visibleRect container:container layoutManager:layoutManager];
    NSRange glyphs = [layoutManager glyphRangeForBoundingRectWithoutAdditionalLayout:visibleRect
                                                                     inTextContainer:container];
    NSRange chars = glyphs.location == NSNotFound || glyphs.length == 0
        ? NSMakeRange(NSNotFound, 0)
        : [layoutManager characterRangeForGlyphRange:glyphs actualGlyphRange:NULL];
    *outScrollOffset = (float)overlay.multilineScrollOffset;
    if (overlay.activeTextHasExactContentHeight)
        *outMaximumOffset = (float)MAX(0.0, overlay.activeTextKnownContentHeight - NSHeight(contentRect));
    *outProjectionVersion = active.node.projectionVersion;
    if (chars.location != NSNotFound) {
        *outVisibleCharacterStart = (uint32_t)MIN(UINT32_MAX, chars.location);
        *outVisibleCharacterLength = (uint32_t)MIN(UINT32_MAX, chars.length);
        NSString *text = overlay.inputProxy.string ?: @"";
        NSString *needle = [NSString stringWithUTF8String:marker];
        NSRange match = needle.length > 0 ? [text rangeOfString:needle] : NSMakeRange(NSNotFound, 0);
        *outMarkerFullyVisible = match.location != NSNotFound &&
            chars.location <= match.location && NSMaxRange(chars) >= NSMaxRange(match);
    }
    return chars.location == NSNotFound ? CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR : CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_test_is_main_thread(int *outIsMainThread, int *outDispatchEnabled) {
    if (outIsMainThread) *outIsMainThread = CjguiIsMainThread() ? 1 : 0;
    if (outDispatchEnabled) *outDispatchEnabled = gCjguiMainThreadDispatchEnabled ? 1 : 0;
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_test_enqueue_composable_event(uint64_t session, uint32_t nodeIndex, uint32_t eventKind, const char *text) {
    __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    CjguiTestHookOnMainThread(^{
        CJGuiInternalSession *ctx = CjguiLookupSession(session);
        if (!ctx || nodeIndex >= ctx.composableNodes.count) {
            status = ctx ? CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
            return;
        }
        // Test-only injection retains the SAME captured accepted identity and
        // geometry as rightMouseDown. It proves lifecycle refusal, not CGEvent
        // delivery; normal consumer acceptance drives the real right button.
        if (eventKind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_CONTEXT_MENU_REQUEST) {
            if (!ctx.composableSceneOverlay || nodeIndex >= ctx.composableSceneOverlay.nodes.count) return;
            CJGuiInternalComposableSceneNode *node = ctx.composableSceneOverlay.nodes[nodeIndex];
            NSRect visual = CjguiComposableVisualNodeRect(node);
            status = CjguiEnqueueComposableCapturedPointerInteraction(ctx, eventKind, node,
                NSMakePoint(NSMidX(visual), NSMidY(visual)), 0)
                ? CJGUI_INTERNAL_RENDERER_OK : CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
            return;
        }
        if (eventKind < CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_ACTIVATE || eventKind > CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_PRESS_CANCEL) {
            status = CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
            return;
        }
        status = CjguiEnqueueComposableInteraction(ctx, eventKind, nodeIndex,
                                                   text ? [NSString stringWithUTF8String:text] : @"", NSMakeRange(0, 0))
            ? CJGUI_INTERNAL_RENDERER_OK : CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    });
    return status;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_test_arm_midwork_composable_event(uint64_t sourceSession,
                                                           uint64_t targetSession,
                                                           uint32_t targetNodeIndex,
                                                           uint32_t eventKind,
                                                           const char *text,
                                                           uint32_t delayMicros) {
    __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    CjguiTestHookOnMainThread(^{
        CJGuiInternalSession *source = CjguiLookupSession(sourceSession);
        CJGuiInternalSession *target = CjguiLookupSession(targetSession);
        if (!source || !target || !source.composableSceneOverlay ||
            targetNodeIndex >= target.composableNodes.count ||
            eventKind != CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_CHANGED ||
            delayMicros > 50000 || !text) return;
        NSString *payload = [NSString stringWithUTF8String:text];
        if (!payload) return;
        source.testMidworkEpoch += 1;
        source.testMidworkArmed = YES;
        source.testMidworkTargetSession = targetSession;
        source.testMidworkTargetIndex = targetNodeIndex;
        source.testMidworkEventKind = eventKind;
        source.testMidworkText = payload;
        source.testMidworkDelayMicros = delayMicros;
        source.testMidworkAStartMicros = 0;
        source.testMidworkAEndMicros = 0;
        source.testMidworkProducerReadyMicros = 0;
        source.testMidworkProducerPostMicros = 0;
        source.testMidworkNativeEnqueueMicros = 0;
        source.testMidworkEnqueueStatus = CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        status = CJGUI_INTERNAL_RENDERER_OK;
    });
    return status;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_test_release_midwork_composable_event(uint64_t sourceSession) {
    __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    CjguiTestHookOnMainThread(^{
        CJGuiInternalSession *source = CjguiLookupSession(sourceSession);
        if (!source || !source.testMidworkArmed) return;
        source.testMidworkArmed = NO;
        uint64_t epoch = source.testMidworkEpoch;
        uint64_t targetToken = source.testMidworkTargetSession;
        uint32_t targetIndex = source.testMidworkTargetIndex;
        uint32_t eventKind = source.testMidworkEventKind;
        NSString *payload = [source.testMidworkText copy] ?: @"";
        uint32_t delayMicros = source.testMidworkDelayMicros;
        source.testMidworkProducerReadyMicros = CjguiMonotonicMicros();
        dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)delayMicros * NSEC_PER_USEC),
                       dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
            uint64_t posted = CjguiMonotonicMicros();
            dispatch_async(dispatch_get_main_queue(), ^{
                CJGuiInternalSession *liveSource = CjguiLookupSession(sourceSession);
                if (!liveSource || liveSource.testMidworkEpoch != epoch) return;
                liveSource.testMidworkProducerPostMicros = posted;
                CJGuiInternalSession *target = CjguiLookupSession(targetToken);
                liveSource.testMidworkEnqueueStatus = target &&
                    CjguiEnqueueComposableInteraction(target, eventKind, targetIndex,
                                                      payload, NSMakeRange(0, 0))
                    ? CJGUI_INTERNAL_RENDERER_OK : CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
                liveSource.testMidworkNativeEnqueueMicros = CjguiMonotonicMicros();
            });
        });
        status = CJGUI_INTERNAL_RENDERER_OK;
    });
    return status;
}

CjguiInternalRendererStatus cjgui_internal_renderer_test_arm_submit_gate(
    uint64_t sourceSession, uint32_t holdMicros) {
    __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    CjguiTestHookOnMainThread(^{
        CJGuiInternalSession *source = CjguiLookupSession(sourceSession);
        if (!source || holdMicros < 1000 || holdMicros > 50000) return;
        source.testSubmitGateArmed = YES;
        source.testSubmitGateHoldMicros = holdMicros;
        status = CJGUI_INTERNAL_RENDERER_OK;
    });
    return status;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_test_midwork_composable_event_timing(uint64_t sourceSession,
                                                              uint64_t *outAStartMicros,
                                                              uint64_t *outAEndMicros,
                                                              uint64_t *outProducerReadyMicros,
                                                              uint64_t *outProducerPostMicros,
                                                              uint64_t *outNativeEnqueueMicros,
                                                              int32_t *outEnqueueStatus) {
    if (!outAStartMicros || !outAEndMicros || !outProducerReadyMicros ||
        !outProducerPostMicros || !outNativeEnqueueMicros || !outEnqueueStatus)
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    CjguiTestHookOnMainThread(^{
        CJGuiInternalSession *source = CjguiLookupSession(sourceSession);
        if (!source) return;
        *outAStartMicros = source.testMidworkAStartMicros;
        *outAEndMicros = source.testMidworkAEndMicros;
        *outProducerReadyMicros = source.testMidworkProducerReadyMicros;
        *outProducerPostMicros = source.testMidworkProducerPostMicros;
        *outNativeEnqueueMicros = source.testMidworkNativeEnqueueMicros;
        *outEnqueueStatus = source.testMidworkEnqueueStatus;
        status = CJGUI_INTERNAL_RENDERER_OK;
    });
    return status;
}

