CjguiInternalRendererStatus
cjgui_internal_renderer_test_send_composable_pointer(uint64_t session, uint32_t phase, float pointX, float pointY) {
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.composableSceneOverlay) {
        return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
    if (!isfinite(pointX) || !isfinite(pointY)) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    NSPoint point = NSMakePoint(pointX, pointY);
    if (phase == 1) {
        CJGuiInternalComposableSceneNode *node = [overlay nodeAtPoint:point];
        return node && [overlay beginPointerCaptureForNode:node atPoint:point]
            ? CJGUI_INTERNAL_RENDERER_OK : CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    if (phase == 2) {
        return [overlay updatePointerCaptureAtPoint:point]
            ? CJGUI_INTERNAL_RENDERER_OK : CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    if (phase == 3 || phase == 4) {
        if (!overlay.pointerCaptureActive) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        if (phase == 4) [overlay tracePointerCaptureCancellation:@"test_pointer_cancel"];
        [overlay endPointerCaptureAtPoint:point cancelled:phase == 4];
        return CJGUI_INTERNAL_RENDERER_OK;
    }
    return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
}

// Test-only: simulates the modifier state a real pointer event would carry
// (`mouseDown:`/`mouseUp:` set exactly this field from NSEvent.modifierFlags).
// It lets a probe drive the production pointer activation path through
// CjguiStampPointerModifiersOnQueuedInteraction without posting a synthetic
// AppKit event, so the native -> queue -> FFI -> window -> controller payload
// can be asserted directly.
void cjgui_internal_renderer_test_set_pointer_modifiers(uint64_t session, int64_t modifierFlags) {
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx) return;
    ctx.pointerModifierFlags = modifierFlags;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_test_activate_composable_point(uint64_t session, float pointX, float pointY) {
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.composableSceneOverlay) {
        return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
    if (!isfinite(pointX) || !isfinite(pointY)) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    CJGuiInternalComposableSceneNode *node = [overlay nodeAtPoint:NSMakePoint(pointX, pointY)];
    if (!node) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    NSPoint point = NSMakePoint(pointX, pointY);
    // This testing seam exercises the production physical press/release
    // contract rather than preserving the retired immediate-on-down action.
    [overlay mouseDownAtPoint:point];
    [overlay completePressAtPoint:point];
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus cjgui_internal_renderer_test_actual_activation_pair(
    uint64_t session, uint64_t nodeId) {
    if (!CjguiIsMainThread()) {
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        CjguiTestHookOnMainThread(^{ status = cjgui_internal_renderer_test_actual_activation_pair(session, nodeId); });
        return status;
    }
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || ctx.destroyed || !ctx.composableSceneOverlay) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    CJGuiInternalComposableSceneNode *node = nil;
    for (CJGuiInternalComposableSceneNode *value in ctx.composableNodes)
        if (value.node.nodeId == nodeId) { node = value; break; }
    if (!node) return CJGUI_INTERNAL_RENDERER_NODE_NOT_FOUND;
    NSUInteger first = ctx.pendingInteractions.count;
    // Exact producer used by accessibilityPerformPress; no events or prefix
    // members are constructed by this test seam.
    [ctx.composableSceneOverlay accessibilityPerformPressForNode:node];
    BOOL pair = ctx.pendingInteractions.count == first + 2 &&
        ctx.pendingInteractions[first].activationPrefix.ordinal == 1 &&
        ctx.pendingInteractions[first + 1].activationPrefix.ordinal == 2;
    if (pair) {
        ctx.testActivationPairSecond = ctx.pendingInteractions[first + 1];
        ctx.testActivationPairFrozenPrefix = ctx.testActivationPairSecond.activationPrefix;
        ctx.testActivationPairReleased = NO;
        ctx.testActivationPairHoldHits = 0;
        ctx.testActivationPairSecondDequeues = 0;
        ctx.testActivationPairRefreshDecision = 0;
    }
    fprintf(stderr, "ACTUAL_PAIR_CONTROL phase=producer tid=%llu mono_ns=%llu first=%lu count=%lu pair=%d generation=%llu nonce=%llu origin=%llu\n",
        (unsigned long long)CjguiCurrentNativeThreadId(), (unsigned long long)CjguiOwnerTraceNanoseconds(),
        (unsigned long)first, (unsigned long)ctx.pendingInteractions.count, pair,
        (unsigned long long)ctx.sessionGeneration,
        (unsigned long long)ctx.testActivationPairFrozenPrefix.nonce,
        (unsigned long long)ctx.testActivationPairFrozenPrefix.sceneVersion);
    return pair ? CJGUI_INTERNAL_RENDERER_OK : CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
}

static BOOL CjguiTestActualPairSecondAtHead(CJGuiInternalSession *ctx) {
    if (!ctx || !ctx.testActivationPairSecond ||
        ctx.pendingInteractions.firstObject != ctx.testActivationPairSecond) return NO;
    CjguiInternalActivationPrefix actual = ctx.testActivationPairSecond.activationPrefix;
    CjguiInternalActivationPrefix frozen = ctx.testActivationPairFrozenPrefix;
    return actual.ordinal == 2 && actual.sessionGeneration == ctx.sessionGeneration &&
        actual.sessionGeneration == frozen.sessionGeneration && actual.nonce == frozen.nonce &&
        actual.sceneVersion == frozen.sceneVersion && actual.nodeId == frozen.nodeId &&
        actual.resourceId == frozen.resourceId && actual.nodeKind == frozen.nodeKind &&
        actual.bindingEpoch == frozen.bindingEpoch && actual.secondKind == frozen.secondKind;
}

void cjgui_internal_renderer_test_actual_pair_owner_marker(uint64_t session, uint64_t kind,
    uint64_t revision, uint64_t scene, uint64_t node) {
    fprintf(stderr, "ACTUAL_PAIR_CONTROL phase=cj_callback session=%llu kind=%llu revision=%llu scene=%llu node=%llu turn=%llu owner_tid=%llu mono_ns=%llu\n",
        (unsigned long long)session, (unsigned long long)kind, (unsigned long long)revision,
        (unsigned long long)scene, (unsigned long long)node,
        (unsigned long long)atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn, memory_order_acquire),
        (unsigned long long)CjguiCurrentNativeThreadId(),
        (unsigned long long)CjguiOwnerTraceNanoseconds());
}

// Test-only observation is called from instrumented copies of the real Cj
// window. It records an admitted refresh or an explicit actual-prefix hold;
// a budget yield and a pending present are never labelled a refresh decision.
void cjgui_internal_renderer_test_actual_pair_refresh_decision(uint64_t session, uint64_t decision) {
    uint64_t ownerThread = CjguiCurrentNativeThreadId();
    uint64_t ownerTurn = atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn, memory_order_acquire);
    CjguiTestHookOnMainThread(^{
        CJGuiInternalSession *ctx = CjguiLookupSession(session);
        if (!CjguiTestActualPairSecondAtHead(ctx) || ctx.testActivationPairReleased ||
            (decision != 1 && decision != 2)) return;
        ctx.testActivationPairRefreshDecision = decision;
        fprintf(stderr, "ACTUAL_PAIR_CONTROL phase=refresh_decision decision=%llu generation=%llu nonce=%llu scene=%llu turn=%llu owner_tid=%llu main_tid=%llu mono_ns=%llu\n",
            (unsigned long long)decision, (unsigned long long)ctx.sessionGeneration,
            (unsigned long long)ctx.testActivationPairFrozenPrefix.nonce,
            (unsigned long long)ctx.composableSceneVersion, (unsigned long long)ownerTurn,
            (unsigned long long)ownerThread, (unsigned long long)CjguiCurrentNativeThreadId(),
            (unsigned long long)CjguiOwnerTraceNanoseconds());
    });
}

CjguiInternalRendererStatus cjgui_internal_renderer_test_actual_pair_snapshot(
    uint64_t session, uint64_t *values, uint32_t count) {
    if (!values || count != 8) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    memset(values, 0, sizeof(uint64_t) * count);
    __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    CjguiTestHookOnMainThread(^{
        CJGuiInternalSession *ctx = CjguiLookupSession(session);
        if (!ctx || ctx.destroyed) return;
        values[0] = ctx.sessionGeneration;
        values[1] = ctx.testActivationPairFrozenPrefix.nonce;
        values[2] = ctx.testActivationPairFrozenPrefix.sceneVersion;
        values[3] = ctx.composableSceneVersion;
        values[4] = ctx.testActivationPairHoldHits;
        values[5] = ctx.testActivationPairSecondDequeues;
        values[6] = ctx.testActivationPairRefreshDecision;
        values[7] = CjguiTestActualPairSecondAtHead(ctx) ? 1 : 0;
        status = CJGUI_INTERNAL_RENDERER_OK;
    });
    return status;
}

CjguiInternalRendererStatus cjgui_internal_renderer_test_actual_pair_release(
    uint64_t session, uint64_t generation, uint64_t nonce) {
    __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_SCENE_STALE;
    CjguiTestHookOnMainThread(^{
        CJGuiInternalSession *ctx = CjguiLookupSession(session);
        if (!CjguiTestActualPairSecondAtHead(ctx) || ctx.testActivationPairReleased ||
            ctx.sessionGeneration != generation || ctx.testActivationPairFrozenPrefix.nonce != nonce ||
            ctx.testActivationPairHoldHits == 0 || ctx.testActivationPairRefreshDecision == 0) return;
        ctx.testActivationPairReleased = YES;
        fprintf(stderr, "ACTUAL_PAIR_CONTROL phase=release generation=%llu nonce=%llu origin=%llu accepted=%llu head_original=1 tid=%llu mono_ns=%llu\n",
            (unsigned long long)generation, (unsigned long long)nonce,
            (unsigned long long)ctx.testActivationPairFrozenPrefix.sceneVersion,
            (unsigned long long)ctx.composableSceneVersion,
            (unsigned long long)CjguiCurrentNativeThreadId(),
            (unsigned long long)CjguiOwnerTraceNanoseconds());
        status = CJGUI_INTERNAL_RENDERER_OK;
    });
    return status;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_test_send_composable_mouse(uint64_t session, uint32_t phase, float pointX, float pointY) {
    __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    CjguiTestHookOnMainThread(^{
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.composableSceneOverlay) {
        status = ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
        return;
    }
    if (!isfinite(pointX) || !isfinite(pointY)) { status = CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR; return; }
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    NSPoint point = NSMakePoint(pointX, pointY);
    if (phase == 1) {
        [overlay mouseDownAtPoint:point];
        { status = CJGUI_INTERNAL_RENDERER_OK; return; }
    }
    if (phase == 2) {
        if (overlay.pointerCaptureActive) {
            { status = [overlay updatePointerCaptureAtPoint:point]
                ? CJGUI_INTERNAL_RENDERER_OK : CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR; return; }
        }
        if (overlay.pressedNodeId == 0) { status = CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR; return; }
        [overlay updateHoverAtPoint:point];
        CJGuiInternalComposableSceneNode *pressed = [overlay pressedPressableNode];
        CJGuiInternalComposableSceneNode *hit = [overlay nodeAtPoint:point];
        if (pressed && (!hit || hit.node.nodeId != pressed.node.nodeId ||
            hit.node.resourceId != pressed.node.resourceId || hit.node.nodeKind != pressed.node.nodeKind)) {
            [overlay cancelPressAtPoint:point];
        }
        { status = CJGUI_INTERNAL_RENDERER_OK; return; }
    }
    if (phase == 3) {
        if (overlay.pointerCaptureActive) {
            [overlay endPointerCaptureAtPoint:point cancelled:NO];
            { status = CJGUI_INTERNAL_RENDERER_OK; return; }
        }
        if (overlay.pressedNodeId == 0) {
            [overlay clearDraggingSelection];
            { status = CJGUI_INTERNAL_RENDERER_OK; return; }
        }
        [overlay updateHoverAtPoint:point];
        [overlay completePressAtPoint:point];
        { status = CJGUI_INTERNAL_RENDERER_OK; return; }
    }
    if (phase == 4) {
        if (overlay.pointerCaptureActive) {
            [overlay tracePointerCaptureCancellation:@"interaction_cancel"];
            [overlay endPointerCaptureAtPoint:point cancelled:YES];
            { status = CJGUI_INTERNAL_RENDERER_OK; return; }
        }
        if (overlay.pressedNodeId == 0) { status = CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR; return; }
        [overlay cancelPressAtPoint:point];
        { status = CJGUI_INTERNAL_RENDERER_OK; return; }
    }
    { status = CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR; return; }
    });
    return status;
}

