CjguiInternalRendererStatus
cjgui_internal_renderer_test_queue_composable_selection(uint64_t session, uint32_t nodeIndex,
                                                          uint32_t selectionStart,
                                                          uint32_t selectionEnd) {
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.composableSceneOverlay || nodeIndex >= ctx.composableNodes.count)
        return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    CJGuiInternalComposableSceneNode *node = ctx.composableNodes[nodeIndex];
    if (node.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT ||
        node.node.isInteractive == 0 || node.node.isReadOnly != 0)
        return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    if (overlay.activeNodeId != node.node.nodeId || overlay.activeNodeResourceId != node.node.resourceId ||
        overlay.activeNodeKind != node.node.nodeKind)
        [overlay mouseDownForNode:node];
    if (selectionEnd < selectionStart || selectionEnd > overlay.inputProxy.string.length)
        return CJGUI_INTERNAL_RENDERER_TEXT_RANGE_INVALID;
    NSRange selection = CjguiComposedSelection(overlay.inputProxy.string, selectionStart, selectionEnd);
    overlay.inputProxy.selectedRange = selection;
    if (!CjguiEnqueueComposableInteraction(ctx,
            CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_SELECTION_CHANGED,
            node.index, @"", selection))
        return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
    NSRect rect = CjguiComposableRect(node, overlay);
    CjguiStampPointerPositionOnQueuedInteraction(ctx,
        CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_SELECTION_CHANGED,
        node.index, NSMakePoint(NSMidX(rect), NSMidY(rect)));
    CjguiStampPointerModifiersOnQueuedInteraction(ctx,
        CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_SELECTION_CHANGED, node.index);
    return CJGUI_INTERNAL_RENDERER_OK;
}

