// Cangjie converts the returned CString after a cross-thread foreign call
// returns. NSString.UTF8String is not a suitable borrowed ABI value across
// that boundary, so retain a NUL-terminated byte copy on the session instead.
static NSData *CjguiStableUtf8CString(NSString *text) {
    NSData *encoded = [(text ?: @"") dataUsingEncoding:NSUTF8StringEncoding];
    NSMutableData *stable = [NSMutableData dataWithCapacity:encoded.length + 1];
    [stable appendData:encoded];
    const uint8_t terminator = 0;
    [stable appendBytes:&terminator length:1];
    return [stable copy];
}

const char *cjgui_internal_renderer_form_event_text(uint64_t session) {
    pthread_once(&gCjguiFormTextBorrowOnce, CjguiCreateFormTextBorrowKey);
    if (!gCjguiFormTextBorrowKeyValid) return "";
    CFDataRef retained = NULL;
    if (session && session <= kCjguiSessionCapacity) {
        NSUInteger index = (NSUInteger)(session - 1);
        pthread_mutex_lock(&gCjguiFormTextSnapshotLock);
        uint64_t live = atomic_load_explicit(&gCjguiCoordinateSessionGeneration[index], memory_order_acquire);
        NSData *stable = live && gCjguiFormTextSnapshotGenerations[index] == live
            ? gCjguiFormTextSnapshots[index] : nil;
        if (stable.length) retained = (CFDataRef)CFRetain((__bridge CFDataRef)stable);
        pthread_mutex_unlock(&gCjguiFormTextSnapshotLock);
    }
    CFDataRef prior = (CFDataRef)pthread_getspecific(gCjguiFormTextBorrowKey);
    if (pthread_setspecific(gCjguiFormTextBorrowKey, retained) != 0) {
        if (retained) CFRelease(retained);
        return "";
    }
    if (prior) CFRelease(prior);
    return retained ? (const char *)CFDataGetBytePtr(retained) : "";
}

