    if (!ctx || eventId == 0 || ctx.pumpedDataTransferEventId != eventId ||
        ctx.pumpedDataTransferBytes.length > kCjguiComposableDataTransferPayloadByteCapacity) return 0;
    return (uint32_t)ctx.pumpedDataTransferBytes.length;
