CjguiInternalRendererStatus
cjgui_internal_renderer_test_composable_data_transfer_cancel(uint64_t session) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = cjgui_internal_renderer_test_composable_data_transfer_cancel(session);
        });
        return status;
    }
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.composableSceneOverlay) {
        return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
    CjguiInternalRendererStatus status =
        cjgui_internal_renderer_test_composable_data_transfer_hover_target(session);
    if (status != CJGUI_INTERNAL_RENDERER_OK) return status;
    // Cancellation enters the same production callback as AppKit. It emits
    // only a paired hover leave; it never reads a pasteboard or queues an
    // owner-facing PASTE/DROP event.
    [ctx.composableSceneOverlay draggingExited:nil];
    return CJGUI_INTERNAL_RENDERER_OK;
}
#endif

typedef enum CjguiOwnerPumpTicketState {
    CjguiOwnerPumpTicketEmpty = 0,
    CjguiOwnerPumpTicketPending = 1,
    CjguiOwnerPumpTicketReady = 2,
} CjguiOwnerPumpTicketState;

// The owner and AppKit exchange one bounded POD result per session. The table
// is not an event queue: AppKit owns the actual per-session FIFO, while the
// ticket only holds the one event already removed from that FIFO.
typedef struct CjguiOwnerPumpTicket {
    CjguiOwnerPumpTicketState state;
    uint64_t session;
    uint64_t sessionGeneration;
    uint64_t nonce;
    // Changes only when same-generation private FIFO work is added/merged or
    // a legal predecessor terminal makes an existing head serviceable.
    uint64_t workRevision;
    uint64_t servicedWorkRevision;
    uint64_t traceTurn;
    uint64_t traceDispatch;
    uint32_t tracePhase;
    BOOL wantsEvent;
    CjguiInternalRendererStatus status;
    CjguiInternalRendererEvent event;
    uint64_t pointerSessionGeneration;
    uint64_t pointerCoordinateEpoch;
    uint64_t pointerStreamSessionGeneration;
    uint64_t pointerStreamBindingEpoch;
    uint64_t pointerStreamFirstSequence;
    uint64_t pointerStreamLastSequence;
    uint64_t pointerStreamPreviousSequence;
    uint32_t pointerStreamPhase;
    uint64_t inputSessionGeneration;
    uint64_t inputSequence;
    uint64_t inputPreviousSequence;
    uint32_t inputEventKind;
    CjguiInternalRendererPointerEventGeometry pointerGeometry;
    CjguiInternalActivationPrefix activationPrefix;
} CjguiOwnerPumpTicket;

static CjguiOwnerPumpTicket gCjguiOwnerPumpTickets[kCjguiSessionCapacity];
static pthread_mutex_t gCjguiOwnerPumpTicketLock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t gCjguiOwnerPumpTicketCondition = PTHREAD_COND_INITIALIZER;
static uint64_t gCjguiOwnerPumpTicketNextNonce = 1;
static uint64_t gCjguiOwnerPumpGlobalWorkRevision = 1;
static _Thread_local BOOL gCjguiOwnerPumpServicingAsyncTicket = NO;
#ifdef CJGUI_OWNER_PUMP_TESTING
static _Atomic(bool) gCjguiOwnerPumpTestEnqueueBeforeReadyNonePublish = false;
static _Atomic(uint64_t) gCjguiOwnerPumpTestEnqueueSession = 0;
static _Atomic(uint32_t) gCjguiOwnerPumpTestEnqueueKind = 0;
static _Atomic(bool) gCjguiOwnerPumpTestEnqueueAfterEvent = false;
static _Atomic(uint64_t) gCjguiOwnerPumpTestAfterEventSession = 0;
static _Atomic(uint32_t) gCjguiOwnerPumpTestAfterEventKind = 0;
static _Atomic(uint64_t) gCjguiOwnerPumpTestPublishRaceNonce = 0;
static _Atomic(uint64_t) gCjguiOwnerPumpTestPublishRaceNextNonce = 0;
#endif

// The coordinate epoch may change while an event waits in this ticket. Pump
// validity is only the renderer-session lifetime generation; per-event pointer
// provenance carries and validates its own captured coordinate epoch.
static uint64_t CjguiOwnerPumpLiveSessionGeneration(uint64_t session) {
    if (!session || session > kCjguiSessionCapacity) return 0;
    return atomic_load_explicit(&gCjguiCoordinateSessionGeneration[session - 1],
        memory_order_acquire);
}

static NSUInteger CjguiOwnerPumpTicketIndex(uint64_t session) {
    return session > 0 && session <= kCjguiSessionCapacity
        ? (NSUInteger)(session - 1) : NSNotFound;
}

enum { CjguiOwnerWaitNotifyTicketWork = 1, CjguiOwnerWaitNotifyGlobalWork = 2,
       CjguiOwnerWaitNotifyReadyEvent = 3 };
typedef struct CjguiOwnerWaitNotifyFact {
    uint64_t revision;
    uint64_t monoNs;
    uint64_t waitId;
    uint64_t ownerSession;
    uint64_t ownerTurn;
    uint64_t ownerGeneration;
    uint64_t sourceSession;
    uint32_t category;
} CjguiOwnerWaitNotifyFact;

static BOOL CjguiOwnerWaitTraceEnabled(void) {
    static int enabled = -1;
    if (enabled < 0) {
        const char *value = getenv("CJGUI_OWNER_WAIT_TRACE");
        enabled = value && strcmp(value, "1") == 0 && CjguiOwnerPhaseTraceEnabled() ? 1 : 0;
    }
    return enabled != 0;
}

static void CjguiOwnerWaitTraceEmit(uint32_t phase, uint64_t waitId, uint32_t auxiliary,
    uint64_t value, uint64_t monoNs, uint64_t session, uint64_t turn, uint64_t generation,
    uint64_t threadId) {
    if (!CjguiOwnerWaitTraceEnabled()) return;
    (void)CjguiOwnerTraceAppendAtWithOwnerIdentity(CJGUI_OWNER_TRACE_OBSERVATION_SCALAR,
        session, turn, waitId, auxiliary, generation, phase, value, monoNs, threadId,
        0, 0, NO, UINT64_MAX);
}

static void CjguiOwnerWaitTraceCurrentContext(uint64_t *outSession, uint64_t *outTurn,
    uint64_t *outGeneration) {
    uint64_t turn = atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn, memory_order_acquire);
    uint64_t startedTurn = atomic_load_explicit(&gCjguiOwnerTraceTurnStartIdentity, memory_order_acquire);
    uint64_t session = atomic_load_explicit(&gCjguiOwnerTraceTurnStartSession, memory_order_acquire);
    uint64_t generation = atomic_load_explicit(&gCjguiOwnerTraceTurnStartGeneration, memory_order_acquire);
    if (!turn || turn == UINT64_MAX || turn != startedTurn) {
        turn = UINT64_MAX;
        session = 0;
        generation = UINT64_MAX;
    }
    *outSession = session;
    *outTurn = turn;
    *outGeneration = generation;
}

static uint64_t CjguiOwnerPumpGlobalWorkRevisionBumpLocked(uint32_t category,
    uint64_t sourceSession, CjguiOwnerWaitNotifyFact *outFact) {
    CjguiOwnerWaitNotifyFact fact = {0};
    if (CjguiOwnerWaitTraceEnabled()) {
        fact.waitId = atomic_load_explicit(&gCjguiOwnerWaitTraceActiveId, memory_order_acquire);
        if (fact.waitId && fact.waitId != UINT64_MAX) {
            fact.ownerSession = atomic_load_explicit(&gCjguiOwnerWaitTraceActiveSession, memory_order_relaxed);
            fact.ownerTurn = atomic_load_explicit(&gCjguiOwnerWaitTraceActiveTurn, memory_order_relaxed);
            fact.ownerGeneration = atomic_load_explicit(&gCjguiOwnerWaitTraceActiveGeneration, memory_order_relaxed);
        } else {
            fact.waitId = 0;
            fact.ownerTurn = UINT64_MAX;
            fact.ownerGeneration = UINT64_MAX;
        }
        fact.sourceSession = sourceSession;
        fact.category = category;
    }
    if (gCjguiOwnerPumpGlobalWorkRevision != UINT64_MAX)
        gCjguiOwnerPumpGlobalWorkRevision += 1;
    fact.revision = gCjguiOwnerPumpGlobalWorkRevision;
    if (CjguiOwnerWaitTraceEnabled()) fact.monoNs = CjguiOwnerTraceNanoseconds();
    pthread_cond_broadcast(&gCjguiOwnerPumpTicketCondition);
    if (outFact) *outFact = fact;
    return fact.revision;
}

static void CjguiOwnerWaitTraceEmitNotify(const CjguiOwnerWaitNotifyFact *fact) {
    if (!fact || !CjguiOwnerWaitTraceEnabled() || !fact->monoNs) return;
    uint64_t threadId = UINT64_MAX;
    if (pthread_threadid_np(NULL, &threadId) != 0 || !threadId) threadId = UINT64_MAX;
    uint32_t phase = fact->category == CjguiOwnerWaitNotifyTicketWork
        ? CJGUI_OWNER_PHASE_OWNER_WAIT_NOTIFY_TICKET_REVISION
        : (fact->category == CjguiOwnerWaitNotifyGlobalWork
            ? CJGUI_OWNER_PHASE_OWNER_WAIT_NOTIFY_GLOBAL_REVISION
            : CJGUI_OWNER_PHASE_OWNER_WAIT_NOTIFY_READY_REVISION);
    uint32_t sourceSession = fact->sourceSession <= kCjguiSessionCapacity
        ? (uint32_t)fact->sourceSession : 0;
    CjguiOwnerWaitTraceEmit(phase, fact->waitId, sourceSession, fact->revision,
        fact->monoNs, fact->ownerSession, fact->ownerTurn, fact->ownerGeneration, threadId);
}

enum { CjguiOwnerWaitExitRevisionChanged = 1, CjguiOwnerWaitExitReadyEvent = 2,
       CjguiOwnerWaitExitDeadline = 3, CjguiOwnerWaitExitError = 4,
       CjguiOwnerWaitExitMainThread = 5 };

static uint64_t CjguiOwnerWaitTraceBegin(uint64_t absoluteDeadlineNs,
    uint64_t effectiveDeadlineNs, uint64_t observedRevision, uint64_t entryMonoNs,
    uint64_t *outSession, uint64_t *outTurn, uint64_t *outGeneration, uint64_t *outThreadId,
    BOOL *outTracked) {
    if (!CjguiOwnerWaitTraceEnabled()) return 0;
    uint64_t waitId = atomic_fetch_add_explicit(&gCjguiOwnerWaitTraceNextId, 1,
        memory_order_relaxed) + 1;
    CjguiOwnerWaitTraceCurrentContext(outSession, outTurn, outGeneration);
    *outThreadId = UINT64_MAX;
    if (pthread_threadid_np(NULL, outThreadId) != 0 || !*outThreadId) *outThreadId = UINT64_MAX;
    uint64_t expected = 0;
    BOOL tracked = atomic_compare_exchange_strong_explicit(&gCjguiOwnerWaitTraceActiveId,
        &expected, UINT64_MAX, memory_order_acq_rel, memory_order_relaxed);
    if (tracked) {
        atomic_store_explicit(&gCjguiOwnerWaitTraceActiveSession, *outSession, memory_order_relaxed);
        atomic_store_explicit(&gCjguiOwnerWaitTraceActiveTurn, *outTurn, memory_order_relaxed);
        atomic_store_explicit(&gCjguiOwnerWaitTraceActiveGeneration, *outGeneration, memory_order_relaxed);
        atomic_store_explicit(&gCjguiOwnerWaitTraceActiveId, waitId, memory_order_release);
    }
    if (outTracked) *outTracked = tracked;
    CjguiOwnerWaitTraceEmit(CJGUI_OWNER_PHASE_OWNER_WAIT_ABSOLUTE_DEADLINE, waitId, 0,
        absoluteDeadlineNs, entryMonoNs, *outSession, *outTurn, *outGeneration, *outThreadId);
    CjguiOwnerWaitTraceEmit(CJGUI_OWNER_PHASE_OWNER_WAIT_EFFECTIVE_DEADLINE, waitId, 0,
        effectiveDeadlineNs, entryMonoNs, *outSession, *outTurn, *outGeneration, *outThreadId);
    CjguiOwnerWaitTraceEmit(CJGUI_OWNER_PHASE_OWNER_WAIT_OBSERVED_REVISION, waitId, 0,
        observedRevision, entryMonoNs, *outSession, *outTurn, *outGeneration, *outThreadId);
    return waitId;
}

static void CjguiOwnerWaitTraceFinish(uint64_t waitId, BOOL tracked, uint32_t reason,
    int32_t nativeStatus, uint64_t currentRevision, uint64_t exitMonoNs,
    uint64_t session, uint64_t turn, uint64_t generation, uint64_t threadId) {
    if (!waitId) return;
    uint32_t phase = reason == CjguiOwnerWaitExitRevisionChanged
        ? CJGUI_OWNER_PHASE_OWNER_WAIT_EXIT_REVISION_CHANGED
        : (reason == CjguiOwnerWaitExitReadyEvent
            ? CJGUI_OWNER_PHASE_OWNER_WAIT_EXIT_READY_EVENT
            : (reason == CjguiOwnerWaitExitDeadline
                ? CJGUI_OWNER_PHASE_OWNER_WAIT_EXIT_DEADLINE
                : (reason == CjguiOwnerWaitExitMainThread
                    ? CJGUI_OWNER_PHASE_OWNER_WAIT_EXIT_MAIN_THREAD
                    : CJGUI_OWNER_PHASE_OWNER_WAIT_EXIT_ERROR)));
    CjguiOwnerWaitTraceEmit(phase, waitId, (uint64_t)(int64_t)nativeStatus,
        currentRevision, exitMonoNs, session, turn, generation, threadId);
    if (tracked) {
        uint64_t expected = waitId;
        (void)atomic_compare_exchange_strong_explicit(&gCjguiOwnerWaitTraceActiveId,
            &expected, 0, memory_order_acq_rel, memory_order_relaxed);
    }
}

static void CjguiOwnerPumpTicketBumpRevisionLocked(CjguiOwnerPumpTicket *ticket) {
    if (ticket->workRevision == UINT64_MAX) {
        ticket->workRevision = 1;
        ticket->servicedWorkRevision = 0;
    } else {
        ticket->workRevision += 1;
    }
    pthread_cond_broadcast(&gCjguiOwnerPumpTicketCondition);
}

static void CjguiOwnerPumpTicketNoteWork(CJGuiInternalSession *session) {
    if (!session || session.destroyed || !session.rendererSessionToken) return;
    if (CjguiOwnerPumpLiveSessionGeneration(session.rendererSessionToken) !=
        session.sessionGeneration) return;
    NSUInteger index = CjguiOwnerPumpTicketIndex(session.rendererSessionToken);
    if (index == NSNotFound) return;
    CjguiOwnerWaitNotifyFact notifyFact = {0};
    pthread_mutex_lock(&gCjguiOwnerPumpTicketLock);
    CjguiOwnerPumpTicket *ticket = &gCjguiOwnerPumpTickets[index];
    (void)CjguiOwnerPumpGlobalWorkRevisionBumpLocked(CjguiOwnerWaitNotifyTicketWork,
        session.rendererSessionToken, &notifyFact);
    if (ticket->state != CjguiOwnerPumpTicketEmpty &&
        ticket->session == session.rendererSessionToken &&
        ticket->sessionGeneration == session.sessionGeneration) {
        CjguiOwnerPumpTicketBumpRevisionLocked(ticket);
    }
    pthread_mutex_unlock(&gCjguiOwnerPumpTicketLock);
    CjguiOwnerWaitTraceEmitNotify(&notifyFact);
}

uint64_t cjgui_internal_renderer_owner_work_revision(void) {
    pthread_mutex_lock(&gCjguiOwnerPumpTicketLock);
    uint64_t revision = gCjguiOwnerPumpGlobalWorkRevision;
    pthread_mutex_unlock(&gCjguiOwnerPumpTicketLock);
    return revision;
}

void cjgui_internal_renderer_owner_notify_work(void) {
    CjguiOwnerWaitNotifyFact notifyFact = {0};
    pthread_mutex_lock(&gCjguiOwnerPumpTicketLock);
    (void)CjguiOwnerPumpGlobalWorkRevisionBumpLocked(CjguiOwnerWaitNotifyGlobalWork,
        UINT64_MAX, &notifyFact);
    pthread_mutex_unlock(&gCjguiOwnerPumpTicketLock);
    CjguiOwnerWaitTraceEmitNotify(&notifyFact);
}

static BOOL CjguiOwnerPumpHasLiveReadyEventLocked(void) {
    for (NSUInteger index = 0; index < kCjguiSessionCapacity; index++) {
        CjguiOwnerPumpTicket *ticket = &gCjguiOwnerPumpTickets[index];
        if (ticket->state != CjguiOwnerPumpTicketReady ||
            ticket->status != CJGUI_INTERNAL_RENDERER_OK ||
            ticket->event.kind == CJGUI_INTERNAL_RENDERER_EVENT_NONE ||
            ticket->session != index + 1 || ticket->sessionGeneration == 0 ||
            CjguiOwnerPumpLiveSessionGeneration(ticket->session) != ticket->sessionGeneration) {
            continue;
        }
        return YES;
    }
    return NO;
}

int32_t cjgui_internal_renderer_owner_wait_work(uint64_t observedRevision,
    uint64_t absoluteDeadlineNs, uint64_t *outIdleWaitNs) {
    if (outIdleWaitNs) *outIdleWaitNs = 0;
    BOOL traceWait = CjguiOwnerWaitTraceEnabled();
    uint64_t ownerSession = 0, ownerTurn = UINT64_MAX, ownerGeneration = UINT64_MAX;
    uint64_t ownerThreadId = UINT64_MAX;
    BOOL trackedWait = NO;
    if (CjguiIsMainThread()) {
        if (traceWait) {
            uint64_t entryNs = CjguiOwnerTraceNanoseconds();
            uint64_t waitId = CjguiOwnerWaitTraceBegin(absoluteDeadlineNs, entryNs, observedRevision,
                entryNs, &ownerSession, &ownerTurn, &ownerGeneration, &ownerThreadId, &trackedWait);
            CjguiOwnerWaitTraceFinish(waitId, trackedWait, CjguiOwnerWaitExitMainThread,
                CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD, observedRevision, entryNs,
                ownerSession, ownerTurn, ownerGeneration, ownerThreadId);
        }
        return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
    }

    const uint64_t maxWaitNs = UINT64_C(16000000);
    uint64_t nowNs = CjguiOwnerTraceNanoseconds();
    uint64_t maximumDeadlineNs = nowNs > UINT64_MAX - maxWaitNs
        ? UINT64_MAX : nowNs + maxWaitNs;
    uint64_t deadlineNs = absoluteDeadlineNs < maximumDeadlineNs
        ? absoluteDeadlineNs : maximumDeadlineNs;
    uint64_t waitId = CjguiOwnerWaitTraceBegin(absoluteDeadlineNs, deadlineNs, observedRevision,
        nowNs, &ownerSession, &ownerTurn, &ownerGeneration, &ownerThreadId, &trackedWait);
    mach_timebase_info_data_t timebase = {0};
    if (outIdleWaitNs) mach_timebase_info(&timebase);

    pthread_mutex_lock(&gCjguiOwnerPumpTicketLock);
    uint64_t entryRevision = gCjguiOwnerPumpGlobalWorkRevision;
    if (waitId) {
        BOOL entryReady = CjguiOwnerPumpHasLiveReadyEventLocked();
        uint64_t entryObservedNs = CjguiOwnerTraceNanoseconds();
        CjguiOwnerWaitTraceEmit(CJGUI_OWNER_PHASE_OWNER_WAIT_ENTRY_STATE, waitId,
            entryReady ? 1u : 0u, entryRevision, entryObservedNs, ownerSession, ownerTurn,
            ownerGeneration, ownerThreadId);
    }
    for (;;) {
        uint64_t currentRevision = gCjguiOwnerPumpGlobalWorkRevision;
        BOOL readyEvent = currentRevision == observedRevision
            ? CjguiOwnerPumpHasLiveReadyEventLocked() : NO;
        uint64_t exitReason = currentRevision != observedRevision
            ? CjguiOwnerWaitExitRevisionChanged
            : (readyEvent ? CjguiOwnerWaitExitReadyEvent : 0);
        if (exitReason) {
            uint64_t exitNs = waitId ? CjguiOwnerTraceNanoseconds() : 0;
            pthread_mutex_unlock(&gCjguiOwnerPumpTicketLock);
            CjguiOwnerWaitTraceFinish(waitId, trackedWait, (uint32_t)exitReason,
                CJGUI_INTERNAL_RENDERER_OK, currentRevision, exitNs,
                ownerSession, ownerTurn, ownerGeneration, ownerThreadId);
            return CJGUI_INTERNAL_RENDERER_OK;
        }
        nowNs = CjguiOwnerTraceNanoseconds();
        if (nowNs >= deadlineNs) {
            currentRevision = gCjguiOwnerPumpGlobalWorkRevision;
            pthread_mutex_unlock(&gCjguiOwnerPumpTicketLock);
            CjguiOwnerWaitTraceFinish(waitId, trackedWait, CjguiOwnerWaitExitDeadline,
                CJGUI_INTERNAL_RENDERER_OK, currentRevision, nowNs,
                ownerSession, ownerTurn, ownerGeneration, ownerThreadId);
            return CJGUI_INTERNAL_RENDERER_OK;
        }
        uint64_t remainingNs = deadlineNs - nowNs;
        struct timespec delay = {
            .tv_sec = (time_t)(remainingNs / UINT64_C(1000000000)),
            .tv_nsec = (long)(remainingNs % UINT64_C(1000000000)),
        };
        uint64_t waitStartedNs = nowNs;
        if (waitId) {
            CjguiOwnerWaitTraceEmit(CJGUI_OWNER_PHASE_OWNER_WAIT_COND_BEGIN, waitId, 0,
                remainingNs, waitStartedNs, ownerSession, ownerTurn, ownerGeneration, ownerThreadId);
        }
        uint64_t waitStartedTicks = mach_absolute_time();
        int waitResult = pthread_cond_timedwait_relative_np(
            &gCjguiOwnerPumpTicketCondition, &gCjguiOwnerPumpTicketLock, &delay);
        uint64_t waitEndedTicks = mach_absolute_time();
        uint64_t waitEndedNs = waitId ? CjguiOwnerTraceNanoseconds() : 0;
        if (waitId) {
            uint64_t returnRevision = gCjguiOwnerPumpGlobalWorkRevision;
            CjguiOwnerWaitTraceEmit(CJGUI_OWNER_PHASE_OWNER_WAIT_COND_RETURN, waitId,
                (uint32_t)waitResult, returnRevision, waitEndedNs, ownerSession, ownerTurn,
                ownerGeneration, ownerThreadId);
        }
        if (outIdleWaitNs) {
            uint64_t durationNs = (uint64_t)(((__uint128_t)(waitEndedTicks - waitStartedTicks) *
                timebase.numer) / MAX((uint32_t)1, timebase.denom));
            *outIdleWaitNs = *outIdleWaitNs > UINT64_MAX - durationNs
                ? UINT64_MAX : *outIdleWaitNs + durationNs;
        }
        if (waitResult != 0 && waitResult != ETIMEDOUT && waitResult != EINTR) {
            currentRevision = gCjguiOwnerPumpGlobalWorkRevision;
            pthread_mutex_unlock(&gCjguiOwnerPumpTicketLock);
            CjguiOwnerWaitTraceFinish(waitId, trackedWait, CjguiOwnerWaitExitError,
                CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR, currentRevision,
                waitEndedNs, ownerSession,
                ownerTurn, ownerGeneration, ownerThreadId);
            return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        }
    }
}

uint32_t cjgui_internal_renderer_owner_pump_has_unconsumed_input(uint64_t session) {
    NSUInteger index = CjguiOwnerPumpTicketIndex(session);
    uint64_t generation = CjguiOwnerPumpLiveSessionGeneration(session);
    if (index == NSNotFound || generation == 0) return 0;
    pthread_mutex_lock(&gCjguiOwnerPumpTicketLock);
    CjguiOwnerPumpTicket *ticket = &gCjguiOwnerPumpTickets[index];
    BOOL held = ticket->session == session && ticket->sessionGeneration == generation &&
        ((ticket->state == CjguiOwnerPumpTicketPending && ticket->wantsEvent) ||
         (ticket->state == CjguiOwnerPumpTicketReady &&
          ticket->event.kind != CJGUI_INTERNAL_RENDERER_EVENT_NONE));
    pthread_mutex_unlock(&gCjguiOwnerPumpTicketLock);
    return held ? 1u : 0u;
}

static BOOL CjguiOwnerPumpTicketMatchesLocked(NSUInteger index, uint64_t nonce,
    uint64_t sessionGeneration) {
    CjguiOwnerPumpTicket *ticket = &gCjguiOwnerPumpTickets[index];
    return ticket->state == CjguiOwnerPumpTicketPending && ticket->nonce == nonce &&
        ticket->sessionGeneration == sessionGeneration;
}

#ifdef CJGUI_OWNER_PUMP_TESTING
enum { CJGUI_OWNER_PUMP_TEST_BEFORE_GUARD = 1, CJGUI_OWNER_PUMP_TEST_AFTER_GUARD_READ = 2 };
typedef struct CjguiOwnerPumpTestBarrier {
    pthread_mutex_t lock;
    pthread_cond_t condition;
    uint32_t mode;
    BOOL reached;
    BOOL released;
    uint64_t pauseMonotonicNs;
    uint64_t pauseThreadId;
    uint64_t guardMonotonicNs;
    uint64_t guardThreadId;
    uint64_t liveGeneration;
    uint64_t expectedGeneration;
    BOOL guardRecorded;
    BOOL wouldRetire;
} CjguiOwnerPumpTestBarrier;
static CjguiOwnerPumpTestBarrier gCjguiOwnerPumpTestBarrier = {
    .lock = PTHREAD_MUTEX_INITIALIZER,
    .condition = PTHREAD_COND_INITIALIZER,
};

static uint64_t CjguiOwnerPumpTestMonotonicNs(void) {
    mach_timebase_info_data_t timebase = {0};
    mach_timebase_info(&timebase);
    return (uint64_t)(((__uint128_t)mach_continuous_time() * timebase.numer) /
        MAX((uint32_t)1, timebase.denom));
}

static uint64_t CjguiOwnerPumpTestThreadId(void) {
    uint64_t threadId = 0;
    if (pthread_threadid_np(NULL, &threadId) != 0 || threadId == 0) return 0;
    return threadId;
}

static void CjguiOwnerPumpTestArmBarrier(uint32_t mode) {
    pthread_mutex_lock(&gCjguiOwnerPumpTestBarrier.lock);
    gCjguiOwnerPumpTestBarrier.mode = mode;
    gCjguiOwnerPumpTestBarrier.reached = NO;
    gCjguiOwnerPumpTestBarrier.released = NO;
    gCjguiOwnerPumpTestBarrier.pauseMonotonicNs = 0;
    gCjguiOwnerPumpTestBarrier.pauseThreadId = 0;
    gCjguiOwnerPumpTestBarrier.guardMonotonicNs = 0;
    gCjguiOwnerPumpTestBarrier.guardThreadId = 0;
    gCjguiOwnerPumpTestBarrier.liveGeneration = 0;
    gCjguiOwnerPumpTestBarrier.expectedGeneration = 0;
    gCjguiOwnerPumpTestBarrier.guardRecorded = NO;
    gCjguiOwnerPumpTestBarrier.wouldRetire = NO;
    pthread_mutex_unlock(&gCjguiOwnerPumpTestBarrier.lock);
}

static BOOL CjguiOwnerPumpTestBarrierSnapshot(CjguiOwnerPumpTestBarrier *out) {
    if (!out) return NO;
    pthread_mutex_lock(&gCjguiOwnerPumpTestBarrier.lock);
    out->mode = gCjguiOwnerPumpTestBarrier.mode;
    out->reached = gCjguiOwnerPumpTestBarrier.reached;
    out->released = gCjguiOwnerPumpTestBarrier.released;
    out->pauseMonotonicNs = gCjguiOwnerPumpTestBarrier.pauseMonotonicNs;
    out->pauseThreadId = gCjguiOwnerPumpTestBarrier.pauseThreadId;
    out->guardMonotonicNs = gCjguiOwnerPumpTestBarrier.guardMonotonicNs;
    out->guardThreadId = gCjguiOwnerPumpTestBarrier.guardThreadId;
    out->liveGeneration = gCjguiOwnerPumpTestBarrier.liveGeneration;
    out->expectedGeneration = gCjguiOwnerPumpTestBarrier.expectedGeneration;
    out->guardRecorded = gCjguiOwnerPumpTestBarrier.guardRecorded;
    out->wouldRetire = gCjguiOwnerPumpTestBarrier.wouldRetire;
    pthread_mutex_unlock(&gCjguiOwnerPumpTestBarrier.lock);
    return out->reached;
}

static void CjguiOwnerPumpTestReleaseBarrier(uint32_t mode) {
    pthread_mutex_lock(&gCjguiOwnerPumpTestBarrier.lock);
    if (gCjguiOwnerPumpTestBarrier.mode == mode && gCjguiOwnerPumpTestBarrier.reached) {
        gCjguiOwnerPumpTestBarrier.released = YES;
        pthread_cond_broadcast(&gCjguiOwnerPumpTestBarrier.condition);
    }
    pthread_mutex_unlock(&gCjguiOwnerPumpTestBarrier.lock);
}

static void CjguiOwnerPumpTestBarrierPoint(uint32_t mode, uint64_t liveGeneration,
    uint64_t expectedGeneration, BOOL wouldRetire) {
    pthread_mutex_lock(&gCjguiOwnerPumpTestBarrier.lock);
    if (mode == CJGUI_OWNER_PUMP_TEST_AFTER_GUARD_READ) {
        mach_timebase_info_data_t timebase = {0};
        mach_timebase_info(&timebase);
        gCjguiOwnerPumpTestBarrier.guardMonotonicNs = (uint64_t)(
            ((__uint128_t)mach_continuous_time() * timebase.numer) /
            MAX((uint32_t)1, timebase.denom));
        uint64_t threadId = 0;
        if (pthread_threadid_np(NULL, &threadId) != 0 || threadId == 0) threadId = 0;
        gCjguiOwnerPumpTestBarrier.guardThreadId = threadId;
        gCjguiOwnerPumpTestBarrier.liveGeneration = liveGeneration;
        gCjguiOwnerPumpTestBarrier.expectedGeneration = expectedGeneration;
        gCjguiOwnerPumpTestBarrier.guardRecorded = YES;
        gCjguiOwnerPumpTestBarrier.wouldRetire = wouldRetire;
    }
    if (gCjguiOwnerPumpTestBarrier.mode == mode && !gCjguiOwnerPumpTestBarrier.reached) {
        if (mode == CJGUI_OWNER_PUMP_TEST_BEFORE_GUARD) {
            mach_timebase_info_data_t timebase = {0};
            mach_timebase_info(&timebase);
            gCjguiOwnerPumpTestBarrier.pauseMonotonicNs = (uint64_t)(
                ((__uint128_t)mach_continuous_time() * timebase.numer) /
                MAX((uint32_t)1, timebase.denom));
            uint64_t threadId = 0;
            if (pthread_threadid_np(NULL, &threadId) != 0 || threadId == 0) threadId = 0;
            gCjguiOwnerPumpTestBarrier.pauseThreadId = threadId;
        }
        gCjguiOwnerPumpTestBarrier.reached = YES;
        pthread_cond_broadcast(&gCjguiOwnerPumpTestBarrier.condition);
        while (!gCjguiOwnerPumpTestBarrier.released)
            pthread_cond_wait(&gCjguiOwnerPumpTestBarrier.condition,
                &gCjguiOwnerPumpTestBarrier.lock);
    }
    pthread_mutex_unlock(&gCjguiOwnerPumpTestBarrier.lock);
}
#endif

static BOOL CjguiOwnerPumpRetireIfSessionChanged(uint64_t session, NSUInteger index,
    uint64_t nonce, uint64_t expectedGeneration) {
#ifdef CJGUI_OWNER_PUMP_TESTING
    CjguiOwnerPumpTestBarrierPoint(CJGUI_OWNER_PUMP_TEST_BEFORE_GUARD, 0,
        expectedGeneration, NO);
#endif
    uint64_t liveGeneration = CjguiOwnerPumpLiveSessionGeneration(session);
    BOOL wouldRetire = expectedGeneration == 0 || liveGeneration != expectedGeneration;
#ifdef CJGUI_OWNER_PUMP_TESTING
    CjguiOwnerPumpTestBarrierPoint(CJGUI_OWNER_PUMP_TEST_AFTER_GUARD_READ, liveGeneration,
        expectedGeneration, wouldRetire);
#endif
    if (!wouldRetire) return NO;
    if (index < kCjguiSessionCapacity && nonce != 0) {
        pthread_mutex_lock(&gCjguiOwnerPumpTicketLock);
        CjguiOwnerPumpTicket *ticket = &gCjguiOwnerPumpTickets[index];
        if (ticket->state != CjguiOwnerPumpTicketEmpty && ticket->session == session &&
            ticket->nonce == nonce && ticket->sessionGeneration == expectedGeneration) {
            memset(ticket, 0, sizeof(*ticket));
            pthread_cond_broadcast(&gCjguiOwnerPumpTicketCondition);
        }
        pthread_mutex_unlock(&gCjguiOwnerPumpTicketLock);
    }
    return YES;
}

static void CjguiOwnerPumpTraceReturn(uint64_t session, uint64_t turn,
    uint64_t dispatch, uint64_t generation, uint32_t phase) {
    if (dispatch != 0) {
        if (!CjguiOwnerPhaseTraceEnabled()) return;
        CjguiOwnerTraceEndWatch(3, dispatch, UINT64_MAX, session, turn, dispatch, dispatch, generation);
        uint64_t liveGeneration = CjguiOwnerPumpLiveSessionGeneration(session);
        uint64_t consumeGeneration = liveGeneration == generation && liveGeneration != 0
            ? liveGeneration : 0;
        uint64_t consumeTurn = atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn,
            memory_order_acquire);
        CjguiOwnerTraceAppendAtWithOwnerIdentity(CJGUI_OWNER_TRACE_OWNER_RETURN,
            session, turn, dispatch, dispatch, generation, phase, 0, 0, 0,
            consumeTurn, consumeGeneration, YES, UINT64_MAX);
    }
}

static void CjguiOwnerPumpTicketService(uint64_t session, NSUInteger index,
    uint64_t nonce, uint64_t sessionGeneration,
    uint64_t traceTurn, uint64_t traceDispatch, uint32_t tracePhase) {
    uint64_t mainStarted = cjgui_internal_renderer_owner_trace_ns();
    uint64_t mainCpuStarted = mainStarted
        ? cjgui_internal_renderer_owner_thread_cpu_ns() : 0;
    cjgui_internal_renderer_owner_trace_dispatch_event(CJGUI_OWNER_TRACE_MAIN_ENTER,
        session, traceTurn, traceDispatch, traceDispatch, sessionGeneration, tracePhase, 0);

    CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    CjguiInternalRendererEvent event = {0};
    event.kind = CJGUI_INTERNAL_RENDERER_EVENT_NONE;
    uint64_t pointerGeneration = 0;
    uint64_t pointerCoordinateEpoch = 0;
    uint64_t pointerStreamGeneration = 0;
    uint64_t pointerStreamBindingEpoch = 0;
    uint64_t pointerStreamFirstSequence = 0;
    uint64_t pointerStreamLastSequence = 0;
    uint64_t pointerStreamPreviousSequence = 0;
    uint32_t pointerStreamPhase = 0;
    uint64_t inputGeneration = 0;
    uint64_t inputSequence = 0;
    uint64_t inputPreviousSequence = 0;
    uint32_t inputEventKind = 0;
    CjguiInternalRendererPointerEventGeometry pointerGeometry = {0};
    CjguiInternalActivationPrefix activationPrefix = {0};
    uint64_t serviceWorkRevision = 0;

    uint64_t currentGeneration = CjguiOwnerPumpLiveSessionGeneration(session);
    BOOL ticketCurrent = NO;
    pthread_mutex_lock(&gCjguiOwnerPumpTicketLock);
    if (index < kCjguiSessionCapacity) {
        ticketCurrent = CjguiOwnerPumpTicketMatchesLocked(index, nonce, sessionGeneration);
    }
    pthread_mutex_unlock(&gCjguiOwnerPumpTicketLock);

    CJGuiInternalSession *ctx = nil;
    if (ticketCurrent && currentGeneration != 0 &&
        currentGeneration == sessionGeneration && CjguiIsMainThread()) {
        ctx = CjguiLookupSession(session);
    }
    if (ctx && !ctx.destroyed && ctx.sessionGeneration == sessionGeneration)
        CjguiClearMainPumpedPointerCoordinateLifetime(ctx);
    if (ctx && !ctx.destroyed && ctx.sessionGeneration == sessionGeneration)
        CjguiClearMainPumpedPointerStream(ctx);
    if (ctx && !ctx.destroyed && ctx.sessionGeneration == sessionGeneration)
        CjguiClearMainPumpedInputProvenance(ctx);
    if (!ticketCurrent) {
        status = CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    } else if (currentGeneration == 0 || currentGeneration != sessionGeneration ||
        !ctx || ctx.destroyed || ctx.sessionGeneration != sessionGeneration) {
        status = CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    } else if (!gCjguiMainThreadDispatchEnabled) {
        status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
    } else {
#ifdef CJGUI_INTERNAL_TESTING
        ctx.testActivationPairTicketRequest = traceDispatch;
#endif
        gCjguiOwnerPumpServicingAsyncTicket = YES;
        BOOL wantsEvent = NO;
        pthread_mutex_lock(&gCjguiOwnerPumpTicketLock);
        if (CjguiOwnerPumpTicketMatchesLocked(index, nonce, sessionGeneration)) {
            wantsEvent = gCjguiOwnerPumpTickets[index].wantsEvent;
        serviceWorkRevision = gCjguiOwnerPumpTickets[index].workRevision;
        }
        pthread_mutex_unlock(&gCjguiOwnerPumpTicketLock);
        status = cjgui_internal_renderer_pump_event(session, 0, wantsEvent ? &event : NULL);
#ifdef CJGUI_OWNER_PUMP_TESTING
        if (status == CJGUI_INTERNAL_RENDERER_OK &&
            event.kind != CJGUI_INTERNAL_RENDERER_EVENT_NONE &&
            atomic_load_explicit(&gCjguiOwnerPumpTestEnqueueAfterEvent,
                memory_order_acquire) &&
            atomic_load_explicit(&gCjguiOwnerPumpTestAfterEventSession,
                memory_order_relaxed) == session) {
            bool expected = true;
            if (atomic_compare_exchange_strong_explicit(
                    &gCjguiOwnerPumpTestEnqueueAfterEvent, &expected, false,
                    memory_order_acq_rel, memory_order_acquire)) {
                uint32_t kind = atomic_load_explicit(&gCjguiOwnerPumpTestAfterEventKind,
                    memory_order_relaxed);
                (void)CjguiEnqueueInteraction(ctx, kind, 0, @"ready-event-preserve", 0, 0);
            }
        }
        if (status == CJGUI_INTERNAL_RENDERER_OK &&
            event.kind == CJGUI_INTERNAL_RENDERER_EVENT_NONE &&
            atomic_load_explicit(&gCjguiOwnerPumpTestEnqueueBeforeReadyNonePublish,
                memory_order_acquire) &&
            atomic_load_explicit(&gCjguiOwnerPumpTestEnqueueSession,
                memory_order_relaxed) == session) {
            bool expected = true;
            if (atomic_compare_exchange_strong_explicit(
                    &gCjguiOwnerPumpTestEnqueueBeforeReadyNonePublish, &expected, false,
                    memory_order_acq_rel, memory_order_acquire)) {
                uint32_t kind = atomic_load_explicit(&gCjguiOwnerPumpTestEnqueueKind,
                    memory_order_relaxed);
                pthread_mutex_lock(&gCjguiOwnerPumpTicketLock);
                CjguiOwnerPumpTicket *ticket = &gCjguiOwnerPumpTickets[index];
                atomic_store_explicit(&gCjguiOwnerPumpTestPublishRaceNonce, ticket->nonce,
                    memory_order_relaxed);
                atomic_store_explicit(&gCjguiOwnerPumpTestPublishRaceNextNonce,
                    gCjguiOwnerPumpTicketNextNonce, memory_order_relaxed);
                pthread_mutex_unlock(&gCjguiOwnerPumpTicketLock);
                (void)CjguiEnqueueInteraction(ctx, kind, 0, @"publish-race", 0, 0);
            }
        }
#endif
        gCjguiOwnerPumpServicingAsyncTicket = NO;
        activationPrefix = ctx.pumpedActivationPrefix;
        ctx.pumpedActivationPrefix = (CjguiInternalActivationPrefix){0};
        if (status == CJGUI_INTERNAL_RENDERER_OK &&
            event.kind != CJGUI_INTERNAL_RENDERER_EVENT_NONE &&
            ctx.pumpedPointerGeometry.present == 1 &&
            ctx.pumpedPointerGeometry.kind == event.kind) {
            pointerGeometry = ctx.pumpedPointerGeometry;
        }
        (void)cjgui_internal_renderer_main_pumped_pointer_coordinate_lifetime(
            session, &pointerGeneration, &pointerCoordinateEpoch);
        CjguiClearMainPumpedPointerCoordinateLifetime(ctx);
        (void)cjgui_internal_renderer_main_pumped_pointer_fifo(session,
            &pointerStreamGeneration, &pointerStreamBindingEpoch,
            &pointerStreamFirstSequence, &pointerStreamLastSequence,
            &pointerStreamPreviousSequence, &pointerStreamPhase);
        CjguiClearMainPumpedPointerStream(ctx);
        (void)cjgui_internal_renderer_main_pumped_input_provenance(session,
            &inputGeneration, &inputSequence, &inputPreviousSequence, &inputEventKind);
        CjguiClearMainPumpedInputProvenance(ctx);
        CjguiTraceOwnerPhase(session, "pump.before_idle.main", mainStarted);
    }

    // Publish the trace edge before the READY state becomes visible to the
    // owner. Otherwise owner_return could race ahead of main_exit in the ring.
    CjguiTraceOwnerCpuSpan(session, "pump.before_idle.main", mainStarted, mainCpuStarted);
    cjgui_internal_renderer_owner_trace_dispatch_event(CJGUI_OWNER_TRACE_MAIN_EXIT,
        session, traceTurn, traceDispatch, traceDispatch, sessionGeneration, tracePhase, 0);

    BOOL reserviceForNewWork = NO;
    CjguiOwnerWaitNotifyFact readyNotifyFact = {0};
    pthread_mutex_lock(&gCjguiOwnerPumpTicketLock);
    if (index < kCjguiSessionCapacity &&
        CjguiOwnerPumpTicketMatchesLocked(index, nonce, sessionGeneration)) {
        CjguiOwnerPumpTicket *ticket = &gCjguiOwnerPumpTickets[index];
        ticket->status = status;
        ticket->event = event;
        ticket->pointerSessionGeneration = pointerGeneration;
        ticket->pointerCoordinateEpoch = pointerCoordinateEpoch;
        ticket->pointerStreamSessionGeneration = pointerStreamGeneration;
        ticket->pointerStreamBindingEpoch = pointerStreamBindingEpoch;
        ticket->pointerStreamFirstSequence = pointerStreamFirstSequence;
        ticket->pointerStreamLastSequence = pointerStreamLastSequence;
        ticket->pointerStreamPreviousSequence = pointerStreamPreviousSequence;
        ticket->pointerStreamPhase = pointerStreamPhase;
        ticket->inputSessionGeneration = inputGeneration;
        ticket->inputSequence = inputSequence;
        ticket->inputPreviousSequence = inputPreviousSequence;
        ticket->inputEventKind = inputEventKind;
        ticket->pointerGeometry = pointerGeometry;
        ticket->activationPrefix = activationPrefix;
        ticket->servicedWorkRevision = serviceWorkRevision;
        if (status == CJGUI_INTERNAL_RENDERER_OK &&
            event.kind == CJGUI_INTERNAL_RENDERER_EVENT_NONE &&
            ticket->workRevision != serviceWorkRevision) {
            // Work arrived after the main service checked an empty FIFO but
            // before READY_NONE was published. Keep the nonce and deadline.
            ticket->state = CjguiOwnerPumpTicketPending;
            reserviceForNewWork = YES;
        } else {
            ticket->servicedWorkRevision = ticket->workRevision;
            ticket->state = CjguiOwnerPumpTicketReady;
            if (status == CJGUI_INTERNAL_RENDERER_OK &&
                event.kind != CJGUI_INTERNAL_RENDERER_EVENT_NONE) {
                (void)CjguiOwnerPumpGlobalWorkRevisionBumpLocked(CjguiOwnerWaitNotifyReadyEvent,
                    session, &readyNotifyFact);
            }
        }
        pthread_cond_broadcast(&gCjguiOwnerPumpTicketCondition);
    }
    pthread_mutex_unlock(&gCjguiOwnerPumpTicketLock);
    CjguiOwnerWaitTraceEmitNotify(&readyNotifyFact);
    if (reserviceForNewWork) {
        dispatch_async(dispatch_get_main_queue(), ^{
            CjguiOwnerPumpTicketService(session, index, nonce,
                sessionGeneration, traceTurn, traceDispatch, tracePhase);
        });
    }
}

static CjguiInternalRendererStatus CjguiOwnerPumpWaitRemaining(uint64_t deadlineMicros,
    uint64_t session, NSUInteger index, uint64_t nonce,
    uint64_t sessionGeneration, uint64_t *outIdleWaitNs) {
    BOOL traceIdle = CjguiOwnerPhaseTraceEnabled() || getenv("CJGUI_OWNER_TURN_TRACE") != NULL;
    int waitResult = 0;
    mach_timebase_info_data_t timebase = {0};
    if (outIdleWaitNs || traceIdle) mach_timebase_info(&timebase);
    pthread_mutex_lock(&gCjguiOwnerPumpTicketLock);
    for (;;) {
        uint64_t now = CjguiCaretBlinkClockMicros();
        if (now >= deadlineMicros) break;
        CjguiOwnerPumpTicket *ticket = &gCjguiOwnerPumpTickets[index];
        BOOL sameTicket = ticket->session == session && ticket->nonce == nonce &&
            ticket->sessionGeneration == sessionGeneration;
        BOOL pending = sameTicket && ticket->state == CjguiOwnerPumpTicketPending;
        BOOL readyNone = sameTicket && ticket->state == CjguiOwnerPumpTicketReady &&
            ticket->status == CJGUI_INTERNAL_RENDERER_OK &&
            ticket->event.kind == CJGUI_INTERNAL_RENDERER_EVENT_NONE;
        if (!pending && !readyNone) break;
        if (readyNone && ticket->workRevision != ticket->servicedWorkRevision) {
            // Reopen this same ticket exactly once for the newest revision.
            // The owner never blocks on AppKit while holding this lock.
            ticket->state = CjguiOwnerPumpTicketPending;
            uint64_t traceTurn = ticket->traceTurn;
            uint64_t traceDispatch = ticket->traceDispatch;
            uint32_t tracePhase = ticket->tracePhase;
            pthread_mutex_unlock(&gCjguiOwnerPumpTicketLock);
            dispatch_async(dispatch_get_main_queue(), ^{
                CjguiOwnerPumpTicketService(session, index, nonce,
                    sessionGeneration, traceTurn, traceDispatch, tracePhase);
            });
            pthread_mutex_lock(&gCjguiOwnerPumpTicketLock);
            continue;
        }
        uint64_t remaining = deadlineMicros - now;
        struct timespec delay = { .tv_sec = (time_t)(remaining / 1000000),
            .tv_nsec = (long)((remaining % 1000000) * 1000) };
        uint64_t waitStartedTicks = mach_absolute_time();
        waitResult = pthread_cond_timedwait_relative_np(&gCjguiOwnerPumpTicketCondition,
            &gCjguiOwnerPumpTicketLock, &delay);
        uint64_t waitEndedTicks = mach_absolute_time();
        if (outIdleWaitNs || traceIdle) {
            uint64_t durationNs = (uint64_t)(((__uint128_t)(waitEndedTicks - waitStartedTicks) *
                timebase.numer) / MAX((uint32_t)1, timebase.denom));
            uint64_t endedNs = CjguiOwnerTraceNanoseconds();
            uint64_t startedNs = endedNs >= durationNs ? endedNs - durationNs : 0;
            pthread_mutex_unlock(&gCjguiOwnerPumpTicketLock);
            if (outIdleWaitNs) *outIdleWaitNs += durationNs;
            if (traceIdle) CjguiTraceOwnerIdleWait(session, startedNs, endedNs);
            pthread_mutex_lock(&gCjguiOwnerPumpTicketLock);
        }
        if (waitResult != 0 && waitResult != ETIMEDOUT && waitResult != EINTR) break;
    }
    pthread_mutex_unlock(&gCjguiOwnerPumpTicketLock);
    return waitResult == 0 || waitResult == ETIMEDOUT || waitResult == EINTR
        ? CJGUI_INTERNAL_RENDERER_OK : CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_pump_event(uint64_t session,
                                   uint32_t timeoutMs,
                                   CjguiInternalRendererEvent *outEvent) {
    return cjgui_internal_renderer_pump_event_measured(session, timeoutMs, outEvent, NULL);
}

CjguiInternalRendererStatus
cjgui_internal_renderer_pump_event_measured(uint64_t session, uint32_t timeoutMs,
    CjguiInternalRendererEvent *outEvent, uint64_t *outIdleWaitNs) {
    if (outIdleWaitNs) *outIdleWaitNs = 0;
    if (outEvent) {
        memset(outEvent, 0, sizeof(CjguiInternalRendererEvent));
        outEvent->kind = CJGUI_INTERNAL_RENDERER_EVENT_NONE;
    }
    cjgui_internal_renderer_publish_owner_consumed_pointer_coordinate_lifetime(session, 0, 0);
    cjgui_internal_renderer_publish_owner_consumed_pointer_fifo(session, 0, 0, 0, 0, 0, 0);
    cjgui_internal_renderer_publish_owner_consumed_input_provenance(session, 0, 0, 0, 0);
    if (!gCjguiOwnerPumpServicingAsyncTicket)
        CjguiClearOwnerConsumedPointerGeometry(session);
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) {
            return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        }
        // The owner never waits for AppKit's queue. One ticket owns one POD
        // result; the caller's outEvent address never crosses this boundary.
        uint64_t waitMicros = (uint64_t)timeoutMs * 1000;
        uint64_t maxWaitMicros = (uint64_t)(kCjguiPumpTimeoutMaxSeconds * 1000000.0);
        if (maxWaitMicros > 16000) maxWaitMicros = 16000;
        if (waitMicros > maxWaitMicros) waitMicros = maxWaitMicros;
        uint64_t deadline = CjguiCaretBlinkClockMicros() + waitMicros;
        uint64_t sessionGeneration = CjguiOwnerPumpLiveSessionGeneration(session);
        NSUInteger index = CjguiOwnerPumpTicketIndex(session);
        if (index == NSNotFound || sessionGeneration == 0) {
            if (index != NSNotFound) {
                pthread_mutex_lock(&gCjguiOwnerPumpTicketLock);
                memset(&gCjguiOwnerPumpTickets[index], 0, sizeof(gCjguiOwnerPumpTickets[index]));
                pthread_mutex_unlock(&gCjguiOwnerPumpTicketLock);
            }
            return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
        }

        uint64_t phaseStarted = cjgui_internal_renderer_owner_trace_ns();
        uint64_t ticketNonce = 0;
        uint64_t traceTurn = 0;
        uint64_t traceDispatch = 0;
        uint32_t tracePhase = CJGUI_OWNER_PHASE_PUMP_BEFORE_IDLE;
        BOOL submitNewTicket = NO;
        BOOL consumedTicket = NO;
        CjguiInternalRendererStatus result = CJGUI_INTERNAL_RENDERER_OK;
        CjguiInternalRendererEvent deliveredEvent = {0};
        deliveredEvent.kind = CJGUI_INTERNAL_RENDERER_EVENT_NONE;
        uint64_t deliveredPointerGeneration = 0;
        uint64_t deliveredPointerEpoch = 0;
        uint64_t deliveredPointerStreamGeneration = 0;
        uint64_t deliveredPointerStreamBindingEpoch = 0;
        uint64_t deliveredPointerStreamFirstSequence = 0;
        uint64_t deliveredPointerStreamLastSequence = 0;
        uint64_t deliveredPointerStreamPreviousSequence = 0;
        uint32_t deliveredPointerStreamPhase = 0;
        uint64_t deliveredInputGeneration = 0;
        uint64_t deliveredInputSequence = 0;
        uint64_t deliveredInputPreviousSequence = 0;
        uint32_t deliveredInputEventKind = 0;
        CjguiInternalRendererPointerEventGeometry deliveredGeometry = {0};
        CjguiInternalActivationPrefix deliveredActivationPrefix = {0};

        pthread_mutex_lock(&gCjguiOwnerPumpTicketLock);
        CjguiOwnerPumpTicket *ticket = &gCjguiOwnerPumpTickets[index];
        BOOL readyEventCanDeliver = ticket->event.kind != CJGUI_INTERNAL_RENDERER_EVENT_NONE && outEvent;
        BOOL readyNoEventCanReturn = ticket->event.kind == CJGUI_INTERNAL_RENDERER_EVENT_NONE &&
            (ticket->status != CJGUI_INTERNAL_RENDERER_OK || waitMicros == 0);
        if (ticket->state != CjguiOwnerPumpTicketEmpty &&
            (ticket->session != session || ticket->sessionGeneration != sessionGeneration)) {
            memset(ticket, 0, sizeof(*ticket));
        }
        if (ticket->state == CjguiOwnerPumpTicketReady &&
            (readyEventCanDeliver || readyNoEventCanReturn)) {
            ticketNonce = ticket->nonce;
            traceTurn = ticket->traceTurn;
            traceDispatch = ticket->traceDispatch;
            tracePhase = ticket->tracePhase;
            result = ticket->status;
            deliveredEvent = ticket->event;
            deliveredPointerGeneration = ticket->pointerSessionGeneration;
            deliveredPointerEpoch = ticket->pointerCoordinateEpoch;
            deliveredPointerStreamGeneration = ticket->pointerStreamSessionGeneration;
            deliveredPointerStreamBindingEpoch = ticket->pointerStreamBindingEpoch;
            deliveredPointerStreamFirstSequence = ticket->pointerStreamFirstSequence;
            deliveredPointerStreamLastSequence = ticket->pointerStreamLastSequence;
            deliveredPointerStreamPreviousSequence = ticket->pointerStreamPreviousSequence;
            deliveredPointerStreamPhase = ticket->pointerStreamPhase;
            deliveredInputGeneration = ticket->inputSessionGeneration;
            deliveredInputSequence = ticket->inputSequence;
            deliveredInputPreviousSequence = ticket->inputPreviousSequence;
            deliveredInputEventKind = ticket->inputEventKind;
            deliveredGeometry = ticket->pointerGeometry;
            deliveredActivationPrefix = ticket->activationPrefix;
            memset(ticket, 0, sizeof(*ticket));
            consumedTicket = YES;
        } else if (ticket->state == CjguiOwnerPumpTicketReady &&
            ((ticket->event.kind != CJGUI_INTERNAL_RENDERER_EVENT_NONE && !outEvent) ||
             (ticket->event.kind == CJGUI_INTERNAL_RENDERER_EVENT_NONE &&
              ticket->status == CJGUI_INTERNAL_RENDERER_OK))) {
            // Keep a READY event until the owner provides an output buffer.
            // A successful NONE result with positive timeout remains in the
            // bounded idle wait below instead of causing a busy poll loop.
            ticketNonce = ticket->nonce;
            traceTurn = ticket->traceTurn;
            traceDispatch = ticket->traceDispatch;
            tracePhase = ticket->tracePhase;
            if (ticket->event.kind == CJGUI_INTERNAL_RENDERER_EVENT_NONE && outEvent &&
                !ticket->wantsEvent) {
                ticket->wantsEvent = YES;
                CjguiOwnerPumpTicketBumpRevisionLocked(ticket);
            }
        } else if (ticket->state == CjguiOwnerPumpTicketEmpty) {
            if (gCjguiOwnerPumpTicketNextNonce == UINT64_MAX) {
                pthread_mutex_unlock(&gCjguiOwnerPumpTicketLock);
                return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
            }
            ticketNonce = gCjguiOwnerPumpTicketNextNonce++;
            traceTurn = atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn, memory_order_acquire);
            ticket->state = CjguiOwnerPumpTicketPending;
            ticket->session = session;
            ticket->sessionGeneration = sessionGeneration;
            ticket->nonce = ticketNonce;
            ticket->traceTurn = traceTurn;
            ticket->tracePhase = tracePhase;
            ticket->wantsEvent = outEvent != NULL;
            ticket->status = CJGUI_INTERNAL_RENDERER_OK;
            memset(&ticket->event, 0, sizeof(ticket->event));
            ticket->event.kind = CJGUI_INTERNAL_RENDERER_EVENT_NONE;
            submitNewTicket = YES;
        } else {
            ticketNonce = ticket->nonce;
            traceTurn = ticket->traceTurn;
            traceDispatch = ticket->traceDispatch;
            tracePhase = ticket->tracePhase;
            if (ticket->state == CjguiOwnerPumpTicketPending && outEvent && !ticket->wantsEvent) {
                ticket->wantsEvent = YES;
                CjguiOwnerPumpTicketBumpRevisionLocked(ticket);
            }
        }
        pthread_mutex_unlock(&gCjguiOwnerPumpTicketLock);

        if (consumedTicket) {
            if (CjguiOwnerPumpRetireIfSessionChanged(session, index, ticketNonce,
                    sessionGeneration)) {
                CjguiOwnerPumpTraceReturn(session, traceTurn, traceDispatch, sessionGeneration, tracePhase);
                CjguiTraceOwnerPhase(session, "pump.before_idle.stale_return", phaseStarted);
                return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
            }
            if (outEvent) *outEvent = deliveredEvent;
            if (deliveredEvent.kind != CJGUI_INTERNAL_RENDERER_EVENT_NONE &&
                deliveredPointerGeneration == sessionGeneration && deliveredPointerEpoch != 0) {
                cjgui_internal_renderer_publish_owner_consumed_pointer_coordinate_lifetime(
                    session, deliveredPointerGeneration, deliveredPointerEpoch);
            }
            if (deliveredEvent.kind == deliveredPointerStreamPhase &&
                deliveredPointerStreamGeneration == sessionGeneration &&
                deliveredPointerStreamBindingEpoch != 0) {
                cjgui_internal_renderer_publish_owner_consumed_pointer_fifo(session,
                    deliveredPointerStreamGeneration, deliveredPointerStreamBindingEpoch,
                    deliveredPointerStreamFirstSequence, deliveredPointerStreamLastSequence,
                    deliveredPointerStreamPreviousSequence, deliveredPointerStreamPhase);
            }
            if (deliveredEvent.kind == deliveredInputEventKind && deliveredInputEventKind != 0 &&
                deliveredInputGeneration == sessionGeneration && deliveredInputSequence != 0) {
                cjgui_internal_renderer_publish_owner_consumed_input_provenance(session,
                    deliveredInputGeneration, deliveredInputSequence, deliveredInputPreviousSequence,
                    deliveredInputEventKind);
            }
            if (deliveredEvent.kind != CJGUI_INTERNAL_RENDERER_EVENT_NONE &&
                deliveredGeometry.present == 1 && deliveredGeometry.kind == deliveredEvent.kind) {
                CjguiPublishOwnerConsumedPointerGeometry(session, sessionGeneration,
                    CjguiCurrentNativeThreadId(), deliveredGeometry);
            } else {
                CjguiClearOwnerConsumedPointerGeometry(session);
            }
            CjguiPublishConsumedActivationPrefix(session, sessionGeneration, deliveredActivationPrefix);
            CjguiOwnerPumpTraceReturn(session, traceTurn, traceDispatch, sessionGeneration, tracePhase);
            CjguiTraceOwnerPhase(session, "pump.before_idle.consume", phaseStarted);
            return result;
        }

        if (submitNewTicket) {
            phaseStarted = cjgui_internal_renderer_owner_trace_ns();
            traceDispatch = cjgui_internal_renderer_owner_trace_dispatch_begin(session, traceTurn,
                0, sessionGeneration, tracePhase, 0);
            pthread_mutex_lock(&gCjguiOwnerPumpTicketLock);
            ticket = &gCjguiOwnerPumpTickets[index];
            if (CjguiOwnerPumpTicketMatchesLocked(index, ticketNonce, sessionGeneration)) {
                ticket->traceDispatch = traceDispatch;
            }
            pthread_mutex_unlock(&gCjguiOwnerPumpTicketLock);
            dispatch_async(dispatch_get_main_queue(), ^{
                CjguiOwnerPumpTicketService(session, index, ticketNonce,
                    sessionGeneration, traceTurn, traceDispatch, tracePhase);
            });
            CjguiTraceOwnerPhase(session, "pump.before_idle.submit", phaseStarted);
        } else {
            CjguiTraceOwnerPhase(session, "pump.before_idle.pending", phaseStarted);
        }

        CjguiInternalRendererStatus waitStatus = CjguiOwnerPumpWaitRemaining(
            deadline, session, index, ticketNonce, sessionGeneration,
            outIdleWaitNs);
        if (waitStatus != CJGUI_INTERNAL_RENDERER_OK) {
            if (CjguiOwnerPumpRetireIfSessionChanged(session, index, ticketNonce,
                    sessionGeneration)) {
                CjguiOwnerPumpTraceReturn(session, traceTurn, traceDispatch, sessionGeneration, tracePhase);
                return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
            }
            return waitStatus;
        }

        // If main serviced this ticket inside the caller's existing bounded
        // idle interval, consume that READY POD before returning. A ticket
        // whose queue wait outlives the interval remains intact for the next
        // owner poll; the asynchronous callback never writes to outEvent.
        pthread_mutex_lock(&gCjguiOwnerPumpTicketLock);
        ticket = &gCjguiOwnerPumpTickets[index];
        if (ticket->state == CjguiOwnerPumpTicketReady &&
            ticket->session == session &&
            ticket->sessionGeneration == sessionGeneration &&
            (ticket->event.kind == CJGUI_INTERNAL_RENDERER_EVENT_NONE || outEvent)) {
            ticketNonce = ticket->nonce;
            traceTurn = ticket->traceTurn;
            traceDispatch = ticket->traceDispatch;
            tracePhase = ticket->tracePhase;
            result = ticket->status;
            deliveredEvent = ticket->event;
            deliveredPointerGeneration = ticket->pointerSessionGeneration;
            deliveredPointerEpoch = ticket->pointerCoordinateEpoch;
            deliveredPointerStreamGeneration = ticket->pointerStreamSessionGeneration;
            deliveredPointerStreamBindingEpoch = ticket->pointerStreamBindingEpoch;
            deliveredPointerStreamFirstSequence = ticket->pointerStreamFirstSequence;
            deliveredPointerStreamLastSequence = ticket->pointerStreamLastSequence;
            deliveredPointerStreamPreviousSequence = ticket->pointerStreamPreviousSequence;
            deliveredPointerStreamPhase = ticket->pointerStreamPhase;
            deliveredInputGeneration = ticket->inputSessionGeneration;
            deliveredInputSequence = ticket->inputSequence;
            deliveredInputPreviousSequence = ticket->inputPreviousSequence;
            deliveredInputEventKind = ticket->inputEventKind;
            deliveredGeometry = ticket->pointerGeometry;
            deliveredActivationPrefix = ticket->activationPrefix;
            memset(ticket, 0, sizeof(*ticket));
            consumedTicket = YES;
        }
        pthread_mutex_unlock(&gCjguiOwnerPumpTicketLock);
        if (consumedTicket) {
            if (CjguiOwnerPumpRetireIfSessionChanged(session, index, ticketNonce,
                    sessionGeneration)) {
                CjguiOwnerPumpTraceReturn(session, traceTurn, traceDispatch, sessionGeneration, tracePhase);
                CjguiTraceOwnerPhase(session, "pump.before_idle.stale_return", phaseStarted);
                return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
            }
            if (outEvent) *outEvent = deliveredEvent;
            if (deliveredEvent.kind != CJGUI_INTERNAL_RENDERER_EVENT_NONE &&
                deliveredPointerGeneration == sessionGeneration && deliveredPointerEpoch != 0) {
                cjgui_internal_renderer_publish_owner_consumed_pointer_coordinate_lifetime(
                    session, deliveredPointerGeneration, deliveredPointerEpoch);
            }
            if (deliveredEvent.kind == deliveredPointerStreamPhase &&
                deliveredPointerStreamGeneration == sessionGeneration &&
                deliveredPointerStreamBindingEpoch != 0) {
                cjgui_internal_renderer_publish_owner_consumed_pointer_fifo(session,
                    deliveredPointerStreamGeneration, deliveredPointerStreamBindingEpoch,
                    deliveredPointerStreamFirstSequence, deliveredPointerStreamLastSequence,
                    deliveredPointerStreamPreviousSequence, deliveredPointerStreamPhase);
            }
            if (deliveredEvent.kind == deliveredInputEventKind && deliveredInputEventKind != 0 &&
                deliveredInputGeneration == sessionGeneration && deliveredInputSequence != 0) {
                cjgui_internal_renderer_publish_owner_consumed_input_provenance(session,
                    deliveredInputGeneration, deliveredInputSequence, deliveredInputPreviousSequence,
                    deliveredInputEventKind);
            }
            if (deliveredEvent.kind != CJGUI_INTERNAL_RENDERER_EVENT_NONE &&
                deliveredGeometry.present == 1 && deliveredGeometry.kind == deliveredEvent.kind) {
                CjguiPublishOwnerConsumedPointerGeometry(session, sessionGeneration,
                    CjguiCurrentNativeThreadId(), deliveredGeometry);
            } else {
                CjguiClearOwnerConsumedPointerGeometry(session);
            }
            CjguiPublishConsumedActivationPrefix(session, sessionGeneration, deliveredActivationPrefix);
            CjguiOwnerPumpTraceReturn(session, traceTurn, traceDispatch, sessionGeneration, tracePhase);
            CjguiTraceOwnerPhase(session, "pump.before_idle.consume", phaseStarted);
            return result;
        }
        if (CjguiOwnerPumpRetireIfSessionChanged(session, index, ticketNonce,
                sessionGeneration)) {
            CjguiOwnerPumpTraceReturn(session, traceTurn, traceDispatch, sessionGeneration, tracePhase);
            CjguiTraceOwnerPhase(session, "pump.before_idle.stale_return", phaseStarted);
            return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
        }
        return waitStatus;
    }

    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || ctx.destroyed) {
        return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }

    CjguiClearMainPumpedPointerCoordinateLifetime(ctx);
    CjguiClearMainPumpedPointerStream(ctx);
    CjguiClearMainPumpedInputProvenance(ctx);
    CjguiRetireComposablePreparationUnit(ctx);
    CjguiRetireSourceProxyPreparationUnit(ctx);
    ctx.pumpedPointerGeometry = (CjguiInternalRendererPointerEventGeometry){0};
    ctx.pumpedActivationPrefix = (CjguiInternalActivationPrefix){0};
    ctx.pumpedInstalledRangeInteraction = nil;
    NSTimeInterval timeoutSeconds = (NSTimeInterval)timeoutMs / 1000.0;
    if (timeoutSeconds > kCjguiPumpTimeoutMaxSeconds) {
        timeoutSeconds = kCjguiPumpTimeoutMaxSeconds;
    }
    if (timeoutSeconds < 0) {
        timeoutSeconds = 0;
    }

    // A Cangjie UI task can run directly on the macOS process main thread.
    // Return an already-queued owner event first: waiting for a new AppKit
    // event here would add the full idle interval to input that the native
    // bridge has already accepted.  Keep the FIFO itself below so this does
    // not alter target identity or close semantics.  With no owner-visible
    // event, this remains the single bounded AppKit acquisition point.
    if (ctx.pendingInteractions.count == 0 && ctx.pendingTransferTerminalFacts.count > 0) {
        [ctx.pendingInteractions addObject:ctx.pendingTransferTerminalFacts.firstObject];
        [ctx.pendingTransferTerminalFacts removeObjectAtIndex:0];
    }
    BOOL hasImmediateOwnerEvent = outEvent &&
        (ctx.pendingInteractions.count > 0 || ctx.pendingTransferTerminalFacts.count > 0 ||
         ctx.pendingInputQueueFullNotice || ctx.closeRequested);
    // Bounded, opt-in trace for a posted IME terminal that never reaches the
    // in-process NSEvent monitor. A successful CGEventPost is not a delivery
    // receipt; distinguish AppKit acquisition starvation from routing/IMK.
    static uint64_t imeTracePumps = 0, imeTraceOwnerSkips = 0, imeTraceDragSkips = 0;
    static uint64_t imeTraceAcquired = 0, imeTraceKeys = 0;
    BOOL traceImePump = getenv("CJGUI_TRACE_IME_PUMP") != NULL;
    if (traceImePump) {
        imeTracePumps += 1;
        if (hasImmediateOwnerEvent) imeTraceOwnerSkips += 1;
        if (gCjguiActiveDataTransferDragSessions != 0) imeTraceDragSkips += 1;
    }
    if (hasImmediateOwnerEvent && (ctx.window.inLiveResize || ctx.composableSceneOverlay.pressedNodeId != 0)) {
        CjguiTraceWindowInputGeometry(ctx, "owner_skip", nil);
    }
    if (!atomic_load_explicit(&gCjguiLauncherOwnsEventLoop, memory_order_acquire) &&
        !hasImmediateOwnerEvent &&
        gCjguiActiveDataTransferDragSessions == 0) {
        NSDate *untilDate = [NSDate dateWithTimeIntervalSinceNow:timeoutSeconds];
        // Do not use an unbounded AppKit loop here: the Cangjie owner must
        // regain control after at most the requested pump interval to apply
        // intent and project the real shared state.
        BOOL traceIdle = CjguiOwnerPhaseTraceEnabled() || getenv("CJGUI_OWNER_TURN_TRACE") != NULL;
        uint64_t idleStarted = (outIdleWaitNs || traceIdle) ? CjguiOwnerTraceNanoseconds() : 0;
        NSEvent *event = [ctx.app nextEventMatchingMask:NSEventMaskAny
                                              untilDate:untilDate
                                                 inMode:NSDefaultRunLoopMode
                                                dequeue:YES];
    if (idleStarted) {
            uint64_t ended = CjguiOwnerTraceNanoseconds();
            if (outIdleWaitNs) *outIdleWaitNs += ended - idleStarted;
            if (traceIdle) CjguiTraceOwnerIdleWait(session, idleStarted, ended);
        }
        if (event) {
            BOOL tracePointer = event.type == NSEventTypeLeftMouseDown || event.type == NSEventTypeLeftMouseUp ||
                event.type == NSEventTypeLeftMouseDragged;
            if (tracePointer) CjguiTraceWindowInputGeometry(ctx, "acquire_before", event);
            if (traceImePump) {
                imeTraceAcquired += 1;
                if (event.type == NSEventTypeKeyDown) {
                    imeTraceKeys += 1;
                    fprintf(stderr, "CJGUI_IME_PUMP_KEY keycode=%d session=%llu pending=%lu\n",
                            (int)event.keyCode, (unsigned long long)ctx.rendererSessionToken,
                            (unsigned long)ctx.pendingInteractions.count);
                }
            }
            uint64_t sendEventStarted = cjgui_internal_renderer_owner_trace_ns();
            [ctx.app sendEvent:event];
            CjguiTraceOwnerPhase(session, "pump.send_event", sendEventStarted);
            if (tracePointer) CjguiTraceWindowInputGeometry(ctx, "acquire_after", event);
            if (traceImePump && (event.type == NSEventTypeLeftMouseDown ||
                event.type == NSEventTypeLeftMouseUp || event.type == NSEventTypeRightMouseDown ||
                event.type == NSEventTypeRightMouseUp)) {
                fprintf(stderr, "CJGUI_IME_PUMP_POINTER type=%lu session=%llu scene=%llu "
                    "window=%ld point=%.3f,%.3f pressed=%llu active=%llu pending=%lu\n",
                    (unsigned long)event.type, (unsigned long long)ctx.rendererSessionToken,
                    (unsigned long long)ctx.composableSceneVersion, (long)event.windowNumber,
                    event.locationInWindow.x, event.locationInWindow.y,
                    (unsigned long long)ctx.composableSceneOverlay.pressedNodeId,
                    (unsigned long long)ctx.composableSceneOverlay.activeNodeId,
                    (unsigned long)ctx.pendingInteractions.count);
            }
        }
    }
    if (traceImePump && imeTracePumps % 100 == 0) {
        fprintf(stderr, "CJGUI_IME_PUMP_SUMMARY pumps=%llu owner_skips=%llu drag_skips=%llu "
                "acquired=%llu keys=%llu pending=%lu transfer=%lu\n",
                (unsigned long long)imeTracePumps, (unsigned long long)imeTraceOwnerSkips,
                (unsigned long long)imeTraceDragSkips, (unsigned long long)imeTraceAcquired,
                (unsigned long long)imeTraceKeys, (unsigned long)ctx.pendingInteractions.count,
                (unsigned long)ctx.pendingTransferTerminalFacts.count);
    }

    // Refresh window content if size changed during the pump.
    if (ctx.window) {
        [ctx.view updateDrawableSize];
    }

    if (outEvent && ctx.pendingInteractions.count > 0) {
        if (!CjguiMaterializeAfterCaretInputAtHead(ctx)) return CJGUI_INTERNAL_RENDERER_OK;
        if (ctx.pendingInteractions.count == 0) return CJGUI_INTERNAL_RENDERER_OK;
        CJGuiInternalQueuedInteraction *interaction = ctx.pendingInteractions.firstObject;
        if (interaction.caretInputBranch) {
            CjguiCaretInputBranch *branch=interaction.caretInputBranch;
            if((interaction.ownerHandoff.valid && !interaction.ownerHandoff.completed) ||
                (branch.ownerHandoff.valid && !branch.ownerHandoff.completed))return CJGUI_INTERNAL_RENDERER_OK;
            if(interaction.ownerHandoff && !interaction.ownerHandoff.valid) {
                CjguiRejectCaretInputBranch(ctx,branch,"owner_handoff_input_retired");
                return CJGUI_INTERNAL_RENDERER_OK;
            }
            if(ctx.activeCaretNavigation || branch.settledSequence<interaction.inputPreviousSequence)
                return CJGUI_INTERNAL_RENDERER_OK;
            if(!branch.valid || branch.settledSequence!=interaction.inputPreviousSequence ||
                !CjguiCaretSnapshotMatchesActual(ctx,branch.result)) {
                CjguiRejectCaretInputBranch(ctx,branch,"navigation_predecessor_not_actual");
                return CJGUI_INTERNAL_RENDERER_OK;
            }
            CJGuiInternalComposableSceneNode *accepted=CjguiCaretPrefixAcceptedNode(ctx,branch.result);
            if (!accepted) {
                CjguiRejectCaretInputBranch(ctx,branch,"accepted_node_not_same_installed_source");
                return CJGUI_INTERNAL_RENDERER_OK;
            }
            // This is the actual accepted node just verified above. Original
            // physical target and installed source stay in the private record.
            interaction.nodeId=accepted.node.nodeId;
            interaction.resourceId=accepted.node.resourceId;
            interaction.nodeKind=accepted.node.nodeKind;
            interaction.projectionVersion=accepted.node.projectionVersion;
            interaction.recordIndex=(uint32_t)accepted.index;
            ctx.activeCaretNavigation=interaction;
        }
#ifdef CJGUI_INTERNAL_TESTING
        if (CjguiTestActualPairSecondAtHead(ctx)) {
            if (!ctx.testActivationPairReleased) {
                ctx.testActivationPairHoldHits += 1;
                if (ctx.testActivationPairHoldHits == 1)
                    fprintf(stderr, "ACTUAL_PAIR_CONTROL phase=second_held generation=%llu nonce=%llu origin=%llu accepted=%llu turn=%llu tid=%llu mono_ns=%llu request=%llu head_original=1\n",
                        (unsigned long long)ctx.sessionGeneration,
                        (unsigned long long)interaction.activationPrefix.nonce,
                        (unsigned long long)interaction.activationPrefix.sceneVersion,
                        (unsigned long long)ctx.composableSceneVersion,
                        (unsigned long long)atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn, memory_order_acquire),
                        (unsigned long long)CjguiCurrentNativeThreadId(),
                        (unsigned long long)CjguiOwnerTraceNanoseconds(),
                        (unsigned long long)ctx.testActivationPairTicketRequest);
                return CJGUI_INTERNAL_RENDERER_OK;
            }
            ctx.testActivationPairSecondDequeues += 1;
            fprintf(stderr, "ACTUAL_PAIR_CONTROL phase=second_dequeue generation=%llu nonce=%llu origin=%llu accepted=%llu count=%llu turn=%llu tid=%llu mono_ns=%llu request=%llu\n",
                (unsigned long long)ctx.sessionGeneration,
                (unsigned long long)interaction.activationPrefix.nonce,
                (unsigned long long)interaction.activationPrefix.sceneVersion,
                (unsigned long long)ctx.composableSceneVersion,
                (unsigned long long)ctx.testActivationPairSecondDequeues,
                (unsigned long long)atomic_load_explicit(&gCjguiOwnerTraceCurrentTurn, memory_order_acquire),
                (unsigned long long)CjguiCurrentNativeThreadId(),
                (unsigned long long)CjguiOwnerTraceNanoseconds(),
                (unsigned long long)ctx.testActivationPairTicketRequest);
        }
#endif
        ctx.pumpedActivationPrefix = interaction.activationPrefix;
        CjguiPublishMainPumpedPointerCoordinateLifetime(ctx, interaction);
        CjguiPublishMainPumpedPointerStream(ctx, interaction);
        CjguiPublishMainPumpedInputProvenance(ctx, interaction);
        if (ctx.inputDequeueSerial!=UINT64_MAX) ctx.inputDequeueSerial++;
        if (ctx.physicalProducerDepth) ctx.physicalProducerContaminated=YES;
        [ctx.pendingInteractions removeObjectAtIndex:0];
        if (interaction.kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_RANGE_CHANGED &&
            (interaction.installedRangeIntent || interaction.installedRangeOwnedInvalid))
            ctx.pumpedInstalledRangeInteraction = interaction;
        outEvent->kind = interaction.kind;
        outEvent->recordIndex = interaction.recordIndex;
        outEvent->selectionStart = interaction.selectionStart;
        outEvent->selectionEnd = interaction.selectionEnd;
        outEvent->nodeId = interaction.nodeId;
        outEvent->projectionVersion = interaction.projectionVersion;
        outEvent->resourceId = interaction.resourceId;
        outEvent->nodeKind = interaction.nodeKind;
        outEvent->pointerX = interaction.pointerX;
        outEvent->pointerY = interaction.pointerY;
        if (interaction.hasPrecisePointer) {
            ctx.pumpedPointerGeometry = (CjguiInternalRendererPointerEventGeometry){
                .present = 1, .kind = interaction.kind, .nodeId = interaction.nodeId,
                .projectionVersion = interaction.projectionVersion,
                .resourceId = interaction.resourceId, .nodeKind = interaction.nodeKind,
                .x = interaction.precisePointerX, .y = interaction.precisePointerY,
                .translateX = interaction.pointerTranslateX,
                .translateY = interaction.pointerTranslateY,
            };
        }
        outEvent->modifierFlags = interaction.modifierFlags;
        outEvent->compositionPhase = interaction.compositionPhase;
        outEvent->replacementStart16 = interaction.replacementStart16;
        outEvent->replacementLength16 = interaction.replacementLength16;
        outEvent->markedStart16 = interaction.markedStart16;
        outEvent->markedLength16 = interaction.markedLength16;
        outEvent->compositionId = interaction.compositionId;
        outEvent->bindingEpoch = interaction.bindingEpoch;
        outEvent->dataTransferEventId = interaction.dataTransferEventId;
        if (traceImePump) {
            fprintf(stderr, "CJGUI_IME_PUMP_INTENT kind=%u session=%llu node=%llu "
                "projection=%llu accepted=%llu selection=%u:%u pending=%lu\n",
                interaction.kind, (unsigned long long)ctx.rendererSessionToken,
                (unsigned long long)interaction.nodeId, (unsigned long long)interaction.projectionVersion,
                (unsigned long long)ctx.composableSceneVersion, interaction.selectionStart,
                interaction.selectionEnd, (unsigned long)ctx.pendingInteractions.count);
        }
        CJGuiInternalTransferDeliveryIdentity *delivery = interaction.transferDeliveryIdentity;
        if (interaction.dataTransferEventId > 0 && delivery && delivery.firstDeliveryOrdinal == 0 &&
            ctx.nextTransferDeliveryOrdinal < UINT64_MAX) {
            delivery.firstDeliveryOrdinal = ++ctx.nextTransferDeliveryOrdinal;
        }
        ctx.pumpedTransferDeliveryOrdinal = delivery.firstDeliveryOrdinal;
#ifdef CJGUI_INTERNAL_TESTING
        ctx.testComposableLastPumpedKind = interaction.kind;
        ctx.testComposableLastPumpedNodeId = interaction.nodeId;
        ctx.testComposableLastPumpedProjectionVersion = interaction.projectionVersion;
#endif
        ctx.pumpedFormText = interaction.formText ?: @"";
        ctx.pumpedFormTextUtf8 = CjguiStableUtf8CString(ctx.pumpedFormText);
        ctx.pumpedDataTransferFormat = interaction.dataTransferFormat ?: @"";
        ctx.pumpedDataTransferBytes = interaction.dataTransferBytes;
        ctx.pumpedDataTransferEventId = interaction.dataTransferEventId;
        ctx.pumpedDataTransferBindingEpoch = interaction.bindingEpoch;
        ctx.pumpedDataTransferNodeId = interaction.nodeId;
        ctx.pumpedDataTransferFormatUtf8 = CjguiStableUtf8CString(ctx.pumpedDataTransferFormat);
        ctx.pumpedDataTransferSourceKind = interaction.dataTransferSourceKind ?: @"";
        ctx.pumpedDataTransferSourceKindUtf8 = CjguiStableUtf8CString(ctx.pumpedDataTransferSourceKind);
        ctx.pumpedDataTransferSourceIdentity = interaction.dataTransferSourceIdentity ?: @"";
        ctx.pumpedDataTransferSourceIdentityUtf8 = CjguiStableUtf8CString(ctx.pumpedDataTransferSourceIdentity);
        ctx.pumpedDataTransferSourceId = interaction.dataTransferSourceId;
        ctx.pumpedDataTransferExpectedOwnerVersion = interaction.expectedOwnerVersion;
    } else if (outEvent && ctx.pendingInputQueueFullNotice) {
        ctx.pumpedTransferDeliveryOrdinal = 0;
        ctx.pumpedDataTransferBytes = nil;
        ctx.pumpedDataTransferEventId = 0;
        ctx.pendingInputQueueFullNotice = NO;
        ctx.pumpedFormText = @"";
        ctx.pumpedFormTextUtf8 = CjguiStableUtf8CString(@"");
        ctx.pumpedDataTransferFormat = @"";
        ctx.pumpedDataTransferFormatUtf8 = CjguiStableUtf8CString(@"");
        ctx.pumpedDataTransferSourceKind = @"";
        ctx.pumpedDataTransferSourceKindUtf8 = CjguiStableUtf8CString(@"");
        ctx.pumpedDataTransferSourceIdentity = @"";
        ctx.pumpedDataTransferSourceIdentityUtf8 = CjguiStableUtf8CString(@"");
        ctx.pumpedDataTransferSourceId = -1;
        outEvent->kind = CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_INPUT_QUEUE_FULL;
    } else if (outEvent && ctx.closeRequested) {
        ctx.pumpedDataTransferBytes = nil;
        ctx.pumpedDataTransferEventId = 0;
        ctx.pumpedFormText = @"";
        ctx.pumpedFormTextUtf8 = CjguiStableUtf8CString(@"");
        ctx.pumpedDataTransferFormat = @"";
        ctx.pumpedDataTransferFormatUtf8 = CjguiStableUtf8CString(@"");
        ctx.pumpedDataTransferSourceKind = @"";
        ctx.pumpedDataTransferSourceKindUtf8 = CjguiStableUtf8CString(@"");
        ctx.pumpedDataTransferSourceIdentity = @"";
        ctx.pumpedDataTransferSourceIdentityUtf8 = CjguiStableUtf8CString(@"");
        ctx.pumpedDataTransferSourceId = -1;
        outEvent->kind = CJGUI_INTERNAL_RENDERER_EVENT_CLOSE_REQUESTED;
    } else if (outEvent) {
        ctx.pumpedDataTransferBytes = nil;
        ctx.pumpedDataTransferEventId = 0;
        ctx.pumpedFormText = @"";
        ctx.pumpedFormTextUtf8 = CjguiStableUtf8CString(@"");
        ctx.pumpedDataTransferFormat = @"";
        ctx.pumpedDataTransferFormatUtf8 = CjguiStableUtf8CString(@"");
        ctx.pumpedDataTransferSourceKind = @"";
        ctx.pumpedDataTransferSourceKindUtf8 = CjguiStableUtf8CString(@"");
        ctx.pumpedDataTransferSourceIdentity = @"";
        ctx.pumpedDataTransferSourceIdentityUtf8 = CjguiStableUtf8CString(@"");
        ctx.pumpedDataTransferSourceId = -1;
    }

    if (outEvent) CjguiPublishPumpedFormText(ctx);

    if (!gCjguiOwnerPumpServicingAsyncTicket) {
        uint64_t pointerGeneration = 0;
        uint64_t pointerCoordinateEpoch = 0;
        int hasPointerLifetime = cjgui_internal_renderer_main_pumped_pointer_coordinate_lifetime(
            session, &pointerGeneration, &pointerCoordinateEpoch);
        if (outEvent && outEvent->kind != CJGUI_INTERNAL_RENDERER_EVENT_NONE &&
            hasPointerLifetime && pointerGeneration != 0 && pointerCoordinateEpoch != 0) {
            cjgui_internal_renderer_publish_owner_consumed_pointer_coordinate_lifetime(
                session, pointerGeneration, pointerCoordinateEpoch);
        }
        CjguiClearMainPumpedPointerCoordinateLifetime(ctx);
        uint64_t streamGeneration = 0;
        uint64_t streamBindingEpoch = 0;
        uint64_t streamFirst = 0;
        uint64_t streamLast = 0;
        uint64_t streamPrevious = 0;
        uint32_t streamPhase = 0;
        int hasPointerStream = cjgui_internal_renderer_main_pumped_pointer_fifo(session,
            &streamGeneration, &streamBindingEpoch, &streamFirst, &streamLast,
            &streamPrevious, &streamPhase);
        if (outEvent && outEvent->kind == streamPhase &&
            outEvent->kind >= CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_BEGIN &&
            outEvent->kind <= CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_CANCEL &&
            hasPointerStream && streamGeneration != 0 && streamBindingEpoch != 0) {
            cjgui_internal_renderer_publish_owner_consumed_pointer_fifo(session,
                streamGeneration, streamBindingEpoch, streamFirst, streamLast,
                streamPrevious, streamPhase);
        } else {
            cjgui_internal_renderer_publish_owner_consumed_pointer_fifo(session, 0, 0, 0, 0, 0, 0);
        }
        if (outEvent && outEvent->kind != CJGUI_INTERNAL_RENDERER_EVENT_NONE &&
            ctx.pumpedPointerGeometry.present == 1 &&
            ctx.pumpedPointerGeometry.kind == outEvent->kind) {
            CjguiPublishOwnerConsumedPointerGeometry(session, ctx.sessionGeneration,
                CjguiCurrentNativeThreadId(), ctx.pumpedPointerGeometry);
        } else {
            CjguiClearOwnerConsumedPointerGeometry(session);
        }
        CjguiClearMainPumpedPointerStream(ctx);
        uint64_t inputGeneration = 0;
        uint64_t inputSequence = 0;
        uint64_t inputPreviousSequence = 0;
        uint32_t inputEventKind = 0;
        int hasInput = cjgui_internal_renderer_main_pumped_input_provenance(session,
            &inputGeneration, &inputSequence, &inputPreviousSequence, &inputEventKind);
        if (outEvent && outEvent->kind == inputEventKind && inputEventKind != 0 && hasInput &&
            inputGeneration == ctx.sessionGeneration && inputSequence != 0) {
            cjgui_internal_renderer_publish_owner_consumed_input_provenance(session,
                inputGeneration, inputSequence, inputPreviousSequence, inputEventKind);
        }
        CjguiClearMainPumpedInputProvenance(ctx);
    }
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_pumped_pointer_geometry(uint64_t session,
    CjguiInternalRendererPointerEventGeometry *outGeometry) {
    if (!outGeometry) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    *outGeometry = (CjguiInternalRendererPointerEventGeometry){0};
    if (!CjguiIsMainThread()) {
        if (!session || session > kCjguiSessionCapacity ||
            !atomic_load_explicit(&gCjguiCoordinateSessionGeneration[session - 1],
                memory_order_acquire)) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
        (void)CjguiReadOwnerConsumedPointerGeometry(session, outGeometry);
        if (!atomic_load_explicit(&gCjguiCoordinateSessionGeneration[session - 1],
                memory_order_acquire)) {
            *outGeometry = (CjguiInternalRendererPointerEventGeometry){0};
            return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
        }
        return CJGUI_INTERNAL_RENDERER_OK;
    }
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || ctx.destroyed) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    *outGeometry = ctx.pumpedPointerGeometry;
    return CJGUI_INTERNAL_RENDERER_OK;
}

// ---- ABI: requestClose ----

CjguiInternalRendererStatus
cjgui_internal_renderer_request_close(uint64_t session) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) {
            return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        }
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        CjguiOwnerTraceDispatchSync(session, 0, CJGUI_OWNER_PHASE_NATIVE_REQUEST_CLOSE, ^{
            status = cjgui_internal_renderer_request_close(session);
        });
        return status;
    }

    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx) {
        return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }

    NSLog(@"cjgui: post close request: probe");
    if (!ctx.closeRequested) {
        ctx.closeRequested = YES;
        NSLog(@"cjgui: close requested: probe");
    }
    NSLog(@"cjgui: main-thread drain");

    if (ctx.window) {
        [ctx.window close];
    }

    return CJGUI_INTERNAL_RENDERER_OK;
}

// ---- ABI: destroy ----

CjguiInternalRendererStatus
cjgui_internal_renderer_destroy(uint64_t session) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) {
            return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        }
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        CjguiOwnerTraceDispatchSync(session, 0, CJGUI_OWNER_PHASE_NATIVE_SESSION_DESTROY, ^{
            status = cjgui_internal_renderer_destroy(session);
        });
        return status;
    }

    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx) {
        return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
    if (ctx.destroyed) {
        // Double destroy: release the slot but signal invalid.
        CjguiReleaseSession(session);
        return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
    // An accepted owner edit may still be waiting for this exact native ACK.
    // Keep the session addressable so the retained Cangjie decision can retry
    // confirmation; destroying here would orphan an accepted body mutation.
    if (ctx.claimedInstalledRangeIntent && !ctx.claimedInstalledRangeIntent.settled)
        return CJGUI_INTERNAL_RENDERER_PENDING_SETTLEMENT_UNRESOLVED;
    if (ctx.rejectedAfterCaretInputs.count || ctx.exportedCaretRecoveryBytes.count ||
        ctx.retainedAfterCaretInputBytes)
        return CJGUI_INTERNAL_RENDERER_PENDING_SETTLEMENT_UNRESOLVED;

    // Remove scalar requester/subscriber interests while this token and
    // generation are still valid. A close never cancels another window's
    // shared load, but it must make this window invisible to late completion.
    CjguiCancelSelectionTransferBPreparation(ctx.selectionTransferCapsule);
    CjguiDiscardSelectionBSpare(ctx);
    CjguiRemoveComposableImageSubscriptions(ctx);
    CjguiCancelTextPreparationWorker(ctx.composablePreparation);
    for (CjguiComposablePreparation *preparation in ctx.retiringComposablePreparations)
        CjguiCancelTextPreparationWorker(preparation);
    CjguiClearWorkloadAttemptCounts((NSUInteger)(session - 1), ctx.sessionGeneration);
    ctx.destroyed = YES;
    CjguiInvalidateCoordinateLifetimeForIdentity(session,ctx.sessionGeneration);
    ctx.composablePreparation = nil;
    [ctx.retiringComposablePreparations removeAllObjects];
    ctx.sourceProxyPreparation = nil;
    [ctx.retiringSourceProxyPreparations removeAllObjects];
    for (CJGuiInternalFileTransferOperation *operation in ctx.pendingFileTransfers) operation.cancelled = YES;
#ifdef CJGUI_INTERNAL_TESTING
    for (CJGuiInternalFileTransferOperation *operation in ctx.pendingFileTransfers)
        if (operation.testReadGate) dispatch_semaphore_signal(operation.testReadGate);
#endif
    [ctx.pendingFileTransfers removeAllObjects];
    ctx.pendingFileTransferReservedBytes = 0;
    [ctx.pendingTransferTerminalFacts removeAllObjects];
#ifdef CJGUI_INTERNAL_TESTING
    // The retained-item seam is process-test-only. Clearing it as any native
    // session retires guarantees a later probe cannot call an item from a
    // prior lifecycle after windows begin closing.
    gCjguiCapturedComposableCommandMenuItem = nil;
#endif
    [ctx.composableCommandMenuItems removeAllObjects];
    [ctx.stagedComposableCommandMenuItems removeAllObjects];
    ctx.composableCommandMenuVersion = 0;
    ctx.stagedComposableCommandMenuVersion = 0;
    if (ctx.window == NSApp.keyWindow) CjguiRebuildComposableCommandMenuForKeyWindow();

    if (ctx.view) {
        [ctx.diagnosticOverlay removeFromSuperview];
        ctx.diagnosticOverlay = nil;
        [ctx.sharedOperationOverlay removeFromSuperview];
        ctx.sharedOperationOverlay = nil;
        [ctx.sharedEditingFormOverlay removeFromSuperview];
        ctx.sharedEditingFormOverlay = nil;
        [ctx.view invalidateBridgeResources];
    }
    if (ctx.window) {
        [[NSNotificationCenter defaultCenter] removeObserver:ctx
                                                        name:NSWindowDidChangeBackingPropertiesNotification
                                                      object:ctx.window];
        [[NSWorkspace.sharedWorkspace notificationCenter] removeObserver:ctx
                                                                    name:NSWorkspaceAccessibilityDisplayOptionsDidChangeNotification
                                                                  object:nil];
        [[NSNotificationCenter defaultCenter] removeObserver:ctx
                                                        name:NSApplicationDidBecomeActiveNotification object:ctx.app];
        [[NSNotificationCenter defaultCenter] removeObserver:ctx
                                                        name:NSApplicationDidResignActiveNotification object:ctx.app];
        [ctx.window setDelegate:nil];
        objc_setAssociatedObject(ctx.window, &CJGuiSessionWindowAssociationKey, nil,
                                 OBJC_ASSOCIATION_ASSIGN);
        // Hidden/minimized windows still belong to NSApp until actually closed.
        // Retire that lifetime before releasing the session, regardless of visibility.
        [ctx.window close];
        [ctx.window setContentView:nil];
    }

    ctx.view = nil;
    ctx.windowMaterialView = nil;
    ctx.windowOpaqueFallbackView = nil;
    ctx.windowContentHost = nil;
    [ctx.composableNodes removeAllObjects];
    [ctx.stagedComposableNodes removeAllObjects];
    [ctx.composableCommandMenuItems removeAllObjects];
    [ctx.stagedComposableCommandMenuItems removeAllObjects];
    // Retire the composable data-transfer declarations with the session. The
    // accepted/staged arrays are the only strong owners of those items; a
    // closed window must not keep its last accepted declarations alive, and a
    // late callback must not find them under a destroyed session.
    [ctx.composableDataTransferItems removeAllObjects];
    [ctx.stagedComposableDataTransferItems removeAllObjects];
    ctx.stagedComposableDataTransferVersion = 0;
    // Other windows keep the shared domain, but no candidate or accepted
    // image in this retired session can own its transfer bytes or texture.
    // Leases held by this session end with it, before the orphan prune decides.
    CjguiSettleComposableImageCandidateLeases(ctx.composableImageDomain, ctx, YES);
    CjguiPruneUnreferencedComposableTransferResources(ctx.composableImageDomain);
    CjguiReleaseComposableImageDomain(ctx);
    ctx.composableImageDomain = nil;
    ctx.window = nil;
    ctx.commandQueue = nil;
    ctx.device = nil;
    ctx.app = nil;

    CjguiReleaseSession(session);
    NSLog(@"cjgui: destroy complete");
    return CJGUI_INTERNAL_RENDERER_OK;
}

// ---- ABI: occupiedSessionCount ----

uint32_t cjgui_internal_renderer_occupied_session_count(void) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) {
            return 0;
        }
        __block uint32_t count = 0;
        dispatch_sync(dispatch_get_main_queue(), ^{
            count = cjgui_internal_renderer_occupied_session_count();
        });
        return count;
    }
    uint32_t count = 0;
    for (NSUInteger i = 0; i < kCjguiSessionCapacity; i++) {
        if (gCjguiSessionOccupied[i]) {
            count++;
        }
    }
    return count;
}
